import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test successful admin registration and duplicate email rejection.
 *
 * This function validates that a new administrator can register using a unique email and valid password, and immediately receives JWT tokens to enable admin session authentication. It also tests the platform's uniqueness constraint by attempting another registration with exactly the same email, expecting a runtime error due to duplicate email policy enforcement.
 *
 * Step-by-step process:
 * 1. Generate a unique business email and a valid password.
 * 2. Register an admin account using these credentials (expect success, validate response structure and header issuance).
 * 3. Immediately attempt to register another admin account with the same email (expect error due to duplication).
 * 4. Confirm correct success and rejection handling for onboarding compliance.
 */
export async function test_api_admin_registration_success_and_duplicate_email_error(connection: api.IConnection) {
  // 1. Generate unique test inputs
  const uniqueEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();

  // 2. Successful admin registration
  const response: IPolEcoBoardAdminAuth.SignUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: uniqueEmail,
      password: password
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(response);
  // Assert JWT header is present
  TestValidator.predicate("Authorization token present")(typeof response.setHeaders.Authorization === "string" && response.setHeaders.Authorization.length > 0);

  // 3. Attempt duplicate registration with same email
  TestValidator.error("duplicate admin registration should fail")(() =>
    api.functional.auth.admin.register.signUp(connection, {
      body: {
        email: uniqueEmail,
        password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>()
      } satisfies IPolEcoBoardAdminAuth.SignUp
    })
  );
}

