import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerator";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";

/**
 * Validate error handling for fetching details of a non-existent moderator account.
 *
 * This test ensures that the system properly rejects queries for moderator details when the provided moderatorId does not correspond to any real account. Proper error handling is a critical part of account management and audit compliance for moderator workflow.
 *
 * Workflow Steps:
 * 1. Register a new moderator account (to obtain authentication and valid credentials for later requests).
 * 2. Generate a random valid UUID (that does not correspond to any real moderator account).
 * 3. As the logged-in moderator, attempt to fetch details for this (non-existent) moderatorId.
 * 4. The API should return a not found error (e.g., HTTP 404 or business error indicating absence), confirming correct negative path handling.
 */
export async function test_api_moderator_account_detail_not_found(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const registrationInput: IPolEcoBoardModeratorRegistration.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password!123",
    display_name: RandomGenerator.name(),
    consent_status: "v1", // Accept current privacy agreement version
  };
  const registrationResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: registrationInput,
  });
  typia.assert(registrationResponse);

  // Headers (including Authorization) are updated automatically on connection state

  // 2. Generate a random UUID for a non-existent moderator account
  const unavailableModeratorId = typia.random<string & tags.Format<"uuid">>();

  // 3. Attempt to retrieve details for the non-existent moderatorId
  // 4. Assert that a not found error occurs
  await TestValidator.error("Should return not found for non-existent moderator")(
    async () => {
      await api.functional.polEcoBoard.moderator.moderators.at(connection, {
        moderatorId: unavailableModeratorId,
      });
    },
  );
}

