import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdmin";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate rejection of invalid privilege escalation for admin accounts.
 *
 * This test ensures that the system enforces privilege assignment rules by refusing updates that set an admin's privilege level to an invalid (out-of-range or disallowed) value.
 * The business rule is that privilege_level must only be within permissible (e.g., 0 or 10) values recognized by the platform, and not arbitrary numeric levels.
 *
 * Process:
 * 1. Register a new admin, capturing the admin UUID needed for privilege update attempts.
 * 2. Authenticate as the admin (to obtain an active session/token for update operation).
 * 3. Attempt to update own admin privilege to an invalid level (e.g., 99 or -5).
 * 4. Confirm that the API rejects the request by raising an error (handled via TestValidator.error), which validates that backend enforcement is working.
 * 5. Optionally, verify that the admin account was NOT updated by attempting a valid fetch or further valid update (if supported).
 */
export async function test_api_admin_update_account_with_invalid_privilege(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const signupResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signupResponse);

  // 2. Authenticate as the admin (to update own record)
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(loginResponse);

  // 3. Prepare an invalid privilege update (assign privilege_level = 99, assuming only 0 or 10 are valid)
  // 4. Attempt the update and expect an error (API should reject invalid privilege_level)
  //    We use TestValidator.error to check error throwing is enforced.
  await TestValidator.error("should reject invalid privilege change")(
    async () => {
      await api.functional.polEcoBoard.admin.admins.update(connection, {
        adminId: signupResponse.setHeaders.Authorization.split(" ")[1] || signupResponse.setHeaders.Authorization,
        body: {
          privilege_level: 99,
        },
      });
    },
  );
}

