import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate failure of member login using invalid credentials.
 *
 * This test verifies that the member login endpoint does not allow access for invalid credentials (wrong email or password), returns a proper error, does not expose any JWT or sensitive data, and ensures the authentication attempt is compliant with audit requirements. No dependencies or setup are needed as only invalid credentials are tested.
 *
 * Steps:
 * 1. Attempt login using a non-existent email (never registered in the system).
 *    - Expect error, no tokens returned, no sensitive information in the response.
 * 2. Attempt login using a valid format email but with an invalid password.
 *    - Expect error, no tokens returned, no sensitive information in the response.
 * 3. Attempt login using clearly invalid credentials (gibberish email/password) to confirm robust error handling.
 *    - Expect error every time, no sensitive information leaked.
 */
export async function test_api_member_login_invalid_credentials(connection: api.IConnection) {
  // 1. Attempt login with a non-existent email address
  await TestValidator.error("login fails for non-existent email")(async () => {
    await api.functional.auth.member.login.signIn(connection, {
      body: {
        email: "no.such.user." + typia.random<string & tags.Format<"email">>(),
        password: "invalidPass!@#" as string & tags.Format<"password">,
      } satisfies IMemberAuthenticationMemberSignIn,
    });
  });

  // 2. Attempt login with valid email but clearly wrong password
  await TestValidator.error("login fails for valid email, wrong password")(async () => {
    await api.functional.auth.member.login.signIn(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "DefinitelyTheWrongPassword123!" as string & tags.Format<"password">,
      } satisfies IMemberAuthenticationMemberSignIn,
    });
  });

  // 3. Attempt login with gibberish credentials
  await TestValidator.error("login fails for gibberish credentials")(async () => {
    await api.functional.auth.member.login.signIn(connection, {
      body: {
        email: "gibberish-" + typia.random<string & tags.Format<"email">>(),
        password: "garbage$$$" as string & tags.Format<"password">,
      } satisfies IMemberAuthenticationMemberSignIn,
    });
  });
}

