import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IPolEcoBoardAuthSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAuthSession";

/**
 * Validates that only admin users may enumerate admin sessions; rejects non-admin and unauthenticated requests.
 *
 * This test ensures that both unauthenticated requests (no JWT) and regular member-authenticated requests are strictly denied access to the /auth/admin/sessions endpoint. Verifies robust access control, preventing admin session leaks to non-admin users.
 *
 * 1. Register a regular member.
 * 2. Log in as the member and obtain JWT.
 * 3. Attempt to enumerate admin sessions with NO auth token – must receive 401/403, never data.
 * 4. Attempt with member JWT as Authorization header – must also be rejected (401/403), never data.
 * 5. Assertion: Any successful response, or session data in error response, is a test failure.
 */
export async function test_api_admin_sessions_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);

  // 2. Login as the member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);

  // Prepare a version of connection with member's JWT
  const memberConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: signInResult.setHeaders.Authorization,
    },
  };

  // 3. Attempt admin session listing with NO token (unauthenticated)
  TestValidator.error("unauthenticated request must fail")(async () => {
    // Remove Authorization header if present
    const unauthConnection: api.IConnection = {
      ...connection,
      headers: {
        ...connection.headers,
      },
    };
    await api.functional.auth.admin.sessions.listActiveSessions(unauthConnection);
  });

  // 4. Attempt admin session listing as non-admin (regular member JWT)
  TestValidator.error("non-admin JWT must not permit admin session listing")(async () => {
    await api.functional.auth.admin.sessions.listActiveSessions(memberConnection);
  });
}

