import type { IMemberAuthenticationMemberChangePasswordResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberChangePasswordResult";

/**
 * Test member password change and session revocation.
 *
 * This test ensures that a member can register, successfully log in, then change their password using the correct current password.
 * It verifies that after a password change:
 *   - The member receives a success response notifying that all previous sessions have been revoked
 *   - Old token can no longer be used (calls with it will fail authentication)
 *   - A fresh login with the new password is required and succeeds
 * The workflow covers both session security and password update business rules.
 *
 * Process Steps:
 * 1. Register as a new member
 * 2. Log in as the member and obtain authentication token
 * 3. Change password, using the correct current password
 * 4. Attempt to use old token (should be rejected)
 * 5. Authenticate again using the new password (should succeed)
 */
export async function test_api_member_password_change_and_session_revocation(
  connection: api.IConnection
) {
  // 1. Register new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);
  TestValidator.predicate("register - received JWT")(
    typeof signUpResult.setHeaders?.Authorization === "string"
  );

  // 2. Log in as member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);
  TestValidator.predicate("login - received JWT")(
    typeof signInResult.setHeaders?.Authorization === "string"
  );
  const oldToken = signInResult.setHeaders.Authorization;

  // 3. Change the password using old token
  // Create new password
  const newPassword = typia.random<string & tags.Format<"password">>();
  // Use member's token for authenticated password change
  const memberConnection = { ...connection, headers: { ...connection.headers, Authorization: oldToken } };
  const changeResult = await api.functional.auth.member.password.changePassword(
    memberConnection,
    {
      body: {
        current_password: password,
        new_password: newPassword,
      } satisfies IMemberAuthenticationMemberChangePassword,
    }
  );
  typia.assert(changeResult);
  TestValidator.predicate("password change success")(changeResult.success === true);
  TestValidator.predicate("relogin required")(changeResult.reloginRequired === true);
  TestValidator.predicate("sessions revoked")(changeResult.sessionsRevoked >= 1);

  // 4. Try to use the old token again: further authenticated request is expected to fail
  // We'll try any authenticated action; here, re-attempt password change or login with the revoked token
  await TestValidator.error("old token should be rejected after password change")(async () => {
    await api.functional.auth.member.password.changePassword(memberConnection, {
      body: {
        current_password: newPassword,
        new_password: typia.random<string & tags.Format<"password">>(),
      } satisfies IMemberAuthenticationMemberChangePassword,
    });
  });

  // 5. Authenticate again with new password: must succeed
  const signInResultNew = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password: newPassword } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResultNew);
  TestValidator.predicate("login with new password - received JWT")(
    typeof signInResultNew.setHeaders?.Authorization === "string"
  );
}

