 * 4. Attempt to call refresh with the revoked refresh token that was issued previously (from login response, NOT a new login).
 * 5. Confirm that the refresh request fails with an error and that no new session/tokens are issued.
 *
 * Edge cases covered:
 * - Refresh is attempted using a refresh token that has been explicitly revoked by logout
 * - No further access/refresh tokens are issued
 * - Error is properly detected and test fails if session is unexpectedly created
 */
export async function test_api_admin_refresh_token_expired_or_revoked(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
