import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin JWT tokens, covering both valid and invalid scenarios.
 *
 * This test ensures that the endpoint for token validation correctly recognizes both active (valid) and revoked (invalid) admin JWTs.
 * It does so by registering a new admin account, logging that admin in (to get a valid token), validating the token successfully, then logging out (revoking the token), and finally validating the now-revoked token (which should be flagged as invalid).
 *
 * Steps:
 * 1. Register a new admin with a unique email/password.
 * 2. Log in with the same credentials to obtain a new JWT access token from setHeaders.
 * 3. Call the validate endpoint with the valid token: should return isValid=true and role="admin".
 * 4. Log out, revoking the current session/token.
 * 5. Call the validate endpoint again with the same (now revoked) token: should return isValid=false and reason is a non-empty string or an error is thrown.
 * 6. (Edge case) Optionally, test an obviously invalid or malformed token and verify proper invalidation.
 */
export async function test_api_admin_validate_token_valid_and_invalid_cases(connection: api.IConnection) {
  // Step 1: Register a new admin account
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(signUpResponse);
  TestValidator.predicate("Authorization exists after registration")(typeof signUpResponse.setHeaders.Authorization === "string" && !!signUpResponse.setHeaders.Authorization);

  // Step 2: Login with that admin to get a new valid token
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(signInResponse);
  TestValidator.predicate("Authorization exists after login")(typeof signInResponse.setHeaders.Authorization === "string" && !!signInResponse.setHeaders.Authorization);

  // Step 3: Validate the valid token
  const token = signInResponse.setHeaders.Authorization.replace(/^Bearer\s+/, "");
  const validateValid = await api.functional.auth.admin.validate.validateToken(connection, {
    body: { token } satisfies IPolEcoBoardAdminAuth.ValidateToken
  });
  typia.assert(validateValid);
  TestValidator.equals("isValid should be true for valid token")(validateValid.isValid)(true);
  TestValidator.equals("role should be admin")(validateValid.role)("admin");
  TestValidator.predicate("accountId present")(!!validateValid.accountId);
  TestValidator.predicate("expiresAt present")(!!validateValid.expiresAt);

  // Step 4: Logout to revoke the token
  await api.functional.auth.admin.logout.signOut(connection);

  // Step 5: Validate the same token (should now be invalid)
  const validateRevoked = await api.functional.auth.admin.validate.validateToken(connection, {
    body: { token } satisfies IPolEcoBoardAdminAuth.ValidateToken
  });
  typia.assert(validateRevoked);
  TestValidator.equals("isValid should be false after logout")(validateRevoked.isValid)(false);
  TestValidator.predicate("reason present for invalid token")(!!validateRevoked.reason);
  TestValidator.equals("role should be undefined after invalidation")(validateRevoked.role)(undefined);
  TestValidator.equals("accountId should be undefined after invalidation")(validateRevoked.accountId)(undefined);
  TestValidator.equals("expiresAt should be undefined after invalidation")(validateRevoked.expiresAt)(undefined);

  // Step 6: Validate an obviously invalid token (malformed)
  const validateMalformed = await api.functional.auth.admin.validate.validateToken(connection, {
    body: { token: "not-a-real-jwt-token" } satisfies IPolEcoBoardAdminAuth.ValidateToken
  });
  typia.assert(validateMalformed);
  TestValidator.equals("isValid should be false for malformed token")(validateMalformed.isValid)(false);
  TestValidator.predicate("reason for malformed token")(!!validateMalformed.reason);
  TestValidator.equals("role should be undefined for malformed token")(validateMalformed.role)(undefined);
  TestValidator.equals("accountId should be undefined for malformed token")(validateMalformed.accountId)(undefined);
  TestValidator.equals("expiresAt should be undefined for malformed token")(validateMalformed.expiresAt)(undefined);
}

