      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      profile_image_uri: null,
      consent_status: "v1.0-consented",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Create a moderation action
  const moderationAction: IPolEcoBoardModerationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: member.id, // Usually the admin but for test, can use known user
      action_type: "warn",
      target_type: "user",
      status: "completed",
      rationale: "Inappropriate behavior detected by moderation.",
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 5. Create a sanction
  const start = new Date().toISOString();
  const end = new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString(); // 7 days from now
  const sanction: IPolEcoBoardSanction = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      sanctioned_user_id: member.id,
      sanction_type: "suspension",
      status: "active",
      rationale: "Temporary suspension due to policy violation.",
      start_at: start,
      end_at: end,
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction);

