  TestValidator.predicate("sanction id is uuid")(
    typeof sanction.id === "string" && sanction.id.length > 0
  );
  TestValidator.equals("refers to correct moderation action")(
    sanction.moderation_action_id
  )(moderationAction.id);
  TestValidator.equals("refers to correct sanctioned_user_id")(
    sanction.sanctioned_user_id
  )(member.id);
  TestValidator.equals("sanction type")(
    sanction.sanction_type
  )("suspension");
  TestValidator.equals("sanction status")(
    sanction.status
  )("active");
  TestValidator.equals("rationale")(
    sanction.rationale
  )("Temporary suspension due to policy violation.");
  TestValidator.equals("start_at")(
    sanction.start_at
  )(start);
  TestValidator.equals("end_at")(
    sanction.end_at
  )(end);
  TestValidator.predicate("created_at and updated_at are valid")(
    typeof sanction.created_at === "string" && typeof sanction.updated_at === "string"
  );
  TestValidator.equals("not soft-deleted")(
    sanction.deleted_at
  )(null);
}

