 *
 * 1. Register a new admin account for authentication using unique credentials
 * 2. Authenticate as the admin (handled by API via token issuance post registration)
 * 3. Create a new notification provider record using valid random data
 * 4. Perform the first deletion on the provider (soft-delete – sets deleted_at)
 * 5. Attempt a second deletion with the same notificationProviderId (should fail)
 * 6. Assert that the second DELETE operation throws an error, confirming correct error semantics for already-deleted resource
 */
export async function test_api_notification_provider_delete_already_deleted(
  connection: api.IConnection,
) {
