    body: {
      email: uniqueAdminEmail,
      password: "TestPassw0rd!"
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminRegisterResponse);

  // 2. (Auth handled via header update; use same connection)

  // 3. Create a new notification provider
  const providerCreate = await api.functional.polEcoBoard.admin.notificationProviders.create(connection, {
    body: {
      provider_name: `TestProvider_${RandomGenerator.alphaNumeric(8)}`,
      provider_key: `key_${RandomGenerator.alphaNumeric(8)}`,
      channels_supported: "email,sms,push",
      endpoint_uri: `https://api.testprovider${RandomGenerator.alphaNumeric(3)}.com/integration`,
      region: "KR",
      status: "active",
      config_metadata: "{\"retry\":3}"
    } satisfies IPolEcoBoardNotificationProvider.ICreate
  });
  typia.assert(providerCreate);

  // 4. Soft-delete the provider (first DELETE)
  await api.functional.polEcoBoard.admin.notificationProviders.erase(connection, {
    notificationProviderId: providerCreate.id,
  });

  // 5. Attempt to delete again (should throw)
