  // 4. Prepare a valid update payload for notification failure
  const updatePayload: IPolEcoBoardNotificationFailure.IUpdate = {
    failure_code: RandomGenerator.alphaNumeric(7),
    failure_message: RandomGenerator.paragraph()(),
    resolution_status: RandomGenerator.alphaNumeric(9),
    provider_id: typia.random<string & tags.Format<"uuid">>(),
    occurred_at: new Date().toISOString(),
  };

  // 5. Attempt to update the non-existent notificationFailureId and expect error
  await TestValidator.error("Should fail for invalid or unauthorized notificationFailureId")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationFailures.update(connection, {
        notificationFailureId: invalidNotificationFailureId,
        body: updatePayload,
      });
