import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a member cannot soft delete their own post after the permitted deletion window has expired.
 *
 * Business context:
 * The board allows authors to soft delete posts only within a specific permitted time window after creation. After this window, even the original author is forbidden from deleting their own posts. Only moderators or admins may delete after expiry. This policy promotes accountability and auditability of discussion history.
 *
 * Test Process:
 * 1. Register a new member (author) with unique, random credentials.
 * 2. Log in as that member to obtain an authenticated session.
 * 3. Create a post in a random, valid category as the logged-in member.
 * 4. Attempt to soft delete the post as the author after (simulated) expiry of the deletion window. (E2E cannot time travel or set created_at, so this step simply expects the API to enforce business logic regardless.)
 * 5. Confirm that deletion fails due to expiry—API must return a permission or business logic error.
 */
export async function test_api_post_soft_delete_outside_author_window_forbidden(
  connection: api.IConnection,
) {
  // 1. Register a new member (author)
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: { email, password },
  });
  typia.assert(signUpResult);

  // 2. Log in as that member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password },
  });
  typia.assert(signInResult);

  // 3. Create a board post (category UUID syntactically valid; title/body follow business constraints)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test post for forbidden late-delete",
      body: "This post is created to check enforcement of the late-delete business window.",
      tag_ids: null, // Explicit null for optional array fields
      attachments: null, // Explicit null for optional array fields
    },
  });
  typia.assert(post);

  // 4. Attempt to soft delete after (simulated) allowed window; actual time passage can't be simulated in E2E
  await TestValidator.error("delete is forbidden after window")(async () => {
    await api.functional.polEcoBoard.member.posts.erase(connection, { postId: post.id });
  });
}

