 * 3. As admin, call the patch /polEcoBoard/admin/guests endpoint with search filters that are almost certain not to match any guest record, e.g. a combination of an obviously fake IP address, unlikely device fingerprint, and future consent status string, to guarantee no results are returned.
 * 4. Verify the response structure: it must include an empty data array, and the pagination metadata must reflect zero records, with page and limit matching the request, and pages equal to zero or one depending on implementation.
 */
export async function test_api_guest_session_search_no_results(connection: api.IConnection) {
  // 1. Register new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in as admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Search with filters matching no guest sessions
  const noMatchFilters = {
    ip_address: "255.255.255.255", // Unlikely IP
    device_fingerprint: "invalid-fingerprint-value-never-used", // Contrived
    consent_status: "FAKE_CONSENT_STATUS_DOES_NOT_EXIST",
    created_after: new Date(Date.now() + 5 * 365 * 24 * 3600 * 1000).toISOString(), // Far future date
    page: 1,
    limit: 20,
  } satisfies IPolEcoBoardGuest.IRequest;
  const response = await api.functional.polEcoBoard.admin.guests.search(connection, {
    body: noMatchFilters,
  });
  typia.assert(response);

  // 4. Validate empty result and pagination structure
  TestValidator.equals("data is empty")(response.data)([]);
  TestValidator.equals("pagination.records is zero")(response.pagination.records)(0);
  TestValidator.equals("pagination.page matches request")(response.pagination.current)(1);
  TestValidator.equals("pagination.limit matches request")(response.pagination.limit)(20);
  TestValidator.predicate("pagination.pages is 0 or 1")(response.pagination.pages === 0 || response.pagination.pages === 1);
}

