 * Workflow:
 * 1. Register a random admin account.
 * 2. Log in as the admin to obtain access token (Authorization header).
 * 3. Create a fully active member account.
 * 4. Soft-delete (deactivate) the member using the admin API.
 *    - (No response body)
 * 5. Attempt to delete the same member again, expect a business rule error (validate via TestValidator.error).
 *
 * Note: Because there is no member fetch API in the provided SDK, post-deletion verification (step 5 in scenario) is omitted.
 */
export async function test_api_admin_member_account_soft_delete_and_already_deleted_error(
  connection: api.IConnection,
) {
  // 1. Register a random admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpRes);

  // 2. Log in as admin
  const adminLoginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginRes);

  // 3. Create a member account
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      profile_image_uri: null,
      consent_status: RandomGenerator.alphaNumeric(8)
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Soft-delete this member as admin
  await api.functional.polEcoBoard.admin.members.erase(connection, {
