      password: password,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Call search with random filters for empty result
  const requestBody: IPolEcoBoardBoardStatus.IRequest = {
    pol_eco_board_board_id: typia.random<string & tags.Format<"uuid">>(),
    status_type: "archived", // less likely to exist, but still valid enum
    actor_admin_id: null,
    actor_moderator_id: null,
    effective_after: null,
    effective_before: null,
    page: 1,
    limit: 10,
    orderBy: null,
    orderDirection: null,
  };
  const output = await api.functional.polEcoBoard.admin.boardStatuses.search(connection, {
