import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate error handling for notification preference search with invalid filters or pagination.
 *
 * This test checks whether the API properly rejects searches for notification preferences when supplied with invalid filter criteria or out-of-bound pagination parameters. It ensures there is no data leakage or unexpected data returned and that the error is clear and well-formed.
 *
 * Steps:
 * 1. Register a new member and log in to obtain authentication.
 * 2. Create at least one notification preference for that member, to ensure search can operate with valid context.
 * 3. Attempt to search notification preferences using:
 *    a. An unsupported/nonexistent event_type filter value.
 *    b. An over-large page number (beyond expected pages).
 * 4. Expect an error or validation issue for each invalid search attempt, checking there is no returned sensitive data and that the result is a recognizable validation failure (error thrown, or response indicates validation error).
 *
 * Note:
 * member_id is a required field in the creation DTO but functionally managed by the server session for regular members. We provide a valid UUID but server should use session ID.
 */
export async function test_api_member_notification_preference_search_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const registerResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(registerResult);

  // 2. Login as the member
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(loginResult);

  // 3. Create a notification preference for this member
  // member_id required in DTO but actual linkage managed by session on server for normal member
  const createPref = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "reply",
      channel: "email",
      opt_in: true,
    },
  });
  typia.assert(createPref);

  // 4a. Invalid filter: non-existent event_type
  await TestValidator.error("invalid event_type should throw")(async () => {
    await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: {
        event_type: "nonexistent_event_type_xyz",
      },
    });
  });

  // 4b. Invalid filter: overbound page parameter
  await TestValidator.error("overbound page param should throw")(async () => {
    await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: {
        page: 9999,
