import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the deletion of moderation audit records and test access control.
 *
 * This test will:
 * 1. Register a new admin (with a secure password of at least 8 chars, as required).
 * 2. Immediately login as admin to activate admin privileges and ensure the connection sets authorization headers for subsequent requests.
 * 3. Create a new moderation action, as an audit must be associated to a specific action.
 * 4. Create an audit record for the moderation action, so we have a valid (moderationActionId, auditId) pair for deletion.
 * 5. Delete the audit record as admin (success case).
 * 6. Attempt to delete the same audit again (should error: not found or already deleted).
 * 7. Register a dummy non-admin account, attempt the same deletion, and verify access denied (if member mode supported; else simulate with unauthenticated connection as placeholder).
 * 8. Attempt to delete a non-existent auditId under current moderationActionId, verify not found error.
 *
 * Each step will assert the correct business and permission logic, and errors thrown will be checked via TestValidator.error.
 */
export async function test_api_moderation_audit_delete_success_and_access_control(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(registerRes);

  // 2. Login as admin to set Authorization (simulate real privilege session)
  const loginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginRes);
  // (connection.headers are now set with Authorization)

  // 3. Create a moderation action to which we'll attach audits
  const moderationActionInput = {
    report_id: typia.random<string & tags.Format<"uuid">>(),
    operator_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: RandomGenerator.alphabets(8),
    target_type: RandomGenerator.alphabets(6),
    status: "pending",
    rationale: RandomGenerator.paragraph()(),
    outcome: "accepted",
  } satisfies IPolEcoBoardModerationAction.ICreate;
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(
    connection,
    { body: moderationActionInput },
  );
  typia.assert(moderationAction);

  // 4. Create an audit associated with the moderation action
  const moderationAuditInput = {
    moderation_action_id: moderationAction.id,
    auditor_id: moderationAction.operator_id,
    pre_state_snapshot: JSON.stringify(moderationAction),
    post_state_snapshot: JSON.stringify(moderationAction),
    reason: RandomGenerator.content()()(),
  } satisfies ModerationAudit.ICreate;
  const moderationAudit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(
    connection,
    {
      moderationActionId: moderationAction.id,
      body: moderationAuditInput,
    },
  );
  typia.assert(moderationAudit);

  // 5. Successfully delete the audit as admin
  await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
    connection,
    { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
  );

  // 6. Attempt to delete again (should throw not found)
  await TestValidator.error("re-deleting already deleted audit should error")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 7. Attempt audit deletion as a non-admin (simulate by removing Authorization) - expect permission error
  const nonAdminConnection = { ...connection, headers: {} } satisfies api.IConnection;
  await TestValidator.error("non-admin cannot delete moderation audit")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        nonAdminConnection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 8. Attempt deleting a non-existent auditId
  await TestValidator.error("deleting non-existent auditId yields not found")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        {
          moderationActionId: moderationAction.id,
          auditId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
}

