import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBusinessReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBusinessReport";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate successful update of a business report by an admin user.
 *
 * This test performs the following business and technical workflow:
 * 1. Registers a new admin account (admin registration).
 * 2. Logs in as the newly created admin, obtaining JWT credentials for authenticated actions.
 * 3. Creates a new business report, retaining its ID for use in the update step.
 * 4. Executes a PUT operation to update the business report (e.g., changes report_type or status).
 * 5. Checks that the response reflects the updated fields, ensuring the update is persisted.
 * 6. Verifies all returned data types and formats through runtime assertion.
 */
export async function test_api_business_report_update_successful_patch(connection: api.IConnection) {
  // 1. Register an admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as the registered admin to obtain JWT
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);
  // Set the Authorization token for next requests
  connection.headers = {
    ...connection.headers,
    Authorization: signInResp.setHeaders.Authorization,
  };

  // 3. Create a business report to update
  const reportCreateBody = {
    report_code: `BR-${Date.now()}`,
    report_type: "METRICS",
    status: "PENDING",
    requested_by_id: typia.random<string & tags.Format<"uuid">>(),
    content_uri: "s3://bucket/business/report/file.pdf",
    triggered_at: new Date().toISOString(),
  } satisfies IPolEcoBoardBusinessReport.ICreate;
  const businessReport = await api.functional.polEcoBoard.admin.businessReports.create(connection, {
    body: reportCreateBody,
  });
  typia.assert(businessReport);

  // 4. Prepare update fields (change report_type, status, maybe delivered_at)
  const updateBody = {
    report_type: "AUDIT",
    status: "COMPLETED",
    delivered_at: new Date().toISOString(),
  } satisfies IPolEcoBoardBusinessReport.IUpdate;
  const updated = await api.functional.polEcoBoard.admin.businessReports.update(connection, {
    businessReportId: businessReport.id,
    body: updateBody,
  });
  typia.assert(updated);

  // 5. Validate updated fields are persisted
  TestValidator.equals("report_type updated")(updated.report_type)(updateBody.report_type);
  TestValidator.equals("status updated")(updated.status)(updateBody.status);
  TestValidator.equals("delivered_at updated")(updated.delivered_at)(updateBody.delivered_at);
  TestValidator.equals("unchanged report_code")(updated.report_code)(businessReport.report_code);
  TestValidator.equals("unchanged id")(updated.id)(businessReport.id);
}

