 * This covers the following business workflow:
 * 1. Register a new admin account (to obtain admin privileges and start a session)
 * 2. Use the admin session to create a new notification provider, and record its notificationProviderId
 * 3. Update that notification provider via the PUT endpoint to modify mutable fields (e.g., provider_name, channels_supported, endpoint_uri, status)
 * 4. Verify that the API response matches the updated values, and that immutable fields (provider_key) have not changed
 */
export async function test_api_notification_provider_update_successful_update(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegistration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminRegistration);

  // 2. Create a new notification provider as the new admin
  const notificationProviderCreateInput: IPolEcoBoardNotificationProvider.ICreate = {
    provider_name: "Initial Provider Name",
    provider_key: RandomGenerator.alphabets(8),
    channels_supported: "email,sms",
    endpoint_uri: "https://api.example.com/notify",
    region: "KR",
    status: "active",
    config_metadata: "{\"version\":1}"
  };
  const createdProvider = await api.functional.polEcoBoard.admin.notificationProviders.create(connection, {
    body: notificationProviderCreateInput
  });
  typia.assert(createdProvider);

  // 3. Update mutable information on the provider via PUT
  const updateInput: IPolEcoBoardNotificationProvider.IUpdate = {
    provider_name: "Updated Provider Name",
    channels_supported: "email,sms,push",
    endpoint_uri: "https://api-updated.example.com/notify",
    status: "inactive"
    // config_metadata, region are omitted (test optionality)
  };
  const updatedProvider = await api.functional.polEcoBoard.admin.notificationProviders.update(connection, {
    notificationProviderId: createdProvider.id,
    body: updateInput
  });
  typia.assert(updatedProvider);

  // 4. Assertions: verify updated and immutable fields
  TestValidator.equals("provider_id remains the same")(updatedProvider.id)(createdProvider.id);
  TestValidator.equals("provider_key is immutable")(updatedProvider.provider_key)(createdProvider.provider_key);
  TestValidator.equals("name updated")(updatedProvider.provider_name)(updateInput.provider_name!);
  TestValidator.equals("channels updated")(updatedProvider.channels_supported)(updateInput.channels_supported!);
  TestValidator.equals("endpoint_uri updated")(updatedProvider.endpoint_uri)(updateInput.endpoint_uri!);
  TestValidator.equals("status updated")(updatedProvider.status)(updateInput.status!);
  // unchanged fields (region/config_metadata) should remain at original values when omitted
  TestValidator.equals("region unchanged when omitted")(updatedProvider.region)(createdProvider.region);
  TestValidator.equals("config_metadata unchanged when omitted")(updatedProvider.config_metadata)(createdProvider.config_metadata);
