/**
 * Validate retrieval of a single maintenance window record by unique ID (admin access).
 *
 * This test ensures that only authenticated admins can retrieve detailed maintenance window records by their unique ID. It validates:
 * - Maintenance window creation and subsequent fetch by ID as the same admin.
 * - Field-by-field equality between created and fetched maintenance window.
 * - Attempts to fetch with a non-existent maintenanceWindowId result in 404/not-found error.
 * - Unauthorized/anonymous requests are blocked with 401/forbidden error.
 *
 * Steps:
 * 1. Register as admin
 * 2. Log in as admin (obtain Authorization header in connection)
 * 3. Create maintenance window using required fields
 * 4. GET maintenance window by valid ID — assert all fields match
 * 5. GET by random UUID (not found) — expect 404 error
 * 6. GET as anonymous (no Authorization) — expect 401 error
 */
export async function test_api_get_maintenance_window_by_id(
  connection: api.IConnection,
) {
  // 1. Register as admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Log in as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a new maintenance window
  const mwInput: IPolEcoBoardMaintenanceWindow.ICreate = {
    window_code: `MAINT_${new Date().toISOString().replace(/[-:.TZ]/g, "").slice(0, 12)}`,
    start_time: new Date().toISOString(),
    end_time: null,
    expected_impact: RandomGenerator.paragraph()(),
    notified_at: null,
  } satisfies IPolEcoBoardMaintenanceWindow.ICreate;
  const mwOutput: IPolEcoBoardMaintenanceWindow = await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
    body: mwInput,
  });
  typia.assert(mwOutput);

  // 4. GET with new ID — assert all fields match (field-by-field)
  const fetched: IPolEcoBoardMaintenanceWindow = await api.functional.polEcoBoard.admin.maintenanceWindows.at(connection, {
    maintenanceWindowId: mwOutput.id,
  });
  typia.assert(fetched);

  TestValidator.equals("maintenance window window_code matches")(fetched.window_code)(mwInput.window_code);
  TestValidator.equals("maintenance window start time matches")(fetched.start_time)(mwInput.start_time);
  TestValidator.equals("maintenance window end time matches")(fetched.end_time ?? null)(mwInput.end_time ?? null);
  TestValidator.equals("maintenance window expected impact matches")(fetched.expected_impact)(mwInput.expected_impact);
  TestValidator.equals("maintenance window notified_at matches")(fetched.notified_at ?? null)(mwInput.notified_at ?? null);

  // 5. GET with random UUID (not found)
  const randomId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("maintenance window not found")(() =>
    api.functional.polEcoBoard.admin.maintenanceWindows.at(connection, {
      maintenanceWindowId: randomId,
    })
  );

  // 6. GET with missing Authorization (as anonymous user)
  const anonConn = { ...connection, headers: { ...connection.headers } };
  delete anonConn.headers["Authorization"];
  TestValidator.error("unauthorized maintenance window GET")(() =>
    api.functional.polEcoBoard.admin.maintenanceWindows.at(anonConn, {
      maintenanceWindowId: mwOutput.id,
    })
  );
}

