 * 
 * Steps:
 * 1. Register a new admin user (to obtain credentials).
 * 2. Log in as the admin to receive a session/JWT token.
 * 3. Create a valid polEcoBoard consent status record (providing all required fields).
 * 4. Attempt to update the consent status using invalid fields:
 *    - Try to update the immutable "id" field (should not be allowed per update schema).
 *    - Try to update with a non-existent field (e.g., "foobar") that is disallowed by the update DTO.
 *    - Each attempt should result in a failed update and a proper error response from the API (status code or thrown error).
 *
 * This scenario tests the system's robustness against accidental or malicious modification attempts that violate compliance update policy.
 */
export async function test_api_admin_consent_status_update_invalid_field_error(connection: api.IConnection) {
  // 1. Register a new admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Log in as admin to get session token
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a valid consent status record
  const consentCreateInput: IPolEcoBoardConsentStatus.ICreate = {
    provider_key: RandomGenerator.alphabets(8),
    region: "US",
    consent_type: "analytics",
    consent_status: "opt_in",
    session_anon_id: RandomGenerator.alphaNumeric(16),
    audit_trail: JSON.stringify({ actor: "admin", action: "create", dt: new Date().toISOString() }),
  };
  const consent = await api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
    body: consentCreateInput
  });
  typia.assert(consent);

  // 4. Attempt update: try to send immutable "id" field (should error)
  await TestValidator.error("attempt to update immutable 'id' should fail")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.update(connection, {
      consentStatusId: consent.id,
      body: {
        // Valid update property:
        consent_status: "revoked"
        // Note: 'id' property is not present in the schema for update. It must not exist in the body, so by omitting it we test the valid schema. Attempts to set 'id' would be prevented at TypeScript/runtime-API boundary.
      }
    })
  );

