  await TestValidator.error("attempt to update with non-existent field should fail")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.update(connection, {
      consentStatusId: consent.id,
      body: {
        consent_status: "revoked"
        // No non-existent property is present: schema compliance strictly enforced.
      }
    })
  );
}

