    // 3. Log in as the member to get a JWT token (simulate member session)
    const loginResp = await api.functional.auth.member.login.signIn(connection, {
        body: {
            email: memberEmail,
            password: memberPassword,
        }
    });
    typia.assert(loginResp);
    // The returned loginResp.setHeaders includes Authorization (JWT); this is handled by the SDK
    // Connection's Authorization header is now set as member

    // 4. As logged-in member, attempt to erase moderator
    await TestValidator.error("forbidden: member may not delete moderator")(async () => {
        await api.functional.polEcoBoard.admin.moderators.erase(connection, {
            moderatorId: moderatorId,
        });
    });
}

