  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 3. Prepare notification failure record input
  const notificationFailureInput: IPolEcoBoardNotificationFailure.ICreate = {
    notification_id: typia.random<string & tags.Format<"uuid">>(),
    provider_id: typia.random<string & tags.Format<"uuid">>(),
    failure_code: "ERR_TEST_CODE",
    failure_message: "Test notification delivery failed for troubleshooting validation.",
    occurred_at: new Date().toISOString(),
    resolution_status: "pending",
  };

  // 4. Create a notification failure record
  const createdFailure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: notificationFailureInput,
