import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the soft delete (archive) of a board and edge cases as an admin.
 *
 * This test ensures that when an admin soft deletes a board:
 *   - The 'deleted_at' field of the board is set, and the board is excluded from active listings, but retained for audit/restoration.
 *   - Attempting to delete a non-existing board or already deleted board returns appropriate errors.
 *   - Attempts to delete with insufficient permissions fail (non-admin/unauthed test is included).
 *   - If board cannot be deleted due to business constraints (e.g. referenced in a mandatory workflow), deletion is blocked.
 *   - All actions are fully audited by API contract.
 *
 * Test Steps:
 * 1. Register a new admin and login to obtain an authenticated session.
 * 2. Create a new board category (required for board creation).
 * 3. Create a new board within that category.
 * 4. Soft delete the created board and verify operation succeeded (repeat GET is not available so rely on success and DTO).
 * 5. Attempt to soft delete again (should error: already deleted/non-existent).
 * 6. Attempt to delete a random, likely non-existent board id (should error: not found).
 * 7. [Edge] Attempt the same delete as an unauthenticated/non-admin user (expect error/forbidden).
 * 8. [Business] If supported by the API, attempt to delete a board that is referenced in a mandatory workflow (should fail due to constraint; not implemented if workflow/references are not modeled in fixtures).
 */
export async function test_api_board_soft_delete_and_edge_cases(connection: api.IConnection) {
  // 1. Register and login admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(loginResp);

  // 2. Create category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<'int32'>>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(2),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<'int32'>>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Soft delete
  await api.functional.polEcoBoard.admin.boards.erase(connection, {
    boardId: board.id
  });

  // 5. Attempt soft delete again (should error)
  await TestValidator.error('Deleting already-deleted board should fail')(async () => {
    await api.functional.polEcoBoard.admin.boards.erase(connection, {
      boardId: board.id
    });
  });

  // 6. Attempt delete with random id (should error)
  await TestValidator.error('Deleting non-existent board should fail')(async () => {
    await api.functional.polEcoBoard.admin.boards.erase(connection, {
      boardId: typia.random<string & tags.Format<'uuid'>>()
    });
  });

  // 7. Attempt delete as unauthenticated user (should error)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined }};
  await TestValidator.error('Deleting as unauthenticated should fail')(async () => {
    await api.functional.polEcoBoard.admin.boards.erase(unauthConnection, {
      boardId: board.id
    });
  });

  // 8. [Business] Cannot implement mandatory workflow reference constraint without further API
}

