import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validates soft deletion (by member) of a polEcoBoard notification addressed to them.
 *
 * This test confirms that an authenticated member can successfully request a soft-delete for their notification using the member/notifications/:notificationId DELETE endpoint. The workflow ensures that the member can only delete their own notifications and cannot delete others'. A notification is set up via the admin endpoint addressed to the test member.
 *
 * Test procedure:
 * 1. Register a new member (email/password)
 * 2. Log in as the member (obtain authentication context)
 * 3. Create a notification addressed to this member using the admin notification creation endpoint
 * 4. Delete the notification via the member DELETE endpoint
 * 5. Confirm the delete succeeds (no error thrown)
 * 6. Verify subsequent delete on same notification is idempotent (API may error or may not, but must not restore/deactivate the deletion)
 * 7. Attempt to soft delete a notification not belonging to this member (should fail: forbidden/unauthorized)
 *
 * Important:
 * - There is no endpoint in current API to directly fetch a notification by ID or to list the member's inbox. Thus, the test cannot directly check deleted_at or inbox removal—these parts are omitted.
 * - Only error/non-error is validated for deletes, as per what is implementable with current SDK/API.
 */
export async function test_api_member_notification_soft_delete_success(connection: api.IConnection) {
  // 1. Register member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 2. Log in as the created member
  await api.functional.auth.member.login.signIn(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create notification addressed to this member (as admin)
  const recipient_member_id = typia.random<string & tags.Format<"uuid">>();
  const notification = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id,
      event_type: "test_event",
      status: "pending",
      attempt_count: 0,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(notification);

  // 4. Member soft deletes their own notification
  await api.functional.polEcoBoard.member.notifications.erase(connection, {
    notificationId: notification.id,
  });

  // 5. Attempt to delete again (should NOT restore/delete again)
  await api.functional.polEcoBoard.member.notifications.erase(connection, {
    notificationId: notification.id,
  });

  // 6. Attempt to delete a notification that doesn't belong to this member
  const otherNotification = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "other_event",
      status: "pending",
      attempt_count: 0,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(otherNotification);
  await TestValidator.error("forbidden on foreign notification")(async () => {
    await api.functional.polEcoBoard.member.notifications.erase(connection, {
      notificationId: otherNotification.id,
    });
  });
}

