import type { IPolEcoBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAppeal";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator can view complete detail of a specific appeal record.
 *
 * This test covers the full flow of moderator-based privileged appeal inspection on the platform:
 * 1. Register a new moderator (with unique random email)
 * 2. Login as that moderator to obtain authentication
 * 3. Create an appeal (using moderator as appellant) referencing a random moderation action ID
 * 4. Retrieve the appeal by its ID through the moderator GET endpoint
 *
 * Validations:
 * - Successful retrieval and detail inspection for authorized moderator
 * - All permissible fields are present: audit/identity, rationale, timeline, moderation and workflow state, etc.
 * - Response does not include admin-only/sensitive fields beyond moderator scope
 * - All data returned (moderation_action_id, appellant_id, reviewer_admin_id, etc) matches the appeal record created
 * - Business logic is enforced per role: moderator sees all mod fields, not admin-only
 */
export async function test_api_appeal_detail_view_moderator_success(connection: api.IConnection) {
  // 1. Register a new moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "P@ssw0rd1234";
  const displayName = RandomGenerator.name();
  const consentStatus = "accepted-v1"; // assuming business-consent string
  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registration);

  // 2. Login as the new moderator (to set proper Authorization, in case the registration token is not re-used)
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(login);

  // 3. Create an appeal as the moderator
  // NOTE: moderation_action_id should be a new, valid UUID. We create a random one for test isolation.
