    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResponse);

  // At this point connection.headers should be set with the Authorization token.

  // 3. Create a valid notification preference (success)
  // We'll use email as channel and reply as valid event_type, and opt_in true
  // For member_id, use a valid uuid (the actual admin's member_id is unknown, so typia.random or test known value)
  const validPreferenceInput: IPolEcoBoardNotificationPreference.ICreate = {
    member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "reply",
    channel: "email",
    opt_in: true,
  };
