  await TestValidator.error("invalid event_type should fail")(() =>
    api.functional.polEcoBoard.admin.notificationPreferences.create(connection, {
      body: invalidTypePreference,
    }),
  );

  // 5. Attempt to create with invalid channel (should throw)
  const invalidChannelPreference: IPolEcoBoardNotificationPreference.ICreate = {
    ...validPreferenceInput,
    channel: "carrier_pigeon",
  };
