import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates that non-admin (member) users CANNOT hard-delete audit trail records (permission denied/test).
 *
 * This test ensures strong permission boundaries for audit trail deletion:
 * 1. Register a regular member and login to capture their JWT (Authorization token).
 * 2. Register and login as an admin, then create a new audit trail entry (as compliance/ops event).
 * 3. Switch authentication back to the member (simulate member session).
 * 4. Attempt to delete the admin-created audit trail as a member user (using member JWT).
 * 5. Confirm that the API rejects the request with a forbidden/permission error.
 * (
 *    The API does not publish a GET for audit trails, so direct existence confirmation is omitted.
 * )
 *
 * This test is essential to ensure that critical audit record deletion is reserved exclusively for admins/super-admins, maintaining regulatory and operational trace integrity.
 */
export async function test_api_audit_trail_delete_permission_denied_non_admin(connection: api.IConnection) {
  // ------ 1. Register a regular member ------
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);
  const member: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1.0"
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // ------ 2. Member login and capture JWT ------
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);
  const memberToken: string = memberLogin.setHeaders.Authorization;

  // ------ 3. Register admin (unique email) ------
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(16);
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignup);

  // ------ 4. Admin login and capture JWT ------
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);
  const adminToken: string = adminLogin.setHeaders.Authorization;

  // ------ 5. Use admin JWT to create an audit trail record ------
  connection.headers = { ...connection.headers, Authorization: adminToken };
  const auditTrail: IPolEcoBoardAuditTrail = await api.functional.polEcoBoard.admin.auditTrails.create(connection, {
    body: {
