 *
 * Test Steps:
 * 1. Register and login memberA
 * 2. Create a post as memberA
 * 3. Cast a vote as memberA (upvote)
 * 4. MemberA updates vote to downvote (should succeed)
 * 5. Register and login memberB
 * 6. MemberB attempts to update memberA's vote (should fail)
 * 7. (If business logic exposes, try updating after expiration window -- omitted if not possible)
 */
export async function test_api_post_vote_update_by_member_success_and_failure(
  connection: api.IConnection,
) {
