  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  const signUpA = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpA);

  // 2. Login as memberA (the connection will carry the token)
  const signInA = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
