import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate updating a comment report as its submitting member before moderation review.
 *
 * This test verifies that a member can update (correct) the details of a report previously filed on a comment, as long as the moderation process has not started and within the allowed policy window. The test covers a realistic report correction scenario from end to end.
 *
 * Steps:
 * 1. Register a new member account (unique email/password) and confirm token.
 * 2. Log in as the member to get authentication.
 * 3. Create a new post in a (random) category to serve as the parent context.
 * 4. Add a comment to the post (target for the later report).
 * 5. File a report on that comment as the member, providing an initial reason and description.
 * 6. Update the comment report details (change the reason code and/or description) as the report author.
 * 7. Assert that the updated report reflects the intended changes (reason code and/or description are updated, IDs are preserved, member is same, and timestamps are reasonable).
 */
export async function test_api_comment_report_update_success_by_member(connection: api.IConnection) {
  // 1. Register a new member account
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const registerRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password
    }
  });
  typia.assert(registerRes);

  // 2. Log in as the member to get authentication
  const loginRes = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password
    }
  });
  typia.assert(loginRes);

  // 3. Create a new post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test scenario post - report update",
      body: "Testing scenario for comment report update by author.",
      tag_ids: null,
      attachments: null
    }
  });
  typia.assert(post);

  // 4. Add a comment to the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "A sample comment for testing reporting and correction."
    }
  });
  typia.assert(comment);

  // 5. File a report for the comment
  const initialReason = "abuse";
  const initialDescription = "First reason - inappropriate language.";
  const report = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: initialReason,
      reason_description: initialDescription,
      post_id: null,
      comment_id: comment.id
    }
  });
  typia.assert(report);

  // 6. Update the report's reason/description as the reporting member
  const updatedReason = "off_topic";
  const updatedDescription = "Corrected reason: not relevant to the original subject.";
  const updatedReport = await api.functional.polEcoBoard.member.comments.reports.update(connection, {
    commentId: comment.id,
    reportId: report.id,
    body: {
      reason_code: updatedReason,
      reason_description: updatedDescription
    }
  });
  typia.assert(updatedReport);

  // 7. Confirm the update is reflected correctly
  TestValidator.equals("report id unchanged")(updatedReport.id)(report.id);
  TestValidator.equals("comment id unchanged")(updatedReport.comment_id)(report.comment_id);
  TestValidator.equals("reporter member same")(updatedReport.reporter_member_id)(report.reporter_member_id);
  TestValidator.equals("reason code updated")(updatedReport.reason_code)(updatedReason);
  TestValidator.equals("description updated")(updatedReport.reason_description)(updatedDescription);
  TestValidator.predicate("created_at unchanged or reasonable")(!!updatedReport.created_at);
}

