/**
 * Validate that attempting to fetch details of a non-existent admin authentication session results in an appropriate not-found error.
 *
 * This test ensures the session details endpoint properly enforces existence checks and scoping: even with correct admin privileges, requesting a session by a UUID that does not exist should return a not-found error instead of a blank result or generic error. This is critical for admin audit dashboards and incident reviews, ensuring sensitive session data cannot be inadvertently leaked or mishandled.
 *
 * Steps:
 * 1. Register a new admin (to guarantee privilege and fresh scope; required for endpoint access).
 * 2. Login as the new admin (to set session tokens in the connection context).
 * 3. Attempt to fetch a session using a random, syntactically-valid but non-existent UUID by calling the session details endpoint.
 * 4. Assert that a not-found error (API error, typically with 404 status) is thrown and no session is returned.
 */
export async function test_api_admin_get_nonexistent_auth_session_error(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Login as the new admin to set authentication headers
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 3. Attempt to fetch a non-existent session
  const fakeAuthSessionId: string = typia.random<string & tags.Format<"uuid">>();

  // 4. Validate that a not-found error is thrown
  await TestValidator.error("not found for non-existent authSessionId")(() =>
    api.functional.polEcoBoard.admin.authSessions.at(connection, {
      authSessionId: fakeAuthSessionId,
    })
  );
}

