  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in first time (Session A)
  const signInRespA = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRespA);
  const sessionConnectionA: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: signInRespA.setHeaders.Authorization,
    },
  };

  // 3. Log in second time (Session B)
  const signInRespB = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRespB);
  const sessionConnectionB: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: signInRespB.setHeaders.Authorization,
    },
  };

  // 4. Enumerate all active sessions using SessionA
  const activeSessions = await api.functional.auth.admin.sessions.listActiveSessions(sessionConnectionA);
  typia.assert(activeSessions);
  TestValidator.predicate("at least 2 sessions exist")(activeSessions.sessions.length >= 2);

  // 5. Identify each session by sessionId
  const sessionIds = activeSessions.sessions.map((s) => s.id);
  TestValidator.equals("unique session ids")(sessionIds.length)(new Set(sessionIds).size);

  // 6. Determine sessionId for SessionB and SessionA (Authorization tokens can't be used directly: match via process of elimination)
  // We'll attempt to revoke the SessionB session using SessionA's context
  const sessionIdB = activeSessions.sessions.find((s) => s.issued_at === activeSessions.sessions.reduce((latest, s2) => s2.issued_at > latest ? s2.issued_at : latest, ""))?.id || activeSessions.sessions[1].id;
  const sessionIdA = activeSessions.sessions.find((s) => s.id !== sessionIdB)?.id || activeSessions.sessions[0].id;

  // 7. Revoke SessionB (the "second" session)
  const revokeResp = await api.functional.auth.admin.sessions.revokeSession(sessionConnectionA, {
    sessionId: sessionIdB,
  });
  typia.assert(revokeResp);
  TestValidator.equals("revoked session id")(revokeResp.sessionId)(sessionIdB);
  TestValidator.equals("session is revoked")(revokeResp.revoked)(true);
  TestValidator.predicate("revokedAt is set")(!!revokeResp.revokedAt);

  // 8. Enumerate sessions again; confirm revoked session is gone
  const activeSessionsAfter = await api.functional.auth.admin.sessions.listActiveSessions(sessionConnectionA);
  typia.assert(activeSessionsAfter);
  TestValidator.predicate("revoked session not present")(activeSessionsAfter.sessions.every((s) => s.id !== sessionIdB));
  TestValidator.predicate("at least 1 session remains")(activeSessionsAfter.sessions.length >= 1);

  // 9. Attempt an authenticated call using revoked SessionB (should fail)
  await TestValidator.error("revoked session cannot access protected API")(async () => {
    await api.functional.auth.admin.sessions.listActiveSessions(sessionConnectionB);
  });
}

