import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAuthSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAuthSession";
import type { IPageIPolEcoBoardAuthSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAuthSession";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that polEcoBoard admin authentication session search properly handles invalid filter input.
 *
 * This test covers two major negative cases:
 * 1. A validly formed UUID for member_id that does not exist in the database (should result in empty result set, not error).
 * 2. An improperly formatted member_id value (not a UUID), which should trigger validation error from the API.
 *
 * Steps:
 * 1. Register an admin account with a unique business email and strong password.
 * 2. Log in as that admin to obtain authentication and authorization headers.
 * 3. Attempt to search authentication sessions using a non-existent (but valid) UUID as member_id; verify result data is empty and no validation error occurs.
 * 4. Attempt to search authentication sessions with a member_id that is NOT a valid UUID (e.g., 'not-a-uuid'); verify API returns a validation error (e.g., 400 Bad Request) and no session data is returned.
 * 5. Optionally, attempt with other obviously invalid filter values (e.g., negative page, non-integer limit) to verify robust validation and error messaging.
 *
 * This ensures the endpoint differentiates between valid-but-not-found, and outright invalid filter values, returning correct error and result semantics.
 */
export async function test_api_admin_auth_session_search_invalid_filter(
  connection: api.IConnection,
) {
  // 1. Register admin
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Search sessions with a non-existent (valid, random) UUID
  const nonExistentMemberId: string = typia.random<string & tags.Format<"uuid">>();
  const sessionResult = await api.functional.polEcoBoard.admin.authSessions.search(connection, {
    body: {
      member_id: nonExistentMemberId,
    } satisfies IPolEcoBoardAuthSession.IRequest,
  });
  typia.assert(sessionResult);
  TestValidator.equals("empty sessions for non-existent member_id")(sessionResult.data.length)(0);

  // 4. Search sessions with an invalid member_id (not a UUID)
  await TestValidator.error("invalid UUID for member_id triggers validation error")(async () => {
    await api.functional.polEcoBoard.admin.authSessions.search(connection, {
      body: {
        member_id: "not-a-uuid",
      } satisfies IPolEcoBoardAuthSession.IRequest,
    });
  });

  // 5. Invalid paging: negative page number
  await TestValidator.error("negative page triggers validation error")(async () => {
    await api.functional.polEcoBoard.admin.authSessions.search(connection, {
      body: {
        page: -1,
      } satisfies IPolEcoBoardAuthSession.IRequest,
    });
  });

  // 6. Invalid paging: non-integer limit (string instead of number)
  await TestValidator.error("non-integer limit triggers validation error")(async () => {
    // @ts-expect-error: This is intentionally to test type violation for runtime validation
    await api.functional.polEcoBoard.admin.authSessions.search(connection, {
      body: {
        // @ts-ignore: bypass for runtime
        limit: "foo",
      } as any,
    });
  });
}

