import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAntiSpamEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAntiSpamEvent";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate successful update of an anti-spam event by an admin.
 *
 * This test follows the E2E path for robust admin content-moderation workflows.
 * It ensures the full compliance/auditability cycle:
 * - Registration of an admin
 * - Authentication of the admin session
 * - Creation of an anti-spam event as test fixture
 * - Update of the event via the provided endpoint, mutating one or more business fields (score, operation, appeal_requested, action_taken)
 * - Validation that the updated record reflects the correct persistence and business logic
 *
 * 1. Register an admin with unique credentials
 * 2. Log in as this admin (auth tokens should be set in connection)
 * 3. POST: Create an anti-spam event, extract the returned id
 * 4. PUT: Perform a meaningful update of at least two fields (for example, adjust score and toggle appeal_requested)
 * 5. Verify the returned object reflects all changes
 * 6. Optionally, ensure old values changed, and all business/audit constraints hold, such as correct id persistence and possible type/field invariants
 */
export async function test_api_anti_spam_event_update_success(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Admin login (should also set Authorization header)
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 3. Create anti-spam event (get full object with id)
  const antiSpamEventInput: IPolEcoBoardAntiSpamEvent.ICreate = {
    provider_key: "akismet",
    operation: "content_submit",
    content_hash: RandomGenerator.alphaNumeric(16),
    score: 0.4,
    action_taken: "approved",
    appeal_requested: false,
    created_at: new Date().toISOString(),
  };
  const createdEvent = await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, {
    body: antiSpamEventInput,
  });
  typia.assert(createdEvent);
  TestValidator.equals("event fields match initial input")(createdEvent.provider_key)(antiSpamEventInput.provider_key);
  TestValidator.equals("appeal requested false at creation")(createdEvent.appeal_requested)(false);

  // 4. Update event (change operation and score, toggle appeal_requested)
  const updateInput: IPolEcoBoardAntiSpamEvent.IUpdate = {
    score: createdEvent.score + 0.25,
    operation: "appeal",
    appeal_requested: true,
    action_taken: "escalated"
  };
  const updatedEvent = await api.functional.polEcoBoard.admin.antiSpamEvents.update(connection, {
    antiSpamEventId: createdEvent.id,
