import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";

/**
 * Validate that access to detailed moderation action information through the admin endpoint is properly restricted.
 *
 * This test simulates an error scenario where an unauthenticated or insufficiently privileged user attempts to fetch moderation action details using the privileged admin API. The goal is to ensure the system enforces authorization checks, denies access, and does not leak private or sensitive information via error messages or responses.
 *
 * Step-by-step process:
 * 1. Attempt to fetch moderation action details from the admin endpoint without appropriate authentication/privileges
 * 2. Expect an authorization or privilege error (access denied) to be thrown
 * 3. Confirm that the error does not expose private moderation action data in the response body
 */
export async function test_api_admin_moderation_action_detail_permission_error(
  connection: api.IConnection,
) {
  // 1. Simulate an unauthenticated/unauthorized request for moderation action details
  const fakeModerationActionId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt the request and expect an authorization error
  await TestValidator.error("unauthorized user cannot fetch admin moderation action detail")(
    async () => {
      // This must throw due to lack of privileges
      await api.functional.polEcoBoard.admin.moderationActions.at(connection, {
        moderationActionId: fakeModerationActionId,
      });
    },
  );

  // 3. (Implicit) If an error is thrown, ensure no response data is returned.
  // We do not inspect error message details for privacy reasons
}

