import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate error cases for admin vote searching with invalid or non-existent commentId and input.
 * 
 * Business context:
 * Admins need robust error feedback when performing moderation tasks. If an invalid or non-existent comment is searched, or if filtering input fails validation (e.g., impossible date ranges, out-of-bounds pagination), the API should return clear errors.
 * 
 * Steps:
 * 1. Admin registration and login (to gain admin privileges for the API call).
 * 2. Attempt search with a commentId that does not exist (random uuid).
 *    - Confirm API returns an explicit error (use TestValidator.error).
 * 3. Attempt search with a malformed/invalid commentId (not a uuid).
 *    - Confirm API returns an error for invalid format.
 * 4. Attempt search with invalid request body (e.g., created_before earlier than created_after, limit out of bounds).
 *    - Confirm API returns validation errors.
 */
export async function test_api_comment_votes_search_invalid_commentid_and_input(
  connection: api.IConnection,
) {
  // 1. Register new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Search with non-existent commentId (valid uuid, but not in DB)
  await TestValidator.error("Search for non-existent comment")(async () => {
    await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(),
      body: {},
    });
  });

  // 4. Search with malformed commentId (not a uuid)
  await TestValidator.error("Search with malformed commentId")(async () => {
    await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
      commentId: "not-a-uuid" as any, // purposely invalid, for validation failure
      body: {},
    });
  });

  // 5. Search with invalid request body - limit over 100, created_before before created_after
  await TestValidator.error("Search with invalid request input")(async () => {
    const createdAfter = new Date(Date.now() + 100000).toISOString();
    const createdBefore = new Date(Date.now()).toISOString();
    await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        created_after: createdAfter,
        created_before: createdBefore,
        limit: 101, // exceeds tags.Maximum<100>
      },
    });
  });
}

