  TestValidator.predicate("registration_enabled is boolean")(
    typeof settings.registration_enabled === "boolean",
  );
  TestValidator.predicate("max_post_length is int")(
    Number.isInteger(settings.max_post_length),
  );
  TestValidator.predicate("max_comment_length is int")(
    Number.isInteger(settings.max_comment_length),
  );
  TestValidator.predicate("default_board_visibility is boolean")(
    typeof settings.default_board_visibility === "boolean",
  );
  TestValidator.predicate("data_retention_days is int")(
    Number.isInteger(settings.data_retention_days),
  );
  TestValidator.predicate("created_at is an ISO date-time string")(
    typeof settings.created_at === "string" && settings.created_at.length > 0,
  );
  TestValidator.predicate("updated_at is an ISO date-time string")(
    typeof settings.updated_at === "string" && settings.updated_at.length > 0,
