import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validates post edit creation and audit linking for a board post written by a member.
 *
 * This test follows the end-to-end journey: member registration → authentication → post authoring → adding post edits.
 * Key validations: correct audit (editor ID matches), edit appears in revision history, multiple edits are appended.
 *
 * Steps:
 * 1. Register a member
 * 2. Log in as the member (acquire authorization)
 * 3. Create a board post (as author)
 * 4. Create the first post edit (with custom body/reason)
 * 5. Validate the edit record: editor_member_id matches member, audit fields correct, edit_body and edit_reason as provided
 * 6. Create a second edit on the same post
 * 7. Validate the new edit exists, history includes both edits with distinct timestamps (created_at)
 */
export async function test_api_post_edit_create_member_success(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberDisplayName = RandomGenerator.name();
  const memberConsentStatus = "v1";
  const createdMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: memberConsentStatus,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(createdMember);

  // 2. Log in as the member
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(loginResult);

  // 3. Create a board post
  const postCategoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(12).slice(0, 40);
  const postBody = RandomGenerator.content()()().slice(0, 300);
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: postCategoryId,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(createdPost);
  TestValidator.equals("author matches")(createdPost.author_member_id)(createdMember.id);

  // 4. Create the first post edit
  const firstEditBody = RandomGenerator.content()()().slice(0, 200);
  const firstEditReason = "Initial correction";
  const firstEdit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
    postId: createdPost.id,
    body: {
      edit_body: firstEditBody,
      edit_reason: firstEditReason,
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(firstEdit);
  TestValidator.equals("editor matches member")(firstEdit.editor_member_id)(createdMember.id);
  TestValidator.equals("edit body matches")(firstEdit.edit_body)(firstEditBody);
  TestValidator.equals("edit reason matches")(firstEdit.edit_reason)(firstEditReason);
  TestValidator.predicate("first edit created_at valid")(!!firstEdit.created_at);

  // 5. Create a second edit for the same post
  const secondEditBody = RandomGenerator.content()()().slice(0, 200);
  const secondEditReason = "Clarification";
  const secondEdit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
    postId: createdPost.id,
    body: {
      edit_body: secondEditBody,
      edit_reason: secondEditReason,
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(secondEdit);
  TestValidator.equals("editor matches member 2")(secondEdit.editor_member_id)(createdMember.id);
  TestValidator.notEquals("two edit IDs differ")(firstEdit.id)(secondEdit.id);
  TestValidator.notEquals("edit timestamps differ")(firstEdit.created_at)(secondEdit.created_at);

  // 6. (Optional) Post-edit: If API supported edit history fetch, would validate both edits are present for the post (not implemented here).
}

