 * 3. Log in as the member (obtain member's JWT and session)
 * 4. Attempt to access moderator details endpoint using member authentication
 * 5. Confirm that a forbidden error is thrown (insufficient permission)
 * 6. (Negative assertion) No privileged moderator data should be returned to the member
 *
 * This confirms compliance with privilege separation policies and enforces security around moderator account management.
 */
export async function test_api_moderator_account_detail_forbidden_for_regular_member(connection: api.IConnection) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "MemberPass123!";
  const consent = "consent_v1";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // Normally would hash, for test pass as-is if API expects raw/hash for test
      display_name: RandomGenerator.name(),
      consent_status: consent,
      profile_image_uri: null
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Register a moderator (simulate business registration flow)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "ModeratorPass123!";
  const moderatorDisplayName = RandomGenerator.name();
