  const moderatorId = moderatorRegistration.moderatorId;

  // 3. Log in as member
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(loginResult);
  // Authorization header is managed by the SDK in connection.headers

  // 4. Attempt forbidden access to moderator detail
  await TestValidator.error("Regular member must not access moderator account details")(
    async () => {
      await api.functional.polEcoBoard.moderator.moderators.at(connection, {
        moderatorId: moderatorId
      });
    }
  );
}

