/**
 * Test viewing a notification as a moderator. This comprehensive test ensures that only an intended recipient moderator can view their assigned notification, correct metadata is present, unauthorized/invalid accesses are properly handled, and privacy boundaries are respected.
 *
 * Test Steps:
 * 1. Register a new moderator with valid data (including consent). Assert fields in response.
 * 2. Log in as the new moderator and store/set the Authorization in connection headers.
 * 3. Register and log in as a new admin; set Authorization for privileged notification creation.
 * 4. From admin context, create a notification with recipient_member_id set to the moderator's memberId. Use a valid event_type and status, leave optional fields (provider_id, related_object_id) as null or omitted. Assert response and returned fields.
 * 5. Switch connection back to the moderator context by re-logging in (or restoring moderator's JWT in headers).
 * 6. Fetch the created notification via moderator API, asserting:
 *    - All expected metadata (ids, timestamps, event_type, etc.) is returned
 *    - recipient_member_id matches moderator's id
 *    - TestValidator.equals on returned fields vs. input/expected
 *    - Privacy: No sensitive fields from other accounts leak
 * 7. Attempt to fetch a notification with a random (nonexistent) UUID. Confirm proper not-found error occurs (using TestValidator.error).
 * 8. Register/log in a DIFFERENT moderator. Try to access the notification created for the first moderator with this second moderator's token, expecting forbidden error.
 */
export async function test_api_moderator_notification_access_success_and_failure(connection: api.IConnection) {
  // 1. Register a new moderator
  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderatorPassword = 'moder@Pass123';
  const moderatorDisplayName = RandomGenerator.name();
