    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals('moderator login email')(moderatorLogin.email)(moderatorEmail);
  // Set connection.headers for moderator session
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorLogin.setHeaders.Authorization,
  };

  // 3. Register and login as admin (to create notifications)
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'admin@PolEco123';
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword },
