  TestValidator.predicate("created_at present")(typeof details.created_at === "string" && details.created_at.length > 0);
  TestValidator.predicate("updated_at present")(typeof details.updated_at === "string" && details.updated_at.length > 0);
  TestValidator.predicate("requested_at present")(typeof details.requested_at === "string" && details.requested_at.length > 0);
