import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Ensures escalation status lifecycle compliance: rejects illegal status reversal after resolution.
 * 
 * Business context: Once an escalation is marked resolved (terminal/final status), business rules prohibit it from being updated back to a non-terminal status such as 'pending' (except with special override permissions, which are not present in this scenario). This test verifies that such illegal transitions are correctly blocked and result in appropriate business errors.
 *
 * Workflow:
 * 1. Register a new admin with unique email and secure password.
 * 2. Authenticate as that admin (ensure Authorization set in connection for subsequent privileged calls).
 * 3. Create a new escalation, initially in 'pending' state.
 * 4. Update the escalation to a terminal status: set status to 'resolved'.
 * 5. Attempt to transition the escalation status back to a non-terminal value (e.g., 'pending').
 * 6. Validate that the system rejects this action (an error is thrown) and that escalation status cannot be reverted from finalized/locked states except with special privilege (which is not present).
 */
export async function test_api_escalation_update_status_illegal_transition_error(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(registerResponse);

  // 2. Log in as that admin
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(loginResponse);

  // 3. Create a new escalation (set status: 'pending')
  const escalationCreateInput: IPolEcoBoardEscalation.ICreate = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    escalator_id: typia.random<string & tags.Format<"uuid">>(),
    recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
    reason: RandomGenerator.paragraph()(120),
    status: 'pending',
  };
  const escalation = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: escalationCreateInput
  });
  typia.assert(escalation);

  // 4. Mark escalation as 'resolved' (terminal status)
  const resolvedEscalation = await api.functional.polEcoBoard.admin.escalations.update(connection, {
    escalationId: escalation.id,
    body: { status: 'resolved' } satisfies IPolEcoBoardEscalation.IUpdate
  });
  typia.assert(resolvedEscalation);
  TestValidator.equals("status resolved")(resolvedEscalation.status)('resolved');

  // 5. Attempt to revert back to non-terminal status ('pending'), expect failure
  await TestValidator.error("illegal status transition: resolved → pending should fail")(async () => {
    await api.functional.polEcoBoard.admin.escalations.update(connection, {
      escalationId: escalation.id,
      body: { status: 'pending' } satisfies IPolEcoBoardEscalation.IUpdate
    });
  });
}

