import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the hard deletion of an anti-spam event by an admin user.
 *
 * This function validates the following workflow:
 * 1. Register a new admin account (required for admin operations).
 * 2. Login as the newly registered admin, verifying authentication.
 * 3. Create a new anti-spam event as a subject for deletion.
 * 4. Perform a hard delete of the created anti-spam event.
 * 5. Confirm that the event is permanently removed by attempting to delete it again and expecting an error.
 * 6. (Skipped: Confirm audit log compliance as there is no API for audit log retrieval.)
 *
 * This ensures admin hard deletion actually erases the record, with no data retained, and no foreign key or relationship errors follow.
 */
export async function test_api_anti_spam_event_hard_delete_success(
  connection: api.IConnection,
) {
  // 1. Register new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignUp,
    },
  );
  typia.assert(signUpResp);

  // 2. Login as admin (token management handled by SDK)
  const signInResp = await api.functional.auth.admin.login.signIn(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignIn,
    },
  );
  typia.assert(signInResp);

  // 3. Create a new anti-spam event to delete
  const antiSpamEventInput = {
    provider_key: RandomGenerator.alphaNumeric(8),
    operation: "content_submit",
    content_hash: RandomGenerator.alphaNumeric(40),
    score: 0.7,
    action_taken: "blocked",
    appeal_requested: false,
    created_at: new Date().toISOString(),
  } satisfies IPolEcoBoardAntiSpamEvent.ICreate;
  const antiSpamEvent = await api.functional.polEcoBoard.admin.antiSpamEvents.create(
    connection,
    {
      body: antiSpamEventInput,
    },
