  const end = new Date(now.getTime() + 3_600_000).toISOString(); // +1h
  const createBody: IPolEcoBoardMaintenanceWindow.ICreate = {
    window_code: `MAINT_${now.toISOString().replace(/[-:.TZ]/g, "").slice(0,12)}`,
    start_time: start,
    end_time: end,
    expected_impact: "Scheduled DB maintenance - no downtime expected.",
    notified_at: null,
  };
  const created = await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
    body: createBody,
  });
