  };
  await TestValidator.error("overlap/uniqueness error expected")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
      body: conflictBody,
    });
  });

  // 5. Try to create invalid window (end < start)
  const badTimeBody: IPolEcoBoardMaintenanceWindow.ICreate = {
    window_code: `MAINT_BADRANGE_${now.getTime()}`,
    start_time: end,
    end_time: start,
