  await TestValidator.error("invalid time range")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
      body: badTimeBody,
    });
  });

  // 6. Try with unauthenticated connection (simulate by clearing headers)
  const unauthConnection = {
    ...connection,
    headers: {},
  };
  await TestValidator.error("auth required")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.create(unauthConnection, {
      body: createBody,
    });
  });
