import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardIncident } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardIncident";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test: polEcoBoard admin incident update (success + validation + permission cases).
 *
 * This test covers:
 * 1. Registering a new admin and logging in.
 * 2. Creating a new incident as admin.
 * 3. Successfully updating mutable fields (description, status, category, etc.).
 * 4. Attempting to update immutable fields (incident_code, created_at) – these fields are not present in the update DTO, so such an attempt is not type-safe and skipped.
 * 5. Permission/authorization check: attempt update with no admin login to ensure permission error is thrown.
 */
export async function test_api_incident_update_success_and_validation_cases(connection: api.IConnection) {
  // Step 1: Register and log in as an admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  // Admin is now registered (token is in connection.headers via SDK)

  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  // SDK should now have admin JWT in connection.headers

  // Step 2: Create a new incident as admin
  const incidentInput: IPolEcoBoardIncident.ICreate = {
    incident_code: RandomGenerator.alphaNumeric(10),
    category: RandomGenerator.pick([
      "OUTAGE", "MAINTENANCE", "BREACH", "COMPLIANCE", "LEGAL",
    ]),
    status: RandomGenerator.pick([
      "OPEN", "RESOLVED", "ESCALATED", "UNDER_REVIEW", "CLOSED",
    ]),
    description: RandomGenerator.paragraph()(),
    detected_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: IPolEcoBoardIncident = await api.functional.polEcoBoard.admin.incidents.create(connection, {
    body: incidentInput,
  });
  typia.assert(created);

  // Step 3: Update mutable fields
  const newDescription = RandomGenerator.paragraph()();
  const newStatus = "RESOLVED";
  const newCategory = created.category;
  const newDetectedAt = created.detected_at;
  const resolvedAt = new Date().toISOString() as string & tags.Format<"date-time">;
  const updateInput: IPolEcoBoardIncident.IUpdate = {
    category: newCategory,
    status: newStatus,
    description: newDescription,
    detected_at: newDetectedAt,
    resolved_at: resolvedAt,
  };
  const updated: IPolEcoBoardIncident = await api.functional.polEcoBoard.admin.incidents.update(connection, {
    incidentId: created.id,
    body: updateInput,
  });
  typia.assert(updated);
  TestValidator.equals("description change")(updated.description)(newDescription);
  TestValidator.equals("status change")(updated.status)(newStatus);
  TestValidator.equals("resolved at change")(updated.resolved_at)(resolvedAt);
  TestValidator.equals("incident code remains")(updated.incident_code)(created.incident_code);
  TestValidator.equals("created_at remains")(updated.created_at)(created.created_at);

  // Step 4: Attempt to update forbidden/immutable fields (skipped, not present in DTO)
  // If attempted, TypeScript will prevent compilation.
  // Optionally, attempt to pass invalid values to existing updatable fields to cause business error
  await TestValidator.error("invalid status fails")(() =>
    api.functional.polEcoBoard.admin.incidents.update(connection, {
      incidentId: created.id,
      body: {
        ...updateInput,
        status: "INVALID_STATUS",
      } as any, // Will cause a runtime validation error from API
    }),
  );

  // Step 5: Attempt update with unauthenticated connection (simulate by removing Authorization header)
  const noAuthConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}) },
  };
  delete noAuthConnection.headers.Authorization;
  await TestValidator.error("permission required for update")(() =>
    api.functional.polEcoBoard.admin.incidents.update(noAuthConnection, {
      incidentId: created.id,
      body: updateInput,
    }),
  );
}

