import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Ensure that a standard (non-admin) member cannot update a comment via the admin API endpoint.
 *
 * This test checks if role-based access control is enforced properly by verifying that unauthenticated or member-authenticated users are denied permission when attempting an admin-level operation (comment update through the admin endpoint).
 *
 * Steps:
 * 1. Register as a new member with a unique email and password.
 * 2. Login as this member to obtain the JWT/auth token.
 * 3. Create a new post as the member (to have an associated post for the comment).
 * 4. Add a new comment to the created post as the member (target for the forbidden update attempt).
 * 5. Attempt to update the comment using the admin endpoint (without admin login), trying to edit the comment body.
 * 6. Verify that this attempt fails with a permission denied or forbidden error (error is thrown).
 *
 * This process validates that only admins can use the admin comment update endpoint, and members are prevented from unauthorized admin actions.
 */
export async function test_api_comment_admin_update_permission_denied(connection: api.IConnection) {
  // 1. Register as a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(signUpResult);

  // 2. Login as the new member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(signInResult);

  // 3. Create a new post as the member
  const postCreateInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(10),
    body: RandomGenerator.content()()(10),
    tag_ids: null,
    attachments: null,
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postCreateInput,
  });
  typia.assert(post);

  // 4. Create a top-level comment as the member
  const commentCreateInput: IPolEcoBoardComment.ICreate = {
    body: RandomGenerator.paragraph()(10),
  };
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: commentCreateInput,
  });
  typia.assert(comment);

  // 5. Attempt to update the comment via the admin endpoint as a non-admin (should fail)
  await TestValidator.error("non-admin cannot update comment using admin endpoint")(async () => {
    await api.functional.polEcoBoard.admin.posts.comments.update(connection, {
      postId: post.id,
      commentId: comment.id,
      body: {
        body: RandomGenerator.paragraph()(12),
      },
    });
  });
}

