/**
 * Validate hard deletion of a polEcoBoard analytics event by admin user.
 *
 * 1. Register new admin account.
 * 2. Login with the new admin account.
 * 3. Create a new analytics event (and verify output).
 * 4. Delete the analytics event as admin.
 * 5. Verify delete succeeded (no errors, or HTTP 204/empty response).
 * 6. Attempt to delete the same event again (should return error / idempotent fail).
 * 7. Attempt to delete a random non-existent analyticsEventId (should return error).
 * 8. Confirm that an unauthorized (non-admin) user CANNOT delete events (should fail with permission error if possible, given API surface).
 *
 * Ensure correct error handling and compliance with all business/role rules.
 */
export async function test_api_analytics_events_delete_admin(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 3. Create analytics event
  const eventInput: IPolEcoBoardAnalyticsEvent.ICreate = {
    event_type: "page_view",
    session_anon_id: RandomGenerator.alphaNumeric(16),
    user_role: "admin",
    event_details: JSON.stringify({ page: "/dashboard", action: "create" }),
    region: "US",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const event = await api.functional.polEcoBoard.admin.analyticsEvents.create(connection, {
    body: eventInput
  });
  typia.assert(event);

  // 4. Delete event as admin
  await api.functional.polEcoBoard.admin.analyticsEvents.erase(connection, {
    analyticsEventId: event.id
  });

  // 5. Try deleting again (should fail)
  await TestValidator.error("delete already-deleted analytics event")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.erase(connection, {
      analyticsEventId: event.id
    })
  );

  // 6. Try deleting a random non-existent event
  await TestValidator.error("delete nonexistent analytics event")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.erase(connection, {
      analyticsEventId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // 7. [Unauthorized attempt]: Try deleting as not-logged-in user
  // Remove Authorization header to simulate no login
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthorized delete attempt")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.erase(unauthConn, {
      analyticsEventId: event.id
    })
  );
}

