/**
 * Verify searching of role transition records as an admin with multiple filters
 * 
 * This test ensures that an admin can successfully query the role transition record table using various filters like affected user, destination role, and status, and that the result correctly includes previously created transitions. 
 *
 * Steps:
 * 1. Register a new admin user.
 * 2. Login as the admin (ensures Authorization for restricted endpoints).
 * 3. Create a role transition event (e.g., promote a member to moderator) with consistent, known values so it can be found again.
 * 4. Search with filters:
 *    (a) Using the affected account's ID
 *    (b) Using the destination_role
 *    (c) Using the status
 *    (d) Using invalid filters to ensure the transition is excluded
 * 5. Verify that the created transition appears in the correct search results and does NOT appear when filters don't match.
 * 6. Paginate (page=1, limit=1) and verify correct pagination structure.
 */
export async function test_api_role_transition_search_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as the admin
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);

  // 3. Create a role transition for a new user id
  const affectedAccountId = typia.random<string & tags.Format<"uuid">>();
  const transition: IPolEcoBoardRoleTransition = await api.functional.polEcoBoard.admin.roleTransitions.create(connection, {
    body: {
      account_id: affectedAccountId,
      approved_by_admin_id: affectedAccountId, // For test simplicity (assuming valid), otherwise use random
      origin_role: "member",
