import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPageIPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for administrative notification search, filtering, audit, and permission boundaries.
 *
 * 1. Register an admin, authenticate.
 * 2. Register a member and a moderator for recipient variety.
 * 3. As admin, create notifications for each role/user using multiple event_type, status, and (optionally) channels/related_object_id.
 * 4. Use PATCH /polEcoBoard/admin/notifications as admin to:
 *    a. Retrieve all notifications with no filter (verify contents and visibility of delivery/context fields, including for other users)
 *    b. Filter by recipient_member_id, event_type, and status, checking only matching notifications are returned.
 *    c. Test time window (created_from/to) filtering (create some in past and some now; verify boundaries).
 *    d. Paginate/sort (set limit=1 and page=1/2; verify correct notification order and content, especially with multiple records).
 * 5. As non-admin (member or moderator), attempt PATCH /polEcoBoard/admin/notifications (should be forbidden/denied, error expected).
 * 6. Attempt PATCH /polEcoBoard/admin/notifications with invalid query/parameters (e.g., bad UUID, negative page/limit) and check for error response.
 * 7. Throughout, validate types and correctness of metadata in responses (id, event_type, status, attempt_count, etc).
 */
export async function test_api_notification_search_admin_privileged_audit_and_filtering(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPw = RandomGenerator.alphaNumeric(10);
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
      body: { email: adminEmail, password: adminPw } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminReg);
  // 2. Admin login (session changes):
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
      body: { email: adminEmail, password: adminPw } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Member registration
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPw = RandomGenerator.alphaNumeric(10);
  const memberReg = await api.functional.auth.member.register.signUp(connection, {
      body: { email: memberEmail, password: memberPw } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberReg);
  const memberId = (/
    (jwt => JSON.parse(atob(jwt.split('.')[1])).sub)
  )(memberReg.setHeaders.Authorization.replace(/Bearer /, ''));

  // 4. Moderator registration
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPw = RandomGenerator.alphaNumeric(12);
  const modReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPw,
      display_name: RandomGenerator.name(),
      consent_status: "1",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(modReg);
  const moderatorId = modReg.moderatorId;

  // 5. Create notifications for each
  // Prepare variations of event_type, status. Use random UUID for related_object_id/channel.
  const now = new Date();
  const eventTypes = ["reply", "moderation_action", "admin_notice"];
  const statuses = ["pending", "delivered"];

  // For each user role
  const allRecipients = [memberId, moderatorId];
  const allNotes: IPolEcoBoardNotification[] = [];
  for (let i = 0; i < allRecipients.length; ++i) {
    for (const eventType of eventTypes) {
      for (const status of statuses) {
        const note = await api.functional.polEcoBoard.admin.notifications.create(connection, {
          body: {
            recipient_member_id: allRecipients[i],
            event_type: eventType,
            status,
            // Simulate multiple delivery attempts and fake timestamps
            attempt_count: i + 1,
            related_object_id: typia.random<string & tags.Format<"uuid">>(),
            provider_id: Math.random() > 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
          } satisfies IPolEcoBoardNotification.ICreate
        });
        typia.assert(note);
        allNotes.push(note);
      }
    }
  }

  // Admin notification to himself
  const adminSelfNote = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: memberId, // Fake: treat admin as member for notification
      event_type: "admin_notice",
      status: "pending",
      attempt_count: 1,
      related_object_id: typia.random<string & tags.Format<"uuid">>(),
      provider_id: null,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(adminSelfNote);

  // 6. List all notifications (no filter)
  let results = await api.functional.polEcoBoard.admin.notifications.index(connection, {
    body: {} satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(results);
  TestValidator.predicate("admin sees all notifications")(results.data.length >= allNotes.length);
  // Check contents, delivery/context fields visibility
  for (const note of results.data) {
    TestValidator.predicate("notification has required fields")(!!note.id && !!note.event_type && !!note.status);
  }

  // 7. Filter by recipient
  for (const rec of allRecipients) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { recipient_member_id: rec } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("all match recipient")(n.recipient_member_id)(rec);
    }
  }

  // 8. Filter by event_type
  for (const eventType of eventTypes) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { event_type: eventType } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("event_type matches")(n.event_type)(eventType);
    }
  }

  // 9. Filter by status
  for (const status of statuses) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { status } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("status matches")(n.status)(status);
    }
  }

  // 10. Date/time boundary filter: use created_from/to (pick earliest/latest note created_at in test set)
