import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPageIPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for administrative notification search, filtering, audit, and permission boundaries.
 *
 * Validates:
 * - Admin can list/search all notifications, with delivery/audit metadata for any user
 * - Filtering by recipient, event_type, status, time window, as well as pagination/sorting
 * - Audit/permission boundaries: only admins may access; others are denied
 * - Error handling for malformed queries (bad uuid, invalid page/limit)
 *
 * Steps:
 * 1. Register and log in as admin (set session)
 * 2. Register member and moderator recipients
 * 3. Create cross-role notifications (variation of event_types/status)
 * 4. Full search with no filter (check all fields/visibility)
 * 5. Filtering by recipient, event_type, and status
 * 6. Filtering by created_at windows
 * 7. Pagination with limit/page checks
 * 8. Negative: non-admin search deny
 * 9. Negative: error with invalid params
 */
export async function test_api_notification_search_admin_privileged_audit_and_filtering(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPw = RandomGenerator.alphaNumeric(10);
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPw } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminReg);

  // 2. Admin login (cred store in session)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPw } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Member registration (need id from JWT sub field)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPw = RandomGenerator.alphaNumeric(10);
  const memberReg = await api.functional.auth.member.register.signUp(connection, {
    body: { email: memberEmail, password: memberPw } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberReg);
  const memberToken = memberReg.setHeaders.Authorization.replace(/^Bearer /, "");
  const memberId = JSON.parse(atob(memberToken.split(".")[1])).sub as string;

  // 4. Moderator registration
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPw = RandomGenerator.alphaNumeric(12);
  const modReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPw,
      display_name: RandomGenerator.name(),
      consent_status: "1",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(modReg);
  const moderatorId = modReg.moderatorId;

  // 5. Create notifications for each user (member, moderator)
  const now = new Date();
  const eventTypes = ["reply", "moderation_action", "admin_notice"];
  const statuses = ["pending", "delivered"];
  const allRecipients = [memberId, moderatorId];
  const allNotes: IPolEcoBoardNotification[] = [];
  for (const rec of allRecipients) {
    for (const eventType of eventTypes) {
      for (const status of statuses) {
        const note = await api.functional.polEcoBoard.admin.notifications.create(connection, {
          body: {
            recipient_member_id: rec,
            event_type: eventType,
            status,
            attempt_count: Math.floor(Math.random() * 3) + 1,
            related_object_id: typia.random<string & tags.Format<"uuid">>(),
            provider_id: Math.random() > 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
          } satisfies IPolEcoBoardNotification.ICreate,
        });
        typia.assert(note);
        allNotes.push(note);
      }
    }
  }

  // Admin notification to member (simulate self note)
  const adminSelfNote = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: memberId,
      event_type: "admin_notice",
      status: "pending",
      attempt_count: 1,
      related_object_id: typia.random<string & tags.Format<"uuid">>(),
      provider_id: null,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(adminSelfNote);

  // 6. List all notifications (no filter, as admin)
  let results = await api.functional.polEcoBoard.admin.notifications.index(connection, {
    body: {} satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(results);
  TestValidator.predicate("admin sees all notifications")(results.data.length >= allNotes.length);
  for (const note of results.data) {
    TestValidator.predicate("id present")(!!note.id);
    TestValidator.predicate("recipient present")(!!note.recipient_member_id);
    TestValidator.predicate("event_type present")(!!note.event_type);
    TestValidator.predicate("status present")(!!note.status);
    TestValidator.predicate("attempt_count >= 1")(note.attempt_count >= 1);
    TestValidator.predicate("created_at valid")(!!note.created_at);
    TestValidator.predicate("updated_at valid")(!!note.updated_at);
  }

  // 7. Filter by recipient
  for (const rec of allRecipients) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { recipient_member_id: rec } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("recipient matches")(n.recipient_member_id)(rec);
    }
  }

  // 8. Filter by event_type
  for (const eventType of eventTypes) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { event_type: eventType } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("event_type matches")(n.event_type)(eventType);
    }
  }

  // 9. Filter by status
  for (const status of statuses) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { status } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("status matches")(n.status)(status);
    }
  }

  // 10. Date/time boundary filter
  const dates = allNotes.map(n => new Date(n.created_at));
  const minCreated = new Date(Math.min(...dates.map(d => d.valueOf()))).toISOString();
  const maxCreated = new Date(Math.max(...dates.map(d => d.valueOf()))).toISOString();
  const dateFilterRes = await api.functional.polEcoBoard.admin.notifications.index(connection, {
    body: { created_from: minCreated, created_to: maxCreated } satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(dateFilterRes);
  TestValidator.predicate("date filter returns records")(dateFilterRes.data.length > 0);
  for (const n of dateFilterRes.data) {
    TestValidator.predicate("created_at in range")(n.created_at >= minCreated && n.created_at <= maxCreated);
  }

  // 11. Pagination - limit 1, page 1 and 2
  const page1 = await api.functional.polEcoBoard.admin.notifications.index(connection, {
    body: { limit: 1, page: 1 } satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(page1);
  const page2 = await api.functional.polEcoBoard.admin.notifications.index(connection, {
    body: { limit: 1, page: 2 } satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(page2);
  TestValidator.notEquals("page 1 and 2 results differ")(page1.data[0]?.id)(page2.data[0]?.id);

  // 12. Permission test: member tries admin search
  connection.headers.Authorization = memberReg.setHeaders.Authorization;
  await TestValidator.error("non-admin denied notification search")(async () => {
    await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: {} satisfies IPolEcoBoardNotification.IRequest,
    });
  });

  // 13. Invalid parameter: bad uuid, negative page/limit
  await TestValidator.error("bad UUID for recipient")(async () => {
    await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { recipient_member_id: "bad-uuid-value" as any } as any,
    });
  });
  await TestValidator.error("negative page/limit")(async () => {
    await api.functional.polEcoBoard.admin.notifications.index(connection, {
      body: { limit: -1, page: -2 } as any,
    });
  });
}

