 *     - Submit invalid moderation_action_id (not a UUID)
 *     - Submit invalid appellant_id (not a UUID)
 *     - Submit empty reason string
 * 4. Confirm that each attempt returns a validation error and does not succeed.
 */
export async function test_api_member_appeal_creation_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Register a new member (for valid appellant_id context)
  const plainPassword = "TestPassword123$";
  const email = typia.random<string & tags.Format<"email">>();
