    profile_image_uri: null,
    consent_status: "v1"
  } satisfies IPolEcoBoardMember.ICreate;
  const member01 = await api.functional.polEcoBoard.members.create(connection, {
    body: member01Input,
  });
  typia.assert(member01);

  // 2. Register member02 (attacker)
  const member02Input = {
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(15),
    display_name: RandomGenerator.name(),
    profile_image_uri: null,
    consent_status: "v1"
  } satisfies IPolEcoBoardMember.ICreate;
  const member02 = await api.functional.polEcoBoard.members.create(connection, {
    body: member02Input,
  });
  typia.assert(member02);

  // 3. Admin creates a category
  const categoryInput = {
    name: RandomGenerator.paragraph()(1, 3),
    description: RandomGenerator.alphaNumeric(10),
    display_order: 1,
  } satisfies IPolEcoBoardCategory.ICreate;
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, { body: categoryInput });
  typia.assert(category);

  // 4. Admin creates a board
  const boardInput = {
    pol_eco_board_category_id: category.id,
    name: RandomGenerator.paragraph()(1, 3),
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
    description: null,
    is_public: true,
    is_archived: false,
    display_order: 1,
  } satisfies IPolEcoBoardBoard.ICreate;
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, { body: boardInput });
  typia.assert(board);

  // 5. Log in as member01 (assume that registration also authenticates or the session simulates member01)
  // (No explicit login endpoint in the SDK - assume registration changes connection's authorized user)

  // 6. member01 creates a post in the created category
  const postInput = {
    category_id: category.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    tag_ids: [],
    attachments: [],
  } satisfies IPolEcoBoardPost.ICreate;
  const post = await api.functional.polEcoBoard.member.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 7. Admin creates a tag
  const tagInput = {
    name: RandomGenerator.alphaNumeric(8),
    slug: RandomGenerator.alphaNumeric(8).toLowerCase(),
    description: null
  } satisfies IPolEcoBoardTag.ICreate;
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, { body: tagInput });
  typia.assert(tag);

  // 8. member01 assigns the tag to the post
  const postTagInput = {
    tag_id: tag.id,
  } satisfies IPolEcoBoardPostTag.ICreate;
  const postTag = await api.functional.polEcoBoard.member.posts.postTags.create(connection, { postId: post.id, body: postTagInput });
  typia.assert(postTag);

  // 9. Switch to member02 context (simulate as if member02 is now active)
  // There's no explicit login, so if available, set connection to member02's session
  // For this E2E, assume connection can be swapped or simulate within the test

  // 10. Attempt to update the post tag assignment as member02 (should fail)
  await TestValidator.error("Should not allow unauthorized update")(
    async () => {
      await api.functional.polEcoBoard.member.posts.postTags.update(connection, {
        postId: post.id,
        postTagId: postTag.id,
        body: { tag_id: tag.id } satisfies IPolEcoBoardPostTag.IUpdate,
      });
    }
  );
}

