import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAnalyticsEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAnalyticsEvent";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the detailed lookup for a polEcoBoard analytics event (admin-only).
 *
 * This test confirms that an admin can register/login, create a new analytics event, and successfully retrieve its details using the analyticsEventId. It ensures all fields match between creation and retrieval.
 * Also tests error handling for non-existent IDs and confirms that unauthorized access (unauthenticated calls) is not permitted.
 *
 * Steps:
 * 1. Register a new admin with unique email and valid password
 * 2. Login as the new admin
 * 3. Create a new analytics event and record its analyticsEventId
 * 4. Retrieve event details using the analyticsEventId
 * 5. Validate presence and correctness of all event fields per schema (event_type, session_anon_id, user_role, event_details, region, created_at), confirming no PII is present
 * 6. Attempt to fetch an event with an invalid/non-existent ID; expect a not-found or business error
 * 7. Attempt to fetch the event as an unauthorized/unauthenticated user; expect denial
 */
export async function test_api_analytics_events_detail_admin(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signUpRes);

  // 2. Login as admin (to set connection credentials)
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signInRes);

  // 3. Create a new analytics event
  const createInput: IPolEcoBoardAnalyticsEvent.ICreate = {
    event_type: "page_view",
    session_anon_id: RandomGenerator.alphaNumeric(16),
    user_role: "admin",
    event_details: JSON.stringify({ path: "/polEcoBoard/dashboard", extra: RandomGenerator.content()()() }),
    region: "US",
    created_at: new Date().toISOString(),
  };
  const createdEvent = await api.functional.polEcoBoard.admin.analyticsEvents.create(connection, {
    body: createInput,
  });
  typia.assert(createdEvent);
  TestValidator.equals("event_type matches")(createdEvent.event_type)(createInput.event_type);
  TestValidator.equals("session_anon_id matches")(createdEvent.session_anon_id)(createInput.session_anon_id);
  TestValidator.equals("user_role matches")(createdEvent.user_role)(createInput.user_role);
  TestValidator.equals("event_details matches")(createdEvent.event_details)(createInput.event_details);
  TestValidator.equals("region matches")(createdEvent.region)(createInput.region);
  TestValidator.equals("created_at matches")(createdEvent.created_at)(createInput.created_at);

  // 4. Retrieve event details using analyticsEventId
  const fetchedEvent = await api.functional.polEcoBoard.admin.analyticsEvents.at(connection, {
    analyticsEventId: createdEvent.id,
  });
  typia.assert(fetchedEvent);
  TestValidator.equals("event_type matches")(fetchedEvent.event_type)(createInput.event_type);
  TestValidator.equals("session_anon_id matches")(fetchedEvent.session_anon_id)(createInput.session_anon_id);
  TestValidator.equals("user_role matches")(fetchedEvent.user_role)(createInput.user_role);
  TestValidator.equals("event_details matches")(fetchedEvent.event_details)(createInput.event_details);
  TestValidator.equals("region matches")(fetchedEvent.region)(createInput.region);
  TestValidator.equals("created_at matches")(fetchedEvent.created_at)(createInput.created_at);

  // 5. Negative: fetch with invalid analyticsEventId
  await TestValidator.error("should not find event for random analyticsEventId")(
    () => api.functional.polEcoBoard.admin.analyticsEvents.at(connection, {
      analyticsEventId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 6. Negative: unauthorized request
  // Remove credentials
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized user cannot access event details")(
    () => api.functional.polEcoBoard.admin.analyticsEvents.at(unauthConnection, {
      analyticsEventId: createdEvent.id,
    }),
  );
}

