import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates the retrieval of a discussion board's full details by boardId for admin users.
 *
 * This test ensures:
 * 1. Category and board can be created through the admin workflow.
 * 2. Authenticated admin can retrieve board by its id and receives all required business fields.
 * 3. Retrieving with a non-existent boardId yields not-found error.
 * 4. Retrieving with an invalid UUID returns a validation error.
 * 5. Attempting access as non-admin yields a forbidden error.
 */
export async function test_api_board_detail_retrieval_by_id(connection: api.IConnection) {
  // Step 1: Register a new admin and login to obtain valid admin session.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestAdmin1!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // Step 2: Create a new category to associate with the board.
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `Economics ${typia.random<number & tags.Type<"int32">>()}`,
      description: "Discussion about Economics",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // Step 3: Create a new board under this category.
  const boardCreateData: IPolEcoBoardBoard.ICreate = {
    pol_eco_board_category_id: category.id,
    name: `Global Finance Board ${typia.random<number & tags.Type<"int32">>()}`,
    code: `finance_${typia.random<number & tags.Type<"int32">>()}`,
    description: "Discussions on international finance and policies.",
    is_public: true,
    is_archived: false,
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: boardCreateData,
  });
  typia.assert(board);

  // Step 4: Retrieve the board details as admin by id.
  const fetched = await api.functional.polEcoBoard.admin.boards.at(connection, {
    boardId: board.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id matches")(fetched.id)(board.id);
  TestValidator.equals("category link matches")(fetched.pol_eco_board_category_id)(category.id);
  TestValidator.equals("name matches")(fetched.name)(boardCreateData.name);
  TestValidator.equals("code matches")(fetched.code)(boardCreateData.code);
  TestValidator.equals("description matches")(fetched.description)(boardCreateData.description);
  TestValidator.equals("is_public matches")(fetched.is_public)(boardCreateData.is_public);
  TestValidator.equals("is_archived matches")(fetched.is_archived)(boardCreateData.is_archived);
  TestValidator.equals("display order")(fetched.display_order)(boardCreateData.display_order);
  TestValidator.predicate("created_at is ISO string")(!!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at is ISO string")(!!Date.parse(fetched.updated_at));

  // Step 5: Negative - try non-existent boardId (valid UUID, not in DB)
  const nonExistBoardId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found for missing boardId")(() =>
    api.functional.polEcoBoard.admin.boards.at(connection, {
      boardId: nonExistBoardId,
    })
  );

  // Step 6: Negative - try with invalid UUID format
  TestValidator.error("validation error for bad UUID")(() =>
    api.functional.polEcoBoard.admin.boards.at(connection, {
      boardId: "bad-uuid-format" as any,
    })
  );

  // Step 7: Negative - try access as unauthenticated (non-admin)
  // Remove admin Authorization header to simulate non-admin
  const unauthorizedConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  TestValidator.error("forbidden for non-admin")(() =>
    api.functional.polEcoBoard.admin.boards.at(unauthorizedConn, { boardId: board.id })
  );
}

