import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostTag";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";

/**
 * E2E test for successfully erasing a tag from a member's post (member is post owner).
 *
 * This test ensures a member can remove a tag from their own post through the following flow:
 * 1. Register new member (collect their UUID).
 * 2. Create a board category as admin.
 * 3. Create a board in that category as admin.
 * 4. Create a post as the registered member in the created category.
 * 5. Create a new tag as admin (to be associated with the post).
 * 6. Assign this tag to the member's post via the appropriate member endpoint.
 * 7. Erase the tag-post assignment using the delete API.
 * 8. Validate the tag assignment is removed - check via business logic or API reflection where possible.
 * 9. Confirm the deletion is soft (i.e., for audit there's evidence of soft delete/audit trail if supported by API DTOs).
 *
 * If the platform doesn't provide a direct way to query current post-tag assignments, the absence of the deleted assignment is confirmed by other means, for example no error on re-assigning, or not appearing in listing. Documentation and comments must clarify how the absence of assignment is validated based on available API.
 */
export async function test_api_post_tag_member_erase_success(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberDisplayName: string = RandomGenerator.name();
  const memberPasswordHash: string = RandomGenerator.alphaNumeric(32);
  const memberConsentStatus: string = "v1";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPasswordHash,
      display_name: memberDisplayName,
      consent_status: memberConsentStatus,
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);
  // 2. Create a board category as admin
  const categoryName: string = RandomGenerator.alphabets(10);
  const categoryDescription: string = RandomGenerator.paragraph()();
  const categoryDisplayOrder: number = typia.random<number & tags.Type<"int32">>();
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: categoryDescription,
      display_order: categoryDisplayOrder,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);
  // 3. Create a board in that category as admin
  const boardName: string = RandomGenerator.alphabets(8);
  const boardCode: string = RandomGenerator.alphaNumeric(8).toLowerCase();
  const boardDisplayOrder: number = typia.random<number & tags.Type<"int32">>();
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardName,
      code: boardCode,
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: boardDisplayOrder,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);
  // 4. Create a post as the registered member in the created category
  const postTitle: string = RandomGenerator.alphaNumeric(15);
  const postBody: string = RandomGenerator.content()()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      body: postBody,
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);
  // 5. Create a tag as admin
  const tagName: string = (RandomGenerator.alphabets(6) + RandomGenerator.alphaNumeric(2));
  const tagSlug: string = tagName.toLowerCase().replace(/[^a-z0-9\-]+/g, "-").slice(0, 30);
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: tagName,
      slug: tagSlug,
      description: RandomGenerator.paragraph()(),
    } satisfies IPolEcoBoardTag.ICreate,
  });
  typia.assert(tag);
  // 6. Assign this tag to the member's post
  const postTag = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: { tag_id: tag.id } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(postTag);
  // 7. Erase the tag-post assignment
  await api.functional.polEcoBoard.member.posts.postTags.erase(connection, {
    postId: post.id,
    postTagId: postTag.id,
  });
  // 8. Validate the tag assignment is removed
  // NOTE: As the API does not provide a post-tag listing endpoint,
  //       we infer removal by attempting to re-assign the tag (should now succeed, not duplicate error)
  const postTagReassigned = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: { tag_id: tag.id } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(postTagReassigned);
}

