import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardModeratorBoardAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorBoardAssignment";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate creation of a moderator-board assignment by an admin.
 *
 * This test ensures an admin can create a valid assignment event linking a registered moderator to a board, including proper audit fields, assignment period, and optional rationale log.
 *
 * Steps:
 * 1. Register a new admin with unique credentials.
 * 2. Login as that admin for privileged endpoints.
 * 3. As admin, create a new board (with all required properties and random category id).
 * 4. Register a new moderator and capture their unique id.
 * 5. As admin, create a moderator-board assignment:
 *    - Reference valid moderator id, board id, assignment time (now), plus optional rational/log.
 *    - assigned_by_admin_id is omitted as admin id is not exposed in test context.
 * 6. Assert the assignment response has correct references, date fields, and all audit-type constraints.
 */
export async function test_api_moderator_board_assignment_creation_success(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create board (requires category id, use random uuid for test)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const boardCreateInput: IPolEcoBoardBoard.ICreate = {
    pol_eco_board_category_id: categoryId,
    name: RandomGenerator.paragraph()(2),
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
    description: RandomGenerator.paragraph()(1),
    is_public: true,
    is_archived: false,
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: boardCreateInput,
  });
  typia.assert(board);

  // 4. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1/accepted",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRes);
  const moderatorId = moderatorRes.moderatorId;

  // 5. Create moderator-board assignment
  const now = new Date().toISOString();
  const assignmentInput: IPolEcoBoardModeratorBoardAssignment.ICreate = {
    pol_eco_board_moderator_id: moderatorId,
    pol_eco_board_board_id: board.id,
    assigned_at: now,
    // No ended_at for active assignment
    role_transfer_log: RandomGenerator.paragraph()(),
    // assigned_by_admin_id is optional; omitting as current admin id is not available
  };
  const assignment = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.create(connection, {
    body: assignmentInput,
  });
  typia.assert(assignment);

  // 6. Assertions on returned assignment fields
  TestValidator.equals("moderator assignment moderator id")(assignment.pol_eco_board_moderator_id)(moderatorId);
  TestValidator.equals("moderator assignment board id")(assignment.pol_eco_board_board_id)(board.id);
  TestValidator.equals("moderator assignment assigned_at")(assignment.assigned_at)(now);
  if (assignment.role_transfer_log !== undefined && assignment.role_transfer_log !== null)
    TestValidator.equals("role_transfer_log")(assignment.role_transfer_log)(assignmentInput.role_transfer_log);
  TestValidator.predicate("assignment id is uuid")(!!assignment.id && assignment.id.length > 10);
  TestValidator.predicate("assignment created_at valid")(!!assignment.created_at && assignment.created_at.length > 10);
  TestValidator.predicate("assignment updated_at valid")(!!assignment.updated_at && assignment.updated_at.length > 10);
  TestValidator.equals("assignment ended_at is null or undefined")(assignment.ended_at)(undefined);
  TestValidator.equals("assignment deleted_at is null or undefined")(assignment.deleted_at)(undefined);
}

