/**
 * E2E test for the comment voting business flow on the polEcoBoard platform.
 *
 * - Validates that a registered and logged-in member can upvote/downvote a comment not written by themselves.
 * - Tests business logic constraints: the same member cannot vote twice on the same comment, and members cannot vote on their own comment.
 *
 * Steps:
 *   1. Register memberA (the voter), and login to get access.
 *   2. Register memberB (the content author), and login to get memberB's access.
 *   3. As memberB, create a post and add a comment (target comment).
 *   4. As memberA, login and upvote (vote_value=1) the comment (should succeed).
 *   5. As memberA, try to upvote the same comment again (should fail due to business rule for duplicate voting).
 *   6. As memberB, attempt to vote on their own comment (should fail).
 *   7. (No banned scenario test due to no such API in provided materials).
 *
 * The test validates success, duplicate prevention, and self-vote prevention by inspecting type assertions and expected error throws.
 */
export async function test_api_comment_vote_create_valid_and_duplicate_prevented(
  connection: api.IConnection,
) {
  // 1. Register memberA (the voter)
  const memberA_email: string = typia.random<string & tags.Format<"email">>();
  const memberA_password: string = typia.random<string & tags.Format<"password">>();
  const memberA_signup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberA_signup);

  // 2. Register memberB (the author)
  const memberB_email: string = typia.random<string & tags.Format<"email">>();
  const memberB_password: string = typia.random<string & tags.Format<"password">>();
  const memberB_signup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberB_signup);

  // 3. Login as memberB to create a post and comment
  const memberB_login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  typia.assert(memberB_login);

  // Create post as memberB
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(30),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // Create comment as memberB
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(5),
      parent_comment_id: null,
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Login as memberA to upvote the comment
  const memberA_login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });
  typia.assert(memberA_login);

  // Upvote with memberA (should succeed)
  const vote1 = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote1);
  TestValidator.equals("vote is correctly for this comment")(vote1.comment_id)(comment.id);
  TestValidator.equals("vote type is upvote")(vote1.vote_value)(1);

  // Try duplicate upvote (should fail)
  await TestValidator.error("duplicate vote should not be allowed")(
    async () => {
      await api.functional.polEcoBoard.member.comments.votes.create(connection, {
        commentId: comment.id,
        body: {
          vote_value: 1,
        } satisfies IPolEcoBoardVote.ICreate,
      });
    },
  );

  // 5. As memberB, try to vote their own comment (should fail)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  await TestValidator.error("author cannot vote on own comment")(
    async () => {
      await api.functional.polEcoBoard.member.comments.votes.create(connection, {
        commentId: comment.id,
        body: {
          vote_value: 1,
        } satisfies IPolEcoBoardVote.ICreate,
      });
    },
  );
}

