import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Verify that updating a comment report is forbidden for a member who did not create the report.
 *
 * This test ensures that only the member who created a report on a comment can update their submission.
 * The process involves registering and logging in two separate member accounts, creating a post and comment as Member A, having A file a report, and then confirming that Member B cannot update the report. The expected outcome is a permission-denied error when B attempts the update.
 *
 * Steps:
 * 1. Register Member A (the report owner).
 * 2. Log in as Member A.
 * 3. Create a post as Member A.
 * 4. Create a comment (to be reported) on that post as Member A.
 * 5. File a report on the comment as Member A.
 * 6. Register Member B (not the report owner).
 * 7. Log in as Member B.
 * 8. Try to update the report (created by A) as B: Expect permission error.
 */
export async function test_api_comment_report_update_forbidden_for_non_report_owner(connection: api.IConnection) {
  // 1. Register Member A
  const emailA = typia.random<string & tags.Format<"email">>();
  const passwordA = typia.random<string & tags.Format<"password">>();
  const signUpA = await api.functional.auth.member.register.signUp(connection, {
    body: { email: emailA, password: passwordA } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpA);

  // 2. Log in as Member A
  const loginA = await api.functional.auth.member.login.signIn(connection, {
    body: { email: emailA, password: passwordA } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(loginA);

  // 3. Create a post as Member A
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(10)(),
      tag_ids: [],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a comment on that post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(5),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. File a report on the comment
  const report = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: "abuse",
      reason_description: RandomGenerator.paragraph()(3),
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report);

  // 6. Register Member B
  const emailB = typia.random<string & tags.Format<"email">>();
  const passwordB = typia.random<string & tags.Format<"password">>();
  const signUpB = await api.functional.auth.member.register.signUp(connection, {
    body: { email: emailB, password: passwordB } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpB);

  // 7. Log in as Member B
  const loginB = await api.functional.auth.member.login.signIn(connection, {
    body: { email: emailB, password: passwordB } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(loginB);

  // 8. Try to update the report as Member B: expect permission denied
  await TestValidator.error("update as non-owner must fail")(async () => {
    await api.functional.polEcoBoard.member.comments.reports.update(connection, {
      commentId: comment.id,
      reportId: report.id,
      body: {
        reason_description: "Updated description by B",
      } satisfies IPolEcoBoardReport.IUpdate,
    });
