 * - All changes are tracked for compliance and incident management.
 *
 * Test workflow:
 * 1. Register a new admin using a unique business email and password.
 * 2. Log in as the newly created admin to obtain authentication for API calls.
 * 3. Create a new maintenance window (with valid input fields), capturing the generated maintenanceWindowId.
 * 4. Prepare update data: modify multiple updatable fields (e.g., change window_code, update start_time, end_time, expected_impact, notified_at).
 * 5. Call the update (PUT) API with the existing window id and new values.
 * 6. Assert the API response reflects all updated fields, with correct value application (including nullables/optionals if used).
 * 7. Confirm that update respects maintenance window policy: start_time is before end_time (if both present), and updated_at is refreshed.
 * 8. If other audit log or compliance features are visible in the response, validate they are correctly appended/updated.
 */
export async function test_api_maintenance_window_update_success(connection: api.IConnection) {
