  TestValidator.equals("start_time updated")(mwUpdateResp.start_time)(mwUpdateInfo.start_time ?? mwCreateInput.start_time);
  TestValidator.equals("end_time updated")(mwUpdateResp.end_time)(mwUpdateInfo.end_time ?? mwCreateInput.end_time);
  TestValidator.equals("expected_impact updated")(mwUpdateResp.expected_impact)(mwUpdateInfo.expected_impact ?? mwCreateInput.expected_impact);
  TestValidator.equals("actual_impact updated")(mwUpdateResp.actual_impact)(mwUpdateInfo.actual_impact ?? null);
  TestValidator.equals("notified_at updated")(mwUpdateResp.notified_at)(mwUpdateInfo.notified_at ?? null);
  TestValidator.predicate("start_time < end_time")(
    mwUpdateResp.end_time === null || mwUpdateResp.start_time < mwUpdateResp.end_time
  );
  TestValidator.notEquals("updated_at refreshed")(mwUpdateResp.updated_at)(mwCreateResp.updated_at);
  // Business rules: updated record must keep same id and window_code unique
  TestValidator.equals("id remains unchanged")(mwUpdateResp.id)(mwCreateResp.id);
  // If deleted_at and created_at can be checked/should persist:
  TestValidator.equals("created_at persists")(mwUpdateResp.created_at)(mwCreateResp.created_at);
}

