  const categoryInput = {
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(1),
    display_order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IPolEcoBoardCategory.ICreate;
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, { body: categoryInput });
  typia.assert(category);

  // 4. Create a board
  const boardInput = {
    pol_eco_board_category_id: category.id,
    name: RandomGenerator.paragraph()(1),
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
    description: RandomGenerator.paragraph()(1),
    is_public: true,
    is_archived: false,
    display_order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IPolEcoBoardBoard.ICreate;
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, { body: boardInput });
  typia.assert(board);

  // 5. Create a board status event
  const now = new Date().toISOString();
  const statusInput = {
    pol_eco_board_board_id: board.id,
