    reason: RandomGenerator.paragraph()(1),
  } satisfies IPolEcoBoardBoardStatus.ICreate;
  const boardStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, { body: statusInput });
  typia.assert(boardStatus);

  // 6. Retrieve board status detail by ID and verify
  const detail = await api.functional.polEcoBoard.admin.boardStatuses.at(connection, { boardStatusId: boardStatus.id });
  typia.assert(detail);

  // Structural checks
  TestValidator.equals("status id")(detail.id)(boardStatus.id);
  TestValidator.equals("board id")(detail.pol_eco_board_board_id)(board.id);
  TestValidator.equals("actor_admin_id")(detail.actor_admin_id)(boardStatus.actor_admin_id);
  TestValidator.equals("actor_moderator_id")(detail.actor_moderator_id)(boardStatus.actor_moderator_id);
  TestValidator.equals("status type")(detail.status_type)(boardStatus.status_type);
  TestValidator.equals("effective at")(detail.effective_at)(boardStatus.effective_at);
  TestValidator.equals("reason")(detail.reason)(boardStatus.reason);

  TestValidator.predicate("has created_at")(typeof detail.created_at === "string");
  TestValidator.predicate("has updated_at")(typeof detail.updated_at === "string");
