import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardExternalAuthProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardExternalAuthProvider";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin retrieval of external authentication provider details.
 *
 * This scenario tests that an authenticated admin can query for the full configuration and audit details of a single external authentication provider by its unique ID. It ensures that all contract fields—such as provider name, key, status, privacy link, jurisdiction, and compliance/consent flags—are present, valid, and correct, and that no personally identifying information or sensitive data is leaked in the response. Business edge cases include: requesting a nonexistent provider ID (should return not-found/business error), a soft-deleted provider (should show appropriate status or deleted_at), and enforcing that members/non-admins cannot access this endpoint (authorization error expected).
 *
 * Steps:
 * 1. Register a new admin and perform authentication (obtain token).
 * 2. Create a new external authentication provider via the admin endpoint, store its generated id.
 * 3. As authenticated admin, fetch the newly created provider by id and assert all properties are present, data matches creation, and no extra fields are present.
 * 4. Edge case: attempt to fetch a non-existent provider id (random uuid), ensure not-found error.
 * 5. (Optional, if delete is not implemented—simulate) Check behavior for "soft-deleted" provider: if deleted_at is not null, assert status/compliance is correct.
 * 6. Attempt access without admin authentication (simulate with connection lacking Authorization), assert authorization is rejected.
 */
export async function test_api_external_auth_provider_admin_get_by_id(connection: api.IConnection) {
  // 1. Admin registration
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create provider
  const createInput: IPolEcoBoardExternalAuthProvider.ICreate = {
    provider_name: "Test SSO",
    provider_key: "test_sso_" + Date.now().toString(),
    status: "enabled",
    privacy_policy_uri: "https://www.example.com/privacy",
    data_residency_region: "US",
    consent_required: true,
  };
  const created = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
    body: createInput,
  });
  typia.assert(created);
  TestValidator.equals("provider_name matches")(created.provider_name)(createInput.provider_name);
  TestValidator.equals("provider_key matches")(created.provider_key)(createInput.provider_key);
  TestValidator.equals("status matches")(created.status)(createInput.status);
  TestValidator.equals("privacy_policy_uri matches")(created.privacy_policy_uri)(createInput.privacy_policy_uri);
  TestValidator.equals("data_residency_region matches")(created.data_residency_region)(createInput.data_residency_region);
  TestValidator.equals("consent_required matches")(created.consent_required)(createInput.consent_required);
  TestValidator.predicate("has UUID id")(!!created.id && created.id.length > 0);
  TestValidator.predicate("created_at present")(!!created.created_at);
  TestValidator.predicate("updated_at present")(!!created.updated_at);
  TestValidator.equals("not soft deleted")(created.deleted_at)(null);

  // 4. Admin can fetch the provider by id
  const fetched = await api.functional.polEcoBoard.admin.externalAuthProviders.at(connection, {
    externalAuthProviderId: created.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id matches")(fetched.id)(created.id);
  TestValidator.equals("provider_name matches")(fetched.provider_name)(createInput.provider_name);
  TestValidator.equals("provider_key matches")(fetched.provider_key)(createInput.provider_key);
  TestValidator.equals("status matches")(fetched.status)(createInput.status);
  TestValidator.equals("privacy_policy_uri matches")(fetched.privacy_policy_uri)(createInput.privacy_policy_uri);
  TestValidator.equals("data_residency_region matches")(fetched.data_residency_region)(createInput.data_residency_region);
  TestValidator.equals("consent_required matches")(fetched.consent_required)(createInput.consent_required);
  TestValidator.equals("not soft deleted")(fetched.deleted_at)(null);

  // 5. Fetch with nonexistent id (should not be found, expect error)
  TestValidator.error("fetching nonexistent provider returns error")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.at(connection, {
      externalAuthProviderId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 6. Attempt fetch without admin (simulate no Authorization header)
  // Clone connection but clear Authorization
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers?.Authorization;
  TestValidator.error("unauthorized access is rejected")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.at(noAuthConnection, {
      externalAuthProviderId: created.id,
    });
  });
}

