import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test access denial and error cases for admin-restricted guest session detail view.
 *
 * This test verifies that the API endpoint for retrieving guest session details via /polEcoBoard/admin/guests/{guestId}
 * properly enforces security and error handling requirements when accessed with:
 * - No admin authentication
 * - An invalid/expired/forged JWT admin token
 * - A valid admin account but non-existent guestId
 *
 * Steps:
 * 1. Register a dummy admin account (for use with valid and invalid login scenarios)
 * 2. Obtain a valid admin JWT token via login
 * 3. Attempt to access a guest session with a completely random (non-existent) guestId using valid JWT => should return not found (404 or similar)
 * 4. Attempt to access with a random/forged token (setting connection.headers.Authorization manually) => should be rejected (401 Unauthorized or similar)
 * 5. Remove JWT authorization entirely and attempt the call => should be rejected (401/403)
 *
 * The test asserts that no sensitive information about guest sessions is leaked in error responses.
 */
export async function test_api_guest_session_detail_admin_unauthorized_or_not_found(
  connection: api.IConnection,
) {
  // Step 1. Register dummy admin for negative permission scenarios
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // Step 2. Login to obtain a valid admin JWT token
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginResp);
  const validJwt = loginResp.setHeaders.Authorization;

  // Step 3. Attempt: valid admin JWT, non-existent guestId (should be NotFound)
  const validJwtConn = { ...connection, headers: { ...connection.headers, Authorization: validJwt } };
  await TestValidator.error("random guestId returns not found")(() =>
    api.functional.polEcoBoard.admin.guests.at(validJwtConn, {
      guestId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // Step 4. Attempt: forged/invalid JWT (should be Unauthorized)
  const forgedJwtConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalid.jwt.token" } };
  await TestValidator.error("forged JWT should be unauthorized")(() =>
    api.functional.polEcoBoard.admin.guests.at(forgedJwtConn, {
      guestId: typia.random<string & tags.Format<"uuid">>()
    })
  );

  // Step 5. Attempt: no Authorization header (should be Unauthorized/Forbidden)
  const { Authorization, ...headersWithoutAuth } = connection.headers ?? {};
  const noJwtConn = { ...connection, headers: headersWithoutAuth };
  await TestValidator.error("no auth header should be denied")(() =>
    api.functional.polEcoBoard.admin.guests.at(noJwtConn, {
      guestId: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

