  // Step 6: Field validation: Invalid status_type (not in allowed enum)
  await TestValidator.error("invalid status_type should be rejected")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: board.id,
        actor_moderator_id: moderatorId,
        status_type: "notarealstatus" as any, // invalid enum value
        effective_at: now,
        reason: "Invalid status_type.",
      } as any,
    })
  );

  // Step 7: Missing reason (optional, should be allowed)
  const statusNoReason = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: moderatorId,
      status_type: "open",
      effective_at: now,
      // reason is intentionally omitted (should be allowed)
    },
  });
  typia.assert(statusNoReason);
  TestValidator.equals("board id matches for no reason")(statusNoReason.pol_eco_board_board_id)(board.id);

  // Step 8: Reference non-existent board
  await TestValidator.error("referencing non-existent board should be rejected")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: typia.random<string & tags.Format<"uuid">>(),
        actor_moderator_id: moderatorId,
        status_type: "locked",
        effective_at: now,
        reason: "Non-existent board reference.",
      },
    })
  );

  // Step 9: Attempt forbidden/unauthenticated usage (simulate logout by clearing Authorization)
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized should be forbidden")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(unauthConn, {
      body: statusPayload,
    })
  );
}

