/**
 * Validate the admin moderator search endpoint with privilege and filter edge cases.
 *
 * This test ensures that:
 * - Only admin roles can search moderators - access is denied to others
 * - Filtering by appointed date, status, and privilege works
 * - Empty search results return valid pagination output
 * - Pagination metadata is correct
 *
 * Steps:
 * 1. Register admin and log in
 * 2. Register at least one moderator (for valid data presence)
 * 3. As admin, search with general filter (should see at least 1 moderator)
 * 4. Filter by member_id: should return only matching moderator
 * 5. Filter by is_active = true: should return only active moderators (should include the one just registered)
 * 6. Filter by appointed_at_from and appointed_at_to window: should return at least the new moderator (if within window)
 * 7. Use a bogus appointed_at_from far in the future: expect empty result, check pagination structure remains correct
 * 8. As moderator, attempt the search – confirm access denied (permission error)
 */
export async function test_api_admin_moderator_search_with_filters_and_no_results(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AaBb!1234567";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Log in as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "BbCc!9876543";
  const moderatorDisplay = RandomGenerator.name();
  const consentStatus = "consented:" + new Date().toISOString();
  const moderatorResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplay,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorResp);

  // 4. As admin, search with default (no filters) to see at least one moderator
  const result1 = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(result1);
  TestValidator.predicate("there is at least one moderator account")(result1.data.length >= 1);

  // 5. Filter by member_id (should match single moderator)
  const result2 = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      member_id: moderatorResp.moderatorId,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(result2);
  TestValidator.equals("filtered by member_id")(result2.data.length)(1);
  TestValidator.equals("moderator id matches")(result2.data[0].member_id)(moderatorResp.moderatorId);

  // 6. Filter by is_active=true (should return our moderator)
  const result3 = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      is_active: true,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(result3);
  TestValidator.predicate("active moderators count >= 1")(result3.data.length >= 1);

  // 7. Filter by appointed_at_from = now - should include just-registered moderator (if implementation supports)
  const now = new Date().toISOString();
  const result4 = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      appointed_at_from: now,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(result4);
  // This may be empty if appointed_at has earlier timestamp, so we just check pagination shape
  typia.assert(result4.pagination);
  typia.assert(result4.data);

  // 8. Filter with appointed_at_from in the far future (expect empty result)
  const result5 = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      appointed_at_from: "2100-01-01T00:00:00.000Z",
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(result5);
  TestValidator.equals("empty result when filter matches none")(result5.data.length)(0);
  typia.assert(result5.pagination);

  // 9. Switch to moderator: log in using moderator token
  connection.headers = { ...connection.headers, Authorization: moderatorResp.setHeaders.Authorization };

  // 10. Try admin search as NON-admin: should fail with permission-denied error
  await TestValidator.error("moderator cannot perform admin moderator search")(async () => {
    await api.functional.polEcoBoard.admin.moderators.search(connection, {
      body: { } as IPolEcoBoardModerator.IRequest,
    });
  });
}

