/**
 * Validate that an admin can update mutable fields on a comment edit record (such as the edit reason) for full audit trail compliance.
 *
 * Scenario:
 * 1. Register a member – for post and comment authorship
 * 2. Register an admin – who will conduct the comment edit update
 * 3. Login as admin to obtain credentials for privileged endpoints
 * 4. Member creates a post
 * 5. Member adds a comment to that post
 * 6. Admin creates a comment edit record for the member's comment
 * 7. Admin updates the edit reason on that comment edit record using the admin update (PUT) endpoint
 * 8. Validate that the updated reason is reflected in the response and that audit-relevant fields (timestamps, editor ID) remain correct
 */
export async function test_api_comment_edit_admin_correct_fields(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestPw1234!!";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 2. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestAdmin123!";
  const adminSignUp = await api.functional.auth.admin.register.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 3. Login as admin for future privileged operations
  const adminSignIn = await api.functional.auth.admin.login.post(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // 4. Member creates a post (simulate switching to member session)
  connection.headers = { Authorization: memberSignUp.setHeaders.Authorization };
  const postCreate = await api.functional.polEcoBoard.member.posts.post(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()(1)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postCreate);

  // 5. Member adds a comment to the post
  const commentCreate = await api.functional.polEcoBoard.member.posts.comments.postByPostid(connection, {
    postId: postCreate.id,
    body: {
      body: RandomGenerator.paragraph()(3),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentCreate);

  // 6. Admin creates a comment edit record for this comment (switch session to admin)
  connection.headers = { Authorization: adminSignUp.setHeaders.Authorization };
  const commentEditCreate = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.postByPostidAndCommentid(connection, {
