    commentId: commentCreate.id,
    body: {
      edit_body: RandomGenerator.paragraph()(4),
      edit_reason: "Initial input for moderation",
    } satisfies IPolEcoBoardCommentEdit.ICreate,
  });
  typia.assert(commentEditCreate);

  // 7. Admin updates the edit reason on the comment edit record
  const updatedReason = "Updated rationale for audit compliance.";
  const commentEditUpdate = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.putByPostidAndCommentidAndCommenteditid(connection, {
    postId: postCreate.id,
    commentId: commentCreate.id,
    commentEditId: commentEditCreate.id,
    body: {
      edit_reason: updatedReason,
    } satisfies IPolEcoBoardCommentEdit.IUpdate,
  });
  typia.assert(commentEditUpdate);
  TestValidator.equals("edit_reason updated")(commentEditUpdate.edit_reason)(updatedReason);
  TestValidator.equals("edited record id matches")(commentEditUpdate.id)(commentEditCreate.id);
  TestValidator.equals("comment id matches")(commentEditUpdate.comment_id)(commentEditCreate.comment_id);
  // 8. Optionally check audit fields timestamp or editor_member_id consistency if desired
}

