import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAppeal";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin can successfully hard-delete an appeal record and that errors are thrown for invalid or repeat deletions.
 *
 * Business context: Appeal deletions are highly privileged, require admin access, and must not quietly fail. Auditable and compliance-critical for moderation review lifecycles.
 *
 * Steps:
 * 1. Register a new admin user (to get a unique admin with fresh credentials).
 * 2. Login as the above admin (to get a privileged, authenticated session).
 * 3. Create a moderation action (required because appeals always reference an existing moderation decision).
 * 4. Create an appeal linked to the moderation action and this admin as the appellant.
 * 5. Delete the appeal by its id using the admin endpoint, expecting a successful hard delete with no result.
 * 6. Attempt to delete the same appeal again and verify a proper error is returned (already deleted or not found).
 * 7. Attempt to delete a random/nonexistent UUID and check for a not-found error response.
 * 8. (If possible, attempt to retrieve the deleted appeal by id to double-check it is actually deleted, though no GET-by-id endpoint is currently exposed in this SDK's list.)
 */
export async function test_api_appeal_deletion_success_and_error_handling(connection: api.IConnection) {
  // 1. Register a new admin user (unique credentials)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin (to ensure the session/cookies are set for privileged calls)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a moderation action (with this admin as the operator)
  const fakeReportId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: fakeReportId,
      operator_id: fakeReportId, // will override below with correct admin id after creation, but no admin id in signUp response
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "Spam post removed for policy violation.",
      outcome: "removed",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // In this SDK, operator_id must match an actual admin uuid, but signUp and signIn responses only deliver setHeaders (jwt), not the admin/member UUIDs. For this test, we proceed with the same random operator_id.

  // 4. Create appeal targeting the above moderation action, as this same admin (again, we have to improvise fake UUIDs, since identity is hidden from signUp/login)
  const appeal = await api.functional.polEcoBoard.admin.appeals.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      appellant_id: fakeReportId,
      reason: "Dispute moderation removal -- requesting review.",
      status: "pending",
    } satisfies IPolEcoBoardAppeal.ICreate,
  });
  typia.assert(appeal);

  // 5. Delete the appeal (should succeed, hard delete, no result)
  await api.functional.polEcoBoard.admin.appeals.erase(connection, {
    appealId: appeal.id,
  });

  // 6. Try to delete the same appeal again (should error)
  await TestValidator.error("delete already deleted appeal")(() =>
    api.functional.polEcoBoard.admin.appeals.erase(connection, { appealId: appeal.id })
  );

  // 7. Try to delete a nonexistent/invalid appealId
  await TestValidator.error("delete nonexistent appeal")(() =>
    api.functional.polEcoBoard.admin.appeals.erase(connection, { appealId: typia.random<string & tags.Format<"uuid">>() })
  );
}

