 *
 * Steps:
 * 1. Register a new admin user.
 * 2. Log in as that admin.
 * 3. Create a moderation action (using a new random report_id, operator_id).
 * 4. Submit an appeal for this moderation action (as admin/appellant).
 * 5. Attempt to submit a duplicate appeal for the same moderation action by the same admin, expecting rejection.
 */
export async function test_api_admin_appeal_creation_duplicate_policy(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphabets(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as the new admin (tokens will be set in connection automatically)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a moderation action (simulate as if the operator is the new admin)
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: admin_id,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: RandomGenerator.paragraph(1)(),
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 4. Submit an appeal for this moderation action (where appellant is that admin)
  const appeal = await api.functional.polEcoBoard.admin.appeals.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      appellant_id: admin_id,
      reason: RandomGenerator.paragraph(1)(),
      status: "pending",
    } satisfies IPolEcoBoardAppeal.ICreate,
  });
  typia.assert(appeal);

  // 5. Attempt to create a duplicate appeal for the same moderation action/appellant - must fail
  await TestValidator.error("admin duplicate appeal is rejected")(() =>
    api.functional.polEcoBoard.admin.appeals.create(connection, {
      body: {
        moderation_action_id: moderationAction.id,
        appellant_id: admin_id,
        reason: RandomGenerator.paragraph(1)(),
        status: "pending",
      } satisfies IPolEcoBoardAppeal.ICreate,
    })
  );
}

