import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can fetch their own notification preference and, if possible, also retrieve notification preferences for another member.
 *
 * Test steps:
 * 1. Register a new moderator using random registration data and confirm the moderatorId, email, and display_name are returned (registration provides Authorization header in setHeaders).
 * 2. Login as the moderator (repeat authorization flow with same credentials to exercise login endpoint and obtain Authorization).
 * 3. Create a notification preference for the moderator (use the moderator's id for member_id in the preference, randomize event_type and channel, opt_in=true/false).
 * 4. Retrieve the notification preference by its id using moderator privileges. Validate the retrieved object matches what was created (member_id, event_type, channel, opt_in, timestamps).
 * 5. Create a second notification preference for a different (synthetic) member (random uuid for member_id, new event_type/channel, opt_in=random).
 * 6. As moderator, attempt to fetch this second preference by its id. (Depending on business rules, this may throw if unauthorized—validate either successful fetch or the correct error behavior, but do not test TypeScript type errors.)
 */
export async function test_api_notification_preference_moderator_get_own_or_member(connection: api.IConnection) {
  // 1. Register a new moderator and get details (including Authorization header)
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestPassword123!";
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v2025.01.01"; // Assume some platform required consent version or status string
  const regResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    }
  });
  typia.assert(regResp);
  TestValidator.equals("moderator email")(regResp.email)(moderatorEmail);
  TestValidator.equals("moderator display_name")(regResp.display_name)(moderatorDisplayName);

  // 2. Login as the moderator to ensure Authorization is obtained/set
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    }
  });
  typia.assert(loginResp);
  TestValidator.equals("login email matches")(loginResp.email)(moderatorEmail);

  // 3. Create a notification preference for the moderator
  const notificationEventType1 = "reply";
  const notificationChannel1 = "email";
  const optIn1 = true;
  const prefResp1 = await api.functional.polEcoBoard.moderator.notificationPreferences.create(connection, {
    body: {
      member_id: regResp.moderatorId,
      event_type: notificationEventType1,
      channel: notificationChannel1,
      opt_in: optIn1,
    }
  });
  typia.assert(prefResp1);
  TestValidator.equals("preference member_id matches")(prefResp1.member_id)(regResp.moderatorId);
  TestValidator.equals("preference event_type matches")(prefResp1.event_type)(notificationEventType1);
  TestValidator.equals("preference channel matches")(prefResp1.channel)(notificationChannel1);
  TestValidator.equals("preference opt_in matches")(prefResp1.opt_in)(optIn1);

