  TestValidator.predicate("created_at is date string")(!isNaN(Date.parse(eventResp.created_at)));
  // id must be a uuid string
  TestValidator.predicate("eventResp.id is uuid-like")(typeof eventResp.id === "string" && eventResp.id.length > 20);

