  });

  // 5. Try create with negative score
  await TestValidator.error("negative score should fail")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, { body: { ...validEvent, score: -1.0 } });
  });
  // Try create with score > 1
  await TestValidator.error("overflow score should fail")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, { body: { ...validEvent, score: 2.23 } });
  });

  // 6. Try create as non-admin (simulate anonymous)
  const anonConnection = { ...connection, headers: { ...connection.headers } };
  delete anonConnection.headers.Authorization;
  await TestValidator.error("non-admin access not allowed")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.create(anonConnection, { body: validEvent });
  });
}

