  const fetched = await api.functional.polEcoBoard.admin.comments.reports.at(connection, {
    commentId: comment.id,
    reportId: report.id,
  });
  typia.assert(fetched);
  // Validate all critical fields match
  TestValidator.equals("report id")(fetched.id)(report.id);
  TestValidator.equals("comment id")(fetched.comment_id)(report.comment_id);
  TestValidator.equals("reason_code")(fetched.reason_code)(report.reason_code);
  TestValidator.equals("reason_description")(fetched.reason_description)(report.reason_description);
  TestValidator.equals("reporter_member_id")(fetched.reporter_member_id)(report.reporter_member_id);
  TestValidator.equals("created_at")(fetched.created_at)(report.created_at);

