  await TestValidator.error("not found reportId")(() =>
    api.functional.polEcoBoard.admin.comments.reports.at(connection, {
      commentId: comment.id,
      reportId: typia.random<string & tags.Format<"uuid">>(), // random unassociated report
    }),
  );

