import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Verify admin-driven soft-deletion of board status events and compliance with audit and retention business rules.
 *
 * This test ensures that an admin user can soft-delete (archive) a board status event and that business logic behaves as expected:
 *
 * 1. Registers and logs in as an admin, yielding privileged session.
 * 2. Creates a category and a discussion board as prerequisites.
 * 3. Records a new board status event (with this admin as the actor).
 * 4. Issues DELETE for the new status event (should archive via deleted_at—not physical removal).
 * 5. Checks that deleted_at has been set (by making additional status event, verifying new event not affected, and comparing outcomes).
 * 6. Attempts duplicate deletion on the same status id (should yield a business error).
 * 7. Attempts deletion of a non-existent boardStatusId (should yield a not-found/business error).
 *
 * Note: Non-admin actor simulation is omitted, as user/moderator auth APIs are unavailable in current E2E surface.
 */
export async function test_api_board_status_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin to ensure token set (redundant if signUp sets, but double-check for strictness)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create a board in that category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(2),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Create a board status event (admin as actor)
  const boardStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: null, // Will be system-resolved based on token
      status_type: "visible",
      effective_at: new Date().toISOString(),
      reason: RandomGenerator.paragraph()(),
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(boardStatus);
  TestValidator.equals("not deleted initially")(boardStatus.deleted_at)(null);

  // 6. Soft-delete the board status event
  await api.functional.polEcoBoard.admin.boardStatuses.erase(connection, {
    boardStatusId: boardStatus.id,
  });

  // 7. Confirm status is now deleted (simulate by making new status, ensure old id not re-used, etc.)
  // Since we can't query the deleted record, create another status to show system allows others
  const boardStatusAfter = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
