  TestValidator.equals("total pages")(emptyListRes.pagination.pages)(0);
  TestValidator.equals("current page")(emptyListRes.pagination.current)(1);
  // Check limit is default or matches supplied
  TestValidator.predicate("limit default or matches supplied")(typeof emptyListRes.pagination.limit === "number" && emptyListRes.pagination.limit > 0 && emptyListRes.pagination.limit <= 100);

