  TestValidator.equals("filtered: record count")(filteredRes.pagination.records)(0);
  TestValidator.equals("filtered: total pages")(filteredRes.pagination.pages)(0);

  // 5. Optionally check pagination with explicit page/limit, still expecting zero-results
  const pagedRes = await api.functional.polEcoBoard.admin.categories.search(connection, {
    body: {
