  });
  typia.assert(member);

  // 2. Authenticate the member (login)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn
  });

  // 3. Create a moderator action referencing a report
  const fakeReportId = typia.random<string & tags.Format<"uuid">>();
  const fakeOperatorId = typia.random<string & tags.Format<"uuid">>(); // Simulate staff
  const actionType = "warn";
  const targetType = "user";
  const status = "completed";
  const rationale = "Policy breach";
  const outcome = "actioned";
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
