      status: appealStatus,
    } satisfies IPolEcoBoardAppeal.ICreate
  });
  typia.assert(appeal);

  // 5. Validate returned appeal fields
  TestValidator.equals("moderation_action_id links moderation action")(appeal.moderation_action_id)(moderationAction.id);
  TestValidator.equals("appellant_id matches member")(appeal.appellant_id)(member.id);
  TestValidator.equals("reason matches input")(appeal.reason)(appealReason);
  TestValidator.equals("status pending")(appeal.status)(appealStatus);
  TestValidator.predicate("has UUID id")(/^([0-9a-fA-F]{8}\-){4}[0-9a-fA-F]{12}$/.test(appeal.id));
  TestValidator.predicate("created_at is ISO timestamp")(new Date(appeal.created_at).toString() !== "Invalid Date");
  TestValidator.predicate("updated_at is ISO timestamp")(new Date(appeal.updated_at).toString() !== "Invalid Date");
