 *
 * Business context:
 * Only admins can register business reports. Registration requires a valid business admin account and authentication via JWT. All fields (report_code, report_type, status, content_uri, requested_by, triggered/delivery timestamps, etc.) must be valid and properly linked. After creation, the inserted report must be retrievable and persistently stored, with all fields matching initial submission.
 *
 * Step-by-step workflow:
 * 1. Register a new admin account (with unique email/password)
 * 2. Login as the new admin (obtain JWT, ensure session/headers are set)
 * 3. Create a business report using valid field values (including referencing the admin's id as requested_by_id)
 * 4. Validate the returned report record matches the request, including all mandatory fields (id, status, timestamps, codes, etc.)
 * 5. (If retrieval function existed in API, fetch and reconfirm values persisted; with current materials, only assert creation output matches requirements)
 */
export async function test_api_business_report_creation_success(connection: api.IConnection){
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a business report with the admin's info
  // As we don't know the admin's UUID directly, and it's needed for requested_by_id, assume platform returns the UUID in the session but with current DTOs only setHeaders are available.
  // For type safety, we'll use a valid uuid for requested_by_id for this E2E (as email/association validation is out of current scope without an admin lookup).
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const reportReq: IPolEcoBoardBusinessReport.ICreate = {
    report_code: "BR-" + typia.random<string>().slice(0,8),
    report_type: "METRICS",
    status: "PENDING",
    requested_by_id: adminId,
    content_uri: "https://storage.example.com/" + typia.random<string>().slice(0,16),
    triggered_at: now,
    delivered_at: null,
    failure_reason: null,
  };
  const reportResp = await api.functional.polEcoBoard.admin.businessReports.create(connection, { body: reportReq });
  typia.assert(reportResp);

  // 4. Validation: Check response fields correspond with request for critical fields
  TestValidator.equals("report_code")(reportResp.report_code)(reportReq.report_code);
  TestValidator.equals("report_type")(reportResp.report_type)(reportReq.report_type);
  TestValidator.equals("status")(reportResp.status)(reportReq.status);
  TestValidator.equals("requested_by_id")(reportResp.requested_by_id)(reportReq.requested_by_id);
  TestValidator.equals("content_uri")(reportResp.content_uri)(reportReq.content_uri);
  TestValidator.equals("triggered_at")(reportResp.triggered_at)(reportReq.triggered_at);
  TestValidator.equals("delivered_at")(reportResp.delivered_at)(reportReq.delivered_at);
  TestValidator.equals("failure_reason")(reportResp.failure_reason)(reportReq.failure_reason);
  // Check mandatory ids and timestamps present
  TestValidator.predicate("business report id is valid uuid")(!!reportResp.id && typeof reportResp.id === "string");
  TestValidator.predicate("created_at is date-time")(!!reportResp.created_at && typeof reportResp.created_at === "string");
  TestValidator.predicate("updated_at is date-time")(!!reportResp.updated_at && typeof reportResp.updated_at === "string");
