import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test successful soft deletion of a comment by a moderator.
 *
 * This test validates the moderation workflow for soft-deleting a comment. It covers the following process:
 * 1. Register a new member (for authoring the post and comment)
 * 2. Register a new moderator (who will perform the deletion)
 * 3. Member creates a post
 * 4. Member creates a comment on that post
 * 5. Moderator logs in
 * 6. Moderator soft-deletes the comment
 *
 * It then checks:
 * - The comment's deleted_at is set after deletion
 * - The comment was not deleted before the operation
 * - The flagged property is set to true (moderator flagging)
 *
 * Steps about the comment disappearing from listings or audit log validation are omitted as the API does not provide endpoints for such verification.
 */
export async function test_api_comment_moderator_delete_success(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "StrongPassw0rd!";
  const memberSignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberSignUpResult);
  // Set member token for authenticated actions
  connection.headers = { ...connection.headers, ...memberSignUpResult.setHeaders };

  // 2. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "ModeratorPassw0rd!";
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "consent_v1.0";
  const moderatorSignUpResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    },
  });
  typia.assert(moderatorSignUpResult);

  // 3. Member creates a post
  const postBody = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1, 2),
    body: RandomGenerator.content()()(1, 2),
    tag_ids: [],
    attachments: [],
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postBody,
  });
  typia.assert(post);

  // 4. Member creates a comment
  const commentBody = {
    body: "This is a comment to be deleted.",
    parent_comment_id: null,
  };
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: commentBody,
  });
  typia.assert(comment);
  TestValidator.equals("deleted_at before deletion")(comment.deleted_at)(null);

  // 5. Moderator logs in
  const modLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(modLogin);
  connection.headers = { ...connection.headers, ...modLogin.setHeaders };

  // 6. Moderator soft-deletes the comment
  const deletedComment = await api.functional.polEcoBoard.moderator.posts.comments.erase(connection, {
    postId: post.id,
    commentId: comment.id,
  });
  typia.assert(deletedComment);
  TestValidator.predicate("deleted_at set after moderator delete")(typeof deletedComment.deleted_at === "string" && !!deletedComment.deleted_at);
  TestValidator.equals("flagged after moderation")(deletedComment.flagged)(true);
}

