import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationFailure";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test successful soft deletion of a notification failure by admin.
 *
 * This test validates the full workflow for an admin to soft-delete a notification failure record in the polEcoBoard system.
 * It confirms that the deletion sets the deleted_at field, preserves the record for audit/compliance, but makes it inaccessible to non-admin roles.
 *
 * Steps:
 * 1. Register a new admin account (with unique business email and password).
 * 2. Log in as that admin to establish an authenticated session (tokens set in connection).
 * 3. Create a new notification failure record using the admin session.
 * 4. Delete (soft-delete) the notification failure record using its id via the admin-only endpoint.
 * 5. (Validate via SDK call—if supported) Confirm the record's deleted_at is set (if record can be queried as admin).
 * 6. (Validate by business logic/code comment) Confirm that non-admin queries would not return the deleted record and that the record remains in the database for audit/compliance (as per business requirements).
 */
export async function test_api_notification_failure_soft_delete_by_admin(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });

  // 2. Log in as this admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });

  // 3. Create a new notification failure record
  const notificationFailure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: {
      notification_id: typia.random<string & tags.Format<"uuid">>(),
      provider_id: null,
      failure_code: "SMTP_TIMEOUT",
      failure_message: "The SMTP provider did not respond within the expected timeframe.",
      occurred_at: new Date().toISOString(),
      resolution_status: "pending"
    }
  });
  typia.assert(notificationFailure);

  // 4. Soft delete (mark as deleted_at) this notification failure
  await api.functional.polEcoBoard.admin.notificationFailures.erase(connection, {
    notificationFailureId: notificationFailure.id
  });

  // 5. (If API supports read as admin) Currently, there is no public SDK/API to re-query deleted failures for their deleted_at value.
  //    If available, you would fetch and assert deleted_at is a valid date-time string.

  // 6. By business workflow: After soft delete, record is hidden from non-admin queries but retained for audits.
  //    This E2E test ensures admin-driven deletion logic per contract.
}

