import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAnalyticsEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAnalyticsEvent";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for updating an analytics event as an admin
 *
 * 1. Register and log in as a new admin (ensures test isolation)
 * 2. Create a new analytics event (capture the id)
 * 3. Update at least one mutable field (event_type, event_details, user_role, region) with valid data and verify changes
 * 4. Ensure audit fields (created_at) are not mutable (attempt update, check ignored/unchanged)
 * 5. Attempt update with invalid analyticsEventId (format and non-existent id) and expect validation/error response
 * 6. Attempt update with invalid/unsupported values for fields and expect validation/error response
 * 7. Logout admin/authenticate as a non-admin (simulate token removal), attempt update, expect forbidden error
 */
export async function test_api_analytics_events_update_admin(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create new analytics event
  const createBody: IPolEcoBoardAnalyticsEvent.ICreate = {
    event_type: "page_view",
    session_anon_id: RandomGenerator.alphaNumeric(16),
    user_role: "member",
    event_details: JSON.stringify({ page: "dashboard" }),
    region: "US",
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: IPolEcoBoardAnalyticsEvent = await api.functional.polEcoBoard.admin.analyticsEvents.create(connection, { body: createBody });
  typia.assert(created);

  // 4. Update an allowed field and verify changes
  const updateBody: IPolEcoBoardAnalyticsEvent.IUpdate = {
    event_type: "login",
    event_details: JSON.stringify({ method: "social", page: "dashboard" }),
    region: "EU",
    user_role: "admin",
  };
  const updated: IPolEcoBoardAnalyticsEvent = await api.functional.polEcoBoard.admin.analyticsEvents.update(connection, {
    analyticsEventId: created.id,
    body: updateBody,
  });
  typia.assert(updated);
  TestValidator.equals("event_type updated")(updated.event_type)(updateBody.event_type);
  TestValidator.equals("event_details updated")(updated.event_details)(updateBody.event_details);
  TestValidator.equals("region updated")(updated.region)(updateBody.region);
  TestValidator.equals("user_role updated")(updated.user_role)(updateBody.user_role);
  // Audit: created_at remains unchanged
  TestValidator.equals("created_at immutable")(updated.created_at)(created.created_at);

  // 5. Attempt updating immutable field (created_at) -- should be ignored
  const tryImmutableUpdate: IPolEcoBoardAnalyticsEvent.IUpdate = {
    event_type: "page_view",
    user_role: "guest",
    event_details: JSON.stringify({ page: "ignore-test" }),
    region: "KR",
    // created_at field is not allowed in IUpdate, compiler prevents inclusion
  };
  const immutableChecked: IPolEcoBoardAnalyticsEvent = await api.functional.polEcoBoard.admin.analyticsEvents.update(connection, {
    analyticsEventId: created.id,
    body: tryImmutableUpdate,
  });
  typia.assert(immutableChecked);
  // created_at should remain unchanged
  TestValidator.equals("created_at remains unchanged")(immutableChecked.created_at)(created.created_at);

  // 6. Invalid analyticsEventId (bad format)
  await TestValidator.error("invalid format analyticsEventId")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.update(connection, {
      analyticsEventId: "not-a-uuid" as string & tags.Format<"uuid">,
      body: updateBody,
    })
  );
  // Non-existent id (valid uuid, but not found)
  await TestValidator.error("non-existent analyticsEventId")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.update(connection, {
      analyticsEventId: typia.random<string & tags.Format<"uuid">>(),
      body: updateBody,
    })
  );
  // 7. Invalid payload (empty body)
  await TestValidator.error("empty update body fails")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.update(connection, {
      analyticsEventId: created.id,
      body: {},
    })
  );
  // 8. Invalid/unsupported field value
  await TestValidator.error("invalid region format")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.update(connection, {
      analyticsEventId: created.id,
      body: { region: "" },
    })
  );

  // 9. Attempt non-admin/unauthorized access (simulate logout by clearing Authorization)
  const prevAuth = connection.headers?.Authorization;
  if (connection.headers) delete connection.headers.Authorization;
  await TestValidator.error("unauthorized update fails")(() =>
    api.functional.polEcoBoard.admin.analyticsEvents.update(connection, {
      analyticsEventId: created.id,
      body: updateBody,
    })
  );
  // Restore admin Authorization for consistent state
  if (connection.headers) connection.headers.Authorization = prevAuth;
}

