import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test: Admin comment report search/filter endpoint with advanced filters & error handling
 *
 * This function validates the search and filter functionality for admin users on comment abuse/activity reports, covering success, empty, and error scenarios, including role enforcement.
 *
 * Steps:
 * 1. Register a new admin and perform admin login; capture any JWT/header handling for token propagation.
 * 2. As a normal (non-admin) member, create a post, then a comment under that post.
 * 3. As a member, file at least two abuse reports against the comment, using different reason_code values and descriptions.
 * 4. As admin, use the search API to:
 *    a. Retrieve all reports for the comment with no filters (should see all reports)
 *    b. Search by reason_code, by reporter_member_id, by date range, pagination, etc. (checking filter logic)
 *    c. Use filter values that should result in empty result sets (nonexistent reporter, unassigned reason code, time range with no matches)
 *    d. Attempt to search with invalid commentId (synthetic UUID)
 *    e. (If infra/SDK allows) as a non-admin, attempt to access (should fail with error/forbidden)
 *
 * 5. Assert that all result pages/displayed info contains only expected & correctly filtered report summaries: check metadata match, counts, etc.
 * 6. Confirm errors returned for unauthorized or bad input cases.
 */
export async function test_api_comment_report_search_by_admin_with_advanced_filters(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResponse);

  // 2. Create a member post & comment (assume member session is current connection)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1, 1),
      body: RandomGenerator.content()(1, 1)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "Test comment for abuse reports.",
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. File two abuse reports with different reason_codes
  const report1 = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: "abuse",
      reason_description: "Obvious spam",
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report1);

  const report2 = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: "spam",
      reason_description: "Repeated posts",
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report2);

  // 4a. Admin: get all reports (no filters)
  const resultAll = await api.functional.polEcoBoard.admin.comments.reports.search(connection, {
    commentId: comment.id,
    body: {},
  });
  typia.assert(resultAll);
  TestValidator.predicate("should list at least two reports for the comment")(
    Array.isArray(resultAll) ? resultAll.length >= 2 : Boolean((resultAll as any)?.data?.length >= 2)
  );

  // 4b. Filter by reason_code
  const resultAbuse = await api.functional.polEcoBoard.admin.comments.reports.search(connection, {
    commentId: comment.id,
    body: { reason_code: "abuse" },
  });
  typia.assert(resultAbuse);
  TestValidator.predicate("contains only the abuse report")(
    Array.isArray(resultAbuse)
      ? resultAbuse.every((r) => r.reason_code === "abuse")
      : Boolean((resultAbuse as any)?.data?.every?.((r: any) => r.reason_code === "abuse"))
  );

  // 4c. Filter by random reporter (should be empty)
  const fakeReporterId = typia.random<string & tags.Format<"uuid">>();
  const resultFakeReporter = await api.functional.polEcoBoard.admin.comments.reports.search(connection, {
    commentId: comment.id,
    body: { reporter_member_id: fakeReporterId },
  });
  typia.assert(resultFakeReporter);
  TestValidator.predicate("empty result for non-existent reporter")(
    Array.isArray(resultFakeReporter)
      ? resultFakeReporter.length === 0
      : Boolean(!(resultFakeReporter as any)?.data?.length)
  );

  // 4d. Invalid commentId (should error)
  await TestValidator.error("invalid commentId should error")(
    async () => {
      await api.functional.polEcoBoard.admin.comments.reports.search(connection, {
        commentId: typia.random<string & tags.Format<"uuid">>(),
        body: {},
      });
    }
  );

  // 4e. (Role enforcement forbidden): For actual forbidden test, would switch to non-admin, then call, and check error forbidden.
  // This is not performed due to limited role/session switching support in basic infra/test harness.
}

