/**
 * Validate search, filter, pagination and permission on maintenance window listing as admin.
 *
 * 1. Register a new admin with unique email and password.
 * 2. Log in as that admin to ensure authenticated session (JWT in connection header).
 * 3. Create multiple maintenance window records with a variety of window_codes and time windows (e.g., different start and end times, some with null/ongoing end_time, some past, some future).
 * 4. Search with no filters: check created records are returned and pagination info present.
 * 5. Search filtering by window_code, expected_impact substring, and time range — verify only appropriate records are returned.
 * 6. Paginate results (if record count exceeds default pagination) and check ability to retrieve correct pages.
 * 7. (Negative) Test: search with valid filter yielding no result — ensure empty data list.
 * 8. (Negative) Test: use clearly invalid filter types/syntax (e.g., page=-1, limit too high), expect error/thrown.
 * 9. (Negative) Test: search as unauthenticated user (no JWT) — expect access denied error.
 */
export async function test_api_maintenance_window_search_filter_pagination(connection: api.IConnection) {
  // Register a new admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // Create 3 maintenance windows (distinct codes, impacts, times)
  const now = new Date();
  const created: IPolEcoBoardMaintenanceWindow[] = [];
  for (let i = 0; i < 3; ++i) {
    const mw = await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
      body: {
        window_code: `MAINT_${now.getFullYear()}${now.getMonth() + 1}${now.getDate()}_${i}`,
        start_time: new Date(now.getTime() + i * 24 * 3600 * 1000).toISOString(),
        end_time: new Date(now.getTime() + (i+1) * 24 * 3600 * 1000).toISOString(),
        expected_impact: i % 2 === 0 ? "service degradation" : "platform offline",
        notified_at: null,
      } satisfies IPolEcoBoardMaintenanceWindow.ICreate,
    });
    created.push(mw);
  }

  // 1) Search with no filters
  const search1 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: {} satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search1);
  TestValidator.predicate("all created windows returned")(created.every(c => search1.data.some(d => d.id === c.id)));
  TestValidator.predicate("pagination info present")(!!search1.pagination && typeof search1.pagination.pages === "number");

  // 2) Filter by window_code
  const codeToFilter = created[1].window_code;
  const search2 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { window_code: codeToFilter } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search2);
  TestValidator.equals("single filtered record")(search2.data.length)(1);
  TestValidator.equals("matching code")(search2.data[0].window_code)(codeToFilter);

  // 3) Filter by expected_impact substring
  const search3 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { expected_impact: "degradation" } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search3);
  TestValidator.predicate("at least one matches expected_impact")(search3.data.some(w => w.expected_impact.includes("degradation")));

  // 4) Time-range filtering
  const timeFrom = created[1].start_time;
  const timeTo = created[2].end_time!;
  const search4 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { start_time_from: timeFrom, start_time_to: timeTo } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search4);
  TestValidator.predicate("time range subset present")(search4.data.every(w => w.start_time >= timeFrom && w.start_time <= timeTo));

  // 5) Pagination - force small page size (limit = 1)
  const search5 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { page: 1, limit: 1 } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search5);
  TestValidator.equals("first page size is 1")(search5.data.length)(1);
  TestValidator.equals("page=1")(search5.pagination.current)(1);
  if (search5.pagination.pages > 1) {
    const search5b = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
      body: { page: 2, limit: 1 } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
    });
    typia.assert(search5b);
    TestValidator.equals("page=2")(search5b.pagination.current)(2);
    TestValidator.equals("page size 1")(search5b.data.length)(1);
  }

  // 6) Negative: filter matching nothing (nonsense code)
  const search6 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { window_code: "NON_EXIST_CODE" } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search6);
  TestValidator.equals("empty result for nonsense code")(search6.data.length)(0);

  // 7) Negative: invalid filter values (page=-1, limit=99999)
  await TestValidator.error("invalid negative page error")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
      body: { page: -1 } as any,
    });
  });
  await TestValidator.error("excessive limit error")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
      body: { limit: 99999 } as any,
    });
  });

  // 8) Negative: unauthenticated search (clear Authorization header)
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthorized without JWT")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.search(unauthConn, { body: {} });
  });
}

