    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginOutput);
  // (SDK connection will now have the admin token)

  // 3. Create a moderation action as this admin
  const reportId = typia.random<string & tags.Format<"uuid">>();
