import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for updating a discussion board (admin privilege required)
 *
 * This test function validates the update operation on a discussion board, focusing on:
 * - Admin registration and login for authorization
 * - Category and board creation for prerequisites
 * - Updating the board with valid data (success)
 * - Uniqueness and reference constraint violations (failures)
 * - Permission enforcement and not-found logic
 *
 * Steps:
 * 1. Register and sign in as admin
 * 2. Create two categories
 * 3. Create a board in the first category
 * 4. Update the board with valid data: switch to 2nd category, change name/code, etc.
 * 5. Confirm response updates
 * 6. Attempt to update with duplicate name/code (should fail)
 * 7. Attempt to update with invalid category id (should fail)
 * 8. Attempt to update with missing required fields (should fail)
 * 9. Attempt to update with a non-existent boardId (should fail/not found)
 * 10. Attempt to update as non-admin (should fail/permission error)
 */
export async function test_api_board_update_success_and_failure_cases(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create two categories
  const category1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: "Category for success update",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category1);

  const category2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: "Category for switch during update",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category2);

  // 4. Create a board in category1
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category1.id,
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: "Test board for update e2e",
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Update the board with new info (SUCCESS)
  const updatedName = board.name + "-updated";
  const updatedCode = board.code + "_u";
  const updateRes = await api.functional.polEcoBoard.admin.boards.update(connection, {
    boardId: board.id,
    body: {
      pol_eco_board_category_id: category2.id,
      name: updatedName,
      code: updatedCode,
      description: "Updated description",
      is_public: false,
      is_archived: true,
      display_order: 2,
    } satisfies IPolEcoBoardBoard.IUpdate,
  });
  typia.assert(updateRes);
  TestValidator.equals("update pol_eco_board_category_id")(updateRes.pol_eco_board_category_id)(category2.id);
  TestValidator.equals("update name")(updateRes.name)(updatedName);
  TestValidator.equals("update code")(updateRes.code)(updatedCode);
  TestValidator.equals("update description")(updateRes.description)("Updated description");
  TestValidator.equals("is_public")(updateRes.is_public)(false);
  TestValidator.equals("is_archived")(updateRes.is_archived)(true);
  TestValidator.equals("display_order")(updateRes.display_order)(2);

  // 6. Attempt to update board using a duplicate name and duplicate code (should FAIL on uniqueness)
  const secondBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category2.id,
      name: RandomGenerator.alphaNumeric(7) + "_b2",
      code: RandomGenerator.alphaNumeric(8).toLowerCase() + "_b2",
      description: "Second board for duplication",
      is_public: true,
      is_archived: false,
      display_order: 3,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(secondBoard);

  // Try duplicate name:
  await TestValidator.error("duplicate board name should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: secondBoard.id,
      body: {
        name: updatedName, // Same as board1's new name
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });
  // Try duplicate code:
  await TestValidator.error("duplicate board code should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: secondBoard.id,
      body: {
        code: updatedCode, // Same as board1's new code
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });

  // 7. Attempt to update with invalid categoryId (referential integrity)
  const invalidCatId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("invalid category id for update should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: board.id,
      body: {
        pol_eco_board_category_id: invalidCatId,
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });

  // 8. Attempt update with missing required fields (should fail)
