    body: {
      pol_eco_board_category_id: category1.id,
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: "Test board for update e2e",
      is_public: true,
      is_archived: false,
      display_order: 1,
