 */
export async function test_api_appeal_search_moderator_role_pagination_success(connection: api.IConnection) {
  // 1. Register as moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestP@ss123!";
  const displayName = RandomGenerator.name();
  const consentStatus = "latest-policy-2024";
  const regRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(regRes);

  // 2. Login as moderator to ensure JWT issued and user session set correctly
  const loginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginRes);

  // 3. Create at least 2 appeals for reproducible test queries
  const modActionId1 = typia.random<string & tags.Format<"uuid">>();
  const modActionId2 = typia.random<string & tags.Format<"uuid">>();
  const modId = regRes.moderatorId;
