  const appeal1 = await api.functional.polEcoBoard.moderator.appeals.create(connection, {
    body: {
      moderation_action_id: modActionId1,
      appellant_id: modId,
      reason: "First sample appeal for moderation test.",
      status: "pending",
    } satisfies IPolEcoBoardAppeal.ICreate,
