  const paged = await api.functional.polEcoBoard.moderator.appeals.index(connection, {
    body: { page: 1, limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("pagination: one item per page")(paged.data.length)(1);
  TestValidator.equals("pagination: page should be 1")(paged.pagination.current)(1);
  TestValidator.equals("pagination: limit should be 1")(paged.pagination.limit)(1);

  // 6. Filter by status: pending (should only match appeal1)
  const statusRes = await api.functional.polEcoBoard.moderator.appeals.index(connection, {
    body: { status: "pending" },
  });
  typia.assert(statusRes);
  TestValidator.predicate("should only find first appeal")(
    statusRes.data.length === 1 && statusRes.data[0].id === appeal1.id
  );

