import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can retrieve any vote record by postId and voteId.
 *
 * Business context: This test ensures that admin-level API permissions allow retrieving any vote record for any post, regardless of the voting user. It must also confirm that non-admins cannot do so, and that proper error handling occurs for invalid identifiers.
 *
 * Steps:
 * 1. Register and login an admin account.
 * 2. Register and login two member accounts.
 * 3. As member1, create a post.
 * 4. As member1 and member2, each cast a vote on the post (cover both upvote/downvote).
 * 5. As admin, retrieve both votes using the admin endpoint and confirm full access/details for both votes.
 * 6. As admin, attempt to retrieve a non-existent vote and confirm error response occurs.
 * 7. As a regular member (non-admin), attempt to retrieve a vote using the admin endpoint and verify access is denied.
 */
export async function test_api_post_vote_admin_retrieve_any_vote_permissions(connection: api.IConnection) {
  // Helper functions for switching identity
  async function admin_register_and_login(email: string, password: string) {
    // Register
    const reg = await api.functional.auth.admin.register.signUp(connection, {
      body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
    });
    typia.assert(reg);
    // Login
    const login = await api.functional.auth.admin.login.signIn(connection, {
      body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
    });
    typia.assert(login);
    // Set token
    connection.headers = { ...(connection.headers ?? {}), Authorization: login.setHeaders.Authorization };
  }

  async function member_register_and_login(email: string, password: string) {
    const reg = await api.functional.auth.member.register.signUp(connection, {
      body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
    });
    typia.assert(reg);
    // Login
    const login = await api.functional.auth.member.login.signIn(connection, {
      body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
    });
    typia.assert(login);
    connection.headers = { ...(connection.headers ?? {}), Authorization: login.setHeaders.Authorization };
  }

  // 1. Register and login an admin
  const admin_email = typia.random<string & tags.Format<"email">>();
  const admin_password = RandomGenerator.alphaNumeric(12);
  await admin_register_and_login(admin_email, admin_password);

  // 2. Register and login two members
  const member1_email = typia.random<string & tags.Format<"email">>();
  const member2_email = typia.random<string & tags.Format<"email">>();
  const member1_password = RandomGenerator.alphaNumeric(12);
  const member2_password = RandomGenerator.alphaNumeric(12);

  await member_register_and_login(member1_email, member1_password);
  // Keep to get author_member_id of member1
  // 3. As member1, create a post
  const category_id = typia.random<string & tags.Format<"uuid">>(); // Use random category_id
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(2),
      // Optionals left blank
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);
  // Save member1 id to confirm in votes later
  const member1_id = post.author_member_id;

  // 4. As member1, cast a vote (upvote)
  const vote1 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote1);

  // As member2, log in and cast a vote (downvote)
  await member_register_and_login(member2_email, member2_password);
  const vote2 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: -1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote2);
  const member2_id = vote2.voter_member_id;

  // 5. As admin, log in and retrieve both votes
  await admin_register_and_login(admin_email, admin_password);
  for (const vote of [vote1, vote2]) {
    const found = await api.functional.polEcoBoard.admin.posts.votes.at(connection, {
      postId: post.id,
      voteId: vote.id,
    });
    typia.assert(found);
    // All fields match expected
    TestValidator.equals("vote id matches")(found.id)(vote.id);
    TestValidator.equals("post id")(found.post_id)(post.id);
    TestValidator.equals("vote value")(found.vote_value)(vote.vote_value);
    TestValidator.equals("voter")(typeof found.voter_member_id)("string");
    TestValidator.equals("created_at present")(
      typeof found.created_at === "string" && !!found.created_at
    )(true);
  }

  // 6. As admin, try to get a non-existent vote id
  const invalid_vote_id = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("non-existent vote id returns error")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.at(connection, {
      postId: post.id,
      voteId: invalid_vote_id,
    });
  });

  // 7. As a non-admin (member1), attempt admin endpoint to read vote (should be denied)
  await member_register_and_login(member1_email, member1_password);
  TestValidator.error("non-admin forbidden to access admin vote endpoint")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.at(connection, {
      postId: post.id,
      voteId: vote1.id,
    });
  });
}

