import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can retrieve full details of a specific moderation audit record and that access is denied for non-moderator roles or invalid input cases.
 *
 * Business context: This is required to ensure audit trail visibility for compliance and transparency purposes, and to prevent data leaks to unauthorized users. The workflow validates successful retrieval as a moderator, missing/invalid audit records, and forbidden access for non-moderators.
 *
 * Steps:
 * 1. Register a new moderator (moderator A).
 * 2. Log in as moderator A to get credentials.
 * 3. Create a moderation action using moderator A account.
 * 4. Add an audit record to the moderation action, with moderator A as the auditor, including unique state snapshots and rationale.
 * 5. Retrieve the audit record using the moderation action ID and audit ID. Validate all audit fields (IDs, rationale, timestamps, snapshots, audit/admin linkage).
 * 6. Attempt to fetch an audit with a non-existent auditId or moderationActionId and confirm error is thrown for not found.
 * 7. Register/login as another new moderator (moderator B) and validate that audit record is still accessible (since the endpoint checks moderator role, not owner).
 * 8. (Negative) Remove/modifier authentication (simulate non-moderator), fetch should be forbidden.
 */
export async function test_api_moderation_action_audit_detail_view_as_moderator(connection: api.IConnection) {
  // 1. Register moderator
  const emailA: string = typia.random<string & tags.Format<"email">>();
  const passwordA = "SecureTestPassword123!";
  const moderatorA = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: emailA,
      password: passwordA,
      display_name: RandomGenerator.name(),
      consent_status: "agree-latest-privacy-policy-V1"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorA);

  // 2. Login as moderator (set JWT in connection)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: emailA,
      password: passwordA
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  // No assertion needed; Authorization header is set on connection

  // 3. Create moderation action
  const action = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: moderatorA.moderatorId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: RandomGenerator.paragraph()(),
      outcome: "accepted"
    } satisfies IPolEcoBoardModerationAction.ICreate
  });
  typia.assert(action);

  // 4. Add an audit record to the moderation action
  const audit = await api.functional.polEcoBoard.moderator.moderationActions.audits.create(connection, {
    moderationActionId: action.id,
    body: {
      moderation_action_id: action.id,
      auditor_id: moderatorA.moderatorId,
      pre_state_snapshot: JSON.stringify({ status: "pending" }),
      post_state_snapshot: JSON.stringify({ status: action.status }),
      reason: RandomGenerator.paragraph()()
    } satisfies IPolEcoBoardModerationAudit.ICreate
  });
  typia.assert(audit);

  // 5. Retrieve the audit record and check all data integrity
  const detail = await api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
    moderationActionId: action.id,
    auditId: audit.id
  });
  typia.assert(detail);
  TestValidator.equals("audit id matches")(detail.id)(audit.id);
  TestValidator.equals("moderation_action_id matches")(detail.moderation_action_id)(action.id);
  TestValidator.equals("auditor_id matches")(detail.auditor_id)(moderatorA.moderatorId);
  TestValidator.equals("pre_state_snapshot matches")(detail.pre_state_snapshot)(audit.pre_state_snapshot);
  TestValidator.equals("post_state_snapshot matches")(detail.post_state_snapshot)(audit.post_state_snapshot);
  TestValidator.equals("reason matches")(detail.reason)(audit.reason);

  // 6. Attempt to fetch with a wrong auditId (should throw)
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found for non-existent auditId")(() =>
    api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
      moderationActionId: action.id,
      auditId: nonExistentId
    })
  );

  // 7. Register as a different moderator (B), audit still allowed
  const emailB: string = typia.random<string & tags.Format<"email">>();
  const passwordB = "DifferentPassword456!";
  const moderatorB = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: emailB,
      password: passwordB,
      display_name: RandomGenerator.name(),
      consent_status: "agree-latest-privacy-policy-V1"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorB);

  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: emailB,
      password: passwordB
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  // Audit is visible to any moderator
  const detailByOther = await api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
    moderationActionId: action.id,
    auditId: audit.id
  });
  typia.assert(detailByOther);
  TestValidator.equals("visible to other moderator")(detailByOther.id)(audit.id);

  // 8. Remove Authorization (simulate non-moderator) and check forbidden
  connection.headers = { ...connection.headers, Authorization: undefined };
  TestValidator.error("forbidden for anon/non-moderator")(() =>
    api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
      moderationActionId: action.id,
      auditId: audit.id
    })
  );
}

