    },
  });
  typia.assert(signInRes);

  // 3. Create several categories for filter/pagination
  const randomPrefix = RandomGenerator.alphabets(8);
  const categories: IPolEcoBoardCategory[] = [];
  for (let i = 0; i < 5; ++i) {
    const name = `${randomPrefix}-cat-${i}`;
    const description = i % 2 === 0 ? `Info-${randomPrefix}-${i}` : null;
    const display_order = i + 1;
    const res = await api.functional.polEcoBoard.admin.categories.create(connection, {
      body: {
        name,
        description,
        display_order,
      },
    });
    typia.assert(res);
    categories.push(res);
