  TestValidator.equals('Display order ascending')(displayedOrders)(sorted);

  // 10. All returned fields present/accurate for all categories in test set
  for (const sample of testSetReturned) {
    TestValidator.predicate('Field: id')(!!sample.id && typeof sample.id === 'string');
    TestValidator.predicate('Field: name')(!!sample.name && typeof sample.name === 'string');
    TestValidator.predicate('Field: display_order')(typeof sample.display_order === 'number');
    TestValidator.predicate('Field: created_at')(!!sample.created_at && typeof sample.created_at === 'string');
    TestValidator.predicate('Field: updated_at')(!!sample.updated_at && typeof sample.updated_at === 'string');
    TestValidator.predicate('Field: description')(
      typeof sample.description === 'string' || sample.description === null || sample.description === undefined
    );
  }

  // 11. Pagination metadata validity
  TestValidator.predicate('Total records ≥ categories')(orderCheck.pagination.records >= testSetReturned.length);
  TestValidator.predicate('Pages ≥ 1')(orderCheck.pagination.pages >= 1);
}

