import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test that an admin can upvote and downvote any existing post, enforcing all relevant business rules.
 *
 * Business context:
 * Admins may cast upvotes (1) or downvotes (-1) on posts they do not author, as part of board moderation and engagement analytics. The system must forbid duplicate voting (multiple upvotes/downvotes by same admin on the same post) and must prevent voting on one's own authored post if this logic is enforced for admins.
 *
 * Test workflow:
 * 1. Register and login as an admin user. Save email/password for switching sessions as needed.
 * 2. Register a member user and login as member.
 * 3. Create a valid post as the member user.
 * 4. Switch back to admin session (re-login as admin to ensure header/state).
 * 5. Submit an upvote (vote_value = 1) on the post as admin.
 *    - Assert success, response is a valid vote with value +1 and matches post id.
 * 6. Submit a downvote (vote_value = -1) on the same post as admin (which business logic may treat as a distinct vote, or may convert the vote).
 *    - Assert success or business logic as expected. Response is a valid vote with value -1 if the action is allowed, or enforced business logic error.
 * 7. Attempt to upvote or downvote again on the same post as admin (should be forbidden; assert error).
 * 8. (Optional) If admin authors a post themselves, attempt to vote on it; assert forbidden if business rule applies.
 */
export async function test_api_post_vote_creation_admin_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 4. Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postCreate = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(15),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postCreate);
  const postId = postCreate.id;

  // 6. Re-login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Cast upvote as admin
  const upvote = await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(upvote);
  TestValidator.equals("upvote: matches postId")(upvote.post_id)(postId);
  TestValidator.equals("upvote: admin voted")(upvote.vote_value)(1);

  // 8. Cast downvote as admin
  const downvote = await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: -1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(downvote);
  TestValidator.equals("downvote: matches postId")(downvote.post_id)(postId);
  TestValidator.equals("downvote: admin downvoted")(downvote.vote_value)(-1);

  // 9. Attempt duplicate upvote as admin should fail
  await TestValidator.error("duplicate upvote forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });

  // 10. Attempt duplicate downvote as admin should fail
  await TestValidator.error("duplicate downvote forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId,
      body: {
        vote_value: -1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });

  // 11. (Optional/Edge) Admin tries to post and vote on own post (if not forbidden, this step can be skipped)
  const adminPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(15),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(adminPost);
  await TestValidator.error("admin voting on own post forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId: adminPost.id,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });
}

