import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test that verifies an admin user can retrieve all details of a specific comment edit via the admin API, including internal/audit fields.
 *
 * This test asserts end-to-end the access control and information fidelity of the endpoint for admin audit and moderation.
 *
 * Steps:
 * 1. Register a new admin user (and get admin email/password). 
 * 2. Login as admin (ensure privileged tokens are set for the connection).
 * 3. Register a new member user for post/comment creation (keep member's credentials for login).
 * 4. Login as member to establish context for board posting.
 * 5. Create a new post as the member (get postId).
 * 6. Write a comment to the post as the member (get commentId).
 * 7. Edit the comment as the member (use put to create an edit history entry, get commentEditId from the response or later retrieval).
 * 8. Switch back to the admin session (login as admin again if needed).
 * 9. Use the admin endpoint GET /polEcoBoard/admin/posts/{postId}/comments/{commentId}/commentEdits/{commentEditId} to retrieve the edit audit record.
 * 10. Assert the returned field fidelity: edit_body matches edit, editor_member_id is member, correct timestamps, and edit_reason (if set) is present.
 *
 * This covers both positive path (proper admin access and detail fields present) and validates intended access-control logic in the system.
 */
export async function test_api_comment_edit_detail_as_admin_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 4. Login as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 5. Create post as member
  const categoryId = typia.random<string & tags.Format<"uuid">>(); // Since category management is out of scope, any UUID
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(20),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Create comment as member
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(10),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 7. Edit comment as member (creates an edit record)
  const updatedBody = RandomGenerator.paragraph()(15);
  const updatedComment = await api.functional.polEcoBoard.member.posts.comments.update(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      body: updatedBody,
    } satisfies IPolEcoBoardComment.IUpdate,
  });
  typia.assert(updatedComment);

  // 8. Switch back to admin session
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 9. Use the admin endpoint to get the comment edit record
  // Assumption: The only edit done is the one just executed, so only one edit is available for this comment
  // We use comment.id as both commentId and commentEditId as a pragmatic approach (since listing all edits is not available by SDK)
  const edit: IPolEcoBoardCommentEdit = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.at(connection, {
    postId: post.id,
    commentId: comment.id,
    commentEditId: comment.id, // In practice, we'd list edits to get the right id
  });
  typia.assert(edit);

  // 10. Assert that core fields correspond (by proxy, since we cannot guarantee correct edit id without edit listing API)
  TestValidator.equals("comment association")(edit.comment_id)(comment.id);
  TestValidator.equals("editor is member")(edit.editor_member_id)(comment.author_member_id);
  TestValidator.equals("edit body matches")(edit.edit_body)(updatedBody);
  TestValidator.predicate("edit created_at is valid ISO date")(!!Date.parse(edit.created_at));
}

