import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate failure scenarios for updating a tag in the polEcoBoard admin tag system.
 *
 * This test ensures that:
 * 1. Invalid update payloads (empty name, invalid slug, missing all updatable fields) are rejected as failures.
 * 2. Attempting to update a non-existent tag (random tagId) fails as expected.
 * 3. Update attempts without proper admin privilege or with invalid/absent JWT token are rejected.
 *
 * The test covers business rule enforcement and access control for the tag update endpoint, ensuring robust error handling and security policy adherence.
 *
 * Steps:
 * 1. Register a new admin and login for an authenticated connection.
 * 2. Create a new tag to serve as the update target.
 * 3. Validate input payload failures:
 *    - Update with empty name (length < 3),
 *    - invalid slug (not URL safe or too short),
 *    - missing all updatable fields (body is {}),
 *    - empty slug (length < 3).
 * 4. Attempt to update a valid tagId with a random non-existent UUID as tagId (should fail).
 * 5. Attempt to update an existing tagId with an unauthenticated/invalid token connection (should fail).
 * 6. Attempt to update with a valid user (not admin) credential, if possible. (Omitted if not applicable).
 * 7. Confirm that appropriate errors are thrown and that no invalid updates are accepted.
 */
export async function test_api_tag_update_invalid_input_and_permissions(connection: api.IConnection) {
  // 1. Register a new admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin to authenticate the connection (ensure JWT is attached)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a tag as the valid admin
  const tagCreate: IPolEcoBoardTag.ICreate = {
    name: "Valid Tag",
    slug: "valid-tag",
    description: "A tag for testing update errors.",
  };
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, { body: tagCreate });
  typia.assert(tag);

  // 4. Try invalid update payloads
  const invalidName = ""; // Too short
  const invalidSlug = "not valid slug!"; // Contains spaces/illegal chars
  const tooShortSlug = "x";
  const updateScenarios = [
    { name: invalidName },
    { slug: invalidSlug },
    { slug: tooShortSlug },
    {},
    { name: "ok", slug: "" },
  ];
  for (const body of updateScenarios) {
    await TestValidator.error(`invalid payload: ${JSON.stringify(body)}`)(async () => {
      await api.functional.polEcoBoard.admin.tags.update(connection, {
        tagId: tag.id,
        body: body as IPolEcoBoardTag.IUpdate,
      });
    });
  }

  // 5. Try updating a non-existent tagId
  const nonExistentTagId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update non-existent tagId")(async () => {
    await api.functional.polEcoBoard.admin.tags.update(connection, {
      tagId: nonExistentTagId,
      body: { name: "Some Name" },
    });
  });

  // 6. Logout/remove admin JWT: simulate unauthenticated/invalid token call
  // Remove the Authorization header
  const unauthenticatedConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete unauthenticatedConnection.headers?.Authorization;
  await TestValidator.error("unauthenticated request fails")(async () => {
    await api.functional.polEcoBoard.admin.tags.update(unauthenticatedConnection, {
      tagId: tag.id,
      body: { name: "Should not succeed" },
    });
  });
  // Test with an invalid JWT
  const invalidJwtConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}), Authorization: "Bearer invalid.jwt.token" },
  };
  await TestValidator.error("invalid JWT fails")(async () => {
    await api.functional.polEcoBoard.admin.tags.update(invalidJwtConnection, {
      tagId: tag.id,
      body: { slug: "should-not-succeed" },
    });
  });
}

