import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the ability for a moderator to soft-delete (archive) a board status event record for a discussion board.
 *
 * Test setup:
 * 1. Register a new admin account and login to set up system prerequisites.
 * 2. As admin, create a new category and a new board within that category.
 * 3. Register a new moderator account and login to acquire privileges.
 * 4. As moderator, create a board status event (of type 'archived') for the previously created board.
 *
 * Test workflow:
 * 5. As moderator, invoke board status deletion API for the boardStatusId just created.
 * 6. Confirm deletion by probing audit/compliance: (a) API does not allow the status to appear on active queries; (b) deleted_at is set to non-null for the deleted event; (c) subsequent attempts to delete same boardStatusId returns business error; (d) deleting a random (nonexistent) UUID gives error.
 * 7. Verify compliance that delete action is only allowed for the actor who has privileges (moderator or admin).
 */
export async function test_api_board_status_soft_delete_by_moderator(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  // 2. Admin login (authorization setup)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  // 3. Create category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.alphaNumeric(30),
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(category);
  // 4. Create board for that category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.alphaNumeric(25),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(board);

  // 5. Moderator registration
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "modPass123!";
  const modDisplayName = RandomGenerator.alphabets(8);
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: "accepted-latest-tos",
    },
  });
  // 6. Moderator login
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    },
  });
  // 7. Moderator creates board status event
  const status = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: null, // null means resolved with token
      actor_admin_id: null,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "Soft-archive scenario setup",
    },
  });
  typia.assert(status);

  // 8. Moderator deletes status
  await api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
    boardStatusId: status.id,
  });
  // 9. PROBE: Attempt to delete again should error
  await TestValidator.error("Board status already deleted fails")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: status.id,
    })
  );
  // 10. PROBE: Attempt to delete a random UUID should error
  await TestValidator.error("Deleting nonexistent board status fails")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

