import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the ability for a moderator to soft-delete (archive) a board status event record for a discussion board.
 *
 * Business rationale:
 * - Moderators should be able to archive (soft-delete) board status events for compliance and operational reversibility, but only on events they have privileges for.
 * - System must strictly mark the record as deleted (set `deleted_at`) without removing from the audit trail.
 * - Subsequent deletion attempts for the same or nonexistent events must raise errors.
 *
 * Step-by-step process:
 * 1. Register a new admin and login to allow privileged category/board creation.
 * 2. As admin: Create a new category and a board in that category.
 * 3. Register a moderator and login as that moderator.
 * 4. As moderator: Create a board status event for that board.
 * 5. Soft-delete the status event (main action).
 * 6. Verify deletion by checking:
 *    a) Second delete call fails (already deleted)
 *    b) Deleting a random nonexistent status also fails
 */
export async function test_api_board_status_soft_delete_by_moderator(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login (to authorize board/category creation)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a new category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.alphaNumeric(30),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create a board under this category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.alphaNumeric(25),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Register a moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "modPass123!";
  const modDisplayName = RandomGenerator.alphabets(8);
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: "accepted-latest-tos",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });

  // 6. Moderator login
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 7. Moderator creates a board status event (archived)
  const status = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: null, // Provided by JWT; only moderator can act here
      actor_admin_id: null,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "Setup for soft-delete test.",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(status);

  // 8. Invoke soft-delete (archive) as moderator
  await api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
    boardStatusId: status.id,
  });

  // 9. Attempt to delete again should fail (already deleted)
  await TestValidator.error("already deleted / double delete")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: status.id,
    })
  );

  // 10. Attempt to delete a random/unknown boardStatusId should fail
  await TestValidator.error("delete nonexistent boardStatusId")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

