import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can retrieve the full list of comments for a post, including flagged and soft-deleted comments, confirming privileged visibility and correct filtering logic.
 *
 * This test simulates a realistic moderation workflow – from fresh registration and login as a moderator, to creating a test board category, board, and post, to generating several comments, some of which are later soft-deleted by the moderator to simulate moderation edge cases. The test then uses the PATCH operation as the moderator to fetch the post's comments with filters for flagged/deleted status, and checks that both ordinary and privileged (flagged, deleted) comment records are properly included in the result.
 *
 * Step-by-step process:
 * 1. Register a new moderator (fresh credentials)
 * 2. Log in as the moderator (obtain moderator session)
 * 3. Create a new board category as the moderator
 * 4. Create a board inside the category as the moderator
 * 5. Create a new post on the board as a member (assume member privileges can be obtained, otherwise simulate as mod for test isolation)
 * 6. Add several comments (by different members or repeat – at least 3), e.g. one normal, one to be flagged, one to be deleted
 * 7. As moderator, soft-delete one of the comments (simulate flagged if possible; otherwise, test only deleted and normal states)
 * 8. As moderator, use PATCH postId/comments with filters:
 *    - flagged: true/false/null (for full coverage)
 *    - include_deleted: true (must include deleted comments in moderation view)
 * 9. Assert the returned comments array includes all expected comments: normal, flagged, and (soft-)deleted.
 * 10. Clean up (optional)
 */
export async function test_api_moderator_comment_list_with_flagged_and_deleted(connection: api.IConnection) {
  // 1. Moderator registration
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "TestP@ssw0rd";
  const modDisplayName = RandomGenerator.name();
  const modConsentStatus = "v1.0";
  const modRegRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: modConsentStatus,
    }
  });
  typia.assert(modRegRes);

  // 2. Moderator login
  const modLoginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    }
  });
  typia.assert(modLoginRes);

  // 3. Create a new board category
  const categoryRes = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "Moderation E2E Category " + RandomGenerator.alphaNumeric(8),
      description: "Test category for moderation E2E scenarios.",
      display_order: typia.random<number & tags.Type<"int32">>(),
    }
  });
  typia.assert(categoryRes);

  // 4. Create a board inside the category
  const boardRes = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: categoryRes.id,
      name: "Test Board " + RandomGenerator.alphaNumeric(6),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: "Board for moderator comment visibility tests.",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    }
  });
  typia.assert(boardRes);

  // 5. Create a post as a member (simulate as moderator, since member APIs are accessible)
  const postRes = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryRes.id,
      title: "Moderation visibility E2E test post",
      body: RandomGenerator.paragraph()(),
    }
  });
  typia.assert(postRes);

  // 6. Create three comments (simulate as same session for test isolation)
  const commentBodies = [
    "Ordinary comment", "Flaggable comment", "Comment to delete"
  ];
  const commentRecords = [];
  for(const commentBody of commentBodies) {
    const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: postRes.id,
      body: {
        body: commentBody,
      }
    });
    typia.assert(comment);
    commentRecords.push(comment);
  }

  // 7. Soft-delete the last comment as moderator
  const deletedComment = await api.functional.polEcoBoard.moderator.posts.comments.erase(connection, {
    postId: postRes.id,
    commentId: commentRecords[2].id
  });
  typia.assert(deletedComment);

  // 8. Fetch all comments as moderator with include_deleted: true, flagged: null
  const listRes = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
    postId: postRes.id,
    body: {
      post_id: postRes.id,
      include_deleted: true,
      flagged: null,
      // Page, limit, etc. can be left undefined (will default)
    },
  });
  typia.assert(listRes);
  // Confirm that all three original comment bodies are in the returned page (including deleted)
  const returnedBodies = listRes.data.map(c => c.body);
  for(const expectedBody of commentBodies) {
    TestValidator.predicate("comment included: " + expectedBody)(returnedBodies.includes(expectedBody));
