/**
 * Validate that a moderator can retrieve the full list of comments for a post, including flagged and soft-deleted comments, confirming privileged visibility and correct filtering logic.
 *
 * This test simulates a realistic moderation workflow – from fresh registration and login as a moderator, to creating a test board category, board, and post, to generating several comments, some of which are later soft-deleted by the moderator to simulate moderation edge cases. The test then uses the PATCH operation as the moderator to fetch the post's comments with filters for flagged/deleted status, and checks that both ordinary and privileged (flagged, deleted) comment records are properly included in the result.
 *
 * Step-by-step process:
 * 1. Register a new moderator (fresh credentials)
 * 2. Log in as the moderator (obtain moderator session)
 * 3. Create a new board category as the moderator
 * 4. Create a board inside the category as the moderator
 * 5. Create a new post on the board as a member (using current session for test isolation)
 * 6. Add several comments (at least 3): ordinary, flagged candidate, and one to be deleted
 * 7. As moderator, soft-delete one of the comments (simulate soft deletion)
 * 8. As moderator, use PATCH postId/comments with filters:
 *    - flagged: null (fetch all)
 *    - include_deleted: true (must include deleted comments in moderation view)
 * 9. Assert that all expected comments (ordinary and deleted) appear in the moderator's result
 */
export async function test_api_moderator_comment_list_with_flagged_and_deleted(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestP@ssw0rd!42";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsentStatus = "v1.0";
  const regResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsentStatus,
    },
  });
  typia.assert(regResult);

  // 2. Moderator login
  const loginResult = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(loginResult);

  // 3. Create category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "E2E Moderation Cat " + RandomGenerator.alphaNumeric(8),
      description: "Category for testing moderator comment retrieval.",
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(category);

  // 4. Create board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: "Test Board " + RandomGenerator.alphaNumeric(6),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: "Board for moderator comment filter E2E.",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(board);

  // 5. Create a post (use moderator session for test isolation)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: "Moderator filter E2E Test Post",
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 6. Add comments
  const commentBodies = [
    "Normal comment for moderation.",
    "Will be deleted comment.",
    "Another ordinary comment."
  ];
  const commentObjs: IPolEcoBoardComment[] = [];
  for (const body of commentBodies) {
    const res = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body,
      },
    });
    typia.assert(res);
    commentObjs.push(res);
  }

  // 7. Delete the second comment (simulate moderator deletion)
  const deleted = await api.functional.polEcoBoard.moderator.posts.comments.erase(connection, {
    postId: post.id,
    commentId: commentObjs[1].id,
  });
  typia.assert(deleted);

  // 8. Fetch all comments as moderator, including deleted
  const search = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      include_deleted: true,
      flagged: null,
    },
  });
  typia.assert(search);

  // 9. Validate that all created comment bodies are represented
  const returnedBodies = search.data.map((c) => c.body);
  for (const originalBody of commentBodies) {
    TestValidator.predicate(`comment visible to moderator: ${originalBody}`)(returnedBodies.includes(originalBody));
  }
  // Specifically check that the deleted comment appears
  TestValidator.predicate("soft-deleted comment present in moderator view")(returnedBodies.includes(commentBodies[1]));
}

