/**
 * Validates that a moderator can successfully update an existing post edit record's reason, with full audit and role-based flow.
 *
 * Business context: In the polEcoBoard, post edits are historical snapshots of post content (for rollbacks and audit) and only certain fields may be changed after commit—primarily the reason for edit (edit_reason), and such changes are strictly permission controlled (moderator/admin only, not member-authored). This scenario ensures that: 1) only allowed fields can be updated, 2) audit compliance is met, and 3) attempts to tamper with restricted fields are appropriately rejected by the system.
 *
 * Workflow:
 * 1. Registers a moderator, retains email/password for authentication
 * 2. Moderator logs in
 * 3. Registers a member (for content ownership)
 * 4. Member logs in
 * 5. Member creates an original board post
 * 6. Moderator creates an initial edit record for that post
 * 7. Moderator updates the edit record, revising only the rationale field (edit_reason)
 * 8. Confirms the update was successful and only the rationale changed, not restricted fields
 * 9. (Edge) Attempts to update restricted fields and expects appropriate rejection
 */
export async function test_api_post_edit_update_by_moderator_valid_audit(connection: api.IConnection) {
  // Step 1: Register moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = RandomGenerator.alphaNumeric(12);
  const modDisplayName = RandomGenerator.name();
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: "v1-accepted"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorReg);
  // Step 2: Moderator login (refresh token/session)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(moderatorLogin);
  // Step 3: Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword satisfies string & tags.Format<"password">
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberSignUp);
  // Step 4: Member login for posting
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword satisfies string & tags.Format<"password">
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(memberLogin);
  // Step 5: Member creates post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1, 1),
      body: RandomGenerator.content()(2, 5),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);
  // Step 6: Moderator creates initial post edit
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  const initEdit = await api.functional.polEcoBoard.moderator.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: RandomGenerator.content()(),
      edit_reason: "Initial creation"
    } satisfies IPolEcoBoardPostEdit.ICreate
  });
  typia.assert(initEdit);
  // Step 7: Moderator updates rationale only
  const updatedReason = "Correction and expanded explanation";
  const updated = await api.functional.polEcoBoard.moderator.posts.postEdits.updateEdit(connection, {
    postId: post.id,
    postEditId: initEdit.id,
    body: {
      edit_reason: updatedReason
    } satisfies IPolEcoBoardPostEdit.IUpdate
  });
  typia.assert(updated);
  // Step 8: Assert rationale changed, edit_body/created_at/post_id/editor_member_id/id unchanged
  TestValidator.equals("edit_reason updated")(updated.edit_reason)(updatedReason);
  TestValidator.equals("edit_body unchanged")(updated.edit_body)(initEdit.edit_body);
  TestValidator.equals("editor id unchanged")(updated.editor_member_id)(initEdit.editor_member_id);
  TestValidator.equals("edit id unchanged")(updated.id)(initEdit.id);
  TestValidator.equals("post id unchanged")(updated.post_id)(initEdit.post_id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(initEdit.created_at);
  // Step 9: Attempt to tamper with restricted fields (should fail)
  await TestValidator.error("modifying edit_body should be rejected")(async () => {
    await api.functional.polEcoBoard.moderator.posts.postEdits.updateEdit(connection, {
      postId: post.id,
      postEditId: initEdit.id,
      body: {
        edit_body: "FORBIDDEN! Should not be allowed",
        edit_reason: "Trying to tamper"
      } as any // Only edit_reason is allowed; edit_body should be ignored/rejected
    });
  });
}

