import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/*
 * Validate permission denied when accessing a comment detail under a post in a restricted/locked state.
 *
 * This test simulates a member who is successfully registered, authenticated, and has created a post and comment in a discussion board. To emulate a permission denial scenario, the board is then locked/archived. After this state change, the same member attempts to fetch the comment detail via GET, which should result in a permission-denied error per business rules. The test also checks that this error is properly structured and, if supported, that an audit/failure log entry is generated.
 *
 * Step-by-step workflow:
 * 1. Register a new member with valid properties
 * 2. Login as the member to obtain authentication context
 * 3. Create a new board category (as admin or permitted context)
 * 4. Create a new board in that category (as admin)
 * 5. Create a post as member in that board/category
 * 6. Create a comment on that post as member
 * 7. Simulate admin archiving/locking the board (restricting comment access)
 * 8. Attempt to GET the comment detail using member's context
 * 9. Validate that the response triggers permission-denied error, checking error structure
 * 10. (If available) Optionally verify that a relevant audit/log entry is created for the incident.
 */
export async function test_api_member_comment_detail_view_permission_denied(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  // NOTE: This value is used for login; in a real system, password_hash should be a hash, but E2E usually uses plain for demo APIs
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberDisplayName = RandomGenerator.alphabets(10);
  const member: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: "v1",
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Login as the member to update the connection JWT context
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create category (must be possible with current JWT—if not, simulate admin here)
  const category: IPolEcoBoardCategory = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `E2E Test Category ${RandomGenerator.alphabets(6)}`,
      description: "Test category for locked board permission",
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 4. Create a board in that category
  const board: IPolEcoBoardBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: `E2E Test Board ${RandomGenerator.alphabets(6)}`,
      code: `e2e_board_${RandomGenerator.alphaNumeric(8).toLowerCase()}`,
      description: "Test board for comment permission",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 5. Create a post as the member
  const post: IPolEcoBoardPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: `Test Post Title ${RandomGenerator.alphabets(5)}`,
      body: RandomGenerator.paragraph()(),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Create a comment as the member
  const comment: IPolEcoBoardComment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()().substring(0, 100),
      parent_comment_id: null
    } satisfies IPolEcoBoardComment.ICreate
  });
  typia.assert(comment);

  // 7. Lock/archive the board as admin (here, we reuse connection context but real system may require role switch)
  const updatedBoard: IPolEcoBoardBoard = await api.functional.polEcoBoard.admin.boards.update(connection, {
    boardId: board.id,
    body: {
      is_archived: true,
    } satisfies IPolEcoBoardBoard.IUpdate
  });
  typia.assert(updatedBoard);
  TestValidator.equals("Board is archived")(updatedBoard.is_archived)(true);

  // 8. Attempt to fetch comment detail as member
  await TestValidator.error("Permission denied retrieving comment under archived board")(
    async () => {
      await api.functional.polEcoBoard.member.posts.comments.at(connection, {
        postId: post.id,
        commentId: comment.id
      });
    }
  );
  // 9. Audit log verification skipped; not available via current API
}

