import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator update of post reports, including field editability, access control, and error handling.
 *
 * Business context: Only moderators or admins can update abuse/inappropriate content reports on posts. This operation should check that all permitted report fields (reason_code, reason_description) are editable and changes are reflected. Further, audit and access rules must prevent updates by ordinary members, non-owners, and for non-existent reports. Error handling for permissions and bad IDs must also be robust.
 *
 * Steps:
 * 1. Register and login as moderator
 * 2. Register and login as member (who will create post and report)
 * 3. Member creates a post
 * 4. Member files report on their own post
 * 5. Moderator updates the report (reason code and description)
 * 6. Confirm report fields updated as expected
 * 7. Attempt forbidden update as a member (should be denied)
 * 8. Attempt update on nonexistent reportId (should error)
 */
export async function test_api_moderator_update_post_report_status_and_notes(connection: api.IConnection) {
  // 1. Register and login as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName = RandomGenerator.alphaNumeric(8);
  const moderatorConsent = "agree_2024_v1"; // Example consent string for demonstration
  const modReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(modReg);

  // Confirm login as moderator (gets fresh token)
  const modLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(modLogin);

  // 2. Register and login as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberReg);

  // Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(memberLogin);

  // 3. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1).substr(0, 100);
  const postBody = RandomGenerator.content()(2, 6).substr(0, 1000);
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Member reports their own post
  const origReasonCode = "abuse";
  const origReasonDescription = "Inappropriate content, test setup.";
  const memberReport = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: post.id,
    body: {
      reason_code: origReasonCode,
      reason_description: origReasonDescription,
      post_id: post.id,
    } satisfies IPolEcoBoardReport.ICreate
  });
  typia.assert(memberReport);

  // 5. Login as moderator again (token context switch)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword }
  });

  // 6. Moderator updates the report
  const updateReasonCode = "off_topic";
  const updateReasonDesc = "Changed reason after review.";
  const updatedReport = await api.functional.polEcoBoard.moderator.posts.reports.update(connection, {
    postId: post.id,
    reportId: memberReport.id,
    body: {
      reason_code: updateReasonCode,
      reason_description: updateReasonDesc
    } satisfies IPolEcoBoardReport.IUpdate
  });
  typia.assert(updatedReport);

  // Check updated fields
  TestValidator.equals("reason_code changed")(updatedReport.reason_code)(updateReasonCode);
  TestValidator.equals("description changed")(updatedReport.reason_description)(updateReasonDesc);
  TestValidator.equals("report id matches")(updatedReport.id)(memberReport.id);

  // 7. Switch to member again for forbidden action
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword }
  });

  // Member tries to update report (should be denied)
  await TestValidator.error("member forbidden to update report")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.reports.update(connection, {
        postId: post.id,
        reportId: memberReport.id,
        body: {
          reason_code: "spam"
        }
      });
    }
  );

  // 8. Login as moderator, try invalid report id
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword }
  });
  const badReportId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("updating nonexistent report fails")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.reports.update(connection, {
        postId: post.id,
        reportId: badReportId,
        body: {
          reason_code: "hate"
        }
      });
    }
  );
}

