    triggered_at: new Date(Date.now() + 60000).toISOString(),
    content_uri: `s3://bucket/reports/${reportCode}-dupe`
  };
  await TestValidator.error("Duplicate report_code should fail")(() =>
    api.functional.polEcoBoard.admin.businessReports.create(connection, { body: secondCreateBody })
