 * 3. Create a board category (admin)
 * 4. Create a board within that category (admin)
 * 5. As member01, create a new post in the board
 * 6. As admin, create a new tag
 * 7. As member01, assign this tag to the post
 * 8. As member02 (not post author), attempt to erase the post-tag assignment
 * 9. Assert that the operation fails with a permission/forbidden error (do not check error message detail)
 */
export async function test_api_post_tag_member_erase_not_owner_forbidden(connection: api.IConnection) {
