  const member01Email = typia.random<string & tags.Format<"email">>();
  const member01: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member01Email,
      password_hash: "hashed_pw01",
      display_name: RandomGenerator.name(),
      consent_status: "v1_policy_agreed"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member01);

  // Step 2: Register member02 (not owner)
  const member02Email = typia.random<string & tags.Format<"email">>();
  const member02: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member02Email,
      password_hash: "hashed_pw02",
      display_name: RandomGenerator.name(),
      consent_status: "v1_policy_agreed"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member02);

  // Step 3: Create a board category (admin)
  const category: IPolEcoBoardCategory = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "Economics Discussions " + RandomGenerator.alphaNumeric(4),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // Step 4: Create a board in this category (admin)
  const board: IPolEcoBoardBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: "Macro Board " + RandomGenerator.alphaNumeric(4),
      code: "macro_" + RandomGenerator.alphaNumeric(6).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // Step 5: As member01, create a post in the board
  // (Assume context token/session for member01 is handled by underlying test infra)
  const post: IPolEcoBoardPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()().slice(0, 32),
      body: RandomGenerator.content()()().slice(0, 300)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // Step 6: As admin, create a tag
  const tag: IPolEcoBoardTag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: "tag" + RandomGenerator.alphaNumeric(5),
      slug: "tag-" + RandomGenerator.alphaNumeric(5).toLowerCase(),
      description: RandomGenerator.paragraph()()
    } satisfies IPolEcoBoardTag.ICreate
  });
  typia.assert(tag);

  // Step 7: As member01, assign the tag to the post
  const postTag: IPolEcoBoardPostTag = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: {
      tag_id: tag.id
    } satisfies IPolEcoBoardPostTag.ICreate
  });
  typia.assert(postTag);

  // Step 8: As member02, attempt to erase the tag assignment (should fail - forbidden)
  // (Assume test framework manages connection context for member02 or that context switching is simulated as needed)
  TestValidator.error("non-owner cannot erase tag")(
    async () => {
      await api.functional.polEcoBoard.member.posts.postTags.erase(connection, {
        postId: post.id,
        postTagId: postTag.id
      });
    }
  );
}

