import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin access to full details of a vote on a comment and forbidden results for lower privilege.
 *
 * This test verifies that a properly authenticated admin can read the full details of a specific vote tied to a comment using /polEcoBoard/admin/comments/{commentId}/votes/{voteId}. It also checks that lower-privilege users, such as the voting member or unauthenticated guests, are forbidden from accessing the same data.
 *
 * Steps:
 * 1. Register an admin account and log in to fetch a token.
 * 2. Register a member account and log in. Create a minimal valid post as this member (providing a valid categoryId, title, body).
 * 3. As member, create a comment on the post.
 * 4. As member, vote (upvote or downvote) on the comment.
 * 5. Switch to admin session (restore admin JWT). Use the /polEcoBoard/admin/comments/{commentId}/votes/{voteId} GET endpoint, passing the correct IDs from previous steps. Assert: (a) the vote record is found, (b) all fields match, (c) the vote is for the expected comment, (d) voter_member_id is that of the member.
 * 6. As guest (no session/JWT) or as the member, attempt to access the same endpoint. Assert: forbidden (error/exception is thrown, not a valid result).
 */
export async function test_api_comment_vote_detail_admin_success_and_forbidden_access(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignUp });
  await api.functional.auth.admin.login.signIn(connection, { body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn });

  // 2. Register and login as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  await api.functional.auth.member.register.signUp(connection, { body: { email: memberEmail, password: memberPassword } satisfies IMemberAuthenticationMemberSignUp });
  await api.functional.auth.member.login.signIn(connection, { body: { email: memberEmail, password: memberPassword } satisfies IMemberAuthenticationMemberSignIn });

  // 3. Create a post (requires valid categoryId, title, body)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, { body: { category_id: typia.random<string & tags.Format<"uuid">>(), title: RandomGenerator.paragraph()(15), body: RandomGenerator.content()()(50) } satisfies IPolEcoBoardPost.ICreate });
  typia.assert(post);

  // 4. Create a comment on the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, { postId: post.id, body: { body: RandomGenerator.paragraph()(10) } satisfies IPolEcoBoardComment.ICreate });
  typia.assert(comment);

  // 5. Vote on the comment
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, { commentId: comment.id, body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate });
  typia.assert(vote);

  // 6. Switch to admin
  await api.functional.auth.admin.login.signIn(connection, { body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn });

  // 7. Fetch vote by admin
  const adminVote = await api.functional.polEcoBoard.admin.comments.votes.at(connection, { commentId: comment.id, voteId: vote.id });
  typia.assert(adminVote);
  TestValidator.equals("vote ID")(adminVote.id)(vote.id);
  TestValidator.equals("comment ID")(adminVote.comment_id)(comment.id);
  TestValidator.equals("voter_member_id")(adminVote.voter_member_id)(vote.voter_member_id);
  TestValidator.equals("vote_value")(adminVote.vote_value)(1);

  // 8. Try fetching vote as member (should be forbidden)
  await api.functional.auth.member.login.signIn(connection, { body: { email: memberEmail, password: memberPassword } satisfies IMemberAuthenticationMemberSignIn });
  TestValidator.error("Member forbidden to access admin vote endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.comments.votes.at(connection, { commentId: comment.id, voteId: vote.id });
    }
  );

  // 9. Try fetching vote as guest (no login)
  // Remove Authorization header
  delete connection.headers.Authorization;
  TestValidator.error("Guest forbidden to access admin vote endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.comments.votes.at(connection, { commentId: comment.id, voteId: vote.id });
    }
  );
}

