export async function test_api_post_tag_deletion_by_moderator_not_found(connection: api.IConnection) {
  // 1. Register and login as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Test1234!";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "v1"; // business consent code

  const moderatorRegisterResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegisterResp);

  // Explicit login as moderator (although register also authenticates), for clarity
  const moderatorLoginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLoginResp);

  // 2. As moderator, create a category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(1),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 3. As moderator, create a board associated with the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(2),
      code: RandomGenerator.alphabets(10).toLowerCase(),
      description: RandomGenerator.paragraph()(1),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 4. Register new member, login as member, and create a post
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "Test5678!";
  const memberDisplayName = RandomGenerator.name();
  const memberConsent = "v1";

  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: memberConsent,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // Login as member
  const memberLoginResp = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginResp);

  // Create a post as member (no tags, core fields only)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.paragraph()(3),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Switch to moderator by logging in again with moderator credentials
  const moderatorRelogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorRelogin);

  // 6. Attempt to DELETE a non-existent (random) postTagId for the created post
  const nonExistentPostTagId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should return not found when deleting non-existent post tag assignment")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.postTags.erase(connection, {
        postId: post.id,
        postTagId: nonExistentPostTagId,
      });
    },
  );
}

