import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin search for board statuses with flexible filter and pagination.
 *
 * This test ensures full search functionality for board status events for admins, including filtering by board ID, status type, actor, and effective date range.
 * All responses must respect pagination and only include board statuses accessible to an authenticated admin.
 *
 * Steps:
 * 1. Register a new admin account and log in (to get authentication token set in connection)
 * 2. Create a board category as admin
 * 3. Create a board under the created category
 * 4. Create a board status event (e.g., status_type 'locked', effective now) on the board, using actor_admin_id
 * 5. Search (PATCH) for board statuses, filtering by pol_eco_board_board_id and status_type
 * 6. Validate the result structure: that pagination object is correct, that at least one event matches our input (board id + status_type), and summary fields are populated.
 */
export async function test_api_admin_board_statuses_search_success(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signUpRes);

  // 2. Login as admin
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signInRes);
  // after login, connection is now authenticated as admin.

  // 3. Create board category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1).slice(0, 60),
      description: RandomGenerator.content()(1)(1).slice(0, 255),
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(category);

  // 4. Create board in this category
  const boardName = RandomGenerator.paragraph()(1).slice(0, 60);
  const boardCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardName,
      code: boardCode,
      description: RandomGenerator.content()(1)(1).slice(0, 255),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(board);

  // 5. Create a board status event for this board (status_type: 'locked')
  const effectiveNow = new Date().toISOString();
  const boardStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: null,
      actor_admin_id: null,
      status_type: 'locked',
      effective_at: effectiveNow,
      reason: 'Admin locks for test',
    },
  });
  typia.assert(boardStatus);

  // 6. PATCH search by board id + status_type
  const searchRes = await api.functional.polEcoBoard.admin.boardStatuses.search(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      status_type: 'locked',
      page: 1,
      limit: 10,
    },
  });
  typia.assert(searchRes);

  // Paginated result structure & at least one result
  const { pagination, data } = searchRes;
  TestValidator.predicate('pagination.current is 1')(pagination.current === 1);
  TestValidator.predicate('pagination.limit is 10')(pagination.limit === 10);
  TestValidator.predicate('data has at least one event')(data.length >= 1);

  // Validate at least one data matches board id & status_type
  const found = data.some(ev => ev.pol_eco_board_board_id === board.id && ev.status_type === 'locked');
  TestValidator.predicate('should have at least one matching status event')(found);
}

