/**
 * E2E test covering business policy for vote deletion on comments in PolEcoBoard.
 *
 * This test validates the following workflow:
 * 1. Register and login as a member (vote owner)
 * 2. Create a post and a comment, then cast a vote as the owner
 * 3. Delete (retract) the vote as the owner
 * 4. Confirm the vote cannot be queried or is excluded from vote tallies (best effort: we cannot query directly, but errors or absence are checked)
 * 5. Register/login as a second (non-owner) member
 * 6. Attempt vote deletion as non-owner and confirm forbidden/authorization failure
 * 7. [Optional/Best effort] Attempt deletion after a hypothetical expired voting window
 *
 * Restrictions:
 * - Use only the provided SDK functions (no admin/lookup/query API for votes, so deletion is tested via flow and error behaviour)
 * - Only use the provided DTOs and response types, no assumptions
 */
export async function test_api_comment_vote_delete_owner_and_policy_checks(connection: api.IConnection) {
  // 1. Register member (Voter) and login
  const voterEmail: string = typia.random<string & tags.Format<"email">>();
  const voterPassword: string = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: voterEmail,
      password: voterPassword
    }
  });
  typia.assert(signUpResult);

  const signInResult = await api.functional.auth.member.login.signIn(connection, {
