      await api.functional.polEcoBoard.member.comments.votes.erase(connection, {
        commentId: comment.id,
        voteId: vote.id
      });
    }
  );

  // 7. Register/login as second member (non-owner)
  const otherEmail: string = typia.random<string & tags.Format<"email">>();
  const otherPassword: string = typia.random<string & tags.Format<"password">>();
  typia.assert(await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: otherEmail,
      password: otherPassword
    }
  }));

  typia.assert(await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: otherEmail,
      password: otherPassword
    }
  }));

  // 8. Non-owner attempts to delete the owner's vote (should fail)
  await TestValidator.error("non-owner cannot delete owner vote")(
    async () => {
      await api.functional.polEcoBoard.member.comments.votes.erase(connection, {
        commentId: comment.id,
        voteId: vote.id
      });
    }
  );
