/**
 * Validate that an admin can successfully retrieve detailed information of a specific report filed for a post.
 *
 * Business context:
 * Admins need access to individual report details for moderation and audit. This process involves setting up all dependencies: registering an admin and member, creating a post as that member, filing a report on the post, and then having the admin retrieve that report. This end-to-end flow validates both permission enforcement and data integrity in report retrieval.
 *
 * Step-by-step workflow:
 * 1. Register a new admin (with random credentials) and extract credentials for login
 * 2. Log in as the admin to ensure the connection carries admin privileges
 * 3. Register a member (providing random but compliant email & password)
 * 4. Log in as the member
 * 5. The member creates a post (with a valid, random category_id, title, body)
 * 6. The member submits a report for the post (with a valid reason_code and optional description)
 * 7. Switch back to the admin account by logging in again
 * 8. The admin retrieves that report using the collected postId and reportId
 * 9. Assert the properties of the returned report, verifying key fields: correct ids, reason_code matches what was submitted, and that sensitive member fields are present and correct.
 */
export async function test_api_post_report_retrieve_success_admin_role(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpRes = await api.functional.auth.admin.register.signUp(connection, {
