import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate updating categories as an admin, including error scenarios for uniqueness conflicts and partial updates.
 *
 * 1. Register an admin and login for authorization.
 * 2. Create two categories.
 * 3. Update the first category with new values (name, description, display_order), verify changes and updated_at timestamp.
 * 4. Attempt to update the second category's name to the first one's (should trigger uniqueness error).
 * 5. Partially update category, changing only one field, and check that other fields remain unchanged.
 */
export async function test_api_category_update_success_and_conflict(connection: api.IConnection) {
  // 1. Register a new admin.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPwd1!" + typia.random<string>().slice(0,8); // Ensure min 8 chars and complexity.
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 2. Login as the admin user to get JWT in connection.
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 3. Create two categories to test updates and conflicts.
  const category1Input: IPolEcoBoardCategory.ICreate = {
    name: "Eco Economy " + typia.random<string>().slice(0,6),
    description: "First eco economy category: " + typia.random<string>().slice(0,10),
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const category2Input: IPolEcoBoardCategory.ICreate = {
    name: "Eco Environment " + typia.random<string>().slice(0,6),
    description: "Second eco env category: " + typia.random<string>().slice(0,10),
    display_order: category1Input.display_order + 1,
  };
  const category1 = await api.functional.polEcoBoard.admin.categories.create(connection, { body: category1Input });
  typia.assert(category1);
  const category2 = await api.functional.polEcoBoard.admin.categories.create(connection, { body: category2Input });
  typia.assert(category2);

  // Save previous updated_at for later comparison
  const category1PrevUpdatedAt = category1.updated_at;

  // 4. Update the first category with new values.
  const category1UpdatedFields: IPolEcoBoardCategory.IUpdate = {
    name: category1.name + " Updated",
    description: (category1.description ?? "") + " (edited)",
    display_order: category1.display_order + 10
  };
  const updatedCategory1 = await api.functional.polEcoBoard.admin.categories.update(connection, {
    categoryId: category1.id,
    body: category1UpdatedFields
  });
  typia.assert(updatedCategory1);
  TestValidator.notEquals("updated_at should change")(updatedCategory1.updated_at)(category1PrevUpdatedAt);
  TestValidator.equals("name updated")(updatedCategory1.name)(category1UpdatedFields.name);
  TestValidator.equals("description updated")(updatedCategory1.description)(category1UpdatedFields.description);
  TestValidator.equals("display_order updated")(updatedCategory1.display_order)(category1UpdatedFields.display_order);

  // 5. Attempt uniqueness conflict by updating category2's name to category1's updated name (should fail).
  await TestValidator.error("duplicate category name should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.categories.update(connection, {
        categoryId: category2.id,
        body: {
          name: updatedCategory1.name
        }
      });
    }
  );

  // 6. Partial update: only update description in category2.
  const partialDescription = (category2.description ?? "") + " (partial update)";
  const partiallyUpdatedCategory2 = await api.functional.polEcoBoard.admin.categories.update(connection, {
    categoryId: category2.id,
    body: {
      description: partialDescription
    }
  });
  typia.assert(partiallyUpdatedCategory2);
  TestValidator.equals("description updated")(partiallyUpdatedCategory2.description)(partialDescription);
  TestValidator.equals("name unchanged")(partiallyUpdatedCategory2.name)(category2.name);
  TestValidator.equals("display_order unchanged")(partiallyUpdatedCategory2.display_order)(category2.display_order);
}

