 * 4. Validate the notification record is returned with correct fields (including id, timestamps)
 * 5. Attempt to create notifications with missing required properties (recipient_member_id, event_type, status)
 * 6. Attempt to create notifications with invalid fields (empty event_type or status)
 * 7. Attempt to create a notification with a non-existent recipient_member_id (should fail by business logic)
 *
 * All negative cases must result in validation or business rule error responses. No external data or pre-existing members are assumed except admin registration.
 */
export async function test_api_admin_notification_creation_success_and_validation_failure(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signUpResponse);

  // 2. Admin login to ensure authentication header is present (may be side-effect of registration anyway)
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signInResponse);

  // 3. Create notification with valid required fields
  const recipientMemberId = typia.random<string & tags.Format<"uuid">>();
  const validEventType = "reply";
  const validStatus = "pending";
  const notification = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: recipientMemberId,
      event_type: validEventType,
      status: validStatus,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(notification);
  TestValidator.equals("recipient_member_id matches")(notification.recipient_member_id)(recipientMemberId);
  TestValidator.equals("event_type matches")(notification.event_type)(validEventType);
  TestValidator.equals("status matches")(notification.status)(validStatus);
  TestValidator.predicate("id assigned, UUID")(typeof notification.id === "string" && notification.id.length > 0);

  // 4. Missing required: recipient_member_id
  await TestValidator.error("missing recipient_member_id should fail")(async () => {
    return api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        event_type: validEventType,
        status: validStatus,
      } as any,
    });
  });

  // 5. Missing required: event_type
  await TestValidator.error("missing event_type should fail")(async () => {
    return api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        recipient_member_id: recipientMemberId,
        status: validStatus,
      } as any,
    });
  });

  // 6. Missing required: status
  await TestValidator.error("missing status should fail")(async () => {
    return api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        recipient_member_id: recipientMemberId,
        event_type: validEventType,
      } as any,
    });
  });

  // 7. Invalid: empty event_type
  await TestValidator.error("empty event_type fails")(async () => {
    return api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        recipient_member_id: recipientMemberId,
        event_type: "",
        status: validStatus,
      },
    });
  });

  // 8. Invalid: empty status
  await TestValidator.error("empty status fails")(async () => {
    return api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        recipient_member_id: recipientMemberId,
        event_type: validEventType,
        status: "",
      },
    });
  });

  // 9. Non-existent recipient_member_id: should fail (business rule or FK validation)
  const unknownMemberId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("unknown recipient_member_id fails")(async () => {
    return api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        recipient_member_id: unknownMemberId,
        event_type: validEventType,
        status: validStatus,
      },
    });
  });
}

