 *    a. Retrieve their own notification failure by ID, verifying all business/audit details are returned correctly.
 *    b. Attempt to retrieve member B's notification failure by ID, verifying an error is thrown (either 403 Forbidden or 404 Not Found), enforcing row-level access control.
 *
 * Validation:
 * - All notification failure fields are present and accurate when accessed by the owning member.
 * - Unauthorized access attempts return error responses and do not leak details of other members' failures.
 */
export async function test_api_notification_failure_member_get_own_and_forbidden_others(connection: api.IConnection) {
