  const memberBPassword = typia.random<string & tags.Format<"password">>();
  const memberBRegister = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberBRegister);

  // 3. Login as member A
  const memberALogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberALogin);

  // 4. Login as member B
  const memberBLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberBLogin);

  // 5. Create notification failure (admin) for member A
