  const notificationIdA = typia.random<string & tags.Format<"uuid">>();
  const notificationFailureDataA: IPolEcoBoardNotificationFailure.ICreate = {
    notification_id: notificationIdA,
    provider_id: null,
    failure_code: "DELIVERY_TIMEOUT",
    failure_message: "Notification delivery timed out.",
    occurred_at: new Date().toISOString(),
    resolution_status: "pending",
  };
