  // 7. Login as member A (refresh Authorization)
  const memberALogin2 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberALogin2);

  // 8. Member A GETs own notification failure (should succeed)
  const retrievedA = await api.functional.polEcoBoard.member.notificationFailures.at(connection, {
    notificationFailureId: notificationFailureA.id,
