import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCommentEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test moderator's ability to update the rationale for a comment edit (revision history) entry.
 *
 * Business Context:
 * Moderators sometimes need to edit the rationale for a comment edit (e.g., for audit correction, compliance, or moderators' intervention in content discussions).
 * Only the rationale (edit_reason) can be updated; all other edit record fields are immutable via this API.
 * The system must audit who made the update and when, and enforce that only allowed fields are changed.
 *
 * Steps:
 * 1. Register a new moderator, then log in as this moderator.
 * 2. Register a normal member, then log in as this member.
 * 3. Member creates a new post in a random category.
 * 4. Member creates a new comment under the post.
 * 5. Member edits their comment (generating an initial comment edit record; this gives us a comment with at least one edit revision).
 * 6. Moderator logs in again (switch context) to perform the audit update.
 * 7. Moderator updates the rationale (edit_reason) of the initial comment edit record.
 * 8. Verify only the rationale changes, all other fields (edit_body, etc.) remain the same.
 * 9. Check audit information: date, editor_member_id matches moderator (if supported).
 *10. Attempt to update a non-existent comment edit ID and assert rejection.
 *
 * Note: API/DTO does not allow updating immutable fields like edit_body. Also, edit record listing/fetching is not available; we use the commentId as a stand-in for editId for test purposes.
 */
export async function test_api_moderator_update_comment_edit_rationale(connection: api.IConnection) {
  // 1. Register a new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestPassw0rd$";
  const moderatorDisplayName = RandomGenerator.name();
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: "consent_v1"
    }
  });

  // Log in as moderator
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword }
  });

  // 2. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestPassw0rd$";
  await api.functional.auth.member.register.signUp(connection, {
    body: { email: memberEmail, password: memberPassword }
  });

  // Log in as member
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword }
  });

  // 3. Member creates a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()(3)(2),
    }
  });
  typia.assert(post);

  // 4. Member creates a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(1),
    }
  });
  typia.assert(comment);

  // 5. Member edits the comment (generates a comment edit record)
  const editedComment = await api.functional.polEcoBoard.member.posts.comments.update(connection, {
    postId: post.id,
    commentId: comment.id,
    body: { body: RandomGenerator.paragraph()(1) }
  });
  typia.assert(editedComment);

  // Assume edit record (editId) is linked to comment.id for test since no edit history/list endpoint exists
  const commentEditId = comment.id;

