  const editRecord = await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.update(connection, {
    postId: post.id,
    commentId: comment.id,
    commentEditId: commentEditId,
    body: { edit_reason: newReason }
  });
  typia.assert(editRecord);
  TestValidator.equals("edit_reason updated")(editRecord.edit_reason)(newReason);
  TestValidator.equals("correct comment id")(editRecord.comment_id)(comment.id);

  // 9. (Optional) editor_member_id = moderator would be checked here if exposed (not available)

  // 10. Attempt update to non-existent editId should throw
  await TestValidator.error("non-existent edit id")(() =>
    api.functional.polEcoBoard.moderator.posts.comments.commentEdits.update(connection, {
      postId: post.id,
      commentId: comment.id,
      commentEditId: typia.random<string & tags.Format<"uuid">>(),
