import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPageIPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator search & filtering of post abuse reports by various filters/pagination.
 *
 * Ensures that:
 * - Moderator can fetch a paginated/filterable list of reports for a post.
 * - Filtering by reason_code, reporter_member_id, created_at ranges works.
 * - Pagination is honored.
 * - Only reports matching the given postId are shown (no cross-post contamination).
 * - Forbidden or invalid postId queries return error.
 *
 * Limitations:
 * - Cannot directly simulate member authentication or non-moderator access attempts due to missing member login endpoints.
 * - Only moderator and the system's allowed flows are testable here.
 *
 * Steps:
 * 1. Register & login as moderator.
 * 2. Create Post as member (performed as moderator, since no member API exists).
 * 3. Create several reports by simulating different "reporters" (random reporter_member_id, reason_code, created_at).
 * 4. Test querying with:
 *    a. No filter (expect all reports)
 *    b. reason_code filter
 *    c. reporter_member_id filter
 *    d. created_at_start/created_at_end
 *    e. Pagination (limit/page)
 *    f. No match filter (expect empty)
 *    g. Invalid postId (error expected)
 *    h. Cross-post check: unrelated report must not be returned
 */
export async function test_api_post_report_search_by_moderator_various_filters(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const password = "Moderator@123";
  const displayName = RandomGenerator.name();
  const consent = "agreed-v1";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password,
      display_name: displayName,
      consent_status: consent
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorReg);

  // 2. Login as moderator (obtain auth token)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(moderatorLogin);

  // 3. Create a post (as-member simulation; only endpoint is available, so performed as moderator)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1, 2);
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: { category_id: categoryId, title: postTitle, body: postBody } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Create multiple reports on this post (simulate different reporters, reasons, time)
  const reasons = ["abuse", "spam", "hate", "off_topic", "other"];
  const createdReports: IPolEcoBoardReport[] = [];
  const reporterIds: string[] = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  // For time variation, set created_at values spread in the past
  const now = new Date();

  for (let i = 0; i < 8; ++i) {
    const reporter_member_id = RandomGenerator.pick(reporterIds);
    const reason_code = RandomGenerator.pick(reasons);
    // Simulate as if reports are created sequentially by changing reason, reporter, created_at spacing
    const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
      postId: post.id,
      body: {
        reason_code,
        reason_description: RandomGenerator.paragraph()(),
        post_id: post.id
      } satisfies IPolEcoBoardReport.ICreate
    });
    // Emulate variety in report creation times by modifying created_at (not possible via API: only system fills created_at)
    createdReports.push(report);
    typia.assert(report);
  }

  // 5. Create an unrelated post + report (for cross-post contamination check)
  const otherPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: { category_id: typia.random<string & tags.Format<"uuid">>(), title: RandomGenerator.paragraph()(1, 2), body: RandomGenerator.content()()() } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(otherPost);

  const otherReport = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: otherPost.id,
    body: {
      reason_code: "spam",
      reason_description: RandomGenerator.paragraph()(),
      post_id: otherPost.id
    } satisfies IPolEcoBoardReport.ICreate
  });
  typia.assert(otherReport);

  // 6a. As moderator, query without filter: expect all 8 reports
  const resAll = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
    postId: post.id,
    body: {} satisfies IPolEcoBoardReport.IRequest
  });
  typia.assert(resAll);
  const reportIdsAll = resAll.data.map((r) => r.id);
  TestValidator.equals("all reports count")(reportIdsAll.length)(8);

  // 6b. By reason_code
  for (const reason of reasons) {
    const res = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: post.id,
      body: { reason_code: reason } satisfies IPolEcoBoardReport.IRequest
    });
    typia.assert(res);
    for (const report of res.data) TestValidator.equals("filter reason_code")(report.reason_code)(reason);
  }

  // 6c. By reporter_member_id
  for (const repId of reporterIds) {
    const res = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: post.id,
      body: { reporter_member_id: repId } satisfies IPolEcoBoardReport.IRequest
    });
    typia.assert(res);
    for (const report of res.data) TestValidator.equals("filter reporter_member_id")(report.reporter_member_id)(repId);
  }

  // 6d. created_at_start/created_at_end - pick min/max from createdReports
  const createdAts = createdReports.map(r => r.created_at).sort();
  if (createdAts.length >= 2) {
    const start = createdAts[1];
    const end = createdAts[createdAts.length - 2];
    const res = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: post.id,
      body: { created_at_start: start, created_at_end: end } satisfies IPolEcoBoardReport.IRequest
    });
    typia.assert(res);
    for (const report of res.data) {
      TestValidator.predicate("created_at_start")(report.created_at >= start);
      TestValidator.predicate("created_at_end")(report.created_at <= end);
    }
  }

  // 6e. Pagination (limit=2, page=2)
  const pageRes = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 2, page: 2 } satisfies IPolEcoBoardReport.IRequest
  });
  typia.assert(pageRes);
  TestValidator.equals("pagination limit")(pageRes.pagination.limit)(2);
  TestValidator.equals("pagination page")(pageRes.pagination.current)(2);

  // 6f. Filter returning no match (e.g., bogus reporter_member_id)
  const noneRes = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
    postId: post.id,
    body: { reporter_member_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardReport.IRequest
  });
  typia.assert(noneRes);
  TestValidator.equals("no results")(noneRes.data.length)(0);

  // 6g. Cross-post: ensure a report from other post is not returned here
  for (const report of resAll.data) {
    TestValidator.notEquals("cross-post contamination")(report.id)(otherReport.id);
    TestValidator.equals("belongs to correct post")(report.post_id)(post.id);
  }

  // 6h. Invalid postId (malformed uuid)
  TestValidator.error("invalid postId")(async () =>
    api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: "invalid-uuid-format" as any,
      body: {} satisfies IPolEcoBoardReport.IRequest
    })
  );

  // 6i. Forbidden: not testable (no member login), so omitted
}

