    moderatorBoardAssignmentId: assignmentCreate.id,
  });
  typia.assert(assignment);
  TestValidator.equals("assignment id matches")(assignment.id)(assignmentCreate.id);
  TestValidator.equals("moderator id matches")(assignment.pol_eco_board_moderator_id)(moderatorSignup.moderatorId);
  TestValidator.equals("board id matches")(assignment.pol_eco_board_board_id)(boardCreate.id);

  // 9. Attempt to fetch a random/non-existent assignmentId as moderator and confirm error
  await TestValidator.error("random assignment id not found/forbidden")(
    async () =>
      await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.at(connection, {
        moderatorBoardAssignmentId: typia.random<string & tags.Format<"uuid">>(),
      }),
  );

  // 10. Register a second moderator and ensure they can't access the first moderator's assignment
  const secondModeratorEmail = typia.random<string & tags.Format<"email">>();
  const secondModeratorPassword = "AnotherPass456!";
  const secondModeratorSignup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: secondModeratorEmail,
      password: secondModeratorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1",
    },
  });
  typia.assert(secondModeratorSignup);

  // Login as second moderator
  const secondModeratorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: secondModeratorEmail,
      password: secondModeratorPassword,
    },
  });
  typia.assert(secondModeratorLogin);

  await TestValidator.error("unauthorized assignment access")(
    async () =>
      await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.at(connection, {
        moderatorBoardAssignmentId: assignmentCreate.id,
      }),
  );
}

