import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPageIPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a registered member can search and retrieve the list of file attachments for a post they are permitted to access.
 *
 * This covers the following business workflow and validates correct API behavior, permissions, and metadata integrity for attachment searching:
 *
 * 1. Register a new board category as admin (needed for board context)
 * 2. Register a board in the created category (admin action)
 * 3. Register and login as a member (to create and access posts and attachments)
 * 4. Member creates a post on the board
 * 5. Member adds at least one attachment to the post
 * 6. Member requests the list of attachments for their own post using the PATCH search endpoint
 * 7. Validate:
 *    - Response contains all of that post's attachments, with correct metadata (filename, type, size, uri, etc)
 *    - Pagination fields are present and correct (e.g. total records, limit, pages)
 *    - Filtering (e.g. by file_name, mime_type) is respected if provided
 *    - Permission boundary: only attachments for accessible posts (not unrelated posts or posts by others) are returned
 *    - Fields like author_member_id, created_at, etc. are present and formatted correctly
 *
 * This E2E test ensures correct business logic, type conformance, and reliable access control around the attachment retrieval workflow.
 */
export async function test_api_post_attachment_search_as_member_success(connection: api.IConnection) {
  // 1. Create a category (admin required)
  const categoryBody: IPolEcoBoardCategory.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: categoryBody,
  });
  typia.assert(category);

  // 2. Create a board in the category (admin required)
  const boardBody: IPolEcoBoardBoard.ICreate = {
    pol_eco_board_category_id: category.id,
    name: RandomGenerator.alphaNumeric(10),
    code: RandomGenerator.alphaNumeric(8).toLowerCase(),
    description: RandomGenerator.paragraph()(),
    is_public: true,
    is_archived: false,
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: boardBody,
  });
  typia.assert(board);

  // 3. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberBody: IPolEcoBoardMember.ICreate = {
    email: memberEmail,
    password_hash: memberPassword, // For testing, treat as plain (in live, must be hashed)
    display_name: RandomGenerator.alphaNumeric(10),
    profile_image_uri: null,
    consent_status: "accepted", // Example value
  };
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: memberBody,
  });
  typia.assert(member);

  // 4. Login as the member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  // No assertion needed, token set in connection

  // 5. Member creates a post on the created board
  const postBody: IPolEcoBoardPost.ICreate = {
    category_id: category.id,
    title: RandomGenerator.alphaNumeric(30),
    body: RandomGenerator.paragraph()(),
    tag_ids: null,
    attachments: null, // attachments created by dedicated endpoint after post creation
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postBody,
  });
  typia.assert(post);

  // 6. Member adds an attachment to the post
  const attachmentBody: IPolEcoBoardAttachment.ICreate = {
    uri: `https://storage.example.com/u/${RandomGenerator.alphaNumeric(16)}`,
    file_name: `${RandomGenerator.alphaNumeric(8)}.pdf`,
    file_size_bytes: typia.random<number & tags.Type<"int32">>(),
    mime_type: "application/pdf",
  };
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: attachmentBody,
  });
  typia.assert(attachment);
  TestValidator.equals("postId matches")(attachment.post_id)(post.id);

  // 7. Member queries the attachment list for their post
  const pageSize = 10;
  const requestBody: IPolEcoBoardAttachment.IRequest = {
    post_id: post.id,
    file_name: null,
    mime_type: null,
    created_after: null,
    created_before: null,
    author_member_id: null,
    page: 1,
    limit: pageSize,
  };
  const result = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: post.id,
    body: requestBody,
  });
  typia.assert(result);

  // 8. Validate response: data should contain the attached file only, with valid metadata.
  TestValidator.predicate("returns at least one attachment for post")(result.data.length >= 1);
  const found = result.data.find((a) => a.id === attachment.id);
  TestValidator.predicate("must find uploaded attachment in result")(!!found);
  if (found) {
    TestValidator.equals("postId matches")(found.post_id)(post.id);
    TestValidator.equals("author matches")(found.author_member_id)(member.id);
    TestValidator.equals("filename matches")(found.file_name)(attachmentBody.file_name);
    TestValidator.equals("mime type matches")(found.mime_type)(attachmentBody.mime_type);
    TestValidator.equals("file size matches")(found.file_size_bytes)(attachmentBody.file_size_bytes);
    TestValidator.predicate("uri present and non-empty")(!!found.uri);
  }

  // 9. Validate pagination fields
  TestValidator.equals("correct page returned")(result.pagination.current)(1);
  TestValidator.equals("limit matches page size")(result.pagination.limit)(pageSize);
  TestValidator.predicate("total at least 1 record")(result.pagination.records >= 1);
  TestValidator.predicate("total pages >= 1")(result.pagination.pages >= 1);

  // 10. Filtering: file_name filter (exact match)
  const filteredResult = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: post.id,
    body: {
      file_name: attachmentBody.file_name,
      post_id: post.id,
      mime_type: null,
      created_after: null,
      created_before: null,
      author_member_id: null,
      page: 1,
      limit: pageSize,
    },
  });
  typia.assert(filteredResult);
  TestValidator.predicate("filtered result contains the file")(filteredResult.data.some((a) => a.id === attachment.id));

  // 11. Filtering: non-matching file_name (should return none)
  const filteredNone = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: post.id,
    body: {
      file_name: "definitely_not_a_file_name____invalid.pdf",
      post_id: post.id,
      mime_type: null,
      created_after: null,
      created_before: null,
      author_member_id: null,
      page: 1,
      limit: pageSize,
    },
  });
  typia.assert(filteredNone);
  TestValidator.equals("zero results for bad file name")(filteredNone.data.length)(0);

  // 12. (Negative test) Permission – attachments for other posts aren't returned (by post_id boundary)
  const bogusResult = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: typia.random<string & tags.Format<"uuid">>(),
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      file_name: null,
      mime_type: null,
      created_after: null,
      created_before: null,
      author_member_id: null,
      page: 1,
      limit: pageSize,
    },
  });
  typia.assert(bogusResult);
  TestValidator.equals("no data for random/other post id")(bogusResult.data.length)(0);
}

