  const noAuthConn = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };
  await TestValidator.error("missing Authorization should error")(async () => {
    await api.functional.polEcoBoard.moderator.comments.reports.search(noAuthConn, {
