 *
 * Business context: Admin accounts must have unrestricted read access to all post edit records, regardless of editor or post author. This is essential for audit, compliance, and moderation. The test simulates the complete workflow: admin registration + login, member registration + login, post creation, post edit, and admin query of post edit detail, including negative cases.
 *
 * Steps:
 * 1. Register a new admin account and log in, acquiring full system permissions.
 * 2. Register a standard member and log in.
 * 3. As member, create a post (article) for editing history.
 * 4. As member, submit an edit (revision) to that post.
 * 5. Switch back to admin session, and use the admin endpoint to query the exact postEdit record by postId/postEditId. Validate that the admin can access full edit details (matching returned values with what was created).
 * 6. Attempt to query a non-existent postEditId as admin and validate a proper error (exception is thrown).
 * 7. (Optional) If deletion is supported, simulate a deleted post edit and confirm that admin receives a proper error when querying a deleted edit record.
 */
export async function test_api_post_edit_detail_admin_access(connection: api.IConnection) {
  // 1. Admin registration
