 *   5. Switch back to the admin session, query the post edit record by postId/postEditId, and validate the data is correct.
 *   6. Attempt to query a non-existent postEditId as admin and validate that an error is thrown (negative path).
 */
export async function test_api_post_edit_detail_admin_access(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
