  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Member registration
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplayName = RandomGenerator.name();
  const memberConsent = "v1";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: memberConsent,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Member login
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 5. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph(1)();
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Member submits an edit (revision)
  const editReason = "First revision for test.";
  const postEdit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: RandomGenerator.content(2)()(),
      edit_reason: editReason,
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(postEdit);

  // 7. Switch back to admin session
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 8. Admin queries the post edit detail
  const adminEditDetail = await api.functional.polEcoBoard.admin.posts.postEdits.atEdit(connection, {
    postId: post.id,
    postEditId: postEdit.id,
