  typia.assert(adminEditDetail);
  TestValidator.equals("edit record id matches")(adminEditDetail.id)(postEdit.id);
  TestValidator.equals("edit post id matches")(adminEditDetail.post_id)(post.id);
  TestValidator.equals("editor member id matches")(adminEditDetail.editor_member_id)(member.id);
  TestValidator.equals("edit body content matches")(adminEditDetail.edit_body)(postEdit.edit_body);
  TestValidator.equals("edit reason matches")(adminEditDetail.edit_reason)(editReason);

  // 9. Admin queries a non-existent postEditId and checks for error
  const fakeEditId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("admin cannot access a nonexistent post edit")(() =>
    api.functional.polEcoBoard.admin.posts.postEdits.atEdit(connection, {
      postId: post.id,
      postEditId: fakeEditId,
    }),
  );
