import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardIncident } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardIncident";
import type { IPageIPolEcoBoardIncident } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardIncident";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate search, pagination, and filtering of incidents as an admin.
 * 
 * 1. Register a new admin user with a unique email/password
 * 2. Login with those credentials (should set Authorization header for future requests)
 * 3. Create several incidents with diverse values:
 *    - Use at least 2 different categories and 2 statuses
 *    - Give some incidents unique incident_code
 *    - Set detected_at to recent, sequential timestamps for ordering
 * 4. Search all incidents with no filter and a small limit (e.g., limit 2, page 1)
 *    - Verify response: total record count matches num created, limit/page correct, data array matches returned limit, all fields correct, none deleted
 * 5. Search with incident_code filter (use one specific code from created set)
 *    - Verify response: only matching incident returned, total/pages = 1, fields match
 * 6. Search with status filter (one status used above)
 *    - Response must only contain incidents with that status
 * 7. Search with category filter (other category)
 *    - Response must only contain incidents with that category
 * 8. Search with paging to page 2 (using the same limit as before)
 *    - Response has the next page of data, correct number of records (if data available), fields/IDs distinct from previous page
 * 9. Confirm all returned incidents have correct field types/forms by typia.assert
 */
export async function test_api_incident_search_pagination_and_filters(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Login
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 3. Create incidents
  const categories = ["OUTAGE", "BREACH"];
  const statuses = ["OPEN", "RESOLVED"];
  const incidents = [];
  for (let i = 0; i < 5; i++) {
    const incident_code = `E2E_TEST_INCIDENT_${i}`;
    const category = categories[i % categories.length];
    const status = statuses[i % statuses.length];
    const detected_at = new Date(Date.now() - i * 1000 * 60).toISOString();
    const created = await api.functional.polEcoBoard.admin.incidents.create(connection, {
      body: {
        incident_code,
        category,
        status,
        description: `Test incident #${i}`,
        detected_at,
      } satisfies IPolEcoBoardIncident.ICreate,
    });
    typia.assert(created);
    incidents.push(created);
  }

  // 4. Search w/ no filters, page 1, limit 2
  const allRes = await api.functional.polEcoBoard.admin.incidents.search(connection, {
    body: {
      page: 1,
      limit: 2,
    } satisfies IPolEcoBoardIncident.IRequest,
  });
  typia.assert(allRes);
  TestValidator.equals("pagination: total records")(allRes.pagination.records)(incidents.length);
  TestValidator.equals("pagination: page number")(allRes.pagination.current)(1);
  TestValidator.equals("pagination: limit")(allRes.pagination.limit)(2);
  TestValidator.equals("data array length")(allRes.data.length)(2);

  for (const inc of allRes.data) {
    typia.assert(inc);
    TestValidator.equals("incident not deleted")(inc.deleted_at)(null);
  }

  // 5. Search by incident_code
  const filteredByCode = await api.functional.polEcoBoard.admin.incidents.search(connection, {
    body: {
      incident_code: incidents[0].incident_code,
    } satisfies IPolEcoBoardIncident.IRequest,
  });
  typia.assert(filteredByCode);
  TestValidator.equals("code filtered: 1 incident")(filteredByCode.data.length)(1);
  TestValidator.equals("code filtered: correct code")(filteredByCode.data[0].incident_code)(incidents[0].incident_code);

  // 6. Search by status
  const filteredByStatus = await api.functional.polEcoBoard.admin.incidents.search(connection, {
    body: {
      status: "OPEN",
    } satisfies IPolEcoBoardIncident.IRequest,
  });
  typia.assert(filteredByStatus);
  for (const inc of filteredByStatus.data) {
    TestValidator.equals("status is OPEN")(inc.status)("OPEN");
  }

  // 7. Search by category
  const filteredByCategory = await api.functional.polEcoBoard.admin.incidents.search(connection, {
    body: {
      category: "BREACH",
    } satisfies IPolEcoBoardIncident.IRequest,
  });
  typia.assert(filteredByCategory);
  for (const inc of filteredByCategory.data) {
    TestValidator.equals("category is BREACH")(inc.category)("BREACH");
  }

  // 8. Search with paging (page 2, limit 2)
  const secondPage = await api.functional.polEcoBoard.admin.incidents.search(connection, {
    body: {
      page: 2,
      limit: 2,
    } satisfies IPolEcoBoardIncident.IRequest,
  });
  typia.assert(secondPage);
  TestValidator.equals("pagination: page 2")(secondPage.pagination.current)(2);
  if (incidents.length > 2) {
    TestValidator.equals("data array length on page 2")(secondPage.data.length)(Math.min(2, incidents.length - 2));
  } else {
    TestValidator.equals("data array length on page 2")(secondPage.data.length)(0);
  }
  // Distinct records from page 1
  if (allRes.data[0] && secondPage.data[0]) {
    TestValidator.notEquals("distinct records on different pages")(secondPage.data[0].id)(allRes.data[0].id);
  }
}

