 * 3. Register a new moderator account. (POST /auth/moderator/register)
 * 4. As the authenticated admin, update the moderator's is_active status to false (revoke privileges) using PUT /polEcoBoard/admin/moderators/{moderatorId}.
 * 5. Validate that the returned moderator object reflects the new is_active value, and that the update and revoked_at timestamps are set correctly per audit requirements.
 * 6. Confirm that business-only fields (like appointed_by_admin_id) remain unchanged and the update is properly auditable.
 *
 * This ensures full privilege demotion logic works, status propagates, and audit trail is protected.
 */
export async function test_api_moderator_update_status_success(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegisterResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminRegisterResp);

  // 2. Login admin
  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResp);

  // 3. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(10);
  const displayName = RandomGenerator.name();
  const consentStatus = "2024-v1-privacy-policy";
  const moderatorRegisterResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegisterResp);

  // 4. Update moderator status via admin to is_active: false
  const updatedAt = new Date().toISOString();
  const updateResp = await api.functional.polEcoBoard.admin.moderators.update(connection, {
    moderatorId: moderatorRegisterResp.moderatorId,
    body: {
      is_active: false,
      revoked_at: updatedAt,
      updated_at: updatedAt,
    } satisfies IPolEcoBoardModerator.IUpdate,
  });
  typia.assert(updateResp);

  // 5. Validate update
  TestValidator.equals("moderatorId matches")(
    updateResp.id,
  )(moderatorRegisterResp.moderatorId);
  TestValidator.equals("is_active status update")(
    updateResp.is_active,
  )(false);
  TestValidator.equals("revoked_at set")(
    updateResp.revoked_at !== null && typeof updateResp.revoked_at === "string",
  )(true);
  TestValidator.equals("updated_at matches")(
    updateResp.updated_at,
  )(updatedAt);
}

