import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardEscalation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardEscalation";
import type { IPageIPolEcoBoardEscalation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardEscalation";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * E2E test for searching escalations as a moderator by various filters with permission checks and edge cases.
 *
 * 1. Register a moderator for authentication.
 * 2. Login as the moderator to obtain JWT.
 * 3. Create several escalation records assigned to the moderator via admin endpoint for test data.
 * 4. As moderator, search escalations:
 *   a. Retrieve all escalations (no filters).
 *   b. Filter by status (e.g., 'pending'), verify correct subset.
 *   c. Filter by actor (escalator_id), only own or others.
 *   d. Filter by rationale (reason field), verify match.
 *   e. Filter by date range (created_at_start / end), verify bounded results.
 *   f. Use pagination (page, limit), check returned limit, navigate pages.
 *   g. Attempt to use invalid filters/fields, expect validation errors.
 *   h. Search for non-existing data, expect empty results.
 *   i. Test with very high page/limit to confirm limiting & correctness.
 *   j. Edge: use filters that would match deleted/archived (deleted_at not null) and verify exclusion or inclusion.
 * 5. Validate all outputs via type assertion and business checks (correct visibility & filtering logic).
 * 6. Logout and test that search with insufficient privileges fails (permission error).
 */
export async function test_api_escalation_search_various_filters_moderator_access(
  connection: api.IConnection,
) {
  // Register and login as moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "StrongP@ssword123";
  const display_name = RandomGenerator.name();
  const consent_status = "v1.1-tos";
  // 1. Moderator register
  const modReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: { email, password, display_name, consent_status } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(modReg);
  // 2. Moderator login (should not be needed, but test authentication flow)
  const modLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(modLogin);
  // 3. Create test escalation records (simulating via admin endpoint)
  const escalationA = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: modReg.moderatorId,
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Auto test rationale for A",
      status: "pending"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationA);
  const escalationB = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: modReg.moderatorId,
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Another test rationale for B",
      status: "resolved"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationB);
  // Escalation, different actor (other moderator)
  const escalationC = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: typia.random<string & tags.Format<"uuid">>(),
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Edge rationale C",
      status: "rejected"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationC);
  // 4a. Retrieve all escalations (no filters)
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: {} satisfies IPolEcoBoardEscalation.IRequest,
    });
    typia.assert(res);
    TestValidator.predicate("at least our created records visible")(
      res.data.some(e => [escalationA.id, escalationB.id].includes(e.id))
    );
  }
  // 4b. Filter by status
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { status: "pending" } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("only pending results")(
      res.data.every(e => e.status === "pending")
    );
  }
  // 4c. Filter by escalator_id (ours)
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { escalator_id: modReg.moderatorId } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all escalations returned for our moderator id")(
      res.data.every(e => e.escalator_id === modReg.moderatorId)
    );
  }
  // 4d. Filter by rationale substring (reason)
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { reason: "rationale for A" } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("reasons containing substring")(
      res.data.every(e => e.reason.includes("rationale for A"))
    );
  }
  // 4e. Filter by date range (created_at_start, created_at_end)
  {
    const now = new Date();
    const before = new Date(now.getTime() - 60 * 1000).toISOString();
    const after = new Date(now.getTime() + 60 * 1000).toISOString();
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { created_at_start: before, created_at_end: after } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all inside date window")(
      res.data.every(e => e.created_at >= before && e.created_at <= after)
    );
  }
  // 4f. Pagination: limit, page
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { limit: 1, page: 1 } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("pagination limit applied")(res.data.length)(1);
    TestValidator.equals("pagination current page")(res.pagination.current)(1);
    TestValidator.equals("pagination limit")(res.pagination.limit)(1);
  }
  // 4g. Invalid fields: status with impossible value
  TestValidator.error("invalid status filter")(async () =>
    api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { status: "definitelynotastatus" } as any
    })
  );
  // 4h. No results (nonexistent moderation_action_id)
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { moderation_action_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("expect empty")(res.data.length)(0);
  }
  // 4i. Massive page/limit (test limiting)
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { limit: 1000, page: 100 } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("do not exceed limit")(res.data.length <= 1000);
  }
  // 4j. Edge: Filter for deleted (simulate, but we can't actually create deleted so ensure nothing returned)
  {
    const deletedAt = new Date(2000,1,1).toISOString();
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { created_at_end: deletedAt } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("no records created long ago have deleted_at")(res.data.length)(0);
  }
  // 6. Attempt with no authentication (remove auth header, expect error)
  const connNoAuth = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  TestValidator.error("permission error without auth")(
    async () => api.functional.polEcoBoard.moderator.escalations.search(connNoAuth, {
      body: {} satisfies IPolEcoBoardEscalation.IRequest
    })
  );
}

