import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * E2E test for moderator escalation search with various filters, pagination, visibility, input validation,
 * and permission checking.
 *
 * This test verifies that moderator accounts can search for escalations (compliance cases) with a variety
 * of filter conditions, and only receive results they are allowed to see. It covers searching by status,
 * actor, rationale substring, date range, pagination parameters, and handles edge cases such as invalid input,
 * empty result sets, and unauthenticated access attempts.
 *
 * Steps performed:
 * 1. Register a new moderator to act as test subject (to receive JWT and be actor for escalations)
 * 2. Login as the moderator (redundant, demonstrates auth flow)
 * 3. Create sample escalation records: two for this moderator as escalator, one for another "actor"
 * 4. Run all major search scenarios as the moderator:
 *    a. No filters (get all visible escalations)
 *    b. Filter by status, escalator_id, reason substring, created_at date range
 *    c. Pagination (page, limit) tested
 *    d. Invalid status raises error
 *    e. Nonexistent filter value returns empty
 *    f. Very large page/limit does not exceed available or max
 *    g. Attempt to filter for deleted/archived (always excluded in test data)
 * 5. Remove auth and verify permission is required for search
 */
export async function test_api_escalation_search_various_filters_moderator_access(
  connection: api.IConnection,
) {
  // 1. Register test moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "StrongP@ssword123";
  const display_name = RandomGenerator.name();
  const consent_status = "v1.1-tos";
  const modReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: { email, password, display_name, consent_status } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(modReg);

  // 2. Login as the moderator (optional - demonstrates full authentication loop)
  const modLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(modLogin);

  // 3. Create escalation cases via admin endpoint
  // Escalation for this moderator, pending status
  const escalationA = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: modReg.moderatorId,
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Auto test rationale for A",
      status: "pending"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationA);
  // Escalation for this moderator, resolved status
  const escalationB = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: modReg.moderatorId,
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Another test rationale for B",
      status: "resolved"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationB);
  // Escalation not for this moderator (ensures filter works)
  const escalationC = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: typia.random<string & tags.Format<"uuid">>(),
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Edge rationale C",
      status: "rejected"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationC);

  // ------------------------ SEARCH VERIFICATIONS --------------------------------
  // 4a. No filters: expect at least the ones for this moderator to be present
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: {} satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("at least our test escalations returned")(
      res.data.some(e => [escalationA.id, escalationB.id].includes(e.id))
    );
  }
  // 4b. Filter by status = 'pending'
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { status: "pending" } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all results are pending")(
      res.data.every(e => e.status === "pending")
    );
  }
  // 4c. Filter by escalator_id: must return only records for this id
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { escalator_id: modReg.moderatorId } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all by this moderator")(
      res.data.every(e => e.escalator_id === modReg.moderatorId)
    );
  }
  // 4d. Filter by partial reason (rationale substring)
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { reason: "rationale for A" } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("reason contains substring")(
      res.data.every(e => e.reason.includes("rationale for A"))
    );
  }
  // 4e. Filter by recent date range
  {
    const now = new Date();
    const before = new Date(now.getTime() - 60 * 1000).toISOString();
    const after = new Date(now.getTime() + 60 * 1000).toISOString();
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { created_at_start: before, created_at_end: after } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all within date range")(
      res.data.every(e => e.created_at >= before && e.created_at <= after)
    );
  }
  // 4f. Pagination: limit=1, page=1
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { limit: 1, page: 1 } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("pagination limit applied")(res.data.length)(1);
    TestValidator.equals("pagination current page")(res.pagination.current)(1);
    TestValidator.equals("pagination limit")(res.pagination.limit)(1);
  }
  // 4g. Invalid filter value for status
  TestValidator.error("invalid status value should error")(async () =>
    api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { status: "definitelynotastatus" } as any
    })
  );
  // 4h. No-result: random moderation_action_id
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { moderation_action_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("expect zero records")(res.data.length)(0);
  }
  // 4i. Very large pagination: confirm not oversized
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { limit: 1000, page: 100 } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("does not return too many records")(res.data.length <= 1000);
  }
  // 4j. Edge case: filter for deleted/archived. (Since we can't create deleted in this suite, simulate date before all creation)
  {
    const deletedDate = new Date(2000, 1, 1).toISOString();
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { created_at_end: deletedDate } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("records before epoch should be empty")(res.data.length)(0);
  }
  // 5. Permission: remove Authorization, error expected
  const connNoAuth = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  TestValidator.error("should get permission error when unauthenticated")(
    async () => api.functional.polEcoBoard.moderator.escalations.search(connNoAuth, {
      body: {} satisfies IPolEcoBoardEscalation.IRequest
    })
  );
}

