import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate successful and error-path admin deletion of a vote on a post.
 *
 * 1. Register and login admin; retain credentials for privileged operations.
 * 2. Admin creates a board category (IPolEcoBoardCategory.ICreate → IPolEcoBoardCategory).
 * 3. Admin creates a board in the category (IPolEcoBoardBoard.ICreate → IPolEcoBoardBoard).
 * 4. Register member (IPolEcoBoardMember.ICreate → IPolEcoBoardMember).
 * 5. Member login to acquire JWT for voting.
 * 6. Member creates post assigned to the created category (IPolEcoBoardPost.ICreate → IPolEcoBoardPost).
 * 7. Member submits a vote (upvote) for the post (IPolEcoBoardVote.ICreate → IPolEcoBoardVote).
 * 8. Admin logs back in (token switch).
 * 9. Admin deletes the member's vote for the post (void return).
 * 10. (Edge case) Admin attempts to delete the same vote again and expects an error (TestValidator.error).
 */
export async function test_api_admin_post_vote_delete_success_and_not_found(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegisterResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminRegisterResult);

  // 2. Admin login (obtain JWT)
  const adminLoginResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResult);

  // 3. Create board category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(16),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create board in category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphaNumeric(18),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(11);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.alphaNumeric(10),
      consent_status: "v1_policy_agreed",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 6. Member login to get token
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 7. Member creates a post in that category
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()().slice(0, 40),
      body: RandomGenerator.paragraph()() + RandomGenerator.alphaNumeric(100),
      tag_ids: [],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 8. Member votes on the post (upvote)
  const vote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 9. Admin logs back in
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 10. Admin deletes member's vote
  await api.functional.polEcoBoard.admin.posts.votes.erase(connection, {
    postId: post.id,
    voteId: vote.id,
  });

  // 11. Edge case: admin tries to delete same vote again → should error (not found)
  await TestValidator.error("deleting already deleted vote should fail")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.erase(connection, {
      postId: post.id,
      voteId: vote.id,
    });
  });
}

