import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates admin vote search, with pagination and filtering, for a specific post in polEcoBoard.
 *
 * This test covers the full admin workflow for reviewing votes on a post with various filters and paginated result handling.
 *
 * Steps:
 * 1. Register a new admin account and log in (admin authentication context)
 * 2. Register two member accounts and log in both (to generate different voter_member_id)
 * 3. Member 1 creates a post under a random category
 * 4. Member 1 upvotes the post
 * 5. Member 2 downvotes the post
 * 6. Additional votes from extra members for pagination
 * 7. Admin searches all votes for the post (no filter) and checks that all votes are returned and valid
 * 8. Admin filters by voter_member_id and vote_value to verify filtering
 * 9. Test pagination with low limit; validate coverage and non-overlap between pages
 */
export async function test_api_post_votes_admin_search_success_and_filters(connection: api.IConnection) {
  // --- 1. Register admin account ---
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10);
  const adminSignUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResult);

  // --- 2. Log in as admin ---
  const adminSignInResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignInResult);

  // --- 3. Register Member 1 & log in ---
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1Password = RandomGenerator.alphaNumeric(10);
  const member1SignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(member1SignUpResult);

  const member1SignInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(member1SignInResult);

  // --- 4. Register Member 2 & log in ---
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Password = RandomGenerator.alphaNumeric(10);
  const member2SignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(member2SignUpResult);

  const member2SignInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(member2SignInResult);

  // --- 5. Member 1 creates a post ---
  // Assume a random valid category UUID and no tags/attachments for simplicity
  const postCategoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(15);
  const postBody = RandomGenerator.content()()(100);
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: postCategoryId,
      title: postTitle,
      body: postBody,
      tag_ids: [],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(createdPost);

  // For gathering correct voter_member_id values, retrieve member1's UUID from post author afterward
  const postId = createdPost.id;
  const authorId = createdPost.author_member_id;

  // --- 6. Member 1 (author) upvotes their post ---
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
