import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAntiSpamEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAntiSpamEvent";
import type { IPageIPolEcoBoardAntiSpamEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAntiSpamEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates the search, filtering, and pagination of anti-spam events by admin, with access control enforcement.
 *
 * This test ensures:
 * - Admin can register and login for authorized access.
 * - At least one anti-spam event exists for meaningful testing.
 * - Search with specific filters (provider_key, operation, action_taken, score range, appeal_requested, created_from/created_to)
 *   only returns events matching the filter criteria.
 * - Pagination parameters (limit, page) work as expected.
 * - Using unmatched or non-existent filter parameters yields no results.
 * - Unauthorized (non-admin) search attempts are denied.
 *
 * Test steps:
 * 1. Register a new admin (random email & password).
 * 2. Login as the admin to obtain credentials.
 * 3. Create a known anti-spam event (store its values for later filtering).
 * 4. Use search API with filters that should match the created event and validate returned events.
 * 5. Use search with edge-case filters that should yield no results.
 * 6. Test pagination correctness by requesting page 1 with limit 1 and ensure only one event is returned, and correct page meta info.
 * 7. Logout (or clear admin auth), then attempt the search as unauthorized/non-admin and validate failure.
 */
export async function test_api_antispam_event_admin_search_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin (sets Authorization header in connection)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a known anti-spam event
  const nowIso = new Date().toISOString();
  const antiSpamEventInput: IPolEcoBoardAntiSpamEvent.ICreate = {
    provider_key: RandomGenerator.alphabets(7),
    operation: "content_submit",
    content_hash: RandomGenerator.alphaNumeric(32),
    score: 0.8,
    action_taken: "blocked",
    appeal_requested: false,
    created_at: nowIso,
  };
  const antiSpamEvent = await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, {
    body: antiSpamEventInput,
  });
  typia.assert(antiSpamEvent);

  // 4. Search with filters that match the created event
  const searchResp = await api.functional.polEcoBoard.admin.antiSpamEvents.search(connection, {
    body: {
      provider_key: antiSpamEventInput.provider_key,
      operation: antiSpamEventInput.operation,
      action_taken: antiSpamEventInput.action_taken,
      score_min: 0.7,
      score_max: 1.0,
      appeal_requested: antiSpamEventInput.appeal_requested,
      created_from: nowIso,
      created_to: nowIso,
      limit: 10,
      page: 1,
    } satisfies IPolEcoBoardAntiSpamEvent.IRequest,
  });
  typia.assert(searchResp);
  // All returned events should match the filter
  for (const ev of searchResp.data) {
    TestValidator.equals("provider_key")(ev.provider_key)(antiSpamEventInput.provider_key);
    TestValidator.equals("operation")(ev.operation)(antiSpamEventInput.operation);
    TestValidator.equals("action_taken")(ev.action_taken)(antiSpamEventInput.action_taken);
    TestValidator.predicate("score min")(ev.score >= 0.7);
    TestValidator.predicate("score max")(ev.score <= 1.0);
    TestValidator.equals("appeal_requested")(ev.appeal_requested)(antiSpamEventInput.appeal_requested);
    TestValidator.equals("created_at")(ev.created_at)(nowIso);
  }

  // 5. Search with filters that will match nothing
  const noneResp = await api.functional.polEcoBoard.admin.antiSpamEvents.search(connection, {
    body: {
      provider_key: "nonexistent_provider",
    },
  });
  typia.assert(noneResp);
  TestValidator.equals("empty result")(noneResp.data.length)(0);

  // 6. Pagination: request page 1, limit 1
  const pagedResp = await api.functional.polEcoBoard.admin.antiSpamEvents.search(connection, {
    body: {
      limit: 1,
      page: 1,
    },
  });
  typia.assert(pagedResp);
  TestValidator.equals("paginated result length")(pagedResp.data.length)(Math.min(pagedResp.pagination.records, 1));
  TestValidator.equals("pagination current")(pagedResp.pagination.current)(1);
  TestValidator.equals("pagination limit")(pagedResp.pagination.limit)(1);

  // 7. Attempt unauthorized search (simulate by removing Authorization header)
  const unauthorizedConnection = {
    ...connection,
    headers: {
      ...connection.headers,
    },
  };
  if (unauthorizedConnection.headers && unauthorizedConnection.headers.Authorization) {
    delete unauthorizedConnection.headers.Authorization;
  }
  await TestValidator.error("unauthorized access should fail")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.search(unauthorizedConnection, {
      body: {},
    });
  });
}

