import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test moderator voting on a post (upvote and downvote, and duplicate-vote prevention)
 *
 * Business context: Moderators can vote on posts (upvote/downvote) for content curation and moderation. They must not be able to vote more than once (duplicate-vote prevention). Moderators use their privilege to participate in board voting, based on their credentials. Members create posts (only they can author), and then moderators interact with the post to cast votes.
 *
 * This workflow verifies:
 *  - Moderator registration and login (credentials stored in connection headers)
 *  - Member registration/login and post creation (because posts must exist to be voted on)
 *  - Moderator can upvote and downvote (vote_value 1 and -1, respectively) on an arbitrary post
 *  - Duplicate voting attempts by the same moderator fail as business rules require (only one vote per post per moderator)
 *
 * Steps:
 * 1. Register a moderator account
 * 2. Log in as that moderator
 * 3. Register a member to author a post
 * 4. Log in as that member
 * 5. Create a post
 * 6. Log in as moderator
 * 7. Cast an upvote (vote_value:1) on the post
 * 8. Confirm the upvote is successful and properly recorded
 * 9. Attempt to upvote again (should fail, duplicate-vote not allowed)
 * 10. Delete all votes as necessary (if API allows, not implementable if function not provided)
 * 11. Then, cast a downvote (vote_value:-1) after removing upvote if possible, otherwise on a new post
 * 12. Attempt to downvote again (should fail)
 * 13. Confirm correct business logic is enforced for both voting actions
 */
export async function test_api_post_vote_creation_moderator_success(connection: api.IConnection) {
  // 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderatorPass1102!";
  const moderatorDisplayName = RandomGenerator.name();
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: "v1" // assuming arbitrary string as version identifier
    }
  });
  // 2. Log in as moderator
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    }
  });
  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "memberPass1102$";
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    }
  });
  // 4. Log in as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    }
  });
  // 5. Create a post (category_id required but no dedicated API for categories, generate a random UUID)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()().substring(0, 30);
  const postBody = RandomGenerator.content()()().substring(0, 100);
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
    }
  });
  typia.assert(post);
  // 6. Log back in as moderator (ensure proper token)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    }
  });
  // 7. Moderator upvotes the post
  const voteUp = await api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 }
  });
  typia.assert(voteUp);
  TestValidator.equals("vote linkage - upvote")(voteUp.post_id)(post.id);
  TestValidator.equals("vote_value - up")(voteUp.vote_value)(1);
  // 8. Try upvoting again (should fail, duplicate-vote not allowed)
  await TestValidator.error("duplicate upvote fails")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post.id,
      body: { vote_value: 1 }
    })
  );
  // 9. (Cannot delete vote if no API)
  // 10. Try to downvote same post (should also fail, only one vote per moderator per post)
  await TestValidator.error("duplicate vote with different value fails")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post.id,
      body: { vote_value: -1 }
    })
  );
  // 11. Create a new post to allow another vote kind
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    }
  });
  const post2Title = RandomGenerator.paragraph()().substring(0, 30);
  const post2Body = RandomGenerator.content()()().substring(0, 100);
  const post2 = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: post2Title,
      body: post2Body,
    }
  });
  typia.assert(post2);
  // 12. Switch to moderator again
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    }
  });
  // 13. Moderator downvotes on new post
  const voteDown = await api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
    postId: post2.id,
    body: { vote_value: -1 }
  });
  typia.assert(voteDown);
  TestValidator.equals("vote linkage - downvote")(voteDown.post_id)(post2.id);
  TestValidator.equals("vote_value - down")(voteDown.vote_value)(-1);
  // 14. Try to downvote again (should fail)
  await TestValidator.error("duplicate downvote fails")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post2.id,
      body: { vote_value: -1 }
    })
  );
  // 15. Try upvoting after already downvoted (should fail)
  await TestValidator.error("switch vote from down to up fails")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post2.id,
      body: { vote_value: 1 }
    })
  );
}

