import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IPageIPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardGuest";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for admin-privileged guest session search using advanced filters.
 *
 * This test validates the following business flow for polEcoBoard admin guest session search:
 *
 * 1. Register a new admin account with unique email and compliant password (min 8 chars)
 * 2. Log in with the same admin credentials to obtain authorization for further actions
 * 3. Using valid admin session, perform a PATCH search on /polEcoBoard/admin/guests with various filter combinations:
 *    - date range (created_after, created_before)
 *    - consent_status (string code)
 *    - device_fingerprint (exact or partial)
 *    - pagination (page, limit)
 *    - sorting config (sort_field, sort_direction)
 *
 * 4. Validate:
 *    - Returns with correct pagination structure (pagination object populated)
 *    - Data array contains guest session objects, each with required fields (id, ip_address, consent_status, etc.)
 *    - Filtering and pagination work as specified (e.g., limit respected, content fits filter criteria)
 *    - All data shape complies with IPolEcoBoardGuest and IPageIPolEcoBoardGuest DTOs
 *
 * This ensures admin-only access, complete data visibility, and proper functioning of guest analytics API for compliance and monitoring.
 */
export async function test_api_guest_session_search_admin_success(connection: api.IConnection) {
  // 1. Register as admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(registerResp);

  // 2. Log in as admin
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(loginResp);

  // 3. PATCH search with various filters as admin
  // We'll generate combined filters: date range, consent status, device, paging, sort
  const now = new Date();
  const created_after = new Date(now.getTime() - 86400000 * 10).toISOString(); // 10 days ago
  const created_before = now.toISOString();
  const filterBody: IPolEcoBoardGuest.IRequest = {
    consent_status: RandomGenerator.alphaNumeric(6),
    ip_address: undefined, // left blank
    device_fingerprint: RandomGenerator.alphaNumeric(10),
    created_after,
    created_before,
    page: 1,
    limit: 5,
    sort_field: 'created_at',
    sort_direction: 'desc',
  };
  const output = await api.functional.polEcoBoard.admin.guests.search(connection, {
    body: filterBody
  });
  typia.assert(output);

  // 4. Validate output pagination & data
  TestValidator.equals('pagination type')(typeof output.pagination, 'object');
  TestValidator.predicate('pagination current is int')(Number.isInteger(output.pagination.current));
  TestValidator.predicate('pagination limit is int')(Number.isInteger(output.pagination.limit));
  TestValidator.predicate('pagination records is int')(Number.isInteger(output.pagination.records));
  TestValidator.predicate('pagination pages is int')(Number.isInteger(output.pagination.pages));

  TestValidator.predicate('data array')(Array.isArray(output.data));
  for (const guest of output.data) {
    typia.assert(guest);
    TestValidator.predicate('guest has UUID')(typeof guest.id === 'string' && guest.id.length > 0);
    TestValidator.predicate('ip_address present')(typeof guest.ip_address === 'string');
    TestValidator.predicate('consent_status present')(typeof guest.consent_status === 'string');
    TestValidator.predicate('created_at format')(typeof guest.created_at === 'string');
    TestValidator.predicate('updated_at format')(typeof guest.updated_at === 'string');
  }
}

