import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IPageIPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardGuest";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate successful admin-privileged search for paginated guest sessions with advanced filters.
 *
 * This test covers the complete data access pipeline for polEcoBoard admin guest session search:
 *
 * 1. Register a new admin user with a unique email and a valid password (min 8 chars).
 * 2. Log in as the newly created admin; this ensures correct authorization for the protected search endpoint.
 * 3. Using the valid admin session, perform a PATCH search on /polEcoBoard/admin/guests, setting various search and filter options:
 *    - Filter by date range (created_after, created_before)
 *    - Filter by consent_status (arbitrary string code)
 *    - Filter by device_fingerprint
 *    - Control pagination (page, limit)
 *    - Sort (sort_field, sort_direction)
 *
 * 4. Assert:
 *    - The output contains a valid pagination object (all required properties with expected types)
 *    - The data array is present, and every item matches the IPolEcoBoardGuest contract
 *    - Key guest properties (IP address, consent, timestamps) are surfaced and type-correct
 *    - (Optional) All business roles and restrictions are respected (admin-only API path)
 *
 * This ensures the API honors all admin workflow requirements, advanced search capability, and proper secure data flow and shape.
 */
export async function test_api_guest_session_search_admin_success(connection: api.IConnection) {
  // 1. Register admin credentials with valid unique email and password
  const adminEmail: string = typia.random<string & tags.Format<'email'>>();
  const adminPassword: string = RandomGenerator.alphaNumeric(16); // 16-char alphanumeric
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResp);

  // 2. Admin login for session establishment
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);

  // 3. Perform a guest sessions search as admin, using advanced search filters & pagination
  const now = new Date();
  const created_after = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString(); // 7 days ago
  const created_before = now.toISOString();
  const consent_status = RandomGenerator.alphaNumeric(6);
  const device_fingerprint = RandomGenerator.alphaNumeric(10);
  const requestBody: IPolEcoBoardGuest.IRequest = {
    consent_status,
    device_fingerprint,
    created_after,
    created_before,
    page: 1,
    limit: 3,
    sort_field: 'created_at',
    sort_direction: 'desc',
  };
  const result = await api.functional.polEcoBoard.admin.guests.search(connection, { body: requestBody });
  typia.assert(result);

  // 4. Validate pagination object structure and data list
  TestValidator.predicate('pagination object')(typeof result.pagination === 'object' && result.pagination !== null);
  TestValidator.predicate('pagination.current integer')(Number.isInteger(result.pagination.current));
  TestValidator.predicate('pagination.limit integer')(Number.isInteger(result.pagination.limit));
  TestValidator.predicate('pagination.records integer')(Number.isInteger(result.pagination.records));
  TestValidator.predicate('pagination.pages integer')(Number.isInteger(result.pagination.pages));

  TestValidator.predicate('data array type')(Array.isArray(result.data));
  for (const guest of result.data) {
    typia.assert(guest);
    TestValidator.predicate('guest id UUID')(typeof guest.id === 'string' && guest.id.length > 0);
    TestValidator.predicate('ip_address')(typeof guest.ip_address === 'string' && guest.ip_address.length > 0);
    TestValidator.predicate('consent_status')(typeof guest.consent_status === 'string' && guest.consent_status.length > 0);
    TestValidator.predicate('created_at format')(typeof guest.created_at === 'string');
    TestValidator.predicate('updated_at format')(typeof guest.updated_at === 'string');
  }
}

