/**
 * Validate that an admin user can retrieve the details of an appeal record after the full appeal workflow.
 *
 * This test simulates an end-to-end business workflow for appeal retrieval:
 * 1. Register a new admin account with unique email and password.
 * 2. Login as admin (token is handled by SDK, no manual management).
 * 3. Register a new member (who will act as the appellant).
 * 4. Login as the member (needed to submit the appeal).
 * 5. Post a moderation action (with report ID, operator as the member).
 * 6. As the member, submit an appeal for the created moderation action.
 * 7. Switch back to admin (login again).
 * 8. Retrieve the appeal by its appealId via the admin endpoint.
 * 9. Assert the key fields of the returned appeal match what was stored, proving admin access works as designed.
 *
 * All API interaction uses only actual provided endpoints and DTOs, with random/generated data as required.
 */
export async function test_api_appeal_detail_access_admin_success(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResponse);

  // 2. Login as admin (token autocapture by SDK)
  const adminSignInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignInResponse);

  // 3. Register new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // Using plain password as test, as hash API is not provided
      display_name: RandomGenerator.name(),
      consent_status: "agreed",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Login as member to get session
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 5. Create a moderation action
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: member.id, // For this test, member acts as the moderator/operator
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "violation of rules",
      outcome: "removed",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 6. Member creates an appeal on the moderation action
  const appeal = await api.functional.polEcoBoard.member.appeals.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      appellant_id: member.id,
      reason: RandomGenerator.paragraph()(200),
      status: "pending",
    } satisfies IPolEcoBoardAppeal.ICreate,
  });
  typia.assert(appeal);

  // 7. Switch back to admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 8. Retrieve the appeal as admin by ID
  const result = await api.functional.polEcoBoard.admin.appeals.at(connection, {
    appealId: appeal.id,
  });
  typia.assert(result);

  // 9. Validate main properties match persisted appeal; timestamps and reviewer/outcome may vary depending on business rules
  TestValidator.equals("appeal id")(result.id)(appeal.id);
  TestValidator.equals("moderation action id")(result.moderation_action_id)(appeal.moderation_action_id);
  TestValidator.equals("appellant id")(result.appellant_id)(appeal.appellant_id);
  TestValidator.equals("reason")(result.reason)(appeal.reason);
  TestValidator.equals("status")(result.status)(appeal.status);
}

