import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can retrieve the full edit history of any post, regardless of authorship, for auditing purposes.
 *
 * This test simulates a complete realistic lifecycle:
 * 1. Register and log in as a new member
 * 2. As that member, create a new post
 * 3. Edit (update) that post at least once to generate edit history
 * 4. Register (or log in as) a moderator
 * 5. As the moderator, retrieve the edit history for the post just edited
 * 6. Validate that the returned edit history includes all post edit snapshots, including the initial creation and subsequent edit(s)
 *
 * This ensures compliance that moderators can audit post changes regardless of the author, and that the history is complete and accurate.
 */
export async function test_api_post_edit_history_moderator_full_access(connection: api.IConnection) {
  // 1. Register as a new member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberPassword = "ModeratePassw0rd!";
  const memberSignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUpResult);

  // 2. Login as the member (sets Authorization)
  const memberSignInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberSignInResult);

  // 3. Create a new post as the member
  const postCreateInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<'uuid'>>(),
    title: RandomGenerator.paragraph()(1, 1),
    body: RandomGenerator.content()(2, 6)(),
    tag_ids: null, // optional, set as null
    attachments: null,
  };
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postCreateInput,
  });
  typia.assert(createdPost);

  // 4. Edit the post to generate history
  const updateTitle = RandomGenerator.paragraph()(1, 1) + " (edited)";
  const updateBody = RandomGenerator.content()(3, 8)() + " #edited";
  const updatedPost = await api.functional.polEcoBoard.member.posts.update(connection, {
    postId: createdPost.id,
    body: {
      title: updateTitle,
      body: updateBody,
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.IUpdate,
  });
  typia.assert(updatedPost);

  // 5. Register a moderator account
  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderatorPassword = "Moderator123!";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "accepted_v1";
  const modSignUpResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(modSignUpResult);

  // 6. Login as the moderator (sets moderator Authorization header)
  const modSignInResult = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(modSignInResult);

  // 7. As moderator, retrieve the edit history for the post
  const editHistoryPage = await api.functional.polEcoBoard.moderator.posts.postEdits.searchEditHistory(connection, {
    postId: createdPost.id,
    body: {}, // empty filter, should retrieve all
  });
  typia.assert(editHistoryPage);
  TestValidator.predicate("Edit history must contain at least two snapshots")(editHistoryPage.data.length >= 2);
  // Optional: further validation of returned edit records
  const containsOriginal = editHistoryPage.data.some(edit => edit.edit_body === postCreateInput.body);
  const containsEdit = editHistoryPage.data.some(edit => edit.edit_body === updateBody);
  TestValidator.predicate("Original post snapshot must exist")(containsOriginal);
  TestValidator.predicate("Edited post snapshot must exist")(containsEdit);
}

