/**
 * Test retrieving a paginated list of tags assigned to a post for both public and private boards.
 *
 * Ensures:
 * - Access control for public and private boards
 * - Correct tag assignment and retrieval
 * - Pagination and filter correctness
 *
 * Business workflow:
 * 1. Create a board category
 * 2. Create a public board and a private board under the category
 * 3. Register a member
 * 4. Member creates a post on each board
 * 5. Search tags to obtain at least two tag UUIDs
 * 6. Assign two tags to each post via moderator endpoint
 * 7. For PUBLIC post:
 *      a. Retrieve tags as unauthenticated user and validate correctness
 *      b. Check pagination/limit
 * 8. For PRIVATE post:
 *      a. Attempt retrieval unauthenticated (should error)
 *      b. Retrieve as the member and validate results
 */
export async function test_api_post_tag_list_retrieval_public_private_post(
  connection: api.IConnection
) {
  // 1. Create board category
  const category = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.alphaNumeric(24),
        display_order: typia.random<number & tags.Type<"int32">>(),
      },
    }
  );
  typia.assert(category);

  // 2. Create a public board and a private board
  const publicBoard = await api.functional.polEcoBoard.admin.boards.create(
    connection,
    {
      body: {
        pol_eco_board_category_id: category.id,
        name: RandomGenerator.alphaNumeric(12),
        code: RandomGenerator.alphaNumeric(8).toLowerCase(),
        description: RandomGenerator.alphaNumeric(20),
        is_public: true,
        is_archived: false,
        display_order: typia.random<number & tags.Type<"int32">>(),
      },
    }
  );
  typia.assert(publicBoard);

  const privateBoard = await api.functional.polEcoBoard.admin.boards.create(
    connection,
    {
      body: {
        pol_eco_board_category_id: category.id,
        name: RandomGenerator.alphaNumeric(12),
        code: RandomGenerator.alphaNumeric(8).toLowerCase(),
        description: RandomGenerator.alphaNumeric(20),
        is_public: false,
        is_archived: false,
        display_order: typia.random<number & tags.Type<"int32">>(),
      },
    }
  );
  typia.assert(privateBoard);

  // 3. Register member
  const memberEmail = `${RandomGenerator.alphaNumeric(8)}@test.com`;
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.alphaNumeric(10),
      profile_image_uri: null,
      consent_status: "v1-consent",
    },
  });
  typia.assert(member);

  // 4. Member creates post on public board
  // (Assuming after member create, connection uses member identity)
  // If not, an explicit member login API would be needed
  const publicPost = await api.functional.polEcoBoard.member.posts.create(
    connection,
    {
      body: {
        category_id: category.id,
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.paragraph()(40),
        tag_ids: null,
        attachments: null,
      },
    }
  );
  typia.assert(publicPost);

  // Member creates post on private board
  const privatePost = await api.functional.polEcoBoard.member.posts.create(
    connection,
    {
      body: {
        category_id: category.id,
        title: RandomGenerator.paragraph()(12),
        body: RandomGenerator.paragraph()(40),
        tag_ids: null,
        attachments: null,
      },
    }
  );
  typia.assert(privatePost);

  // 5. Search tags to obtain two tag UUIDs
  const tagsPage = await api.functional.polEcoBoard.tags.search(connection, {
    body: {
      limit: 10,
      page: 1,
    },
  });
  typia.assert(tagsPage);
  TestValidator.predicate("enough tags")(tagsPage.data.length >= 2);
  const tag1 = tagsPage.data[0];
  const tag2 = tagsPage.data[1];

  // 6. Assign two tags to each post via moderator endpoint
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: publicPost.id,
    body: { tag_id: tag1.id },
  });
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: publicPost.id,
    body: { tag_id: tag2.id },
  });
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: privatePost.id,
    body: { tag_id: tag1.id },
  });
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: privatePost.id,
    body: { tag_id: tag2.id },
  });

  // 7. Retrieve tags for PUBLIC post as unauthenticated user
  {
    const output = await api.functional.polEcoBoard.posts.postTags.search(connection, {
      postId: publicPost.id,
      body: {
        page: 1,
        limit: 2,
      },
    });
    typia.assert(output);
    TestValidator.equals("public post tag count")(output.data.length)(2);
    TestValidator.equals("pagination count")(output.pagination.limit)(2);
    TestValidator.equals("tag-ids for public post")(
      output.data.map((t) => t.tag_id).sort()
    )([
      tag1.id,
      tag2.id,
    ].sort());
  }

  // 8. Retrieve tags for PRIVATE post
  // 8-a. As unauthenticated: expect error
  await TestValidator.error("private post tag listing as unauthenticated fails")(
    async () => {
      await api.functional.polEcoBoard.posts.postTags.search(connection, {
        postId: privatePost.id,
        body: {
          page: 1,
          limit: 2,
        },
      });
    }
  );
  // 8-b. As member (should succeed)
  const privateTags = await api.functional.polEcoBoard.posts.postTags.search(
    connection,
    {
      postId: privatePost.id,
      body: {
        page: 1,
        limit: 2,
      },
    }
  );
  typia.assert(privateTags);
  TestValidator.equals("private post tag count")(privateTags.data.length)(2);
  TestValidator.equals("pagination count")(privateTags.pagination.limit)(2);
  TestValidator.equals("tag-ids for private post")(
    privateTags.data.map((t) => t.tag_id).sort()
  )([
    tag1.id,
    tag2.id,
  ].sort());
}

