import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardSanction";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin can retrieve the full details of a sanction by ID (with business compliance) and ensure proper permissions and not-found logic.
 *
 * Scenario steps:
 * 1. Register a new admin (using random unique credentials).
 * 2. Login as that admin for authorization/session.
 * 3. Create a moderation action (provides moderation_action_id).
 * 4. Create a valid sanction referencing the newly created moderation action and a target user (using random uuid for user).
 * 5. Retrieve the just-created sanction by its sanctionId as admin and validate all returned fields are present and business accurate (type, linkages, rationale, status, audit fields).
 * 6. Check access control by logging out (simulate no admin) or passing empty connection/headers and attempting to get the sanction detail - expect business error due to missing/invalid permissions.
 * 7. Attempt to fetch a sanction with a non-existent sanctionId (random UUID not used in system) - ensure the API returns not-found according to business error handling.
 * 8. Delete (soft delete) the sanction (simulate by directly setting the deleted_at field if possible, but if API not provided, skip actual deletion) and try to retrieve it, confirming the business error for accessing deleted sanctions or not-found semantics per API behavior.
 * (If soft/hard delete endpoint is not available, skip actual deletion step, but always check the not-found handler.)
 */
export async function test_api_sanction_detail_admin_access_not_found_and_permission(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Login as that admin
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Create a moderation action
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const operatorId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: operatorId,
      action_type: "warn",
      target_type: "user",
      status: "completed",
      rationale: "Automated compliance violation.",
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 4. Create a sanction referencing the moderation action and a random sanctioned user
  const sanctionedUserId = typia.random<string & tags.Format<"uuid">>();
  const startAt = new Date().toISOString();
  const endAt = null; // indefinite ban
  const createSanctionBody = {
    moderation_action_id: moderationAction.id,
    sanctioned_user_id: sanctionedUserId,
    sanction_type: "ban",
    status: "active",
    rationale: "Serious terms of use violation.",
    start_at: startAt,
    end_at: endAt
  } satisfies IPolEcoBoardSanction.ICreate;
  const sanction = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: createSanctionBody,
  });
  typia.assert(sanction);

  // 5. Retrieve the created sanction as admin and verify business fields
  const fetchedSanction = await api.functional.polEcoBoard.admin.sanctions.at(connection, {
    sanctionId: sanction.id,
  });
  typia.assert(fetchedSanction);
  TestValidator.equals("sanction.id matches")(fetchedSanction.id)(sanction.id);
  TestValidator.equals("moderation_action_id matches")(fetchedSanction.moderation_action_id)(createSanctionBody.moderation_action_id);
  TestValidator.equals("sanctioned_user_id matches")(fetchedSanction.sanctioned_user_id)(sanctionedUserId);
  TestValidator.equals("sanction_type matches")(fetchedSanction.sanction_type)(createSanctionBody.sanction_type);
  TestValidator.equals("status matches")(fetchedSanction.status)(createSanctionBody.status);
  TestValidator.equals("rationale matches")(fetchedSanction.rationale)(createSanctionBody.rationale);
  TestValidator.equals("start_at matches")(fetchedSanction.start_at)(createSanctionBody.start_at);
  TestValidator.equals("end_at matches")(fetchedSanction.end_at)(createSanctionBody.end_at);
  TestValidator.predicate("must have created_at timestamp")(!!fetchedSanction.created_at);
  TestValidator.predicate("must have updated_at timestamp")(!!fetchedSanction.updated_at);
  TestValidator.equals("not deleted")(fetchedSanction.deleted_at)(null);

  // 6. Attempt to access as non-admin (simulate invalid headers/no auth)
  const unauthConnection = { ...connection, headers: {}};
  await TestValidator.error("unauthorized access fails")(async () => {
    await api.functional.polEcoBoard.admin.sanctions.at(unauthConnection, { sanctionId: sanction.id });
  });

  // 7. Attempt to fetch a non-existent sanctionId (random uuid)
  const randomSanctionId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for non-existent sanctionId")(async () => {
    await api.functional.polEcoBoard.admin.sanctions.at(connection, { sanctionId: randomSanctionId });
  });

  // 8. Deletion/business not-found for deleted sanctions: only possible if delete endpoint is present (not available), so skip deletion, but confirm workflow covered above
}

