  typia.assert(searchAll);
  // Validate all returned records are for this moderator
  for (const pref of searchAll.data)
    TestValidator.equals("all prefs belong to moderator")(pref.member_id)(moderatorId);
  // Validate full set was returned
  TestValidator.equals("all prefs returned")(searchAll.data.length)(createdPrefs.length);
  TestValidator.equals("pagination records")(searchAll.pagination.records)(createdPrefs.length);

  // 4b. Search by event_type
  for (const eventType of eventTypes) {
    const filteredByEvent = createdPrefs.filter(x => x.event_type === eventType);
    const searchByEvent = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        event_type: eventType,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByEvent);
    TestValidator.equals(`event_type '${eventType}' filter count`)(searchByEvent.data.length)(filteredByEvent.length);
    for (const pref of searchByEvent.data) {
      TestValidator.equals("event_type matches")(pref.event_type)(eventType);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4c. Search by channel
  for (const channel of channels) {
    const filteredByChannel = createdPrefs.filter(x => x.channel === channel);
    const searchByChannel = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        channel,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByChannel);
    TestValidator.equals(`channel '${channel}' filter count`)(searchByChannel.data.length)(filteredByChannel.length);
    for (const pref of searchByChannel.data) {
      TestValidator.equals("channel matches")(pref.channel)(channel);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4d. Search by opt_in status
  for (const optIn of optInMatrix) {
    const filteredByOpt = createdPrefs.filter(x => x.opt_in === optIn);
    const searchByOpt = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        opt_in: optIn,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByOpt);
    TestValidator.equals(`opt_in='${optIn}' filter count`)(searchByOpt.data.length)(filteredByOpt.length);
    for (const pref of searchByOpt.data) {
      TestValidator.equals("opt_in matches")(pref.opt_in)(optIn);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4e. Pagination edge: page through with small limit, check for correct non-overlapping, correct union of all ids
  const pagedLimit = 5;
  const totalPages = Math.ceil(createdPrefs.length / pagedLimit);
  let allPagedIds: string[] = [];
  for (let page = 1; page <= totalPages; page++) {
    const pageResult = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        page,
        limit: pagedLimit,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(pageResult);
    for (const pref of pageResult.data) {
      TestValidator.equals("member_id matches in paging")(pref.member_id)(moderatorId);
      // Ids must not repeat across pages
      TestValidator.predicate(`unique id in pages: ${pref.id}`)(!allPagedIds.includes(pref.id));
      allPagedIds.push(pref.id);
    }
  }
  // The union of paged ids must cover all
  TestValidator.equals("paged id union covers all")(allPagedIds.length)(createdPrefs.length);
  for (const id of allPagedIds)
    TestValidator.predicate(`id found in createdPrefs`)(createdPrefs.some(p => p.id === id));
}

