import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validates that a moderator can successfully add a file attachment to any board post, including posts not authored by themselves (privilege check).
 *
 * This test covers the entire workflow:
 * 1. Register a member account who will author the original post.
 * 2. Login as that member and create a post under their identity.
 * 3. Register a new moderator account (different user, separate credentials).
 * 4. Login as the moderator.
 * 5. While authenticated as moderator, add a file attachment to the member's post using the moderator endpoint.
 * 6. Confirm the attachment creation is successful, that audit fields (author_member_id, post_id etc.) are set as required, and the moderator's ID is reflected as uploader.
 * 7. Validate the return object for business correctness and required metadata.
 *
 * Prerequisites handled:
 * - Member and moderator registrations, unique (random) emails
 * - Test post creation by the correct author-member
 * - Proper role switching for context
 *
 * Validates privilege elevation and audit/trace consistency, as well as guarantees that moderator attachment is allowed to arbitrary post for moderation purpose.
 */
export async function test_api_post_attachment_create_moderator_to_any_post(connection: api.IConnection) {
  // Step 1: Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberSignup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });
  typia.assert(memberSignup);

  // Step 2: Login as member
  const memberSignin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });
  typia.assert(memberSignin);

  // Step 3: Create a post as the member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = "Moderator-attach test " + RandomGenerator.alphabets(8);
  const postBody = RandomGenerator.paragraph()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody
    }
  });
  typia.assert(post);

  // Step 4: Register and login as a moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = RandomGenerator.alphaNumeric(10);
  const displayName = RandomGenerator.name();
  const consentStatus = "v1.0:accepted";

  const modSignup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: displayName,
      consent_status: consentStatus
    }
  });
  typia.assert(modSignup);

  const modSignin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword
    }
  });
  typia.assert(modSignin);

  // Step 5: Moderator adds attachment to member's post
  const attachmentBody = {
    uri: "https://test.cdn/mockfile-" + RandomGenerator.alphaNumeric(6) + ".pdf",
    file_name: "testfile.pdf",
    file_size_bytes: 10240,
    mime_type: "application/pdf"
  };
  const attachment = await api.functional.polEcoBoard.moderator.posts.attachments.create(connection, {
    postId: post.id,
    body: attachmentBody
  });
  typia.assert(attachment);

  // Step 6: Assert audit fields & output
  TestValidator.equals("post_id matches")(attachment.post_id)(post.id);
  TestValidator.equals("file_name")(attachment.file_name)(attachmentBody.file_name);
  TestValidator.equals("mime type")(attachment.mime_type)(attachmentBody.mime_type);
  TestValidator.equals("file size")(attachment.file_size_bytes)(attachmentBody.file_size_bytes);
  TestValidator.predicate("author_member_id is nonempty moderator id")(!!attachment.author_member_id && typeof attachment.author_member_id === "string");
  TestValidator.predicate("created_at exists")(!!attachment.created_at);
  TestValidator.equals("deleted_at is null")(attachment.deleted_at)(null);
}

