import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * E2E test for moderator/admin tag assignment to posts in polEcoBoard.
 *
 * This scenario tests that: 
 *   - a moderator can add tags to any post (not just their own)
 *   - assignment succeeds with return of the assignment object
 *   - unauthorized users (members) cannot assign tags,
 *   - duplicate tag assignment and not found errors work as expected,
 *   - moderator privilege overrides author-only constraint.
 *
 * Steps:
 * 1. Register a moderator
 * 2. Log in as moderator and store credentials
 * 3. Create a board category (as moderator, if permitted by platform otherwise skip admin-authz check)
 * 4. Create a board within the category
 * 5. Register a member and log in as member
 * 6. Member creates a post
 * 7. Moderator logs in, searches for available tags
 * 8. Moderator assigns a tag to the member post via moderator endpoint
 * 9. Confirm assignment successful
 * 10. Attempt duplicate assignment (should error)
 * 11. Log in as member and attempt tag assignment (should error)
 * 12. Assign with a non-existent tag or post (should error)
 */
export async function test_api_moderator_post_tag_assignment_as_moderator_or_admin(
  connection: api.IConnection,
) {
  // 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphabets(10);
  const moderatorDisplayName = RandomGenerator.alphaNumeric(8);
  const moderatorConsent = "consent_v1";
  const moderatorRegisterResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegisterResult);

  // 2. Moderator login to establish session
  const moderatorLoginResult = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLoginResult);

  // 3. Create a board category
  const categoryName = RandomGenerator.alphaNumeric(12);
  const categoryResult = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: RandomGenerator.paragraph()(15),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(categoryResult);

  // 4. Create board in category
  const boardName = RandomGenerator.alphaNumeric(10);
  const boardCode = RandomGenerator.alphaNumeric(6).toLowerCase();
  const boardResult = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: categoryResult.id,
      name: boardName,
      code: boardCode,
      description: RandomGenerator.paragraph()(32),
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(boardResult);

  // 5. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphabets(10);
  const memberDisplayName = RandomGenerator.alphaNumeric(8);
  const memberConsent = "consent_v1";
  const memberResult = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: memberConsent,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(memberResult);

  // 6. Member login
  const memberLoginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginResult);

  // 7. Member creates a post (as member, after login)
  const postTitle = RandomGenerator.paragraph()(3);
  const postBody = RandomGenerator.paragraph()(20);
  const memberPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryResult.id,
      title: postTitle,
      body: postBody,
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(memberPost);

  // 8. Moderator login, search for available tags
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  const tagSearchResult = await api.functional.polEcoBoard.tags.search(connection, {
    body: {
      limit: 20,
      page: 1,
    } satisfies IPolEcoBoardTag.IRequest,
  });
  typia.assert(tagSearchResult);
  const allTags = tagSearchResult.data;
  // Pick an existing tag for assignment
  if (allTags.length === 0) {
    throw new Error("No tags available to assign for test.");
  }
  const chosenTag = RandomGenerator.pick(allTags);

  // 9. Moderator assigns tag to member's post
  const assignResult = await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: memberPost.id,
    body: {
      tag_id: chosenTag.id,
    } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(assignResult);
  TestValidator.equals("assigned post id")(assignResult.post_id)(memberPost.id);
  TestValidator.equals("assigned tag id")(assignResult.tag_id)(chosenTag.id);

  // 10. Duplicate assignment should fail
  await TestValidator.error("duplicate post-tag assignment should error")(async () => {
    await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
      postId: memberPost.id,
      body: {
        tag_id: chosenTag.id,
      } satisfies IPolEcoBoardPostTag.ICreate,
    });
  });

  // 11. Member (not moderator) attempts assignment (should error)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  await TestValidator.error("member cannot assign tag as moderator endpoint")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
        postId: memberPost.id,
        body: {
          tag_id: chosenTag.id,
        } satisfies IPolEcoBoardPostTag.ICreate,
      });
    }
  );

  // 12. Assign with a non-existent tag or post (should error)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  const fakeTagId = typia.random<string & tags.Format<"uuid">>();
  const fakePostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent tag assignment")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
        postId: memberPost.id,
        body: {
          tag_id: fakeTagId,
        } satisfies IPolEcoBoardPostTag.ICreate,
      });
    }
  );
  await TestValidator.error("non-existent post assignment")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
        postId: fakePostId,
        body: {
          tag_id: chosenTag.id,
        } satisfies IPolEcoBoardPostTag.ICreate,
      });
    }
  );
}

