import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardConsentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardConsentStatus";
import type { IPageIPolEcoBoardConsentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardConsentStatus";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin paginated search/filter for consent status records in polEcoBoard.
 *
 * This scenario tests the end-to-end process for retrieving a paginated list of consent status records with various filter criteria:
 * - provider_key
 * - consent_type
 * - consent_status
 * - region
 * - session_anon_id
 * - created_at (time window)
 * Also tests pagination, negative (no result) queries, and large dataset scenarios.
 *
 * Steps:
 * 1. Register an admin and login (obtain Authorization for subsequent API calls)
 * 2. Create multiple consent status records, each with distinct filterable fields
 * 3. Search by each filterable field one at a time, checking if the correct records are returned
 * 4. Test combinations of filters
 * 5. Test time window (created_after & created_before)
 * 6. Verify pagination: page 1, page 2, limit N, and data does not duplicate between pages
 * 7. Search with intentional mismatched/invalid filters (should return empty result data)
 * 8. Attempt obviously invalid filter syntax and confirm API gracefully errors or returns empty data
 * 9. Ensure that no sensitive information is leaked in responses (only fields defined in DTO visible)
 */
export async function test_api_consent_status_search_various_filters(connection: api.IConnection) {
  // 1. Admin sign-up
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login (sets Authorization header)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a variety of consent status records
  const now = new Date();
  const statuses: IPolEcoBoardConsentStatus[] = [];
  for (let i = 0; i < 8; ++i) {
    const consent = await api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: `provider${i % 2}`,
        region: i % 2 === 0 ? 'US' : 'KR',
        consent_type: i % 3 === 0 ? 'analytics' : i % 3 === 1 ? 'third_party' : 'profiling',
        consent_status: ['opt_in', 'opt_out', 'revoked', 'pending'][i % 4],
        session_anon_id: `session${Math.floor(i / 2)}`,
        audit_trail: `Entry #${i}, created for e2e test`,
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    });
    typia.assert(consent);
    statuses.push(consent);
  }

  // 4. Search by provider_key
  for (const provider of ['provider0', 'provider1']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { provider_key: provider, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert(out);
    TestValidator.predicate(`all provider_key=${provider}`)(out.data.every(cs => cs.provider_key === provider));
  }

  // 5. Search by consent_type
  for (const consentType of ['analytics', 'third_party', 'profiling']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { consent_type: consentType, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert(out);
    TestValidator.predicate(`consent_type=${consentType}`)(out.data.every(cs => cs.consent_type === consentType));
  }

  // 6. Search by consent_status
  for (const status of ['opt_in', 'opt_out', 'revoked', 'pending']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { consent_status: status, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert(out);
    TestValidator.predicate(`consent_status=${status}`)(out.data.every(cs => cs.consent_status === status));
  }

  // 7. Search by region
  for (const region of ['US', 'KR']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { region, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert(out);
    TestValidator.predicate(`region=${region}`)(out.data.every(cs => cs.region === region));
  }

  // 8. Search by session_anon_id
  for (let s = 0; s < 4; ++s) {
    const sid = `session${s}`;
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { session_anon_id: sid, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert(out);
    TestValidator.predicate(`session_anon_id=${sid}`)(out.data.every(cs => cs.session_anon_id === sid));
  }

  // 9. Combined filter: provider_key + consent_type + consent_status + region
  const pick = statuses[2];
  const outCombo = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: {
      provider_key: pick.provider_key,
      consent_type: pick.consent_type,
      consent_status: pick.consent_status,
      region: pick.region,
      limit: 10,
    } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert(outCombo);
  TestValidator.predicate("exact combo")(outCombo.data.every(cs =>
    cs.provider_key === pick.provider_key &&
    cs.region === pick.region &&
    cs.consent_type === pick.consent_type &&
    cs.consent_status === pick.consent_status
  ));
  TestValidator.predicate("combo result matches at least 1")(outCombo.data.length >= 1);

  // 10. Created_after, created_before (use the timestamps of created records)
  const boundary = statuses[4].created_at;
  const outAfter = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: { created_after: boundary, limit: 100 } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert(outAfter);
  TestValidator.predicate("created_after filter")(outAfter.data.every(cs => cs.created_at > boundary));

  const outBefore = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: { created_before: boundary, limit: 100 } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert(outBefore);
  TestValidator.predicate("created_before filter")(outBefore.data.every(cs => cs.created_at < boundary));

  // 11. Pagination test: set limit to 3, iterate pages, check no duplicate ids, data count matches total
  let all: IPolEcoBoardConsentStatus[] = [];
  let page = 1;
  let seen = new Set<string>();
  let totalRecords = -1;
  for (;;) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { page, limit: 3 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert(out);
    if (page === 1) totalRecords = out.pagination.records;
    for (const cs of out.data) {
      TestValidator.predicate('unique id')(seen.has(cs.id) === false);
      seen.add(cs.id);
      all.push(cs);
    }
    if (out.data.length < 3) break;
    ++page;
  }
  TestValidator.equals('total matches sum')(all.length)(totalRecords);

  // 12. Edge: filter with values known not to exist
  const emptyOut = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: { provider_key: 'non-existent-provider' } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert(emptyOut);
  TestValidator.equals('empty')(emptyOut.data.length)(0);

  // 13. Edge: obviously invalid filter syntax (numbers instead of strings)
  await TestValidator.error('invalid filter type')(async () => {
    await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { provider_key: 12345 as any } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
  });

  // 14. Validate only allowed fields exist, sensitive data is not leaked
  for (const cs of all) {
    const allowed = ['id','provider_key','region','consent_type','consent_status','session_anon_id','audit_trail','created_at'];
    const actualFields = Object.keys(cs);
    TestValidator.equals('fields not leaked')(actualFields.sort())(allowed.sort());
  }
}

