 * Steps:
 * 1. Register an admin and login (obtain Authorization for subsequent API calls).
 * 2. Create multiple consent status records, each with distinct filterable fields.
 * 3. Search by each filterable field one at a time, checking if the correct records are returned.
 * 4. Test combinations of filters.
 * 5. Test time window (created_after & created_before).
 * 6. Verify pagination: page 1, page 2, limit N, and data does not duplicate between pages.
 * 7. Search with intentional mismatched/invalid filters (should return empty result data).
 * 8. Attempt obviously invalid filter syntax and confirm API gracefully errors or returns empty data.
 * 9. Ensure that no sensitive information is leaked in responses (only fields defined in DTO visible).
 */
export async function test_api_consent_status_search_various_filters(connection: api.IConnection) {
  // 1. Admin sign-up
  const adminEmail: string & tags.Format<"email"> = typia.random<string & tags.Format<"email">>();
  const adminPassword: string & tags.MinLength<8> & tags.MaxLength<128> = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login (sets Authorization header)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a variety of consent status records with distinctive fields
  const statuses: IPolEcoBoardConsentStatus[] = [];
  for (let i = 0; i < 8; ++i) {
    const consent = await api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: `prov${i % 3}`,
        region: i % 2 === 0 ? 'US' : 'KR',
        consent_type: i % 3 === 0 ? 'analytics' : i % 3 === 1 ? 'third_party' : 'profiling',
        consent_status: ['opt_in', 'opt_out', 'revoked', 'pending'][i % 4],
        session_anon_id: `sess_${Math.floor(i / 2)}`,
        audit_trail: `Entry #${i}, e2e test`,
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    });
    typia.assert<IPolEcoBoardConsentStatus>(consent);
    statuses.push(consent);
  }

  // 4. Filter by each provider_key
  for (const provider_key of ['prov0', 'prov1', 'prov2']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { provider_key, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert<IPageIPolEcoBoardConsentStatus>(out);
    TestValidator.predicate(`all provider_key=${provider_key}`)(out.data.every(cs => cs.provider_key === provider_key));
  }

  // 5. Filter by each consent_type
  for (const consent_type of ['analytics', 'third_party', 'profiling']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { consent_type, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert<IPageIPolEcoBoardConsentStatus>(out);
    TestValidator.predicate(`consent_type=${consent_type}`)(out.data.every(cs => cs.consent_type === consent_type));
  }

  // 6. Filter by each consent_status
  for (const consent_status of ['opt_in', 'opt_out', 'revoked', 'pending']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { consent_status, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert<IPageIPolEcoBoardConsentStatus>(out);
    TestValidator.predicate(`consent_status=${consent_status}`)(out.data.every(cs => cs.consent_status === consent_status));
  }

  // 7. Filter by each region
  for (const region of ['US', 'KR']) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { region, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert<IPageIPolEcoBoardConsentStatus>(out);
    TestValidator.predicate(`region=${region}`)(out.data.every(cs => cs.region === region));
  }

  // 8. Filter by session_anon_id
  for (let s = 0; s < 4; ++s) {
    const session_anon_id = `sess_${s}`;
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { session_anon_id, limit: 10 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert<IPageIPolEcoBoardConsentStatus>(out);
    TestValidator.predicate(`session_anon_id=${session_anon_id}`)(out.data.every(cs => cs.session_anon_id === session_anon_id));
  }

  // 9. Combined filter: provider_key + consent_type + consent_status + region
  const comboPick = statuses[2];
  const comboOut = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: {
      provider_key: comboPick.provider_key,
      consent_type: comboPick.consent_type,
      consent_status: comboPick.consent_status,
      region: comboPick.region,
      limit: 10,
    } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert<IPageIPolEcoBoardConsentStatus>(comboOut);
  TestValidator.predicate("combo filters match")(comboOut.data.every(cs =>
    cs.provider_key === comboPick.provider_key &&
    cs.region === comboPick.region &&
    cs.consent_type === comboPick.consent_type &&
    cs.consent_status === comboPick.consent_status
  ));
  TestValidator.predicate("at least 1 result for combo")(comboOut.data.length >= 1);

  // 10. Time window: created_after & created_before
  const boundaryTime = statuses[4].created_at;
  const outAfter = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: { created_after: boundaryTime, limit: 100 } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert<IPageIPolEcoBoardConsentStatus>(outAfter);
  TestValidator.predicate("created_after filter")(outAfter.data.every(cs => cs.created_at > boundaryTime));

  const outBefore = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: { created_before: boundaryTime, limit: 100 } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert<IPageIPolEcoBoardConsentStatus>(outBefore);
  TestValidator.predicate("created_before filter")(outBefore.data.every(cs => cs.created_at < boundaryTime));

  // 11. Pagination: set limit small and iterate pages, ensure no duplicate ids, total count matches
  let all: IPolEcoBoardConsentStatus[] = [];
  let seen = new Set<string>();
  let totalRecords = -1;
  for (let page = 1;; ++page) {
    const out = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { page, limit: 3 } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
    typia.assert<IPageIPolEcoBoardConsentStatus>(out);
    if (page === 1) totalRecords = out.pagination.records;
    for (const cs of out.data) {
      TestValidator.predicate('unique id')(seen.has(cs.id) === false);
      seen.add(cs.id);
      all.push(cs);
    }
    if (out.data.length < 3) break;
  }
  TestValidator.equals('pagination total matches')(all.length)(totalRecords);

  // 12. Edge: filter with non-existent values (empty result)
  const empty = await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
    body: { provider_key: 'prov-never' } satisfies IPolEcoBoardConsentStatus.IRequest,
  });
  typia.assert<IPageIPolEcoBoardConsentStatus>(empty);
  TestValidator.equals('empty filter result')(empty.data.length)(0);

  // 13. Edge: invalid filter syntax (number for provider_key, should throw)
  await TestValidator.error('invalid filter type')(async () => {
    await api.functional.polEcoBoard.admin.consentStatuses.search(connection, {
      body: { provider_key: 777 as any } satisfies IPolEcoBoardConsentStatus.IRequest,
    });
  });

  // 14. Validate no sensitive data is leaked (only DTO fields present)
  const allowedFields = [
    'id','provider_key','region','consent_type','consent_status','session_anon_id','audit_trail','created_at'];
  for (const cs of all) {
    const actualFields = Object.keys(cs);
    TestValidator.equals('fields match DTO only')(actualFields.sort())(allowedFields.sort());
  }
}

