import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IPageIPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPostEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for post edit history fetch by admin.
 *
 * This covers:
 * - Admin account registration and login to obtain authorization
 * - Member account creation and login to create a new post
 * - Creation of a member post to serve as base content
 * - Creation of multiple post edits (using API) to generate a real edit history
 * - Admin fetches edit history of the post (happy path)
 * - Verifies correct pagination, ordering, and filtering (by editor, date, sort order, limit)
 * - Verifies all expected audit metadata fields and edit snapshot content
 * - Tests fetching edit history for a post with no edits (should return an empty array)
 * - Tests access denial when admin is logged out or using an invalid token
 */
export async function test_api_post_edit_history_admin_fetch(connection: api.IConnection) {
  // 1. Register admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });

  // 2. Admin login to get authorization token
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    }
  });

  // 3. Create member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: "v1"
    }
  });
  typia.assert(member);

  // 4. Member login
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });

  // 5. Create a board post as member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(10);
  const postBody = RandomGenerator.content()()(30);
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody
    }
  });
  typia.assert(post);

  // 6. Add several post edits as member
  const editSnapshots: IPolEcoBoardPostEdit[] = [];
  for (let i = 0; i < 5; ++i) {
    const edit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
      postId: post.id,
      body: {
        edit_body: RandomGenerator.content()()(30 + i * 5),
        edit_reason: `Revision ${i}`
      }
    });
    typia.assert(edit);
    editSnapshots.push(edit);
  }

  // 7. Admin login again to refresh token
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });

  // 8. Admin fetch edit history -- happy path, all records
  const page = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      page: 1,
      limit: 10
    }
  });
  typia.assert(page);
  TestValidator.equals("edit count matches")(page.data.length)(editSnapshots.length);
  TestValidator.predicate("all audit fields present")(page.data.every(edit => typeof edit.id === "string" && typeof edit.editor_member_id === "string" && typeof edit.edit_body === "string" && typeof edit.created_at === "string"));

  // 9. Check filtering (editor_member_id)
  const filtered = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      editor_member_id: member.id
    }
  });
  typia.assert(filtered);
  TestValidator.equals("all edits by member")(filtered.data.every(e => e.editor_member_id === member.id))(true);

  // 10. Sorting by created_at desc
  const sorted = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      order_by: "created_at",
      order_dir: "desc"
    }
  });
  typia.assert(sorted);
  for(let j = 1; j < sorted.data.length; ++j) {
    TestValidator.predicate("sorted desc")(sorted.data[j-1].created_at >= sorted.data[j].created_at);
  }

  // 11. Empty edit history for new post
  const post2 = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(30)
    }
  });
  typia.assert(post2);
  const empty = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post2.id,
    body: {}
  });
  typia.assert(empty);
  TestValidator.equals("no edit history")(empty.data.length)(0);

  // 12. Unauthorized access: admin logs out or uses wrong token
  const fakeConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer fake-token" } };
  await TestValidator.error("unauthorized access fails")(async () => {
    await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(fakeConn, {
      postId: post.id,
      body: {}
    });
  });
}

