      editor_member_id: member.id
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(filtered);
  TestValidator.equals("all filtered by member")(filtered.data.every(e => e.editor_member_id === member.id))(true);

  // 9. Sorting by created_at descending
  const sorted = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      order_by: "created_at",
      order_dir: "desc"
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
