  for(let j = 1; j < sorted.data.length; ++j) {
    TestValidator.predicate("sorted desc")(sorted.data[j-1].created_at >= sorted.data[j].created_at);
  }

  // 10. No edits: create a new post, fetch should return empty data
  const newPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()()(36)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(newPost);
  const empty = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: newPost.id,
    body: {} satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(empty);
  TestValidator.equals("empty edit history")(empty.data.length)(0);

  // 11. Unauthorized: fake admin token
  const fakeConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalid-token" } };
  await TestValidator.error("admin unauthorized access fails")(async () => {
    await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(fakeConn, {
      postId: post.id,
      body: {} satisfies IPolEcoBoardPostEdit.IRequest
    });
  });
}

