/**
 * Validate pagination and edge case handling for admin comment listing.
 *
 * This test ensures that the admin endpoint for listing post comments
 * supports predictable pagination, handles large data sets, and deals
 * correctly with edge scenarios where a page is partially full or empty.
 *
 * Workflow:
 * 1. Register a new admin and login (capture JWT for all admin calls)
 * 2. Create a new board category
 * 3. Create a new board within the category
 * 4. Create a new post in the board via member endpoint (simulating a user post)
 * 5. Bulk create a large number (e.g., 45) of comments on the post via member endpoint
 * 6. As admin, call the PATCH /polEcoBoard/admin/posts/{postId}/comments endpoint repeatedly with varying
 *    page and limit settings:
 *    - Validate 1st page (limit 10): 10 records, correct ordering, non-empty
 *    - Validate a middle page (e.g., page 3, limit 10): 10 records, correct index range
 *    - Validate last page (should have only 5 records when using limit 10)
 *    - Validate a page beyond max (e.g., page 10, limit 10) yields empty data array
 *    - Confirm total record count and total pages match the expected
 *    - All comments returned correspond to the test post
 *    - Results sorted by 'created_at desc' by default
 * 7. Optionally check with custom order (asc) and confirm list order reverses
 */
export async function test_api_admin_comment_list_pagination_and_edge_case(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
