    commentEditId,
  });
  typia.assert(deletedEdit);

  // Basic referential validations
  TestValidator.equals("deleted edit record has correct id")(deletedEdit.id)(commentEditId);
  TestValidator.equals("deleted edit record refers to correct comment")(deletedEdit.comment_id)(comment.id);
}

