/**
 * Validate admin comment listing, with ability to see flagged and soft-deleted comments, and filtering.
 *
 * This e2e workflow validates that an admin account can view all comments (including flagged and deleted/soft-deleted) on a post and can apply filtering on author and status. It ensures admin privileges allow visibility into comments that are not visible to regular users, and checks compliance of all business/audit fields for admin.
 *
 * Workflow:
 * 1. Register a new admin (use unique email/password for test isolation).
 * 2. Log in as that admin so connection has Authorization header.
 * 3. Admin: create a post category for the board.
 * 4. Admin: create a board in the category.
 * 5. Member: create a post in the board (member context simulated via not setting admin auth headers for post creation).
 * 6. Member: add several comments to the post (all by member context). Vary a few: standard, flagged, and for deletion.
 * 7. Admin: flag a comment (simulate by re-creating comment with flagged=true through DB or via direct edit—if not possible, use multiple comments and delete one for soft-delete path).
 * 8. Admin: soft-delete a comment (DELETE endpoint as admin).
 * 9. As admin: use /admin/posts/{postId}/comments (PATCH) with no filter to fetch all comments and validate all statuses/fields included.
 * 10. As admin: use filters (e.g., flagged=true, include_deleted=true, author filter) to validate filtering and audit capabilities.
 * 11. Validate response fields, presence of flagged/deleted, and admin-internal fields like deleted_at are included, and that filtering selects correct results only.
 */
export async function test_api_admin_comment_list_with_flagged_deleted_and_filtering(connection: api.IConnection) {
