    body: { body: "Delete me comment for admin filter test" } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentToDelete);

  // 8. Admin soft-deletes a comment
  const deletedComment = await api.functional.polEcoBoard.admin.posts.comments.erase(connection, {
    postId: post.id,
    commentId: commentToDelete.id,
  });
  typia.assert(deletedComment);
  TestValidator.predicate("deleted_at is set for soft-deleted comment")(!!deletedComment.deleted_at);

  // 9. Admin fetches all comments (with include_deleted set)
  const allResults = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      include_deleted: true,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(allResults);
  // Validate all 3 comments included
  TestValidator.predicate("all results included - admin can see deleted and flagged")(
    allResults.data.length >= 3
  );

  // 10. Admin fetches only deleted comments
  const onlyDeleted = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      include_deleted: true,
      // Filtering by deleted, so we expect only those with deleted_at set
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(onlyDeleted);
  TestValidator.predicate("at least one deleted comment present")(
    onlyDeleted.data.find(d => d.id === commentToDelete.id) !== undefined
  );

  // 11. Admin fetches only comments by the original author (should match at least the normal and flagged comment, plus soft deleted)
  const authorComments = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
