      include_deleted: true,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(authorComments);
  TestValidator.predicate("all author comments included")(
    authorComments.data.every(c => c.author_member_id === commentNormal.author_member_id)
  );

  // 12. (Optional) Validate admin-audit fields present
  for (const c of allResults.data) {
    // For admin, deleted_at, flagged should always be present; check schema compliance
    TestValidator.predicate("admin can see audit fields: flagged present")(typeof c.flagged === "boolean");
    TestValidator.predicate("admin can see created_at")(typeof c.created_at === "string");
    TestValidator.predicate("admin can see updated_at")(typeof c.updated_at === "string");
    // Soft-deleted comments have non-null deleted_at
    if (c.id === commentToDelete.id) {
      TestValidator.predicate("deleted_at present for deleted comment")(typeof deletedComment.deleted_at === "string");
    }
  }
}

