import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the ability of an admin to update any polEcoBoard post, including overriding normal edit/authorship constraints and properly handling input validation errors.
 *
 * Business context:
 * - Admins must be able to edit any post at any time, regardless of lock windows or original authorship. This ensures moderation and compliance capabilities are not blocked.
 * - All input validation (title/body min/max length, forbidden/extra fields, malformed input) should trigger clear error responses.
 * - Edits should be fully audited (i.e., timestamps and updated fields tracked per business rules).
 *
 * Test steps:
 * 1. Register and log in an admin user (obtain admin credentials) for future requests.
 * 2. Register and log in a normal member so a post can be created with non-admin authorship.
 * 3. As admin, create a board category.
 * 4. As member, create a new post in the board category (save returned post for test).
 * 5. As admin, update the post:
 *    a. Valid update: Change post title and body to valid, different text. Verify the updated post is returned and the changes are reflected.
 *    b. Invalid update (validation errors):
 *         - Supply a title that is too short (<10 chars), verify error thrown.
 *         - Supply a body that is too short (<10 chars), verify error thrown.
 *         - Supply a title that is too long (>120 chars), verify error thrown.
 *         - Supply a body that is too long (>10,000 chars), verify error thrown.
 *         - Attempt to update forbidden fields (e.g., author_member_id, id, category_id), verify error thrown.
 *    c. Audit: Confirm updated_at field was updated appropriately after successful edit, and that previous/forbidden fields remain unchanged.
 */
export async function test_api_admin_post_update_success_and_validation(connection: api.IConnection) {
  // 1. Register an admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegisterResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminRegisterResponse);

  // 2. Log in as the admin user
  const adminLoginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResponse);

  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberRegisterResponse = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRegisterResponse);

  // 4. Log in as the member
  const memberLoginResponse = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginResponse);

  // 5. As admin, create a board category (category is required for new post)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  const categoryCreate = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(30),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(categoryCreate);

  // 6. As member, create a post
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  const postCreate = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryCreate.id,
      title: RandomGenerator.alphabets(20),
      body: RandomGenerator.paragraph()(60),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postCreate);

  // 7. As admin, log in and update the member's post with valid data
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  const validTitle = RandomGenerator.alphabets(25);
  const validBody = RandomGenerator.paragraph()(200);
  const postUpdate = await api.functional.polEcoBoard.admin.posts.update(connection, {
    postId: postCreate.id,
    body: {
      title: validTitle,
      body: validBody,
    } satisfies IPolEcoBoardPost.IUpdate,
  });
  typia.assert(postUpdate);
  TestValidator.equals("updated title")(postUpdate.title)(validTitle);
  TestValidator.equals("updated body")(postUpdate.body)(validBody);
  TestValidator.equals("category remains")(postUpdate.category_id)(categoryCreate.id);
  TestValidator.equals("author remains")(postUpdate.author_member_id)(postCreate.author_member_id);
  TestValidator.predicate("updated_at has increased")(
    new Date(postUpdate.updated_at).getTime() > new Date(postCreate.updated_at).getTime()
  );

  // 8. Attempt various invalid admin updates (validation errors)
  // a. Too short title
  TestValidator.error("title too short")(() =>
    api.functional.polEcoBoard.admin.posts.update(connection, {
      postId: postCreate.id,
      body: {
        title: RandomGenerator.alphabets(2),
      } satisfies IPolEcoBoardPost.IUpdate,
    })
  );
  // b. Too long title
  TestValidator.error("title too long")(() =>
    api.functional.polEcoBoard.admin.posts.update(connection, {
      postId: postCreate.id,
      body: {
        title: RandomGenerator.alphabets(130),
      } satisfies IPolEcoBoardPost.IUpdate,
    })
  );
  // c. Too short body
  TestValidator.error("body too short")(() =>
    api.functional.polEcoBoard.admin.posts.update(connection, {
      postId: postCreate.id,
      body: {
        body: RandomGenerator.alphabets(3),
      } satisfies IPolEcoBoardPost.IUpdate,
    })
  );
  // d. Too long body
  TestValidator.error("body too long")(() =>
    api.functional.polEcoBoard.admin.posts.update(connection, {
      postId: postCreate.id,
      body: {
        body: RandomGenerator.alphabets(10200),
      } satisfies IPolEcoBoardPost.IUpdate,
    })
  );
  // e. Attempt to update forbidden fields (id, author_member_id, category_id, flagged, created_at, updated_at, deleted_at, etc)
  // These fields should throw because they're not allowed in update DTO
  TestValidator.error("set forbidden field: id")(() =>
    api.functional.polEcoBoard.admin.posts.update(connection, {
      postId: postCreate.id,
      body: {
        // @ts-expect-error: forbidden by schema
        id: typia.random<string & tags.Format<"uuid">>(),
        // permitted fields: title/body/tags/attachments
      } as any,
    })
  );
  TestValidator.error("set forbidden field: author_member_id")(() =>
    api.functional.polEcoBoard.admin.posts.update(connection, {
      postId: postCreate.id,
      body: {
        // @ts-expect-error: forbidden by schema
        author_member_id: typia.random<string & tags.Format<"uuid">>(),
      } as any,
    })
  );
  TestValidator.error("set forbidden field: category_id")(() =>
    api.functional.polEcoBoard.admin.posts.update(connection, {
      postId: postCreate.id,
      body: {
        // @ts-expect-error: forbidden by schema
        category_id: categoryCreate.id,
      } as any,
    })
  );
}

