import type { IPolEcoBoardModeratorBoardAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorBoardAssignment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIPolEcoBoardModeratorBoardAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardModeratorBoardAssignment";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate multi-criteria search functionality for moderator-board assignments as an admin.
 *
 * This covers the end-to-end workflow for moderator assignment management:
 * - Register admin
 * - Admin login
 * - Create a board category
 * - Create two boards under this category
 * - Create two moderators
 * - Assign a unique moderator to each board via admin assignment
 * - Use PATCH /polEcoBoard/admin/moderatorBoardAssignments to search:
 *   * By both moderator ID and board ID
 *   * Filtering by admin ID (assigned_by_admin_id)
 *   * Filtering by status ('active', 'ended')
 *   * With pagination
 * - Test for both matching and non-matching (empty) search results
 */
export async function test_api_admin_board_assignment_search_multi_criteria(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpRes);

  // 2. Admin login
  const adminSignInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignInRes);

  // 3. Create a category
  const categoryName = RandomGenerator.alphaNumeric(12);
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create two boards in the category
  const boardNames = [RandomGenerator.alphaNumeric(10), RandomGenerator.alphaNumeric(10)];
  const boardCodes = [RandomGenerator.alphaNumeric(8).toLowerCase(), RandomGenerator.alphaNumeric(8).toLowerCase()];
  const board1 = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardNames[0],
      code: boardCodes[0],
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board1);
  const board2 = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardNames[1],
      code: boardCodes[1],
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 2,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board2);

  // 5. Register two moderators
  const modPwd = RandomGenerator.alphaNumeric(10);
  const moderator1Email = typia.random<string & tags.Format<"email">>();
  const moderator2Email = typia.random<string & tags.Format<"email">>();
  const moderator1 = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderator1Email,
      password: modPwd,
