    TestValidator.predicate("result has assignment1")(
      res.data.some(x => x.id === assignment1.id),
    );
  }
  // 7-2. Search by second moderator and board (assignment2)
  {
    const res = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.search(
      connection,
      {
        body: {
          pagination: { page: 1, pageSize: 10 },
          pol_eco_board_moderator_id: moderator2.moderatorId,
          pol_eco_board_board_id: board2.id,
          assigned_by_admin_id: null,
          status: "active",
