/**
 * Validate unauthorized admin search for post attachments.
 *
 * This test ensures that the PATCH endpoint /polEcoBoard/admin/posts/{postId}/attachments does NOT allow access unless called by a valid, authorized admin session. It covers the following workflow:
 *
 * 1. Admin registration and login to set context (but token will NOT be used for unauthorized attempts).
 * 2. Create preconditions: board category, board, member, and member-created post with an attachment.
 * 3. Attempt the PATCH endpoint as admin in two scenarios:
 *     a. No Authorization header at all.
 *     b. Expired/invalid Authorization header (simulate by providing random/garbage token).
 * 4. Assert that both attempts are rejected with authorization error and NO confidential information (e.g., attachment metadata or file URIs) is exposed in the response.
 *
 * Ensures that no sensitive attachment data leaks to unauthorized users and compliance/audit trail responsibilities are upheld for such attempts.
 */
export async function test_api_post_attachment_search_by_admin_unauthorized(connection: api.IConnection) {
  // Step 1: Register and login as admin (for setup - do NOT use this token for unauthorized attempts)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // Step 2: Create category, board, member, and post+attachment
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1).slice(0,40),
      description: RandomGenerator.paragraph()(1),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
