    postId: post.id,
    body: {
      uri: "https://cdn.example.com/testfile.dat",
      file_name: "testfile.dat",
      file_size_bytes: 1234,
      mime_type: "application/octet-stream",
    } satisfies IPolEcoBoardAttachment.ICreate,
  });
  typia.assert(attachment);

  // Step 3a: Attempt attachment search as admin with NO token
  const noAuthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Unauthorized search should fail - no token")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.attachments.search(noAuthConnection, {
        postId: post.id,
        body: {}, // empty filter is valid
      });
    }
  );

  // Step 3b: Attempt with INVALID token
  const invalidAuthConnection = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalidtoken" } };
  await TestValidator.error("Unauthorized search should fail - invalid token")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.attachments.search(invalidAuthConnection, {
        postId: post.id,
        body: {},
      });
    }
  );

  // Optionally: Could check that the thrown error does NOT contain sensitive data (but TestValidator.error only checks for error thrown)
}

