/**
 * Validate that an admin user can retrieve full attachment details for any post regardless of authorship, category, or privacy status.
 *
 * Business context: For operational and compliance purposes, platform administrators must be able to fetch complete metadata of any post attachment—regardless of the post's author, board, or privacy/locked status. Attachment meta-access is critical for content review, legal request fulfillment, data retention audits, and operational troubleshooting.
 *
 * Test necessity: Ensures that the admin privilege bypasses member-level access scope and always returns attachment details (even for locked/post-moderation content), fulfilling compliance/audit requirements.
 *
 * Step-by-step:
 * 1. Register a new member and create a new post linked to a valid category.
 * 2. Log the member in to get an authenticated session and create a post with required properties.
 * 3. Upload a file attachment to the post (use randomly generated file meta for realism).
 * 4. Register a new admin using a valid business email and sufficiently strong password per schema constraints.
 * 5. Log the admin in to enable admin-level session on the test connection.
 * 6. As admin, fetch the attachment details using the /polEcoBoard/admin/posts/{postId}/attachments/{attachmentId} endpoint.
 * 7. Confirm that the response contains all metadata fields (id, post_id, author_member_id, uri, file_name, file_size_bytes, mime_type, created_at, deleted_at).
 * 8. Validate that the file meta is visible (i.e., not redacted or restricted by privacy); attachment info matches that returned at creation.
 */
export async function test_api_post_attachment_details_admin_access(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 2. Member login
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 3. Create a new post as the member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()()(100),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Add attachment to the post
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: {
      uri: `https://storage.service/${typia.random<string & tags.Format<"uuid">>()}.pdf`,
      file_name: `test_${RandomGenerator.alphaNumeric(8)}.pdf`,
      file_size_bytes: typia.random<number & tags.Type<"int32">>(),
      mime_type: "application/pdf",
    } satisfies IPolEcoBoardAttachment.ICreate,
  });
  typia.assert(attachment);

  // 5. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 6. Admin login, switches session context
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 7. As admin, fetch the attachment details
  const adminAttachment = await api.functional.polEcoBoard.admin.posts.attachments.at(connection, {
    postId: post.id,
    attachmentId: attachment.id,
  });
  typia.assert(adminAttachment);

  // 8. Validate metadata: ensure all fields are visible and values match original upload
  TestValidator.equals("Attachment ID matches")(adminAttachment.id)(attachment.id);
  TestValidator.equals("Post ID matches")(adminAttachment.post_id)(post.id);
  TestValidator.equals("File name matches")(adminAttachment.file_name)(attachment.file_name);
  TestValidator.equals("MIME type matches")(adminAttachment.mime_type)(attachment.mime_type);
  TestValidator.equals("File size matches")(adminAttachment.file_size_bytes)(attachment.file_size_bytes);
  TestValidator.equals("URI matches")(adminAttachment.uri)(attachment.uri);
  TestValidator.equals("Author member ID matches")(adminAttachment.author_member_id)(attachment.author_member_id);
  TestValidator.predicate("Created at is valid")(typeof adminAttachment.created_at === "string" && adminAttachment.created_at.length > 0);
}

