import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the successful assignment of a tag to a post by an admin.
 *
 * This test simulates the entire admin-driven workflow for post tag assignment in polEcoBoard:
 *   1. Register a new admin and obtain authorization.
 *   2. Create a new category as admin.
 *   3. Create a new board, linking it to the category.
 *   4. Register a new member (as posts require member context).
 *   5. As the member, create a post in the new board/category.
 *   6. With admin rights, create a new tag.
 *   7. Assign the newly created tag to the post using the admin interface.
 *   8. Validate referential integrity—ensure tag appears in the post's assignment; validate correct metadata.
 *
 * Validates all business rules and reference constraints for admin post tagging.
 */
export async function test_api_post_tag_admin_tag_assignment_happy_path(connection: api.IConnection) {
  // 1. Register a new admin and obtain authorization (admin signUp)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminSignUpRes);
  // Authorization header automatically set in connection

  // 2. Create a new category (admin required)
  const categoryName = RandomGenerator.alphabets(10);
  const categoryDesc = RandomGenerator.paragraph()(1);
  const displayOrder = typia.random<number & tags.Type<"int32">>();
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: categoryDesc,
      display_order: displayOrder
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create a new board, linking to the category
  const boardName = RandomGenerator.alphabets(10);
  const boardCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const boardDesc = RandomGenerator.paragraph()(1);
  const boardIsPublic = true;
  const boardIsArchived = false;
  const boardDisplayOrder = typia.random<number & tags.Type<"int32">>();
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardName,
      code: boardCode,
      description: boardDesc,
      is_public: boardIsPublic,
      is_archived: boardIsArchived,
      display_order: boardDisplayOrder
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Register a new member (posting flow requires member account)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplayName = RandomGenerator.alphabets(10);
  const memberConsent = "consent_given";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: memberConsent
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 5. As the member, create a post in the board/category (simulate authentication if needed)
  const postTitle = RandomGenerator.paragraph()(1).substring(0, 50); // meet min 10/max 120
  const postBody = RandomGenerator.content()(1)();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      body: postBody
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. As admin, create a tag
  const tagName = RandomGenerator.alphabets(8);
  const tagSlug = tagName.toLowerCase();
  const tagDesc = RandomGenerator.content()(1)();
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: tagName,
      slug: tagSlug,
      description: tagDesc
    } satisfies IPolEcoBoardTag.ICreate
  });
  typia.assert(tag);

  // 7. With admin privileges, assign tag to post
  const postTagAssignment = await api.functional.polEcoBoard.admin.posts.postTags.create(connection, {
    postId: post.id,
    body: {
      tag_id: tag.id
    } satisfies IPolEcoBoardPostTag.ICreate
  });
