import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardSanction";
import type { IPageIPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardSanction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * E2E: Test moderator sanction search, filtering and scope enforcement.
 *
 * This test covers the following workflow:
 * 1. Register a new moderator.
 * 2. Log in as that moderator to obtain authentication context.
 * 3. Create a moderation action (as the moderator) needed for sanction linkage.
 * 4. Create a new sanction as that moderator, for a dummy sanctioned user (simulate public member id).
 * 5. Search for sanctions using various filters:
 *    a. By moderation_action_id
 *    b. By sanctioned_user_id
 *    c. By sanction_type
 *    d. By status
 *    e. Pagination with page and limit
 *    f. By start_from and end_to
 * 6. Confirm result data matches filter specifications and only sanctions within moderator scope are visible.
 * 7. Attempt search with malformed/insufficient permissions and expect errors.
 */
export async function test_api_sanction_search_moderator_access_scope_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestP@ssw0rd1!";
  const moderatorSignUpResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accepted-v1"
    }
  });
  typia.assert(moderatorSignUpResponse);
  const moderatorId = moderatorSignUpResponse.moderatorId;

  // 2. Login as moderator (session should carry token - for redundancy)
  const loginResponse = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    }
  });
  typia.assert(loginResponse);
  TestValidator.equals("email matches")(loginResponse.email)(moderatorEmail);
  TestValidator.equals("moderatorId matches")(loginResponse.moderatorId)(moderatorId);

  // 3. Create moderation action as this moderator
  const action = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: moderatorId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "Test removal for E2E",
      outcome: "accepted"
    }
  });
  typia.assert(action);
  TestValidator.equals("action operator_id")(action.operator_id)(moderatorId);

  // 4. Create sanction connected to that action, on a dummy user
  const sanctionedUserId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const sanction = await api.functional.polEcoBoard.moderator.sanctions.create(connection, {
    body: {
      moderation_action_id: action.id,
      sanctioned_user_id: sanctionedUserId,
      sanction_type: "ban",
      status: "active",
      rationale: "E2E violation test",
      start_at: now.toISOString(),
      end_at: new Date(+now + 3 * 24 * 60 * 60 * 1000).toISOString() // 3 days later
    }
  });
  typia.assert(sanction);
  TestValidator.equals("sanctioned user matches")(sanction.sanctioned_user_id)(sanctionedUserId);
  TestValidator.equals("action link matches")(sanction.moderation_action_id)(action.id);

  // --- 5. SEARCH FILTERS ---
  // 5a. Search by moderation_action_id: Must get the sanction
  const searchByAction = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: action.id }
  });
  typia.assert(searchByAction);
  TestValidator.predicate("sanction present in results")(
    searchByAction.data.some(s => s.id === sanction.id)
  );

  // 5b. Search by sanctioned_user_id: Must get sanction
  const searchByUser = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { sanctioned_user_id: sanctionedUserId }
  });
  typia.assert(searchByUser);
  TestValidator.predicate("sanctioned user result")(
    searchByUser.data.some(s => s.sanctioned_user_id === sanctionedUserId)
  );

  // 5c. Sanction type and status (positive case)
  const searchByTypeAndStatus = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: {
      sanction_type: "ban",
      status: "active"
    }
  });
  typia.assert(searchByTypeAndStatus);
  TestValidator.predicate("sanction type/status")(
    searchByTypeAndStatus.data.some(s => s.sanctioned_user_id === sanctionedUserId)
  );

  // 5d. Pagination (limit=1)
  const paged = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { page: 1, limit: 1 }
  });
  typia.assert(paged);
  TestValidator.equals("per page limit 1")(paged.data.length)(1);

  // 5e. Start/end range
  const filterByDate = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { start_from: now.toISOString(), end_to: sanction.end_at }
  });
  typia.assert(filterByDate);
  TestValidator.predicate("date range contains sanction")(
    filterByDate.data.some(s => s.id === sanction.id)
  );

  // 6. Scope enforcement: Query by unrelated moderation_action_id should yield empty or only sanctions in scope.
  const unrelatedActionId = typia.random<string & tags.Format<"uuid">>();
  const unrelatedSearch = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: {
      moderation_action_id: unrelatedActionId
    }
  });
  typia.assert(unrelatedSearch);
  TestValidator.predicate("no unrelated sanctions")(
    unrelatedSearch.data.length === 0 || unrelatedSearch.data.every(s => s.moderation_action_id === unrelatedActionId)
  );
  // 7. Malformed: status with bad value
  TestValidator.error("malformed status value throws")(() =>
    api.functional.polEcoBoard.moderator.sanctions.search(connection, {
      body: {
        status: "not-a-valid-status"
      }
    })
  );

  // 7b. Insufficient permissions: Simulate by registering a new moderator with no actions/sanctions in scope, search for original sanction and expect not to see it.
  const outsiderEmail = typia.random<string & tags.Format<"email">>();
  const outsiderPassword = "ANoScopeMod!2";
  const outsiderReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: outsiderEmail,
      password: outsiderPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accepted-v1"
    }
  });
  typia.assert(outsiderReg);
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: outsiderEmail, password: outsiderPassword }
  });
  const outsiderSearch = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: action.id }
  });
  typia.assert(outsiderSearch);
  TestValidator.predicate("outsider cannot see sanction")(
    !outsiderSearch.data.some(s => s.id === sanction.id)
  );
}

