import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the creation and validation of a privileged account audit record as an admin.
 *
 * This test verifies that an authenticated admin can create a new account audit record using the /polEcoBoard/admin/accountAudits endpoint.
 * The test ensures proper creation with valid data, confirms all necessary metadata and generated identifiers in the response,
 * and also checks for correct error responses for invalid inputs.
 *
 * Steps:
 * 1. Register a new admin with unique credentials using /auth/admin/register.
 * 2. Log in as the registered admin via /auth/admin/login (credentials, session token handling).
 * 3. Attempt to create an account audit record with valid data: must include acceptable action_type (from enum), valid UUIDs for actor and target, status, event_source, and occurred_at.
 * 4. Assert that the response includes a valid ID, all required metadata fields, with correct data echo and timestamping.
 * 5. Negative test: attempt creation with missing required fields (e.g., omit action_type or actor_id) and confirm that a validation error is thrown.
 * 6. Negative test: attempt creation with an invalid action_type value (not present in enum) and confirm that a validation error is thrown.
 */
export async function test_api_account_audit_creation_validation_and_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 2. Log in as admin (get/set JWT automatically in connection)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 3. Create valid audit log
  const actorId = typia.random<string & tags.Format<"uuid">>();
  const targetAccountId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const validAuditInput: IPolEcoBoardAccountAudit.ICreate = {
    action_type: "create",
    actor_id: actorId,
    target_account_id: targetAccountId,
    event_source: "admin_api",
    status: "success",
    occurred_at: now,
    action_metadata: "Initial account creation by admin"
  };
  const audit = await api.functional.polEcoBoard.admin.accountAudits.create(connection, { body: validAuditInput });
  typia.assert(audit);
  TestValidator.equals("action_type echo")(audit.action_type)("create");
  TestValidator.equals("actor_id echo")(audit.actor_id)(actorId);
  TestValidator.equals("target_account_id echo")(audit.target_account_id)(targetAccountId);
  TestValidator.equals("event_source echo")(audit.event_source)("admin_api");
  TestValidator.equals("status echo")(audit.status)("success");
  TestValidator.equals("occurred_at echo")(audit.occurred_at)(now);
  TestValidator.predicate("id is uuid")(typeof audit.id === "string" && audit.id.length > 0);
  TestValidator.predicate("created_at exists")(typeof audit.created_at === "string" && audit.created_at.length > 0);

  // 5. Negative: missing required field (action_type)
  const missingActionType = { ...validAuditInput };
  delete (missingActionType as any).action_type;
  TestValidator.error("Missing action_type fails")(() =>
    api.functional.polEcoBoard.admin.accountAudits.create(connection, { body: missingActionType as any })
  );

  // 6. Negative: invalid action_type value
  const invalidAction = { ...validAuditInput, action_type: "not_a_real_action" as any };
  TestValidator.error("Invalid action_type fails")(() =>
    api.functional.polEcoBoard.admin.accountAudits.create(connection, { body: invalidAction as any })
  );
}

