import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPageIPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can perform paginated and filtered search for attachments to a board post.
 *
 * This test ensures:
 * 1. Admin registration and sign-in works, yielding an authorized session.
 * 2. An admin can create a category and a board inside it.
 * 3. A member can be signed up, logged in, and author a post on the board.
 * 4. Many attachments are uploaded by the member to the post, covering a variety of file types and names.
 * 5. As admin, search for attachments on the post, using advanced filters (file name, file type, date range), and with pagination options.
 * 6. Validate attachment search accurately returns filtered and paged data, reflecting uploaded files, and that result set matches query parameters for file type and name filtering across multiple pages. Optionally check audit information as observable.
 */
export async function test_api_post_attachment_search_by_admin_with_pagination(connection: api.IConnection) {
  // 1. Admin registration and login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 2. Create a category for posts
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(12),
      description: RandomGenerator.paragraph()(),
      display_order: 1
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create a board within the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(16),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 1
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Register and log in as a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplay = RandomGenerator.alphabets(10);
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplay,
      consent_status: "v1-consent"
    } satisfies IPolEcoBoardMember.ICreate
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });

  // 5. Member creates a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()().slice(0,40),
      body: RandomGenerator.content()()().slice(0,150)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Upload multiple (20) attachments of varying types
  const attachmentTypes = [
    { mime_type: "image/png", file_name: "file1.png" },
    { mime_type: "application/pdf", file_name: "file2.pdf" },
    { mime_type: "image/jpeg", file_name: "file3.jpg" },
    { mime_type: "text/plain", file_name: "notes.txt" },
    { mime_type: "text/markdown", file_name: "doc.md" }
  ];
  const attachments = await ArrayUtil.asyncRepeat(20)(async (i) => {
    const type = attachmentTypes[i % attachmentTypes.length];
    const result = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
      postId: post.id,
      body: {
        uri: `https://cdn.example.com/uploaded/file${i}_${RandomGenerator.alphaNumeric(8)}.${type.file_name.split('.').pop()}`,
        file_name: `${String(i).padStart(2,'0')}_${type.file_name}`,
        file_size_bytes: typia.random<number & tags.Type<"int32">>(),
        mime_type: type.mime_type
      } satisfies IPolEcoBoardAttachment.ICreate
    });
    typia.assert(result);
    return result;
  });

  // 7. Switch role back to admin (re-login to set admin context)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 8. Admin requests first page (limit=5) for image/png attachments
  const searchFilter = {
    mime_type: "image/png",
    limit: 5,
    page: 1
  } satisfies IPolEcoBoardAttachment.IRequest;
  const page1 = await api.functional.polEcoBoard.admin.posts.attachments.search(connection, {
    postId: post.id,
    body: searchFilter
  });
  typia.assert(page1);
  TestValidator.equals("limit match")(page1.pagination.limit)(5);
  TestValidator.equals("current page")(page1.pagination.current)(1);
  TestValidator.predicate("all attachments are png")(page1.data.every(a => a.mime_type === "image/png"));

  // 9. Admin fetches the second page of image/png attachments
  const page2 = await api.functional.polEcoBoard.admin.posts.attachments.search(connection, {
    postId: post.id,
    body: { ...searchFilter, page: 2 }
  });
  typia.assert(page2);
  TestValidator.equals("second page")(page2.pagination.current)(2);
  TestValidator.predicate("all attachments are png on page 2")(page2.data.every(a => a.mime_type === "image/png"));
  // Confirm no overlap between pages
  TestValidator.predicate("page 1 and 2 data are distinct")(
    page1.data.every(d1 => !page2.data.find(d2 => d2.id === d1.id))
  );

  // 10. Admin searches by file extension (markdown files)
  const mdSearch = await api.functional.polEcoBoard.admin.posts.attachments.search(connection, {
    postId: post.id,
    body: { file_name: ".md", limit: 10, page: 1 } satisfies IPolEcoBoardAttachment.IRequest
  });
  typia.assert(mdSearch);
  TestValidator.predicate("all file_name contains .md")(mdSearch.data.every(a => a.file_name.includes(".md")));

  // 11. Admin fetches all attachments paginated (page 1, limit 10), no filter
  const allSearch = await api.functional.polEcoBoard.admin.posts.attachments.search(connection, {
    postId: post.id,
    body: { limit: 10, page: 1 } satisfies IPolEcoBoardAttachment.IRequest
  });
  typia.assert(allSearch);
  TestValidator.equals("records total")(allSearch.pagination.records)(attachments.length);
  TestValidator.equals("data size")(allSearch.data.length)(Math.min(10, attachments.length));
}

