import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Comprehensive test for moderator account login scenarios.
 *
 * This test validates the full workflow for moderator login, including both success and various failure scenarios.
 * The flow covers new account registration (prerequisite), successful sign-in, and several types of failed login attempts (invalid password, unknown email, and repeated failures for rate limiting/security).
 *
 * Steps:
 * 1. Register a new moderator account with a unique email/password/display_name/consent_status, and verify registration success.
 * 2. Attempt login with correct credentials and verify successful response (moderator ID, JWT issued, email/display_name match, Authorization header present).
 * 3. Attempt login with correct email but wrong password; expect error response (do not leak security details).
 * 4. Attempt login with unregistered email and a random password; expect error response.
 * 5. Attempt repeated login failures with the same account to trigger rate limiting—validate API returns error after threshold is reached (behavior may depend on implementation).
 * 6. Confirm all error responses do not leak account existence or security info.
 *
 * Note: Test for inactive/banned account is omitted, as there is no API to suspend or deactivate accounts using only public endpoints.
 */
export async function test_api_moderator_login_success_and_failure_cases(
  connection: api.IConnection,
) {
  // 1. Register a new moderator account
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword123!";
  const displayName = RandomGenerator.name();
  const consentStatus = "v20240813";

  const registerResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registerResponse);
  TestValidator.equals("email matches")(registerResponse.email)(email);
  TestValidator.equals("display_name matches")(registerResponse.display_name)(displayName);
  TestValidator.predicate("Authorization header present")(
    typeof registerResponse.setHeaders?.Authorization === "string" &&
    registerResponse.setHeaders?.Authorization.startsWith("Bearer ")
  );

  // 2. Attempt login with correct credentials
  const loginResponse = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResponse);
  TestValidator.equals("login email matches")(loginResponse.email)(email);
  TestValidator.equals("login display_name matches")(loginResponse.display_name)(displayName);
  TestValidator.predicate("Authorization header present on login")(
    typeof loginResponse.setHeaders?.Authorization === "string" &&
    loginResponse.setHeaders?.Authorization.startsWith("Bearer ")
  );

  // 3. Attempt login with correct email but incorrect password
  await TestValidator.error("login fails with wrong password")(async () => {
    await api.functional.auth.moderator.login.signIn(connection, {
      body: {
        email,
        password: "WrongPassword!@#",
      } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
    });
  });

  // 4. Attempt login with unregistered email
  await TestValidator.error("login fails with non-existent email")(async () => {
    await api.functional.auth.moderator.login.signIn(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "AnotherFakePass1!",
      } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
    });
  });

  // 5. Repeated failed logins to check rate limit/security error
  for (let i = 0; i < 5; i++) {
    await TestValidator.error(`failed login attempt #${i + 1}`)(async () => {
      await api.functional.auth.moderator.login.signIn(connection, {
        body: {
          email,
          password: "DefinitelyWrongPassword123#",
        } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
      });
    });
  }
  // (Optional) The actual error for rate limit vs wrong password may depend on backend; ensure API gives consistent security-friendly errors.
}

