import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationFailure";
import type { IPageIPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationFailure";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate comprehensive searching and pagination of notification failures as an admin.
 *
 * This test validates that the admin can search and paginate all notification delivery failures using advanced filters, verifying visibility and security boundaries.
 *
 * 1. Register a unique admin and log in to acquire authentication for privileged actions.
 * 2. Prepare multiple notification failure records:
 *    - Vary recipients (recipient_member_id), notification_id, provider_id, failure_code, and resolution_status.
 *    - Ensure enough records so pagination is meaningful (limit < total records).
 * 3. As admin, run search API with:
 *    - No filters, validate all created failures are visible in correct order.
 *    - Various combinations: by failure_code, by provider_id, by resolution_status, and combinations thereof. Validate returned results match expected records, filtering correctly. Check that field values are correct and complete.
 *    - Pagination: check default, custom limit, and different page returns. Confirm correct pagination metadata and sliced datasets.
 *    - Filtering for non-existent failure_code or made-up recipient_member_id: expect empty result set and correct pagination metadata.
 * 4. Security: Remove Authorization or login as a non-admin. Search attempt should be forbidden/denied (business error thrown).
 */
export async function test_api_notification_failure_admin_search_full_scope(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);

  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Create test notification failures for several members/providers/codes/status
  const recipients = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const notifications = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const providers = [typia.random<string & tags.Format<"uuid">>(), null];
  const codes = ["smtp_421", "api_LIMIT", "sys_MEMFAILS"];
  const statuses = ["pending", "resolved", "permanent_failure"];

  // Flatten all combinations; create extra for pagination validation
  const allFailures: IPolEcoBoardNotificationFailure[] = [];
  for (const recipient of recipients) {
    for (const notification_id of notifications) {
      for (const provider_id of providers) {
        for (const failure_code of codes) {
          for (const resolution_status of statuses) {
            // Vary occurred_at by time for deterministic order
            const occurred_at = new Date(Date.now() - Math.floor(Math.random() * 1000000)).toISOString();
            const failure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
              body: {
                notification_id,
                provider_id,
                failure_code,
                failure_message: `${failure_code} for recipient ${recipient}`,
                occurred_at,
                resolution_status,
              } satisfies IPolEcoBoardNotificationFailure.ICreate,
            });
            typia.assert(failure);
            allFailures.push(failure);
          }
        }
      }
    }
  }

  // 3. Advanced filter/search and pagination validation
  // a) No filter, get all
  let pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, { body: { } });
  typia.assert(pageResp);
  // Should return allFailures by most recent occurred_at descending (?) or default sorting
  TestValidator.predicate("all failures are visible")(pageResp.pagination.records >= allFailures.length);
  const returnedIds = pageResp.data.map(f => f.id);
  allFailures.forEach(f => TestValidator.predicate(`returned id ${f.id}`)(returnedIds.includes(f.id)));

  // b) Filter by failure_code
  for (const code of codes) {
    const filtered = allFailures.filter(f => f.failure_code === code);
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
      body: { failure_code: code },
    });
    typia.assert(pageResp);
    TestValidator.equals(`failure_code=${code}`)(pageResp.data.length)(filtered.length);
    pageResp.data.forEach(f => TestValidator.equals("code matches")(f.failure_code)(code));
  }

  // c) Filter by provider_id
  for (const provider_id of providers) {
    const filtered = allFailures.filter(f => f.provider_id === provider_id);
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
      body: provider_id ? { provider_id } : { provider_id: null },
    });
    typia.assert(pageResp);
    TestValidator.equals(`provider_id=${provider_id}`)(pageResp.data.length)(filtered.length);
    pageResp.data.forEach(f => TestValidator.equals("provider_id")(f.provider_id ?? null)(provider_id));
  }

  // d) Filter by resolution_status
  for (const status of statuses) {
    const filtered = allFailures.filter(f => f.resolution_status === status);
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
      body: { resolution_status: status },
    });
    typia.assert(pageResp);
    TestValidator.equals(`resolution_status=${status}`)(pageResp.data.length)(filtered.length);
    pageResp.data.forEach(f => TestValidator.equals("status matches")(f.resolution_status)(status));
  }

  // e) Combined filter (failure_code + provider + status)
  for (const code of codes) {
    for (const provider_id of providers) {
      for (const status of statuses) {
        const filtered = allFailures.filter(
          f => f.failure_code === code && f.provider_id === provider_id && f.resolution_status === status,
        );
        pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
          body: {
            failure_code: code,
            provider_id,
            resolution_status: status,
          },
        });
        typia.assert(pageResp);
        TestValidator.equals(`combo filter length: ${code},${provider_id},${status}`)(pageResp.data.length)(filtered.length);
        pageResp.data.forEach(
          f => {
            TestValidator.equals("combo code")(f.failure_code)(code);
            TestValidator.equals("combo provider")(f.provider_id ?? null)(provider_id);
            TestValidator.equals("combo status")(f.resolution_status)(status);
          },
        );
      }
    }
  }

  // f) Pagination
  const firstPageLimit = 3;
  pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, { body: { limit: firstPageLimit } });
  typia.assert(pageResp);
  TestValidator.equals("pagination limit")(pageResp.pagination.limit)(firstPageLimit);
  TestValidator.equals("first page length")(pageResp.data.length)(Math.min(firstPageLimit, allFailures.length));
  if (allFailures.length > firstPageLimit) {
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, { body: { limit: firstPageLimit, page: 2 } });
    typia.assert(pageResp);
    TestValidator.equals("pagination page 2")(pageResp.pagination.current)(2);
  }

  // g) Filter for non-existent failure_code
  pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
    body: { failure_code: "does_NOT_exist_code" },
  });
  typia.assert(pageResp);
  TestValidator.equals("no results")(pageResp.data.length)(0);

  // h) Filter for non-existent recipient_member_id
  pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
    body: { recipient_member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(pageResp);
  TestValidator.equals("no results for unknown user")(pageResp.data.length)(0);

  // 4. Security: try searching without Authorization (or as non-admin)
  // Remove auth
  const noAuthConnection = { ...connection, headers: {} };
  await TestValidator.error("search with no auth/role fails")(async () => {
    await api.functional.polEcoBoard.admin.notificationFailures.search(noAuthConnection, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardConsentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardConsentStatus";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate retrieval of a consent status record by unique ID as an admin.
 *
 * This test simulates the admin compliance workflow for verifying consent status records in the polEcoBoard system.
 * It ensures all critical fields are present, admin permissions are enforced, and non-admins are restricted.
 *
 * Steps:
 * 1. Register a new admin account with valid unique credentials.
 * 2. Login as the just-registered admin to receive proper authentication headers.
 * 3. Create a new consent status record (with valid provider_key, region, consent_type, consent_status, session_anon_id, audit_trail).
 * 4. Fetch the created record by its returned UUID using GET as the admin.
 * 5. Validate all expected fields: provider_key, region, consent_type, consent_status, session_anon_id, audit_trail, created_at, id.
 * 6. Confirm the response type matches IPolEcoBoardConsentStatus, with true data equality match.
 * 7. Attempt to access the same resource WITHOUT the admin token, and assert that access is denied (permissions enforced).
 */
export async function test_api_consent_status_fetch_success(connection: api.IConnection) {
  // 1. Register new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResp);

  // 2. Login as the admin
  const adminSignInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignInResp);

  // 3. Create new consent status record
  const createInput: IPolEcoBoardConsentStatus.ICreate = {
    provider_key: RandomGenerator.alphaNumeric(6),
    region: "US",
    consent_type: RandomGenerator.alphaNumeric(8),
    consent_status: RandomGenerator.pick(["opt_in", "opt_out", "revoked", "pending"]),
    session_anon_id: RandomGenerator.alphaNumeric(10),
    audit_trail: JSON.stringify({ source: "test", timestamp: new Date().toISOString() }),
  };
  const createdConsentStatus = await api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
    body: createInput,
  });
  typia.assert(createdConsentStatus);

  // 4. Fetch consent status by ID (as admin)
  const fetchedConsentStatus = await api.functional.polEcoBoard.admin.consentStatuses.at(connection, {
    consentStatusId: createdConsentStatus.id,
  });
  typia.assert(fetchedConsentStatus);
  // 5. Validate all expected fields
  TestValidator.equals("provider_key")(fetchedConsentStatus.provider_key)(createInput.provider_key);
  TestValidator.equals("region")(fetchedConsentStatus.region)(createInput.region);
  TestValidator.equals("consent_type")(fetchedConsentStatus.consent_type)(createInput.consent_type);
  TestValidator.equals("consent_status")(fetchedConsentStatus.consent_status)(createInput.consent_status);
  TestValidator.equals("session_anon_id")(fetchedConsentStatus.session_anon_id)(createInput.session_anon_id);
  TestValidator.equals("audit_trail")(fetchedConsentStatus.audit_trail)(createInput.audit_trail);
  TestValidator.equals("id")(fetchedConsentStatus.id)(createdConsentStatus.id);
  // created_at is not directly matched (set by the backend), but should be ISO8601
  TestValidator.predicate("created_at format")(!!fetchedConsentStatus.created_at && !isNaN(Date.parse(fetchedConsentStatus.created_at)));

  // 6. Attempt access WITHOUT admin headers (simulate logout by clearing Authorization header)
  const anonConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Non-admin access denied")(
    async () => {
      await api.functional.polEcoBoard.admin.consentStatuses.at(anonConnection, {
        consentStatusId: createdConsentStatus.id,
      });
    },
  );
}

