/**
 * E2E test for searching and paginating admin audit trail records.
 *
 * This test validates the end-to-end workflow for an admin searching audit trail records
 * with filtering and pagination. It covers account creation, login, data setup,
 * a complex search filter, and thorough verification of the expected results, including pagination metadata.
 *
 * Steps:
 * 1. Register a new admin account with a unique email and a secure password.
 * 2. Login as the admin to obtain authorization tokens for subsequent privileged operations.
 * 3. Create several audit trail records, varying by action type, performed_by_id, resource, and time.
 * 4. Submit a PATCH search request with filter parameters (action type, performed_by_id, page, limit).
 * 5. Assert that only records matching the filter parameters are returned.
 * 6. Check that pagination info in the response is correct and logically consistent.
 */
export async function test_api_audit_trail_search_filter_pagination(connection: api.IConnection) {
  // 1. Register a new admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Login as admin
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // Use the same admin UUID for all records to ensure search test is meaningful
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const actionTypes = [
    "CONFIG_CHANGE",
    "ROLE_ASSIGN",
    "DATA_ERASURE",
  ];
  const targetResources = [
    "SYSTEM_CONFIG",
    "USER_42",
    "DOCUMENT_XYZ",
  ];

  // 3. Create several audit trail records with a mix of filters
  const now = new Date();
  const createdRecords = await ArrayUtil.asyncRepeat(6)(async (_, i) => {
    const action_type = actionTypes[i % actionTypes.length];
    const performed_by_id = adminId;
    const target_resource = targetResources[i % targetResources.length];
    const recorded_at = new Date(now.getTime() - i * 24 * 60 * 60 * 1000).toISOString();
    return await api.functional.polEcoBoard.admin.auditTrails.create(connection, {
      body: {
        action_type,
        performed_by_id,
        target_resource,
        audit_context: JSON.stringify({ desc: RandomGenerator.paragraph()() }),
        recorded_at,
      } satisfies IPolEcoBoardAuditTrail.ICreate,
    });
  });
  createdRecords.forEach(typia.assert);

  // 4. Search with complex filter (action_type=CONFIG_CHANGE, performed_by_id, page=1, limit=2)
  const searchParams = {
    action_type: "CONFIG_CHANGE",
    performed_by_id: adminId,
    page: 1,
    limit: 2,
  } satisfies IPolEcoBoardAuditTrail.IRequest;
  const searchRes = await api.functional.polEcoBoard.admin.auditTrails.search(connection, {
    body: searchParams,
  });
  typia.assert(searchRes);

  // 5. Results must match the filters
  searchRes.data.forEach((audit) => {
    TestValidator.equals("action_type filtered")(audit.action_type)("CONFIG_CHANGE");
    TestValidator.equals("performed_by_id filtered")(audit.performed_by_id)(adminId);
  });

  // 6. Pagination checks
  TestValidator.predicate("response row count <= limit")(searchRes.data.length <= 2);
  TestValidator.equals("pagination current")(searchRes.pagination.current)(1);
  TestValidator.equals("pagination limit")(searchRes.pagination.limit)(2);
  TestValidator.predicate("total records >= returned rows")(searchRes.pagination.records >= searchRes.data.length);
  TestValidator.predicate("total pages >= 1")(searchRes.pagination.pages >= 1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
