import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for searching and listing external authentication providers as an admin with filters, sorting, and pagination.
 *
 * Covers:
 * 1. Admin registration and authentication.
 * 2. Creating several external auth providers with varying properties (status, provider_name, region).
 * 3. Searching with no filters (should return all non-deleted providers by default, paginated).
 * 4. Searching by provider_name text (should only return matching name).
 * 5. Filtering by status (e.g., 'disabled' only).
 * 6. Filtering by jurisdiction/region (e.g., 'EU' only).
 * 7. Result pagination (limit/page, metadata validation).
 * 8. Filter combination that yields zero results.
 * 9. Attempt by non-admin (unauthenticated) user to search (should fail with error).
 */
export async function test_api_external_auth_provider_search_admin_filter_sort_pagination(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create external auth providers with variety of props
  const createdProviders = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const status = i === 0
      ? "enabled"
      : i === 1
      ? "disabled"
      : i === 2
      ? "maintenance"
      : "enabled";
    const region = ["US", "EU", "APAC", "US", "EU"][i];
    const provider = await api.functional.polEcoBoard.admin.externalAuthProviders.create(
      connection,
      {
        body: {
          provider_name: `Provider ${RandomGenerator.alphaNumeric(3)}_${i}`,
          provider_key: `provider${i}_${RandomGenerator.alphaNumeric(5).toLowerCase()}`,
          status,
          privacy_policy_uri: `https://provider${i}.example.com/privacy`,
          data_residency_region: region,
          consent_required: i % 2 === 0,
        } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
      },
    );
    typia.assert(provider);
    return provider;
  });

  // 4. Search with no filters - should return all non-deleted
  const result1 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {},
  });
  typia.assert(result1);
  TestValidator.predicate("returns all created providers")(result1.data.length === createdProviders.length);

  // 5. Search: filter by provider_name
  const nameQuery = createdProviders[2].provider_name.slice(0, 8);
  const result2 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      provider_name: nameQuery,
    },
  });
  typia.assert(result2);
  TestValidator.predicate("name filter only returns matches")(result2.data.every((r) => r.provider_name.includes(nameQuery)));

  // 6. Search: filter by status (disabled)
  const result3 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      status: "disabled",
    },
  });
  typia.assert(result3);
  TestValidator.predicate("status filter only disabled")(result3.data.every((r) => r.status === "disabled"));

  // 7. Search: filter by region (jurisdiction)
  const regionFilter = "EU";
  const result4 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      region: regionFilter,
    },
  });
  typia.assert(result4);
  TestValidator.predicate("region filter EU")(result4.data.every((r) => r.data_residency_region === regionFilter));

  // 8. Search: pagination (page & limit)
  const result5 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(result5);
  TestValidator.equals("pagination limit")(result5.pagination.limit)(2);
  TestValidator.equals("pagination page")(result5.pagination.current)(1);
  TestValidator.predicate("pagination count")(result5.data.length <= 2);

  // 9. Search with filter yielding zero results
  const result6 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      provider_name: "NO_MATCHING_PROVIDER",
    },
  });
  typia.assert(result6);
  TestValidator.equals("zero results")(result6.data.length)(0);

  // 10. Try searching as unauthenticated user (should error)
  const anonConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("non-admin rejected")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.search(anonConn, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardExternalAuthProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardExternalAuthProvider";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the admin soft-delete flow for external authentication providers and access restriction logic.
 *
 * This test validates that:
 * - An admin can soft-delete an external authentication provider by its ID
 * - After deletion, any further delete attempts or attempts as a non-admin are properly rejected
 * - Attempts to delete a non-existent provider also return errors as expected
 * - Verifies type contracts and enforcement of access control, with business context documentation
 *
 * Steps implemented:
 * 1. Register a new admin and log in to obtain privileges
 * 2. Create an external authentication provider
 * 3. Admin deletes (soft) the provider
 * 4. Verify repeated delete and deletion of non-existent records is blocked
 * 5. Confirm non-admin context cannot delete providers
 *
 * Note: Due to SDK limits, no search/list/fetch API is available for negative retrieval validation or audit logs; those checks are omitted.
 */
export async function test_api_external_auth_provider_admin_soft_delete_and_access_restriction(
  connection: api.IConnection,
) {
  // 1. Register and log in admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();

  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 2. Create external authentication provider
  const createInput: IPolEcoBoardExternalAuthProvider.ICreate = {
    provider_name: "TestProvider-" + RandomGenerator.alphaNumeric(8),
    provider_key: "test_key_" + RandomGenerator.alphaNumeric(8),
    status: "enabled",
    privacy_policy_uri: "https://example.com/privacy-policy" + RandomGenerator.alphaNumeric(6),
    data_residency_region: "US",
    consent_required: true,
  };
  const provider = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
    body: createInput,
  });
  typia.assert(provider);
  TestValidator.equals("provider not deleted after creation")(provider.deleted_at)(null);

  // 3. Admin soft-deletes provider by ID
  await api.functional.polEcoBoard.admin.externalAuthProviders.erase(connection, {
    externalAuthProviderId: provider.id,
  });

  // 4. Blocked: repeated delete by admin (double delete)
  await TestValidator.error("double soft-delete fails")(() =>
    api.functional.polEcoBoard.admin.externalAuthProviders.erase(connection, {
      externalAuthProviderId: provider.id,
    })
  );

  // 4. Blocked: deletion of non-existent provider
  await TestValidator.error("delete non-existent provider fails")(() =>
    api.functional.polEcoBoard.admin.externalAuthProviders.erase(connection, {
      externalAuthProviderId: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Attempt delete as non-admin (simulate by clearing Authorization header)
  const nonAdminConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("non-admin cannot soft-delete provider")(() =>
    api.functional.polEcoBoard.admin.externalAuthProviders.erase(nonAdminConnection, {
      externalAuthProviderId: provider.id,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
