import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validates moderator-only access to full comment vote details, and correct permission error for non-moderators.
 *
 * This test ensures that:
 *  - A moderator can fetch all audit details for a specific vote on a comment, with full referential and field integrity.
 *  - The endpoint enforces moderator-only access (403/permission error for ordinary members).
 *
 * Steps:
 * 1. Register and login a moderator; store the Bearer token.
 * 2. Register and login a member; store Bearer token and identity.
 * 3. Member creates a post (injected category_id/title/body).
 * 4. Member adds a comment to the post.
 * 5. Member upvotes or downvotes the comment.
 * 6. Moderator fetches vote detail by (commentId, voteId) and verifies full properties and referential integrity.
 * 7. Member attempts same fetch; expect authorization error.
 */
export async function test_api_comment_vote_detail_moderator_success_and_permission(connection: api.IConnection) {
  // 1. Register moderator and store credentials/token
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "testPassword!1";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "privacy_v1";

  const moderatorRegister = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegister);

  // 2. Login as moderator (refresh token)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);
  const moderatorAuth = moderatorLogin.setHeaders.Authorization;

  // Save original connection headers to restore later
  const originalAuth = connection.headers?.Authorization;

  // 3. Register a new member and login
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testMemberPW2!";
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);
  const memberAuth = memberLogin.setHeaders.Authorization;

  // 4. Member creates a post
  connection.headers = {
    ...connection.headers,
    Authorization: memberAuth,
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.content()()(50),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Member creates a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(10),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 6. Member votes on the comment
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 7. Switch to moderator credential
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorAuth,
  };

  // 8. Moderator fetches vote details
  const detail = await api.functional.polEcoBoard.moderator.comments.votes.at(connection, {
    commentId: comment.id,
    voteId: vote.id,
  });
  typia.assert(detail);
  TestValidator.equals("commentId match")(detail.comment_id)(comment.id);
  TestValidator.equals("vote id match")(detail.id)(vote.id);
  TestValidator.equals("vote value")(detail.vote_value)(vote.vote_value);
  TestValidator.equals("voter member id")(detail.voter_member_id)(vote.voter_member_id);

  TestValidator.predicate("created_at is ISO string")(!!detail.created_at && typeof detail.created_at === "string" && !isNaN(Date.parse(detail.created_at)));

  // 9. Switch back to member
  connection.headers = {
    ...connection.headers,
    Authorization: memberAuth,
  };
  // 10. Attempt to fetch the vote (should fail with error)
  await TestValidator.error("permission error for non-moderator")(async () => {
    await api.functional.polEcoBoard.moderator.comments.votes.at(connection, {
      commentId: comment.id,
      voteId: vote.id,
    });
  });

  // Restore original connection headers
  connection.headers = {
    ...connection.headers,
    Authorization: originalAuth,
  };
}

