    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Try to fetch a report with non-existent postId and reportId (random UUIDs)
  await TestValidator.error("non-existent post/report should error")(() =>
    api.functional.polEcoBoard.admin.posts.reports.at(connection, {
      postId: typia.random<string & tags.Format<"uuid">>(),
      reportId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 4. Try to fetch a report as an unauthenticated user (simulate by removing Authorization)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized admin access should fail")(() =>
    api.functional.polEcoBoard.admin.posts.reports.at(unauthConnection, {
      postId: typia.random<string & tags.Format<"uuid">>(),
      reportId: typia.random<string & tags.Format<"uuid">>(),
