/**
 * Test moderator-originated report submission on a post in polEcoBoard.
 *
 * This scenario validates that moderators can report posts, that moderator privilege-based access is enforced,
 * and that normal business rules (e.g., duplicate report prevention on the same post) are correctly implemented for the moderator role.
 *
 * Steps:
 * 1. Register a moderator account and login to establish moderator authentication context.
 * 2. Register a member account and login as that member (to create a post as a normal user).
 * 3. Submit a new post as the member to obtain a valid post for reporting.
 * 4. Switch to the moderator account (login if necessary).
 * 5. Submit a report against the member's post as the moderator, specifying a valid reason code and description.
 * 6. Validate that a report is created and linked to correct moderator (authentication), with correct data.
 * 7. Attempt to submit a duplicate report from the same moderator for the same post, and verify business rules are enforced
 *    (e.g., error is thrown for duplicate, or business response prevents multiple reports by same moderator on same post).
 */
export async function test_api_moderator_post_report_submission(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = typia.random<string & tags.Format<"password">>();
  const displayName: string = RandomGenerator.name();
  const consentStatus: string = "policy_v1";
  const modRegRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: displayName,
      consent_status: consentStatus,
