      email: adminBEmail,
      password: adminBPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  // Token for admin B is now in connection.headers.Authorization

  // 8. Attempt to get A's escalation as B (should fail)
  await TestValidator.error("should reject if not recipient admin")(() =>
    api.functional.polEcoBoard.admin.escalations.at(connection, {
