import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for moderator-initiated creation of an escalation event to admin.
 *
 * This test validates that a moderator can escalate an already recorded moderation action to an admin by creating a new escalation event. It ensures:
 * - Correct referencing of an existing moderation action
 * - Use of authenticated moderator identity (escalator)
 * - Use of a valid admin as escalation recipient
 * - Business rationale (reason) is supplied
 * - Initial status set per business logic (e.g., 'pending')
 *
 * It also checks essential failure scenarios:
 * - Error if moderation action does not exist
 * - Error if admin id (recipient) is invalid
 * - Error if reason is missing
 * - Denial if not authenticated as a moderator
 *
 * Steps:
 * 1. Register and login as moderator, save moderatorId
 * 2. Register admin, save adminId (if available; see note on platform constraint)
 * 3. (If not internally generated) login as admin, if association context is needed
 * 4. With moderator session, create a valid moderation action
 * 5. As moderator, create an escalation referencing this action, with valid admin recipient and reason
 * 6. Validate success, check returned record matches request, escalation is visible (if query endpoint available)
 * 7. With invalid inputs: non-existent moderationActionId, wrong adminId, or empty reason, call escalation creation and expect failure
 * 8. Attempt escalation with unauthenticated/non-moderator session and expect failure
 */
export async function test_api_escalation_creation_by_moderator(connection: api.IConnection) {
  // 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "P@ssw0rd!234";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "v1.0_terms_agreed";

  const moderatorRegResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorRegResp);
  const moderatorId = moderatorRegResp.moderatorId;

  // 2. Login as moderator
  const moderatorAuthResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(moderatorAuthResp);

  // 3. Register an admin (recipient)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "P@ssw0rdAdmin!234";
  const adminRegResp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminRegResp);

  // (Optional) Login as admin (if any session context is needed)
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  // Moderator login again to ensure session for escalation creation
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

  // 4. Create moderation action event
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const modAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: moderatorId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "Test content violation",
      outcome: "removed"
    } satisfies IPolEcoBoardModerationAction.ICreate
  });
  typia.assert(modAction);

  // ---
  // Note: The recipient admin's actual UUID is NOT available after creation via SDK;
  // in production/business flows, such an ID would need to be introspected via a query endpoint.
  // For this E2E, simulate with a random UUID, and verify that validation will fail if not a real admin.
  // If the real adminId is needed and available, test can be improved with that lookup.
  const recipientAdminId = RandomGenerator.uuid();
  // ---

  // 5. Create escalation event (valid)
  const validReason = "Policy escalation for senior admin review.";
  const escalationStatus = "pending";
  const escalationReq = {
    moderation_action_id: modAction.id,
    escalator_id: moderatorId,
    recipient_admin_id: recipientAdminId,
    reason: validReason,
    status: escalationStatus
  } satisfies IPolEcoBoardEscalation.ICreate;

  const escalationResp = await api.functional.polEcoBoard.moderator.escalations.create(connection, {
    body: escalationReq
  });
  typia.assert(escalationResp);

  // 6. Verify escalation record matches request
  TestValidator.equals("moderation_action_id")(escalationResp.moderation_action_id)(modAction.id);
  TestValidator.equals("escalator_id")(escalationResp.escalator_id)(moderatorId);
  TestValidator.equals("recipient_admin_id")(escalationResp.recipient_admin_id)(recipientAdminId);
  TestValidator.equals("reason")(escalationResp.reason)(validReason);
  TestValidator.equals("status")(escalationResp.status)(escalationStatus);

  // 7. Failure scenarios: Invalid moderation_action_id
  await TestValidator.error("non-existent moderation action fails")(async () => {
    await api.functional.polEcoBoard.moderator.escalations.create(connection, {
      body: {
        ...escalationReq,
        moderation_action_id: RandomGenerator.uuid()
      } satisfies IPolEcoBoardEscalation.ICreate
    });
  });
  // Invalid recipient admin
  await TestValidator.error("invalid admin id fails")(async () => {
    await api.functional.polEcoBoard.moderator.escalations.create(connection, {
      body: {
        ...escalationReq,
        recipient_admin_id: RandomGenerator.uuid()
      } satisfies IPolEcoBoardEscalation.ICreate
    });
  });
  // Missing reason: compile-time error prevention, test is omitted

  // 8. Unauthorized - switch session to admin (not moderator)
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  await TestValidator.error("admin cannot perform escalation as moderator")(async () => {
    await api.functional.polEcoBoard.moderator.escalations.create(connection, {
      body: escalationReq
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
