import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Comprehensive E2E test for board status creation as a moderator, including business rules
 * and permission/error validation for the polEcoBoard system.
 *
 * This function validates:
 * 1. Successful board status creation by an authenticated moderator using valid data, following correct registration and login and referencing a real board
 * 2. Validation errors for missing or invalid required fields (such as missing boardId, invalid status_type, or missing rationale if required)
 * 3. Attempt to create a board status referencing a non-existent board (should fail)
 * 4. Forbidden/unauthorized attempts by an unauthenticated or non-moderator context
 * 5. Ensures business continuity and rule enforcement, including allowed status_type transitions (using enums), and descriptive error feedback where needed
 *
 * Workflow overview (as implemented):
 * - Step 1: Register and authenticate a new moderator (using unique registration fields)
 * - Step 2: Create a new board (required for a valid reference)
 * - Step 3: Post a new board status event using valid data as the moderator
 * - Step 4: Attempt invalid creations: missing required fields, invalid enum value, missing reason
 * - Step 5: Attempt to reference a non-existent board
 * - Step 6: Attempt board status creation without authentication, and check for forbidden error
 */
export async function test_api_board_status_creation_by_moderator_with_validation_and_permission_errors(
  connection: api.IConnection,
) {
  // Step 1: Register a new moderator and extract id/token
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorRegRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: "SecretPassword123!",
      display_name: RandomGenerator.name(),
      consent_status: "v1.0-policy-accepted",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegRes);

  // Step 2: Login as moderator (simulates real flow, ensures JWT in connection)
  const moderatorLoginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: "SecretPassword123!",
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLoginRes);
  const moderatorId = moderatorLoginRes.moderatorId;

  // Step 3: Create a board (precondition for valid status creation)
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // Step 4: As moderator, create valid board status event
  const now = new Date().toISOString();
  const statusPayload: IPolEcoBoardBoardStatus.ICreate = {
    pol_eco_board_board_id: board.id,
    actor_moderator_id: moderatorId,
    status_type: "locked",
    effective_at: now,
    reason: "Testing board lock by moderator.",
  };
  const createdStatus = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: statusPayload,
  });
  typia.assert(createdStatus);
  TestValidator.equals("board id matches")(createdStatus.pol_eco_board_board_id)(board.id);
  TestValidator.equals("status type matches")(createdStatus.status_type)(statusPayload.status_type);

  // Step 5: Field validation: Missing pol_eco_board_board_id - cannot strictly compile, skip as per TS constraints

  // Step 6: Field validation: Invalid status_type (not in allowed enum)
  await TestValidator.error("invalid status_type should be rejected")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: board.id,
        actor_moderator_id: moderatorId,
        status_type: "notarealstatus" as any, // forced for testing, will fail at runtime
        effective_at: now,
        reason: "Invalid status_type.",
      } as any,
    })
  );

  // Step 7: Missing reason (optional)
  const statusNoReason = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: moderatorId,
      status_type: "open",
      effective_at: now,
      // reason is intentionally omitted (should be allowed)
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(statusNoReason);
  TestValidator.equals("board id matches for no reason")(statusNoReason.pol_eco_board_board_id)(board.id);

  // Step 8: Reference non-existent board
  await TestValidator.error("referencing non-existent board should be rejected")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: typia.random<string & tags.Format<"uuid">>(),
        actor_moderator_id: moderatorId,
        status_type: "locked",
        effective_at: now,
        reason: "Non-existent board reference.",
      } satisfies IPolEcoBoardBoardStatus.ICreate,
    })
  );

  // Step 9: Attempt forbidden/unauthenticated usage (simulate logout by clearing Authorization)
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized should be forbidden")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(unauthConn, {
      body: statusPayload,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
