import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IPageIPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate searching notification preferences by an authenticated member (with filtering and pagination).
 *
 * This test ensures end-to-end that:
 * - A member can register and login.
 * - The member can create multiple notification preferences for various event types and channels.
 * - Searching for notification preferences returns only the authenticated member's records.
 * - Filtering by event type and channel is respected.
 * - Pagination works as expected (correct number of records per page, proper total count).
 *
 * Scenario steps:
 * 1. Register a new member account (random, unique email).
 * 2. Log in with the new member credentials.
 * 3. Create 6+ notification preferences with distinct event_type/channel/opt_in combinations for the member.
 * 4. Perform PATCH search without any filter: all created preferences for the member should be returned.
 * 5. Perform PATCH search filtering for a subset (by event_type, by channel, by opt_in, and by multiple filters together), and verify the filtered output matches those criteria.
 * 6. Perform PATCH search with pagination (e.g., limit=2, page=2) and verify correct slicing of result data and accurate pagination meta.
 */
export async function test_api_member_notification_preference_search_success(
  connection: api.IConnection,
) {
  // 1. Register a member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signUpResult);

  // 2. Log in with the registered account
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signInResult);
  // JWT Authorization auto-handled in connection

  // 3. Create multiple notification preferences for the member
  const eventTypes = [
    "reply",
    "moderation_action",
    "mention",
  ];
  const channels = [
    "email",
    "push",
  ];
  const optIns = [true, false];
  // Generate all combinations (3*2*2 = 12), but we'll create a subset (6-8) unique
  const preferencesToCreate: { event_type: string; channel: string; opt_in: boolean }[] = [];
  for (const event_type of eventTypes) for (const channel of channels) for (const opt_in of optIns) preferencesToCreate.push({ event_type, channel, opt_in });
  const createdPrefs: IPolEcoBoardNotificationPreference[] = [];

  let known_member_id: string & tags.Format<"uuid"> | undefined = undefined;
  for (const { event_type, channel, opt_in } of preferencesToCreate.slice(0, 6)) {
    // Try to get the member_id from the first created record for canonical reference
    const pref = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
      body: {
        member_id: known_member_id ? known_member_id : typia.random<string & tags.Format<"uuid">>(),
        event_type,
        channel,
        opt_in,
      },
    });
    typia.assert(pref);
    if (!known_member_id) known_member_id = pref.member_id;
    createdPrefs.push(pref);
  }
  const real_member_id = known_member_id!;

  // 4. Search without filters: all 6 records should be returned
  {
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: {},
    });
    typia.assert(output);
    for (const pref of output.data) {
      TestValidator.equals("only this member's preferences returned")(pref.member_id)(real_member_id);
    }
    TestValidator.predicate("all created preferences are returned")(
      createdPrefs.every(({ id }) => output.data.some((p) => p.id === id)),
    );
  }

  // 5. Filter by event_type (choose one)
  {
    const filter_type = createdPrefs[0].event_type;
    const filtered = createdPrefs.filter((p) => p.event_type === filter_type);
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: { event_type: filter_type },
    });
    typia.assert(output);
    TestValidator.equals("event_type filter count")(output.data.length)(filtered.length);
    TestValidator.predicate("event_type = filter_type")(output.data.every((p) => p.event_type === filter_type));
  }

  // 6. Filter by channel (choose one)
  {
    const filter_channel = createdPrefs[1].channel;
    const filtered = createdPrefs.filter((p) => p.channel === filter_channel);
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: { channel: filter_channel },
    });
    typia.assert(output);
    TestValidator.equals("channel filter count")(output.data.length)(filtered.length);
    TestValidator.predicate("channel = filter_channel")(output.data.every((p) => p.channel === filter_channel));
  }

  // 7. Filter by opt_in
  {
    const filter_optin = createdPrefs[2].opt_in;
    const filtered = createdPrefs.filter((p) => p.opt_in === filter_optin);
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: { opt_in: filter_optin },
    });
    typia.assert(output);
    TestValidator.equals("opt_in filter count")(output.data.length)(filtered.length);
    TestValidator.predicate("all opt_in = filter")(output.data.every((p) => p.opt_in === filter_optin));
  }

  // 8. Combined filter: event_type+channel+opt_in (pick one record)
  {
    const pick = createdPrefs[3];
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: {
        event_type: pick.event_type,
        channel: pick.channel,
        opt_in: pick.opt_in,
      },
    });
    typia.assert(output);
    TestValidator.equals("combined filter count")(output.data.length)(1); // only one such
