import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPageIPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardReport";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator searching and filtering of reports on a comment, with pagination and error case handling.
 *
 * Ensures the following workflow:
 * 1. Moderator registers and logs in to obtain privileged access
 * 2. A post is created as a member
 * 3. A comment is left on the post as a member
 * 4. Two reports are filed against the comment for different reasons (using available member session)
 * 5. The moderator uses the search API to:
 *    - Retrieve all reports for the comment
 *    - Filter reports by reason_code (e.g., 'spam')
 *    - Filter reports by reporter_member_id
 *    - Paginate results (limit=1)
 *    - Search for a random/fake commentId to check empty results
 *    - Attempt invalid commentId (should error)
 *    - Attempt unauthenticated access (should error)
 * 6. Each response is asserted for correct filtering, paging, and type conformance
 *
 * This validates robust moderator-side tools for abuse reporting oversight, verifies filter and paging logic, and enforces role-based access controls to report search.
 */
export async function test_api_comment_report_search_pagination_and_filtering_moderator(connection: api.IConnection) {
  // 1. Register and login as moderator
  const modEmail: string = typia.random<string & tags.Format<"email">>();
  const modPassword = "TestPassword12!";
  const displayName = RandomGenerator.name();
  const consentStatus = "accepted-v1";
  // Register new moderator
  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registration);
  TestValidator.equals("mod email matches")(registration.email)(modEmail);

  // Login to get Authorization set
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(login);
  TestValidator.equals("mod login email")(login.email)(modEmail);

  // 2. Create a post as a member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()().slice(0,50),
      body: RandomGenerator.content()()().slice(0,100),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Add a comment to the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()()().slice(0,60)
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. File two reports from simulated member session
  // Use two distinct reason codes for filtering tests
  const reasonCodes = ["abuse", "spam", "hate", "off_topic", "other"];
  const pickedReason1 = RandomGenerator.pick(reasonCodes);
  const pickedReason2 = "spam";
  // First report
  const report1 = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: pickedReason1,
      reason_description: "Report reason one.",
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report1);
  // Second report
  const report2 = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: pickedReason2,
      reason_description: "Report reason two (spam).",
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report2);

  // 5a. Moderator fetches all reports for this comment (no filter)
  const allPage = await api.functional.polEcoBoard.moderator.comments.reports.search(connection, {
    commentId: comment.id,
    body: {} satisfies IPolEcoBoardReport.IRequest,
  });
  typia.assert(allPage);
  TestValidator.predicate("should return at least 2 reports")(Array.isArray(allPage.data) && allPage.data.length >= 2);
  const ids = allPage.data.map((r) => r.id);
  TestValidator.equals("contains report1")(ids.includes(report1.id))(true);
  TestValidator.equals("contains report2")(ids.includes(report2.id))(true);

  // 5b. Filter by reason_code ('spam')
  const spamPage = await api.functional.polEcoBoard.moderator.comments.reports.search(connection, {
    commentId: comment.id,
    body: { reason_code: pickedReason2 } satisfies IPolEcoBoardReport.IRequest,
  });
  typia.assert(spamPage);
  TestValidator.predicate("all reason_code is 'spam'")(spamPage.data.every((r) => r.reason_code === pickedReason2));
  TestValidator.predicate("non-empty spam filter")(spamPage.data.length > 0);

  // 5c. Filter by reporter_member_id
  const reporterId = report1.reporter_member_id;
  const byReporter = await api.functional.polEcoBoard.moderator.comments.reports.search(connection, {
    commentId: comment.id,
    body: { reporter_member_id: reporterId } satisfies IPolEcoBoardReport.IRequest,
  });
  typia.assert(byReporter);
  TestValidator.predicate("all have reporter_member_id")(byReporter.data.every((r) => r.reporter_member_id === reporterId));

  // 5d. Pagination: limit = 1
  const paged = await api.functional.polEcoBoard.moderator.comments.reports.search(connection, {
    commentId: comment.id,
    body: { limit: 1, page: 1 } satisfies IPolEcoBoardReport.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("limit=1 returns at most 1")(paged.data.length <= 1)(true);

  // 5e. Search on a commentId with no reports (random new commentId)
  const noReportsRes = await api.functional.polEcoBoard.moderator.comments.reports.search(connection, {
    commentId: typia.random<string & tags.Format<"uuid">>(),
    body: {} satisfies IPolEcoBoardReport.IRequest,
  });
  typia.assert(noReportsRes);
  TestValidator.equals("no reports should be returned")(noReportsRes.data.length)(0);

  // 5f. Invalid commentId format
  await TestValidator.error("invalid commentId should error")(async () => {
    await api.functional.polEcoBoard.moderator.comments.reports.search(connection, {
      commentId: "not-a-uuid" as any,
      body: {} as any,
    });
  });

  // 5g. Unauthorized search (remove Authorization header)
  const noAuthConn = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };
  await TestValidator.error("missing Authorization should error")(async () => {
    await api.functional.polEcoBoard.moderator.comments.reports.search(noAuthConn, {
      commentId: comment.id,
      body: {} satisfies IPolEcoBoardReport.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test creation of a new abuse report against a comment as a member, covering business rules and error prevention for duplicate and unauthorized behavior.
 *
 * This test validates the following:
 * - Successful creation of a report with required reason_code and optional reason_description (unique first report by a member).
 * - Duplicate prevention: Block the same member from reporting the same comment with the identical reason more than once.
 * - Error cases: invalid commentId for reporting returns error, unauthorized/guest users cannot report comments (are blocked).
 *
 * Test steps:
 * 1. Register a new member account (the "reporting" user).
 * 2. Log in as this member to acquire authentication.
 * 3. Create a post (so a comment can belong to it).
 * 4. Add a comment to the post (target for reporting).
 * 5. Successfully create a first report against the comment (valid reason_code, optional reason_description).
 * 6. Attempt to file a duplicate report (same member, same comment, reason_code) and expect error.
 * 7. Attempt to file a report with an invalid commentId (expect error).
 * 8. Log out (simulate guest/unauthenticated state) and attempt to report the comment (expect error).
 *
 * Each step asserts correct business and API behavior.
 */
export async function test_api_member_comment_report_creation_success_and_duplicate_block(
  connection: api.IConnection,
) {
  // 1. Register a new member account
  const baseEmail: string = typia.random<string & tags.Format<"email">>();
  const basePassword: string = RandomGenerator.alphaNumeric(12);
  const baseDisplayName: string = RandomGenerator.name();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: baseEmail,
      password_hash: basePassword,
      display_name: baseDisplayName,
      consent_status: "v1-consent-policy"
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Log in as this member for authenticated session
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: baseEmail,
      password: basePassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  // At this point, connection.headers contains Authorization for member

  // 3. Create a new post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(20),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Add a comment to the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()(10),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. File a unique abuse report on the comment (success case)
  const firstReportReason = "abuse"; // Assume one of allowed business values
  const firstReportDescription = "This comment is inappropriate.";
  const report1 = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: firstReportReason,
      reason_description: firstReportDescription,
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report1);
  TestValidator.equals("report is for comment")(report1.comment_id)(comment.id);
  TestValidator.equals("reporter member")(report1.reporter_member_id)(member.id);
  TestValidator.equals("reason code")(report1.reason_code)(firstReportReason);
  TestValidator.equals("description")(report1.reason_description)(firstReportDescription);

  // 6. Attempt to file a duplicate report (expect failure)
  await TestValidator.error("duplicate report should fail")(() =>
    api.functional.polEcoBoard.member.comments.reports.create(connection, {
      commentId: comment.id,
      body: {
        reason_code: firstReportReason,
        reason_description: firstReportDescription,
        comment_id: comment.id,
      } satisfies IPolEcoBoardReport.ICreate,
    })
  );

  // 7. Attempt to report with invalid commentId (expect failure)
  await TestValidator.error("invalid commentId should fail")(() =>
    api.functional.polEcoBoard.member.comments.reports.create(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(), // Should not exist
      body: {
        reason_code: "spam",
        reason_description: "Clearly spam.",
        comment_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IPolEcoBoardReport.ICreate,
    })
  );

  // 8. Simulate unauthenticated state by clearing connection.headers.Authorization
  const savedAuth = connection.headers?.Authorization;
  if (connection.headers) delete connection.headers.Authorization;
  await TestValidator.error("unauthenticated user cannot report")(() =>
    api.functional.polEcoBoard.member.comments.reports.create(connection, {
      commentId: comment.id,
      body: {
        reason_code: "abuse",
        reason_description: "Guest cannot report",
        comment_id: comment.id,
      } satisfies IPolEcoBoardReport.ICreate,
    })
  );
  // Restore auth for further tests
  if (connection.headers && savedAuth) connection.headers.Authorization = savedAuth;
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
