 * This test verifies the following workflow:
 * 1. Moderator registers and logs in
 * 2. Two distinct members register and log in
 * 3. Member1 creates a post
 * 4. Member1 upvotes their own post, generating a vote
 * 5. Member2 downvotes the same post, generating a second vote
 * 6. Moderator retrieves each vote by voteId and verifies all details are accessible and correct
 * 7. Moderator attempts to retrieve a non-existent voteId, ensuring the proper error is returned
 * 8. A member attempts to call the moderator-only endpoint and is denied
 *
 * This ensures:
 * - Moderator role has access to all required vote details
 * - Members are properly forbidden from using moderator endpoints
 * - Error handling for non-existent voteIds works as intended
 */
export async function test_api_post_vote_moderator_retrieve_any_vote_and_permission(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Mod@123!!";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
