  // 3. Register two standard members
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1Password = "TestMem1!2024";
  const member1Reg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    },
  });
  typia.assert(member1Reg);

  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Password = "TestMem2!2024";
  const member2Reg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    },
  });
  typia.assert(member2Reg);

  // 4. Log in as member1
  const member1Login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    },
  });
  typia.assert(member1Login);

  // 5. Member1 creates a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(20),
      body: RandomGenerator.content()(100),
    },
  });
  typia.assert(post);

  // 6. Member1 votes (upvote)
  const vote1 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: {
      vote_value: 1,
    },
  });
  typia.assert(vote1);

  // 7. Log in as member2
  const member2Login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    },
