  // 8. Member2 votes (downvote)
  const vote2 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: {
      vote_value: -1,
    },
  });
  typia.assert(vote2);

  // 9. Log back in as moderator to test retrieval and permissions
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });

  // 10. Moderator retrieves each vote and validates details
  for (const vote of [vote1, vote2]) {
    const modView = await api.functional.polEcoBoard.moderator.posts.votes.at(connection, {
      postId: post.id,
      voteId: vote.id,
