 *
 * Steps:
 * 1. Attempt to search for guests without any authentication. Expect an authorization error.
 * 2. Register a new admin user.
 * 3. Login as the admin user to acquire a valid admin JWT (for positive control, not used in negative test).
 * 4. Manually remove Authorization header (simulate guest/no-token access) and call again.
 * 5. (If feasible) Simulate a non-admin token (not technically possible with only admin endpoints; skip if only admin role is supported).
 * 6. Confirm that the endpoint does not return guest data in any unauthorized scenario.
 * 7. (Optional) With the valid admin JWT, confirm that search does succeed (positive contrast, not focus of this test).
 */
export async function test_api_guest_session_search_unauthorized(connection: api.IConnection) {
  // 1. Attempt search without any authentication (bare connection)
  TestValidator.error("Guest access should be denied")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.search(connection, {
        body: typia.random<IPolEcoBoardGuest.IRequest>()
      });
