    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(loginResp);
  const adminToken = loginResp.setHeaders.Authorization;

  // 4. Try search with explicit removal of Authorization (simulate logout or guest)
  const guestConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined
    }
  };
  TestValidator.error("Explicitly no-Authorization should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.search(guestConnection, {
        body: typia.random<IPolEcoBoardGuest.IRequest>()
      });
    }
  );

  // 5. (Non-admin JWT negative test skipped, as only admin auth endpoints exist.)

  // 6. Positive control: confirm access works with valid admin token
  const adminConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: adminToken
    }
  };
  const success = await api.functional.polEcoBoard.admin.guests.search(adminConnection, {
    body: typia.random<IPolEcoBoardGuest.IRequest>()
  });
  typia.assert(success);
}

