import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate member access to their own post attachment details (metadata and download information).
 *
 * Business rationale: Only the post author (authenticated member) should be able to fetch the details/metadata for a specific attachment on their own post. This validates access control, metadata accuracy, and correct attachment-to-post linkage. The returned object must include all fields (ids, filenames, URIs, file size, mime type, author id, timestamps, and deletion status).
 *
 * Steps:
 * 1. Register a new member using a unique email and password.
 * 2. Log in as that member (to obtain and store Authorization tokens on the connection).
 * 3. Create a new post under a random category with basic title/body.
 * 4. Attach a file to that post using valid metadata (uri, file_name, file_size_bytes, mime_type).
 * 5. Retrieve the attachment details via API and validate all field-level metadata, including author_member_id matches our account, file properties, and download uri.
 */
export async function test_api_post_attachment_details_member_access(
  connection: api.IConnection,
) {
  // 1. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const registerResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(registerResult);

  // 2. Login to get token
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(loginResult);

  // 3. Create a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(25),
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(createdPost);

  // 4. Add an attachment to the post
  const attachmentInput = {
    uri: RandomGenerator.alphaNumeric(30),
    file_name: RandomGenerator.alphaNumeric(8) + ".pdf",
    file_size_bytes: typia.random<number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<1000000>>(),
    mime_type: "application/pdf",
  };
  const createdAttachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: createdPost.id,
    body: attachmentInput,
  });
  typia.assert(createdAttachment);

  // 5. Retrieve the attachment by ID as the author
  const loadedAttachment = await api.functional.polEcoBoard.member.posts.attachments.at(connection, {
    postId: createdPost.id,
    attachmentId: createdAttachment.id,
  });
  typia.assert(loadedAttachment);

  // Validate all key fields and ownership
  TestValidator.equals("author ID matches")(loadedAttachment.author_member_id)(createdPost.author_member_id);
  TestValidator.equals("post linkage")(loadedAttachment.post_id)(createdPost.id);
  TestValidator.equals("file name")(loadedAttachment.file_name)(attachmentInput.file_name);
  TestValidator.equals("file size")(loadedAttachment.file_size_bytes)(attachmentInput.file_size_bytes);
