 *   8. Continue (optionally) to maximum allowed tags, then attempt to exceed: expect error (if policy is visible, usually 5 tags max).
 *   9. Try to assign a random non-existent tag (random UUID): expect error.
 *  10. Register a second member and login (not the post author).
 *  11. Attempt to assign a (valid) tag to the post while logged in as non-author: expect error (permission/AUTH constraint).
 *
 *   All API responses must be validated for correct DTO typing. All business errors are checked for actual error throw (TestValidator.error) but not for specific message contents. No type-system violation cases.
 */
export async function test_api_member_post_tag_assignment_success_and_constraint(
  connection: api.IConnection,
) {
  // 1. Register and login as a new member (the author)
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphabets(10);
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email,
      password_hash: password, // Normally expects hash; for test, plaintext for login/demo
      display_name: RandomGenerator.name(),
      consent_status: "v1-consented",
    } satisfies IPolEcoBoardMember.ICreate
  });

  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn
  });

  // 2. Create category for board
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `TestCategory-${RandomGenerator.alphabets(5)}`,
      description: "Category for tag assignment test.",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create the board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: `TestBoard-${RandomGenerator.alphabets(5)}`,
      code: `board${RandomGenerator.alphaNumeric(3)}`.toLowerCase(),
      is_public: true,
      is_archived: false,
      description: "Board for member tag assign test.",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Obtain at least two tags to assign to the post (search)
  let tag1;
  let tag2;
  let availableTagsPage = await api.functional.polEcoBoard.tags.search(connection, {
    body: { page: 1, limit: 10 } satisfies IPolEcoBoardTag.IRequest,
  });
  typia.assert(availableTagsPage);
  if (availableTagsPage.data.length >= 2) {
    [tag1, tag2] = availableTagsPage.data.slice(0, 2);
  } else {
    throw new Error("Not enough tags exist in the system. Please provision at least two tags for this test.");
  }

  // 5. Member creates a post with no tags initially
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(100),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Assign first tag to post: expect success
  const postTag1 = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: { tag_id: tag1.id } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(postTag1);
  TestValidator.equals("assigned post_id matches")(postTag1.post_id)(post.id);
  TestValidator.equals("assigned tag_id matches")(postTag1.tag_id)(tag1.id);

  // 7. Assign the same tag again: expect uniqueness/duplicate error
  TestValidator.error("cannot assign the same tag twice")(() =>
    api.functional.polEcoBoard.member.posts.postTags.create(connection, {
      postId: post.id,
      body: { tag_id: tag1.id } satisfies IPolEcoBoardPostTag.ICreate,
    })
  );

  // 8. Assign a second, distinct tag: expect success
  const postTag2 = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: { tag_id: tag2.id } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(postTag2);
  TestValidator.equals("assigned post_id matches")(postTag2.post_id)(post.id);
  TestValidator.equals("assigned tag_id matches")(postTag2.tag_id)(tag2.id);

  // 9. Attempt to assign a random non-existent tag: expect error
  TestValidator.error("cannot assign non-existent tag")(() =>
    api.functional.polEcoBoard.member.posts.postTags.create(connection, {
      postId: post.id,
      body: { tag_id: typia.random<string & tags.Format<"uuid">>() } as IPolEcoBoardPostTag.ICreate,
    })
  );

  // 10. Optionally test max tag count limit (if >2 tags are available)
  if (availableTagsPage.data.length > 2) {
    for (let i = 2; i < availableTagsPage.data.length; ++i) {
      await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
        postId: post.id,
        body: { tag_id: availableTagsPage.data[i].id } satisfies IPolEcoBoardPostTag.ICreate,
      });
    }
    // Attempt to exceed tag count (try new random UUID)
    TestValidator.error("exceed max tag count")(() =>
      api.functional.polEcoBoard.member.posts.postTags.create(connection, {
        postId: post.id,
        body: { tag_id: typia.random<string & tags.Format<"uuid">>() } as IPolEcoBoardPostTag.ICreate,
      })
    );
  }

  // 11. Register a second member (not the post author) and login
  const email2 = typia.random<string & tags.Format<"email">>();
  const password2 = RandomGenerator.alphabets(10);
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: email2,
      password_hash: password2,
      display_name: RandomGenerator.name(),
      consent_status: "v1-consented",
    } satisfies IPolEcoBoardMember.ICreate
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: email2, password: password2 } satisfies IMemberAuthenticationMemberSignIn
  });

  // 12. Attempt to assign tag as non-owner: expect error
  TestValidator.error("cannot assign tag as non-author")(() =>
    api.functional.polEcoBoard.member.posts.postTags.create(connection, {
      postId: post.id,
      body: { tag_id: tag1.id } satisfies IPolEcoBoardPostTag.ICreate,
    })
  );
}

