  // 6. Moderator soft-deletes the post
  await api.functional.polEcoBoard.moderator.posts.eraseByPostid(connection, {
    postId: createdPost.id,
  });

  // 7. No direct API to verify deleted_at (SDK limitation); for completeness test would require admin/audit fetch.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the deletion of moderation audit records and test access control.
 *
 * Business context:
 * - Only admin accounts may delete moderation audit records.
 * - Deleting an audit that is already deleted or does not exist must result in a not-found error.
 * - Attempts by non-admins must be denied with a proper error (permission denied/unauthorized).
 *
 * Test steps:
 * 1. Register and log in as a new admin (password of at least 8 chars).
 * 2. Create a moderation action (required for audit association).
 * 3. Create an audit record for that moderation action.
 * 4. Delete the audit as admin (success case).
 * 5. Verify that re-deletion of the same audit fails (not found).
 * 6. Attempt audit deletion as non-admin (simulate by using a connection without admin Authorization header).
 * 7. Attempt deletion with a random non-existent auditId, expect not found error.
 */
export async function test_api_moderation_audit_delete_success_and_access_control(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(registerRes);

  // 2. Log in as admin to set Authorization for privileged requests
  const loginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginRes);
  // Authorization header is now set for subsequent privileged API calls

  // 3. Create a moderation action (the parent for the audit)
  const actionInput = {
    report_id: typia.random<string & tags.Format<"uuid">>(),
    operator_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: RandomGenerator.alphabets(8),
    target_type: RandomGenerator.alphabets(6),
    status: "pending",
    rationale: RandomGenerator.paragraph()(),
    outcome: "accepted",
  } satisfies IPolEcoBoardModerationAction.ICreate;
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(
    connection,
    { body: actionInput },
  );
  typia.assert(moderationAction);

  // 4. Create an audit associated with the moderation action
  const auditInput = {
    moderation_action_id: moderationAction.id,
    auditor_id: moderationAction.operator_id,
    pre_state_snapshot: JSON.stringify(moderationAction),
    post_state_snapshot: JSON.stringify(moderationAction),
    reason: RandomGenerator.content()()(),
  } satisfies ModerationAudit.ICreate;
  const moderationAudit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(
    connection,
    {
      moderationActionId: moderationAction.id,
      body: auditInput,
    },
  );
  typia.assert(moderationAudit);

  // 5. Successfully delete the audit as admin
  await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
    connection,
    { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
  );

  // 6. Try to delete the audit again (must fail with not found)
  await TestValidator.error("second delete of same audit must fail")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 7. Attempt deletion as non-admin (simulate by removing admin Authorization header)
  const anonConnection = { ...connection, headers: {} } satisfies api.IConnection;
  await TestValidator.error("non-admin/unauthenticated cannot delete audit")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        anonConnection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 8. Attempt to delete a non-existent audit under this moderation action
  await TestValidator.error("deleting random auditId fails")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        {
          moderationActionId: moderationAction.id,
          auditId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardSanction";
import type { IPageIPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardSanction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test that a moderator can search for sanctions within their permitted scope, and that filtering, pagination, and status/type work as designed.
 *
 * The test workflow:
 *   1. Register a new moderator account
 *   2. Log in as the moderator, confirm authentication
 *   3. Create a moderation action with the moderator's ID
 *   4. Create a new sanction under that action for a dummy sanctioned user
 *   5. Perform multiple sanctions searches using:
 *      a. moderation_action_id
 *      b. sanctioned_user_id
 *      c. sanction_type and status
 *      d. pagination (page/limit)
 *      e. start_from / end_to date range
 *   6. Confirm that results reflect the correct filters and only allow visible sanctions in moderator scope
 *   7. Perform search with malformed filter (bad status) and confirm error is thrown
 *   8. Register another moderator with no sanctions in scope, check that it cannot view the original created sanction
 */
export async function test_api_sanction_search_moderator_access_scope_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestP@ssw0rd1!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accepted-v1",
    },
  });
  typia.assert(moderatorSignUp);
  const moderatorId = moderatorSignUp.moderatorId;

  // 2. Log in as moderator and verify identity
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("moderator ID matches")(moderatorLogin.moderatorId)(moderatorId);
  TestValidator.equals("moderator email matches")(moderatorLogin.email)(moderatorEmail);

  // 3. Create moderation action
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: moderatorId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "E2E test moderation action rationale",
      outcome: "accepted",
    },
  });
  typia.assert(moderationAction);
  TestValidator.equals("moderation action operator_id")(moderationAction.operator_id)(moderatorId);

  // 4. Create a sanction under that action for a dummy user
  const sanctionedUserId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const sanction = await api.functional.polEcoBoard.moderator.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      sanctioned_user_id: sanctionedUserId,
      sanction_type: "ban",
      status: "active",
      rationale: "E2E test sanction rationale",
      start_at: now.toISOString(),
      end_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(),
    },
  });
  typia.assert(sanction);
  TestValidator.equals("sanction operator id via moderation action")(sanction.moderation_action_id)(moderationAction.id);
  TestValidator.equals("sanctioned user matches")(sanction.sanctioned_user_id)(sanctionedUserId);

  // --- 5. SEARCH FILTERS ---
  // 5a. Search by moderation_action_id
  const searchByAction = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: moderationAction.id },
  });
  typia.assert(searchByAction);
  TestValidator.predicate("search by moderation_action_id yields sanction")(
    searchByAction.data.some(s => s.id === sanction.id)
  );

  // 5b. Search by sanctioned_user_id
  const searchByUser = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { sanctioned_user_id: sanctionedUserId },
  });
  typia.assert(searchByUser);
  TestValidator.predicate("search by sanctioned_user_id yields sanction")(
    searchByUser.data.some(s => s.id === sanction.id)
  );

  // 5c. Search by sanction_type and status
  const searchByTypeAndStatus = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: {
      sanction_type: "ban",
      status: "active",
    },
  });
  typia.assert(searchByTypeAndStatus);
  TestValidator.predicate("search by sanction_type/status yields sanction")(
    searchByTypeAndStatus.data.some(s => s.id === sanction.id)
  );

  // 5d. Pagination test (limit=1)
  const pagedResults = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { page: 1, limit: 1 },
  });
  typia.assert(pagedResults);
  TestValidator.equals("pagination limit=1")(pagedResults.data.length)(1);

  // 5e. Date range (start_from/end_to)
  const searchByDateRange = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: {
      start_from: now.toISOString(),
      end_to: sanction.end_at,
    },
  });
  typia.assert(searchByDateRange);
  TestValidator.predicate("search by date range yields sanction")(
    searchByDateRange.data.some(s => s.id === sanction.id)
  );

  // 6. Scope enforcement: search by random moderation_action_id should not yield this sanction
  const unrelatedActionId = typia.random<string & tags.Format<"uuid">>();
  const unrelatedSearch = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: unrelatedActionId },
  });
  typia.assert(unrelatedSearch);
  TestValidator.predicate("unrelated moderation_action_id does not show sanction")(
    unrelatedSearch.data.every(s => s.id !== sanction.id)
  );

  // 7. Malformed filter: status with a value not in business list
  TestValidator.error("bad status value throws error")(() =>
    api.functional.polEcoBoard.moderator.sanctions.search(connection, {
      body: { status: "not-a-valid-status" },
    })
  );

  // 8. Insufficient permissions: new moderator cannot see other moderator's sanctions
  const outsiderEmail = typia.random<string & tags.Format<"email">>();
  const outsiderPassword = "AnotherMod!2";
  const outsiderReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: outsiderEmail,
      password: outsiderPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accepted-v1",
    },
  });
  typia.assert(outsiderReg);
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: outsiderEmail,
      password: outsiderPassword,
    },
  });
  const outsiderSearch = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: moderationAction.id },
  });
  typia.assert(outsiderSearch);
  TestValidator.predicate("outsider moderator cannot see created sanction")(
    !outsiderSearch.data.some(s => s.id === sanction.id)
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
