import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Verify that a member cannot delete an attachment from a post owned by another member (permission denied).
 *
 * This test ensures robust authorization for attachment deletion in the polEcoBoard API:
 * - Only the post's author (or privileged moderator/admin, not covered here) may remove an attachment from their own post.
 * - A member should not be able to delete another member's post attachment and must receive a permission error instead.
 * - The integrity of the post and its attachments remain intact if unauthorized deletion is attempted.
 *
 * Business flow:
 * 1. Register Member A (post/attachment owner).
 * 2. Log in as Member A; create a new post in some category.
 * 3. Add an attachment to this post as Member A.
 * 4. Register Member B (unauthorized member), log in as Member B.
 * 5. Attempt to delete Member A's post attachment as Member B; expect permission denied error.
 * 6. (If possible) Validate that post and attachment are NOT deleted (by checking they remain present).
 */
export async function test_api_post_attachment_delete_member_permission_denied(connection: api.IConnection) {
  // 1. Register Member A
  const memberA_email = typia.random<string & tags.Format<"email">>();
  const memberA_password = typia.random<string & tags.Format<"password">>();
  const signUpA = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });
  typia.assert(signUpA);
  // Switch to Member A's token for authenticated requests
  connection.headers.Authorization = signUpA.setHeaders.Authorization;

  // 2. Create a new post as Member A
  const newPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Unique Post Title " + (Math.random() * 1000000).toFixed(0),
      body: "Body of the post - minimum 10 characters.",
    },
  });
  typia.assert(newPost);

  // 3. Add an attachment as Member A
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: newPost.id,
    body: {
      uri: "https://cdn.example.com/file/" + typia.random<string & tags.Format<"uuid">>(),
      file_name: "file.txt",
      file_size_bytes: 1024,
      mime_type: "text/plain",
    },
  });
  typia.assert(attachment);

  // 4. Register Member B
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_password = typia.random<string & tags.Format<"password">>();
  const signUpB = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  typia.assert(signUpB);

  // 5. Log in as Member B (authority switching)
  const signInB = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  typia.assert(signInB);
  connection.headers.Authorization = signInB.setHeaders.Authorization;

  // 6. Attempt to erase the attachment owned by Member A, expect permission error
  await TestValidator.error("member B cannot delete another member's post attachment")(
    async () => {
      await api.functional.polEcoBoard.member.posts.attachments.erase(connection, {
        postId: newPost.id,
        attachmentId: attachment.id,
      });
    }
  );
}

