/**
 * Validates the admin's capability to remove a tag assignment from a post.
 *
 * This test ensures that only a privileged admin can erase a tag assignment (not the tag entity itself) from a post, covering:
 *  - Admin registration and login flow
 *  - Category and board creation
 *  - Tag creation by admin
 *  - Member account registration and login
 *  - Post creation by member
 *  - Tag assignment by member
 *  - Tag assignment deletion by admin
 *  - Verification that tag assignment is removed, tag entity remains
 *  - Confirmation no errors are thrown on valid operations
 *
 * Step-by-step process:
 * 1. Register a new admin and login
 * 2. Admin creates a category
 * 3. Admin creates a board under that category
 * 4. Admin creates a tag
 * 5. Register new member and login as member
 * 6. Member creates a post under the new category
 * 7. Member assigns the tag to the post
 * 8. Switch to admin session and delete the tag assignment
 * 9. Member reassigns the tag to the post to assert deletion was successful
 * 10. Assert tag entity remains (not deleted)
 */
export async function test_api_post_tag_deletion_by_admin_success(connection: api.IConnection) {
