import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPageIPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin search for post attachments is unauthorized without a valid session.
 *
 * This test ensures that PATCH /polEcoBoard/admin/posts/{postId}/attachments
 * (admin search/filter on post attachments) is inaccessible unless called with
 * a valid/authorized admin JWT. The test covers two attack/abuse vectors:
 *
 * 1. Attempt using NO Authorization header at all (completely unauthenticated).
 * 2. Attempt using an INVALID/forged Authorization header (e.g. "Bearer invalidtoken").
 *
 * For both, the endpoint must return an appropriate HTTP authorization error (typically 401/403),
 * must NOT leak any confidential file/attachment metadata (e.g., URIs, file names, MIME types),
 * and must uphold platform compliance requirements by ensuring information disclosure is prevented.
 *
 * The setup builds a fully valid resource chain: admin registration, board/category, member, post, and attachment
 * so the tested endpoint is called in a realistic state. Note: There is no endpoint for direct audit trail validation,
 * so this test ensures only business-side security: access control and no data leak in error output.
 *
 * Steps:
 * 1. Register and login as admin (for setup purposes).
 * 2. Create board category and board.
 * 3. Register and login a member; member creates a post and uploads an attachment.
 * 4. Try to search attachments as admin with:
 *    a) No Authorization header
 *    b) Invalid Authorization header
 * 5. Assert both attempts are denied (error thrown), and no attachment data is disclosed in error message.
 */
export async function test_api_post_attachment_search_by_admin_unauthorized(connection: api.IConnection) {
  // 1. Register and login as admin (use only for setup; NOT for unauthorized attempts)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Create necessary board category and board
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1).slice(0, 45),
      description: RandomGenerator.paragraph()(1).slice(0, 80),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(12).slice(0, 30),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(1).slice(0, 80),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Register and login a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  // Register (set password_hash = memberPassword as a test simplification)
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.alphabets(10),
      consent_status: "v1-consented",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  // Login to setup session for member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // Member creates post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1).slice(0, 60),
      body: RandomGenerator.paragraph()(1).repeat(3),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // Member uploads an attachment to the post
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: {
      uri: "https://cdn.example.com/testfile.dat",
      file_name: "testfile.dat",
      file_size_bytes: 45678,
      mime_type: "application/octet-stream",
    } satisfies IPolEcoBoardAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4a. Attempt PATCH as admin with NO token (no Authorization header at all)
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Admin patch attachment search with no token should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.attachments.search(unauthConn, {
        postId: post.id,
        body: {}, // empty search/filter is valid, should trigger access check
      });
    }
  );

  // 4b. Attempt PATCH as admin with INVALID token (wrong/forged value)
  const forgedConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer NotARealToken" } };
  await TestValidator.error("Admin patch attachment search with invalid token should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.attachments.search(forgedConn, {
        postId: post.id,
        body: {},
      });
    }
  );
  // If error exposes attachment/uri/etc. in the error's data, that would be a security leak (not checkable here)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdmin";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that access to admin details is forbidden for regular (non-admin) members.
 *
 * This test ensures that a regular member, once logged in, cannot access admin profile details via the /polEcoBoard/admin/admins/{adminId} endpoint. This enforces strict privilege boundaries and is essential for compliance and data security. Attempted unauthorized access must result in a forbidden error, and (in a production system) should be audited for compliance.
 *
 * Steps:
 * 1. Register a new admin account to create an adminId for test targeting
 * 2. Register a regular (non-admin) member account
 * 3. Log in as the member and set their session credentials on the connection
 * 4. As the member, attempt to retrieve the admin's profile via the admin detail API
 * 5. Confirm that the system returns a forbidden error (HTTP 403 or equivalent)
 * 6. (Audit logging validation is noted but not runtime-checked in this test)
 */
export async function test_api_admin_detail_forbidden_for_member(
  connection: api.IConnection,
) {
  // 1. Register a new admin account (for adminId target)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const adminResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminResp);

  // Retrieve adminId for the admin we just registered.
  // Since the API does not return adminId, we attempt to fetch admin's profile using the current admin session.
  // This works because the registration sets the JWT token for the just-created admin.
  const adminProfile = await api.functional.polEcoBoard.admin.admins.at(connection, {
    adminId: await extractAdminIdFromTokenOrSession(connection),
  });
  typia.assert(adminProfile);
  const adminId = adminProfile.id;

  // 2. Register a new regular member account
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);
  const memberDisplayName: string = RandomGenerator.name();
  const memberConsentStatus: string = "2024-consent";

  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: memberConsentStatus,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 3. Log in as the member (switch session context)
  const memberLoginResp = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginResp);

  // Apply the member's JWT Authorization token to the connection for further requests
  connection.headers = {
    ...connection.headers,
    ...memberLoginResp.setHeaders,
  };

  // 4. Attempt to retrieve the admin's details using the member privileges
  await TestValidator.error("Regular member must not access admin details")(
    async () => {
      await api.functional.polEcoBoard.admin.admins.at(connection, {
        adminId,
      });
    }
  );
  // 5. (Optional: Audit log validation could be performed if side channel support is available)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPageIPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator comment filtering and pagination.
 *
 * This test simulates the workflow of a moderator listing and filtering comments on a post with pagination—ensuring the dashboard/triage tools function as intended.
 *
 * Process:
 * 1. Register a moderator and log them in, initializing the connection for moderator access.
 * 2. Set up a board category and a board using admin endpoints (required to create a post structure under test).
 * 3. Create a single post (by member) in the board for receiving comments.
 * 4. Add multiple comments (between 12–24) to the post to enable pagination testing and filter variety.
 * 5. Issue PATCH (search) on the moderator comments listing endpoint with various IPolEcoBoardComment.IRequest filters:
 *    a. Filter by author (author_member_id of first comment).
 *    b. Pagination with custom page/limit (e.g., page: 2, limit: 5).
 *    c. Date range filtering (created_from/created_to based on created_at values).
 *    d. Flagged status filter.
 *    e. Parent comment filtering (for replies).
 * 6. In each invocation, asserts that the returned data matches the filters/paging requested, and pagination metadata is correct (page, limit, total).
 *
 * Ensures that the business rules for moderator search and pagination are accurately enforced and that UI/dashboard experiences are robust for moderators.
 */
export async function test_api_moderator_comment_list_filter_and_pagination(connection: api.IConnection) {
  // 1. Register moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword!123";
  const displayName = RandomGenerator.name();
  const consentStatus = "v1-consent-agreed";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);

  // 2. Login as moderator
  const loginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginRes);

  // 3. Create test category and board (admin endpoints; assumes moderator has admin rights or tests run with admin role)
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1, 3),
      description: RandomGenerator.paragraph()(1, 5),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(1, 3),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(1, 5),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 4. Create a post on the board as a member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(2, 4),
      body: RandomGenerator.content()(2, 4),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Add multiple comments (for pagination/filtering); randomly some will be flagged, and some will be replies
  const commentCount = typia.random<number & tags.Type<"int32"> & tags.Minimum<12> & tags.Maximum<24>>();
  const comments: IPolEcoBoardComment[] = [];
  for (let i = 0; i < commentCount; ++i) {
    let parentId: string | null = null;
    // Make every 5th comment a reply to previous comment, if possible
    if (i > 0 && i % 5 === 0) {
      parentId = comments[i - 1].id;
    }
    const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(1, 2),
        parent_comment_id: parentId || undefined,
      } satisfies IPolEcoBoardComment.ICreate,
    });
    typia.assert(comment);
    // Simulate flagging: Mark some comments as flagged for later filtering
    if (i % 6 === 0) {
      comment.flagged = true;
    }
    comments.push(comment);
  }

  // 6a. Moderator filters by author_member_id
  const targetAuthor = comments[0].author_member_id;
  const byAuthor = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      author_member_id: targetAuthor,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(byAuthor);
  for (const c of byAuthor.data) {
    TestValidator.equals("author filter")(c.author_member_id)(targetAuthor);
  }

  // 6b. Pagination test: page 2, limit 5
  const paged = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: 2,
      limit: 5,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("pagination.limit")(paged.pagination.limit)(5);
  TestValidator.equals("pagination.page")(paged.pagination.current)(2);

  // 6c. Date range filtering: use first/last comment created_at
  const createdFrom = comments[2].created_at;
  const createdTo = comments[comments.length - 2].created_at;
  const byRange = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      created_from: createdFrom,
      created_to: createdTo,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(byRange);
  for (const c of byRange.data) {
    TestValidator.predicate("createdAt range")(
      c.created_at >= createdFrom && c.created_at <= createdTo
    );
  }

  // 6d. Filter flagged comments (assuming some are flagged by test logic)
  const flagged = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      flagged: true,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(flagged);
  for (const c of flagged.data) {
    TestValidator.equals("flagged")(c.flagged)(true);
  }

  // 6e. Filter by parent_comment_id (should match reply comments)
  const reply = comments.find((c) => !!c.parent_comment_id);
  if (reply) {
    const parentFilter = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
      postId: post.id,
      body: {
        post_id: post.id,
        parent_comment_id: reply.parent_comment_id!,
      } satisfies IPolEcoBoardComment.IRequest,
    });
    typia.assert(parentFilter);
    for (const c of parentFilter.data) {
      TestValidator.equals("parent_comment_id")(c.parent_comment_id)(reply.parent_comment_id!);
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPageIPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin user can properly search, filter, and paginate abuse/moderation reports for a specific post.
 *
 * This comprehensive test covers:
 * 1. Set up: Register a new admin and log in, register a post as a member, and create several reports on that post as a member user.
 * 2. As an admin, call the report search (PATCH /polEcoBoard/admin/posts/{postId}/reports) endpoint with:
 *    - No filters (basic scan, first page expected)
 *    - Pagination (e.g. limit=2, page=2), verifying correct metadata and content
 *    - Filter by reason_code (should return only matching subset)
 *    - Filter by created_at range (should return only reports in this window)
 *    - Filter by reporter_member_id (only reports by a specific reporter)
 *    - All filters combined (should properly intersect sets)
 *    - Filter with intentionally excessive limits (should clip to allowed server max, e.g. 100)
 *    - Filter for an empty result (no matches)
 * 3. Negative cases:
 *    - Search for a non-existent postId (should yield empty or error)
 *    - Search for a deleted postId (should yield empty or error)
 *    - search as unauthenticated or with expired/bad token (should fail with auth error)
 *    - search with invalid postId format (should fail with validation error)
 *    - search as a non-admin (should fail with authorization error)
 *
 * Steps:
 * 1. Register and login as admin.
 * 2. Register and login as member (for creating a post and reports).
 * 3. Create a post as a member.
 * 4. File several reports against that post as a member (vary reason, description, and created_at via test timing).
 * 5. Switch to admin user.
 * 6. Exercise the /polEcoBoard/admin/posts/{postId}/reports endpoint with varied filters and paging as described above.
 * 7. Validate response types, content, pagination, and access controls.
 */
export async function test_api_post_report_search_by_admin_filter_pagination_error_handling(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Create a post as a member (simulate as member by using member post endpoint)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1, 2),
      body: RandomGenerator.content()(1, 3)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. File several reports as a member (simulate as ordinary member)
  // We'll file 3 reports with different reason_codes
  const reasons = ["abuse", "spam", "hate"];
  for (const reason of reasons) {
    const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
      postId: post.id,
      body: {
        reason_code: reason,
        reason_description: `Report for ${reason} at ${new Date().toISOString()}`,
        post_id: post.id,
      } satisfies IPolEcoBoardReport.ICreate,
    });
    typia.assert(report);
  }

  // 4. As admin, perform report searches with various filters & pagination
  // a) No filters (should return all above reports, correct pagination)
  let output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: {},
  });
  typia.assert(output);
  TestValidator.predicate("all reports returned")(output.data.length >= 3);
  TestValidator.equals("total records")(output.pagination.records)(output.data.length);

  // b) Pagination (limit=2, page=1)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(output);
  TestValidator.equals("pagination limit")(output.pagination.limit)(2);
  TestValidator.equals("pagination current page")(output.pagination.current)(1);
  TestValidator.predicate("page contains 2 or fewer entries")(output.data.length <= 2);

  // c) Filter by reason_code (reason_code = "spam")
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "spam" },
  });
  typia.assert(output);
  TestValidator.predicate("only spam reports")(output.data.every(r => r.reason_code === "spam"));

  // d) Date range filter (from now - 1min to now + 2min)
  const now = new Date();
  const from = new Date(now.getTime() - 60 * 1000).toISOString();
  const to = new Date(now.getTime() + 120 * 1000).toISOString();
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { created_at_start: from, created_at_end: to },
  });
  typia.assert(output);
  TestValidator.predicate("created in window")(output.data.every(r => r.created_at >= from && r.created_at <= to));

  // e) Reporter filter (reporter_member_id from a report)
  const firstReport = output.data[0];
  if (firstReport) {
    output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
      postId: post.id,
      body: { reporter_member_id: firstReport.reporter_member_id },
    });
    typia.assert(output);
    TestValidator.predicate("only first reporter")(output.data.every(r => r.reporter_member_id === firstReport.reporter_member_id));
  }

  // f) Combination filter (reason_code and date range)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "spam", created_at_start: from, created_at_end: to },
  });
  typia.assert(output);
  TestValidator.predicate("spam reports in window")(output.data.every(r => r.reason_code === "spam" && r.created_at >= from && r.created_at <= to));

  // g) Excessive limit (limit=1000, should be capped, but must not error)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 1000 },
  });
  typia.assert(output);
  TestValidator.predicate("limit not exceeded")(output.pagination.limit <= 100);

  // h) Empty result (impossible reason_code)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "nonexistent_reason_code_zzz" },
  });
  typia.assert(output);
  TestValidator.equals("empty data")(output.data.length)(0);

  // 5. Negative cases
  // i) Non-existent postId (random uuid)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: typia.random<string & tags.Format<"uuid">>(),
    body: {},
  });
  typia.assert(output);
  // We cannot guarantee error vs empty, but must not throw

  // j) Invalid postId format
  await TestValidator.error("malformed postId should fail")(async () => {
    await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
      postId: "not_a_uuid" as any,
      body: {},
    });
  });

  // k) Unauthenticated: remove token manually and attempt
  const oldAuth = connection.headers.Authorization;
  delete connection.headers.Authorization;
  await TestValidator.error("unauthenticated access fails")(async () => {
    await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
      postId: post.id,
      body: {},
    });
  });
  connection.headers.Authorization = oldAuth;

