import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate permission controls for deletion of guest session records.
 *
 * Only administrators should be able to delete guest session records due to the private and sensitive nature of the data. This test ensures that non-admin users — specifically, authenticated members and unauthenticated (public) users — are forbidden from deleting guest sessions via the admin-only endpoint.
 *
 * Test Procedure:
 * 1. Create a new guest session (as unauthenticated user).
 * 2. Register a normal (non-admin) member account and log in as that member.
 * 3. As an authenticated member, attempt to delete the guest session via the admin endpoint. This should result in a forbidden/unauthorized error.
 * 4. Log out to become the public/unauthenticated session.
 * 5. As a public (unauthenticated) user, attempt to delete the guest session via the admin endpoint. Again, this action must fail with a forbidden/unauthorized error.
 *
 * At each step, the API response must be checked to confirm proper enforcement of access controls and that non-admin users never succeed in deletion attempts.
 */
export async function test_api_guest_delete_forbidden_nonadmin(connection: api.IConnection) {
  // 1. Create a new guest session (public)
  const guest = await api.functional.polEcoBoard.guests.create(connection, {
    body: {
      ip_address: RandomGenerator.ip(),
      device_fingerprint: RandomGenerator.alphaNumeric(16),
      consent_status: RandomGenerator.alphabets(8),
    } satisfies IPolEcoBoardGuest.ICreate,
  });
  typia.assert(guest);

  // 2. Register a new member (non-admin)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);

  // 3. Log in as the member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);

  // 4. As authenticated member, try to delete guest (should fail)
  await TestValidator.error("non-admin member cannot delete guest via admin endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.erase(connection, {
        guestId: guest.id,
      });
    },
  );

  // 5. Become public session (simulate logout by removing Authorization header)
  if (connection.headers) delete connection.headers["Authorization"];

  // 6. As public user, try to delete guest (should fail)
  await TestValidator.error("unauthenticated user cannot delete guest via admin endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.erase(connection, {
        guestId: guest.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
