/**
 * E2E test: admin can search and filter post listings with all advanced filters, pagination and ordering on polEcoBoard.
 *
 * Business context: Validates that platform admins are able to audit or moderate any post (including deleted/flagged), are able to search by any filterable property (category, author, status, keyword, tag, date, views), and pagination/sorting works as expected. Covers edge cases—including empty result and invalid filters.
 *
 * Steps:
 * 1. Register and login as a new admin
 * 2. Create multiple posts with a diverse mix of category_id, title/body/keywords, tags, and various flags (simulate flagged/deleted by property if feasible)
 * 3. For each filter feature, perform a search with that filter and assert results match expectations
 * 4. Test pagination and ordering options
 * 5. Test edge cases: empty results, invalid search
 */
export async function test_api_admin_post_search_success_and_filtering(connection: api.IConnection) {
  // 1. Register and login as admin
