  });
  typia.assert(loginResponse);

  // 3. Attempt to delete a non-existent comment edit as moderator
  await TestValidator.error("Deleting invalid commentEditId must result in error")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.eraseByPostidAndCommentidAndCommenteditid(
        connection,
        {
          postId: typia.random<string & tags.Format<"uuid">>(),
          commentId: typia.random<string & tags.Format<"uuid">>(),
          commentEditId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostTag";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";
import type { IPageIPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate tag assignment workflow for polEcoBoard posts as a member (author).
 *
 * Test Purpose:
 *   - Ensure a post author (member) can successfully assign a tag to their own post.
 *   - Validate that adding the same tag twice fails with a business error (uniqueness enforcement).
 *   - Validate that exceeding maximum allowed tag count per post is rejected.
 *   - Ensure assignment of non-existent tag is rejected.
 *   - Ensure attempts to assign tags by a non-author member fail (permission constraint).
 *   - Confirm responses and audit (side effect, if visible in API) on all validation and business logic boundaries.
 *
 * Test Steps:
 *   1. Register a new member and login to get session context.
 *   2. Create a board category and a board (as necessary prerequisites for post creation).
 *   3. Create tags for test (at least 2 tags) to assign to posts.
 *   4. Member creates a post in the board/category.
 *   5. Assign first tag to the post: expect success.
 *   6. Assign the same tag again: expect error due to duplicate / uniqueness.
 *   7. Assign a second distinct tag: expect success.
 *   8. Continue (optionally) to maximum allowed tags, then attempt to exceed: expect error (if policy is visible, usually 5 tags max).
 *   9. Try to assign a random non-existent tag (random UUID): expect error.
 *  10. Register a second member and login (not the post author).
 *  11. Attempt to assign a (valid) tag to the post while logged in as non-author: expect error (permission/AUTH constraint).
 *
 *   All API responses must be validated for correct DTO typing. All business errors are checked for actual error throw (TestValidator.error) but not for specific message contents. No type-system violation cases.
 */
export async function test_api_member_post_tag_assignment_success_and_constraint(
  connection: api.IConnection,
) {
  // 1. Register and login as a new member (the author)
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphabets(10);
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email,
      password_hash: password, // Normally expects hash; for test, plaintext for login/demo
      display_name: RandomGenerator.name(),
      consent_status: "v1-consented",
    } satisfies IPolEcoBoardMember.ICreate
  });

  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn
  });

  // 2. Create category for board
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `TestCategory-${RandomGenerator.alphabets(5)}`,
      description: "Category for tag assignment test.",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create the board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: `TestBoard-${RandomGenerator.alphabets(5)}`,
      code: `board${RandomGenerator.alphaNumeric(3)}`.toLowerCase(),
      is_public: true,
      is_archived: false,
      description: "Board for member tag assign test.",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Obtain at least two tags to assign to the post (search)
  let tag1;
  let tag2;
  let availableTagsPage = await api.functional.polEcoBoard.tags.search(connection, {
    body: { page: 1, limit: 10 } satisfies IPolEcoBoardTag.IRequest,
  });
  typia.assert(availableTagsPage);
  if (availableTagsPage.data.length >= 2) {
    [tag1, tag2] = availableTagsPage.data.slice(0, 2);
  } else {
    throw new Error("Not enough tags exist in the system. Please provision at least two tags for this test.");
  }

  // 5. Member creates a post with no tags initially
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(100),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Assign first tag to post: expect success
  const postTag1 = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: { tag_id: tag1.id } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(postTag1);
  TestValidator.equals("assigned post_id matches")(postTag1.post_id)(post.id);
  TestValidator.equals("assigned tag_id matches")(postTag1.tag_id)(tag1.id);

  // 7. Assign the same tag again: expect uniqueness/duplicate error
  TestValidator.error("cannot assign the same tag twice")(() =>
    api.functional.polEcoBoard.member.posts.postTags.create(connection, {
      postId: post.id,
      body: { tag_id: tag1.id } satisfies IPolEcoBoardPostTag.ICreate,
    })
  );

  // 8. Assign a second, distinct tag: expect success
  const postTag2 = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: { tag_id: tag2.id } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(postTag2);
  TestValidator.equals("assigned post_id matches")(postTag2.post_id)(post.id);
  TestValidator.equals("assigned tag_id matches")(postTag2.tag_id)(tag2.id);

  // 9. Attempt to assign a random non-existent tag: expect error
  TestValidator.error("cannot assign non-existent tag")(() =>
    api.functional.polEcoBoard.member.posts.postTags.create(connection, {
      postId: post.id,
      body: { tag_id: typia.random<string & tags.Format<"uuid">>() } as IPolEcoBoardPostTag.ICreate,
    })
  );

  // 10. Optionally test max tag count limit (if >2 tags are available)
  if (availableTagsPage.data.length > 2) {
    for (let i = 2; i < availableTagsPage.data.length; ++i) {
      await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
        postId: post.id,
        body: { tag_id: availableTagsPage.data[i].id } satisfies IPolEcoBoardPostTag.ICreate,
      });
    }
    // Attempt to exceed tag count (try new random UUID)
    TestValidator.error("exceed max tag count")(() =>
      api.functional.polEcoBoard.member.posts.postTags.create(connection, {
        postId: post.id,
        body: { tag_id: typia.random<string & tags.Format<"uuid">>() } as IPolEcoBoardPostTag.ICreate,
      })
    );
  }

  // 11. Register a second member (not the post author) and login
  const email2 = typia.random<string & tags.Format<"email">>();
  const password2 = RandomGenerator.alphabets(10);
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: email2,
      password_hash: password2,
      display_name: RandomGenerator.name(),
      consent_status: "v1-consented",
    } satisfies IPolEcoBoardMember.ICreate
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: email2, password: password2 } satisfies IMemberAuthenticationMemberSignIn
  });

  // 12. Attempt to assign tag as non-owner: expect error
  TestValidator.error("cannot assign tag as non-author")(() =>
    api.functional.polEcoBoard.member.posts.postTags.create(connection, {
      postId: post.id,
      body: { tag_id: tag1.id } satisfies IPolEcoBoardPostTag.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can retrieve full details of a specific moderation audit record
 * and that access is denied for non-moderator roles or invalid input cases.
 *
 * Business context: This test ensures audit trail visibility for compliance and accountability,
 * while confirming that unauthorized persons cannot access audit records.
 *
 * Steps:
 * 1. Register a moderator (A).
 * 2. Log in as moderator A.
 * 3. Create a moderation action under moderator A's ID.
 * 4. Add an audit record to the action as moderator A.
 * 5. Retrieve the audit detail and validate all fields and linkages.
 * 6. Confirm error for non-existent auditId.
 * 7. Register/login as moderator B and confirm cross-moderator visibility.
 * 8. Simulate non-moderator fetch (no auth) and validate access is forbidden.
 */
export async function test_api_moderation_action_audit_detail_view_as_moderator(connection: api.IConnection) {
  // 1. Register moderator (A)
  const emailA: string = typia.random<string & tags.Format<"email">>();
  const passwordA = "SecureTestPassword123!";
  const moderatorA = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: emailA,
      password: passwordA,
      display_name: RandomGenerator.name(),
      consent_status: "agree-latest-privacy-policy-V1"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorA);

  // 2. Login as moderator A
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: emailA,
      password: passwordA
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

  // 3. Create moderation action as A
  const action = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: moderatorA.moderatorId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: RandomGenerator.paragraph()(),
      outcome: "accepted"
    } satisfies IPolEcoBoardModerationAction.ICreate
  });
  typia.assert(action);

  // 4. Add an audit record to the moderation action
  const audit = await api.functional.polEcoBoard.moderator.moderationActions.audits.create(connection, {
    moderationActionId: action.id,
    body: {
      moderation_action_id: action.id,
      auditor_id: moderatorA.moderatorId,
      pre_state_snapshot: JSON.stringify({ status: "pending" }),
      post_state_snapshot: JSON.stringify({ status: action.status }),
      reason: RandomGenerator.paragraph()()
    } satisfies IPolEcoBoardModerationAudit.ICreate
  });
  typia.assert(audit);

  // 5. Retrieve and validate the audit detail
  const detail = await api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
    moderationActionId: action.id,
    auditId: audit.id
  });
  typia.assert(detail);
  TestValidator.equals("audit id matches")(detail.id)(audit.id);
  TestValidator.equals("moderation_action_id matches")(detail.moderation_action_id)(action.id);
  TestValidator.equals("auditor_id matches")(detail.auditor_id)(moderatorA.moderatorId);
  TestValidator.equals("pre_state_snapshot matches")(detail.pre_state_snapshot)(audit.pre_state_snapshot);
  TestValidator.equals("post_state_snapshot matches")(detail.post_state_snapshot)(audit.post_state_snapshot);
  TestValidator.equals("reason matches")(detail.reason)(audit.reason);

  // 6. Negative: fetch with a non-existent auditId
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found for non-existent auditId")(() =>
    api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
      moderationActionId: action.id,
      auditId: nonExistentId
    })
  );

  // 7. Register/login as moderator B and confirm audit accessibility
  const emailB: string = typia.random<string & tags.Format<"email">>();
  const passwordB = "DifferentPassword456!";
  const moderatorB = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: emailB,
      password: passwordB,
      display_name: RandomGenerator.name(),
      consent_status: "agree-latest-privacy-policy-V1"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorB);

  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: emailB,
      password: passwordB
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  const detailByOther = await api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
    moderationActionId: action.id,
    auditId: audit.id
  });
  typia.assert(detailByOther);
  TestValidator.equals("audit accessible to other moderator")(detailByOther.id)(audit.id);

  // 8. Simulate non-moderator fetch: clear Authorization
  connection.headers = { ...connection.headers, Authorization: undefined };
  TestValidator.error("forbidden for anonymous/non-moderator access")(() =>
    api.functional.polEcoBoard.moderator.moderationActions.audits.at(connection, {
      moderationActionId: action.id,
      auditId: audit.id
    })
  );
}

