import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCommentEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate administrative creation of a comment edit record for compliance/correction flows.
 *
 * This test simulates an admin forcing a comment edit entry:
 *  1. Admin registers and logs in, becoming the editor context.
 *  2. Member registers and logs in to create real content the admin will manage.
 *  3. The member creates a new post (minimal required fields, business-typical data).
 *  4. The member adds a comment to the post to establish an auditable comment history.
 *  5. Admin logs in again if needed (to ensure context for privileged action).
 *  6. Admin performs manual creation of a comment edit (edit body and optional reason).
 *
 * This test validates:
 *  - Proper creation and linkage between post, comment, and resulting comment edit (IDs must match as expected).
 *  - The edit attributed to the admin as editor_member_id (type structure only -- no cross-query here).
 *  - Edit content and reason are exactly as given.
 *  - Auditability via non-null created_at.
 *
 * Error scenario:
 *  - Attempt to create a comment edit for a non-existent comment (random UUID) and verify an error is thrown.
 */
export async function test_api_admin_create_comment_edit_record(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminJoinRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminJoinRes);

  // 2. Log in as admin for a fresh token (privileged context)
  const adminLoginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginRes);

  // 3. Register a member to author content
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberRegRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRegRes);

  // 4. Member logs in
  const memberLoginRes = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginRes);

  // 5. Member creates a post to be edited
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10, 50),
      body: RandomGenerator.content()(30, 300, 1000),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Member creates a comment under that post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()(10, 30, 300),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 7. Switch back to admin privilege context
  const adminReloginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminReloginRes);

  // 8. Admin manually creates a comment edit record for the member's comment
  const editBody = `[Edited by admin] ` + RandomGenerator.content()(20, 30, 150);
  const editReason = "Compliance correction test.";
  const edit = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.create(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      edit_body: editBody,
      edit_reason: editReason,
    } satisfies IPolEcoBoardCommentEdit.ICreate,
  });
  typia.assert(edit);
  TestValidator.equals("Edit linkage to comment")(edit.comment_id)(comment.id);
  TestValidator.equals("Edit body content matches")(edit.edit_body)(editBody);
  TestValidator.equals("Edit reason matches")(edit.edit_reason)(editReason);
  TestValidator.predicate("Edit timestamp exists")(!!edit.created_at);

  // 9. Validate error occurs for non-existent comment ID
  TestValidator.error("Should fail for nonexistent comment")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.comments.commentEdits.create(connection, {
        postId: post.id,
        commentId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          edit_body: "[Nonexistent comment edit]",
        } satisfies IPolEcoBoardCommentEdit.ICreate,
      });
    }
  );
}

