  typia.assert(adminLoginRes);

  // 3. Register a member to author content
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberRegRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRegRes);

  // 4. Member logs in
  const memberLoginRes = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginRes);

  // 5. Member creates a post to be edited
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(), // should produce a reasonable string
      body: RandomGenerator.content()(200, 400), // properly invoked to return a string
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Member creates a comment under that post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()(30, 60),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 7. Switch back to admin privilege context
  const adminReloginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminReloginRes);

  // 8. Admin manually creates a comment edit record for the member's comment
  const editBody = `[Edited by admin] ` + RandomGenerator.content()(40, 80);
  const editReason = "Compliance correction test.";
  const edit = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.create(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      edit_body: editBody,
      edit_reason: editReason,
    } satisfies IPolEcoBoardCommentEdit.ICreate,
  });
  typia.assert(edit);
  TestValidator.equals("Edit linkage to comment")(edit.comment_id)(comment.id);
  TestValidator.equals("Edit body content matches")(edit.edit_body)(editBody);
  TestValidator.equals("Edit reason matches")(edit.edit_reason)(editReason);
  TestValidator.predicate("Edit timestamp exists")(!!edit.created_at);

  // 9. Validate error occurs for non-existent comment ID
  TestValidator.error("Should fail for nonexistent comment")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.comments.commentEdits.create(connection, {
        postId: post.id,
        commentId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          edit_body: "[Nonexistent comment edit]",
        } satisfies IPolEcoBoardCommentEdit.ICreate,
      });
    }
  );
}

