import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IPageIPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate enforcement of admin-only access control for notification preference search endpoint.
 *
 * Business context: Only admin users should be able to access the /polEcoBoard/admin/notificationPreferences search endpoint. Regular members and unauthenticated users must not be able to read bulk notification preferences for security, privacy, and regulatory reasons.
 *
 * Test covers two permission denial pathways:
 * 1. Authenticated regular member attempts to use admin search endpoint – must be denied (permission error).
 * 2. Attempt search with no authentication at all – must also be denied.
 *
 * This ensures boundary enforcement and no privilege escalation.
 *
 * Step-by-step process:
 * 1. Register a regular member.
 * 2. Login as the member (obtain member's jwt token in connection).
 * 3. Attempt to call notification preferences search endpoint with valid member authentication – expect error.
 * 4. Remove authentication (simulate unauthenticated access).
 * 5. Attempt to call notification preferences search endpoint without any Authorization – expect error.
 */
export async function test_api_notification_preferences_admin_search_permission_denied(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const registerResult = await api.functional.auth.member.register.post(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(registerResult);

  // 2. Login as the member
  const loginResult = await api.functional.auth.member.login.post(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(loginResult);

  // 3. Attempt admin notification preferences search as member (should be denied)
  await TestValidator.error("member cannot access admin notification preferences")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationPreferences.patch(connection, {
        body: {}, // empty search (valid type)
      });
    }
  );

  // 4. Remove authentication, simulate no authentication
  const unauthenticatedConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthenticatedConnection.headers.Authorization;

  // 5. Attempt admin notification preferences search with no credentials (should be denied)
  await TestValidator.error("unauthenticated user cannot access admin notification preferences")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationPreferences.patch(unauthenticatedConnection, {
        body: {},
      });
    }
  );
}

