import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPageIPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin search for post attachments is unauthorized without a valid session.
 *
 * This test ensures that PATCH /polEcoBoard/admin/posts/{postId}/attachments
 * (admin search/filter on post attachments) is inaccessible unless called with
 * a valid/authorized admin JWT. The test covers two attack/abuse vectors:
 *
 * 1. Attempt using NO Authorization header at all (completely unauthenticated).
 * 2. Attempt using an INVALID/forged Authorization header (e.g. "Bearer invalidtoken").
 *
 * For both, the endpoint must return an appropriate HTTP authorization error (typically 401/403),
 * must NOT leak any confidential file/attachment metadata (e.g., URIs, file names, MIME types),
 * and must uphold platform compliance requirements by ensuring information disclosure is prevented.
 *
 * The setup builds a fully valid resource chain: admin registration, board/category, member, post, and attachment
 * so the tested endpoint is called in a realistic state. Note: There is no endpoint for direct audit trail validation,
 * so this test ensures only business-side security: access control and no data leak in error output.
 *
 * Steps:
 * 1. Register and login as admin (for setup purposes).
 * 2. Create board category and board.
 * 3. Register and login a member; member creates a post and uploads an attachment.
 * 4. Try to search attachments as admin with:
 *    a) No Authorization header
 *    b) Invalid Authorization header
 * 5. Assert both attempts are denied (error thrown), and no attachment data is disclosed in error message.
 */
export async function test_api_post_attachment_search_by_admin_unauthorized(connection: api.IConnection) {
  // 1. Register and login as admin (use only for setup; NOT for unauthorized attempts)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Create necessary board category and board
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1).slice(0, 45),
      description: RandomGenerator.paragraph()(1).slice(0, 80),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(12).slice(0, 30),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(1).slice(0, 80),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Register and login a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  // Register (set password_hash = memberPassword as a test simplification)
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.alphabets(10),
      consent_status: "v1-consented",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  // Login to setup session for member
