import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate forbidden access to post edit history for non-authors.
 *
 * Ensures that a regular member (not the post's author and with no admin/moderator privileges)
 * receives a permission denied error when attempting to access the edit detail of another
 * member's post via the protected endpoint. This confirms backend enforcement of RBAC.
 *
 * Business scenario walkthrough:
 * 1. Register a member to act as the post author (authorMember).
 * 2. Author logs in successfully.
 * 3. Author creates a new board post in a random category.
 * 4. Author submits an edit to their own post.
 * 5. Register a second member (nonAuthorMember).
 * 6. Second member logs in successfully (no moderator/admin privileges).
 * 7. Second member attempts to fetch the post edit detail using the protected endpoint.
 * 8. Assert that the request is rejected (403 forbidden) due to lacking permissions.
 */
export async function test_api_post_edit_detail_member_permission_denied_non_author(
  connection: api.IConnection,
) {
  // 1. Register first member (author)
  const authorEmail = typia.random<string & tags.Format<"email">>();
  const authorPassword = "testPassword123!";
  const author: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: authorEmail,
      password_hash: authorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1-consent",
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(author);

  // 2. Login as author
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: authorEmail,
      password: authorPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Author creates a post
  const post: IPolEcoBoardPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()(1000),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Author creates a post edit
  const postEdit: IPolEcoBoardPostEdit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: RandomGenerator.content()(900),
      edit_reason: "Initial post correction.",
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(postEdit);

  // 5. Register second member (not the author, not privileged)
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Password = "testPassword456!";
  const member2: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member2Email,
      password_hash: member2Password,
      display_name: RandomGenerator.name(),
      consent_status: "v1-consent",
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member2);

  // 6. Login as second member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 7. Attempt forbidden post edit detail request as non-author (should fail with 403)
  await TestValidator.error("non-author cannot access another member's post edit detail")(
    async () => {
      await api.functional.polEcoBoard.member.posts.postEdits.atEdit(connection, {
        postId: post.id,
        postEditId: postEdit.id,
      });
    },
  );
}

