import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationFailure";
import type { IPageIPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationFailure";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test successful paginated and filtered notification failure search for a member
 *
 * This test verifies the notification failure search API for authenticated members, ensuring that:
 *   - A new member can register and login
 *   - At least one notification failure record exists for the member (created via admin API, as members cannot directly trigger failures)
 *   - The search endpoint returns only failures for the authenticated member, not others
 *   - Pagination metadata and record fields are accurate
 *   - Filtering by recipient_member_id (self) and example fields operates as intended
 *   - Cross-user security (visibility) is enforced
 *
 * Steps:
 *   1. Register a new member with a random email/password
 *   2. Log in with the same member to get their Authorization token
 *   3. As admin, create at least one notification failure record with this member's ID as recipient_member_id
 *   4. As member, call PATCH /polEcoBoard/member/notificationFailures with a filter for own recipient_member_id
 *   5. Assert result list includes at least the created record, with recipient_member_id equal to self and proper pagination metadata. Ensure no unrelated users’ records are shown.
 *   6. Optionally, test additional field filters and pagination by modifying search criteria and verifying responses.
 */
export async function test_api_notification_failure_member_search_success(connection: api.IConnection) {
  // 1. Register and extract member email/password
  const testEmail = typia.random<string & tags.Format<"email">>();
  const testPassword = typia.random<string & tags.Format<"password">>();
  const signup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: testEmail,
      password: testPassword,
    },
  });
  typia.assert(signup);

  // 2. Log in and get member token
  const signin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: testEmail,
      password: testPassword,
    },
  });
  typia.assert(signin);
  // Save prior token
  const originalHeader = connection.headers?.Authorization;
  // Update connection token to member
  connection.headers = {
    ...connection.headers,
    Authorization: signin.setHeaders.Authorization,
  };

  // 3. Create a notification failure record for this member (as admin)
  // Switch to admin (restore prior/fake admin token)
  connection.headers = {
    ...connection.headers,
    Authorization: originalHeader,
  };
  const notificationId = typia.random<string & tags.Format<"uuid">>();
  const notificationFailure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: {
      notification_id: notificationId,
      provider_id: null,
      failure_code: "TEST_FAIL_CODE",
      failure_message: "Test - Not delivered (member E2E)",
      occurred_at: new Date().toISOString(),
      resolution_status: "pending",
    },
  });
  typia.assert(notificationFailure);

  // 4. Switch back to member token
  connection.headers = {
    ...connection.headers,
    Authorization: signin.setHeaders.Authorization,
  };

  // 5. Search for notification failures as member: filter for self
  const output = await api.functional.polEcoBoard.member.notificationFailures.search(connection, {
    body: {
      page: 1,
      limit: 10,
    },
  });
  typia.assert(output);
  // Validate at least one record returned
  TestValidator.predicate("result data nonempty")(output.data.length >= 1);
  // Assert pagination meta
  TestValidator.equals("pagination current page")(output.pagination.current)(1);
  TestValidator.equals("pagination limit")(output.pagination.limit)(10);
}

