import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can successfully create a post edit history entry for a specific post.
 *
 * Business context:
 * - Demonstrates that moderator audit trails are being maintained for post edits
 * - Ensures compliance and rollback features by tracking all edit snapshots
 *
 * Step-by-step process:
 * 1. Register a moderator with a unique email/password/etc.
 * 2. Moderator logs in to get authentication session
 * 3. Register a member who will author the original post
 * 4. Member logs in to get authentication session
 * 5. Member creates a post (category chosen randomly)
 * 6. Moderator logs in again (switches session)
 * 7. Moderator creates a post edit snapshot (edit_body/edit_reason must differ from original post)
 * 8. Check that audit trail is correct: post, actor, content, and rationale are as provided; timestamp is valid RFC3339
 */
export async function test_api_post_edit_create_by_moderator_authorized_success(connection: api.IConnection) {
  // 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1-consent";
  const moderatorRegister = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegister);
  TestValidator.equals("moderator email matches")(moderatorRegister.email)(moderatorEmail);
  TestValidator.equals("moderator display_name matches")(moderatorRegister.display_name)(moderatorDisplayName);
  const moderatorId = moderatorRegister.moderatorId;

  // 2. Moderator logs in
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
