import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IPageIPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardGuest";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that unauthorized and non-admin users cannot access guest search endpoint (/polEcoBoard/admin/guests).
 *
 * This test verifies strict access control for the guest search feature. Unauthenticated requests and requests using only a basic token (non-admin) must be denied, ensuring personally identifying guest data stays protected.
 *
 * Steps:
 * 1. Attempt to search for guests without any authentication. Expect an authorization error.
 * 2. Register a new admin user.
 * 3. Login as the admin user to acquire a valid admin JWT (for positive control, not used in negative test).
 * 4. Manually remove Authorization header (simulate guest/no-token access) and call again.
 * 5. (If feasible) Simulate a non-admin token (not technically possible with only admin endpoints; skip if only admin role is supported).
 * 6. Confirm that the endpoint does not return guest data in any unauthorized scenario.
 * 7. (Optional) With the valid admin JWT, confirm that search does succeed (positive contrast, not focus of this test).
 */
export async function test_api_guest_session_search_unauthorized(connection: api.IConnection) {
  // 1. Attempt search without any authentication (bare connection)
  TestValidator.error("Guest access should be denied")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.search(connection, {
        body: typia.random<IPolEcoBoardGuest.IRequest>()
      });
    }
  );

  // 2. Register a new admin user for control
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword }
      satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 3. Login as the new admin
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(loginResp);
  const adminToken = loginResp.setHeaders.Authorization;

  // 4. Try search with explicit removal of Authorization (simulate logout or guest)
  const guestConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined
    }
  };
  TestValidator.error("Explicitly no-Authorization should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.search(guestConnection, {
        body: typia.random<IPolEcoBoardGuest.IRequest>()
      });
    }
  );

  // 5. (Non-admin JWT negative test skipped, as only admin auth endpoints exist.)

  // 6. Positive control: confirm access works with valid admin token
  const adminConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: adminToken
    }
  };
  const success = await api.functional.polEcoBoard.admin.guests.search(adminConnection, {
    body: typia.random<IPolEcoBoardGuest.IRequest>()
  });
  typia.assert(success);
}

