import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPageIPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test advanced moderation action search by admin, including admin-only permissions and filter logic.
 *
 * Business context: Only admins can access the moderation actions audit/search endpoint. This E2E test validates correct admin authentication, filter usage, response structure, and proper error handling for unauthorized access.
 *
 * Step-by-step:
 * 1. Register a new admin account via POST /auth/admin/register.
 * 2. Log in as the new admin via POST /auth/admin/login to refresh the authorization token.
 * 3. Search moderation actions as admin with filters (e.g., action_type, page, limit):
 *    - PATCH /polEcoBoard/admin/moderationActions
 *    - Validate paginated, filter-matching response structure
 * 4. Attempt to search moderation actions as unauthenticated (non-admin):
 *    - API call must be rejected (forbidden or unauthorized error)
 */
export async function test_api_moderation_action_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      },
    },
  );
  typia.assert(signUpResponse);

  // 2. Login as the new admin (refreshes Authorization)
  const signInResponse = await api.functional.auth.admin.login.signIn(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      },
    },
  );
  typia.assert(signInResponse);

  // 3. Compose search filters (admin-only)
  const searchFilters = {
    action_type: "warn",
    // Optionally test for other filters such as target_type, status, etc.
    page: 1,
    limit: 10,
  } satisfies IPolEcoBoardModerationAction.IRequest;

  // 4. Search moderation actions as admin
  const pageResult = await api.functional.polEcoBoard.admin.moderationActions.search(
    connection,
    {
      body: searchFilters,
    },
  );
  typia.assert(pageResult);
  // Validate pagination structure
  TestValidator.predicate("pagination present")(typeof pageResult.pagination === "object");
  TestValidator.predicate("pagination fields exist")(
    typeof pageResult.pagination.current === "number" &&
      typeof pageResult.pagination.limit === "number" &&
      typeof pageResult.pagination.records === "number" &&
      typeof pageResult.pagination.pages === "number"
  );
  // Optionally confirm that result records, if present, match the filter
  for (const action of pageResult.data) {
    if (searchFilters.action_type)
      TestValidator.equals("action_type matches filter")(action.action_type)(searchFilters.action_type);
    // For more exhaustive testing, you could check other filters (target_type, status) if set
  }

  // 5. Attempt access as non-admin (simulate unauthenticated)
  const unauthConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };
  await TestValidator.error("non-admin access is forbidden")(() =>
    api.functional.polEcoBoard.admin.moderationActions.search(unauthConnection, {
      body: searchFilters,
    })
  );
}

