import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test moderator-originated report submission on a post in polEcoBoard.
 *
 * This scenario validates that moderators can report posts, that moderator privilege-based access is enforced,
 * and that normal business rules (e.g., duplicate report prevention on the same post) are correctly implemented for the moderator role.
 *
 * Steps:
 * 1. Register a moderator account and login to establish moderator authentication context.
 * 2. Register a member account and login as that member (to create a post as a normal user).
 * 3. Submit a new post as the member to obtain a valid post for reporting.
 * 4. Switch to the moderator account (login if necessary).
 * 5. Submit a report against the member's post as the moderator, specifying a valid reason code and description.
 * 6. Validate that a report is created and linked to correct moderator (authentication), with correct data.
 * 7. Attempt to submit a duplicate report from the same moderator for the same post, and verify business rules are enforced
 *    (e.g., error is thrown for duplicate, or business response prevents multiple reports by same moderator on same post).
 */
export async function test_api_moderator_post_report_submission(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = typia.random<string & tags.Format<"password">>();
  const displayName: string = RandomGenerator.name();
  const consentStatus: string = "policy_v1";
  const modRegRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: displayName,
      consent_status: consentStatus,
    },
  });
  typia.assert(modRegRes);
  // Moderation JWT will be set in headers

  // 2. Register and login member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = typia.random<string & tags.Format<"password">>();

  const memRegRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memRegRes);

  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 3. Create a polEcoBoard post as member
  const postCreateInput = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(10),
    body: RandomGenerator.content()(50),
    tag_ids: null,
    attachments: null,
  } satisfies IPolEcoBoardPost.ICreate;
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postCreateInput,
  });
  typia.assert(post);
  const postId = post.id;

  // 4. Switch to moderator (login)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });

  // 5. Submit report as moderator
  const reportReason = "abuse";
  const reportDescription = "Moderator reporting content as abusive";
  const reportInput = {
    reason_code: reportReason,
    reason_description: reportDescription,
    post_id: postId,
    comment_id: null,
  } satisfies IPolEcoBoardReport.ICreate;
  const report = await api.functional.polEcoBoard.moderator.posts.reports.create(connection, {
    postId: postId,
    body: reportInput,
  });
  typia.assert(report);
  TestValidator.equals("reported post id")(report.post_id)(postId);
  TestValidator.equals("reason code")(report.reason_code)(reportReason);
  TestValidator.equals("reason description")(report.reason_description)(reportDescription);

  // 6. Attempt to submit duplicate moderation report; ensure business rule (single report per moderator per post) enforced
  await TestValidator.error("should reject duplicate moderator report")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.reports.create(connection, {
        postId: postId,
        body: reportInput,
      });
    }
  );
}

