import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate session invalidation upon admin logout.
 *
 * This test ensures that after an admin user logs out, their current authentication session is fully revoked and their JWT token is no longer usable for accessing protected admin endpoints.
 *
 * Business Context:
 * Administrators must be able to securely log out. Logging out needs to reliably invalidate the session in the backend, so the same access token (JWT) cannot be used to access any protected endpoints. This is vital for session security, especially in shared or public environments, and for meeting compliance requirements.
 *
 * Steps:
 * 1. Register a new admin account with a unique email and a valid password.
 * 2. Log in as this admin to obtain a valid JWT (session token).
 * 3. Set the Authorization header for follow-up requests using the returned JWT.
 * 4. Call logout as the authenticated admin (JWT in Authorization header).
 * 5. Attempt to access a protected endpoint (like /auth/admin/logout again) using the same JWT.
 * 6. Validate that this access fails (e.g., returns 401 Unauthorized), confirming session invalidation.
 */
export async function test_api_admin_logout_session_invalidation(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Log in as the new admin and extract token
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);
  const token = signInRes.setHeaders.Authorization;
  connection.headers.Authorization = token;

  // 3. Perform logout (invalidate session)
  const signOutRes = await api.functional.auth.admin.logout.signOut(connection);
  typia.assert(signOutRes);

  // 4. Try to access a protected endpoint with the same (now-revoked) token. This must fail.
  connection.headers.Authorization = token;
  await TestValidator.error("access denied after logout")(async () => {
    await api.functional.auth.admin.logout.signOut(connection);
  });
}

