import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate error handling when fetching a report by postId and reportId as admin, covering not-found and unauthorized edge cases.
 *
 * This test ensures the admin report retrieval API robustly handles both 1) requests for non-existent resources, and 2) unauthorized access attempts as required by the business error flow. The following scenarios are covered:
 *
 * 1. Admin registration and login, establishing a valid admin session for the test.
 * 2. Attempting to fetch a report with random UUIDs for both postId and reportId (which are extremely unlikely to correspond to actual records), and confirming an error is thrown (i.e., not found or similar).
 * 3. Simulating an unauthenticated (non-admin) request by removing the Authorization token from the connection headers, and verifying the endpoint correctly blocks access (error is thrown).
 *
 * Notes:
 * - It is not feasible to trigger a malformed-UUID runtime error because the TypeScript signature enforces UUID format at compile-time (i.e., format errors are prevented statically, not caught at runtime).
 * - Error validation uses TestValidator.error, only confirming that an error is thrown, not inspecting the error details in depth.
 */
export async function test_api_post_report_retrieve_not_found_or_unauthorized(connection: api.IConnection) {
  // 1. Register a new admin for privileged actions
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin to establish authentication/session
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Try to fetch a report with non-existent postId and reportId (random UUIDs)
  await TestValidator.error("non-existent post/report should error")(() =>
    api.functional.polEcoBoard.admin.posts.reports.at(connection, {
      postId: typia.random<string & tags.Format<"uuid">>(),
      reportId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 4. Try to fetch a report as an unauthenticated user (simulate by removing Authorization)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthorized admin access should fail")(() =>
    api.functional.polEcoBoard.admin.posts.reports.at(unauthConnection, {
      postId: typia.random<string & tags.Format<"uuid">>(),
      reportId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 5. Skipped: malformed UUID scenario, as invalid UUID will not compile at the callsite.
}

