import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that only users with admin privileges can delete a vote from a post on the polEcoBoard.
 *
 * This scenario ensures that attempts to delete a vote by an unauthenticated user or by a regular member (who lacks admin rights) are properly rejected by the API, enforcing role-based access control for the admin vote deletion endpoint.
 *
 * Step-by-step process:
 * 1. Create a board category (admin)
 * 2. Create a board in the category (admin)
 * 3. Register a member (non-admin user)
 * 4. Log in as the member
 * 5. Member creates a post
 * 6. Member votes on the post
 * 7. Attempt to delete the vote with no authentication (should fail)
 * 8. Attempt to delete the vote as the member (should fail)
 *
 * Results: Both deletion attempts should fail, showing permission is granted only to admins on this API.
 */
export async function test_api_admin_post_vote_delete_unauthorized_access(connection: api.IConnection) {
  // 1. Create a board category (admin)
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 2. Create a board in the category (admin)
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphaNumeric(12),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Register a member
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email,
      password_hash: password, // For test, plain password is used as hash
      display_name: RandomGenerator.name(),
      profile_image_uri: null,
      consent_status: "v1",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Member login
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  // Now connection is authenticated as the member

  // 5. Member creates a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(1),
      tag_ids: [],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Member votes on the post
  const vote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 7. Attempt deletion without authentication (clear Authorization header)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("unauthenticated cannot delete vote")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.eraseByPostidAndVoteid(unauthConnection, {
      postId: post.id,
      voteId: vote.id,
    });
  });

  // 8. Attempt deletion as member (authenticated but not admin)
  await TestValidator.error("member cannot delete vote via admin endpoint")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.eraseByPostidAndVoteid(connection, {
      postId: post.id,
      voteId: vote.id,
    });
  });
}

