import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardServiceSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardServiceSettings";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an authenticated admin can successfully retrieve all global platform-level settings.
 *
 * Business context:
 * Admins need to view the entire configuration state of the platform, including registration policy, content constraints, and audit timelines.
 *
 * Step-by-step process:
 * 1. Register a new admin (platform must allow admin registration via unique business email and valid password)
 * 2. Log in as the admin to receive auth credentials
 * 3. Call GET /polEcoBoard/admin/serviceSettings as this admin
 * 4. Assert that the returned configuration object contains all required fields: id, registration_enabled, max_post_length, max_comment_length, default_board_visibility, data_retention_days, created_at, updated_at
 * 5. Assert that returned field types and formats are correct and sensitive admin-level info is present
 */
export async function test_api_service_settings_singleton_get_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Log in as the admin using provided credentials (ensures correct session and header tokens)
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 3. Call GET /polEcoBoard/admin/serviceSettings as authenticated admin
  const settings = await api.functional.polEcoBoard.admin.serviceSettings.at(connection);
  typia.assert(settings);

  // 4. Validate all expected configuration keys are present and field types/formats are correct
  TestValidator.predicate("platform config id is uuid")(
    typeof settings.id === "string" && settings.id.match(/[0-9a-fA-F-]{36}/)
  );
  TestValidator.predicate("registration_enabled is boolean")(typeof settings.registration_enabled === "boolean");
  TestValidator.predicate("max_post_length is int32")(
    typeof settings.max_post_length === "number" && Number.isInteger(settings.max_post_length)
  );
  TestValidator.predicate("max_comment_length is int32")(
    typeof settings.max_comment_length === "number" && Number.isInteger(settings.max_comment_length)
  );
  TestValidator.predicate("default_board_visibility is boolean")(typeof settings.default_board_visibility === "boolean");
  TestValidator.predicate("data_retention_days is int32")(
    typeof settings.data_retention_days === "number" && Number.isInteger(settings.data_retention_days)
  );
  TestValidator.predicate("created_at is ISO string")(
    typeof settings.created_at === "string" && !Number.isNaN(Date.parse(settings.created_at))
  );
  TestValidator.predicate("updated_at is ISO string")(
    typeof settings.updated_at === "string" && !Number.isNaN(Date.parse(settings.updated_at))
  );
}

