import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator ability to soft delete (not hard delete) any post for moderation reasons.
 *
 * This test simulates a typical moderation workflow:
 * 1. Register a new member with a valid email and password
 * 2. Login as that member to obtain an authorization token
 * 3. The member creates a new post in a valid category via the member post API
 * 4. Register a moderator account (capturing credentials and consent status)
 * 5. Login as the moderator to gain moderator privileges
 * 6. Moderator soft deletes (deactivates) the member's post by postId via the moderator delete endpoint
 * 7. There is no direct API to re-fetch or verify the deleted state in this SDK, but the API contract specifies soft delete is realized by deleted_at being set non-null, and the post is hidden from regular feeds. (Assume audit-confirmation/manual DB check by business process for actual cases)
 *
 * Preconditions:
 * - Both member and moderator registration APIs are functional
 * - The domain has valid category UUIDs available (randomly generated for sake of test)
 *
 * Steps:
 * 1. Register member
 * 2. Login as member
 * 3. Create a post
 * 4. Register moderator
 * 5. Login as moderator
 * 6. Soft delete the post by postId
 * 7. (Cannot verify via API directly that deleted_at is set due to SDK limitation; typically checked via admin review/logs outside this flow)
 */
export async function test_api_post_soft_delete_by_moderator_success(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberRegisterResult = await api.functional.auth.member.register.post(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberRegisterResult);

  // 2. Login as the member
  const memberLoginResult = await api.functional.auth.member.login.post(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberLoginResult);

  // 3. Create a post as the member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postCreateRequest = {
    category_id: categoryId,
    title: "E2E Test Post - Can be deleted by moderation.",
    body: "This is an E2E test post body. Created for moderation delete test.",
    tag_ids: [],
