import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can create comments on any post, regardless of its board status (flagged, locked, or archived), where business rules permit.
 * Also ensures that each created comment is visible for audit and moderation (with audit metadata present), and business rule enforcement (e.g., deletion) is effective for admin as well.
 *
 * Business context: Admins may comment on posts for moderation, compliance, or special notices, even on restricted boards. This test confirms that:
 * - Admin privilege allows comment creation on locked and archived boards when business rule permits.
 * - Comment audit fields and key properties (post association, author, timestamps, body, and flagged status) are correctly set.
 * - Attempts to comment on deleted/non-existent posts are blocked, with appropriate error signaling.
 *
 * Test steps:
 * 1. Register a new admin user
 * 2. Log in as the admin (JWT is set for privileged API)
 * 3. Create a new post (as member)
 * 4. Change the board status of the post to 'locked'.
 * 5. As admin, create a comment on the locked post. Assert all key response properties.
 * 6. Change the board status to 'archived' and repeat: comment as admin, asserting as above.
 * 7. (Edge) Simulate a deleted post by using a random UUID, and verify that attempting to comment as admin results in an error.
 *
 * Detailed assertions:
 * - After each comment, confirm: post association, body accuracy, flag presence, timestamp fields.
 * - For the deleted post, ensure the error is thrown (TestValidator.error) and type safety is preserved.
 */
export async function test_api_admin_create_comment_on_any_post_with_audit_trail(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(15);
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResp);

  // 2. Log in as the admin
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);

  // 3. Create a new post as member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(1, true).substring(0, 32),
      body: RandomGenerator.content()(2, true).slice(0, 120),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Set board status to 'locked' for the post's board
  const lockedStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: post.category_id,
      actor_admin_id: null,
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: "Locked for admin comment E2E test",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(lockedStatus);

  // 5. As admin, create a comment on the locked post
  const commentText = "Admin comment on locked post.";
  const comment = await api.functional.polEcoBoard.admin.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: commentText,
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);
  TestValidator.equals("post association")(comment.post_id)(post.id);
  TestValidator.equals("body matches")(comment.body)(commentText);
  TestValidator.equals("flagged present")(typeof comment.flagged === "boolean")(true);
  TestValidator.predicate("created_at and updated_at present")(!!comment.created_at && !!comment.updated_at);

  // 6. Set board status to 'archived' and repeat
  const archivedStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: post.category_id,
      actor_admin_id: null,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "Archived for admin comment E2E test",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(archivedStatus);
  const archivedCommentBody = "Admin comment on archived post.";
  const archivedComment = await api.functional.polEcoBoard.admin.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: archivedCommentBody,
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(archivedComment);
  TestValidator.equals("archived post association")(archivedComment.post_id)(post.id);
  TestValidator.equals("archived body matches")(archivedComment.body)(archivedCommentBody);

  // 7. Simulate deleted/non-existent post and assert error is signaled
  const deletedPostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("admin cannot comment on deleted post")(async () => {
    await api.functional.polEcoBoard.admin.posts.comments.create(connection, {
      postId: deletedPostId,
      body: {
        body: "Should fail: post deleted",
      } satisfies IPolEcoBoardComment.ICreate,
    });
  });
}

