import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can create comments on any post, regardless of board status (normal, locked, archived), as business rules permit. Also verifies that auditing fields are present and the comment is visible for moderation.
 * Steps:
 * 1. Register and log in as a new admin
 * 2. Create a post in a random category
 * 3. Change the category's board status to locked and verify an admin can comment
 * 4. Change the category's board status to archived and verify an admin can comment
 * 5. Attempt to comment as admin on a non-existent (deleted) post and expect an error
 */
export async function test_api_admin_create_comment_on_any_post_with_audit_trail(connection: api.IConnection) {
  // 1. Register and login admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(15);
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResp);
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);

  // 2. Create post as member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(1, true).substring(0, 32),
      body: RandomGenerator.content()(2, true).substring(0, 120),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Lock board and comment as admin
  await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: post.category_id,
      actor_admin_id: null,
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: "locked for E2E",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  const commentBodyLocked = "Admin comment on locked post.";
  const commentLocked = await api.functional.polEcoBoard.admin.posts.comments.create(connection, {
    postId: post.id,
    body: { body: commentBodyLocked } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentLocked);
  TestValidator.equals("post association")(commentLocked.post_id)(post.id);
  TestValidator.equals("body matches")(commentLocked.body)(commentBodyLocked);
  TestValidator.predicate("flagged field exists and boolean")(
    typeof commentLocked.flagged === "boolean"
  );
  TestValidator.predicate("timestamps set")(
    Boolean(commentLocked.created_at && commentLocked.updated_at)
  );

  // 4. Archive board and comment as admin
  await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: post.category_id,
      actor_admin_id: null,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "archived for E2E",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  const commentBodyArchived = "Admin comment on archived post.";
  const commentArchived = await api.functional.polEcoBoard.admin.posts.comments.create(connection, {
    postId: post.id,
    body: { body: commentBodyArchived } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentArchived);
  TestValidator.equals("archived post association")(commentArchived.post_id)(post.id);
  TestValidator.equals("archived body matches")(commentArchived.body)(commentBodyArchived);
  TestValidator.predicate("archived flagged boolean")(
    typeof commentArchived.flagged === "boolean"
  );

  // 5. Attempt to comment on a non-existent (deleted) post, expect error
  const deletedPostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("admin cannot comment on deleted post")(async () => {
    await api.functional.polEcoBoard.admin.posts.comments.create(connection, {
      postId: deletedPostId,
      body: { body: "Should fail: post deleted" } satisfies IPolEcoBoardComment.ICreate,
    });
  });
}

