import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdmin";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that access to admin details is forbidden for regular (non-admin) members.
 *
 * This test ensures that a regular member, once logged in, cannot access admin profile details via the /polEcoBoard/admin/admins/{adminId} endpoint. This enforces strict privilege boundaries and is essential for compliance and data security. Attempted unauthorized access must result in a forbidden error, and (in a production system) should be audited for compliance.
 *
 * Steps:
 * 1. Register a new admin account to create an adminId for test targeting
 * 2. Register a regular (non-admin) member account
 * 3. Log in as the member and set their session credentials on the connection
 * 4. As the member, attempt to retrieve the admin's profile via the admin detail API
 * 5. Confirm that the system returns a forbidden error (HTTP 403 or equivalent)
 * 6. (Audit logging validation is noted but not runtime-checked in this test)
 */
export async function test_api_admin_detail_forbidden_for_member(
  connection: api.IConnection,
) {
  // 1. Register a new admin account (for adminId target)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const adminResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminResp);

  // Retrieve adminId for the admin we just registered.
  // Since the API does not return adminId, we attempt to fetch admin's profile using the current admin session.
  // This works because the registration sets the JWT token for the just-created admin.
  const adminProfile = await api.functional.polEcoBoard.admin.admins.at(connection, {
    adminId: await extractAdminIdFromTokenOrSession(connection),
  });
  typia.assert(adminProfile);
  const adminId = adminProfile.id;

  // 2. Register a new regular member account
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = RandomGenerator.alphaNumeric(12);
  const memberDisplayName: string = RandomGenerator.name();
  const memberConsentStatus: string = "2024-consent";

  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: memberConsentStatus,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 3. Log in as the member (switch session context)
  const memberLoginResp = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginResp);

