import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardEscalation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardEscalation";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin can retrieve escalation detail by escalationId and business, relational, and audit fields are all included.
 *
 * This E2E test ensures the correctness, security, and robustness of the escalation detail API for polEcoBoard administrator workflows.
 *
 * Steps:
 * 1. Register and login as admin A to obtain Authorization context.
 * 2. Create an escalation event as admin A (assigning random moderator/admin for escalation structure).
 * 3. Retrieve the escalation by id as admin A, verify all fields and audit consistency.
 * 4. Attempt to retrieve a non-existent escalation id, expect a not-found error.
 * 5. Register and login as a second admin (admin B).
 * 6. Attempt to retrieve admin A's escalation as admin B, expect rejection or not-found as per permissions.
 * 7. Attempt access with no token and with an invalid/malformed token, verify authorization rejection.
 *
 * Edge cases related to deletion/closure cannot be tested as no such API exists in the materials.
 */
export async function test_api_escalation_detail_access_by_id_admin(connection: api.IConnection) {
  // 1. Register admin A
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminAEmail,
      password: adminAPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin A
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminAEmail,
      password: adminAPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  // connection.headers.Authorization is now set

  // 3. Create an escalation as admin A
  const escalationInput: IPolEcoBoardEscalation.ICreate = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    escalator_id: typia.random<string & tags.Format<"uuid">>(),
    recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
    reason: RandomGenerator.paragraph()(200),
    status: "pending",
  };
  const created = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: escalationInput,
  });
