import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";

/**
 * Validate the successful creation or retrieval of a guest session for anonymous users on polEcoBoard.
 *
 * This test covers the flow where an anonymous, non-authenticated visitor starts a guest session by providing their IP address, consent status, and, optionally, a device/browser fingerprint. The core business logic ensures a guest session is recorded for IP and consent tracking (with optional device ID), no authentication is required, and the result is always a session object representing this visit/consent event.
 *
 * Steps:
 * 1. Prepare random input for IPolEcoBoardGuest.ICreate: valid IPv4/IPv6 address, consent status string/code, optionally a device_fingerprint string/null
 * 2. Call api.functional.auth.guest.session.startGuestSession to create or refresh the guest session
 * 3. Validate that the returned IPolEcoBoardGuest object:
 *    - includes a correctly persisted ip_address, consent_status, and the device_fingerprint (if sent)
 *    - has valid id (uuid), and correct created_at/updated_at timestamps
 *    - can be created without device_fingerprint (optional property)
 * 4. Ensure that no authentication is required (endpoint can be called with unauthenticated connection)
 * 5. (Edge) Call again with same ip_address/consent_status/device_fingerprint to verify the guest session is idempotent (id and info match, created_at may be same or updated)
 * 6. Test with and without device_fingerprint to validate proper optional handling
 */
export async function test_api_guest_session_creation_success(
  connection: api.IConnection,
) {
  // 1. Prepare input for guest session creation with device_fingerprint.
  const ipAddress: string = RandomGenerator.ip();
  const consent: string = RandomGenerator.alphabets(12);
  const deviceFingerprint: string = RandomGenerator.alphaNumeric(16);

  // 2. Start guest session with device_fingerprint (all fields present).
  const guestWithFingerprint = await api.functional.auth.guest.session.startGuestSession(connection, {
    body: {
      ip_address: ipAddress,
      consent_status: consent,
      device_fingerprint: deviceFingerprint,
    } satisfies IPolEcoBoardGuest.ICreate,
  });
  typia.assert(guestWithFingerprint);
  // Check field persistence
  TestValidator.equals("ip_address")(guestWithFingerprint.ip_address)(ipAddress);
  TestValidator.equals("consent_status")(guestWithFingerprint.consent_status)(consent);
  TestValidator.equals("device_fingerprint")(guestWithFingerprint.device_fingerprint)(deviceFingerprint);
  // Validate ID and timestamps
  TestValidator.predicate("id is uuid")(guestWithFingerprint.id.length > 0);
  TestValidator.predicate("created_at ISO")(!!Date.parse(guestWithFingerprint.created_at));
  TestValidator.predicate("updated_at ISO")(!!Date.parse(guestWithFingerprint.updated_at));

  // 3. Repeat: call again to check idempotency (should match).
  const guestDuplicate = await api.functional.auth.guest.session.startGuestSession(connection, {
    body: {
      ip_address: ipAddress,
      consent_status: consent,
      device_fingerprint: deviceFingerprint,
    },
  });
  typia.assert(guestDuplicate);
  TestValidator.equals("idempotent id")(guestDuplicate.id)(guestWithFingerprint.id);
  TestValidator.equals("ip_address repeat")(guestDuplicate.ip_address)(ipAddress);
  TestValidator.equals("consent_status repeat")(guestDuplicate.consent_status)(consent);
  TestValidator.equals("device_fingerprint repeat")(guestDuplicate.device_fingerprint)(deviceFingerprint);

  // 4. Start guest session WITHOUT device_fingerprint (optional omitted case)
  const guestNoFingerprint = await api.functional.auth.guest.session.startGuestSession(connection, {
    body: {
      ip_address: ipAddress,
      consent_status: consent,
    },
  });
  typia.assert(guestNoFingerprint);
  TestValidator.equals("ip_address no fingerprint")(guestNoFingerprint.ip_address)(ipAddress);
  TestValidator.equals("consent_status no fingerprint")(guestNoFingerprint.consent_status)(consent);
  // device_fingerprint omitted/null as per API contract
  TestValidator.equals("device_fingerprint defaults null")(guestNoFingerprint.device_fingerprint)(null);
  // Also validate id, created_at/updated_at (should be valid objects)
  TestValidator.predicate("id present")(typeof guestNoFingerprint.id === "string" && guestNoFingerprint.id.length > 0);
  TestValidator.predicate("created_at present")(!!Date.parse(guestNoFingerprint.created_at));
  TestValidator.predicate("updated_at present")(!!Date.parse(guestNoFingerprint.updated_at));
}

