import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the admin vote search endpoint for scenarios where no results are returned and when invalid filters are provided.
 *
 * Business Context:
 * This test ensures that admin-level searching of votes for a specific post works as expected in two negative cases: (1) valid filters with no matching votes, and (2) invalid filter payloads that should yield clear error responses (without sensitive leakage). It covers the full setup from user and post creation to vote history population and edge-case assertion.
 *
 * Steps:
 * 1. Register a new admin and authenticate to obtain admin privileges for search.
 * 2. Register a new member and authenticate to create a post and vote.
 * 3. As the member, create a new post in a random category with valid content.
 * 4. As the member, cast both upvote and downvote on the post to ensure votes are present.
 * 5. As the admin, search votes for the post with a non-existent voter_member_id and a vote_value not used (if only upvotes were cast, search for downvotes).
 *    - Assert that returned pagination is valid and results array is empty.
 * 6. As the admin, attempt to search votes using an invalid request body (e.g., vote_value with string instead of valid number).
 *    - Assert the API rejects input with a proper error, and that no sensitive detail is exposed.
 */
export async function test_api_post_votes_admin_search_no_results_and_invalid_filters(connection: api.IConnection) {
  // 1. Register and authenticate admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(adminLogin);

  // 2. Register and authenticate member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignUp
  });
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(memberLogin);

  // 3. Create post as member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.paragraph()(30),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Cast votes as member (both upvote and downvote for coverage)
  const upvote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate
  });
  typia.assert(upvote);
  const downvote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
