import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator-driven attachment deletion for PolEcoBoard.
 *
 * This test ensures a post attachment can be deleted by a moderator, and verifies correct business effects:
 *  - The attachment is no longer present when listing post attachments (not directly testable as listing endpoint is not exposed)
 *  - The attachment is either removed or marked as deleted (confirmation is limited to successful DELETE call)
 *  - The deletion action is traceable via audit (audit trail validation described but not directly testable without audit API)
 *  - Downloading the attachment after deletion is blocked (business logic described but not directly testable as no download API)
 *
 * Steps:
 * 1. Moderator registers and logs in (obtain moderator token).
 * 2. Member registers and logs in (obtain member token).
 * 3. Member creates a post (obtain postId).
 * 4. Member uploads an attachment to the post (obtain attachmentId).
 * 5. Moderator logs in (switch context back) and deletes the attachment by postId/attachmentId.
 * 6. (Optional, if such API existed) Confirm via list/read that attachment no longer present or is marked deleted.
 *
 * Limitations:
 * - Cannot directly test for audit/event log or attachment download after deletion, as no such endpoints are present.
 * - Main testable path is successful completion of the moderation DELETE operation.
 */
export async function test_api_moderator_post_attachment_delete_success(connection: api.IConnection) {
  // 1. Moderator registration and login
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Moderator123!";
  const moderatorDisplay = RandomGenerator.name();
  const moderatorConsent = "TOS-2024-08-13";

  // Register moderator
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplay,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);

  // Login as moderator
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);

  // 2. Member registration and login
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "UserPa33!";
  const memberDisplay = RandomGenerator.name();
  const memberConsent = "TOS-2024-08-13";

  // Register member
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplay,
      consent_status: memberConsent,
      profile_image_uri: null,
    },
  });
  typia.assert(member);

  // Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberLogin);

  // 3. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(50),
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(post);

  // 4. Member uploads an attachment
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: {
      uri: "https://example.com/sample.pdf",
      file_name: "sample.pdf",
      file_size_bytes: 345678,
      mime_type: "application/pdf",
    },
  });
  typia.assert(attachment);

  // 5. Moderator logs in again (to refresh context in case of token switch)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
