import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Verify that a moderator can retrieve the metadata and details of any attachment, regardless of author, for compliance or moderation.
 *
 * Business context:
 * Moderators are required to access the full details and metadata of any attachment for investigative, audit, compliance, or content moderation tasks. This test ensures that a moderator account can successfully retrieve an attachment posted by a regular member, regardless of authorship, and that all metadata is accessible as required by business rules. Permission models must ensure that moderators have this elevated visibility versus ordinary users.
 *
 * Step-by-step process:
 * 1. Register a member account (to author a post and add an attachment)
 * 2. Log in as this member to obtain authentication
 * 3. Member creates a post
 * 4. Member uploads/attaches a file to the new post
 * 5. Register a moderator account
 * 6. Log in as the moderator, switching roles/auth context
 * 7. As moderator, retrieve the full attachment metadata by postId and attachmentId
 * 8. Validate that the moderator receives correct, complete metadata
 */
export async function test_api_post_attachment_details_moderator_access(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 2. Login as the member
  const memberSignIn = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberSignIn);

  // 3. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(1, 1, 10),
      body: RandomGenerator.content()()(),
      tag_ids: [],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Member adds an attachment to the post
  const attachmentCreate = {
    uri: `https://cdn.files/${RandomGenerator.alphaNumeric(8)}.pdf`,
    file_name: RandomGenerator.alphabets(7) + ".pdf",
    file_size_bytes: typia.random<number & tags.Type<"int32">>(),
    mime_type: "application/pdf",
  } satisfies IPolEcoBoardAttachment.ICreate;
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: attachmentCreate,
  });
  typia.assert(attachment);
  TestValidator.equals("attached post matches")(attachment.post_id)(post.id);
  TestValidator.equals("filename matches")(attachment.file_name)(attachmentCreate.file_name);

  // 5. Register a moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphabets(12);
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "ACCEPTED:20240813-1",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorSignUp);

  // 6. Login as the moderator
  const moderatorSignIn = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorSignIn);

  // 7. As moderator, retrieve the attachment details
  const attachmentDetail = await api.functional.polEcoBoard.moderator.posts.attachments.at(connection, {
    postId: post.id,
    attachmentId: attachment.id,
  });
  typia.assert(attachmentDetail);
  TestValidator.equals("attachment id")(attachmentDetail.id)(attachment.id);
  TestValidator.equals("post id")(attachmentDetail.post_id)(post.id);
  TestValidator.equals("file_name")(attachmentDetail.file_name)(attachmentCreate.file_name);
  TestValidator.equals("mime_type")(attachmentDetail.mime_type)(attachmentCreate.mime_type);
  TestValidator.equals("file_size_bytes")(attachmentDetail.file_size_bytes)(attachmentCreate.file_size_bytes);
  TestValidator.equals("uri")(attachmentDetail.uri)(attachmentCreate.uri);
}

