import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for updating an analytics event as an admin
 *
 * Validates that analytics events can be properly updated by an admin, with enforcement
 * of business rules around mutable and immutable fields, comprehensive error response
 * checks, and full audit compliance for event record integrity.
 *
 * Steps covered:
 * 1. Register and log in as a new admin for test isolation
 * 2. Create a new analytics event (capture a valid id)
 * 3. Update multiple mutable fields and verify changes
 * 4. Assert audit fields (created_at) are immutable
 * 5. Attempt update with malformed and non-existent analyticsEventId
 * 6. Test invalid/unsupported field values for schema validation error
 * 7. Simulate unauthorized access and confirm forbidden error
 */
export async function test_api_analytics_events_update_admin(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin (session set in connection)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create an analytics event (get a real id)
  const createBody: IPolEcoBoardAnalyticsEvent.ICreate = {
