import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can create a post edit history entry on behalf of another user, capturing audit fields (pre/post-edit state, admin identity, rationale).
 *
 * This workflow simulates the end-to-end compliance process for admin-driven post audit:
 *
 * 1. Register an admin account (obtain authorized credentials).
 * 2. Login as admin to have usable Authorization session.
 * 3. Register a new member account, representing a community user.
 * 4. Login as member to gain access and post creation privileges.
 * 5. Create a new post as the member, which will later be the subject of the admin's historical edit.
 * 6. Switch context back to admin account by logging in again (updates Authorization header).
 * 7. Create a new edit entry on the user's post, providing a rationale/comment.
 * 8. Verify the IPolEcoBoardPostEdit response includes all correct audit and relationship fields:
 *    - post_id matches the target post
 *    - editor_member_id is an admin's member ID (not the original post author)
 *    - edit_body is as submitted in the request
 *    - edit_reason is as submitted
 *    - created_at is present and recent
 * 9. Try to perform the same action (edit as admin) using a regular member session and validate that authorization error occurs (business rule: only admin/moderator allowed).
 */
export async function test_api_post_edit_create_by_admin_audit_fields(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignup);

  // 2. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignup);

  // 4. Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Create post as member
  const postParams: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph(1)(),
    body: RandomGenerator.content(2)(),
    tag_ids: [],
    attachments: [],
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, { body: postParams });
  typia.assert(post);

  // 6. Switch back to admin (login again)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Admin creates post edit history (audit entry) with a rationale
  const editBody = RandomGenerator.content(2)();
  const editReason = "Compliance correction: policy violation";
  const postEdit = await api.functional.polEcoBoard.admin.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: editBody,
      edit_reason: editReason,
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(postEdit);
  // 8. Validate audit and relationship fields in the post edit
  TestValidator.equals("target post_id")(postEdit.post_id)(post.id);
  TestValidator.notEquals("admin editor ID is not post author")(postEdit.editor_member_id)(post.author_member_id);
  TestValidator.equals("edit_body value")(postEdit.edit_body)(editBody);
  TestValidator.equals("edit_reason value")(postEdit.edit_reason)(editReason);
  TestValidator.predicate("created_at is present and recent")(!!postEdit.created_at && typeof postEdit.created_at === "string");

  // 9. Try to create post edit as a non-admin (member) and expect an error
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  TestValidator.error("Only admin can create post edit audit entry")(() => api.functional.polEcoBoard.admin.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: RandomGenerator.content(1)(),
      edit_reason: "Member should not be able to perform this action",
    } satisfies IPolEcoBoardPostEdit.ICreate,
  }));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardConsentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardConsentStatus";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate retrieval of a consent status record by unique ID as an admin.
 *
 * This test simulates the admin compliance workflow for verifying consent status records in the polEcoBoard system.
 * It ensures all critical fields are present, admin permissions are enforced, and non-admins are restricted.
 *
 * Steps:
 * 1. Register a new admin account with valid unique credentials.
 * 2. Login as the just-registered admin to receive proper authentication headers.
 * 3. Create a new consent status record (with valid provider_key, region, consent_type, consent_status, session_anon_id, audit_trail).
 * 4. Fetch the created record by its returned UUID using GET as the admin.
 * 5. Validate all expected fields: provider_key, region, consent_type, consent_status, session_anon_id, audit_trail, created_at, id.
 * 6. Confirm the response type matches IPolEcoBoardConsentStatus, with true data equality match.
 * 7. Attempt to access the same resource WITHOUT the admin token, and assert that access is denied (permissions enforced).
 */
export async function test_api_consent_status_fetch_success(connection: api.IConnection) {
  // 1. Register new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResp);

  // 2. Login as the admin
  const adminSignInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignInResp);

  // 3. Create new consent status record
  const createInput: IPolEcoBoardConsentStatus.ICreate = {
    provider_key: RandomGenerator.alphaNumeric(6),
    region: "US",
    consent_type: RandomGenerator.alphaNumeric(8),
    consent_status: RandomGenerator.pick(["opt_in", "opt_out", "revoked", "pending"]),
    session_anon_id: RandomGenerator.alphaNumeric(10),
    audit_trail: JSON.stringify({ source: "test", timestamp: new Date().toISOString() }),
  };
  const createdConsentStatus = await api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
    body: createInput,
  });
  typia.assert(createdConsentStatus);

  // 4. Fetch consent status by ID (as admin)
  const fetchedConsentStatus = await api.functional.polEcoBoard.admin.consentStatuses.at(connection, {
    consentStatusId: createdConsentStatus.id,
  });
  typia.assert(fetchedConsentStatus);
  // 5. Validate all expected fields
  TestValidator.equals("provider_key")(fetchedConsentStatus.provider_key)(createInput.provider_key);
  TestValidator.equals("region")(fetchedConsentStatus.region)(createInput.region);
  TestValidator.equals("consent_type")(fetchedConsentStatus.consent_type)(createInput.consent_type);
  TestValidator.equals("consent_status")(fetchedConsentStatus.consent_status)(createInput.consent_status);
  TestValidator.equals("session_anon_id")(fetchedConsentStatus.session_anon_id)(createInput.session_anon_id);
  TestValidator.equals("audit_trail")(fetchedConsentStatus.audit_trail)(createInput.audit_trail);
  TestValidator.equals("id")(fetchedConsentStatus.id)(createdConsentStatus.id);
  // created_at is not directly matched (set by the backend), but should be ISO8601
  TestValidator.predicate("created_at format")(!!fetchedConsentStatus.created_at && !isNaN(Date.parse(fetchedConsentStatus.created_at)));

  // 6. Attempt access WITHOUT admin headers (simulate logout by clearing Authorization header)
  const anonConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Non-admin access denied")(
    async () => {
      await api.functional.polEcoBoard.admin.consentStatuses.at(anonConnection, {
        consentStatusId: createdConsentStatus.id,
      });
    },
  );
}

