import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate updating a post edit by admin and confirm audit compliance.
 *
 * This test checks that an admin can update the `edit_reason` of a post edit record and that the change is persisted (audit trail). It covers the business flow from authentication through post and edit creation to update, using correct DTOs and API patterns.
 *
 * Workflow:
 * 1. Register a new admin account.
 * 2. Login as admin to establish privileges.
 * 3. Register a member (as base author for the post).
 * 4. Login as the member.
 * 5. Create a new post as the member.
 * 6. Login as admin again (token context switch).
 * 7. Admin creates the first post edit record.
 * 8. Admin updates the post edit (edits the edit_reason field).
 * 9. Assert that the edit_reason is updated and the edit id is unchanged.
 */
export async function test_api_post_edit_update_by_admin_success_and_audit(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 4. Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Create post as member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph(1),
      body: RandomGenerator.paragraph(2),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Re-login as admin (token context)
  const adminRelogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminRelogin);

  // 7. Admin creates first post edit
  const initialEditReason = "Initial rationale for moderation.";
  const postEdit = await api.functional.polEcoBoard.admin.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: post.body,
      edit_reason: initialEditReason,
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(postEdit);

  // 8. Admin updates the post edit record
  const updatedEditReason = "Updated for compliance review.";
  const updatedPostEdit = await api.functional.polEcoBoard.admin.posts.postEdits.updateEdit(connection, {
    postId: post.id,
    postEditId: postEdit.id,
    body: {
      edit_reason: updatedEditReason,
    } satisfies IPolEcoBoardPostEdit.IUpdate,
  });
  typia.assert(updatedPostEdit);

  // 9. Assert changes: id is the same, edit_reason updated
  TestValidator.equals("edit id unchanged")(updatedPostEdit.id)(postEdit.id);
  TestValidator.equals("edit_reason updated")(updatedPostEdit.edit_reason)(updatedEditReason);
}

