import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can successfully create a moderation audit record via the /polEcoBoard/moderator/moderationActions/{moderationActionId}/audits endpoint.
 *
 * This test simulates a real-world moderation scenario. It ensures that only authorized moderators or admins can create audit records attached to moderation actions, and that all required business fields (rationale, pre/post state, actor identity) are enforced.
 *
 * Steps:
 * 1. Register a new moderator (to have a clean account for auth & business rules).
 * 2. Login as that moderator to ensure the connection carries the JWT token as required.
 * 3. Create a moderation action (simulates handling a moderation report - must include required fields such as report_id, action_type, rationale, etc.).
 * 4. Use the newly created moderator and moderation action to create an audit record.
 *    - Supply valid pre_state_snapshot/post_state_snapshot, rationale, and moderator as auditor_id.
 *    - Verify the created audit record reflects all input fields and has audit metadata (timestamps, etc.).
 * 5. Negative test: Try to create an audit with fields missing, and confirm error is returned.
 * 6. Negative test: Try to create an audit as not logged in / as a non-moderator, and confirm access is denied.
 */
export async function test_api_moderator_create_moderation_audit_success(connection: api.IConnection) {
  // 1. Register a new moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName: string = RandomGenerator.alphabets(8);
  const consentStatus: string = "accepted_v1";

  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);

  // 2. Login as moderator (ensure that Authorization header is updated in connection)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("login moderatorId matches register")(
    moderatorLogin.moderatorId
  )(moderatorReg.moderatorId);

  // 3. Create moderation action (simulate handling a reported post/comment)
  // Simulate report target and types
  const reportId: string = typia.random<string & tags.Format<"uuid">>();
  const actionType = "remove";
  const targetType = "post";
  const status = "completed";
  const rationale = "Violation of community standards (spam post)";
  const outcome = "accepted";
  const operatorId = moderatorLogin.moderatorId;

  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: operatorId,
      action_type: actionType,
      target_type: targetType,
      status: status,
      rationale: rationale,
      outcome: outcome,
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);
  TestValidator.equals("moderation action operator matches moderator")(
    moderationAction.operator_id
  )(moderatorLogin.moderatorId);
  TestValidator.equals("moderation action rationale matches")(
    moderationAction.rationale
  )(rationale);

  // 4. Create moderation audit (success path)
  const preState = { status: "pending", rationale: "Initial review" };
  const postState = {
    status: moderationAction.status,
    rationale: moderationAction.rationale,
    outcome: moderationAction.outcome,
  };
  const auditReason = "Final decision documented by moderator.";

  const audit = await api.functional.polEcoBoard.moderator.moderationActions.audits.create(connection, {
    moderationActionId: moderationAction.id,
    body: {
      moderation_action_id: moderationAction.id,
      auditor_id: moderatorLogin.moderatorId,
      pre_state_snapshot: JSON.stringify(preState),
      post_state_snapshot: JSON.stringify(postState),
      reason: auditReason,
    } satisfies IPolEcoBoardModerationAudit.ICreate,
  });
  typia.assert(audit);
  TestValidator.equals("audit moderation_action_id matches")(
    audit.moderation_action_id
  )(moderationAction.id);
  TestValidator.equals("audit auditor_id matches moderator")(
    audit.auditor_id
  )(moderatorLogin.moderatorId);
  TestValidator.equals("audit reason matches")(
    audit.reason
  )(auditReason);
  TestValidator.predicate("audit has created/updated timestamps")(
    typeof audit.created_at === "string" && audit.created_at.length > 0 &&
    typeof audit.updated_at === "string" && audit.updated_at.length > 0
  );

  // 5. Negative test: Attempt audit creation with missing required fields (omit pre_state_snapshot)
  await TestValidator.error("creating audit with missing field should fail")(
    async () => {
      await api.functional.polEcoBoard.moderator.moderationActions.audits.create(
        connection,
        {
          moderationActionId: moderationAction.id,
          body: {
            moderation_action_id: moderationAction.id,
            auditor_id: moderatorLogin.moderatorId,
            // pre_state_snapshot: omitted on purpose
            post_state_snapshot: JSON.stringify(postState),
            reason: auditReason,
          } as any, // purposely use 'as any' only for error trigger (runtime, not type suppression)
        }
      );
    }
  );

  // 6. Negative test: Attempt to create audit as a non-moderator (simulate logout by removing Authorization header or new connection)
  const unauthConnection = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error(
    "unauthenticated user should not be able to create moderation audit"
  )(async () => {
    await api.functional.polEcoBoard.moderator.moderationActions.audits.create(
      unauthConnection,
      {
        moderationActionId: moderationAction.id,
        body: {
          moderation_action_id: moderationAction.id,
          auditor_id: moderatorLogin.moderatorId,
          pre_state_snapshot: JSON.stringify(preState),
          post_state_snapshot: JSON.stringify(postState),
          reason: auditReason,
        } satisfies IPolEcoBoardModerationAudit.ICreate,
      }
    );
  });
}

