  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("login moderatorId matches register")(
    moderatorLogin.moderatorId
  )(moderatorReg.moderatorId);

  // 3. Create moderation action (simulate handling a reported post/comment)
  // Simulate report target and types
  const reportId: string = typia.random<string & tags.Format<"uuid">>();
  const actionType = "remove";
  const targetType = "post";
  const status = "completed";
  const rationale = "Violation of community standards (spam post)";
  const outcome = "accepted";
  const operatorId = moderatorLogin.moderatorId;

  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: operatorId,
      action_type: actionType,
      target_type: targetType,
      status: status,
      rationale: rationale,
      outcome: outcome,
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);
  TestValidator.equals("moderation action operator matches moderator")(
    moderationAction.operator_id
  )(moderatorLogin.moderatorId);
  TestValidator.equals("moderation action rationale matches")(
    moderationAction.rationale
  )(rationale);

  // 4. Create moderation audit (success path)
  const preState = { status: "pending", rationale: "Initial review" };
  const postState = {
    status: moderationAction.status,
    rationale: moderationAction.rationale,
    outcome: moderationAction.outcome,
  };
  const auditReason = "Final decision documented by moderator.";

  const audit = await api.functional.polEcoBoard.moderator.moderationActions.audits.create(connection, {
    moderationActionId: moderationAction.id,
    body: {
      moderation_action_id: moderationAction.id,
      auditor_id: moderatorLogin.moderatorId,
      pre_state_snapshot: JSON.stringify(preState),
      post_state_snapshot: JSON.stringify(postState),
      reason: auditReason,
    } satisfies IPolEcoBoardModerationAudit.ICreate,
  });
  typia.assert(audit);
  TestValidator.equals("audit moderation_action_id matches")(
    audit.moderation_action_id
  )(moderationAction.id);
  TestValidator.equals("audit auditor_id matches moderator")(
    audit.auditor_id
  )(moderatorLogin.moderatorId);
  TestValidator.equals("audit reason matches")(
    audit.reason
  )(auditReason);
  TestValidator.predicate("audit has created/updated timestamps")(
    typeof audit.created_at === "string" && audit.created_at.length > 0 &&
    typeof audit.updated_at === "string" && audit.updated_at.length > 0
  );

  // 5. Negative test: Attempt audit creation with missing required fields (omit pre_state_snapshot)
  await TestValidator.error("creating audit with missing field should fail")(
    async () => {
      await api.functional.polEcoBoard.moderator.moderationActions.audits.create(
        connection,
        {
          moderationActionId: moderationAction.id,
          body: {
            moderation_action_id: moderationAction.id,
            auditor_id: moderatorLogin.moderatorId,
            // pre_state_snapshot: omitted on purpose
            post_state_snapshot: JSON.stringify(postState),
            reason: auditReason,
          } as any, // purposely use 'as any' only for error trigger (runtime, not type suppression)
        }
      );
    }
  );

  // 6. Negative test: Attempt to create audit as a non-moderator
  // Instead of manipulating connection.headers, just pass the given connection object
  // (the connection won't be authenticated as moderator unless login API is called)
  // So we can simulate by passing a fresh connection object with only the required fields (host, etc)
  const unauthConnection: api.IConnection = { host: connection.host };
  await TestValidator.error(
    "unauthenticated user should not be able to create moderation audit"
  )(async () => {
    await api.functional.polEcoBoard.moderator.moderationActions.audits.create(
      unauthConnection,
      {
        moderationActionId: moderationAction.id,
        body: {
          moderation_action_id: moderationAction.id,
          auditor_id: moderatorLogin.moderatorId,
          pre_state_snapshot: JSON.stringify(preState),
          post_state_snapshot: JSON.stringify(postState),
          reason: auditReason,
        } satisfies IPolEcoBoardModerationAudit.ICreate,
      }
    );
  });
}

