import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates admin-only soft deletion (moderation) of a comment on a post.
 *
 * Business context: Only admins can perform comment deletion through the admin endpoint. Deleted comments are hidden from standard listings but retained for admin audit. The deletion must be idempotent or return a business/validation error when repeated. Admin actions are explicitly required for this privileged operation. Permission enforcement is critical.
 *
 * Test workflow:
 * 1. Register a regular member and as that member, create a post.
 * 2. The member leaves a comment on that post.
 * 3. Register an admin account and authenticate as admin.
 * 4. Admin deletes the member's comment via the admin endpoint.
 * 5. Validate the comment's deleted_at is set.
 * 6. Admin deletes the same comment again (should error or be idempotent).
 * 7. Attempt to delete a comment with a random/invalid commentId (should error).
 * 8. Attempt to delete a comment on non-existent or deleted post (should error).
 * 9. As a non-admin (member), attempt to use the admin endpoint and confirm permission error.
 */
export async function test_api_admin_comment_deletion_success_and_permission(connection: api.IConnection) {
  // ---------- Test Setup: Register member, create post and comment ----------
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPasswordHash = RandomGenerator.alphabets(32);
  const memberDisplayName = RandomGenerator.name();
  const memberConsent = "v1";
  // Register member
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPasswordHash,
      display_name: memberDisplayName,
      consent_status: memberConsent
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // Create a post as the member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(20),
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // Create a comment as member
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(8)
    } satisfies IPolEcoBoardComment.ICreate
  });
  typia.assert(comment);

  // ---------- Test Setup: Register and authenticate admin ----------
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  // Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // ---------- Test: Admin deletes the comment ----------
  const erased = await api.functional.polEcoBoard.admin.posts.comments.erase(connection, {
    postId: post.id,
    commentId: comment.id
  });
  typia.assert(erased);
  TestValidator.equals("deleted_at should be set")(typeof erased.deleted_at === "string")(true);

  // ---------- Test: Admin tries to delete already deleted comment ----------
  TestValidator.error("deleting already deleted comment should error or be idempotent")(async () => {
    await api.functional.polEcoBoard.admin.posts.comments.erase(connection, {
      postId: post.id,
      commentId: comment.id
    });
  });

  // ---------- Test: Delete a comment with random/invalid commentId ----------
  const randomCommentId = typia.random<string & tags.Format<"uuid">>()
  TestValidator.error("deleting random non-existent comment should error")(async () => {
    await api.functional.polEcoBoard.admin.posts.comments.erase(connection, {
      postId: post.id,
      commentId: randomCommentId
    });
  });

  // ---------- Test: Delete a comment on non-existent post ----------
  const randomPostId = typia.random<string & tags.Format<"uuid">>()
  TestValidator.error("deleting comment on non-existent post should error")(async () => {
    await api.functional.polEcoBoard.admin.posts.comments.erase(connection, {
      postId: randomPostId,
      commentId: comment.id
    });
  });

  // ---------- Test: Permission denied for non-admin user ----------
  // Re-login as member, attempt admin-only endpoint
  // (Assume connection swaps user context on successful login - see system guidelines)
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPasswordHash,
      display_name: memberDisplayName,
      consent_status: memberConsent
    } satisfies IPolEcoBoardMember.ICreate
  });
  TestValidator.error("non-admin cannot use admin endpoint")(async () => {
