import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Ensure that members cannot add more attachments to a post than the platform allows.
 *
 * Business workflow:
 * 1. Member registration (with random email and password).
 * 2. Login for authentication and JWT token setup.
 * 3. Create a polEcoBoard post with valid category, title, and body.
 * 4. Upload the maximum allowable number of attachments one by one, and confirm all succeed.
 * 5. Attempt to upload one additional attachment (exceeding the per-post limit).
 * 6. Confirm the server rejects the request with an error, and no attachment is created beyond the quota.
 *
 * Platform quota for attachments per post is assumed as 5 for this test; adjust the MAX_ATTACHMENTS_PER_POST constant if policy changes.
 */
export async function test_api_post_attachment_create_member_exceeds_limit(
  connection: api.IConnection,
) {
  // 1. Member registration
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 2. Member login (sets JWT Authorization in connection)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create a post
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1, 2).slice(0, 120); // within 10-120 chars
  const postBody = RandomGenerator.content()(2, 10).slice(0, 10000); // within 10-10,000 chars
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Upload maximum allowable attachments
  const MAX_ATTACHMENTS_PER_POST = 5; // Increase if business rule changes
  const uploadedAttachmentIds: string[] = [];
  for (let i = 0; i < MAX_ATTACHMENTS_PER_POST; ++i) {
    const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
      postId: post.id,
      body: {
        uri: `https://example.com/file${i + 1}.pdf`,
        file_name: `sample_file_${i + 1}.pdf`,
        file_size_bytes: 2048 + i * 200,
        mime_type: "application/pdf",
      } satisfies IPolEcoBoardAttachment.ICreate,
    });
    typia.assert(attachment);
    TestValidator.equals("attached to correct post")(attachment.post_id)(post.id);
    uploadedAttachmentIds.push(attachment.id);
  }

  // 5. Attempt to upload one extra attachment (should fail)
  await TestValidator.error("attachment limit exceeded should fail")(
    async () => {
      await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
        postId: post.id,
        body: {
          uri: `https://example.com/overflow.pdf`,
          file_name: "overflow_attachment.pdf",
          file_size_bytes: 4096,
          mime_type: "application/pdf",
        } satisfies IPolEcoBoardAttachment.ICreate,
      });
    },
  );
}

