import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationProvider";
import type { IPageIPolEcoBoardNotificationProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationProvider";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test searching for notification providers as an admin.
 *
 * This test validates the core admin flows for listing/searching notification providers registered in polEcoBoard. The test will:
 * 1. Register an admin user (fresh credentials)
 * 2. Login as admin to obtain an authentication token
 * 3. Create at least one notification provider for search validation
 * 4. Perform search requests with various filters (status, region, paging) and with no filters at all
 * 5. Confirm that search returns paginated, correctly filtered results matching the provider schema
 * 6. Confirm access control by ensuring that unauthenticated (non-admin) requests fail
 */
export async function test_api_admin_notification_provider_search_successful(
  connection: api.IConnection,
) {
  // 1. Register an admin user
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(15);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signUpRes);

  // 2. Login as admin to obtain authentication token
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signInRes);

  // 3. Create at least one notification provider for search validation
  const providerData: IPolEcoBoardNotificationProvider.ICreate = {
    provider_name: RandomGenerator.paragraph()(1).slice(0, 40),
    provider_key: RandomGenerator.alphaNumeric(12),
    channels_supported: "email,sms,push",
    endpoint_uri: "https://" + RandomGenerator.alphaNumeric(7) + ".webhook.test/v2/notify",
    region: RandomGenerator.alphaNumeric(6),
    status: RandomGenerator.pick(["active", "inactive", "maintenance"]),
    config_metadata: JSON.stringify({ note: "e2e test integration config" }),
  };
  const createdProvider = await api.functional.polEcoBoard.admin.notificationProviders.create(connection, {
    body: providerData,
  });
  typia.assert(createdProvider);
  TestValidator.equals("provider_name")(createdProvider.provider_name)(providerData.provider_name);
  TestValidator.equals("provider_key")(createdProvider.provider_key)(providerData.provider_key);

  // 4a. Search with no filters, all providers should include the one just created
  const resultAll = await api.functional.polEcoBoard.admin.notificationProviders.search(connection, { body: {} });
  typia.assert(resultAll);
  TestValidator.predicate("Result includes created provider")(
    resultAll.data.some(p => p.provider_key === providerData.provider_key)
  );

  // 4b. Search by status
  const resultByStatus = await api.functional.polEcoBoard.admin.notificationProviders.search(connection, {
    body: { status: providerData.status },
  });
  typia.assert(resultByStatus);
  TestValidator.predicate("All results have correct status")(
    resultByStatus.data.every(p => p.status === providerData.status)
  );

  // 4c. Search by region
  const resultByRegion = await api.functional.polEcoBoard.admin.notificationProviders.search(connection, {
    body: { region: providerData.region },
  });
  typia.assert(resultByRegion);
  TestValidator.predicate("All results match region")(
    resultByRegion.data.every(p => p.region === providerData.region)
  );

  // 4d. Search with pagination (limit 1, page 1)
  const pagedResult = await api.functional.polEcoBoard.admin.notificationProviders.search(connection, {
    body: { limit: 1, page: 1 },
  });
  typia.assert(pagedResult);
  TestValidator.equals("pagination limit")(pagedResult.pagination.limit)(1);
  TestValidator.predicate("At most 1 record returned")(
    pagedResult.data.length <= 1
  );

  // 5. Validate returned objects are valid and not soft-deleted
  resultAll.data.forEach(obj => {
    typia.assert(obj);
    TestValidator.equals("not soft deleted")(obj.deleted_at)(null);
  });

  // 6. Confirm error for requests without admin Authorization
  const unauthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("Unauthorized access should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationProviders.search(
        unauthConn,
        { body: {} },
      );
    }
  );
}

