 */
export async function test_api_comment_report_search_pagination_and_filtering_moderator(connection: api.IConnection) {
  // 1. Register and login as moderator
  const modEmail: string = typia.random<string & tags.Format<"email">>();
  const modPassword = "TestPassword12!";
  const displayName = RandomGenerator.name();
