import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPageIPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin user can properly search, filter, and paginate abuse/moderation reports for a specific post.
 *
 * This comprehensive test covers:
 * 1. Set up: Register a new admin and log in, register a post as a member, and create several reports on that post as a member user.
 * 2. As an admin, call the report search (PATCH /polEcoBoard/admin/posts/{postId}/reports) endpoint with:
 *    - No filters (basic scan, first page expected)
 *    - Pagination (e.g. limit=2, page=2), verifying correct metadata and content
 *    - Filter by reason_code (should return only matching subset)
 *    - Filter by created_at range (should return only reports in this window)
 *    - Filter by reporter_member_id (only reports by a specific reporter)
 *    - All filters combined (should properly intersect sets)
 *    - Filter with intentionally excessive limits (should clip to allowed server max, e.g. 100)
 *    - Filter for an empty result (no matches)
 * 3. Negative cases:
 *    - Search for a non-existent postId (should yield empty or error)
 *    - Search for a deleted postId (should yield empty or error)
 *    - search as unauthenticated or with expired/bad token (should fail with auth error)
 *    - search with invalid postId format (should fail with validation error)
 *    - search as a non-admin (should fail with authorization error)
 *
 * Steps:
 * 1. Register and login as admin.
 * 2. Register and login as member (for creating a post and reports).
 * 3. Create a post as a member.
 * 4. File several reports against that post as a member (vary reason, description, and created_at via test timing).
 * 5. Switch to admin user.
 * 6. Exercise the /polEcoBoard/admin/posts/{postId}/reports endpoint with varied filters and paging as described above.
 * 7. Validate response types, content, pagination, and access controls.
 */
export async function test_api_post_report_search_by_admin_filter_pagination_error_handling(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Create a post as a member (simulate as member by using member post endpoint)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1, 2),
      body: RandomGenerator.content()(1, 3)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. File several reports as a member (simulate as ordinary member)
  // We'll file 3 reports with different reason_codes
  const reasons = ["abuse", "spam", "hate"];
  for (const reason of reasons) {
    const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
      postId: post.id,
      body: {
        reason_code: reason,
        reason_description: `Report for ${reason} at ${new Date().toISOString()}`,
        post_id: post.id,
      } satisfies IPolEcoBoardReport.ICreate,
    });
    typia.assert(report);
  }

  // 4. As admin, perform report searches with various filters & pagination
  // a) No filters (should return all above reports, correct pagination)
  let output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: {},
  });
  typia.assert(output);
  TestValidator.predicate("all reports returned")(output.data.length >= 3);
  TestValidator.equals("total records")(output.pagination.records)(output.data.length);

  // b) Pagination (limit=2, page=1)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(output);
  TestValidator.equals("pagination limit")(output.pagination.limit)(2);
  TestValidator.equals("pagination current page")(output.pagination.current)(1);
  TestValidator.predicate("page contains 2 or fewer entries")(output.data.length <= 2);

  // c) Filter by reason_code (reason_code = "spam")
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "spam" },
  });
  typia.assert(output);
  TestValidator.predicate("only spam reports")(output.data.every(r => r.reason_code === "spam"));

  // d) Date range filter (from now - 1min to now + 2min)
  const now = new Date();
  const from = new Date(now.getTime() - 60 * 1000).toISOString();
  const to = new Date(now.getTime() + 120 * 1000).toISOString();
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { created_at_start: from, created_at_end: to },
  });
  typia.assert(output);
  TestValidator.predicate("created in window")(output.data.every(r => r.created_at >= from && r.created_at <= to));

  // e) Reporter filter (reporter_member_id from a report)
  const firstReport = output.data[0];
  if (firstReport) {
    output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
      postId: post.id,
      body: { reporter_member_id: firstReport.reporter_member_id },
    });
    typia.assert(output);
    TestValidator.predicate("only first reporter")(output.data.every(r => r.reporter_member_id === firstReport.reporter_member_id));
  }

  // f) Combination filter (reason_code and date range)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "spam", created_at_start: from, created_at_end: to },
  });
  typia.assert(output);
  TestValidator.predicate("spam reports in window")(output.data.every(r => r.reason_code === "spam" && r.created_at >= from && r.created_at <= to));

  // g) Excessive limit (limit=1000, should be capped, but must not error)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 1000 },
  });
  typia.assert(output);
  TestValidator.predicate("limit not exceeded")(output.pagination.limit <= 100);

  // h) Empty result (impossible reason_code)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "nonexistent_reason_code_zzz" },
  });
  typia.assert(output);
  TestValidator.equals("empty data")(output.data.length)(0);

  // 5. Negative cases
  // i) Non-existent postId (random uuid)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: typia.random<string & tags.Format<"uuid">>(),
    body: {},
  });
  typia.assert(output);
  // We cannot guarantee error vs empty, but must not throw

  // j) Invalid postId format
  await TestValidator.error("malformed postId should fail")(async () => {
    await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
      postId: "not_a_uuid" as any,
      body: {},
    });
  });

  // k) Unauthenticated: remove token manually and attempt
  if (connection.headers) {
    const oldAuth = connection.headers.Authorization;
    delete connection.headers.Authorization;
    await TestValidator.error("unauthenticated access fails")(async () => {
      await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
        postId: post.id,
        body: {},
      });
    });
    connection.headers.Authorization = oldAuth;
  }

  // l) Authorization: simulate as member (auth as member) - cannot create member with current API, so omitted.
}

