import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the ability of an admin to update any polEcoBoard post, including overriding normal edit/authorship constraints and properly handling input validation errors.
 *
 * Business context:
 * - Admins must be able to edit any post at any time, regardless of lock windows or original authorship. This ensures moderation and compliance capabilities are not blocked.
 * - All input validation (title/body min/max length, forbidden/extra fields, malformed input) should trigger clear error responses.
 * - Edits should be fully audited (i.e., timestamps and updated fields tracked per business rules).
 *
 * Test steps:
 * 1. Register and log in an admin user (obtain admin credentials) for future requests.
 * 2. Register and log in a normal member so a post can be created with non-admin authorship.
 * 3. As admin, create a board category.
 * 4. As member, create a new post in the board category (save returned post for test).
 * 5. As admin, update the post:
 *    a. Valid update: Change post title and body to valid, different text. Verify the updated post is returned and the changes are reflected.
 *    b. Invalid update (validation errors):
 *         - Supply a title that is too short (<10 chars), verify error thrown.
 *         - Supply a body that is too short (<10 chars), verify error thrown.
 *         - Supply a title that is too long (>120 chars), verify error thrown.
 *         - Supply a body that is too long (>10,000 chars), verify error thrown.
 *    c. Audit: Confirm updated_at field was updated appropriately after successful edit, and that previous/forbidden fields remain unchanged.
 */
export async function test_api_admin_post_update_success_and_validation(connection: api.IConnection) {
  // 1. Register an admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
