    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    },
  });
  typia.assert(moderatorSignUp);
  const moderatorId = moderatorSignUp.moderatorId;
  const moderatorToken = moderatorSignUp.setHeaders.Authorization;

  // 2. Login as moderator (check login/identity)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("moderator login id matches sign up")(moderatorLogin.moderatorId)(moderatorId);

  // Set connection for moderator
  connection.headers = { ...connection.headers, Authorization: moderatorToken };

  // 3. Register member (unique email/password)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = "Member#12345";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberSignUp);
  const memberToken = memberSignUp.setHeaders.Authorization;

  // 4. Login as member to acquire real session
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 5. As admin/moderator, create notifications for self and member
  // Self notification
  const notifSelf = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: moderatorId,
      event_type: "moderation_action",
      status: "delivered",
    },
  });
  typia.assert(notifSelf);

  // Member notification
  // Use same logic as before, but with correct member id
  const notifMember = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: memberEmail === moderatorEmail ? typia.random<string & tags.Format<"uuid">>() : memberSignUp.setHeaders.Authorization,
      event_type: "admin_notice",
      status: "pending",
    },
  });
  typia.assert(notifMember);
  const memberId = notifMember.recipient_member_id;

  // 6. Search all notifications for moderator (self)
  const selfSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { recipient_member_id: moderatorId },
  });
  typia.assert(selfSearch);
  TestValidator.predicate("self notification present")(!!selfSearch.data.find((n) => n.id === notifSelf.id));

  // 7. Search notifications for member using recipient_member_id filter
  const memberSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { recipient_member_id: memberId },
  });
  typia.assert(memberSearch);
  TestValidator.predicate("member notification present")(!!memberSearch.data.find((n) => n.id === notifMember.id));

  // 8. Filtering: status
  const statusSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { status: "pending" },
  });
  typia.assert(statusSearch);
  TestValidator.predicate("pending notification present")(statusSearch.data.some((n) => n.status === "pending"));

  // Filtering: event_type
  const typeSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { event_type: "moderation_action" },
  });
  typia.assert(typeSearch);
  TestValidator.predicate("moderation_action notification present")(typeSearch.data.some((n) => n.event_type === "moderation_action"));

  // 9. Pagination: limit=1
  const paged = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("one item page limit")(paged.data.length)(1);
  TestValidator.predicate("pagination fields")(typeof paged.pagination.current === "number" && typeof paged.pagination.pages === "number");

  // 10. Unauthorized: member tries to access moderator notifications endpoint
  connection.headers = { ...connection.headers, Authorization: memberToken };
  TestValidator.error("member cannot access moderator endpoint")(async () => {
    await api.functional.polEcoBoard.moderator.notifications.index(connection, {
      body: {},
    });
  });

  // 11. Expired or invalid token
  connection.headers = { ...connection.headers, Authorization: "Bearer invalidtoken" };
  TestValidator.error("invalid token denied")(async () => {
    await api.functional.polEcoBoard.moderator.notifications.index(connection, {
      body: { recipient_member_id: moderatorId },
    });
  });

  // 12. Invalid filter criteria (nonexistent status)
  connection.headers = { ...connection.headers, Authorization: moderatorToken };
  TestValidator.error("invalid filter fails")(async () => {
    await api.functional.polEcoBoard.moderator.notifications.index(connection, {
      body: { status: "not-a-real-status" },
    });
  });
}

