import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCommentEdit";
import type { IPageIPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardCommentEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test retrieval of comment edit history as a moderator for audit and compliance.
 *
 * Ensures that:
 * 1. Moderators can retrieve the complete edit history of any comment regardless of authorship.
 * 2. Advanced filtering (by editor_member_id, by comment, pagination) works.
 * 3. Edge cases are handled, such as requesting for invalid or non-existent comment, and permission enforcement (non-moderators are denied access).
 * 4. An empty result set is handled gracefully (no error, just empty data).
 *
 * Step-by-step process:
 * 1. Register a regular member, then create a post and an associated comment as that member.
 * 2. Edit the comment multiple times to generate edit history records.
 * 3. Register and login as a moderator (obtaining Authorization).
 * 4. As a moderator, fetch the edit history for the comment (unfiltered: should return all histories).
 * 5. Fetch the edit history using filter by editor_member_id (should isolate entries for that member).
 * 6. Attempt to fetch history for invalid/nonexistent commentId (should fail gracefully).
 * 7. Attempt to fetch history for the comment as a non-moderator (should be rejected with permission error).
 * 8. Edit a comment that has no edits and verify retrieval returns empty history (no error, empty array).
 */
export async function test_api_comment_edit_history_moderator_access_audit_filtering(connection: api.IConnection) {
  // -----------------------------------------------------------------------------
  // 1. Register a regular member, create a post and a comment.
  // -----------------------------------------------------------------------------
  const member_email = typia.random<string & tags.Format<"email">>();
  const member_display = RandomGenerator.alphaNumeric(12);
  const member_password = RandomGenerator.alphaNumeric(10);

  // Register the member
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member_email,
      password_hash: member_password,
      display_name: member_display,
      profile_image_uri: null,
      consent_status: "latest_v1"
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // Create a post (random category_id for test; in real setup should ensure exists)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(),
      tag_ids: [],
      attachments: []
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // Create a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(1),
      parent_comment_id: null,
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // -----------------------------------------------------------------------------
  // 2. Edit the comment multiple times to generate edit history records.
  // -----------------------------------------------------------------------------
  const edit_bodies = [RandomGenerator.paragraph()(1), RandomGenerator.paragraph()(1)];
  for (const edited_body of edit_bodies) {
    const editedComment = await api.functional.polEcoBoard.member.posts.comments.update(connection, {
      postId: post.id,
      commentId: comment.id,
      body: {
        body: edited_body,
      } satisfies IPolEcoBoardComment.IUpdate,
    });
    typia.assert(editedComment);
  }

  // -----------------------------------------------------------------------------
  // 3. Register and login as a moderator
  // -----------------------------------------------------------------------------
  const moderator_email = typia.random<string & tags.Format<"email">>();
  const moderator_display = RandomGenerator.alphaNumeric(10);
  const moderator_password = RandomGenerator.alphaNumeric(8);

  const moderatorRegister = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderator_email,
      password: moderator_password,
      display_name: moderator_display,
      consent_status: "latest_v1",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegister);

  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderator_email,
      password: moderator_password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);

  // -----------------------------------------------------------------------------
  // 4. As moderator, fetch the full edit history (no filters)
  // -----------------------------------------------------------------------------
  const commentHistoryUnfiltered = await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.search(connection, {
    postId: post.id,
    commentId: comment.id,
    body: { page: 1, limit: 10 } satisfies IPolEcoBoardCommentEdit.IRequest,
  });
  typia.assert(commentHistoryUnfiltered);
  TestValidator.predicate("history results present")(commentHistoryUnfiltered.data.length >= 2);

  // Assert that editor_member_id matches member for all history events
  for (const hist of commentHistoryUnfiltered.data) {
    TestValidator.equals("editor_member_id matches")(hist.editor_member_id)(member.id);
    TestValidator.equals("comment_id matches")(hist.comment_id)(comment.id);
  }

  // -----------------------------------------------------------------------------
  // 5. Fetch edit history filtered by editor_member_id (should match entries)
  // -----------------------------------------------------------------------------
  const commentHistoryByEditor = await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.search(connection, {
    postId: post.id,
    commentId: comment.id,
    body: { editor_member_id: member.id, page: 1, limit: 10 } satisfies IPolEcoBoardCommentEdit.IRequest,
  });
  typia.assert(commentHistoryByEditor);
  for (const hist of commentHistoryByEditor.data) {
    TestValidator.equals("filtered editor matches")(hist.editor_member_id)(member.id);
    TestValidator.equals("comment_id matches")(hist.comment_id)(comment.id);
  }
  TestValidator.equals("history lengths equal")(commentHistoryByEditor.data.length)(commentHistoryUnfiltered.data.length);

  // -----------------------------------------------------------------------------
  // 6. Attempt to fetch history for invalid/nonexistent commentId
  // -----------------------------------------------------------------------------
  const invalid_comment_id = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("history fetch with invalid commentId fails")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.search(connection, {
        postId: post.id,
        commentId: invalid_comment_id,
        body: { page: 1, limit: 10 } satisfies IPolEcoBoardCommentEdit.IRequest,
      });
    }
  );

  // -----------------------------------------------------------------------------
  // 7. Attempt to fetch history as NON-moderator (should reject)
  // -----------------------------------------------------------------------------
  // Here, log in as the original member (simulate switching roles by losing/modifying JWT)
  // Since there's no member login in this API surface, simulate by removing Authorization
  const connWithoutAuth: api.IConnection = {
    ...connection,
    headers: { ...(connection.headers || {}), Authorization: undefined },
  };
  TestValidator.error("non-moderator cannot access moderator endpoint")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.search(connWithoutAuth, {
        postId: post.id,
        commentId: comment.id,
        body: { page: 1, limit: 10 } satisfies IPolEcoBoardCommentEdit.IRequest,
      });
    }
  );

  // -----------------------------------------------------------------------------
  // 8. Create a comment that is NEVER edited, and history fetch should be empty.
  // -----------------------------------------------------------------------------
  // New post and comment for a pristine test
  const post2 = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(),
      tag_ids: [],
      attachments: []
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post2);

  const comment2 = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post2.id,
    body: {
      body: RandomGenerator.paragraph()(1),
      parent_comment_id: null,
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment2);

  const pristineHistory = await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.search(connection, {
    postId: post2.id,
    commentId: comment2.id,
    body: { page: 1, limit: 10 } satisfies IPolEcoBoardCommentEdit.IRequest,
  });
  typia.assert(pristineHistory);
  TestValidator.equals("no edit history is empty")(pristineHistory.data.length)(0);
}

