  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { limit: 1000, page: 100 } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("does not return too many records")(res.data.length <= 1000);
  }
  // 4j. Edge case: filter for deleted/archived. (Since we can't create deleted in this suite, simulate date before all creation)
