import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPageIPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardBoard";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the admin board search API for advanced filtering, pagination, and permission enforcement.
 *
 * This function simulates a full workflow for an admin searching boards, using all supported filters and pagination mechanisms, with checks for correct record retrieval, schema, and authorization.
 * It also verifies correct enforcement of admin-only protection, and covers many edge cases including no-result circumstances and invalid filters.
 *
 * Steps:
 * 1. Register an admin account and log in to get auth credentials (token set via SDK `connection` headers).
 * 2. Create two board categories (catA, catB) via admin API.
 * 3. Create four boards: two in catA, two in catB, with deliberately different codes/names/public/archive/displayOrder values to test filter/sorting behaviors.
 * 4. For each supported filter (category, code, name, is_public, is_archived, display_order):
 *    - Call the search API with only that filter and validate only expected boards are returned.
 * 5. Test with multiple filters combined (e.g., catA + is_public=false).
 * 6. Use pagination (limit, page) to verify correct record slicing (page 1, 2, etc.).
 * 7. Try invalid category UUID and confirm empty result (no crash).
 * 8. Try code/name partial match and confirm correct records.
 * 9. Try invalid pagination values (page=0, limit=0, limit>100) and check for proper failure or validation error.
 * 10. As a negative case, clear admin tokens from the connection and attempt board search; assert that unauthorized error or access denied occurs.
 * 11. For every search result, typia.assert() each record and check key fields (category linkage, schema, etc).
 */
export async function test_api_board_search_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10);
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  // 2. Login admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });

  // 3. Create categories
  const catA = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      display_order: 1,
      description: "Category A",
    },
  });
  const catB = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      display_order: 2,
      description: "Category B",
    },
  });

  // 4. Create boards in different categories & with varied properties
  const boards: IPolEcoBoardBoard[] = [];
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catA.id,
      name: "Board 1A",
      code: "board1a_code",
      description: null,
      is_public: true,
      is_archived: false,
      display_order: 3,
    },
  }));
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catA.id,
      name: "Board 2A",
      code: "board2a_unique",
      description: "desc2A",
      is_public: false,
      is_archived: true,
      display_order: 4,
    },
  }));
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catB.id,
      name: "Board 1B",
      code: "board1b_code",
      description: null,
      is_public: false,
      is_archived: false,
      display_order: 5,
    },
  }));
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catB.id,
      name: "Board 2B",
      code: "board2b_search",
      description: "desc2B",
      is_public: true,
      is_archived: true,
      display_order: 6,
    },
  }));

  // 5. Filtering and paging checks

  // By category id
  let result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { pol_eco_board_category_id: catA.id },
  });
  typia.assert(result);
  TestValidator.equals("catA boards count")(result.data.length)(2);
  for (const b of result.data) TestValidator.equals("cat id")(b.pol_eco_board_category_id)(catA.id);

  // By code (exact match)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { code: "board2b_search" },
  });
  typia.assert(result);
  TestValidator.equals("code boards")(result.data.length)(1);
  TestValidator.equals("code check")(result.data[0].code)("board2b_search");

  // By name (partial/substring)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { name: "Board 1" },
  });
  typia.assert(result);
  TestValidator.equals("by name includes")(result.data.length)(2);
  for (const b of result.data) TestValidator.predicate("name includes 'Board 1'")(b.name.includes("Board 1"));

  // is_public filter
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { is_public: false },
  });
  typia.assert(result);
  for (const b of result.data) TestValidator.equals("is_public false")(b.is_public)(false);

  // is_archived filter
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { is_archived: true },
  });
  typia.assert(result);
  for (const b of result.data) TestValidator.equals("is_archived true")(b.is_archived)(true);

  // display_order filter
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { display_order: 6 },
  });
  typia.assert(result);
  TestValidator.equals("display_order count")(result.data.length)(1);
  TestValidator.equals("display_order value")(result.data[0].display_order)(6);

  // Combined filters
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: {
      pol_eco_board_category_id: catA.id,
      is_public: true,
    },
  });
  typia.assert(result);
  TestValidator.equals("catA + is_public true count")(result.data.length)(1);
  TestValidator.equals("combined filter match")(result.data[0].name)("Board 1A");

  // Pagination (limit 2, page 2)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(result);
  TestValidator.equals("page limit")(result.pagination.limit)(2);
  TestValidator.equals("pagination current")(result.pagination.current)(2);
  // total records, pages should reflect count
  TestValidator.equals("pagination total")(result.pagination.records)(4);
  TestValidator.equals("pagination pages")(result.pagination.pages)(2);

  // Invalid category (should return 0 results, not an error)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals("invalid category = 0")(result.data.length)(0);

  // Invalid pagination values (page=0: probably validation error)
  await TestValidator.error("page=0 throws")(() => api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { page: 0 },
  }));
  // limit=0
  await TestValidator.error("limit=0 throws")(() => api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { limit: 0 },
  }));
  // limit>100
  await TestValidator.error("limit>100 throws")(() => api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { limit: 101 },
  }));

  // 6. Permission enforcement: access denied if not an admin
  // simulate by removing Authorization from connection headers
  const noAuthConn = { ...connection, headers: { ...connection.headers, Authorization: undefined } };
  await TestValidator.error("no-auth fails")(() => api.functional.polEcoBoard.admin.boards.search(noAuthConn, {
    body: {},
  }));

  // Schema validation for search results
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: {},
  });
  typia.assert(result);
  for (const b of result.data) {
    TestValidator.predicate("id is uuid")(typeof b.id === "string" && b.id.length > 0);
    TestValidator.predicate("cat id is uuid")(typeof b.pol_eco_board_category_id === "string");
    TestValidator.predicate("display_order is int")(typeof b.display_order === "number");
    // Check all board data can be matched to real categories
    TestValidator.predicate("category exists")([catA.id, catB.id].includes(b.pol_eco_board_category_id));
  }
}

