 * Validate searching notification preferences by an authenticated member (with filtering and pagination).
 *
 * This test ensures end-to-end that:
 * - A member can register and login.
 * - The member can create multiple notification preferences for various event types and channels.
 * - Searching for notification preferences returns only the authenticated member's records.
 * - Filtering by event type and channel is respected.
 * - Pagination works as expected (correct number of records per page, proper total count).
 *
 * Scenario steps:
 * 1. Register a new member account (random, unique email).
 * 2. Log in with the new member credentials.
 * 3. Create 6+ notification preferences with distinct event_type/channel/opt_in combinations for the member.
 * 4. Perform PATCH search without any filter: all created preferences for the member should be returned.
 * 5. Perform PATCH search filtering for a subset (by event_type, by channel, by opt_in, and by multiple filters together), and verify the filtered output matches those criteria.
 * 6. Perform PATCH search with pagination (e.g., limit=2, page=2) and verify correct slicing of result data and accurate pagination meta.
 */
export async function test_api_member_notification_preference_search_success(
  connection: api.IConnection,
) {
  // 1. Register a member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signUpResult);

  // 2. Log in with the registered account
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signInResult);
  // JWT Authorization auto-handled in connection

  // 3. Create multiple notification preferences for the member
  const eventTypes = [
    "reply",
    "moderation_action",
    "mention",
  ];
  const channels = [
    "email",
    "push",
  ];
  const optIns = [true, false];
  // Generate all combinations (3*2*2 = 12), but we'll create a subset (6-8) unique
  const preferencesToCreate: { event_type: string; channel: string; opt_in: boolean }[] = [];
  for (const event_type of eventTypes) for (const channel of channels) for (const opt_in of optIns) preferencesToCreate.push({ event_type, channel, opt_in });
  const createdPrefs: IPolEcoBoardNotificationPreference[] = [];

  let known_member_id: string & tags.Format<"uuid"> | undefined = undefined;
  for (const { event_type, channel, opt_in } of preferencesToCreate.slice(0, 6)) {
    const pref = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
      body: {
        member_id: known_member_id ? known_member_id : typia.random<string & tags.Format<"uuid">>(),
        event_type,
        channel,
        opt_in,
      },
    });
    typia.assert(pref);
    if (!known_member_id) known_member_id = pref.member_id;
    createdPrefs.push(pref);
  }
  const real_member_id = known_member_id!;

  // 4. Search without filters: all 6 records should be returned
  {
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: {},
    });
    typia.assert(output);
    for (const pref of output.data) {
      TestValidator.equals("only this member's preferences returned")(pref.member_id)(real_member_id);
    }
    TestValidator.predicate("all created preferences are returned")(
      createdPrefs.every(({ id }) => output.data.some((p) => p.id === id)),
    );
  }

  // 5. Filter by event_type (choose one)
  {
    const filter_type = createdPrefs[0].event_type;
    const filtered = createdPrefs.filter((p) => p.event_type === filter_type);
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: { event_type: filter_type },
    });
    typia.assert(output);
    TestValidator.equals("event_type filter count")(output.data.length)(filtered.length);
    TestValidator.predicate("event_type = filter_type")(output.data.every((p) => p.event_type === filter_type));
  }

  // 6. Filter by channel (choose one)
  {
    const filter_channel = createdPrefs[1].channel;
    const filtered = createdPrefs.filter((p) => p.channel === filter_channel);
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: { channel: filter_channel },
    });
    typia.assert(output);
    TestValidator.equals("channel filter count")(output.data.length)(filtered.length);
    TestValidator.predicate("channel = filter_channel")(output.data.every((p) => p.channel === filter_channel));
  }

  // 7. Filter by opt_in
  {
    const filter_optin = createdPrefs[2].opt_in;
    const filtered = createdPrefs.filter((p) => p.opt_in === filter_optin);
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: { opt_in: filter_optin },
    });
    typia.assert(output);
    TestValidator.equals("opt_in filter count")(output.data.length)(filtered.length);
    TestValidator.predicate("all opt_in = filter")(output.data.every((p) => p.opt_in === filter_optin));
  }

  // 8. Combined filter: event_type+channel+opt_in (pick one record)
  {
    const pick = createdPrefs[3];
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: {
        event_type: pick.event_type,
        channel: pick.channel,
        opt_in: pick.opt_in,
      },
    });
    typia.assert(output);
    TestValidator.equals("combined filter count")(output.data.length)(1); // only one such
    TestValidator.equals("id matches")(output.data[0].id)(pick.id);
  }

  // 9. Pagination test (limit=2, page=2)
  {
    const output = await api.functional.polEcoBoard.member.notificationPreferences.search(connection, {
      body: {
        limit: 2,
        page: 2,
      },
    });
    typia.assert(output);
    TestValidator.equals("pagination limit")(output.pagination.limit)(2);
    TestValidator.equals("pagination current")(output.pagination.current)(2);
    TestValidator.equals("pagination records")(output.pagination.records)(createdPrefs.length);
    const expected = createdPrefs.slice(2, 4).map((p) => p.id);
    const actual = output.data.map((p) => p.id);
    TestValidator.equals("page 2 correct slice")(actual.length)(expected.length);
    TestValidator.predicate("pagination page 2 contains correct records")(
      expected.every((eid) => actual.includes(eid)),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin access to full details of a vote on a comment, and confirm forbidden results for lower privilege.
 *
 * This test verifies that a properly authenticated admin can read the full details of a specific vote tied to a comment using /polEcoBoard/admin/comments/{commentId}/votes/{voteId}. It also checks that lower-privilege users, such as the voting member or unauthenticated guests, are forbidden from accessing the same data.
 *
 * Steps:
 * 1. Register an admin account and log in to fetch a token.
 * 2. Register a member account and log in. Create a minimal valid post as this member.
 * 3. As member, create a comment on the post.
 * 4. As member, vote (upvote) on the comment.
 * 5. Switch to admin account (restore admin JWT). Use the /polEcoBoard/admin/comments/{commentId}/votes/{voteId} GET endpoint, passing the correct IDs. Assert: (a) the vote record is found, (b) all fields match, (c) the vote is for the expected comment, (d) voter_member_id matches the member.
 * 6. As guest (no session/JWT) or as the member, attempt to access the same endpoint. Assert: forbidden (error/exception is thrown, not a valid result).
 */
export async function test_api_comment_vote_detail_admin_success_and_forbidden_access(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Register and login as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create a post (requires valid category_id, title, body)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.content()()(50),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a comment on the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(10),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. Vote on the comment
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 6. Switch to admin account
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Fetch vote by admin
  const adminVote = await api.functional.polEcoBoard.admin.comments.votes.at(connection, {
    commentId: comment.id,
    voteId: vote.id,
  });
  typia.assert(adminVote);
  TestValidator.equals("vote ID")(adminVote.id)(vote.id);
  TestValidator.equals("comment ID")(adminVote.comment_id)(comment.id);
  TestValidator.equals("voter_member_id")(adminVote.voter_member_id)(vote.voter_member_id);
  TestValidator.equals("vote_value")(adminVote.vote_value)(1);

  // 8. Try fetching vote as member (should be forbidden)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  TestValidator.error("Member forbidden to access admin vote endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.comments.votes.at(connection, {
        commentId: comment.id,
        voteId: vote.id,
      });
    },
  );

  // 9. Try fetching vote as guest (no login)
  delete connection.headers.Authorization;
  TestValidator.error("Guest forbidden to access admin vote endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.comments.votes.at(connection, {
        commentId: comment.id,
        voteId: vote.id,
      });
    },
  );
}

