import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin access to full details of a vote on a comment, and confirm forbidden results for lower privilege.
 *
 * This test verifies that a properly authenticated admin can read the full details of a specific vote tied to a comment using /polEcoBoard/admin/comments/{commentId}/votes/{voteId}. It also checks that lower-privilege users, such as the voting member or unauthenticated guests, are forbidden from accessing the same data.
 *
 * Steps:
 * 1. Register an admin account and log in to fetch a token.
 * 2. Register a member account and log in. Create a minimal valid post as this member.
 * 3. As member, create a comment on the post.
 * 4. As member, vote (upvote) on the comment.
 * 5. Switch to admin account (restore admin JWT). Use the /polEcoBoard/admin/comments/{commentId}/votes/{voteId} GET endpoint, passing the correct IDs. Assert: (a) the vote record is found, (b) all fields match, (c) the vote is for the expected comment, (d) voter_member_id matches the member.
 * 6. As guest (no session/JWT) or as the member, attempt to access the same endpoint. Assert: forbidden (error/exception is thrown, not a valid result).
 */
export async function test_api_comment_vote_detail_admin_success_and_forbidden_access(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Register and login as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create a post (requires valid category_id, title, body)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.content()()(50),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a comment on the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(10),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. Vote on the comment
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 6. Switch to admin account
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Fetch vote by admin
  const adminVote = await api.functional.polEcoBoard.admin.comments.votes.at(connection, {
    commentId: comment.id,
    voteId: vote.id,
  });
  typia.assert(adminVote);
  TestValidator.equals("vote ID")(adminVote.id)(vote.id);
  TestValidator.equals("comment ID")(adminVote.comment_id)(comment.id);
  TestValidator.equals("voter_member_id")(adminVote.voter_member_id)(vote.voter_member_id);
  TestValidator.equals("vote_value")(adminVote.vote_value)(1);

  // 8. Try fetching vote as member (should be forbidden)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  TestValidator.error("Member forbidden to access admin vote endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.comments.votes.at(connection, {
        commentId: comment.id,
        voteId: vote.id,
      });
    },
  );

  // 9. Try fetching vote as guest (no login)
  // Instead of modifying connection.headers directly (which may be undefined),
  // create a new shallow-copied connection WITHOUT Authorization header
  const guestConnection: api.IConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}) },
  };
  delete guestConnection.headers.Authorization;
  TestValidator.error("Guest forbidden to access admin vote endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.comments.votes.at(guestConnection, {
        commentId: comment.id,
        voteId: vote.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";

/**
 * Validate failure cases for post reporting: ensure unauthenticated users cannot submit reports and
 * schema or business validation is enforced for report reason codes/descriptions.
 *
 * This test covers two failure branches for post report submissions:
 * 1. Guest (unauthenticated) users must not be able to report posts. Upon attempting a report submission
 *    with no authentication, a 401 (or 403) error must be thrown.
 * 2. When authenticated, attempts to report a post with invalid inputs — such as missing or invalid reason_code,
 *    or empty/too-long reason_description — should be rejected with validation errors by the API.
 *
 * Business context:
 * - Only members may report posts; moderation relies on strict input schemas for reports.
 * - Reason codes must match allowed values; blank or garbage should be rejected. Descriptions that are excessively long
 *   or missing as required must trigger errors.
 *
 * Workflow:
 * 1. Create a member post through the normal endpoint (setup prerequisite, must be authenticated).
 * 2. Attempt to report that post (using the new post ID) as an unauthenticated user and validate error behavior.
 * 3. Authenticate (become a valid member user).
 * 4. Attempt to submit a report with missing reason_code: expect schema error.
 * 5. Attempt with an obviously invalid reason_code (e.g. 'invalid_code'): expect validation error.
 * 6. Attempt with a too-long reason_description: expect validation error.
 * 7. Optionally, attempt valid report (should succeed for completeness, but main focus is on validation failures).
 */
export async function test_api_member_post_report_submission_unauthenticated_and_validation(
  connection: api.IConnection,
) {
  // 1. Create a member post (authentication required)
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.alphaNumeric(16),
    body: RandomGenerator.paragraph()(15),
    tag_ids: null,
    attachments: null,
  };
  // Create post as authenticated member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);
  // Post ID for reporting
  const postId = post.id;

  // 2. Attempt post report as unauthenticated user (simulate by clearing auth header)
  //    Should throw 401/403
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers["Authorization"];
  TestValidator.error("guest should not submit report")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(unauthConnection, {
        postId,
        body: {
          reason_code: "spam", // Assume 'spam' is valid but won't test validity here
          reason_description: "Reported as spam.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 3. Re-authenticate as member (not needed if prior login is preserved)

  // 4. Attempt report missing reason_code (schema error: code required)
  TestValidator.error("missing reason_code triggers schema error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          // @ts-expect-error
          // Intentionally omit reason_code: This would normally be TS error, but simulate "empty string" if type required
          reason_code: "", // Intentionally empty string to trigger server validation error
          reason_description: "Insufficient code.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 5. Attempt report with invalid reason_code
  TestValidator.error("invalid reason_code triggers business validation error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          reason_code: "invalid_code", // Not an approved business value
          reason_description: "Purposefully invalid reason code.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 6. Attempt report with too-long reason_description
  TestValidator.error("reason_description > 400 chars triggers validation error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          reason_code: "spam", // Use plausible good value
          reason_description: RandomGenerator.alphaNumeric(500), // Exceed 400-char limit
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 7. (Optional) Submit valid report (should succeed; for full coverage)
  const validReport = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId,
    body: {
      reason_code: "spam", // Use plausible valid value
      reason_description: "Obvious spam post, violating forum guidelines.",
      post_id: postId,
      comment_id: null,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(validReport);
  TestValidator.equals("report post_id matches")(validReport.post_id)(postId);
}

