      title: "Deleted: Obsolete Discussion", // keyword 'deleted', will simulate deleted by reading property after creation
      body: "This thread has been deleted by admin.",
      tag_ids: [tagIds[1]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));

  for (const post of posts) typia.assert(post);

