import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";

/**
 * Validate the successful creation of guest sessions via POST /polEcoBoard/guests.
 *
 * Business context and necessity:
 * This test ensures the correct functioning of guest session registration, a core analytics and compliance requirement. It covers not just happy-path creation with all fields (e.g., device fingerprint for analytics) but also minimal information, privacy/compliance for user consent, and behavior when repeated payloads are sent (to observe handling of potentially duplicate/abusive anonymous creation).
 *
 * Step-by-step process:
 * 1. Create a guest session using all fields (IP, device fingerprint, consent); verify output matches input, proper UUID and timestamps.
 * 2. Edge case: Create a guest session with minimal payload (IP and consent only), confirm device_fingerprint is omitted or null, other values match.
 * 3. Try to create a guest session omitting the required consent_status; verify that this triggers an error, confirming privacy enforcement.
 * 4. Call the API twice consecutively with the same IP/device payload; verify that two sessions are created with unique IDs (non-idempotent behavior as per analytics use-case).
 */
export async function test_api_guest_session_creation_valid_and_minimal_payload(
  connection: api.IConnection,
) {
  // 1. Standard guest session creation with all fields present.
  const fullPayload: IPolEcoBoardGuest.ICreate = {
    ip_address: typia.random<string>(),
    device_fingerprint: typia.random<string>(),
    consent_status: "agreed_v2025", // Example versioned consent string
  };
  const guest1: IPolEcoBoardGuest = await api.functional.polEcoBoard.guests.create(connection, { body: fullPayload });
  typia.assert(guest1);
  TestValidator.equals("ip_address matches")(guest1.ip_address)(fullPayload.ip_address);
  TestValidator.equals("device_fingerprint matches")(guest1.device_fingerprint)(fullPayload.device_fingerprint);
  TestValidator.equals("consent_status matches")(guest1.consent_status)(fullPayload.consent_status);
  TestValidator.predicate("uuid format")(typeof guest1.id === "string" && guest1.id.length === 36 && guest1.id.includes("-"));
  TestValidator.predicate("created_at is valid string")(typeof guest1.created_at === "string");
  TestValidator.predicate("updated_at is valid string")(typeof guest1.updated_at === "string");

  // 2. Minimal required fields (edge case: omit device_fingerprint)
  const minimalPayload: IPolEcoBoardGuest.ICreate = {
    ip_address: typia.random<string>(),
    consent_status: "agreed_v2025"
  };
  const guest2: IPolEcoBoardGuest = await api.functional.polEcoBoard.guests.create(connection, { body: minimalPayload });
  typia.assert(guest2);
  TestValidator.equals("ip_address matches")(guest2.ip_address)(minimalPayload.ip_address);
  TestValidator.equals("device_fingerprint is undefined or null")(guest2.device_fingerprint)(undefined);
  TestValidator.equals("consent_status matches")(guest2.consent_status)(minimalPayload.consent_status);

  // 3. Privacy policy: missing consent_status triggers runtime error
  await TestValidator.error("missing consent_status throws error")(() =>
    api.functional.polEcoBoard.guests.create(connection, {
      body: {
        ip_address: typia.random<string>()
      } as any // Only for this negative runtime case
    })
  );

  // 4. Repeat calls with same IP/device
  const repeatPayload: IPolEcoBoardGuest.ICreate = {
    ip_address: "203.0.113.42",
    device_fingerprint: "deviceXYZ2025",
    consent_status: "agreed_v2025"
  };
  const g1: IPolEcoBoardGuest = await api.functional.polEcoBoard.guests.create(connection, { body: repeatPayload });
  typia.assert(g1);
  const g2: IPolEcoBoardGuest = await api.functional.polEcoBoard.guests.create(connection, { body: repeatPayload });
  typia.assert(g2);
  TestValidator.notEquals("repeat calls give unique session ids")(g1.id)(g2.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";

/**
 * Validate failure handling for guest session creation with invalid input.
 *
 * This test ensures that attempts to create a polEcoBoard guest session with input that violates validation rules (such as an improperly formatted IP address or a missing consent status) are properly rejected by the API. The endpoint should return actionable error messages and no guest session should be created in these cases.
 *
 * Steps:
 * 1. Attempt to create a guest session with an invalidly formatted IP address (e.g., 'not-an-ip'). Expect error.
 * 2. Attempt to create a guest session with consent_status missing from payload. Expect error.
 *
 * This protects against accepting invalid or incomplete privacy information and ensures back-end integrity for guest analytics and legal compliance.
 */
export async function test_api_guest_session_creation_invalid_input_failure(connection: api.IConnection) {
  // 1. Attempt with invalid IP address (non-IP string)
  await TestValidator.error("invalid IP address should fail")(async () => {
    await api.functional.polEcoBoard.guests.create(connection, {
      body: {
        ip_address: "not-an-ip",
        device_fingerprint: null,
        consent_status: "v1"
      } satisfies IPolEcoBoardGuest.ICreate
    });
  });

  // 2. Attempt with missing consent_status.
  // As TypeScript requires the field, we simulate a missing/invalid consent by passing an empty string.
  await TestValidator.error("missing consent_status should fail")(async () => {
    await api.functional.polEcoBoard.guests.create(connection, {
      body: {
        ip_address: "192.168.1.100",
        device_fingerprint: null,
        consent_status: ""
      } satisfies IPolEcoBoardGuest.ICreate
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
