/**
 * Validate successful update of an anti-spam event by an admin.
 *
 * This test covers the end-to-end admin moderation cycle:
 * - Register a new admin
 * - Authenticate as that admin
 * - Create an anti-spam event for test purposes
 * - Update the event using the update API, changing multiple business fields
 * - Assert that the returned record matches the update and preserves audit/invariant fields
 *
 * 1. Register an admin account
 * 2. Log in as the admin (auth is set in connection)
 * 3. Create an anti-spam event, get id from response
 * 4. Update multiple updatable fields via the update endpoint
 * 5. Validate that all business logic and audit invariants hold, including id persistence
 */
export async function test_api_anti_spam_event_update_success(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Admin login (Authorization header is set by SDK)
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 3. Create anti-spam event
  const antiSpamEventInput: IPolEcoBoardAntiSpamEvent.ICreate = {
    provider_key: "akismet",
    operation: "content_submit",
    content_hash: RandomGenerator.alphaNumeric(16),
    score: 0.4,
    action_taken: "approved",
    appeal_requested: false,
    created_at: new Date().toISOString(),
  };
  const createdEvent = await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, {
    body: antiSpamEventInput,
  });
  typia.assert(createdEvent);
  TestValidator.equals("provider_key at creation")(createdEvent.provider_key)(antiSpamEventInput.provider_key);
  TestValidator.equals("appeal requested at creation")(createdEvent.appeal_requested)(false);

  // 4. Update event: change operation and score, toggle appeal status
  const updateInput: IPolEcoBoardAntiSpamEvent.IUpdate = {
    operation: "appeal",
    score: createdEvent.score + 0.25,
    action_taken: "escalated",
    appeal_requested: true,
  };
  const updatedEvent = await api.functional.polEcoBoard.admin.antiSpamEvents.update(connection, {
    antiSpamEventId: createdEvent.id,
    body: updateInput,
  });
  typia.assert(updatedEvent);

  // 5. Validate updates & field invariants
  TestValidator.equals("score updated")(updatedEvent.score)(updateInput.score);
  TestValidator.equals("operation updated")(updatedEvent.operation)(updateInput.operation);
  TestValidator.equals("appeal requested updated")(updatedEvent.appeal_requested)(true);
  TestValidator.equals("action_taken updated")(updatedEvent.action_taken)(updateInput.action_taken);
  TestValidator.equals("id invariant")(updatedEvent.id)(createdEvent.id);
  TestValidator.equals("content_hash invariant")(updatedEvent.content_hash)(createdEvent.content_hash);
  TestValidator.equals("provider_key invariant")(updatedEvent.provider_key)(createdEvent.provider_key);
}

