  // 3c. Missing consent_type
  TestValidator.error("missing consent_type")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        // consent_type missing
        consent_status: "opt_in",
        session_anon_id: RandomGenerator.alphaNumeric(10),
        audit_trail: "Test audit",
      } as any // forcibly missing
    })
  );

  // 3d. Invalid consent_status value
  TestValidator.error("invalid consent_status")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        consent_type: "analytics",
