  // 3e. Completely empty request body
  TestValidator.error("empty request body")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {} as any
    })
  );

  // 3f. Malformed session_anon_id (empty string)
  TestValidator.error("empty session_anon_id")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        consent_type: "analytics",
        consent_status: "opt_in",
        session_anon_id: "",
        audit_trail: "Test audit",
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    })
  );

  // 3g. Malformed audit_trail (empty string)
  TestValidator.error("empty audit_trail")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        consent_type: "analytics",
        consent_status: "opt_in",
        session_anon_id: RandomGenerator.alphaNumeric(10),
        audit_trail: "",
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    })
