import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardModeratorSignOut } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorSignOut";

/**
 * E2E test for moderator logout and session invalidation.
 *
 * This test verifies the full logout flow for a moderator user. It ensures that upon logout, the moderator’s session token is effectively revoked so that further access to protected moderator APIs is denied. It confirms both the success of the logout operation and the idempotency of subsequent logout attempts, also checking that use of a revoked token results in access denial.
 *
 * Test workflow:
 * 1. Register a new moderator account.
 * 2. Log in as the new moderator and save the JWT from the response.
 * 3. Access a protected API with the valid token to confirm authentication is effective.
 * 4. Call logout with the token and check for success.
 * 5. Attempt another call to the protected API with the now-invalid token; confirm it is rejected (session revoked).
 * 6. Attempt to logout again with the same token; verify idempotency and a properly handled error response.
 */
export async function test_api_moderator_logout_session_invalidation(connection: api.IConnection) {
  // 1. Register new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "P@ssword1!";
  const moderatorName = RandomGenerator.name();
  const consentStatus = "v1.0";

  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorName,
      consent_status: consentStatus
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(registration);
  TestValidator.equals("moderator email matches")(registration.email)(moderatorEmail);
  TestValidator.equals("moderator display name matches")(registration.display_name)(moderatorName);
  TestValidator.predicate("registration setHeaders includes Authorization")(
    typeof registration.setHeaders?.Authorization === "string"
  );

  // 2. Log in as moderator
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(login);
  TestValidator.equals("login email matches")(login.email)(moderatorEmail);
  TestValidator.predicate("login setHeaders includes Authorization")(
    typeof login.setHeaders?.Authorization === "string"
  );

  // Save JWT
  const jwt = login.setHeaders.Authorization;
  const authedConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: jwt
    }
  };

  // 3. Access a protected endpoint to confirm token is valid (logout works)
  const preLogoutTest = await api.functional.auth.moderator.logout.signOut(authedConnection);
  typia.assert(preLogoutTest);
  TestValidator.equals("logout success pre")(preLogoutTest.success)(true);

  // 4. Attempt again to logout with now-revoked token
  const secondLogout = await api.functional.auth.moderator.logout.signOut(authedConnection);
  typia.assert(secondLogout);
  TestValidator.equals("logout idempotency")(secondLogout.success)(false);

  // 5. Attempt another protected call (should fail)
  await TestValidator.error("re-using revoked JWT should fail access")(async () => {
    await api.functional.auth.moderator.logout.signOut(authedConnection);
  });

  // 6. Log in again to confirm valid session can be created after a clean logout
  const loginAgain = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(loginAgain);
  const jwt2 = loginAgain.setHeaders.Authorization;
  const reAuthedConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: jwt2
    }
  };

  // Clean logout again
  const finalLogout = await api.functional.auth.moderator.logout.signOut(reAuthedConnection);
  typia.assert(finalLogout);
  TestValidator.equals("final logout success")(finalLogout.success)(true);
}

