/**
 * Validate moderator JWT token acceptance and error cases.
 *
 * This test validates both the acceptance of valid JWT tokens and correct
 * handling of malformed/invalid/revoked token scenarios for moderators.
 *
 * Step-by-step process:
 * 1. Register a new moderator, acquiring a fresh JWT.
 * 2. Validate the issued token from registration; expect acceptance and correct decoded identity.
 * 3. Log in with the same credentials, receive a new JWT.
 * 4. Validate the token from login; ensure identical identity and valid context.
 * 5. Attempt validation with a clearly malformed non-JWT string; must be rejected.
 * 6. Attempt validation with an empty string token; must be rejected.
 * 7. Attempt validation with a syntactically valid but inauthentic/garbage JWT token; must be rejected and not expose sensitive fields.
 * All cases are asserted for both technical acceptance and business logic guarantees.
 */
export async function test_api_moderator_token_validation_valid_and_invalid_tokens(connection: api.IConnection) {
  // 1. Register a new moderator, acquire JWT
  const registrationInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPa55w0rd??!",
    display_name: RandomGenerator.name(),
    consent_status: "latest_terms_v1",
  } satisfies IPolEcoBoardModeratorRegistration.ICreate;
  const registrationResp = await api.functional.auth.moderator.register.signUp(connection, { body: registrationInput });
  typia.assert(registrationResp);
  const regJwt = registrationResp.setHeaders.Authorization.replace(/^Bearer /, "");
  const moderatorId = registrationResp.moderatorId;

  // 2. Validate registration JWT
  const validCheck = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: regJwt } });
  typia.assert(validCheck);
  TestValidator.predicate("token valid after registration")(validCheck.isValid === true);
  TestValidator.equals("moderatorId matches after reg")(validCheck.moderatorId)(moderatorId);
  TestValidator.equals("role == moderator")(validCheck.role)("moderator");
  TestValidator.equals("email matches")(validCheck.email)(registrationInput.email);

  // 3. Login as this moderator, get new JWT
  const loginInput = {
    email: registrationInput.email,
    password: registrationInput.password,
  } satisfies IPolEcoBoardModeratorAuthentication.ICreate;
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, { body: loginInput });
  typia.assert(loginResp);
  const loginJwt = loginResp.setHeaders.Authorization.replace(/^Bearer /, "");
  TestValidator.equals("login moderatorId matches reg")(loginResp.moderatorId)(moderatorId);

  // 4. Validate login JWT
  const loginValidCheck = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: loginJwt } });
  typia.assert(loginValidCheck);
  TestValidator.predicate("token valid after login")(loginValidCheck.isValid === true);
  TestValidator.equals("moderatorId matches after login")(loginValidCheck.moderatorId)(moderatorId);
  TestValidator.equals("role == moderator")(loginValidCheck.role)("moderator");
  TestValidator.equals("email matches after login")(loginValidCheck.email)(registrationInput.email);

  // 5. Clearly malformed non-JWT token
  const malformedTokenResp = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: "NOT.A.JWT" } });
  typia.assert(malformedTokenResp);
  TestValidator.predicate("malformed token rejected")(malformedTokenResp.isValid === false);

  // 6. Empty string token
  const emptyTokenResp = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: "" } });
  typia.assert(emptyTokenResp);
  TestValidator.predicate("empty token rejected")(emptyTokenResp.isValid === false);

  // 7. Syntactically correct but fabricated JWT
  const fakeJwt = [
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9",
    "eyJ1c2VyIjoibm9uZSIsImV4cCI6MTYyMDAwMDAwMH0",
    "NOTASIGNATURE"
  ].join(".");
  const fakeTokenResp = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: fakeJwt } });
  typia.assert(fakeTokenResp);
  TestValidator.predicate("fake/junk JWT rejected")(fakeTokenResp.isValid === false);
  TestValidator.predicate("invalid token should not expose moderatorId")(!fakeTokenResp.moderatorId);
  TestValidator.predicate("invalid token should not expose memberId")(!fakeTokenResp.memberId);
  TestValidator.predicate("invalid token should not expose email")(!fakeTokenResp.email);
}

