import type { IMemberAuthenticationMemberRefreshTokenResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberRefreshTokenResult";

/**
 * Validate member authentication refresh token issuance and expiry logic.
 *
 * This test ensures that a refresh token can successfully obtain new JWT tokens, and that revoked or expired tokens are properly invalidated.
 *
 * Step-by-step process:
 * 1. Register a new member (to ensure a unique account for each test run).
 * 2. Log in with the new member credentials to obtain initial access and refresh tokens.
 * 3. Use the issued refresh token with the refresh API to acquire new tokens, verifying issuance.
 * 4. Log out to revoke the session (refresh token).
 * 5. Attempt to refresh tokens again using the (now revoked) old refresh token, validating that it fails with an error (session revoked/invalid token).
 *
 * All success responses are validated for correct structure, type and value using typia assertions and TestValidator. All error scenarios focus on runtime business logic failures—not on compilation/type failures.
 */
export async function test_api_member_refresh_token_issuance_success_and_expiry(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);
  TestValidator.predicate("signUp returns setHeaders.Authorization")(typeof signUpResult.setHeaders?.Authorization === "string");

  // 2. Log in as the new member to issue tokens
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);
  TestValidator.predicate("signIn returns setHeaders.Authorization")(typeof signInResult.setHeaders?.Authorization === "string");

  // 3. Use refresh API to get a new access/refresh token pair
  // First successful refresh
  const refreshResult1 = await api.functional.auth.member.refresh.refreshToken(connection, {
    body: {
      refreshToken: signInResult.setHeaders.Authorization,
    } satisfies IMemberAuthenticationMemberRefreshToken,
  });
  typia.assert(refreshResult1);
  TestValidator.equals("tokenType is Bearer")(refreshResult1.tokenType)("Bearer");
  TestValidator.predicate("refreshResult1 provides new access/refresh tokens")(
    typeof refreshResult1.accessToken === "string" && typeof refreshResult1.refreshToken === "string"
  );
  const refreshToken = refreshResult1.refreshToken;

  // 4. Log out (revoke session)
  const signOutResult = await api.functional.auth.member.logout.signOut(connection);
  typia.assert(signOutResult);

  // 5. Attempt to use revoked refresh token (should fail)
  await TestValidator.error("revoked/invalid refresh should not work")(async () => {
    await api.functional.auth.member.refresh.refreshToken(connection, {
      body: {
        refreshToken,
      } satisfies IMemberAuthenticationMemberRefreshToken,
    });
  });
}

