/**
 * E2E Test for successful and unsuccessful external authentication provider creation by admin
 *
 * This test covers:
 * 1. Admin registration and login (dependencies for privileged actions)
 * 2. Successful creation of an external authentication provider with all required fields.
 * 3. Validation that response contains all details: UUID, timestamps, and business fields.
 * 4. Duplication error check (provider_key and provider_name must be unique):
 *    - Attempt to create with the same provider_key or provider_name and expect error.
 * 5. Field validation edge-cases:
 *    - Provide an invalid status value (not one of 'enabled', 'disabled', 'maintenance') and confirm validation error.
 *    - Provide a malformed privacy_policy_uri (not a valid URI) and confirm validation error.
 * 6. Access control: Attempt creating a provider WHEN NOT authenticated as admin and confirm access denied.
 *
 * Process:
 * - Register and login as admin.
 * - Create an external auth provider successfully (fields: provider_name, provider_key, status, privacy_policy_uri, data_residency_region, consent_required).
 * - Assert all returned details available (incl. id, timestamps, fields, etc).
 * - Try to create another with duplicate provider_key or provider_name.
 * - Try to create with invalid status value.
 * - Try to create with malformed URI.
 * - Logout or reset auth; try to create with no/admin token and expect failure.
 */
export async function test_api_external_auth_provider_admin_create_success_and_duplicate_key(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: password,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: password,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Successful provider creation
  const input = {
    provider_name: "TestProvider" + RandomGenerator.alphaNumeric(5),
    provider_key: "test_provider_key_" + RandomGenerator.alphaNumeric(5),
    status: "enabled",
    privacy_policy_uri: "https://privacypolicy." + RandomGenerator.alphaNumeric(8) + ".com/pp.html",
    data_residency_region: "US",
    consent_required: true,
  } satisfies IPolEcoBoardExternalAuthProvider.ICreate;
  const created = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, { body: input });
  typia.assert(created);
  TestValidator.equals("provider_name matches")(created.provider_name)(input.provider_name);
  TestValidator.equals("provider_key matches")(created.provider_key)(input.provider_key);
  TestValidator.equals("status matches")(created.status)(input.status);
  TestValidator.equals("privacy_policy_uri matches")(created.privacy_policy_uri)(input.privacy_policy_uri);
  TestValidator.equals("region matches")(created.data_residency_region)(input.data_residency_region);
  TestValidator.equals("consent_required matches")(created.consent_required)(input.consent_required);
  TestValidator.predicate("id is UUID")(typeof created.id === "string" && created.id.length > 0);
  TestValidator.predicate("created_at date")(typeof created.created_at === "string");
  TestValidator.predicate("updated_at date")(typeof created.updated_at === "string");

  // 4. Duplicate provider_key
  await TestValidator.error("duplicate provider_key")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        ...input,
        provider_name: input.provider_name + "_dup",
      } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
    });
  });
  // 5. Duplicate provider_name
  await TestValidator.error("duplicate provider_name")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        ...input,
        provider_key: input.provider_key + "_dup",
      } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
    });
  });
  // 6. Invalid status value
  await TestValidator.error("invalid status value")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        ...input,
        status: "invalid_status",
        provider_key: input.provider_key + "_invalidstatus",
        provider_name: input.provider_name + "_invalidstatus",
      } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
    });
