/**
 * Test the registration process for a new member on the PolEcoBoard and enforce email uniqueness validation.
 *
 * This function validates:
 *   - Successful registration of a new member with a valid email, password hash, display name, and consent status.
 *   - The created member's 'is_active' is true.
 *   - Sensitive fields like password hash are never returned in the response.
 *   - Enforced uniqueness of the email field.
 *   - Clear error handling when attempting to register a second member with the same email address.
 *
 * Steps:
 * 1. Register a new member with valid and unique properties.
 * 2. Validate the presence and type of the returned member (no password hash, is_active true).
 * 3. Attempt registration with the same email and different display name, consent status, and password hash.
 * 4. Validate that a duplicate email error occurs (error is thrown).
 */
export async function test_api_member_registration_success_and_duplicate_email_error(connection: api.IConnection) {
  // 1. Prepare random but valid user attributes
  const email: string = typia.random<string & tags.Format<"email">>();
  const displayName: string = RandomGenerator.alphaNumeric(12);
  const consentStatus: string = RandomGenerator.alphaNumeric(8);
  const passwordHash: string = RandomGenerator.alphaNumeric(60); // bcrypt-like hash string (fixed 60 chars)

  // 2. Register member with these unique credentials
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: email,
      password_hash: passwordHash,
      display_name: displayName,
      consent_status: consentStatus,
      // profile_image_uri is optional and omitted deliberately
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 3. Validate core response attributes and policy
  TestValidator.equals("email matches")(member.email)(email);
  TestValidator.equals("display name matches")(member.display_name)(displayName);
  TestValidator.equals("consent status matches")(member.consent_status)(consentStatus);
  TestValidator.equals("is_active is true")(member.is_active)(true);
  // Ensure password_hash is NOT present in API response
  if ((member as any).password_hash !== undefined)
    throw new Error("Password hash must not be included in member API response");

  // 4. Attempt to register another member with the same email (should fail)
  await TestValidator.error("duplicate email registration triggers error")(() =>
    api.functional.polEcoBoard.members.create(connection, {
      body: {
        email: email, // duplicate
        password_hash: RandomGenerator.alphaNumeric(60),
        display_name: RandomGenerator.alphaNumeric(12),
        consent_status: RandomGenerator.alphaNumeric(8),
      } satisfies IPolEcoBoardMember.ICreate,
    })
  );
}

