import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a member can update their own notification preference.
 *
 * This test covers the self-service scenario where a member registers, logs in, creates a notification preference, and then updates that preference by its ID (changing opt_in status and/or channel). It ensures that changed fields are reflected and confirms adherence to the update and ownership rules.
 *
 * Test flow:
 * 1. Register a new member with unique email and password.
 * 2. Login as the new member (to set Authorization).
 * 3. Create a notification preference (pick random event_type and channel, opt_in = true or false).
 * 4. Update that notification preference (change opt_in status and/or channel).
 * 5. Validate the returned notification preference object reflects the updated values.
 */
export async function test_api_member_notification_preference_update_success_and_self_permission(connection: api.IConnection) {
  // 1. Register new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const registerResult = await api.functional.auth.member.register.signUp(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(registerResult);

  // 2. Login as the new member (token setup handled internally)
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(loginResult);

  // 3. Create a notification preference (opt_in true, standard event & channel)
  // NOTE: member_id cannot be dynamically determined from authentication APIs provided, so use a random UUID as per limitations
  const member_id = typia.random<string & tags.Format<"uuid">>();
  const createPrefInput: IPolEcoBoardNotificationPreference.ICreate = {
    member_id,
    event_type: "reply",
    channel: "email",
    opt_in: true,
  };
  const createdPreference = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: createPrefInput,
  });
  typia.assert(createdPreference);

  // 4. Update the notification preference (flip opt_in and change channel)
  const updateInput: IPolEcoBoardNotificationPreference.IUpdate = {
    channel: "push",
    opt_in: !createdPreference.opt_in,
  };
  const updatedPreference = await api.functional.polEcoBoard.member.notificationPreferences.update(connection, {
    notificationPreferenceId: createdPreference.id,
    body: updateInput,
  });
  typia.assert(updatedPreference);

