 *
 * This tests the following real-world workflow:
 * 1. Register a new admin account to obtain admin privileges and an active session
 * 2. Create a new notification provider using the admin credentials, recording its UUID
 * 3. Use the PUT endpoint to update several mutable fields on the provider
 * 4. Validate that the response reflects these updates and that immutable fields (like provider_key) remain unchanged
 *
 * This ensures that the business logic for notification provider configuration is robust and conforms to the API contract — covering privilege, mutability, and integrity guarantees.
 */
export async function test_api_notification_provider_update_successful_update(connection: api.IConnection) {
  // 1. Register a new admin account
