    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminSignUpResponse);

  // 2. Create a new notification provider as the admin
  const providerCreateInput: IPolEcoBoardNotificationProvider.ICreate = {
    provider_name: "Initial Provider Name",
    provider_key: RandomGenerator.alphabets(8),
    channels_supported: "email,sms",
