 *   1. Register an admin user, then login to obtain credentials
 *   2. Admin creates a new board category (for subsequent board creation)
 *   3. Admin creates a board assigned to the new category
 *   4. Register a moderator, then login as moderator
 *   5. Admin assigns this moderator to the created board
 *   6. Moderator creates a board history event for the given board
 *   7. Moderator performs DELETE for that board history event
 *   8. (Verification that deleted_at is set requires a query/read API, which is not available with current SDK functions)
 *
 * Each step is implemented using only permitted API endpoints and DTOs; all role/context switching is handled by logging in as the relevant user. Business logic and permission sequencing is strictly followed.
 *
 * NOTE: The test cannot verify the actual state of deleted_at or perform negative queries due to lack of corresponding read/query endpoints in provided SDK functions. As required, such scenario steps are omitted.
 */
export async function test_api_board_history_moderator_soft_delete_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 3. Admin creates a new category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 4. Admin creates a new board in the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
