  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

  // 7. Re-login as admin to perform board assignment
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 8. Admin assigns the moderator to the board
  const assignment = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.create(connection, {
    body: {
      pol_eco_board_moderator_id: moderatorReg.moderatorId,
      pol_eco_board_board_id: board.id,
      assigned_at: new Date().toISOString()
    } satisfies IPolEcoBoardModeratorBoardAssignment.ICreate
  });
  typia.assert(assignment);

  // 9. Moderator login again to perform board history actions
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

