/**
 * Validate that a moderator can search for their assigned boards using filters and pagination.
 *
 * Business context:
 * Moderators must be able to see their current board assignments using dashboard search, filtered by moderator, board, and status, with support for paging. Admin is responsible for setup.
 *
 * Steps:
 * 1. Register a moderator (unique email, password, display name, consent status)
 * 2. Login as moderator to acquire identity and JWT
 * 3. Register an admin (unique email, password)
 * 4. Login as admin to create board/category and perform assignment
 * 5. Create a category (admin)
 * 6. Create a board in the category (admin)
 * 7. Assign the moderator to the board (admin)
 * 8. Login as moderator to perform moderator-board assignment search with all filters:
 *    - moderatorId (self)
 *    - boardId
 *    - status
 *    - Pagination controls (page/pageSize)
 *    Verify: matching assignment is returned, details correct
 * 9. Search with status="ended" (should yield zero results)
 * 10. Search with non-matching moderator and board IDs (should yield zero results)
 * 11. Search with pageSize=1 to verify pagination enforcement
 */
export async function test_api_moderator_board_assignment_search_filter_pagination(connection: api.IConnection) {
  // 1. Register a unique moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "modPassword123";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "v1-accepted";
  const moderatorRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRes);
  const moderatorId = moderatorRes.moderatorId;

  // 2. Login as moderator
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);

  // 3. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassw0rd!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 4. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 5. Create a category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(1),
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 6. Create a board in the category
  const boardName = RandomGenerator.paragraph()(1);
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardName,
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 7. Assign moderator to the board
  const assignment = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.create(connection, {
    body: {
      pol_eco_board_moderator_id: moderatorId,
      pol_eco_board_board_id: board.id,
      assigned_by_admin_id: null,
      assigned_at: new Date().toISOString(),
      ended_at: null,
      role_transfer_log: "test-assignment",
    } satisfies IPolEcoBoardModeratorBoardAssignment.ICreate,
  });
  typia.assert(assignment);

  // 8. Login as moderator and search using all filters
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  const pageRequest = { page: 1, pageSize: 10 } satisfies IPage.IRequest;
  const searchRes = await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.search(connection, {
    body: {
      pagination: pageRequest,
      pol_eco_board_moderator_id: moderatorId,
      pol_eco_board_board_id: board.id,
      status: "active",
    } satisfies IPolEcoBoardModeratorBoardAssignment.IRequest,
  });
  typia.assert(searchRes);
  TestValidator.predicate("at least one assignment found")(searchRes.data.length >= 1);
  TestValidator.equals("matched assignment id")(searchRes.data[0].id)(assignment.id);
  TestValidator.equals("matched moderator id")(searchRes.data[0].pol_eco_board_moderator_id)(moderatorId);
  TestValidator.equals("matched board id")(searchRes.data[0].pol_eco_board_board_id)(board.id);

  // 9. Search for status "ended" should yield zero results
  const endedSearch = await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.search(connection, {
    body: {
      pagination: pageRequest,
      pol_eco_board_moderator_id: moderatorId,
      status: "ended",
    } satisfies IPolEcoBoardModeratorBoardAssignment.IRequest,
  });
  typia.assert(endedSearch);
  TestValidator.equals("no ended assignments")(endedSearch.data.length)(0);

  // 10. Search with non-matching moderator and board ids
  const nonMatchSearch = await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.search(connection, {
    body: {
      pagination: pageRequest,
      pol_eco_board_moderator_id: typia.random<string & tags.Format<"uuid">>(),
      pol_eco_board_board_id: typia.random<string & tags.Format<"uuid">>(),
      status: "active",
    } satisfies IPolEcoBoardModeratorBoardAssignment.IRequest,
  });
  typia.assert(nonMatchSearch);
  TestValidator.equals("no assignment for invalid ids")(nonMatchSearch.data.length)(0);

  // 11. Pagination: pageSize=1
  const singlePage = await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 1 },
      pol_eco_board_moderator_id: moderatorId,
      status: "active",
    } satisfies IPolEcoBoardModeratorBoardAssignment.IRequest,
  });
  typia.assert(singlePage);
  TestValidator.equals("page size enforced")(singlePage.pagination.limit)(1);
}

