/**
 * Validate that a moderator can retrieve their own moderator-board assignment by ID,
 * including correct authorization, error handling for non-existent/unauthorized
 * assignments, and setup via full business workflow.
 *
 * This test ensures both the normal and boundary-case behavior for the endpoint,
 * validating that moderator-board assignments are retrievable only for authorized
 * moderators and that error/forbidden is returned for invalid IDs or unauthorized attempts.
 *
 * Step-by-step process:
 * 1. Register a moderator, saving their moderatorId and credential details.
 * 2. Register and login an admin.
 * 3. Admin creates a new board category.
 * 4. Admin creates a new board in the created category.
 * 5. Admin creates a moderator-board assignment for the moderator and board (save assignmentId).
 * 6. Moderator logs in (get JWT via setHeaders.Authorization).
 * 7. Moderator fetches their moderator-board assignment by ID -> verify full record is returned and matches the assignmentId.
 * 8. Fetch a random/non-existent assignmentId as moderator -> confirm error (TestValidator.error / forbidden or not found).
 * 9. Register a second moderator and ensure they cannot fetch the first moderator's assignment.
 */
export async function test_api_moderator_board_assignment_get_success_invalid_forbidden(
  connection: api.IConnection,
) {
  // 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "StrongPass123!";
  const moderatorSignup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1",
    },
  });
