 * 1. Register two different members (one will author a post, the other will report it).
 * 2. Login as the post author, create a valid post in any category.
 * 3. Login as the reporter member (not the post author).
 * 4. Submit a report for the post as the reporter. Use a valid reason code and description.
 * 5. Verify the report was created: response contains expected properties, linked to the correct post and reporter.
 * 6. Attempt to submit another report for the same post by the same member; verify that a duplicate error is thrown.
 *
 * Edge cases covered:
 * - Ensuring only authenticated members can report (by only authenticating).
 * - De-duplication (a member cannot submit two reports for one post).
 */
export async function test_api_member_post_report_submission_success_and_duplicate_prevention(connection: api.IConnection) {
