    body: {
      email: reporterEmail,
      password: reporterPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 2. Login as author and create a post
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: authorEmail,
      password: authorPassword,
    },
  });
  const createPostInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Test post for report scenario - " + Date.now(),
    body: "Content of the post to be reported. " + Date.now(),
    attachments: null,
    tag_ids: null,
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: createPostInput,
  });
  typia.assert(post);

  // 3. Login as reporter member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: reporterEmail,
      password: reporterPassword,
    },
  });

  // 4. Submit a report for the post
  const reportRequest: IPolEcoBoardReport.ICreate = {
    reason_code: "abuse",
    reason_description: "Inappropriate content.",
    post_id: post.id,
    comment_id: null,
  };
  const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: post.id,
    body: reportRequest,
  });
  typia.assert(report);
  TestValidator.equals("report linked post ID")(report.post_id)(post.id);
  TestValidator.equals("report reason code")(report.reason_code)(reportRequest.reason_code);
  TestValidator.equals("report description")(report.reason_description)(reportRequest.reason_description);

  // 5. Attempt to submit another report for the same post by the same member
  await TestValidator.error("duplicate report prevented")(async () => {
    await api.functional.polEcoBoard.member.posts.reports.create(connection, {
      postId: post.id,
      body: reportRequest,
    });
  });
}

