import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";

/**
 * Validate failure cases for post reporting: ensure unauthenticated users cannot submit reports and
 * schema or business validation is enforced for report reason codes/descriptions.
 *
 * This test covers two failure branches for post report submissions:
 * 1. Guest (unauthenticated) users must not be able to report posts. Upon attempting a report submission
 *    with no authentication, a 401 (or 403) error must be thrown.
 * 2. When authenticated, attempts to report a post with invalid inputs — such as missing or invalid reason_code,
 *    or empty/too-long reason_description — should be rejected with validation errors by the API.
 *
 * Business context:
 * - Only members may report posts; moderation relies on strict input schemas for reports.
 * - Reason codes must match allowed values; blank or garbage should be rejected. Descriptions that are excessively long
 *   or missing as required must trigger errors.
 *
 * Workflow:
 * 1. Create a member post through the normal endpoint (setup prerequisite, must be authenticated).
 * 2. Attempt to report that post (using the new post ID) as an unauthenticated user and validate error behavior.
 * 3. Authenticate (become a valid member user).
 * 4. Attempt to submit a report with missing reason_code: expect schema error.
 * 5. Attempt with an obviously invalid reason_code (e.g. 'invalid_code'): expect validation error.
 * 6. Attempt with a too-long reason_description: expect validation error.
 * 7. Optionally, attempt valid report (should succeed for completeness, but main focus is on validation failures).
 */
export async function test_api_member_post_report_submission_unauthenticated_and_validation(
  connection: api.IConnection,
) {
  // 1. Create a member post (authentication required)
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.alphaNumeric(16),
    body: RandomGenerator.paragraph()(15),
    tag_ids: null,
    attachments: null,
  };
  // Create post as authenticated member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);
  // Post ID for reporting
  const postId = post.id;

  // 2. Attempt post report as unauthenticated user (simulate by clearing auth header)
  //    Should throw 401/403
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers["Authorization"];
  TestValidator.error("guest should not submit report")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(unauthConnection, {
        postId,
        body: {
          reason_code: "spam", // Assume 'spam' is valid but won't test validity here
          reason_description: "Reported as spam.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 3. Re-authenticate as member (not needed if prior login is preserved)

  // 4. Attempt report missing reason_code (schema error: code required)
  TestValidator.error("missing reason_code triggers schema error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          // Intentionally empty string to trigger server validation error
          reason_code: "", 
          reason_description: "Insufficient code.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 5. Attempt report with invalid reason_code
  TestValidator.error("invalid reason_code triggers business validation error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          reason_code: "invalid_code", // Not an approved business value
          reason_description: "Purposefully invalid reason code.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 6. Attempt report with too-long reason_description
  TestValidator.error("reason_description > 400 chars triggers validation error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          reason_code: "spam", // Use plausible good value
          reason_description: RandomGenerator.alphaNumeric(500), // Exceed 400-char limit
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 7. (Optional) Submit valid report (should succeed; for full coverage)
  const validReport = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId,
    body: {
      reason_code: "spam", // Use plausible valid value
      reason_description: "Obvious spam post, violating forum guidelines.",
      post_id: postId,
      comment_id: null,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(validReport);
  TestValidator.equals("report post_id matches")(validReport.post_id)(postId);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate error handling for moderator report submission under invalid conditions (self-reporting, missing required fields).
 *
 * This test covers two core business rule validations:
 * 1. Moderators are not permitted to report their own posts (self-report). Submission should return a business rule error.
 * 2. Submitting a report with missing required fields (e.g., without reason_code) must fail with validation errors, not create a report.
 *
 * Workflow:
 * 1. Register a moderator account (used for all actions - auth and post ownership).
 * 2. Login as the moderator and create a new post.
 * 3. Attempt to submit a report on that post as the same moderator. Expect a rejection due to self-reporting prohibition.
 * 4. Attempt to submit a report with missing required 'reason_code'. Expect a validation error.
 * 5. (Edge case) Attempt to submit with empty reason_code or both post_id and comment_id missing/null if allowed by DTO, otherwise skip.
 *
 * Each error scenario should be caught using TestValidator.error() and must not result in successful report creation.
 */
export async function test_api_moderator_post_report_submission_invalid_conditions(
  connection: api.IConnection,
) {
  // 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Test1234!";
  const moderatorDisplay = RandomGenerator.name();
  const moderatorConsent = "v1-terms";
  const registerRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplay,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registerRes);

  // 2. Login as moderator (token auto-injected for subsequent requests)
  const loginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginRes);

  // 3. Create a new post as this moderator
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postInput = {
    category_id: categoryId,
    title: "Moderator Self Post - For Invalid Report Test",
    body: "This post will be used to test invalid moderator report scenarios.",
  } satisfies IPolEcoBoardPost.ICreate;
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(createdPost);

  // 4. Attempt to report own post as moderator - should error (self-report not allowed)
  await TestValidator.error("self-reporting should fail")(async () => {
    await api.functional.polEcoBoard.moderator.posts.reports.create(connection, {
      postId: createdPost.id,
      body: {
        reason_code: "abuse",
        reason_description: "Testing self-report prohibition.",
        post_id: createdPost.id,
      } satisfies IPolEcoBoardReport.ICreate,
    });
  });

  // 5. Attempt to report with missing required field 'reason_code' - should error (validation error)
  await TestValidator.error("missing reason_code should fail")(async () => {
    // Intentionally omit reason_code (force runtime error only, not compile error)
    await api.functional.polEcoBoard.moderator.posts.reports.create(connection, {
      postId: createdPost.id,
      body: {
        // reason_code omitted
        post_id: createdPost.id,
      } as unknown as IPolEcoBoardReport.ICreate,
    });
  });

  // 6. Attempt to submit with empty reason_code string if allowed
  await TestValidator.error("empty reason_code should fail")(async () => {
    await api.functional.polEcoBoard.moderator.posts.reports.create(connection, {
      postId: createdPost.id,
      body: {
        reason_code: "",
        post_id: createdPost.id,
      } satisfies IPolEcoBoardReport.ICreate,
    });
  });

  // 7. If DTO allows, try missing post_id and comment_id both (should fail) - do only if allowed by schema/TS
  await TestValidator.error("missing post_id/comment_id should fail")(async () => {
    await api.functional.polEcoBoard.moderator.posts.reports.create(connection, {
      postId: createdPost.id,
      body: {
        reason_code: "abuse",
        // no post_id, no comment_id
      } as unknown as IPolEcoBoardReport.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the admin reporting flow for a polEcoBoard post and related error conditions.
 *
 * This test simulates a real admin workflow:
 * 1. Registers an admin account
 * 2. Logs in as the admin and saves credentials
 * 3. Registers a member account
 * 4. Logs in as the member, creates a board post
 * 5. Logs back in as admin
 * 6. Submits a report for the member's post using required fields
 * 7. Verifies the report object is correctly saved and matches input data
 * 8. Attempts to report the same post again as the same admin, expects failure due to duplicate prevention
 * 9. Attempts to report a non-existent post, expects business error
 */
export async function test_api_admin_post_report_submission_and_error_conditions(connection: api.IConnection) {
  // 1. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPwd123!";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignup);

  // 2. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "MemberPwd123!";
  const memberSignup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignup);

  // 4. Login as member and create a post
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // Actually create a post as the member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postCreateInput: IPolEcoBoardPost.ICreate = {
    category_id: categoryId,
    title: "Eco Policy Issue - air quality",
    body: "Discussion about air quality and latest policies. Is the air getting better in urban areas?",
  };
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postCreateInput,
  });
  typia.assert(createdPost);

  // 5. Login back as admin so we have privileges for reporting as admin
  const adminLogin2 = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin2);

  // 6. Admin submits a report for the member's post
  const reportInput: IPolEcoBoardReport.ICreate = {
    reason_code: "abuse",
    reason_description: "This post contains inappropriate content.",
    post_id: createdPost.id,
  };
  const report = await api.functional.polEcoBoard.admin.posts.reports.create(connection, {
    postId: createdPost.id,
    body: reportInput,
  });
  typia.assert(report);
  TestValidator.equals("reported post id")(report.post_id)(createdPost.id);
  TestValidator.equals("reason code")(report.reason_code)("abuse");
  TestValidator.equals("reason description")(report.reason_description)("This post contains inappropriate content.");
  TestValidator.predicate("report has id")(typeof report.id === "string" && report.id.length > 0);
  TestValidator.predicate("report created_at")(typeof report.created_at === "string" && report.created_at.length > 0);

  // 7. Attempt to submit a duplicate report for the same post as the same admin
  await TestValidator.error("duplicate report prevention")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.reports.create(connection, {
        postId: createdPost.id,
        body: reportInput,
      });
    },
  );

  // 8. Attempt to submit a report for a non-existent post
  await TestValidator.error("invalid post id check")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.reports.create(connection, {
        postId: typia.random<string & tags.Format<"uuid">>(),
        body: {
          reason_code: "abuse",
          reason_description: "Attempt on non-existent post.",
          post_id: typia.random<string & tags.Format<"uuid">>(),
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IPageIPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPostEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for an admin fetching the full edit/audit history of a post.
 *
 * Business context:
 * - Only admins (or authorized roles) may access revision audit trails.
 * - Verifies all business audit fields, edge cases (empty history), and authorization enforcement.
 *
 * Test steps:
 * 1. Register admin and acquire admin session.
 * 2. Register a member account and create a post as member.
 * 3. Generate multiple edits for the member's post (simulating a rich edit history).
 * 4. As admin, fetch full edit/audit history and verify returned data and pagination.
 * 5. Test all edit history business metadata fields.
 * 6. Test audit filtering (by editor) and sorting/pagination.
 * 7. Check result for post with no edits.
 * 8. Confirm that unauthenticated/faulty session is denied.
 */
export async function test_api_post_edit_history_admin_fetch(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: "v1"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 4. Login as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });

  // 5. Create post as member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(12);
  const postBody = RandomGenerator.content()()(36);
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Create several post edits
  const editSnapshots: IPolEcoBoardPostEdit[] = [];
  for (let i = 0; i < 4; ++i) {
    const edit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
      postId: post.id,
      body: {
        edit_body: RandomGenerator.content()()(36 + i * 5),
        edit_reason: `Revision #${i+1}`
      } satisfies IPolEcoBoardPostEdit.ICreate
    });
    typia.assert(edit);
    editSnapshots.push(edit);
  }

  // Switch back to admin session before admin APIs
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 7. Fetch edit history: happy path (all records, full audit fields)
  const page = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      page: 1,
      limit: 20
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(page);
  TestValidator.equals("edit count matches")(page.data.length)(editSnapshots.length);
  // Ensure all expected audit snapshot fields are present and valid
  TestValidator.predicate("edit audits valid")(page.data.every(edit => (
    typeof edit.id === "string" &&
    typeof edit.post_id === "string" &&
    typeof edit.editor_member_id === "string" &&
    typeof edit.edit_body === "string" &&
    typeof edit.created_at === "string"
  )));

  // 8. Filtering by editor_member_id
  const filtered = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      editor_member_id: member.id
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(filtered);
  TestValidator.equals("all filtered by member")(filtered.data.every(e => e.editor_member_id === member.id))(true);

  // 9. Sorting by created_at descending
  const sorted = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      order_by: "created_at",
      order_dir: "desc"
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(sorted);
  for(let j = 1; j < sorted.data.length; ++j) {
    TestValidator.predicate("sorted desc")(sorted.data[j-1].created_at >= sorted.data[j].created_at);
  }

  // 10. No edits: create a new post, fetch should return empty data
  const newPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()()(36)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(newPost);
  const empty = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: newPost.id,
    body: {} satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(empty);
  TestValidator.equals("empty edit history")(empty.data.length)(0);

  // 11. Unauthorized: fake admin token
  const fakeConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalid-token" } };
  await TestValidator.error("admin unauthorized access fails")(async () => {
    await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(fakeConn, {
      postId: post.id,
      body: {} satisfies IPolEcoBoardPostEdit.IRequest
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validates that a post author (member) can fetch the full detail of a post edit on their own post.
 *
 * This test covers the full member workflow for edit detail retrieval and validates all historical edit info and access control via author login.
 *
 * Steps:
 * 1. Register a new member to serve as the post author.
 * 2. Log in as that member and obtain a valid session.
 * 3. Create a new post – category_id is populated with a valid random UUID, as category fetch APIs are unavailable.
 * 4. Record an edit to the post, providing a new edit_body and edit_reason.
 * 5. Fetch the edit detail by its ID as the post author.
 * 6. Assert that the returned edit object contains correct and complete information:
 *    - editor_member_id matches the logged-in member
 *    - post_id matches the created post
 *    - edit_body and edit_reason match what was submitted
 *    - created_at is a non-empty ISO string
 *
 * Note: Negative tests for non-author (moderator/admin) permission are not possible here due to lack of such flows in the supplied API. This test covers only author access control.
 */
export async function test_api_post_edit_detail_member_access(connection: api.IConnection) {
  // 1. Register a new member as post author
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(16);
  const displayName = RandomGenerator.name();
  const consentStatus = "v1.0";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email,
      password_hash: password,
      display_name: displayName,
      consent_status: consentStatus,
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Log in as member (auth token made available in connection)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create a new post
