 * 2. Log in as Member A
 * 3. Create a post as Member A (capture postId)
 * 4. Register Member B with random credentials
 * 5. Log in as Member B
 * 6. Attempt to create a post edit for Member A's post as Member B (should fail with forbidden/perms error)
 */
export async function test_api_post_edit_create_member_forbidden_other_post(connection: api.IConnection) {
