 *
 * 1. Register and log in a new admin, verifying authentication.
 * 2. Create a valid maintenance window and verify correct creation (window_code uniqueness, start/end, expected_impact).
 * 3. Attempt to create an overlapping/conflicting window and confirm a validation or uniqueness error.
 * 4. Attempt to create a window with invalid time range (end_time < start_time) and check for error.
 * 5. Attempt creation with a non-admin/unauthenticated connection and verify access denied.
 *
 * Business context:
 * - Maintenance window creation is restricted to authenticated admin accounts only.
 * - window_code must be unique; window times should not overlap or be invalid.
 * - Authorization, schema, and business errors must be validated appropriately.
 */
export async function test_api_create_maintenance_window_happy_path_and_validation(connection: api.IConnection) {
  // 1. Register a new admin for authentication/authorization
  const adminEmail = typia.random<string & tags.Format<"email">>();
