    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 3. Create a valid maintenance window
  const now = new Date();
  const start = new Date(now.getTime() + 60_000).toISOString(); // 1 min in future
  const end = new Date(now.getTime() + 3_600_000).toISOString(); // +1h
  const createBody: IPolEcoBoardMaintenanceWindow.ICreate = {
    window_code: `MAINT_${now.toISOString().replace(/[-:.TZ]/g, "").slice(0,12)}`,
    start_time: start,
    end_time: end,
    expected_impact: "Scheduled DB maintenance - no downtime expected.",
    notified_at: null,
  };
  const created = await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
    body: createBody,
  });
  typia.assert(created);
  TestValidator.equals("window_code matches")(created.window_code)(createBody.window_code);
  TestValidator.equals("expected_impact matches")(created.expected_impact)(createBody.expected_impact);
  TestValidator.equals("start_time matches")(created.start_time)(createBody.start_time);
  TestValidator.equals("end_time matches")(created.end_time)(createBody.end_time);
  TestValidator.equals("notified_at matches")(created.notified_at)(null);

  // 4. Try to create a conflicting (overlapping) maintenance window
  const conflictBody: IPolEcoBoardMaintenanceWindow.ICreate = {
    window_code: `MAINT_CONFLICT_${now.getTime()}`,
    start_time: start,
    end_time: end,
    expected_impact: "Should fail due to overlap.",
    notified_at: null,
  };
  await TestValidator.error("overlap/uniqueness error expected")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
      body: conflictBody,
    });
  });

  // 5. Try to create invalid window (end < start)
  const badTimeBody: IPolEcoBoardMaintenanceWindow.ICreate = {
    window_code: `MAINT_BADRANGE_${now.getTime()}`,
    start_time: end,
    end_time: start,
    expected_impact: "Should fail due to end before start.",
    notified_at: null,
  };
  await TestValidator.error("invalid time range")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
      body: badTimeBody,
    });
  });

  // 6. Try with unauthenticated connection (simulate by clearing headers)
  const unauthConnection = {
    ...connection,
    headers: {},
  };
  await TestValidator.error("auth required")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.create(unauthConnection, {
      body: createBody,
    });
  });
}

