import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardBoardHistory";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate moderator board history search (filters, pagination, access)
 *
 * This test covers the ability for a moderator to retrieve a paginated, filtered list of board history change events using all business-relevant filters and correct role-based authentication.
 *
 * Business context and steps:
 * 1. Register and log in as a moderator (to later test access and data visibility).
 * 2. Register and log in as an admin (so we can create categories, board, and generate board history records).
 * 3. As admin, create two categories with unique names.
 * 4. As admin, create a board under the first category.
 * 5. As admin, migrate board to the second category—this generates a board history record. Optionally, generate another change for diversity.
 * 6. Switch back to moderator: log in as the moderator. Run PATCH search requests for board histories filtering by: board id, category, actor, change_type, and time interval. Use pagination (page=1, pageSize=1, etc.).
 * 7. Assert that only permitted events are returned, filtering and pagination work, audit meta is present.
 * 8. Run edge tests: filter with non-existent board, invalid filter, or forbidden access scenario, to verify audit compliance and proper error handling.
 */
export async function test_api_board_history_search_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // ----- Moderator registration and login -----
  const mod_email = typia.random<string & tags.Format<"email">>();
  const mod_password = "M0dStrongPass!234";
  const mod_display_name = RandomGenerator.name();
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: mod_email,
      password: mod_password,
      display_name: mod_display_name,
      consent_status: "accept-latest",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);

  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: mod_email,
      password: mod_password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);

  // ----- Admin registration and login -----
  const admin_email = typia.random<string & tags.Format<"email">>();
  const admin_password = "Adm1nStr0ngPass!456";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: admin_email,
      password: admin_password,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: admin_email,
      password: admin_password,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // ----- Create two categories as admin -----
  const category1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "Category " + RandomGenerator.alphabets(5),
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category1);

  const category2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "Category " + RandomGenerator.alphabets(6),
      description: RandomGenerator.paragraph()(),
      display_order: 2,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category2);

  // ----- Create a board in category1 -----
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category1.id,
      name: "Board " + RandomGenerator.alphabets(6),
      code: "board_" + RandomGenerator.alphaNumeric(6),
      description: RandomGenerator.content()()(),
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // ----- Admin migrates board to category2 (generates board history record) -----
  const nowTime = new Date().toISOString();
  const boardHistory1 = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: category1.id,
      new_category_id: category2.id,
      actor_admin_id: undefined,
      actor_moderator_id: undefined,
      change_type: "reassignment",
      change_reason: "Category migration for test scenario",
      changed_at: nowTime,
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(boardHistory1);

  // Optional: another event for more diversity (admin archives board)
  const boardHistory2 = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: category2.id,
      new_category_id: category2.id,
      actor_admin_id: undefined,
      actor_moderator_id: undefined,
      change_type: "archive",
      change_reason: "Archived for test coverage",
      changed_at: new Date(Date.now() + 5000).toISOString(),
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(boardHistory2);

  // ----- Switch back to moderator for board history search -----
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: mod_email,
      password: mod_password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // ----- (A) Query board history by board id (should include both records) -----
  const patchBoardHistoryByBoard = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 20 },
      pol_eco_board_board_id: board.id,
    } satisfies IPolEcoBoardBoardHistory.IRequest,
  });
  typia.assert(patchBoardHistoryByBoard);
  TestValidator.predicate("board history list returned, filter by board id")(patchBoardHistoryByBoard.data.length >= 1);
  TestValidator.equals("pagination meta present")(typeof patchBoardHistoryByBoard.pagination.current === "number")(true);

  // ----- (B) Query by new_category_id (should include both if both histories point to category2) -----
  const patchByNewCategory = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 10 },
      new_category_id: category2.id,
    } satisfies IPolEcoBoardBoardHistory.IRequest,
  });
  typia.assert(patchByNewCategory);
  TestValidator.predicate("board history filter by new_category_id")(patchByNewCategory.data.some(e => e.new_category_id === category2.id));

  // ----- (C) Query by previous_category_id (should only match the first event) -----
  const patchByPrevCategory = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 10 },
      previous_category_id: category1.id,
    } satisfies IPolEcoBoardBoardHistory.IRequest,
  });
  typia.assert(patchByPrevCategory);
  TestValidator.predicate("prev_category result only")(patchByPrevCategory.data.every(e => e.previous_category_id === category1.id));

  // ----- (D) Query by change_type ("archive")
  const patchByChangeType = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 10 },
      change_type: "archive",
    } satisfies IPolEcoBoardBoardHistory.IRequest,
  });
  typia.assert(patchByChangeType);
  TestValidator.predicate("change_type=archive present")(patchByChangeType.data.some(e => e.change_type === "archive"));

  // ----- (E) Query by time: after boardHistory1.changed_at - should catch later event
  const patchByChangedAfter = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 10 },
      changed_after: boardHistory1.changed_at,
    } satisfies IPolEcoBoardBoardHistory.IRequest,
  });
  typia.assert(patchByChangedAfter);
  TestValidator.predicate("filter by changed_after")(patchByChangedAfter.data.every(e => e.changed_at > boardHistory1.changed_at));

  // ----- (F) Query with pagination: page 1, pageSize 1
  const patchPaginated = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 1 },
    } satisfies IPolEcoBoardBoardHistory.IRequest,
  });
  typia.assert(patchPaginated);
  TestValidator.equals("pagination page 1, pageSize 1")(patchPaginated.pagination.current)(1);
  TestValidator.equals("pageSize==1")(patchPaginated.data.length)(Math.min(1, patchPaginated.pagination.limit, patchPaginated.pagination.records));

  // ----- (G) Query with actor_admin_id - REMOVED (ISummary does not expose actor_admin_id)

  // ----- (H) Query with filter that should yield no results (random UUID)
  const patchByUnknownBoard = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 10 },
      pol_eco_board_board_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(patchByUnknownBoard);
  TestValidator.equals("empty result set for unknown board")(patchByUnknownBoard.data.length)(0);

  // ----- (I) Invalid/forbidden access tested (simulate using an obviously invalid actor_moderator_id)
  // ISummary does not expose actor_moderator_id, so we cannot assert on record content, only that response is correct (empty)
  const patchInvalidFilter = await api.functional.polEcoBoard.moderator.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 10 },
      actor_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(patchInvalidFilter);
  TestValidator.equals("forbidden/invalid filter yields no data")(patchInvalidFilter.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardBoardHistory";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can search and retrieve the board change history using filters and pagination.
 *
 * This test covers the workflow from authentication, category and board setup, generating board histories, and then exercising the board history search endpoint with a comprehensive set of filters. It also checks access restrictions and error handling for improper requests.
 *
 * Step-by-step process:
 * 1. Register a new admin using unique credentials
 * 2. Log in as the newly created admin
 * 3. Create at least two distinct board categories
 * 4. Create two boards, each in one category
 * 5. Generate meaningful board history records by simulating board reassignments and type changes (each with clear attributes)
 * 6. Issue a search (PATCH) for board histories with no filters (should return all)
 * 7. Search with filters: by change_type, by board id, by category ids, by change date interval, by actor_admin_id
 * 8. Search using pagination (request pageSize 1, iterate through results)
 * 9. Attempt access as a non-admin (should be denied)
 * 10. Attempt invalid filter parameters (e.g. invalid uuid, invalid dates) and expect validation errors
 */
export async function test_api_board_history_search_admin_filters_and_pagination(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(signUpResponse);

  // 2. Log in as admin
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(signInResponse);

  // 3. Create categories
  const cat1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: "Policy board",
      display_order: 1
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(cat1);

  const cat2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: "Economy board",
      display_order: 2
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(cat2);

  // 4. Create boards in categories
  const brd1 = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: cat1.id,
      name: RandomGenerator.alphaNumeric(12),
      code: RandomGenerator.alphaNumeric(8),
      description: "Board 1 description",
      is_public: true,
      is_archived: false,
      display_order: 1
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(brd1);
  const brd2 = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: cat2.id,
      name: RandomGenerator.alphaNumeric(13),
      code: RandomGenerator.alphaNumeric(7),
      description: "Board 2 description",
      is_public: false,
      is_archived: false,
      display_order: 2
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(brd2);

  // 5. Generate multiple board history records
  // A. Move board1 to category2 (reassignment)
  const hist1 = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: brd1.id,
      previous_category_id: cat1.id,
      new_category_id: cat2.id,
      actor_admin_id: null,
      actor_moderator_id: null,
      change_type: "reassignment",
      change_reason: "Move for focus",
      changed_at: new Date().toISOString()
    } satisfies IPolEcoBoardBoardHistory.ICreate
  });
  typia.assert(hist1);
  // B. Archive board2
  const hist2 = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: brd2.id,
      previous_category_id: cat2.id,
      new_category_id: cat2.id,
      actor_admin_id: null,
      actor_moderator_id: null,
      change_type: "archive",
      change_reason: "Routine archival",
      changed_at: new Date().toISOString()
    } satisfies IPolEcoBoardBoardHistory.ICreate
  });
  typia.assert(hist2);

  // 6. Search with no filter (all)
  const allResult = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: {
      pagination: { page: 1, pageSize: 10 }
    } satisfies IPolEcoBoardBoardHistory.IRequest
  });
  typia.assert(allResult);
  TestValidator.predicate("should return created history records")(allResult.data.some(r => [hist1.id, hist2.id].includes(r.id)));

  // 7. Filter by change_type
  const onlyArchive = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: { pagination: { page: 1, pageSize: 5 }, change_type: "archive" }
  });
  typia.assert(onlyArchive);
  TestValidator.predicate("all are archived")(onlyArchive.data.every(r => r.change_type === "archive"));

  // 7.b Filter by board id
  const byBoard1 = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: { pagination: { page: 1, pageSize: 5 }, pol_eco_board_board_id: brd1.id }
  });
  typia.assert(byBoard1);
  TestValidator.predicate("all belong to board1")(byBoard1.data.every(r => r.pol_eco_board_board_id === brd1.id));

  // 7.c Filter by both cat2 as new_category_id
  const byNewCat2 = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: { pagination: { page: 1, pageSize: 5 }, new_category_id: cat2.id }
  });
  typia.assert(byNewCat2);
  TestValidator.predicate("all new_category_id == cat2")(byNewCat2.data.every(r => r.new_category_id === cat2.id));

  // 7.d Filter by change interval
  const earliest = new Date(Date.now() - 1000 * 60 * 5).toISOString();
  const latest = new Date(Date.now() + 1000 * 60 * 5).toISOString();
  const byInterval = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: { pagination: { page: 1, pageSize: 10 }, changed_after: earliest, changed_before: latest }
  });
  typia.assert(byInterval);
  TestValidator.predicate("change in interval")(byInterval.data.every(r => r.changed_at >= earliest && r.changed_at <= latest));

  // 7.e Filter by non-existent actor_admin_id (should be empty)
  const byInvalidActor = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: { pagination: { page: 1, pageSize: 5 }, actor_admin_id: typia.random<string & tags.Format<"uuid">>() }
  });
  typia.assert(byInvalidActor);
  TestValidator.equals("should be empty")(byInvalidActor.data.length)(0);

  // 8. Pagination test: pageSize=1 & data iterations
  const paged = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: { pagination: { page: 1, pageSize: 1 } }
  });
  typia.assert(paged);
  TestValidator.equals("pageSize == 1")(paged.data.length)(1);
  const pagedPage2 = await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
    body: { pagination: { page: 2, pageSize: 1 } }
  });
  typia.assert(pagedPage2);
  TestValidator.equals("pageSize == 1 (2nd page)")(pagedPage2.data.length)(1);

  // 9. Unauthorized access: do not supply admin credentials (simulate by creating fresh non-admin connection)
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated should not access boardHistories")(() =>
    api.functional.polEcoBoard.admin.boardHistories.search(unauthConnection as any, {
      body: { pagination: { page: 1, pageSize: 1 } }
    })
  );

  // 10. Invalid parameters: bad UUID and invalid date
  await TestValidator.error("invalid UUID")(async () => {
    await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
      body: { pagination: { page: 1, pageSize: 1 }, pol_eco_board_board_id: "BAD-UUID" }
    });
  });
  await TestValidator.error("invalid date string")(async () => {
    await api.functional.polEcoBoard.admin.boardHistories.search(connection, {
      body: { pagination: { page: 1, pageSize: 1 }, changed_after: "not-a-date" }
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardHistory";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate moderator access to board history detail API.
 *
 * Tests the ability of a moderator to fetch full details of a board change history by boardHistoryId.
 * Covers the following workflow:
 * 1. Register and login an admin (creates source data for board histories)
 * 2. Register and login a moderator (for API permission context)
 * 3. Admin creates a category
 * 4. Admin creates a board within that category
 * 5. Admin creates a board history record for the board
 * 6. Moderator fetches the boardHistoryId and checks field composition
 * 7. Moderator attempts to fetch a random/nonexistent and (if possible) deleted ID, verifies correct permission/error behaviour
 *
 * This test ensures the permission matrix and business workflow are enforced, with all object references and rationale visible to moderators.
 */
export async function test_api_board_history_get_detail_as_moderator(connection: api.IConnection) {
  // 1. Register and login admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Register and login moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsentStatus = "accepted_v1";
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 3. Admin creates a category
  // Switch back to admin (login again to set admin token)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Admin creates a board within the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(12),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Admin creates a board history record for the board
  const history = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: null,
      new_category_id: category.id,
      actor_admin_id: null, // Could set adminId if available; left null for path compatibility
      actor_moderator_id: null,
      change_type: "reassignment",
      change_reason: RandomGenerator.paragraph()(),
      changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(history);

  // 6. Moderator fetches boardHistoryId (login again as moderator)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  const fetched = await api.functional.polEcoBoard.moderator.boardHistories.at(connection, {
    boardHistoryId: history.id,
  });
  typia.assert(fetched);
  TestValidator.equals("boardHistoryId matches")(fetched.id)(history.id);
