import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the ability for a moderator to soft-delete (archive) a board status event record for a discussion board.
 *
 * Business rationale:
 * - Moderators should be able to archive (soft-delete) board status events for compliance and operational reversibility, but only on events they have privileges for.
 * - System must strictly mark the record as deleted (set `deleted_at`) without removing from the audit trail.
 * - Subsequent deletion attempts for the same or nonexistent events must raise errors.
 *
 * Step-by-step process:
 * 1. Register a new admin and login to allow privileged category/board creation.
 * 2. As admin: Create a new category and a board in that category.
 * 3. Register a moderator and login as that moderator.
 * 4. As moderator: Create a board status event for that board.
 * 5. Soft-delete the status event (main action).
 * 6. Verify deletion by checking:
 *    a) Second delete call fails (already deleted)
 *    b) Deleting a random nonexistent status also fails
 */
export async function test_api_board_status_soft_delete_by_moderator(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login (to authorize board/category creation)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a new category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.alphaNumeric(30),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create a board under this category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.alphaNumeric(25),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Register a moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "modPass123!";
  const modDisplayName = RandomGenerator.alphabets(8);
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: "accepted-latest-tos",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });

  // 6. Moderator login
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 7. Moderator creates a board status event (archived)
  const status = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: null, // Provided by JWT; only moderator can act here
      actor_admin_id: null,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "Setup for soft-delete test.",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(status);

  // 8. Invoke soft-delete (archive) as moderator
  await api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
    boardStatusId: status.id,
  });

  // 9. Attempt to delete again should fail (already deleted)
  await TestValidator.error("already deleted / double delete")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: status.id,
    })
  );

  // 10. Attempt to delete a random/unknown boardStatusId should fail
  await TestValidator.error("delete nonexistent boardStatusId")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Verify admin-driven soft-deletion of board status events and compliance with audit and retention business rules.
 *
 * This test ensures that an admin user can soft-delete (archive) a board status event and that business logic behaves as expected:
 *
 * 1. Registers and logs in as an admin, yielding privileged session.
 * 2. Creates a category and a discussion board as prerequisites.
 * 3. Records a new board status event (with this admin as the actor).
 * 4. Issues DELETE for the new status event (should archive via deleted_at—not physical removal).
 * 5. Checks that deleted_at has been set (by making additional status event, verifying new event not affected, and comparing outcomes).
 * 6. Attempts duplicate deletion on the same status id (should yield a business error).
 * 7. Attempts deletion of a non-existent boardStatusId (should yield a not-found/business error).
 *
 * Note: Non-admin actor simulation is omitted, as user/moderator auth APIs are unavailable in current E2E surface.
 */
export async function test_api_board_status_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin to ensure token set (redundant if signUp sets, but double-check for strictness)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create a board in that category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(2),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Create a board status event (admin as actor)
  const boardStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: null, // Will be system-resolved based on token
      status_type: "visible",
      effective_at: new Date().toISOString(),
      reason: RandomGenerator.paragraph()(),
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(boardStatus);
  TestValidator.equals("not deleted initially")(boardStatus.deleted_at)(null);

  // 6. Soft-delete the board status event
  await api.functional.polEcoBoard.admin.boardStatuses.erase(connection, {
    boardStatusId: boardStatus.id,
  });

  // 7. Confirm status is now deleted (simulate by making new status, ensure old id not re-used, etc.)
  // Since we can't query the deleted record, create another status to show system allows others
  const boardStatusAfter = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: null,
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: RandomGenerator.paragraph()(),
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(boardStatusAfter);
  TestValidator.notEquals("new status has new id")(boardStatusAfter.id)(boardStatus.id);

  // 8. Edge: Try deleting already-deleted record (should error)
  await TestValidator.error("re-delete yields error")(async () => {
    await api.functional.polEcoBoard.admin.boardStatuses.erase(connection, {
      boardStatusId: boardStatus.id,
    });
  });

  // 9. Edge: Try deleting random/non-existent id (should error)
  await TestValidator.error("delete random id fails")(async () => {
    await api.functional.polEcoBoard.admin.boardStatuses.erase(connection, {
      boardStatusId: typia.random<string & tags.Format<"uuid">>()
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardEscalation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardEscalation";
import type { IPageIPolEcoBoardEscalation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardEscalation";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * E2E test for moderator escalation search with various filters, pagination, visibility, input validation,
 * and permission checking.
 *
 * This test verifies that moderator accounts can search for escalations (compliance cases) with a variety
 * of filter conditions, and only receive results they are allowed to see. It covers searching by status,
 * actor, rationale substring, date range, pagination parameters, and handles edge cases such as invalid input,
 * empty result sets, and unauthenticated access attempts.
 *
 * Steps performed:
 * 1. Register a new moderator to act as test subject (to receive JWT and be actor for escalations)
 * 2. Login as the moderator (redundant, demonstrates auth flow)
 * 3. Create sample escalation records: two for this moderator as escalator, one for another "actor"
 * 4. Run all major search scenarios as the moderator:
 *    a. No filters (get all visible escalations)
 *    b. Filter by status, escalator_id, reason substring, created_at date range
 *    c. Pagination (page, limit) tested
 *    d. Invalid status raises error
 *    e. Nonexistent filter value returns empty
 *    f. Very large page/limit does not exceed available or max
 *    g. Attempt to filter for deleted/archived (always excluded in test data)
 * 5. Remove auth and verify permission is required for search
 */
export async function test_api_escalation_search_various_filters_moderator_access(
  connection: api.IConnection,
) {
  // 1. Register test moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "StrongP@ssword123";
  const display_name = RandomGenerator.name();
  const consent_status = "v1.1-tos";
  const modReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: { email, password, display_name, consent_status } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(modReg);

  // 2. Login as the moderator (optional - demonstrates full authentication loop)
  const modLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(modLogin);

  // 3. Create escalation cases via admin endpoint
  // Escalation for this moderator, pending status
  const escalationA = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: modReg.moderatorId,
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Auto test rationale for A",
      status: "pending"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationA);
  // Escalation for this moderator, resolved status
  const escalationB = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: modReg.moderatorId,
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Another test rationale for B",
      status: "resolved"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationB);
  // Escalation not for this moderator (ensures filter works)
  const escalationC = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: typia.random<string & tags.Format<"uuid">>(),
      recipient_admin_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "Edge rationale C",
      status: "rejected"
    } satisfies IPolEcoBoardEscalation.ICreate
  });
  typia.assert(escalationC);

  // ------------------------ SEARCH VERIFICATIONS --------------------------------
  // 4a. No filters: expect at least the ones for this moderator to be present
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: {} satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("at least our test escalations returned")(
      res.data.some(e => [escalationA.id, escalationB.id].includes(e.id))
    );
  }
  // 4b. Filter by status = 'pending'
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { status: "pending" } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all results are pending")(
      res.data.every(e => e.status === "pending")
    );
  }
  // 4c. Filter by escalator_id: must return only records for this id
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { escalator_id: modReg.moderatorId } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all by this moderator")(
      res.data.every(e => e.escalator_id === modReg.moderatorId)
    );
  }
  // 4d. Filter by partial reason (rationale substring)
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { reason: "rationale for A" } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("reason contains substring")(
      res.data.every(e => e.reason.includes("rationale for A"))
    );
  }
  // 4e. Filter by recent date range
  {
    const now = new Date();
    const before = new Date(now.getTime() - 60 * 1000).toISOString();
    const after = new Date(now.getTime() + 60 * 1000).toISOString();
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { created_at_start: before, created_at_end: after } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("all within date range")(
      res.data.every(e => e.created_at >= before && e.created_at <= after)
    );
  }
  // 4f. Pagination: limit=1, page=1
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { limit: 1, page: 1 } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("pagination limit applied")(res.data.length)(1);
    TestValidator.equals("pagination current page")(res.pagination.current)(1);
    TestValidator.equals("pagination limit")(res.pagination.limit)(1);
  }
  // 4g. Invalid filter value for status
  TestValidator.error("invalid status value should error")(async () =>
    api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { status: "definitelynotastatus" } as any
    })
  );
  // 4h. No-result: random moderation_action_id
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { moderation_action_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("expect zero records")(res.data.length)(0);
  }
  // 4i. Very large pagination: confirm not oversized
  {
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { limit: 1000, page: 100 } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.predicate("does not return too many records")(res.data.length <= 1000);
  }
  // 4j. Edge case: filter for deleted/archived. (Since we can't create deleted in this suite, simulate date before all creation)
  {
    const deletedDate = new Date(2000, 1, 1).toISOString();
    const res = await api.functional.polEcoBoard.moderator.escalations.search(connection, {
      body: { created_at_end: deletedDate } satisfies IPolEcoBoardEscalation.IRequest
    });
    typia.assert(res);
    TestValidator.equals("records before epoch should be empty")(res.data.length)(0);
  }
  // 5. Permission: remove Authorization, error expected
  const headers = { ...connection.headers };
  delete headers.Authorization;
  const connNoAuth = { ...connection, headers };
  TestValidator.error("should get permission error when unauthenticated")(
    async () => api.functional.polEcoBoard.moderator.escalations.search(connNoAuth, {
      body: {} satisfies IPolEcoBoardEscalation.IRequest
    })
  );
}

