 * This test verifies that a moderator can only access escalation details that they have created (where escalator_id matches), receives permission denied when attempting to fetch escalations they don't own, and gets a not-found error for non-existent escalationIds. It also checks API behavior for finalized/deleted escalations (if supported by schema).
 *
 * Workflow:
 * 1. Register and login as moderator A
 * 2. Register and login as moderator B
 * 3. Create two escalation records:
 *     a. escalation1: escalator_id = moderator A
 *     b. escalation2: escalator_id = moderator B
 * 4. As moderator A, fetch escalation1 (expect success)
 * 5. As moderator A, fetch escalation2 (expect permission denied)
 * 6. As moderator A, fetch a non-existent escalationId (expect not found)
 * 7. (If possible by schema) mark escalation as deleted or finalized and verify fetch response
 */
export async function test_api_escalation_detail_access_by_id_moderator(connection: api.IConnection) {
  // 1. Register moderator A
  const modAEmail = typia.random<string & tags.Format<"email">>();
  const modAPassword = "Test!1234";
  const modARes = await api.functional.auth.moderator.register.signUp(connection, {
