  const modBPassword = "Test!5678";
  const modBRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modBEmail,
      password: modBPassword,
      display_name: RandomGenerator.name(),
      consent_status: "latest-policy-v1"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(modBRes);
  const moderatorBId = modBRes.moderatorId;

  // 3. Login as moderator A to acquire session (token in connection)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modAEmail,
      password: modAPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

  // 4. Create escalation1 (escalator_id = moderatorA)
  const escalation1 = await api.functional.polEcoBoard.admin.escalations.create(connection, {
    body: {
      moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
      escalator_id: moderatorAId,
