import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates privileged creation and error handling for board status events by an admin user.
 *
 * This E2E test covers:
 * 1. Admin registration and login
 * 2. Creation of a board to operate on
 * 3. Successful status event creation as admin
 * 4. Input validation error (invalid enum)
 * 5. Attempt to create status for non-existent board
 * 6. Business rule error such as status transition not allowed
 * 7. Audit requirements (rationale, audit fields)
 *
 * Notes:
 * - Testing attempt by a lower-role user (non-admin) is NOT possible given exposed SDK functions: no non-admin endpoint is provided for board status creation.
 * - Runtime validation errors tested: invalid enum, non-existent board, disallowed transition, and audit/rationale field checks.
 * - Omitting required fields (e.g., status_type required in TS) as error scenario is not included, per instructions.
 */
export async function test_api_board_status_creation_by_admin_with_business_constraints(connection: api.IConnection) {
  // 1. Register and login as new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);

  // Register admin
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 2. Create a board as admin
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(1).slice(0, 255),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Successfully create status event as admin
  const now = new Date();
  const boardStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
      status_type: "locked",
      effective_at: new Date(now.getTime() + 60 * 1000).toISOString(),
      reason: "Routine moderation lock for audit",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(boardStatus);
  TestValidator.equals("board association")(boardStatus.pol_eco_board_board_id)(board.id);
  TestValidator.equals("status_type")(boardStatus.status_type)("locked");
  TestValidator.equals("reason set")(boardStatus.reason)("Routine moderation lock for audit");
  TestValidator.predicate("audit created_at present")(!!boardStatus.created_at);
  TestValidator.predicate("audit effective_at present")(!!boardStatus.effective_at);
  TestValidator.predicate("admin actor present")(!!boardStatus.actor_admin_id);

  // 4. Input validation error: invalid enum value for status_type
  await TestValidator.error("invalid status_type enum")(() =>
    api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: board.id,
        actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
        status_type: "invalid_status_type" as any,
        effective_at: new Date(now.getTime() + 120 * 1000).toISOString(),
        reason: "Testing invalid status_type",
      } as any,
    })
  );

  // 5. Attempt to create status for a non-existent board
  await TestValidator.error("non-existent boardId")(() =>
    api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: typia.random<string & tags.Format<"uuid">>(),
        actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
        status_type: "locked",
        effective_at: new Date(now.getTime() + 180 * 1000).toISOString(),
        reason: "Intentionally wrong boardId",
      },
    })
  );

  // 6. Business rule error: disallowed transition (e.g., archive then open)
  // First: archive the board
  const archiveStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
      status_type: "archived",
      effective_at: new Date(now.getTime() + 240 * 1000).toISOString(),
      reason: "Archiving for business rule test",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(archiveStatus);

  // Attempt to re-open the archived board (supposed to fail)
  await TestValidator.error("business rule transition forbidden")(() =>
    api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: board.id,
        actor_admin_id: typia.random<string & tags.Format<"uuid">>(),
        status_type: "open",
        effective_at: new Date(now.getTime() + 300 * 1000).toISOString(),
        reason: "Attempt to re-open archived board",
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test updating details of a board status event by a moderator (PUT /polEcoBoard/moderator/boardStatuses/{boardStatusId}).
 *
 * This test validates multiple business cases for board status event updates:
 *
 * 1. Successfully update an existing status event by an authorized moderator
 * 2. Attempt update with invalid or missing fields (should fail)
 * 3. Attempt update after allowed edit window (should fail if window is enforced)
 * 4. Update of a deleted (soft-deleted) or non-existent event (should fail)
 * 5. Update attempt by unauthorized (non-moderator) actor (should fail)
 *
 * Steps:
 * - Register and login as a new moderator
 * - Create a board status event for a random board as this moderator
 * - Successfully update the status event using valid inputs (expect audit fields changed)
 * - Try to update with missing required fields (should error)
 * - (If allowed edit window: update after the window expires)
 * - Try to update a deleted status event (first soft-delete, then try update; expect error)
 * - Try updating a non-existent boardStatusId (expect error)
 * - Try updating as unauthorized (simulate by removing Authorization or using invalid token)
 */
export async function test_api_board_status_update_by_moderator_with_state_and_permission_validation(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestModPass1!",
      display_name: RandomGenerator.name(),
      consent_status: "v1/2024-consent",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);
  const moderatorEmail = moderatorReg.email;
  const moderatorPassword = "TestModPass1!";

  // 2. Login as the registered moderator (confirm token is set)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);

  // 3. Create a board status event with this moderator
  const polEcoBoardBoardId = typia.random<string & tags.Format<"uuid">>();
  const createBoardStatus = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: polEcoBoardBoardId,
      actor_moderator_id: moderatorLogin.moderatorId,
      status_type: "visible",
      effective_at: new Date().toISOString(),
      reason: "Initial status set by moderator",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(createBoardStatus);
  const boardStatusId = createBoardStatus.id;

  // 4. Successful update of the board status event
  const updateStatus1 = await api.functional.polEcoBoard.moderator.boardStatuses.update(connection, {
    boardStatusId,
    body: {
      status_type: "locked",
      reason: "Board locked for moderation review",
      actor_moderator_id: moderatorLogin.moderatorId,
    } satisfies IPolEcoBoardBoardStatus.IUpdate,
  });
  typia.assert(updateStatus1);
  TestValidator.equals("board status id match")(updateStatus1.id)(boardStatusId);
  TestValidator.equals("status type updated")(updateStatus1.status_type)("locked");
  TestValidator.equals("reason updated")(updateStatus1.reason)("Board locked for moderation review");
  TestValidator.equals("actor moderator id updated")(updateStatus1.actor_moderator_id)(moderatorLogin.moderatorId);

  // 5. Error: update with invalid (illegal status_type)
  await TestValidator.error("invalid status_type should fail")(async () => {
    await api.functional.polEcoBoard.moderator.boardStatuses.update(connection, {
      boardStatusId,
      body: {
        status_type: "non-existent-status" as any,
        actor_moderator_id: moderatorLogin.moderatorId,
      } as any,
    });
  });

  // 6. Error: update a non-existent boardStatusId
  const fakeBoardStatusId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update with non-existent boardStatusId should fail")(async () => {
    await api.functional.polEcoBoard.moderator.boardStatuses.update(connection, {
      boardStatusId: fakeBoardStatusId,
      body: {
        status_type: "locked",
        reason: "Testing non-existent",
        actor_moderator_id: moderatorLogin.moderatorId,
      } satisfies IPolEcoBoardBoardStatus.IUpdate,
    });
  });

  // 7. Error: update as non-moderator (no Authorization) - Remove token, expect error
  const noAuthConnection = { ...connection, headers: { ...connection.headers, Authorization: "" } };
  await TestValidator.error("update as non-moderator should fail")(async () => {
    await api.functional.polEcoBoard.moderator.boardStatuses.update(noAuthConnection, {
      boardStatusId,
      body: {
        status_type: "visible",
        reason: "Unauthorized update attempt",
      } satisfies IPolEcoBoardBoardStatus.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for validating the admin update (PUT) of board status events in the policy eco board system.
 *
 * Covers scenarios:
 * 1. Successful admin update on a legitimate board status event (e.g., correct rationale, new effective_at, or status_type change)
 * 2. Business validation – fail on missing/invalid required fields (status_type, effective_at)
 * 3. Soft-deleted and non-existent boardStatusId update should fail (returns error)
 * 4. Permission test – call the endpoint with no auth (should fail with 401)
 * 5. After a successful update, confirm audit fields (updated_at changed, correct actor), check edit window business rules
 *
 * Main asserts: response shape/type, error handling, audit/actor field checks.
 */
export async function test_api_board_status_update_by_admin_with_full_business_validation(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePwd" + Math.floor(Math.random() * 10000000); // must be min 8 chars
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Admin login (token attached for subsequent requests)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 3. Create a board for test (using random / valid data for all required fields)
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      name: "TestBoard_" + Math.floor(Math.random() * 10000000),
      code: "testcode_" + Math.floor(Math.random() * 10000000),
      is_public: true,
      is_archived: false,
      display_order: 1,
    },
  });
  typia.assert(board);

  // 4. Create initial board status event (locked)
  const initialStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: null, // should be auto-resolved by backend according to privilege, can leave null
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: "Initial lock for moderation",
    },
  });
  typia.assert(initialStatus);

  // 5. Valid update as admin: change reason and time
  const newReason = "Moderation period ended, reopening board";
  const newEffectiveAt = new Date(Date.now() + 86400000).toISOString();
  const updated = await api.functional.polEcoBoard.admin.boardStatuses.update(connection, {
    boardStatusId: initialStatus.id,
    body: {
      status_type: "open", // changing status to open
      effective_at: newEffectiveAt,
      reason: newReason,
      actor_admin_id: null,
    },
  });
  typia.assert(updated);
  TestValidator.equals("status_type updated")(updated.status_type)("open");
  TestValidator.equals("reason updated")(updated.reason)(newReason);
  TestValidator.equals("effective_at updated")(updated.effective_at)(newEffectiveAt);
  // updated_at should be after previous
  TestValidator.predicate("updated_at newer")(new Date(updated.updated_at) > new Date(initialStatus.updated_at));

  // 6. Invalid update: non-existent boardStatusId (random UUID)
  await TestValidator.error("update non-existent status event fails")(async () => {
    return api.functional.polEcoBoard.admin.boardStatuses.update(connection, {
      boardStatusId: typia.random<string & tags.Format<"uuid">>(),
      body: {
        status_type: "hidden",
        effective_at: new Date().toISOString(),
        reason: "Trying to update non-existent event",
      },
    });
  });

  // 7. Permission: remove Authorization header (simulate unauthenticated request)
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers.Authorization;
  await TestValidator.error("update without auth")(async () => {
    return api.functional.polEcoBoard.admin.boardStatuses.update(noAuthConnection, {
      boardStatusId: initialStatus.id,
      body: {
        status_type: "archived",
        effective_at: new Date().toISOString(),
        reason: "Should not succeed without auth",
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMaintenanceWindow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMaintenanceWindow";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate successful update of an existing maintenance window by an admin.
 *
 * Business context:
 * - Only authenticated admins may update maintenance windows.
 * - Audit trails and business rules (time validity, policy checks) must be obeyed on update.
 * - All changes are tracked for compliance and incident management.
 *
 * Test workflow:
 * 1. Register a new admin using a unique business email and password.
 * 2. Log in as the newly created admin to obtain authentication for API calls.
 * 3. Create a new maintenance window (with valid input fields), capturing the generated maintenanceWindowId.
 * 4. Prepare update data: modify multiple updatable fields (e.g., change window_code, update start_time, end_time, expected_impact, notified_at).
 * 5. Call the update (PUT) API with the existing window id and new values.
 * 6. Assert the API response reflects all updated fields, with correct value application (including nullables/optionals if used).
 * 7. Confirm that update respects maintenance window policy: start_time is before end_time (if both present), and updated_at is refreshed.
 * 8. If other audit log or compliance features are visible in the response, validate they are correctly appended/updated.
 */
export async function test_api_maintenance_window_update_success(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResp);

  // 2. Login as admin
  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResp);

  // 3. Create maintenance window
  const mwCreateInput = {
    window_code: `MAINT_${new Date().toISOString().slice(0,10).replace(/-/g,"")}_${RandomGenerator.alphaNumeric(3)}`,
    start_time: new Date(Date.now() + 60 * 60 * 1000).toISOString(), // one hour from now
    end_time: new Date(Date.now() + 3 * 60 * 60 * 1000).toISOString(), // three hours from now
    expected_impact: RandomGenerator.paragraph()(1),
    notified_at: null, // no notifications sent yet
  } satisfies IPolEcoBoardMaintenanceWindow.ICreate;
  const mwCreateResp = await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
    body: mwCreateInput,
  });
  typia.assert(mwCreateResp);

  // 4. Prepare update info (change multiple fields)
  const mwUpdateInfo = {
    window_code: `${mwCreateInput.window_code}_U`,
    start_time: new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString(), // shift to later start
    end_time: new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString(), // later end time
    expected_impact: RandomGenerator.paragraph()(1),
    actual_impact: RandomGenerator.paragraph()(1),
    notified_at: new Date().toISOString(),
  } satisfies IPolEcoBoardMaintenanceWindow.IUpdate;

  // 5. Update the window
  const mwUpdateResp = await api.functional.polEcoBoard.admin.maintenanceWindows.update(connection, {
    maintenanceWindowId: mwCreateResp.id,
    body: mwUpdateInfo,
  });
  typia.assert(mwUpdateResp);

  // 6. Response checks
  TestValidator.equals("window_code updated")(mwUpdateResp.window_code)(mwUpdateInfo.window_code ?? mwCreateInput.window_code);
  TestValidator.equals("start_time updated")(mwUpdateResp.start_time)(mwUpdateInfo.start_time ?? mwCreateInput.start_time);
  TestValidator.equals("end_time updated")(mwUpdateResp.end_time)(mwUpdateInfo.end_time ?? mwCreateInput.end_time);
  TestValidator.equals("expected_impact updated")(mwUpdateResp.expected_impact)(mwUpdateInfo.expected_impact ?? mwCreateInput.expected_impact);
  TestValidator.equals("actual_impact updated")(mwUpdateResp.actual_impact)(mwUpdateInfo.actual_impact ?? null);
  TestValidator.equals("notified_at updated")(mwUpdateResp.notified_at)(mwUpdateInfo.notified_at ?? null);
  // Fix: Only compare start_time < end_time if end_time is defined and not null
  TestValidator.predicate("start_time < end_time")(
    mwUpdateResp.end_time != null ? mwUpdateResp.start_time < mwUpdateResp.end_time : true
  );
  TestValidator.notEquals("updated_at refreshed")(mwUpdateResp.updated_at)(mwCreateResp.updated_at);
  // Business rules: updated record must keep same id and window_code unique
