import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardServiceMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardServiceMetric";
import type { IPageIPolEcoBoardServiceMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardServiceMetric";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin search, pagination, and filtering of service metrics.
 *
 * This scenario ensures admin users can perform advanced searches on service metrics, leveraging filtering and pagination. The comprehensive flow verifies that filters—such as metric_code and date ranges—correctly constrain the search result, pagination metadata is accurate, and unauthenticated access is denied. It also validates realistic data by registering metrics with varying codes and time windows to create a meaningful population for filtering.
 *
 * Steps:
 * 1. Register a new admin account (using a unique test email and valid password).
 * 2. Log in as that admin to obtain authentication.
 * 3. Register multiple (at least 3) well-differentiated service metric records:
 *    - Use varying metric_code values (e.g., 'POST_COUNT', 'COMMENT_COUNT')
 *    - Use distinct metric_window_start/metric_window_end times
 *    - Use both value_int and value_double populated on different metrics
 *    - Vary notes values
 * 4. Use the metrics search API to:
 *    a. Retrieve all records with no filters, and verify pagination/data integrity
 *    b. Filter by specific metric_code (should only return matching code)
 *    c. Filter by a range of metric_window_start (from/to) to select a subset
 *    d. Filter by notes substring to test partial text match
 *    e. Page results using limit=1 and different page numbers to verify record splitting, total count, and page count
 * 5. For each search:
 *    - Validate that returned data matches the filter criteria
 *    - Check pagination metadata: current, limit, total records, total pages
 * 6. (Negative case) Attempt the search call before authenticating (e.g., with a fresh connection with no Authorization header), and ensure it fails.
 */
export async function test_api_service_metrics_search_pagination_and_filter(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail: string = typia.random<string & tags.Format<'email'>>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in as this admin (simulate fresh connection)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Register several metrics with different codes/windows/values/notes
  const now = new Date();
  const metrics = [
    // Metric 1
    await api.functional.polEcoBoard.admin.serviceMetrics.create(connection, {
      body: {
        metric_code: 'POST_COUNT',
        metric_window_start: new Date(now.getTime() - 3600 * 1000 * 24).toISOString(),
        metric_window_end: now.toISOString(),
        value_int: 17,
        notes: 'post metric baseline',
      } satisfies IPolEcoBoardServiceMetric.ICreate,
    }),
    // Metric 2
    await api.functional.polEcoBoard.admin.serviceMetrics.create(connection, {
      body: {
        metric_code: 'COMMENT_COUNT',
        metric_window_start: new Date(now.getTime() - 2 * 3600 * 1000 * 24).toISOString(),
        metric_window_end: new Date(now.getTime() - 3600 * 1000 * 24).toISOString(),
        value_int: 44,
        notes: 'comment metric spike',
      } satisfies IPolEcoBoardServiceMetric.ICreate,
    }),
    // Metric 3
    await api.functional.polEcoBoard.admin.serviceMetrics.create(connection, {
      body: {
        metric_code: 'API_LATENCY',
        metric_window_start: new Date(now.getTime() - 3 * 3600 * 1000 * 24).toISOString(),
        metric_window_end: new Date(now.getTime() - 2 * 3600 * 1000 * 24).toISOString(),
        value_double: 101.25,
        notes: 'latency baseline with API upgrades',
      } satisfies IPolEcoBoardServiceMetric.ICreate,
    }),
  ];
  metrics.forEach(x => typia.assert(x));

  // 4a. Search without filter
  const searchAll = await api.functional.polEcoBoard.admin.serviceMetrics.search(connection, { body: { } });
  typia.assert(searchAll);
  TestValidator.predicate('no filter returns at least all records')(searchAll.data.length >= 3);
  TestValidator.equals('total records')(searchAll.pagination.records)(searchAll.data.length);

  // 4b. Metric code filter
  const searchPostCount = await api.functional.polEcoBoard.admin.serviceMetrics.search(connection, {
    body: { metric_code: 'POST_COUNT' },
  });
  typia.assert(searchPostCount);
  TestValidator.predicate('POST_COUNT filter results correct')(
    searchPostCount.data.every(x => x.metric_code === 'POST_COUNT'),
  );

  // 4c. Window date range filter
  const startFrom = metrics[2].metric_window_start;
  const endTo = metrics[1].metric_window_end;
  const subsetRange = await api.functional.polEcoBoard.admin.serviceMetrics.search(connection, {
    body: {
      metric_window_start_from: startFrom,
      metric_window_start_to: endTo,
    },
  });
  typia.assert(subsetRange);
  TestValidator.predicate('window_start_from/to only returns in range')(
    subsetRange.data.every(
      m => m.metric_window_start >= startFrom && m.metric_window_start < endTo,
    ),
  );

  // 4d. Notes substring fuzzy filter
  const substring = 'spike';
  const noteFilter = await api.functional.polEcoBoard.admin.serviceMetrics.search(connection, {
    body: { notes: substring },
  });
  typia.assert(noteFilter);
  TestValidator.predicate('notes fuzzy search returns only matches')(
    noteFilter.data.every(m => m.notes?.includes(substring)),
  );

  // 4e. Pagination test: limit & explicit page
  const paginated = await api.functional.polEcoBoard.admin.serviceMetrics.search(connection, {
    body: { limit: 1, page: 2 },
  });
  typia.assert(paginated);
  TestValidator.equals('pagination limit 1')(paginated.pagination.limit)(1);
  TestValidator.equals('pagination current 2')(paginated.pagination.current)(2);
  TestValidator.predicate('pagination respects page')(paginated.data.length <= 1);
  TestValidator.equals('pagination total')(paginated.pagination.records)(searchAll.pagination.records);

  // 5. Negative: unauthorized session fails
  const freshConn = { ...connection, headers: { } };
  await TestValidator.error('unauthenticated search fails')(async () => {
    await api.functional.polEcoBoard.admin.serviceMetrics.search(freshConn, { body: { } });
  });
}

