/**
 * Test that non-admin users (members) are strictly forbidden from updating account audit records.
 *
 * This test verifies that API access control is enforced, preventing regular logged-in members from updating sensitive account audit entries—even if authenticated.
 *
 * Steps:
 * 1. Register a regular polEcoBoard member (not admin).
 * 2. Login with member credentials; obtain authentication token.
 * 3. As admin (implicit/api-privileged), create an account audit log record for update attempt.
 * 4. Switch to member session (authorization header), attempt to update the audit record using PUT.
 * 5. Confirm that a permission/authorization error is thrown and no changes are made.
 */
export async function test_api_account_audit_update_fail_non_admin(connection: api.IConnection) {
  // 1. Register a regular board member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "password123";
  const member: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Login as the newly registered member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(signInResult);
  connection.headers = {
    ...connection.headers,
    ...signInResult.setHeaders
  };

  // 3. As admin, create an account audit record
  // (simulate admin by using the existing-connection privilege)
  const adminAuditRecord: IPolEcoBoardAccountAudit = await api.functional.polEcoBoard.admin.accountAudits.create(connection, {
    body: {
      action_type: "ban",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      target_account_id: member.id,
      event_source: "test-case",
      status: "success",
      occurred_at: new Date().toISOString()
    } satisfies IPolEcoBoardAccountAudit.ICreate
  });
  typia.assert(adminAuditRecord);

  // 4. Login as the regular member again and update session to non-admin
  const signInResult2 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(signInResult2);
  connection.headers = {
    ...connection.headers,
    ...signInResult2.setHeaders
  };

  // 5. Attempt to update the account audit record as this non-admin member; expect a permission error
  await TestValidator.error("Non-admin forbidden from updating account audit record")(async () => {
    await api.functional.polEcoBoard.admin.accountAudits.update(connection, {
      accountAuditId: adminAuditRecord.id,
      body: {
        action_metadata: "malicious attempt by non-admin"
      } satisfies IPolEcoBoardAccountAudit.IUpdate
    });
  });
}

