  const auditCreateInput: IPolEcoBoardAccountAudit.ICreate = {
    action_type: "ban",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    target_account_id: typia.random<string & tags.Format<"uuid">>(),
    action_metadata: null,
    event_source: "e2e_test_suite",
    status: "success",
