  const auditStillExists = searchResult.data.find((item) => item.id === createdAudit.id);
  TestValidator.equals("audit record should be deleted")(auditStillExists)(undefined);

  // 6. (Optional) Search for audit logs of the deletion action itself by this admin
  // If deletion event is not auto-logged or not exposed here, this is skipped.
}

