/**
 * Validate retrieval of all active admin sessions for a logged-in admin account.
 *
 * This test ensures that the /auth/admin/sessions endpoint returns only the current admin user’s active (unexpired, unrevoked) sessions. It verifies that each session entry includes correct metadata (id, member_id, provider, ip_address, device_fingerprint, user_agent, timestamps, etc.), that no sessions for other admins are shown, and that sensitive information/secrets are never included. The end-to-end flow checked is:
 *
 * 1. Register a new admin with unique business email and a secure password, then confirm successful registration and correct return structure.
 * 2. Log in as the registered admin (introducing at least one active session), confirm receipt of JWT token/headers and correct response structure.
 * 3. (Optional: Log in again to create a second concurrent session, if supported. This may create multiple concurrent sessions for the same admin if API allows repeated logins.)
 * 4. Call GET /auth/admin/sessions as the logged-in admin and check that returned sessions belong to that admin only, with correct metadata, no revoked or expired sessions, no sessions for other users, and no secret/token values in session summaries.
 * 5. Validate type safety, business logic assertions, and metadata for each returned session.
 */
export async function test_api_admin_sessions_enumeration_for_logged_in_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);
  TestValidator.predicate("JWT Authorization header present")(
    typeof signUpResponse.setHeaders.Authorization === "string" &&
      signUpResponse.setHeaders.Authorization.startsWith("Bearer ")
  );

  // 2. Log in as the admin (introduce at least one active session)
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);
  TestValidator.predicate("JWT Authorization header from login present")(
    typeof signInResponse.setHeaders.Authorization === "string" &&
      signInResponse.setHeaders.Authorization.startsWith("Bearer ")
  );

  // 3. (Optional) Log in again to create a second concurrent session (if supported)
  const signInResponseSecond = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponseSecond);
  TestValidator.predicate("JWT Authorization header from second login present")(
    typeof signInResponseSecond.setHeaders.Authorization === "string" &&
      signInResponseSecond.setHeaders.Authorization.startsWith("Bearer ")
  );

  // 4. Get active sessions for current admin
  const activeSessions = await api.functional.auth.admin.sessions.listActiveSessions(connection);
  typia.assert(activeSessions);
  TestValidator.predicate("sessions array exists and is nonempty")(
    Array.isArray(activeSessions.sessions) && activeSessions.sessions.length >= 1
  );
  for (const session of activeSessions.sessions) {
    typia.assert(session);
    // Check required fields are correct type/format
    TestValidator.predicate("session id is uuid")(
      typeof session.id === "string" && /^[0-9a-fA-F-]{36}$/.test(session.id)
    );
    TestValidator.equals("member_id is consistent with all sessions")(session.member_id)(activeSessions.sessions[0].member_id);
    TestValidator.predicate("provider is present")(
      typeof session.provider === "string" && session.provider.length > 0
    );
    TestValidator.predicate("ip_address present")(
      typeof session.ip_address === "string"
    );
    // timestamps
    TestValidator.predicate("issued_at is date-time string")(
      typeof session.issued_at === "string" &&
        !isNaN(Date.parse(session.issued_at))
    );
    TestValidator.predicate("expires_at is date-time string")(
      typeof session.expires_at === "string" &&
        !isNaN(Date.parse(session.expires_at))
    );
    TestValidator.predicate("created_at is date-time string")(
      typeof session.created_at === "string" &&
        !isNaN(Date.parse(session.created_at))
    );
    TestValidator.predicate("updated_at is date-time string")(
      typeof session.updated_at === "string" &&
        !isNaN(Date.parse(session.updated_at))
    );
    // No revoked sessions
    TestValidator.equals("revoked_at must be null or undefined (active)")(session.revoked_at ?? null)(null);
    // device fingerprint and user-agent can be null or string, basic type check
    if (session.device_fingerprint !== undefined && session.device_fingerprint !== null)
      TestValidator.predicate("device_fingerprint is string or null")(
        typeof session.device_fingerprint === "string"
      );
    if (session.user_agent !== undefined && session.user_agent !== null)
      TestValidator.predicate("user_agent is string or null")(
        typeof session.user_agent === "string"
      );
  }
}

