/**
 * Test session revocation with an invalid sessionId for admin accounts.
 *
 * This scenario validates that the DELETE /auth/admin/sessions/{sessionId} endpoint securely rejects attempts to revoke sessions that do NOT belong to the currently authenticated admin, or which do not exist. It verifies correct error handling and that no collateral effect occurs for valid sessions.
 *
 * Business justification:
 * Admins must only be allowed to revoke their own sessions; cross-account session revocation is a violation of security isolation. Furthermore, using fabricated or unrelated sessionIds must consistently result in not found or unauthorized errors, not successful responses or silent failures.
 *
 * Steps:
 * 1. Register a new admin account (to ensure clean environment).
 * 2. Log in with that admin account to establish an authenticated context.
 * 3. Attempt to DELETE /auth/admin/sessions/{sessionId} with a random UUID (not a real session).
 *    - Expect error: operation should fail (not found/unauthorized).
 * 4. Optionally, attempt again with a sessionId belonging to a different admin (if possible) to confirm cross-account isolation, but this is skipped unless such session can be safely created.
 * 5. Ensure no valid session is revoked by the invalid operation.
 */
export async function test_api_admin_session_revoke_invalid_id(connection: api.IConnection) {
  // 1. Register a new admin account
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signupResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signupResponse);

  // 2. Log in as this admin (to ensure connection.headers are up to date for session-scoped API calls)
  const signinResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signinResponse);

  // 3. Attempt to revoke a session using a random, nonexistent sessionId
  const invalidSessionId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("invalid sessionId must return error")(async () => {
    await api.functional.auth.admin.sessions.revokeSession(connection, { sessionId: invalidSessionId });
  });

  // 4. (Optional, skipped): No valid way to test cross-account revocation without creating a second admin/login & session.
  //    If API someday returns active session listing, this should be expanded to test it.

  // 5. Ensure the admin's session remains valid — try to make an authenticated API call (e.g., redundant login) to prove not revoked.
  const postCheckResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(postCheckResponse);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that invoking the revoke-all endpoint logs out the current admin from all active sessions, regardless of how many times or from how many devices/browsers the same admin has logged in. This confirms global session revocation works as expected for enterprise-level security.
 *
 * Steps:
 * 1. Register a new admin using a unique business email and password. Capture credentials for reuse.
 * 2. Log in as the admin from two simulated sessions (emulated by cloning the connection object):
 *    - Perform two distinct login API calls with the same email/password, simulating different devices/browsers.
 *    - After each login, store the Authorization/refresh tokens returned in each simulated connection.
 * 3. Validate that both authenticated connections (tokens) can successfully call an authenticated endpoint (such as revoke-all).
 * 4. Using the first session, call /auth/admin/tokens/revoke-all to revoke all admin sessions.
 * 5. Assert that:
 *    - The response indicates at least two sessions were revoked and provides their session UUIDs.
 * 6. Attempt to use both connections (tokens) to call an authenticated endpoint (here: revoke-all again):
 *    - Both should now fail (tokens invalidated). Confirm HTTP error is thrown.
 * 7. Log in again using the same credentials. Confirm a new token is issued, and authenticated endpoints work again.
 *
 * This test ensures that token/session invalidation applies to all active tokens, not just the session making the request, providing robust defense in situations like device loss, compromise, or credential reset.
 */
export async function test_api_admin_revoke_all_tokens_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(signUpResp);

  // 2. Simulate multi-session (multi-device) login
  function cloneConnectionWithAuth(setHeaders: IJwtSetHeaders): api.IConnection {
    return {
      ...connection,
      headers: {
        ...connection.headers,
        ...setHeaders,
      },
    };
  }

  const signInResp1 = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(signInResp1);
  const session1 = cloneConnectionWithAuth(signInResp1.setHeaders);

  const signInResp2 = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(signInResp2);
  const session2 = cloneConnectionWithAuth(signInResp2.setHeaders);

  // 3. Both sessions must be able to call an authenticated endpoint successfully
  const testResp1 = await api.functional.auth.admin.tokens.revoke_all.revokeAllTokens(session1);
  typia.assert(testResp1);

  const testResp2 = await api.functional.auth.admin.tokens.revoke_all.revokeAllTokens(session2);
  typia.assert(testResp2);

  // Now login again to obtain fresh tokens (since above calls would have invalidated old ones)
  const signInRespAgain = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(signInRespAgain);
  const sessionAgain = cloneConnectionWithAuth(signInRespAgain.setHeaders);

  // 4. On sessionAgain, call revoke-all to invalidate all tokens (main security action)
  const revokeResult = await api.functional.auth.admin.tokens.revoke_all.revokeAllTokens(sessionAgain);
  typia.assert(revokeResult);
  TestValidator.predicate("multiple sessions revoked")(revokeResult.totalRevoked >= 2);
  TestValidator.equals("session IDs array length")(revokeResult.revokedSessionIds.length)(revokeResult.totalRevoked);

  // 5. After revoke, both pre-existing sessions should fail (tokens become invalid)
  await TestValidator.error("session1 token is revoked, cannot call protected endpoint")(async () => {
    await api.functional.auth.admin.tokens.revoke_all.revokeAllTokens(session1);
  });
  await TestValidator.error("session2 token is revoked, cannot call protected endpoint")(async () => {
    await api.functional.auth.admin.tokens.revoke_all.revokeAllTokens(session2);
  });

  // 6. Fresh login still works
  const recoverySignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(recoverySignIn);
  const freshSession = cloneConnectionWithAuth(recoverySignIn.setHeaders);
  const authResp = await api.functional.auth.admin.tokens.revoke_all.revokeAllTokens(freshSession);
  typia.assert(authResp);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
