/**
 * Validate that an admin can successfully update a consent status record and business rules are enforced.
 *
 * This test verifies the privileged workflow of updating compliance records by an admin, which supports legal audit and correction scenarios by authorized personnel.
 *
 * Steps:
 * 1. Register a new admin and log in to secure authentication/authorization context.
 * 2. Create a new consent status entry so there is a record ready to update.
 * 3. Update a field (e.g., consent_status and audit_trail) using the update API.
 * 4. Validate the returned entity reflects updated values, and immutable fields remain unchanged.
 * 5. (Implicit) Confirm only permitted fields may be modified, and all compliance journaling is proper.
 */
export async function test_api_admin_consent_status_update_successful(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Log in as the created admin
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResponse);

  // 3. Create a sample consent status record
  const createInput: IPolEcoBoardConsentStatus.ICreate = {
    provider_key: "analytics",
    region: "US",
    consent_type: "profiling",
    consent_status: "opt_in",
    session_anon_id: typia.random<string>(),
    audit_trail: JSON.stringify({ action: "creation", timestamp: new Date().toISOString() }),
  };
  const consentStatus = await api.functional.polEcoBoard.admin.consentStatuses.create(connection, { body: createInput });
  typia.assert(consentStatus);

  // 4. Update a field (e.g., consent_status, audit_trail)
  const updateInput: IPolEcoBoardConsentStatus.IUpdate = {
    consent_status: "revoked",
    audit_trail: JSON.stringify({ action: "update", timestamp: new Date().toISOString() }),
  };
  const updated = await api.functional.polEcoBoard.admin.consentStatuses.update(connection, {
    consentStatusId: consentStatus.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 5. Validate business rules
  TestValidator.equals("id should match")(updated.id)(consentStatus.id);
  TestValidator.equals("provider_key should not change")(updated.provider_key)(consentStatus.provider_key);
  TestValidator.equals("region should not change")(updated.region)(consentStatus.region);
  TestValidator.equals("consent_type should not change")(updated.consent_type)(consentStatus.consent_type);
  TestValidator.equals("session_anon_id should not change")(updated.session_anon_id)(consentStatus.session_anon_id);
  TestValidator.equals("consent_status should update")(updated.consent_status)("revoked");
  TestValidator.predicate("audit_trail reflects update")(
    typeof updated.audit_trail === "string" && updated.audit_trail.includes("update")
  );
