 *
 * Steps:
 * 1. Register a new admin account to enable privileged API actions (required for notification provider management).
 * 2. Login as the created admin (attaching auth tokens for subsequent requests).
 * 3. Create a notification provider with a unique provider_key and provider_name.
 * 4. Attempt to create another provider with the same provider_key and a different provider_name (should trigger uniqueness violation).
 * 5. Attempt to create a provider with the same provider_name and a different provider_key (should also trigger uniqueness violation).
 * 6. Confirm that API responds with an error in both duplicate cases, upholding business and schema rules for data integrity.
 */
export async function test_api_admin_notification_provider_create_duplicate_error(
  connection: api.IConnection,
) {
  // 1. Register a new admin account (required for privileged actions)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12); // must satisfy minLength 8
  const registration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registration);

  // 2. Login as admin (ensure Authorization attached for subsequent calls)
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(login);

  // 3. Create a notification provider with unique key and name
  const baseProviderName = "TestProvider-" + RandomGenerator.alphaNumeric(6);
  const baseProviderKey = "test-key-" + RandomGenerator.alphaNumeric(6);
  const providerFields: IPolEcoBoardNotificationProvider.ICreate = {
    provider_name: baseProviderName,
    provider_key: baseProviderKey,
    channels_supported: "email,sms", // minimal formats for testing
    endpoint_uri: "https://api.testprovider.com/integration",
    region: "US",
    status: "active",
    config_metadata: '{}',
  };
  const createdProvider = await api.functional.polEcoBoard.admin.notificationProviders.create(connection, {
    body: providerFields,
  });
  typia.assert(createdProvider);

  // 4. Attempt to create a provider with the SAME provider_key (should fail)
  const duplicateKeyFields: IPolEcoBoardNotificationProvider.ICreate = {
    ...providerFields,
    provider_name: baseProviderName + "_dupe", // change name, key is duplicated
  };
  await TestValidator.error("should error: duplicate provider_key")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationProviders.create(connection, {
        body: duplicateKeyFields,
      });
