/**
 * Validate admin-only retrieval of post details, including error and access control scenarios.
 *
 * This test ensures:
 * 1. Admins can successfully fetch detail for an existing post.
 * 2. An explicit error is thrown when attempting to fetch a non-existent post.
 * 3. Members (and by analogy, other non-admins) are forbidden from accessing the admin-only endpoint.
 *
 * Workflow:
 * - Register and authenticate an admin.
 * - Register and authenticate a member.
 * - Member creates a post (retain postId for later retrieval).
 * - Admin retrieves the post detail by ID (should succeed, and returned data matches what was created).
 * - Admin attempts to retrieve a non-existent postId (should yield a not found error).
 * - Member (now re-authenticated) attempts to access the admin-only detail endpoint (should yield a forbidden error or similar access denial).
 */
export async function test_api_admin_post_detail_access_success_and_errors(
  connection: api.IConnection,
) {
  // Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  // Authenticate as admin (get admin token)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  // Authenticate as member (get member token)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // Member creates a post (must supply valid category_id, title, body; tags/attachments optional)
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()().slice(0, 50),
    body: RandomGenerator.content()()().slice(0, 200),
    tag_ids: [],
    attachments: [],
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);

  // Re-authenticate as admin before admin API access
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 1. Admin retrieves the existing post detail by ID
  const fetched = await api.functional.polEcoBoard.admin.posts.at(connection, {
    postId: post.id,
  });
  typia.assert(fetched);
  TestValidator.equals("admin can view posted content")(fetched.id)(post.id);
  TestValidator.equals("admin detail fields: category")(fetched.category_id)(postInput.category_id);
  TestValidator.equals("admin detail fields: title")(fetched.title)(postInput.title);
  TestValidator.equals("admin detail fields: body")(fetched.body)(postInput.body);
  TestValidator.equals("admin detail comment count")(fetched.comment_count)(0);

  // 2. Admin tries non-existent postId (should fail with not found or error)
  await TestValidator.error("admin receives not-found for unknown post")(
    async () =>
      await api.functional.polEcoBoard.admin.posts.at(connection, {
        postId: typia.random<string & tags.Format<"uuid">>(), // random and likely unused
      })
  );

  // 3. Member tries to access admin-only endpoint (should get forbidden)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  await TestValidator.error("member forbidden to access admin-detail endpoint")(
    async () =>
      await api.functional.polEcoBoard.admin.posts.at(connection, {
        postId: post.id,
      })
  );
}

