import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test hard deletion of an authentication session by an admin.
 *
 * Business context: Only privileged admins are allowed to perform hard deletion of authentication sessions for incident response, compliance, or manual cleanup. Once deleted, the session must be irreversibly removed – no further use is possible. The test verifies audit compliance and business logic integrity.
 *
 * Step-by-step process:
 * 1. Register a new admin account to trigger session creation.
 * 2. Authenticate as this admin to obtain valid session/authorization tokens.
 * 3. Extract the admin's current authentication session ID (from the JWT setHeaders or via the API interface if possible).
 * 4. Hard-delete the just-created session using the admin capability API, referenced by the session ID.
 * 5. Assert the request succeeds (HTTP 200/204 or no error thrown).
 * 6. Attempt to perform an API call with the now-deleted session credentials and expect denial (i.e., token no longer accepted or session not found).
 * 7. If possible, verify audit log reflects the deletion action (this is out-of-scope if no endpoint/audit fetch is available).
 */
export async function test_api_auth_session_delete_success(connection: api.IConnection) {
  // 1. Register a new admin account to trigger session creation
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResp);
  TestValidator.predicate("authorization header exists after register")(typeof registerResp.setHeaders?.Authorization === "string" && registerResp.setHeaders.Authorization.length > 0);

  // 2. Login as the admin to obtain an active session (should issue setHeaders.Authorization)
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);
  TestValidator.predicate("authorization header exists after login")(typeof loginResp.setHeaders?.Authorization === "string" && loginResp.setHeaders.Authorization.length > 0);

  // 3. Extract the admin's current authentication session ID from JWT
  //    Assume Bearer <jwt> and that the payload.jti is the session UUID
  const jwt = loginResp.setHeaders.Authorization.split(" ")[1];
  const payloadBase64 = jwt.split(".")[1];
  const jwtPayload = JSON.parse(Buffer.from(payloadBase64, "base64").toString("utf8"));
  const authSessionId = jwtPayload.jti as string;
  TestValidator.predicate("session id is a nonempty uuid string")(typeof authSessionId === "string" && authSessionId.length > 10);

  // 4. Hard-delete the authentication session using the admin endpoint and the extracted session id
  await api.functional.polEcoBoard.admin.authSessions.erase(connection, {
    authSessionId,
  });

  // 5. Attempt to use the deleted session for a privileged endpoint; must fail
  connection.headers = { ...connection.headers, Authorization: `Bearer ${jwt}` };
  await TestValidator.error("requests with deleted session must fail")(async () => {
    await api.functional.auth.admin.login.signIn(connection, {
      body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
    });
  });

  // 6. (Audit log verification skipped, as endpoint is not exposed)
}

