import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin can retrieve details of any comment on any post, including regular, flagged, and deleted comments (to the extent possible with available APIs), and receives correct errors on missing/unauthorized comment combinations.
 *
 * ## Business Context
 * Admins are responsible for audit, moderation, and compliance across all posts and comments. This test ensures that the privileged GET endpoint for comment detail provides all business, moderation, and audit fields for any given comment.
 *
 * ## Steps:
 * 1. Register a new admin account with a unique email and password.
 * 2. Login as admin, acquiring a session for authenticated, privileged requests.
 * 3. Create a new post for the comment to attach to (as allowed by the current authentication context).
 * 4. Create a new comment under the created post using the member comment creation API.
 * 5. Retrieve the comment as admin using the privileged detail endpoint, confirming all audit/metadata fields (id, post_id, author_member_id, flagged, deleted_at, etc.) and check population of correct values (including nulls and booleans where appropriate).
 * 6. Attempt to access a non-existent commentId under the real post, expect a not-found error.
 * 7. Attempt to access a real comment under a non-existent postId, expect a not-found or forbidden error.
 * 8. Attempt to access a real comment under an unrelated, valid postId, expect forbidden/not-found error.
 */
export async function test_api_admin_comment_detail_view_and_access_errors(connection: api.IConnection) {
  // 1. Register a new admin (admin role required for privileged comment access)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Login as admin
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);
  // The SDK should update connection.headers.Authorization after login

  // 3. Create a post (as admin or as member if required; only member create API is available)
  // NOTE: No member registration API provided, so this is performed in the admin session.
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(15);
  const postBody = RandomGenerator.content()(100)();
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(createdPost);

  // 4. Create a comment under the post (same authentication context)
  const commentBody = RandomGenerator.paragraph()(8);
  const createdComment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: createdPost.id,
    body: {
      body: commentBody,
      parent_comment_id: null
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(createdComment);

  // 5. Retrieve the comment as admin (should include all moderation/audit fields)
  const adminComment = await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
    postId: createdPost.id,
    commentId: createdComment.id,
  });
  typia.assert(adminComment);
  TestValidator.equals("body matches")(adminComment.body)(createdComment.body);
  TestValidator.equals("flagged - should be false for new comment")(adminComment.flagged)(false);
  TestValidator.equals("deleted_at - should be null for active comment")(adminComment.deleted_at)(null);
  TestValidator.equals("post_id matches")(adminComment.post_id)(createdPost.id);
  TestValidator.equals("id matches")(adminComment.id)(createdComment.id);
  TestValidator.predicate("author_member_id populated")(typeof adminComment.author_member_id === "string" && adminComment.author_member_id.length > 0);
  TestValidator.predicate("created_at populated")(typeof adminComment.created_at === "string" && adminComment.created_at.length > 0);
  TestValidator.predicate("updated_at populated")(typeof adminComment.updated_at === "string" && adminComment.updated_at.length > 0);

  // 6. Error: request with non-existent commentId
  const randomCommentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should fail for non-existent commentId")(async () =>
    await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
      postId: createdPost.id,
      commentId: randomCommentId
    })
  );

  // 7. Error: request with non-existent postId
  const randomPostId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should fail for non-existent postId")(async () =>
    await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
      postId: randomPostId,
      commentId: createdComment.id
    })
  );

  // 8. Error: mismatched but valid postId and commentId (comment doesn't belong to post)
  const otherPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()(80)(),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(otherPost);
  TestValidator.error("should fail for mismatched post and comment")(async () =>
    await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
      postId: otherPost.id,
      commentId: createdComment.id
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test that a registered member can create a new comment under an active post and validate both successful and invalid cases.
 *
 * This test ensures the API correctly allows authenticated members to post comments with valid input, supports replies (parent_comment_id), and enforces validation on comment properties and authentication status. The below process covers workflow and error scenarios:
 *
 * 1. Register a member with a random email and password.
 * 2. Login as that member and apply the returned JWT header into the connection for authentication.
 * 3. Create a new post as the member (category_id, title, body).
 * 4. Create a top-level comment with a valid body (length 5 to 1000 chars); expect success, check returned comment fields and author.
 * 5. Create a reply (child comment) under the first comment, using parent_comment_id; expect success, verify reply fields and linkage.
 * 6. Attempt to create a comment with an empty body or body shorter than 5 chars; expect error.
 * 7. Attempt to create a comment with an overly long body (>1000 chars); expect error.
 * 8. Attempt to reply with an invalid parent_comment_id (random UUID not existing); expect error.
 * 9. Remove authorization (simulate unauthenticated user) and attempt to create a comment; expect authentication error.
 */
export async function test_api_member_create_comment_success_and_validation_errors(
  connection: api.IConnection,
) {
  // 1. Register member
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword12345!";
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);

  // 2. Login to retrieve token and set in connection
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);
  connection.headers = {
    ...connection.headers,
    Authorization: signInResult.setHeaders.Authorization,
  };

  // 3. Create post (category_id, title, body): use valid random values
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.alphabets(20),
    body: RandomGenerator.alphabets(100),
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 4. Create top-level comment with valid body
  const commentInput: IPolEcoBoardComment.ICreate = {
    body: RandomGenerator.alphabets(25),
  };
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: commentInput,
  });
  typia.assert(comment);
  TestValidator.equals("post id matches on comment")(comment.post_id)(post.id);
  TestValidator.equals("parent_comment_id null for top-level")(comment.parent_comment_id)(null);
  TestValidator.equals("body matches on comment")(comment.body)(commentInput.body);

  // 5. Create reply by setting parent_comment_id
  const replyInput: IPolEcoBoardComment.ICreate = {
    body: RandomGenerator.alphabets(50),
    parent_comment_id: comment.id,
  };
  const reply = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: replyInput,
  });
  typia.assert(reply);
  TestValidator.equals("parent_comment_id on reply")(reply.parent_comment_id)(comment.id);
  TestValidator.equals("body matches on reply")(reply.body)(replyInput.body);

  // 6. Attempt comment with invalid/empty body (too short)
  await TestValidator.error("body too short should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: { body: "h" },
    })
  );

  // 7. Attempt comment with body too long
  await TestValidator.error("body too long should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: { body: "x".repeat(1001) },
    })
  );

  // 8. Attempt reply with invalid parent_comment_id
  await TestValidator.error("invalid parent_comment_id should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: RandomGenerator.alphabets(20),
        parent_comment_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 9. Remove Authorization header and attempt unauthenticated comment
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthenticated comment should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(unauthConn, {
      postId: post.id,
      body: { body: RandomGenerator.alphabets(10) },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can create comments under any post, including posts that are flagged, locked, or archived if business rules permit moderator override.
 *
 * This includes positive cases (regular, flagged, locked, archived) and negative cases (deleted post or lock that blocks all).
 * Also verify proper audit records/metadata are present on the created comment.
 *
 * Steps:
 * 1. Register a moderator account
 * 2. Log in as moderator
 * 3. Create a regular post (as member, but since only moderator/member flows are available in this E2E, use moderator JWT)
 * 4. (Positive) Add comment to active/regular post as moderator (should succeed)
 * 5. (Positive) Set post status to 'locked' and add comment as moderator (should succeed due to privileged override)
 * 6. (Positive) Set post status to 'archived' and add comment as moderator (should succeed if permitted)
 * 7. (Negative) Try to add comment to a deleted/nonexistent post as moderator (should fail)
 * 8. (Negative) If business rules supported a non-overridable lock type, test block (skipped as not present)
 * 9. After each successful comment, assert audit data: audit trail fields set, author is moderator, correct postId, etc.
 */
export async function test_api_moderator_create_comment_with_privileged_post_access(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderatorPassword = "SuperStrongPassword1!";
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1";
  const registrationResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registrationResp);
  const moderatorId = registrationResp.moderatorId;

  // 2. Log in as moderator
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResp);
  TestValidator.equals("Moderator identity matches")(loginResp.moderatorId)(moderatorId);

  // 3. Create a test post as member (using moderator JWT because only moderator flows are available)
  const categoryId = typia.random<string & tags.Format<'uuid'>>();
  const postTitle = RandomGenerator.paragraph(1)();
  const postBody = RandomGenerator.content()(10, 20)();
  const postResp = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postResp);
  const postId = postResp.id;

  // 4. Add comment to regular/active post (should succeed)
  const commentBody1 = RandomGenerator.content()(5, 10)();
  const comment1 = await api.functional.polEcoBoard.moderator.posts.comments.create(connection, {
    postId,
    body: { body: commentBody1 } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment1);
  TestValidator.equals("Regular: comment post_id matches")(comment1.post_id)(postId);
  TestValidator.equals("Regular: moderator authored")(comment1.author_member_id)(loginResp.moderatorId);
  TestValidator.predicate("Audit trail: created_at present")(typeof comment1.created_at === "string");
  TestValidator.predicate("Audit trail: updated_at present")(typeof comment1.updated_at === "string");
  TestValidator.predicate("Flagged field is boolean")(typeof comment1.flagged === "boolean");

  // 5. Set post status to 'locked' and add comment as moderator (should succeed due to moderator privilege)
  const lockStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: postId,
      actor_moderator_id: moderatorId,
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: "Test lock as moderator",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(lockStatus);

  const commentBody2 = RandomGenerator.content()(5, 10)();
  const comment2 = await api.functional.polEcoBoard.moderator.posts.comments.create(connection, {
    postId,
    body: { body: commentBody2 } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment2);
  TestValidator.equals("Locked: comment post_id matches")(comment2.post_id)(postId);
  TestValidator.equals("Locked: moderator authored")(comment2.author_member_id)(loginResp.moderatorId);
  TestValidator.predicate("Locked: created_at tz")(typeof comment2.created_at === "string");
  TestValidator.predicate("Locked: updated_at tz")(typeof comment2.updated_at === "string");
  TestValidator.predicate("Locked: flagged boolean")(typeof comment2.flagged === "boolean");

  // 6. Set post status to 'archived' and add comment as moderator (should succeed if software allows)
  const archiveStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: postId,
      actor_moderator_id: moderatorId,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "Test archive as moderator",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
