/**
 * Validate admin ability to update a post report in polEcoBoard.
 *
 * This test performs and verifies the full workflow for admin report moderation:
 *  1. Register a member.
 *  2. Register a new admin account.
 *  3. Login as admin for authorization to update the report.
 *  4. Login as member for post/report flows.
 *  5. Member creates a post.
 *  6. Member reports the post.
 *  7. Switch to admin, update the report (change reason/code/notes).
 *  8. Validate that the update is applied and that only a privileged user can perform this.
 *
 * Steps require session switching via Authorization headers (from returned setHeaders), to mimic real authentication transitions between member/admin.
 */
export async function test_api_post_report_update_admin_happy_path(connection: api.IConnection) {
  // 1. Register a member user
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });
  typia.assert(memberReg);
  connection.headers = { ...connection.headers, ...memberReg.setHeaders };

  // 2. Register an admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!E2EPass2025";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminReg);

  // 3. Login as admin to fetch Authorization JWT for admin API
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminLogin);
  connection.headers = { ...connection.headers, ...adminLogin.setHeaders };

  // 4. Switch back to member session for post/report
  const memberReAuth = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });
  typia.assert(memberReAuth);
  connection.headers = { ...connection.headers, ...memberReAuth.setHeaders };

  // 5. Member creates a new post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "E2E: Test post for admin report update",
      body: "Automated E2E test post content for admin update path."
    }
  });
  typia.assert(post);

  // 6. Member reports the new post
  const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: post.id,
    body: {
      reason_code: "abuse",
      reason_description: "Flagged for moderation in E2E admin test.",
      post_id: post.id,
      comment_id: null
    }
  });
  typia.assert(report);

  // 7. Switch to admin session for updating the report
  connection.headers = { ...connection.headers, ...adminLogin.setHeaders };

  // Perform update: change reason and moderation notes
  const updatedReason = "hate";
  const updatedDescription = "Moderation complete: test admin updated this report.";
  const updated = await api.functional.polEcoBoard.admin.posts.reports.update(connection, {
    postId: post.id,
    reportId: report.id,
    body: {
      reason_code: updatedReason,
      reason_description: updatedDescription
    }
  });
  typia.assert(updated);

  // 8. Validate update
  TestValidator.equals("reason_code updated")(updated.reason_code)(updatedReason);
  TestValidator.equals("description updated")(updated.reason_description)(updatedDescription);
  TestValidator.equals("report id")(updated.id)(report.id);
  TestValidator.equals("post id")(updated.post_id)(report.post_id);
}

