  if (someTag && someTag.name.length >= 2) {
    const partial = someTag.name.slice(0, 2);
    const filteredName = await api.functional.polEcoBoard.tags.search(connection, { body: { name: partial } });
    typia.assert(filteredName);
    TestValidator.predicate("tags should contain name substring")(
      filteredName.data.every(t => t.name.includes(partial))
    );
  }

  // 3. Filter by exact slug
  if (someTag) {
    const filteredSlug = await api.functional.polEcoBoard.tags.search(connection, { body: { slug: someTag.slug } });
    typia.assert(filteredSlug);
    TestValidator.predicate("all tags have exact slug")(
      filteredSlug.data.every(t => t.slug === someTag.slug)
    );
    if (filteredSlug.data.length > 0) {
      TestValidator.equals("filtered slug returns one record")(filteredSlug.data[0].slug)(someTag.slug);
    }
  }

  // 4. Pagination test: page=2, limit=1 (meaningful only if there are >=2)
  if (unfiltered.data.length > 1) {
    const paginated = await api.functional.polEcoBoard.tags.search(connection, { body: { page: 2, limit: 1 } });
    typia.assert(paginated);
    TestValidator.equals("limit respected")(paginated.data.length)(1);
    TestValidator.equals("current page")(paginated.pagination.current)(2);
  }

  // 5. Edge: Nonexistent tag name
  const noResult = await api.functional.polEcoBoard.tags.search(connection, { body: { name: "nonexistent-auto-be-test-tag" } });
  typia.assert(noResult);
  TestValidator.equals("no data for nonexistent tag")(noResult.data.length)(0);

  // 6. Edge: Invalid pagination (page=0, limit=1000)
  const invalidPage = await api.functional.polEcoBoard.tags.search(connection, { body: { page: 0, limit: 1000 } });
  typia.assert(invalidPage);
  TestValidator.predicate("page >= 1")(invalidPage.pagination.current >= 1);
  TestValidator.predicate("limit reasonable")(invalidPage.pagination.limit <= 100);
}

