 * 2. Log in as that admin to obtain an authentication token
 * 3. Create a new service metric record (to use as update target)
 * 4. Update the service metric using the admin account; modify window dates and attach operational notes
 * 5. Confirm that:
 *    - The updated record reflects the new window and notes data
 *    - Unchanged fields are still correct and persistent
 *    - Audit fields (updated_at) are modified and after created_at
 *
 * Test covers correctness, persistency, audit trail policy, and admin-only authorization for update.
 */
export async function test_api_service_metric_update_successful_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
