 *
 * This test validates that the API correctly returns all information about a specific business report when accessed by an authenticated admin user. Steps include registering a new admin, logging in as that admin, creating a business report, and then fetching it by ID to ensure all data matches what was created.
 *
 * 1. Register an admin account using valid, unique credentials.
 * 2. Log in as that admin to acquire authentication headers.
 * 3. Create a business report using unique, realistic data.
 * 4. Fetch the report by businessReportId using the GET endpoint.
 * 5. Assert that the fetched report's data matches the originally created report.
 */
export async function test_api_business_report_fetch_valid_id(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(signUpRes);

  // 2. Log in as the admin
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(signInRes);

  // 3. Create a business report
  const now = new Date();
  const input: IPolEcoBoardBusinessReport.ICreate = {
    report_code: RandomGenerator.alphaNumeric(8) + "-BRPT",
    report_type: RandomGenerator.pick([
      "METRICS",
      "AUDIT",
      "INCIDENTS",
      "EXPORT",
      "SLA",
      "LEGAL",
      "COMPLIANCE"
    ]),
    status: RandomGenerator.pick(["PENDING", "COMPLETED", "FAILED", "DELIVERED"]),
    requested_by_id: typia.random<string & tags.Format<"uuid">>(),
    content_uri: `https://s3.example.com/reports/${RandomGenerator.alphaNumeric(12)}.pdf`,
    triggered_at: now.toISOString(),
    delivered_at: null,
    failure_reason: null
  };
  const createRes = await api.functional.polEcoBoard.admin.businessReports.create(connection, {
    body: input
