  TestValidator.equals("content_uri matches")(fetchedReport.content_uri)(input.content_uri);
  TestValidator.equals("triggered_at matches")(fetchedReport.triggered_at)(input.triggered_at);
  TestValidator.equals("failure_reason matches")(fetchedReport.failure_reason)(input.failure_reason);
}

