import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardBusinessReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBusinessReport";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate enforcement of uniqueness constraint on business report creation (report_code).
 *
 * This test ensures the API prohibits the creation of two business reports with the same report_code. It mimics a scenario where an admin (registered and logged in) creates a business report and then attempts to create another with an identical report_code. The second attempt must fail at the business logic layer due to violation of the uniqueness constraint, resulting in an error. This check is critical to guarantee data integrity for business reporting.
 *
 * Steps:
 * 1. Register an admin account with unique credentials
 * 2. Log in as the created admin (to set Authorization header etc.)
 * 3. Construct a valid IPolEcoBoardBusinessReport.ICreate object with a random report_code
 * 4. Successfully create the first business report with this code
 * 5. Attempt to create a second business report with the exact same report_code (but possibly other random fields)
 * 6. Validate that the second call results in a business error (e.g. duplicate violation)
 */
export async function test_api_business_report_creation_duplicate_code(connection: api.IConnection) {
  // 1. Register admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminSignUpResp);

  // 2. Login with the same admin account (set Authorization header)
  const adminSignInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(adminSignInResp);

  // 3. Prepare business report create payload (random with known report_code)
  const reportCode = RandomGenerator.alphaNumeric(10);
  const requestedById = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const firstCreateBody: IPolEcoBoardBusinessReport.ICreate = {
    report_code: reportCode,
    report_type: "METRICS",
    status: "PENDING",
    requested_by_id: requestedById,
    content_uri: `s3://bucket/reports/${reportCode}`,
    triggered_at: now,
    delivered_at: null,
    failure_reason: null
  };

  // 4. Create first business report
  const firstReport = await api.functional.polEcoBoard.admin.businessReports.create(connection, { body: firstCreateBody });
  typia.assert(firstReport);
  TestValidator.equals("First report code matches")(firstReport.report_code)(reportCode);

  // 5. Attempt duplicate creation with the same report_code
  const secondCreateBody: IPolEcoBoardBusinessReport.ICreate = {
    ...firstCreateBody,
    // Optionally, change some fields except report_code
    triggered_at: new Date(Date.now() + 60000).toISOString(),
    content_uri: `s3://bucket/reports/${reportCode}-dupe`
  };
  await TestValidator.error("Duplicate report_code should fail")(() =>
    api.functional.polEcoBoard.admin.businessReports.create(connection, { body: secondCreateBody })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAnalyticsEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAnalyticsEvent";
import type { IPageIPolEcoBoardAnalyticsEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAnalyticsEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate pagination, filtering, and permission logic for analytics event search by admin.
 *
 * This test checks coherent business logic and error handling for searching analytics events as admin:
 * 1. Register and login as admin, persist JWT headers
 * 2. Create distinct analytics events with varied event_type, user_role, and region
 * 3. Test paginated search with various filters and sort parameters, verifying expected data is returned and summaries omit sensitive details
 * 4. Confirm correct error response for invalid filters
 * 5. Confirm permission denied for unauthenticated requests
 *
 * Non-admin user case is omitted (no such API/token in current SDK)
 */
export async function test_api_analytics_events_pagination_and_filtering_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResp);
  TestValidator.predicate("register returns Authorization")(
    !!registerResp.setHeaders?.Authorization && typeof registerResp.setHeaders.Authorization === "string",
  );

  // 2. Login as admin and persist Authorization header
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);
  TestValidator.predicate("login returns Authorization")(
    !!loginResp.setHeaders?.Authorization && typeof loginResp.setHeaders.Authorization === "string",
  );
  // Set login Authorization token for subsequent requests (overwrites connection headers, which is automatic in E2E framework)

  // 3. Create at least 3 analytics events with different values
  const event_values = [
    {
      event_type: "page_view",
      user_role: "guest",
      region: "US",
      details_word: "alpha",
    },
    {
      event_type: "login",
      user_role: "member",
      region: "EU",
      details_word: "beta",
    },
    {
      event_type: "moderation_action",
      user_role: "admin",
      region: "KR",
      details_word: "gamma",
    },
  ];

  const now = new Date();
  const events: IPolEcoBoardAnalyticsEvent[] = [];
  for (let i = 0; i < event_values.length; ++i) {
    const v = event_values[i];
    const ev = await api.functional.polEcoBoard.admin.analyticsEvents.create(connection, {
      body: {
        event_type: v.event_type,
        session_anon_id: RandomGenerator.alphaNumeric(16),
        user_role: v.user_role,
        event_details: JSON.stringify({ info: v.details_word }),
        region: v.region,
        created_at: new Date(now.getTime() - i * 60000).toISOString(),
      } satisfies IPolEcoBoardAnalyticsEvent.ICreate,
    });
    typia.assert(ev);
    events.push(ev);
  }

  // 4.a. Filter by event_type
  const searchByType = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: "login",
      user_role: null,
      session_anon_id: null,
      region: null,
      created_from: null,
      created_to: null,
      keyword: null,
      page: 1,
      limit: 10,
      sort_by: null,
      sort_direction: null,
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(searchByType);
  TestValidator.predicate("only login event_type returned")(
    searchByType.data.every(ev => ev.event_type === "login"),
  );

  // 4.b. Filter by user_role
  const searchByRole = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: null,
      user_role: "guest",
      session_anon_id: null,
      region: null,
      created_from: null,
      created_to: null,
      keyword: null,
      page: 1,
      limit: 10,
      sort_by: null,
      sort_direction: null,
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(searchByRole);
  TestValidator.predicate("only guest user_role")(
    searchByRole.data.every(ev => ev.user_role === "guest"),
  );

  // 4.c. Filter by date range (inclusive from, exclusive to)
  const min_dt = events[1].created_at;
  const max_dt = events[0].created_at;
  const searchByDate = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: null,
      user_role: null,
      session_anon_id: null,
      region: null,
      created_from: min_dt,
      created_to: max_dt,
      keyword: null,
      page: 1,
      limit: 10,
      sort_by: null,
      sort_direction: null,
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(searchByDate);
  TestValidator.predicate("created_at within min_dt <= x < max_dt")(
    searchByDate.data.every(ev =>
      new Date(ev.created_at) >= new Date(min_dt) && new Date(ev.created_at) < new Date(max_dt),
    ),
  );

  // 4.d. Filter by keyword (event_details JSON string contains it)
  const searchByKeyword = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: null,
      user_role: null,
      session_anon_id: null,
      region: null,
      created_from: null,
      created_to: null,
      keyword: "alpha",
      page: 1,
      limit: 10,
      sort_by: null,
      sort_direction: null,
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(searchByKeyword);
  TestValidator.predicate("keyword alpha present in event_details")(
    searchByKeyword.data.some(ev => ev.event_type === "page_view"),
  );

  // 4.e. Pagination test: limit = 2, should get both pages covering all events
  const searchPage1 = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: null,
      user_role: null,
      session_anon_id: null,
      region: null,
      created_from: null,
      created_to: null,
      keyword: null,
      page: 1,
      limit: 2,
      sort_by: null,
      sort_direction: null,
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(searchPage1);
  TestValidator.equals("limit of 2")(
    searchPage1.pagination.limit,
  )(2);
  TestValidator.equals("page 1")(
    searchPage1.pagination.current,
  )(1);
  TestValidator.predicate("<= limit")(
    searchPage1.data.length <= 2,
  );

  const searchPage2 = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: null,
      user_role: null,
      session_anon_id: null,
      region: null,
      created_from: null,
      created_to: null,
      keyword: null,
      page: 2,
      limit: 2,
      sort_by: null,
      sort_direction: null,
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(searchPage2);
  TestValidator.equals("page 2")(
    searchPage2.pagination.current,
  )(2);

  // All data together should cover all created events (ignoring extra data if present in system)
  const pageEvents = [
    ...searchPage1.data,
    ...searchPage2.data,
  ];
  TestValidator.predicate("union covers 3 ids")(
    events.every(e => pageEvents.some(ev => ev.id === e.id)),
  );

  // 4.f. Sort by created_at asc
  const sortAsc = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: null,
      user_role: null,
      session_anon_id: null,
      region: null,
      created_from: null,
      created_to: null,
      keyword: null,
      page: 1,
      limit: 10,
      sort_by: "created_at",
      sort_direction: "asc",
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(sortAsc);
  TestValidator.predicate("monotonically increasing created_at")(
    sortAsc.data.every((ev, i, arr) =>
      i === 0 || ev.created_at >= arr[i - 1].created_at,
    ),
  );

  // 4.f. Sort by event_type desc
  const sortTypeDesc = await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
    body: {
      event_type: null,
      user_role: null,
      session_anon_id: null,
      region: null,
      created_from: null,
      created_to: null,
      keyword: null,
      page: 1,
      limit: 10,
      sort_by: "event_type",
      sort_direction: "desc",
    } satisfies IPolEcoBoardAnalyticsEvent.IRequest,
  });
  typia.assert(sortTypeDesc);
  TestValidator.predicate("monotonically decreasing event_type")(
    sortTypeDesc.data.every((ev, i, arr) =>
      i === 0 || ev.event_type <= arr[i - 1].event_type,
    ),
  );

  // For all returned data, ensure only summary fields are present (no sensitive info in ISummary)
  for (const group of [
    searchByType.data,
    searchByRole.data,
    searchByDate.data,
    searchByKeyword.data,
    searchPage1.data,
    searchPage2.data,
    sortAsc.data,
    sortTypeDesc.data,
  ]) {
    for (const ev of group) {
      // id, event_type, user_role, region, created_at only
      TestValidator.predicate("only ISummary fields present")(
        Object.keys(ev).sort().join(",") ===
          ["created_at", "event_type", "id", "region", "user_role"].sort().join(","),
      );
    }
  }

  // 5. Invalid filter value: non-integer page
  await TestValidator.error("invalid non-integer page")(
    async () =>
      await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
        body: {
          event_type: null,
          user_role: null,
          session_anon_id: null,
          region: null,
          created_from: null,
          created_to: null,
          keyword: null,
          page: "XX" as unknown as number, // intentionally invalid
          limit: 10,
          sort_by: null,
          sort_direction: null,
        } as any,
      }),
  );

  // 5. Invalid filter value: bad sort_direction
  await TestValidator.error("invalid sort_direction")(
    async () =>
      await api.functional.polEcoBoard.admin.analyticsEvents.search(connection, {
        body: {
          event_type: null,
          user_role: null,
          session_anon_id: null,
          region: null,
          created_from: null,
          created_to: null,
          keyword: null,
          page: 1,
          limit: 10,
          sort_by: null,
          sort_direction: "foobar" as any, // invalid
        } as any,
      }),
  );

  // 6. Unauthenticated access
  const anonConnection: api.IConnection = {
    ...connection,
    headers: {}, // no Authorization
  };
  await TestValidator.error("unauthenticated forbidden")(
    async () =>
      await api.functional.polEcoBoard.admin.analyticsEvents.search(anonConnection, {
        body: {
          event_type: null,
          user_role: null,
          session_anon_id: null,
          region: null,
          created_from: null,
          created_to: null,
          keyword: null,
          page: 1,
