  TestValidator.equals("correct comment id")(editRecord.comment_id)(comment.id);

  // 9. (Optional) editor_member_id = moderator would be checked here if exposed (not available)

  // 10. Attempt update to non-existent editId should throw
  await TestValidator.error("non-existent edit id")(() =>
