 * 3. Create a member user to serve as the subject for a role transition.
 * 4. Create a new role transition for this member (e.g., promote to moderator), using a test admin/member id as the approver.
 * 5. Use the delete endpoint to logically remove (soft delete) the role transition by its unique ID.
 * 6. Attempt to delete the same role transition again and confirm an appropriate error occurs (e.g., not found or already deleted).
 * 7. Attempt to delete a randomly generated (non-existent) role transition ID and confirm an error is returned.
 *
 * Validates: admin authentication control; role transition creation; logical deletion by admin; appropriate error signaling for deletion of missing/invalid/previously deleted records.
 */
export async function test_api_role_transition_deletion_success_and_not_found(connection: api.IConnection) {
