  });

  // 2. Login as admin to acquire JWT for authentication
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const member: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(32),
      display_name: memberDisplayName,
      consent_status: "agree-v1",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Create role transition for that member (use member.id as approver test value for coverage)
  const roleTransition: IPolEcoBoardRoleTransition = await api.functional.polEcoBoard.admin.roleTransitions.create(connection, {
    body: {
      account_id: member.id,
      approved_by_admin_id: member.id, // For test, use member.id as dummy admin id
      origin_role: "member",
      destination_role: "moderator",
      reason: "Promotion for moderation",
      status: "completed",
      requested_at: new Date().toISOString(),
    } satisfies IPolEcoBoardRoleTransition.ICreate,
  });
