import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate audit log searching with filters and pagination as an admin.
 *
 * This test ensures that admin users can:
 * 1. Register and authenticate properly as admins, and perform actions that generate audit events (e.g., member registration, privilege change).
 * 2. Search the audit log using the dedicated endpoint with various filters (action_type, actor, date ranges), and with pagination controls (limit/page).
 * 3. Validate that results are correct: the returned audit summaries must match the filters (action types, date ranges, actors), and the total results and pages reflect correct pagination.
 * 4. Attempt a query with an invalid filter to confirm proper error handling from the API.
 *
 * Steps:
 * 1. Register a new admin via /auth/admin/register (generates admin; also a member; this should also generate at least one audit event for account creation).
 * 2. Login as admin via /auth/admin/login (session token is auto-managed).
 * 3. Register one or more member accounts via /polEcoBoard/members (generates member(s), and several audit events for creates).
 * 4. (If permitted) Use /polEcoBoard/admin/accountAudits.post to create bespoke manual audit entries (to test filtering specific entries).
 * 5. As admin, search audits via /polEcoBoard/admin/accountAudits.patch:
 *    - a. With no filters: Should return all available audits (at least those above), sorted as expected.
 *    - b. With actor_id filter (admin or created member), should only see audits where actor matches.
 *    - c. With action_type filter ("create", "update", etc), should only see matching types.
 *    - d. With occurred_after/occurred_before: date range filtering should work.
 *    - e. With page/limit: pagination returns only correct sublists, with accurate pagination metadata.
 *    - f. With invalid action_type (string not in enum): should receive a descriptive error.
 */
export async function test_api_account_audit_search_filtering_and_pagination(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(signUpResponse);

  // 2. Login as admin
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(signInResponse);

  // 3. Register members
  const members = await ArrayUtil.asyncRepeat(3)(async () => {
    const member = await api.functional.polEcoBoard.members.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        profile_image_uri: null,
        consent_status: "v1"
      } satisfies IPolEcoBoardMember.ICreate
    });
    typia.assert(member);
    return member;
  });

  // 4. Create a manual audit event
  const auditManual = await api.functional.polEcoBoard.admin.accountAudits.create(connection, {
    body: {
      action_type: "privilege_escalation",
      actor_id: members[0].id,
      target_account_id: members[1].id,
      action_metadata: "Promoted user to moderator",
      event_source: "api-test",
      status: "success",
      occurred_at: new Date().toISOString()
    } satisfies IPolEcoBoardAccountAudit.ICreate
  });
  typia.assert(auditManual);

  // 5.a. Search all audits (no filter)
  const allAudits = await api.functional.polEcoBoard.admin.accountAudits.search(connection, {
    body: {} satisfies IPolEcoBoardAccountAudit.IRequest
  });
  typia.assert(allAudits);
  TestValidator.predicate("should return at least one audit entry")(allAudits.data.length >= 1);

  // 5.b. Search audits by actor_id (the admin)
  const auditByAdmin = await api.functional.polEcoBoard.admin.accountAudits.search(connection, {
    body: { actor_id: auditManual.actor_id } satisfies IPolEcoBoardAccountAudit.IRequest
  });
  typia.assert(auditByAdmin);
  TestValidator.predicate("all audits have correct actor_id")(auditByAdmin.data.every(audit => audit.actor_id === auditManual.actor_id));

  // 5.c. Search audits by action_type
  const auditByType = await api.functional.polEcoBoard.admin.accountAudits.search(connection, {
    body: { action_type: "privilege_escalation" } satisfies IPolEcoBoardAccountAudit.IRequest
  });
  typia.assert(auditByType);
  TestValidator.predicate("should return our manual audit")(auditByType.data.some(audit => audit.id === auditManual.id));

  // 5.d. Search audits by occurred_after (just before manual audit)
  const occurredBeforeManual = new Date(Date.now() - 1000 * 60).toISOString();
  const auditDateFilter = await api.functional.polEcoBoard.admin.accountAudits.search(connection, {
    body: { occurred_after: occurredBeforeManual } satisfies IPolEcoBoardAccountAudit.IRequest
  });
  typia.assert(auditDateFilter);
  TestValidator.predicate("all occurred after")(auditDateFilter.data.every(a => new Date(a.occurred_at) >= new Date(occurredBeforeManual)));

  // 5.e. Search audits with pagination
  const auditPaginated = await api.functional.polEcoBoard.admin.accountAudits.search(connection, {
    body: {
      limit: 2,
      page: 1
    } satisfies IPolEcoBoardAccountAudit.IRequest
  });
  typia.assert(auditPaginated);
  TestValidator.equals("paginated - max 2")(auditPaginated.data.length <= 2)(true);
  TestValidator.equals("pagination meta")(auditPaginated.pagination.limit)(2);

  // 5.f. Invalid filter: action_type not in enum
  await TestValidator.error("invalid action type fails")(async () => {
    await api.functional.polEcoBoard.admin.accountAudits.search(connection, {
      body: {
        action_type: "NOT_A_REAL_TYPE" as any
      } as IPolEcoBoardAccountAudit.IRequest
    });
  });
}

