  // 6. Negative: invalid action_type value
  const invalidAction = {
    ...validAuditInput,
    action_type: "not_a_real_action" as any,
  };
  TestValidator.error("Invalid action_type fails")(() =>
    api.functional.polEcoBoard.admin.accountAudits.create(
      connection,
      { body: invalidAction as any },
    ),
  );
}

