import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate tag deletion with in-use reference conflict in polEcoBoard.
 *
 * This test verifies that an admin cannot delete a tag if it is referenced by a post.
 *
 * Business process:
 * 1. Register an admin account for privileged tag/post management
 * 2. Login as admin to get session/authorization
 * 3. Create a tag in the admin console
 * 4. As admin (who can post), create a post that references (uses) the tag
 * 5. Attempt to delete the tag, which should fail with an error due to reference integrity (the tag is in use)
 *
 * Steps:
 * 1. Register admin (random email/password)
 * 2. Login as admin
 * 3. Create a tag (ensure unique name/slug)
 * 4. Create a post, linking tag by id (attach tag_ids=[tag.id])
 * 5. Attempt to delete the tag (expect error)
 */
export async function test_api_tag_deletion_with_in_use_reference_conflict(
  connection: api.IConnection,
) {
  // 1. Register admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUp);

  // 2. Login as admin
  const signIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signIn);

  // 3. Create a tag
  const tagName = RandomGenerator.alphaNumeric(10);
  const tagSlug = tagName.toLowerCase();
  const tagDescription = RandomGenerator.paragraph()();
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: tagName,
      slug: tagSlug,
      description: tagDescription,
    } satisfies IPolEcoBoardTag.ICreate,
  });
  typia.assert(tag);

  // 4. Create a post referencing the tag
  const postTitle = RandomGenerator.paragraph()();
  const postBody = RandomGenerator.content()()();
  const postCategoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: postCategoryId,
      title: postTitle,
      body: postBody,
      tag_ids: [tag.id],
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Attempt to delete the tag (should fail due to in-use reference)
  await TestValidator.error("cannot delete tag that is still referenced by a post")(() =>
    api.functional.polEcoBoard.admin.tags.erase(connection, { tagId: tag.id })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validates moderator ability to paginate and filter comment votes.
 *
 * Scenario confirms end-to-end business logic, including authentication, comment creation, voting, and privileged moderation access:
 *
 * 1. Register and login as a moderator (captures moderator session/token).
 * 2. Register and login as member A (to create post/comment and serve as voter).
 * 3. Member A creates a post in a random category.
 * 4. Member A adds a comment to his post.
 * 5. Register and login as member B, who will cast a vote.
 * 6. Member B casts an upvote on the comment.
 * 7. Register and login as member C, who casts a downvote on the comment.
 * 8. As moderator (restore token), list votes on the comment via moderator search endpoint, using various filters:
 *      - filter by vote_value (1 for upvote, -1 for downvote)
 *      - filter by voter_member_id
 *      - test pagination with limit/page values
 *      - validate all returned votes match filter criteria, and full result is as expected (all votes visible, correct values)
 *
 * 9. Also verify that moderator can see voter identities in results (privacy bypass per moderator role).
 */
export async function test_api_comment_votes_search_moderator_access(connection: api.IConnection) {
  // 1. Register and login as moderator
  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderatorPassword = "ModeratorPw1!";
  const moderatorDisplayName = RandomGenerator.name();
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: "accepted"
    }
  });

  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    }
  });

  // 2. Register and login as member A
  const memberAEmail = typia.random<string & tags.Format<'email'>>();
  const memberAPassword = "PasswordA1!";
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword
    }
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword
    }
  });

  // 3. Member A creates a post
  const categoryId = typia.random<string & tags.Format<'uuid'>>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(30)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Member A adds a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()()(),
    } satisfies IPolEcoBoardComment.ICreate
  });
  typia.assert(comment);

  // 5. Register and login as member B
  const memberBEmail = typia.random<string & tags.Format<'email'>>();
  const memberBPassword = "PasswordB1!";
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword
    }
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword
    }
  });

  // 6. Member B casts an upvote
  const voteB = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1
    } satisfies IPolEcoBoardVote.ICreate
  });
  typia.assert(voteB);

  // 7. Register and login as member C
  const memberCEmail = typia.random<string & tags.Format<'email'>>();
  const memberCPassword = "PasswordC1!";
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberCEmail,
      password: memberCPassword
    }
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberCEmail,
      password: memberCPassword
    }
  });

  // 8. Member C casts a downvote
  const voteC = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: -1
    } satisfies IPolEcoBoardVote.ICreate
  });
  typia.assert(voteC);

  // 9. Switch back to moderator account for vote search
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    }
  });

  // 10. Moderator fetches all votes for this comment
  const allVotesRes = await api.functional.polEcoBoard.moderator.comments.votes.search(connection, {
    commentId: comment.id,
    body: { page: 1, limit: 10 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(allVotesRes);
  TestValidator.equals("should see two votes")(allVotesRes.data.length)(2);

  // 11. Filter by vote_value (upvote)
  const upvoteRes = await api.functional.polEcoBoard.moderator.comments.votes.search(connection, {
    commentId: comment.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(upvoteRes);
  TestValidator.predicate("should only return upvotes")(upvoteRes.data.every(v => v.vote_value === 1));
  TestValidator.equals("should see one upvote")(upvoteRes.data.length)(1);

  // 12. Filter by voter_member_id (downvote: memberC)
  const downvoteRes = await api.functional.polEcoBoard.moderator.comments.votes.search(connection, {
    commentId: comment.id,
    body: { vote_value: -1, voter_member_id: voteC.voter_member_id } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(downvoteRes);
  TestValidator.equals("should see one downvote")(downvoteRes.data.length)(1);
  TestValidator.equals("voter matches")(downvoteRes.data[0].voter_member_id)(voteC.voter_member_id);

  // 13. Paginated fetch (limit=1, page=1 and page=2)
  const page1Res = await api.functional.polEcoBoard.moderator.comments.votes.search(connection, {
    commentId: comment.id,
    body: { page: 1, limit: 1 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(page1Res);
  TestValidator.equals("page 1 result length")(page1Res.data.length)(1);
  TestValidator.equals("pagination page")(page1Res.pagination.current)(1);

  const page2Res = await api.functional.polEcoBoard.moderator.comments.votes.search(connection, {
    commentId: comment.id,
    body: { page: 2, limit: 1 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(page2Res);
  TestValidator.equals("page 2 result length")(page2Res.data.length)(1);
  TestValidator.equals("pagination page")(page2Res.pagination.current)(2);

  // 14. Moderator can see actual voter_member_id field for each vote (privacy bypass)
  TestValidator.predicate("voter identities revealed")
    (allVotesRes.data.every(v => typeof v.voter_member_id === "string" && v.voter_member_id.length > 0));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test permission denied response when a non-privileged member tries to list comment votes via the moderator endpoint.
 *
 * This test ensures that users who are not moderators or admins cannot access sensitive comment vote listing via the moderator API.
 * It performs all necessary setup as a regular member, then verifies that role-based access control is enforced.
 *
 * Steps:
 * 1. Register and log in as a new member (ordinary user, not moderator or admin).
 * 2. Create a post to establish context for subsequent comment and voting interactions.
 * 3. Add a comment to the post.
 * 4. Attempt to access the moderator comment votes listing endpoint for the comment as the member.
 * 5. Validate that the operation results in a permission/authentication (forbidden) error, confirming the endpoint enforces proper role restrictions.
 */
export async function test_api_comment_votes_search_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register a new member (non-privileged user)
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });

  // 2. Login as the member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });

  // 3. Create a post as the member
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(400),
      tag_ids: [],
      attachments: [],
    },
  });
  typia.assert(post);

  // 4. Add a comment to the created post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(10),
    },
  });
  typia.assert(comment);

  // 5. Attempt to access moderator comment votes endpoint as a member, expecting forbidden error
  await TestValidator.error("member should not access moderator comment votes API")(async () => {
    await api.functional.polEcoBoard.moderator.comments.votes.search(connection, {
      commentId: comment.id,
      body: {
        comment_id: comment.id,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can retrieve a paginated, filtered list of votes on a comment for moderation and audit purposes.
 *
 * This test exercises the full moderation/audit workflow:
 * 1. Register and log in as admin to acquire privileged access for comment vote search.
 * 2. Register and log in as a member who will create a post, add a comment, and vote.
 * 3. The member creates a post in a randomly chosen category (using a random UUID for the test).
 * 4. The member adds a top-level comment to the post.
 * 5. The member casts an upvote for the comment.
 * 6. Re-authenticate as the admin and search votes on that comment using the admin API, with a paginated request (limit=10, page=1).
 * 7. Confirm that the vote is returned and the details (vote value, voter, comment id) are correct.
 * 8. Additionally, test filtering by voter_member_id and vote_value, and verify pagination/limit enforcement.
 * 9. Check that filtering for an unmatching vote_value (downvote) yields an empty result array.
 */
export async function test_api_comment_votes_search_admin_access(connection: api.IConnection) {
  // 1. Register and log in as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminSignUpResp);

  const adminSignInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(adminSignInResp);

  // 2. Register and log in as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignUpResp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberSignUpResp);

  const memberSignInResp = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(memberSignInResp);

  // 3. Member creates a post
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(20)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Member adds a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(6)
    } satisfies IPolEcoBoardComment.ICreate
  });
  typia.assert(comment);

  // 5. Member casts an upvote for the comment
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1
    } satisfies IPolEcoBoardVote.ICreate
  });
  typia.assert(vote);

  // 6. Re-login as admin for vote searching
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 7. Admin searches votes for the comment (pagination, page=1, limit=10)
  const voteSearchResp = await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
    commentId: comment.id,
    body: { comment_id: comment.id, limit: 10, page: 1 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(voteSearchResp);

  // 8. Validate that the vote info is present and accurate
  TestValidator.equals("returned vote count")(voteSearchResp.data.length)(1);
  const v = voteSearchResp.data[0];
  TestValidator.equals("comment id matches")(v.comment_id)(comment.id);
  TestValidator.equals("vote value matches")(v.vote_value)(1);

  // 9. Test filtering by voter_member_id should return the vote
  const filterByVoterResp = await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
    commentId: comment.id,
    body: {
      comment_id: comment.id,
      voter_member_id: v.voter_member_id,
      limit: 10,
      page: 1
    } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(filterByVoterResp);
  TestValidator.equals("filter by voter - count")(filterByVoterResp.data.length)(1);
  TestValidator.equals("voter matches")(filterByVoterResp.data[0].voter_member_id)(v.voter_member_id);

  // 10. Check filter by negative vote_value yields zero results
  const downvoteResp = await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
    commentId: comment.id,
    body: { comment_id: comment.id, vote_value: -1, limit: 10, page: 1 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(downvoteResp);
  TestValidator.equals("no downvotes")(downvoteResp.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate error cases for admin vote searching with invalid or non-existent commentId and input.
 *
 * Business context:
 * Admins must receive robust error feedback when moderating voting records. If an invalid or non-existent commentId is searched, or invalid filter input is supplied (such as impossible date ranges or out-of-bounds pagination), the API should return explicit and clear errors for moderation reliability and client-side clarity.
 *
 * Steps:
 * 1. Register a new admin account (establish privileged context).
 * 2. Login with the admin account.
 * 3. Attempt to search for votes with a non-existent commentId (valid uuid not in DB).
 *    - Confirm the API returns an explicit error (TestValidator.error).
 * 4. Attempt to search with a malformed commentId (not a uuid string).
 *    - Confirm schema/validation error is returned.
 * 5. Attempt to search with invalid request body (limit > 100, created_before prior to created_after).
 *    - Confirm validation error is returned.
 */
export async function test_api_comment_votes_search_invalid_commentid_and_input(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Attempt vote search with non-existent commentId (assume random uuid is not in DB)
  await TestValidator.error("Search for non-existent commentId")(async () => {
    await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(),
      body: {},
    });
  });

  // 4. Attempt search with a malformed commentId (invalid uuid string)
  await TestValidator.error("Malformed commentId input")(async () => {
    await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
      commentId: "not-a-uuid" as any, // purposely trigger validation error
      body: {},
    });
  });

  // 5. Attempt search with an invalid request body (invalid pagination and date range)
  await TestValidator.error("Invalid vote search request body")(async () => {
    const createdAfter = new Date(Date.now() + 10000).toISOString();
