 *
 * This test verifies:
 * - Proper setup and entitlement of moderator role for audit search
 * - That the moderator can access audit records for an action they have rights to
 * - Correct linkage of audits to moderation actions
 * - Basic pagination metadata and presence of created audits in results
 *
 * Business context: Audit search by moderators is core to compliance and incident response.
 *
 * Steps:
 * 1. Register a moderator (save IDs & headers)
 * 2. Login as moderator to sync authentication
 * 3. Create moderation action as admin, using moderator as operator_id
 * 4. Create two audit events for the moderation action (using moderator as auditor_id)
 * 5. As moderator, search for audits for this action
 * 6. Assert that audits returned match those created, and validate pagination metadata
 */
export async function test_api_moderator_moderation_action_audit_search_success(
  connection: api.IConnection
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestPw_1234";
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "accept_latest";
  const registerResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registerResp);
  const moderatorId = registerResp.moderatorId;

  // 2. Login as moderator (ensure Authorization header is saved in connection)
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResp);

  // 3. Create moderation action as admin (using moderator as operator_id)
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: moderatorId,
      action_type: "warn",
      target_type: "post",
      status: "completed",
      rationale: "Policy violation test",
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);
  const moderationActionId = moderationAction.id;

  // 4. Create two audits for the moderation action as admin
  const preState1 = JSON.stringify({ status: "pending" });
  const postState1 = JSON.stringify({ status: "completed" });
  const audit1 = await api.functional.polEcoBoard.admin.moderationActions.audits.create(connection, {
    moderationActionId,
    body: {
      moderation_action_id: moderationActionId,
      auditor_id: moderatorId,
      pre_state_snapshot: preState1,
      post_state_snapshot: postState1,
      reason: "Initial moderation action completed.",
    } satisfies IPolEcoBoardModerationAudit.ICreate,
  });
  typia.assert(audit1);

  const preState2 = JSON.stringify({ status: "completed" });
  const postState2 = JSON.stringify({ status: "overruled" });
  const audit2 = await api.functional.polEcoBoard.admin.moderationActions.audits.create(connection, {
    moderationActionId,
    body: {
      moderation_action_id: moderationActionId,
      auditor_id: moderatorId,
      pre_state_snapshot: preState2,
      post_state_snapshot: postState2,
      reason: "Action outcome changed to overruled.",
    } satisfies IPolEcoBoardModerationAudit.ICreate,
  });
  typia.assert(audit2);

  // 5. As moderator, search for audits for this action (no filters)
  const auditPage = await api.functional.polEcoBoard.moderator.moderationActions.audits.search(connection, {
    moderationActionId,
    body: {
      moderation_action_id: moderationActionId,
      page: 1,
      limit: 10,
    } satisfies IPolEcoBoardModerationAudit.IRequest,
  });
  typia.assert(auditPage);
  // Result must list both audits we created
  TestValidator.predicate("contains audit1")(
    auditPage.data.some(a => a.id === audit1.id)
  );
  TestValidator.predicate("contains audit2")(
    auditPage.data.some(a => a.id === audit2.id)
  );
  // Pagination must be correct
  TestValidator.equals("pagination page")(auditPage.pagination.current)(1);
  TestValidator.predicate("limit >= returned count")(
    auditPage.data.length <= 10
  );
  // Auditor filter test (should only match if filtered correctly)
  const auditPageFiltered = await api.functional.polEcoBoard.moderator.moderationActions.audits.search(connection, {
    moderationActionId,
    body: {
      moderation_action_id: moderationActionId,
      auditor_id: moderatorId,
      page: 1,
      limit: 10,
    } satisfies IPolEcoBoardModerationAudit.IRequest,
  });
  typia.assert(auditPageFiltered);
  TestValidator.predicate("filtered contains audit1 or audit2")(
    auditPageFiltered.data.some(a => a.id === audit1.id || a.id === audit2.id)
  );
}

