 * 3. Create a moderation action as the admin, setting all compliance/business required fields.
 * 4. Create a moderation audit record for that action (as the same admin), with full pre/post state, rationale, and references.
 * 5. Fetch the created audit record by its moderationActionId and auditId as the logged-in admin.
 * 6. Assert all major properties of the audit record match what was inserted (moderation_action_id, auditor_id, reason, pre/post snapshots).
 */
export async function test_api_admin_moderation_action_audit_get_success(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail: string & tags.Format<"email"> = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
