    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 3. Create moderation action
  // In a real system, the operator_id would match the admin's id, but
