 * It attempts to create an edit revision for a post using the admin endpoint
 * without providing any valid JWT Authorization token in the connection context.
 *
 * Preconditions:
 *   - An admin account is registered as a dependency (not used directly in this test, but required for completeness in the broader E2E suite).
 *
 * Steps:
 * 1. (Dependency) Register a new admin account (not used for this unauthenticated request).
 * 2. Attempt to create a post edit using the admin endpoint WITHOUT supplying Authorization in the connection context.
 * 3. Assert that an authorization error is thrown and that the edit is NOT created (API denies unauthenticated access).
 */
export async function test_api_post_edit_create_by_admin_fail_without_auth(connection: api.IConnection) {
  // Step 1: Register admin (dependency, not used for token)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
