import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test that a moderator can perform audit-compliant soft deletion (set deleted_at) of a post edit revision record on the polEcoBoard.
 *
 * **Business context:**
 * - Only moderators can issue post edit deletion (compliance, correction).
 * - Deletion is audit/soft (marks deleted_at), not physical DB delete.
 * - Main post is not affected in integrity or visibility.
 *
 * **Workflow:**
 * 1. Register & log in moderator for compliance permission enforcement
 * 2. Register & log in member (author) for post creation
 * 3. Member creates a post
 * 4. Switch session: moderator logs in
 * 5. Moderator creates a post edit on that post (revision/snapshot)
 * 6. Moderator deletes that post edit (soft/audit compliant)
 * 7. Ensure no error is thrown and main post is unaffected (by assumption)
 * 8. (Bonus) Attempt deletion as non-moderator and validate rejection
 *
 * **Edge case:** Success is assumed if erase API call completes without error, as audit/DB verification is out of E2E API scope.
 */
export async function test_api_post_edit_delete_by_moderator_compliance(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "modTestPw1!";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "policy-v1.0-consent";

  const moderatorSignup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorSignup);

  // 2. Moderator logs in (ensure fresh token for session segment)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(moderatorLogin);

  // 3. Register member (author role)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "memTestPw1!";
  const memberSignup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberSignup);

  // 4. Member logs in
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(memberLogin);

  // 5. Member creates a post
  const postBody: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, { body: postBody });
  typia.assert(post);

  // 6. Switch back to moderator session for revision ops
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

  // 7. Moderator creates a post edit
  const postEditBody: IPolEcoBoardPostEdit.ICreate = {
    edit_body: RandomGenerator.content()()(1),
    edit_reason: "Initial compliance check",
  };
  const postEdit = await api.functional.polEcoBoard.moderator.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: postEditBody
  });
  typia.assert(postEdit);

  // 8. Moderator deletes the post edit (soft, audit complaint)
  await api.functional.polEcoBoard.moderator.posts.postEdits.eraseEdit(connection, {
    postId: post.id,
    postEditId: postEdit.id
  });
  // No API call to confirm delete—success = API no error (void)

  // 9. Attempt deletion as non-moderator (should fail: test audit guard)
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword } satisfies IMemberAuthenticationMemberSignIn
  });
  await TestValidator.error("non-moderator cannot delete post edit")(async () => {
    await api.functional.polEcoBoard.moderator.posts.postEdits.eraseEdit(connection, {
      postId: post.id,
      postEditId: postEdit.id
    });
  });
}

