/**
 * Validate error handling and idempotency when a moderator tries to delete a non-existent or already deleted post edit.
 *
 * This scenario ensures that the API returns an appropriate error (such as 404 Not Found or equivalent) without deleting unrelated data or generating adverse side effects. It also ensures idempotency: repeated delete requests on the same (non-existent or already deleted) resource should yield the same error result.
 *
 * Step-by-step process:
 * 1. Register a new moderator account.
 * 2. Log in with the moderator account to acquire valid authentication.
 * 3. Attempt to delete a post edit revision using random (non-existent) UUIDs for both postId and postEditId.
 * 4. Validate that an error is returned from the API (e.g., 404 Not Found).
 * 5. Make a second identical delete attempt to ensure consistent error response (idempotency).
 * 6. Optionally, verify that no actual data was affected (cannot be validated if resource did not exist, but check for absence of server errors or state changes).
 */
export async function test_api_post_edit_delete_by_moderator_nonexistent(
  connection: api.IConnection,
) {
  // 1. Register a new moderator account
  const email = typia.random<string & tags.Format<"email">>();
  const password = "StrongP@ssw0rd!";
  const display_name = RandomGenerator.name();
  const consent_status = "v1.0/2024/eco-policy";
  const moderatorRegistrationResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name,
      consent_status,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
