import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates the successful update of a notification record by an admin user.
 *
 * This test covers the end-to-end flow for an admin updating a notification:
 * 1. Register a new admin user using the public registration endpoint.
 * 2. Log in as the admin to set up authentication for privileged operations.
 * 3. Create an initial notification event (with known recipient and event_type/status values) using the admin notifications endpoint.
 * 4. Update the notification record by its ID (fields like status, attempt_count, delivered_at, etc.).
 * 5. Check that the response contains the expected updated values, and verify key audit fields (updated_at changes, status changes etc.).
 *
 * Steps:
 *  1. Register admin with random but valid email/password.
 *  2. Log in with admin credentials (should update connection with a valid Authorization header).
 *  3. Create notification with typia.random<IPolEcoBoardNotification.ICreate> (store recipient_member_id etc.).
 *  4. Build an update (e.g. change status from 'pending' to 'delivered', increment attempt_count, set delivered_at to now).
 *  5. Call update endpoint. Assert output matches:
 *     - id unchanged
 *     - changed fields match request
 *     - updated_at reflects update
 *     - other non-updated fields remain unchanged
 *  6. Optionally, check side effect fields such as attempt counts, timestamps, status transitions, etc.
 */
export async function test_api_admin_notification_update_success(connection: api.IConnection) {
  // 1. Register admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create an initial notification (required fields only for first test)
  const notificationCreate: IPolEcoBoardNotification.ICreate = {
    recipient_member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "test_event_type",
    status: "pending",
    provider_id: null,
    related_object_id: null,
    attempt_count: 0,
  };
  const created = await api.functional.polEcoBoard.admin.notifications.create(connection, { body: notificationCreate });
  typia.assert(created);

  // 4. Prepare an update: Change status to 'delivered', increment attempt_count, set delivered_at to now.
  const updateBody: IPolEcoBoardNotification.IUpdate = {
    status: "delivered",
    attempt_count: created.attempt_count + 1,
    delivered_at: new Date().toISOString(),
    last_attempted_at: new Date().toISOString(),
    provider_id: created.provider_id ?? null,
  };
  const updated = await api.functional.polEcoBoard.admin.notifications.update(connection, {
    notificationId: created.id,
    body: updateBody,
  });
  typia.assert(updated);

  // 5. Validate that only permitted fields changed, and others remain the same
  TestValidator.equals("id")(updated.id)(created.id);
  TestValidator.equals("recipient_member_id")(updated.recipient_member_id)(created.recipient_member_id);
  TestValidator.equals("event_type")(updated.event_type)(created.event_type);
  TestValidator.equals("status")(updated.status)(updateBody.status);
  TestValidator.equals("attempt_count")(updated.attempt_count)(updateBody.attempt_count);
  TestValidator.equals("delivered_at")(updated.delivered_at)(updateBody.delivered_at);
  TestValidator.equals("last_attempted_at")(updated.last_attempted_at)(updateBody.last_attempted_at);
  TestValidator.equals("provider_id")(updated.provider_id)(updateBody.provider_id);
  TestValidator.notEquals("updated_at should be changed")(updated.updated_at)(created.updated_at);
  TestValidator.equals("created_at immutable")(updated.created_at)(created.created_at);
  TestValidator.equals("related_object_id")(updated.related_object_id)(created.related_object_id);
  TestValidator.equals("deleted_at")(updated.deleted_at)(created.deleted_at);
}

