 *
 * Workflow:
 * 1. Register and login as a new admin with unique credentials.
 * 2. Create a valid notification to confirm general workflow, but use a non-matching UUID for the negative test.
 * 3. Attempt to update a notification with a randomly generated UUID (guaranteed to not match our created notification), expecting an error response.
 * 4. Assert that the error logic is triggered and that no state mutation occurs for real notifications.
 *
 * There is no public 'get notification by id' endpoint, so no direct data-state re-check is possible; test is scoped to API contract errors only.
 */
export async function test_api_admin_notification_update_invalid_id(connection: api.IConnection) {
  // 1. Register a unique admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as the registered admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a valid notification for system context
  const notificationInput = {
    recipient_member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: RandomGenerator.alphabets(8),
