  // --- Important test limitation ---
  // There is no way to obtain the member ID from the registration/login APIs, yet notification creation requires recipient_member_id.
  // For this integration test, we must assume the infra provides the correct recipient_member_id for memberA.
  // Here, we simulate by supplying a random UUID as a placeholder; in a real environment, test infra must resolve correct IDs.
  const fakeMemberAId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create a notification for Member A as admin
  const notification = await api.functional.polEcoBoard.admin.notifications.create(connection, {
