import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IPageIPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator user can search for their own notification preferences using pagination and filter options.
 *
 * Test steps:
 * 1. Register a new moderator using the registration endpoint (capture email/password for login).
 * 2. Login as this moderator and ensure Authorization header is set for subsequent authenticated calls.
 * 3. Create a set of diverse notification preferences for this moderator, using various event_type/channel/opt_in combos, via the POST endpoint.
 * 4. Use the PATCH endpoint to search for preferences, varying parameters for:
 *    a. No filters (returns all for the moderator, paginated)
 *    b. Filter by event_type (one of those created above)
 *    c. Filter by channel (one of those created above)
 *    d. Filter by opt_in status (true/false)
 *    e. Pagination: request small limit & page through results, test edge case (results at boundaries)
 * 5. Validate for each search:
 *    - Only notification preferences for this moderator account are returned (member_id matches moderatorId)
 *    - All result records match the search filter
 *    - Pagination metadata reflects the correct number of total records (as can be confirmed from the created set)
 */
export async function test_api_moderator_notification_preference_search_by_self(connection: api.IConnection) {
  // 1. Register a new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(10);
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1-policy-agree";

  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registration);
  const moderatorId = registration.moderatorId;

  // 2. Log in as this moderator
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(login);

  // 3. Create diverse notification preferences
  const eventTypes = ["reply", "moderation_action", "new_topic", "system_alert"];
  const channels = ["email", "push", "in_app", "sms"];
  const optInMatrix = [true, false];
  // Total: 4*4*2 = 32 notification preferences
  const createdPrefs: IPolEcoBoardNotificationPreference[] = [];
  for (const event_type of eventTypes) {
    for (const channel of channels) {
      for (const opt_in of optInMatrix) {
        const pref = await api.functional.polEcoBoard.moderator.notificationPreferences.create(connection, {
          body: {
            member_id: moderatorId,
            event_type,
            channel,
            opt_in
          } satisfies IPolEcoBoardNotificationPreference.ICreate,
        });
        typia.assert(pref);
        createdPrefs.push(pref);
      }
    }
  }
  TestValidator.equals("created preference count")(createdPrefs.length)(eventTypes.length * channels.length * optInMatrix.length);
  // Used for later filter count checks

  // 4a. Search: No filters (all for moderator, paginated)
  const searchAll = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
    body: {
      page: 1,
      limit: 32,
    } satisfies IPolEcoBoardNotificationPreference.IRequest,
  });
  typia.assert(searchAll);
  // Validate all returned records are for this moderator
  for (const pref of searchAll.data)
    TestValidator.equals("all prefs belong to moderator")(pref.member_id)(moderatorId);
  // Validate full set was returned
  TestValidator.equals("all prefs returned")(searchAll.data.length)(createdPrefs.length);
  TestValidator.equals("pagination records")(searchAll.pagination.records)(createdPrefs.length);

  // 4b. Search by event_type
  for (const eventType of eventTypes) {
    const filteredByEvent = createdPrefs.filter(x => x.event_type === eventType);
    const searchByEvent = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        event_type: eventType,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByEvent);
    TestValidator.equals(`event_type '${eventType}' filter count`)(searchByEvent.data.length)(filteredByEvent.length);
    for (const pref of searchByEvent.data) {
      TestValidator.equals("event_type matches")(pref.event_type)(eventType);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4c. Search by channel
  for (const channel of channels) {
    const filteredByChannel = createdPrefs.filter(x => x.channel === channel);
    const searchByChannel = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        channel,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByChannel);
    TestValidator.equals(`channel '${channel}' filter count`)(searchByChannel.data.length)(filteredByChannel.length);
    for (const pref of searchByChannel.data) {
      TestValidator.equals("channel matches")(pref.channel)(channel);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4d. Search by opt_in status
  for (const optIn of optInMatrix) {
    const filteredByOpt = createdPrefs.filter(x => x.opt_in === optIn);
    const searchByOpt = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        opt_in: optIn,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByOpt);
    TestValidator.equals(`opt_in='${optIn}' filter count`)(searchByOpt.data.length)(filteredByOpt.length);
    for (const pref of searchByOpt.data) {
      TestValidator.equals("opt_in matches")(pref.opt_in)(optIn);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4e. Pagination edge: page through with small limit, check for correct non-overlapping, correct union of all ids
  const pagedLimit = 5;
  const totalPages = Math.ceil(createdPrefs.length / pagedLimit);
  let allPagedIds: string[] = [];
  for (let page = 1; page <= totalPages; page++) {
    const pageResult = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        page,
        limit: pagedLimit,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(pageResult);
    for (const pref of pageResult.data) {
      TestValidator.equals("member_id matches in paging")(pref.member_id)(moderatorId);
      // Ids must not repeat across pages
      TestValidator.predicate(`unique id in pages: ${pref.id}`)(!allPagedIds.includes(pref.id));
      allPagedIds.push(pref.id);
    }
  }
  // The union of paged ids must cover all
  TestValidator.equals("paged id union covers all")(allPagedIds.length)(createdPrefs.length);
  for (const id of allPagedIds)
    TestValidator.predicate(`id found in createdPrefs`)(createdPrefs.some(p => p.id === id));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IPageIPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator cannot search notification preferences for another user without proper authorization.
 *
 * This test covers the enforcement of access control in the notification preference search API. It ensures that when a moderator attempts to search notification preferences by specifying another user's member_id as a filter (without explicit admin permissions), the system correctly denies the action and does not leak any user information.
 *
 * Steps:
 * 1. Register a moderator with random credentials.
 * 2. Log the moderator in to establish an authenticated session.
 * 3. Register a standard member to be the target of access.
 * 4. As the member, create a notification preference record. This ensures there is sensitive data the moderator could attempt to access.
 * 5. Switch back to moderator by logging in.
 * 6. As the moderator, attempt to search for notification preferences using the member's member_id as a filter (API PATCH /polEcoBoard/moderator/notificationPreferences with member_id set).
 * 7. Check that a runtime error is thrown (via TestValidator.error) and that no unauthorized data is returned. The result should correspond to a permission or access denied violation, confirming boundaries are being enforced.
 */
export async function test_api_moderator_notification_preference_search_invalid_role_access(
  connection: api.IConnection,
) {
  // Step 1: Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = typia.random<string & tags.Format<"password">>();
  const moderatorDisplayName = RandomGenerator.name();
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: "v1.0.0"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });

  // Step 2: Login as the moderator
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

  // Step 3: Register a test member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberRegisterResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberRegisterResult);
  const memberAuthHeader = memberRegisterResult.setHeaders.Authorization;

  // Step 4: As the member, create a notification preference
  // The member_id field will be ignored by the backend (will default to the authenticated JWT member)
  const memberConnection = { ...connection, headers: { ...connection.headers, Authorization: memberAuthHeader } };
  const notifPref = await api.functional.polEcoBoard.member.notificationPreferences.create(memberConnection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "reply",
      channel: "email",
      opt_in: true
    } satisfies IPolEcoBoardNotificationPreference.ICreate
  });
  typia.assert(notifPref);

  // Step 5: Switch back to the moderator session
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });

  // Step 6: Moderator attempts to search for member's notification preferences (illegal access)
  await TestValidator.error("moderator must not access another user's notification preferences")(
    async () => {
      await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
        body: {
          member_id: notifPref.member_id,
          event_type: notifPref.event_type,
          channel: notifPref.channel,
          page: 1,
          limit: 10
        } satisfies IPolEcoBoardNotificationPreference.IRequest
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAntiSpamEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAntiSpamEvent";
import type { IPageIPolEcoBoardAntiSpamEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAntiSpamEvent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates the search, filtering, and pagination of anti-spam events by admin, with access control enforcement.
 *
 * This test ensures:
 * - Admin can register and login for authorized access.
 * - At least one anti-spam event exists for meaningful testing.
 * - Search with specific filters (provider_key, operation, action_taken, score range, appeal_requested, created_from/created_to)
 *   only returns events matching the filter criteria.
 * - Pagination parameters (limit, page) work as expected.
 * - Using unmatched or non-existent filter parameters yields no results.
 * - Unauthorized (non-admin) search attempts are denied.
 *
 * Test steps:
 * 1. Register a new admin (random email & password).
 * 2. Login as the admin to obtain credentials.
 * 3. Create a known anti-spam event (store its values for later filtering).
 * 4. Use search API with filters that should match the created event and validate returned events.
 * 5. Use search with edge-case filters that should yield no results.
 * 6. Test pagination correctness by requesting page 1 with limit 1 and ensure only one event is returned, and correct page meta info.
 * 7. Logout (or clear admin auth), then attempt the search as unauthorized/non-admin and validate failure.
 */
export async function test_api_antispam_event_admin_search_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin (sets Authorization header in connection)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a known anti-spam event
  const nowIso = new Date().toISOString();
  const antiSpamEventInput: IPolEcoBoardAntiSpamEvent.ICreate = {
    provider_key: RandomGenerator.alphabets(7),
    operation: "content_submit",
    content_hash: RandomGenerator.alphaNumeric(32),
    score: 0.8,
    action_taken: "blocked",
    appeal_requested: false,
    created_at: nowIso,
  };
  const antiSpamEvent = await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, {
    body: antiSpamEventInput,
  });
  typia.assert(antiSpamEvent);

  // 4. Search with filters that match the created event
  const searchResp = await api.functional.polEcoBoard.admin.antiSpamEvents.search(connection, {
    body: {
      provider_key: antiSpamEventInput.provider_key,
      operation: antiSpamEventInput.operation,
      action_taken: antiSpamEventInput.action_taken,
      score_min: 0.7,
      score_max: 1.0,
      appeal_requested: antiSpamEventInput.appeal_requested,
      created_from: nowIso,
      created_to: nowIso,
      limit: 10,
      page: 1,
    } satisfies IPolEcoBoardAntiSpamEvent.IRequest,
  });
  typia.assert(searchResp);
  // All returned events should match the filter
  for (const ev of searchResp.data) {
    TestValidator.equals("provider_key")(ev.provider_key)(antiSpamEventInput.provider_key);
    TestValidator.equals("operation")(ev.operation)(antiSpamEventInput.operation);
    TestValidator.equals("action_taken")(ev.action_taken)(antiSpamEventInput.action_taken);
    TestValidator.predicate("score min")(ev.score >= 0.7);
    TestValidator.predicate("score max")(ev.score <= 1.0);
    TestValidator.equals("appeal_requested")(ev.appeal_requested)(antiSpamEventInput.appeal_requested);
    TestValidator.equals("created_at")(ev.created_at)(nowIso);
  }

  // 5. Search with filters that will match nothing
  const noneResp = await api.functional.polEcoBoard.admin.antiSpamEvents.search(connection, {
    body: {
      provider_key: "nonexistent_provider",
    },
  });
  typia.assert(noneResp);
  TestValidator.equals("empty result")(noneResp.data.length)(0);

  // 6. Pagination: request page 1, limit 1
  const pagedResp = await api.functional.polEcoBoard.admin.antiSpamEvents.search(connection, {
    body: {
      limit: 1,
      page: 1,
    },
  });
  typia.assert(pagedResp);
  TestValidator.equals("paginated result length")(pagedResp.data.length)(Math.min(pagedResp.pagination.records, 1));
  TestValidator.equals("pagination current")(pagedResp.pagination.current)(1);
  TestValidator.equals("pagination limit")(pagedResp.pagination.limit)(1);

  // 7. Attempt unauthorized search (simulate by removing Authorization header)
  const unauthorizedConnection = {
    ...connection,
    headers: {
      ...connection.headers,
    },
  };
  if (unauthorizedConnection.headers && unauthorizedConnection.headers.Authorization) {
    delete unauthorizedConnection.headers.Authorization;
  }
  await TestValidator.error("unauthorized access should fail")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.search(unauthorizedConnection, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
