/**
 * Validate the search and filtered retrieval of anti-spam event logs by a moderator.
 *
 * This test covers realistic business flows:
 *   1. Register a new moderator account
 *   2. Log in as that moderator
 *   3. Create at least one anti-spam event via the admin endpoint
 *   4. As moderator, use the search API to retrieve events with filters (such as operation, score, action_taken)
 *   5. Check that the results returned by the search API match filtering criteria and include accurate pagination info
 *   6. Confirm that non-moderator access to the search API is denied
 *   7. Confirm bad requests (invalid input) are handled with errors
 */
export async function test_api_antispam_event_moderator_search_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Register Moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "testpassword!1234";
  const moderatorDisplayName = RandomGenerator.name();
  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: "v1-terms-2024-accepted"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registration);

  // 2. Moderator login
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(login);

  // 3. Admin creates an anti-spam event
  const testProviderKey = "akismet";
  const testOperation = "content_submit";
  const testActionTaken = "blocked";
  const testScore = 0.73;
  const testAppealRequested = false;
  const eventCreatedAt = new Date().toISOString();
  const eventCreation = await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, {
    body: {
      provider_key: testProviderKey,
      operation: testOperation,
      content_hash: RandomGenerator.alphaNumeric(24),
      score: testScore,
      action_taken: testActionTaken,
      appeal_requested: testAppealRequested,
      created_at: eventCreatedAt
    } satisfies IPolEcoBoardAntiSpamEvent.ICreate
  });
  typia.assert(eventCreation);

  // 4. Moderator searches anti-spam events with filters
  const searchResult = await api.functional.polEcoBoard.moderator.antiSpamEvents.search(connection, {
    body: {
      provider_key: testProviderKey,
      operation: testOperation,
      action_taken: testActionTaken,
      appeal_requested: testAppealRequested,
      score_min: 0.5,
      score_max: 0.9,
      created_from: eventCreatedAt,
      created_to: null,
      page: 1,
      limit: 20,
      sort_by: "created_at",
      sort_direction: "desc",
      keyword: null
    } satisfies IPolEcoBoardAntiSpamEvent.IRequest
  });
