    TestValidator.equals("appeal_requested matches")(event.appeal_requested)(testAppealRequested);
    TestValidator.predicate("score filter matches")(event.score >= 0.5 && event.score <= 0.9);
    TestValidator.predicate("created_at matches")(new Date(event.created_at) >= new Date(eventCreatedAt));
  }
  // Validate pagination structure
  TestValidator.equals("page is 1")(searchResult.pagination.current)(1);
  TestValidator.equals("limit is 20")(searchResult.pagination.limit)(20);
  TestValidator.predicate("total records >= 1")(searchResult.pagination.records >= 1);

  // 5. Non-moderator (unauthenticated) access forbidden
  if (connection.headers?.Authorization) delete connection.headers.Authorization;
  TestValidator.error("non-moderator access must be denied")(
    async () => {
      await api.functional.polEcoBoard.moderator.antiSpamEvents.search(connection, {
        body: { page: 1, limit: 10 } satisfies IPolEcoBoardAntiSpamEvent.IRequest
      });
    }
  );

  // 6. Input validation error (limit above max)
  // Restore moderator session for input error test
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  TestValidator.error("limit above max triggers error")(
    async () => {
      await api.functional.polEcoBoard.moderator.antiSpamEvents.search(connection, {
        body: { page: 1, limit: 9999 } satisfies IPolEcoBoardAntiSpamEvent.IRequest
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAntiSpamEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAntiSpamEvent";
