/**
 * Validate detailed anti-spam event retrieval (admin access).
 *
 * This test ensures that an admin can fetch full details of a specific anti-spam event by its ID, with all business fields as created.
 * It also tests that forbidden and not-found scenarios behave correctly.
 *
 * Steps:
 * 1. Register a new admin account.
 * 2. Sign in as that admin (obtain JWT in connection automatically).
 * 3. Create a new anti-spam event with specific test data.
 * 4. Retrieve that event by its ID as admin and verify all returned fields match those used in creation.
 * 5. Attempt to retrieve a non-existent event ID → expect not-found error.
 * 6. (Optional) Remove admin token and try retrieving existing anti-spam event – expect forbidden error (not implemented here due to no API for non-admin user context).
 */
export async function test_api_antispam_event_admin_detail_view_by_id(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
