import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAntiSpamEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAntiSpamEvent";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate anti-spam event creation by an admin user on the polEcoBoard platform (positive and negative scenarios).
 *
 * This test ensures that only authenticated admin users are able to create new anti-spam event records via the POST /polEcoBoard/admin/antiSpamEvents endpoint. It covers required business logic and type validation, edge case handling, and access restriction to unauthorized users.
 *
 * Step-by-step process:
 * 1. Register a new admin account using valid credentials.
 * 2. Log in with the same admin credentials to obtain an authenticated session/token.
 * 3. Create a valid anti-spam event as the admin, filling all required fields with plausible values. Verify the response matches input and all expected fields.
 * 4. Attempt creation of an anti-spam event with missing required fields and verify rejection due to validation error.
 * 5. Attempt creation of an anti-spam event with invalid score (e.g., negative value or value >1.0), confirm error response.
 * 6. Attempt to create an anti-spam event as a non-admin (no authentication) and confirm access is denied.
 *
 * Test inputs and result assertions utilize the provided API SDK, DTOs, and runtime type assertions. All assertions use TestValidator. Use typia.random<T>() for realistic input value construction. Type-safety and DTO property compliance is strictly enforced by the test.
 */
export async function test_api_antispam_event_creation_by_admin_valid_and_invalid(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(signUpResp);

  // 2. Log in with admin credentials
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  typia.assert(signInResp);

  // 3. Create valid anti-spam event as admin
  const validEvent: IPolEcoBoardAntiSpamEvent.ICreate = {
    provider_key: "akismet",
    operation: "content_submit",
    content_hash: RandomGenerator.alphaNumeric(32),
    score: 0.51,
    action_taken: "approved",
    appeal_requested: false,
    created_at: new Date().toISOString(),
  };
  const eventResp = await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, { body: validEvent });
  typia.assert(eventResp);
  TestValidator.equals("provider_key")(eventResp.provider_key)(validEvent.provider_key);
  TestValidator.equals("operation")(eventResp.operation)(validEvent.operation);
  TestValidator.equals("content_hash")(eventResp.content_hash)(validEvent.content_hash);
  TestValidator.equals("score")(eventResp.score)(validEvent.score);
  TestValidator.equals("action_taken")(eventResp.action_taken)(validEvent.action_taken);
  TestValidator.equals("appeal_requested")(eventResp.appeal_requested)(validEvent.appeal_requested);
  TestValidator.predicate("created_at is date string")(!isNaN(Date.parse(eventResp.created_at)));
  TestValidator.predicate("id is uuid-like")(typeof eventResp.id === "string" && eventResp.id.length > 20);

  // 4. Attempt creation with missing required fields (omit provider_key)
  const { provider_key, ...missingProviderKey } = validEvent;
  await TestValidator.error("missing provider_key should fail")(async () => {
    // @ts-expect-error: intentionally omitting required field for negative test
    await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, { body: missingProviderKey });
  });

  // 5. Attempt creation with invalid score (negative value)
  await TestValidator.error("negative score should fail")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, {
      body: { ...validEvent, score: -0.1 },
    });
  });
  // Attempt creation with score > 1.0
  await TestValidator.error("overflow score should fail")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.create(connection, {
      body: { ...validEvent, score: 2.22 },
    });
  });

  // 6. Attempt creation as a non-admin (no authentication)
  const anonConnection = { ...connection, headers: { ...connection.headers } };
  delete anonConnection.headers.Authorization;
  await TestValidator.error("non-admin access not allowed")(async () => {
    await api.functional.polEcoBoard.admin.antiSpamEvents.create(anonConnection, { body: validEvent });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
