import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator view of comment report detail and access restrictions.
 *
 * This test verifies that a moderator can retrieve the full details of an abuse report filed on a comment. It covers both successful retrieval and permission boundary cases. It ensures the system restricts access based on roles and properly handles mismatched or invalid IDs.
 *
 * Steps:
 * 1. Register a moderator account
 * 2. Login as the moderator and capture Authorization
 * 3. Create a post as a member (SDK enables this as an open operation, so simulate as 'member')
 * 4. Add a comment to the post as a member (SDK enables this as an open operation)
 * 5. File a report on the comment as a member (SDK enables this as an open operation)
 * 6. Retrieve the report as moderator: confirm all fields
 * 7. Negative: attempt retrieval with wrong reportId (should error)
 * 8. Negative: attempt retrieval with wrong commentId (should error)
 * 9. (Edge: retrieval as member is not implemented, as no member/auth endpoint exists)
 */
export async function test_api_comment_report_detail_view_moderator_role(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestModerator123!";
  const registerRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: RandomGenerator.name(),
      consent_status: "agree_v1",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registerRes);

  // 2. Login as moderator (refresh Authorization)
  const loginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginRes);

  // 3. Create post as member (open endpoint)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(2),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Add comment to the post as member
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()()(1),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. File a report on the comment as member
  const report = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: "abuse",
      reason_description: "Inappropriate language.",
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report);

  // 6. Retrieve the report as moderator (should succeed)
  const fetched = await api.functional.polEcoBoard.moderator.comments.reports.at(connection, {
    commentId: comment.id,
    reportId: report.id,
  });
  typia.assert(fetched);
  TestValidator.equals("reportId matches")(fetched.id)(report.id);
  TestValidator.equals("commentId matches")(fetched.comment_id)(comment.id);
  TestValidator.equals("reason code matches")(fetched.reason_code)(report.reason_code);
  TestValidator.equals("reporter id matches")(fetched.reporter_member_id)(report.reporter_member_id);
  TestValidator.equals("created_at matches")(fetched.created_at)(report.created_at);

  // 7. Negative: wrong reportId
  await TestValidator.error("wrong reportId should error")(async () => {
    await api.functional.polEcoBoard.moderator.comments.reports.at(connection, {
      commentId: comment.id,
      reportId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 8. Negative: wrong commentId
  await TestValidator.error("wrong commentId should error")(async () => {
    await api.functional.polEcoBoard.moderator.comments.reports.at(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(),
      reportId: report.id,
    });
  });

  // 9. No member login/logout endpoints in SDK; cannot test member-restricted retrieval.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin's ability to view a specific comment report (detail view).
 *
 * Business Context:
 * Ensure that an admin user can retrieve the full detail of a filed report on a comment, including all audit/moderation/abuse fields. This verifies proper admin access, exposes sensitive fields for moderation review, and enforces correct permission boundaries — only admins may succeed; errors are thrown when misusing IDs or role.
 *
 * Steps:
 * 1. Register a new admin (and obtain credentials)
 * 2. Login as the admin (activates admin session/token)
 * 3. Create a post as a member (prereq for comment)
 * 4. Create a comment on the post (as member)
 * 5. File a report for the comment (as member)
 * 6. As the admin, fetch the report detail (expect success, all fields match what was filed in step 5)
 * 7. Attempt to fetch with an invalid reportId (expect error)
 * 8. Attempt to fetch with a mismatched commentId (expect error)
 * 9. Attempt to fetch report as a non-admin (wrong role or no token, expect error)
 */
export async function test_api_comment_report_detail_view_admin_role(connection: api.IConnection) {
  // Step 1: Register a new admin (unique credentials)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegisterOut = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminRegisterOut);

  // Step 2: Login as this admin (get valid token)
  const adminLoginOut = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginOut);

  // The connection now carries admin privileges for privileged requests

  // Step 3: Create a post as member (not possible to simulate real member auth in this context; but API accepts member actions if connection permits)
  // Fake a valid category_id for post (as schema allows any UUID here, and test is not about this logic)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(50),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // Step 4: Create a comment on the post.
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(8),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // Step 5: File a report against the comment
  const reportReason = "abuse";
  const reportDesc = RandomGenerator.paragraph()(10);
  const report = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: reportReason,
      reason_description: reportDesc,
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report);

  // Step 6: As admin, fetch the report detail by (commentId,reportId)
  const fetched = await api.functional.polEcoBoard.admin.comments.reports.at(connection, {
    commentId: comment.id,
    reportId: report.id,
  });
  typia.assert(fetched);
  // Validate all critical fields match
  TestValidator.equals("report id")(fetched.id)(report.id);
  TestValidator.equals("comment id")(fetched.comment_id)(report.comment_id);
  TestValidator.equals("reason_code")(fetched.reason_code)(report.reason_code);
  TestValidator.equals("reason_description")(fetched.reason_description)(report.reason_description);
  TestValidator.equals("reporter_member_id")(fetched.reporter_member_id)(report.reporter_member_id);
  TestValidator.equals("created_at")(fetched.created_at)(report.created_at);

  // Step 7: Try to fetch with non-existent reportId (should error)
  await TestValidator.error("not found reportId")(() =>
    api.functional.polEcoBoard.admin.comments.reports.at(connection, {
      commentId: comment.id,
      reportId: typia.random<string & tags.Format<"uuid">>(), // random unassociated report
    }),
  );

  // Step 8: Try to fetch same reportId, but mismatched/wrong commentId (should error)
  await TestValidator.error("mismatched commentId")(() =>
    api.functional.polEcoBoard.admin.comments.reports.at(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(), // wrong commentId
      reportId: report.id,
    }),
  );

  // Step 9: Try to fetch as non-admin (simulate by clearing connection.headers.Authorization)
  // Save old token, remove Authorization, try API, restore
  const oldAuth = connection.headers?.Authorization;
  if (connection.headers) delete connection.headers.Authorization;
  await TestValidator.error("forbidden for non-admin")(() =>
    api.functional.polEcoBoard.admin.comments.reports.at(connection, {
      commentId: comment.id,
      reportId: report.id,
    }),
  );
  // Restore admin token
  if (connection.headers && oldAuth) connection.headers.Authorization = oldAuth;
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPageIPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * E2E test for member role advanced post search with filtering and pagination.
 *
 * This test validates that a registered, logged-in member can retrieve a filtered, paginated list of post summaries using the /polEcoBoard/member/posts API. It focuses on verifying that only accessible posts (not flagged/deleted unless policy allows) are returned, pagination metadata is correct, and business logic such as visibility and filtering is enforced.
 *
 * Steps:
 * 1. Register a new member using the /polEcoBoard/members endpoint with unique account details.
 * 2. Log in as that member using /auth/member/login with their email and password to obtain the API access token (Authorization header is set automatically on the connection object).
 * 3. Perform a search for posts (via /polEcoBoard/member/posts) with various pagination and filter criteria (category, keywords, tags, date, active/unflagged status).
 * 4. Validate the response: ensure the returned posts are limited to those the member should see, response includes correct pagination metadata, and all filter criteria are respected.
 *    - Specially check that flagged or deleted posts are not included (unless policy or permissions change in the future).
 *    - Use multiple filters and paging options: valid results with data, no results for out-of-bounds pages, and empty result set when filters exclude all posts.
 * 5. Validate edge cases (empty result, exceeding page bounds, and only active/unflagged posts shown).
 */
export async function test_api_post_search_member_role_success_filter_pagination(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: "v1.0"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Login as the created member
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(login);

  // 3. Perform post search with various filter and pagination criteria
  // --- Round 1: Default (most permissive) search, expect only non-flagged/non-deleted posts
  const searchFilters = {
    page: 1,
    limit: 10,
    flagged: false,
    deleted: false,
    order_by: "created_at",
    order_dir: "desc",
    with_tags: false
  } satisfies IPolEcoBoardPost.IRequest;

  const page1 = await api.functional.polEcoBoard.member.posts.search(connection, {
    body: searchFilters,
  });
  typia.assert(page1);

  TestValidator.equals("pagination.limit")(page1.pagination.limit)(10);
  TestValidator.equals("pagination.current")(page1.pagination.current)(1);
  TestValidator.predicate("pagination pages >= 1")(page1.pagination.pages >= 1);

  for (const summary of page1.data) {
    TestValidator.equals("flagged is false for all returned posts")(summary.flagged)(false);
  }

  // --- Round 2: Edge case - Request page outside of range (should return empty array with correct pagination)
  const outOfBoundsPage = (page1.pagination.pages || 1) + 1;
  const outOfBoundsFilters = { ...searchFilters, page: outOfBoundsPage } satisfies IPolEcoBoardPost.IRequest;
  const emptyPage = await api.functional.polEcoBoard.member.posts.search(connection, {
    body: outOfBoundsFilters,
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty result set for out-of-bounds page")(emptyPage.data.length)(0);

  // --- Round 3: Keyword search with unlikely string (should return empty array)
  const keyword = `unlikely_keyword_${RandomGenerator.alphaNumeric(10)}`;
  const keywordFilters = { ...searchFilters, search: keyword } satisfies IPolEcoBoardPost.IRequest;
  const keywordPage = await api.functional.polEcoBoard.member.posts.search(connection, {
    body: keywordFilters,
  });
  typia.assert(keywordPage);
  TestValidator.equals("empty result for unmatched keyword")(keywordPage.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPageIPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate unauthorized access to the member posts PATCH search endpoint.
 *
 * This test ensures that attempts to invoke the advanced post summary search for polEcoBoard as a guest (i.e., without any authentication token) are properly rejected by the API. The endpoint is intended for authenticated members only, so any unauthenticated access must be blocked and must not leak post data.
 *
 * Steps:
 * 1. Attempt to perform a PATCH /polEcoBoard/member/posts request WITHOUT authentication (connection has no valid token or JWT is expired).
 * 2. Pass a normal filter/search request body using random/valid values (e.g., page/limit/order/category).
 * 3. Assert that the API returns an authorization error (should be HTTP 401 or 403, depending on implementation).
 * 4. Confirm that the response contains no post data (i.e., no summary rows/data, no pagination object), and that the error message is clear.
 */
export async function test_api_post_search_member_role_unauthorized_access(connection: api.IConnection) {
  // Compose a valid filter/search body using random data
  const searchBody: IPolEcoBoardPost.IRequest = {
    page: 1,
    limit: 10,
    search: RandomGenerator.alphaNumeric(8),
    category_id: typia.random<string & tags.Format<"uuid">>(),
  };

  // Remove Authorization header or ensure it's absent/expired
  const guestConnection = {
    ...connection,
    headers: {
      ...connection.headers,
    },
  };
  delete guestConnection.headers.Authorization;

  // Attempt the unauthorized call and expect an error
  await TestValidator.error("unauthorized access should fail")(
    async () => {
      await api.functional.polEcoBoard.member.posts.search(guestConnection, {
        body: searchBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardThirdPartyAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardThirdPartyAuditLog";
import type { IPageIPolEcoBoardThirdPartyAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardThirdPartyAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for searching third-party audit logs with filters and pagination by an admin.
 *
 * Business context:
 * Admin users need to review external system interactions for compliance and incident investigation. This function validates that admins can effectively search and filter logs by provider key, event type, result, and date range, and that pagination works as expected. Also, only admins may access this endpoint, and searching with invalid query parameters is properly handled.
 *
 * Steps:
 * 1. Register a new admin account for authentication.
 * 2. Login as the admin to obtain JWT token (session).
 * 3. Create multiple third-party audit logs with diverse provider_key, event_type, and result_code values, spread across various timestamps and with optional correlation_id.
 * 4. Search using no filters and verify all records are returned, pagination metadata matches.
 * 5. Search using single filters (by provider_key, by event_type, by result_code) and confirm only correct logs are returned for each filter.
 * 6. Search using time range filters (from_date, to_date) and confirm date filtering works and pagination metadata updates correctly.
 * 7. Search with a combination of filters and check that the intersection result is correct.
 * 8. Search with filters guaranteed not to match any log (invalid provider_key, event_type) and verify results are empty and metadata shows zero records.
 * 9. Attempt search as a non-admin (unauthenticated) and verify access is denied.
 * 10. Attempt search with invalid parameter types and confirm a precise error message is returned (e.g., using string instead of int32 for page).
 */
export async function test_api_third_party_audit_logs_search_various_filters_and_pagination(connection: api.IConnection) {
  // 1. Register new admin for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(signUpResponse);

  // 2. Login as admin to get session (Authorization header set)
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(signInResponse);

  // 3. Create diverse audit logs for testing filters and pagination
  const testLogs = [
    {
      provider_key: "google",
      event_type: "auth_flow_start",
      event_payload: "{}",
      result_code: "success",
      correlation_id: "CORR-001",
      created_at: new Date(Date.now() - 86400000 * 3).toISOString()
    },
    {
      provider_key: "analytics",
      event_type: "api_call",
      event_payload: "{}",
      result_code: "failure",
      correlation_id: "CORR-002",
      created_at: new Date(Date.now() - 86400000 * 2).toISOString()
    },
    {
      provider_key: "anti_spam",
      event_type: "token_refresh",
      event_payload: "{}",
      result_code: "timeout",
      correlation_id: "CORR-003",
      created_at: new Date(Date.now() - 86400000).toISOString()
    },
    {
      provider_key: "analytics",
      event_type: "api_call",
      event_payload: '{}',
      result_code: "success",
      correlation_id: null,
      created_at: new Date(Date.now()).toISOString()
    }
  ];
  const createdLogIds: string[] = [];
  for (const log of testLogs) {
    const output = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.create(connection, {
      body: {
        provider_key: log.provider_key,
        event_type: log.event_type,
        event_payload: log.event_payload,
        result_code: log.result_code,
        correlation_id: log.correlation_id
      } satisfies IPolEcoBoardThirdPartyAuditLog.ICreate
    });
    typia.assert(output);
    createdLogIds.push(output.id);
  }

  // 4. Search with no filters; should return all created logs
  const allLogsResult = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.search(connection, {
    body: { page: 1, limit: 100 } satisfies IPolEcoBoardThirdPartyAuditLog.IRequest
  });
  typia.assert(allLogsResult);
  TestValidator.predicate("all logs returned")(
    allLogsResult.data.some(d => createdLogIds.includes(d.id))
  );
  TestValidator.equals("pagination matches")(allLogsResult.pagination.records >= testLogs.length ? allLogsResult.pagination.records : testLogs.length)(allLogsResult.pagination.records);

  // 5. Filter by provider_key
  const googleLogs = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.search(connection, {
    body: { provider_key: "google" } satisfies IPolEcoBoardThirdPartyAuditLog.IRequest
  });
  typia.assert(googleLogs);
  TestValidator.predicate("provider_key filter works")(
    googleLogs.data.every(d => d.provider_key === "google")
  );

  // 6. Filter by event_type
  const apiCallLogs = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.search(connection, {
    body: { event_type: "api_call" } satisfies IPolEcoBoardThirdPartyAuditLog.IRequest
  });
  typia.assert(apiCallLogs);
  TestValidator.predicate("event_type filter works")(
    apiCallLogs.data.every(d => d.event_type === "api_call")
  );

  // 7. Filter by date range
  const fromDate = new Date(Date.now() - 86400000 * 2.5).toISOString();
  const toDate = new Date().toISOString();
  const dateRangeLogs = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.search(connection, {
    body: { from_date: fromDate, to_date: toDate } satisfies IPolEcoBoardThirdPartyAuditLog.IRequest
  });
  typia.assert(dateRangeLogs);
  TestValidator.predicate("date filter works")(
    dateRangeLogs.data.every(d => d.created_at >= fromDate && d.created_at <= toDate)
  );

  // 8. Combined filters: provider_key + event_type
  const combinedLogs = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.search(connection, {
    body: { provider_key: "analytics", event_type: "api_call" } satisfies IPolEcoBoardThirdPartyAuditLog.IRequest
  });
  typia.assert(combinedLogs);
  TestValidator.predicate("combined filters work")(
    combinedLogs.data.every(d => d.provider_key === "analytics" && d.event_type === "api_call")
  );

  // 9. Non-matching filter (should return empty)
  const noMatchLogs = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.search(connection, {
    body: { provider_key: "nonexistent", event_type: "foobar" } satisfies IPolEcoBoardThirdPartyAuditLog.IRequest
  });
  typia.assert(noMatchLogs);
  TestValidator.equals("no logs found")(noMatchLogs.data.length)(0);
  TestValidator.equals("pagination zero")(noMatchLogs.pagination.records)(0);

  // 10. Attempt search as unauthenticated user (should fail with access error)
  const anonConnection = { ...connection, headers: {} };
  await TestValidator.error("access denied for non-admin")(
    async () => {
      await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.search(anonConnection, {
        body: { provider_key: "google" } satisfies IPolEcoBoardThirdPartyAuditLog.IRequest
      });
    }
  );

  // 11. Attempt search with invalid parameter type for 'page' (should fail with validation error)
  await TestValidator.error("validation error for page param")(
