import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardThirdPartyAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardThirdPartyAuditLog";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate updating of polEcoBoard third-party audit logs via the admin API.
 *
 * This test covers both successful field updates by a privileged admin and business/policy constraint violations such as attempts to update an immutable or deleted log. It also verifies permission enforcement for non-admin access attempts.
 *
 * Step-by-step process:
 * 1. Register a unique admin account.
 * 2. Log in as that admin to obtain the auth token (handled in connection object).
 * 3. Insert a new third-party audit log entry via POST /polEcoBoard/admin/thirdPartyAuditLogs.
 * 4. Update allowed fields (event_type, result_code, event_payload, correlation_id) for the inserted audit log using PUT /polEcoBoard/admin/thirdPartyAuditLogs/{thirdPartyAuditLogId} as the admin. Assert all updates persist as expected.
 * 5. Attempt an invalid update such as empty result_code to validate business constraint enforcement (should return error).
 * 6. Attempt to update a non-existent/invalid UUID log (should return error).
 * 7. Permission error: try update call without being an admin (clear auth header on connection), expecting a permission error.
 */
export async function test_api_third_party_audit_log_update_success_and_constraint_violations(
  connection: api.IConnection,
) {
  // 1. Register admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin (refresh token in connection)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Insert an initial third-party audit log entry
  const originalLog = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.create(connection, {
    body: {
      provider_key: "analytics",
      event_type: "api_call",
      event_payload: JSON.stringify({ action: "query", count: 1 }),
      result_code: "success",
      correlation_id: RandomGenerator.alphaNumeric(12),
    } satisfies IPolEcoBoardThirdPartyAuditLog.ICreate,
  });
  typia.assert(originalLog);

  // 4. Update allowed fields for the log, assert changes persist
  const updateInput = {
    event_type: "api_response",
    result_code: "failure",
    event_payload: JSON.stringify({ error: "timeout" }),
    correlation_id: RandomGenerator.alphaNumeric(15),
  } satisfies IPolEcoBoardThirdPartyAuditLog.IUpdate;
  const updatedLog = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.update(connection, {
    thirdPartyAuditLogId: originalLog.id,
    body: updateInput,
  });
  typia.assert(updatedLog);
  TestValidator.equals("event_type updated")(updatedLog.event_type)(updateInput.event_type);
  TestValidator.equals("result_code updated")(updatedLog.result_code)(updateInput.result_code);
  TestValidator.equals("event_payload updated")(updatedLog.event_payload)(updateInput.event_payload);
  TestValidator.equals("correlation_id updated")(updatedLog.correlation_id)(updateInput.correlation_id);

  // 5. Attempt update with an invalid value (e.g. empty result_code)
  await TestValidator.error("empty result_code should fail")(() =>
    api.functional.polEcoBoard.admin.thirdPartyAuditLogs.update(connection, {
      thirdPartyAuditLogId: originalLog.id,
      body: {
        result_code: "",
      },
    }),
  );

  // 6. Attempt update to a non-existent log (invalid UUID)
  await TestValidator.error("update on non-existent log")(async () =>
    api.functional.polEcoBoard.admin.thirdPartyAuditLogs.update(connection, {
      thirdPartyAuditLogId: typia.random<string & tags.Format<"uuid">>(),
      body: { result_code: "fail" },
    }),
  );

  // 7. Permission error: try update call without being an admin (clear auth header)
  const nonAdminConnection = { ...connection, headers: {} };
  await TestValidator.error("update without admin privilege")(async () =>
    api.functional.polEcoBoard.admin.thirdPartyAuditLogs.update(nonAdminConnection, {
      thirdPartyAuditLogId: originalLog.id,
      body: { result_code: "fail" },
    }),
  );
}

