/**
 * Validate admin soft-deletion of a third-party integration audit log.
 *
 * This test simulates a privileged admin soft-deleting a third-party integration audit log entry
 * and confirms correct business behavior as well as security rules enforcement:
 *
 * 1. Admin is registered and logged in to obtain necessary privileges
 * 2. A new audit log is created (as the target for deletion)
 * 3. Admin issues a DELETE request for this audit log (soft delete)
 * 4. Any further DELETE for the same log must yield an error (already deleted)
 * 5. Attempts to delete as an unprivileged/non-admin should yield a permission error
 *
 * Steps:
 * 1. Register a new admin account with unique credentials
 * 2. Log in with this admin to acquire tokens for privileged access
 * 3. Create a third-party audit log record as the admin
 * 4. Soft-delete the audit log via admin DELETE endpoint
 * 5. Attempt to delete again and expect an error (already deleted)
 * 6. Simulate an unprivileged context and attempt deletion—should yield permission error
 */
export async function test_api_third_party_audit_log_soft_delete_and_access_after_deletion(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Log in as admin
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Create audit log as admin
  const auditLogCreateInput = {
    provider_key: RandomGenerator.alphaNumeric(8),
    event_type: "api_call",
    event_payload: "{}",
    result_code: "success",
    correlation_id: RandomGenerator.alphaNumeric(10),
  } satisfies IPolEcoBoardThirdPartyAuditLog.ICreate;
  const createdLog = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.create(connection, {
    body: auditLogCreateInput,
  });
  typia.assert(createdLog);

  // 4. Soft-delete the audit log
  await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.erase(connection, {
    thirdPartyAuditLogId: createdLog.id,
  });

  // 5. Attempt to delete again (should raise error)
  await TestValidator.error("Deleting already deleted log must fail")(
    () => api.functional.polEcoBoard.admin.thirdPartyAuditLogs.erase(connection, {
      thirdPartyAuditLogId: createdLog.id,
    }),
  );

  // 6. Simulate unprivileged context (no admin tokens/headers)
  const unprivilegedConnection = {
    ...connection,
    headers: {},
  };
  await TestValidator.error("Unprivileged user cannot delete audit logs")(
    () => api.functional.polEcoBoard.admin.thirdPartyAuditLogs.erase(unprivilegedConnection, {
      thirdPartyAuditLogId: createdLog.id,
    }),
  );
}

