  TestValidator.equals("target_resource immutable")(updated.target_resource)(originalRecord.target_resource);
  TestValidator.equals("recorded_at immutable")(updated.recorded_at)(originalRecord.recorded_at);

  // updated_at should reflect the update and be after or equal to created_at
  TestValidator.predicate("updated_at should be >= created_at")(
    updated.updated_at >= updated.created_at,
  );

  // 6. (If more API endpoints existed: Confirm a new audit entry for this update was added)
  // For now, only validate as much as allowed by public API response
}

