  // ------ 5. Use admin JWT to create an audit trail record ------
  connection.headers = { ...connection.headers, Authorization: adminToken };
  const auditTrail: IPolEcoBoardAuditTrail = await api.functional.polEcoBoard.admin.auditTrails.create(connection, {
    body: {
      action_type: "CONFIG_CHANGE",
      performed_by_id: member.id, // We'll use the member's ID as an actor for variety
      target_resource: RandomGenerator.alphaNumeric(8),
      audit_context: RandomGenerator.paragraph()(),
      recorded_at: new Date().toISOString()
    } satisfies IPolEcoBoardAuditTrail.ICreate,
  });
  typia.assert(auditTrail);

  // ------ 6. Switch authentication to member (non-admin) ------
  connection.headers = { ...connection.headers, Authorization: memberToken };

  // ------ 7. Attempt forbidden deletion (should throw) ------
  await TestValidator.error("Non-admin cannot delete audit trail")(
    async () => {
      await api.functional.polEcoBoard.admin.auditTrails.erase(connection, {
        auditTrailId: auditTrail.id
      });
