/**
 * Validate successful retrieval of an incident detail by admin user.
 *
 * This test simulates the full workflow an admin must follow to fetch an incident detail from the system. It covers admin registration, login, incident creation, and incident detail fetching. It ensures business-critical details match between create and get-detail and confirms no sensitive fields are leaked and that access is allowed only for admins.
 *
 * Steps:
 * 1. Register a new admin account
 * 2. Authenticate as the admin (token is set in connection automatically)
 * 3. Create a new incident (with specific code, category, status, etc)
 * 4. Fetch the incident by its id via the admin GET endpoint
 * 5. Validate that all relevant fields match between create and detail (incident_code, category, status, description, detected_at, etc.)
 * 6. Verify that sensitive/jwt fields are not returned in the get-detail response
 * 7. Confirm admin-only access (edge case covered in separate test)
 */
export async function test_api_incident_detail_fetch_success(connection: api.IConnection) {
  // 1. Register new admin account
  const email: string & tags.Format<"email"> = typia.random<string & tags.Format<"email">>();
  const password: string & tags.MinLength<8> & tags.MaxLength<128> = RandomGenerator.alphaNumeric(12);
  const signUpRes: IPolEcoBoardAdminAuth.SignUpResponse =
