  // 2. Login as admin to get auth token (re-sets Authorization header)
  const signInRes: IPolEcoBoardAdminAuth.SignInResponse =
    await api.functional.auth.admin.login.signIn(connection, {
      body: {
        email,
        password,
      } satisfies IPolEcoBoardAdminAuth.SignIn,
    });
  typia.assert(signInRes);

  // 3. Register a new incident with controlled/randomized fields
  const incidentInput: IPolEcoBoardIncident.ICreate = {
    incident_code: `TEST_${RandomGenerator.alphaNumeric(6).toUpperCase()}`,
    category: RandomGenerator.pick([
      "OUTAGE",
      "BREACH",
      "COMPLIANCE",
      "LEGAL",
      "MAINTENANCE",
    ]),
    status: RandomGenerator.pick(["OPEN", "RESOLVED"]),
    description: RandomGenerator.paragraph()(),
    detected_at: new Date().toISOString(),
  };
  const incidentCreated: IPolEcoBoardIncident =
    await api.functional.polEcoBoard.admin.incidents.create(connection, {
      body: incidentInput,
    });
