  // 5. Validate incident details match between create & get-detail
  TestValidator.equals("incident_code matches")(incidentDetail.incident_code)(incidentInput.incident_code);
  TestValidator.equals("category matches")(incidentDetail.category)(incidentInput.category);
  TestValidator.equals("status matches")(incidentDetail.status)(incidentInput.status);
  TestValidator.equals("description matches")(incidentDetail.description)(incidentInput.description);
  TestValidator.equals("detected_at matches")(incidentDetail.detected_at)(incidentInput.detected_at);

  // 6. Basic schema-check: id, timestamps, and ensure no sensitive info is leaked
  TestValidator.predicate("id should be defined and uuid")(!!incidentDetail.id && incidentDetail.id.length > 0);
  TestValidator.predicate("created_at timestamp present")(!!incidentDetail.created_at && incidentDetail.created_at.length > 0);
  TestValidator.predicate("updated_at timestamp present")(!!incidentDetail.updated_at && incidentDetail.updated_at.length > 0);
  // resolved_at and deleted_at should be undefined or null by default
  TestValidator.predicate("resolved_at default is null or undefined")(incidentDetail.resolved_at === null || incidentDetail.resolved_at === undefined);
  TestValidator.predicate("deleted_at default is null or undefined")(incidentDetail.deleted_at === null || incidentDetail.deleted_at === undefined);
}

