import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate retrieval of a member's own vote on a post, and rejection of invalid or unauthorized accesses.
 *
 * This test covers the following flows:
 * 1. Register as a member (user A), and log in to get a connection with authentication.
 * 2. Create a new post as the logged-in member.
 * 3. Cast a vote (upvote or downvote) on the post as the logged-in member.
 * 4. Retrieve the vote just cast using its voteId and postId, and verify that all details match the cast vote.
 * 5. Try to retrieve a vote with a random/non-existent voteId on the same post; confirm error is thrown.
 * 6. Register and log in as a different member (user B).
 * 7. As user B, attempt to retrieve user A's vote; confirm permission denial or error is thrown.
 */
export async function test_api_post_vote_member_retrieve_own_vote_success_and_errors(
  connection: api.IConnection,
) {
  // 1. Register user A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 2. Log in as user A
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create a post as user A
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: "Test Post for Vote Retrieval",
      body: "This is a post created to test retrieval of the member's own vote.",
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Cast a vote as user A
  const voteValue: 1 | -1 = RandomGenerator.pick([1, -1]);
  const vote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: {
      vote_value: voteValue,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 5. Retrieve the vote using postId and voteId, verify details
  const retrievedVote = await api.functional.polEcoBoard.member.posts.votes.at(connection, {
    postId: post.id,
    voteId: vote.id,
  });
  typia.assert(retrievedVote);
  TestValidator.equals("vote id matches")(retrievedVote.id)(vote.id);
  TestValidator.equals("post id matches")(retrievedVote.post_id)(post.id);
  TestValidator.equals("vote value matches")(retrievedVote.vote_value)(voteValue);

  // 6. Try to retrieve a non-existent vote (random voteId)
  await TestValidator.error("non-existent voteId returns error")(async () => {
    await api.functional.polEcoBoard.member.posts.votes.at(connection, {
      postId: post.id,
      voteId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 7. Register and log in as user B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 8. As user B (now logged in), attempt to retrieve user A's vote
  await TestValidator.error("cannot access another member's vote")(async () => {
    await api.functional.polEcoBoard.member.posts.votes.at(connection, {
      postId: post.id,
      voteId: vote.id,
    });
  });
}

