/**
 * Validate that updating global service settings requires admin privileges.
 *
 * The goal is to ensure that only properly authenticated admins can update the global polEcoBoard system settings. 
 * Attempt the update first with no authentication (unauthenticated call), then with a non-admin (member or invalid) token.
 * In both cases, the attempt should be denied with an authorization error (401 or 403) and must not succeed.
 *
 * Step-by-step process:
 * 1. Register a valid admin account (setup, to ensure platform is not in a pristine or uninitialized state).
 * 2. Attempt to update service settings WITHOUT any Authorization header (unauthenticated).
 *    Expect an error: API must reject the request.
 * 3. Attempt to update service settings WITH a fake/bogus/non-admin (simulated member-level/invalid) Authorization header.
 *    Expect an error: API must reject the request.
 * 4. At each step, use valid patch data. Assert that the request fails (error is thrown), regardless of error message or status.
 *
 * Notes:
 * - No attempt is made here to validate error details or status codes, just that the operation is not permitted.
 * - Since there is no member or non-admin registration/login API, step 3 uses a clearly invalid/fake JWT to simulate a non-admin attempt.
 */
export async function test_api_service_settings_update_unauthorized(connection: api.IConnection) {
  // 1. Register a valid admin (setup, ensures service settings can be updated legitimately if needed)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
