    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminReg);

  // Settings patch to attempt in negative cases
  const patch: IPolEcoBoardServiceSettings.IUpdate = {
    registration_enabled: false,
    max_post_length: 1234,
    max_comment_length: 4321,
    default_board_visibility: false,
    data_retention_days: 5,
  };

  // 2. Try updating service settings WITHOUT authentication (no Authorization header)
  TestValidator.error("unauthenticated settings update must be denied")(async () => {
    const unauthConn: api.IConnection = {
      ...connection,
      headers: Object.fromEntries(Object.entries(connection.headers??{}).filter(([key]) => key.toLowerCase()!=="authorization")),
    };
    await api.functional.polEcoBoard.admin.serviceSettings.update(unauthConn, { body: patch });
  });

  // 3. Try updating service settings WITH a fake/bogus/non-admin Authorization header
  TestValidator.error("non-admin settings update must be denied")(async () => {
    const fakeConn: api.IConnection = {
      ...connection,
      headers: {
        ...connection.headers,
        Authorization: "Bearer fakemembernonadmin.jwt.token",
      },
    };
    await api.functional.polEcoBoard.admin.serviceSettings.update(fakeConn, { body: patch });
  });
}

