import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that unauthorized and admin users have correct access to guest session search endpoint (/polEcoBoard/admin/guests).
 *
 * This test verifies strict access control for the guest search feature. It confirms that unauthenticated requests do not succeed (no JWT), and that authenticated admin requests do succeed. Attempts to use a non-admin token are not implemented, as no non-admin/member endpoints are available in provided API.
 *
 * Steps:
 * 1. Attempt to search for guests without any authentication. Expect an authorization error.
 * 2. Register a new admin user.
 * 3. Login as the admin user to obtain a valid admin JWT (for positive control).
 * 4. Remove the Authorization header (to simulate guest/no-token access) and call again. Expect an error.
 * 5. As a positive control, with the valid admin JWT, confirm access works and guest data is returned.
 */
export async function test_api_guest_session_search_unauthorized(connection: api.IConnection) {
  // 1. Attempt search without any authentication (bare/guest access)
  await TestValidator.error("Guest access should be denied")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.search(connection, {
        body: typia.random<IPolEcoBoardGuest.IRequest>(),
      });
    }
  );

  // 2. Register a new admin user for test
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 3. Login as the admin
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);
  const adminToken = loginResp.setHeaders.Authorization;

  // 4. Try search again with Authorization header forcibly removed (simulate unauthenticated)
  const guestConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(([k]) => k !== "Authorization")
    )
  };
  await TestValidator.error("Explicitly no-Authorization should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.search(guestConnection, {
        body: typia.random<IPolEcoBoardGuest.IRequest>(),
      });
    }
  );

  // 5. With the valid admin JWT, access works (positive control)
  const adminConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: adminToken,
    },
  };
  const success = await api.functional.polEcoBoard.admin.guests.search(adminConnection, {
    body: typia.random<IPolEcoBoardGuest.IRequest>(),
  });
  typia.assert(success);
}

