import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate error response for attempting to create a duplicate category name in polEcoBoard admin.
 *
 * This test verifies that the API enforces uniqueness on the category name field when creating board categories. It simulates a typical admin workflow:
 * 1. Register a new admin using a unique email address and secure password.
 * 2. Log in as the newly registered admin to obtain authorization tokens.
 * 3. Create the first category with a newly generated, unique name.
 * 4. Attempt to create a second category with the exact same "name" (and any valid values for other fields).
 * 5. Confirm the system responds with an error (conflict/business rule violation), indicating category name uniqueness is enforced.
 *
 * Steps:
 * 1. Generate unique admin credentials and register the admin account using api.functional.auth.admin.register.signUp
 * 2. Log in with those credentials using api.functional.auth.admin.login.signIn (token is automatically handled in connection)
 * 3. Generate a random, unique string for the category "name"
 * 4. Compose a valid IPolEcoBoardCategory.ICreate payload and create the category (api.functional.polEcoBoard.admin.categories.create)
 * 5. Attempt another category creation with the exact same "name" (other fields can differ)
 * 6. Validate that an error is thrown (TestValidator.error), confirming duplicate names are rejected at the business rule level
 */
export async function test_api_category_creation_duplicate_name_error(
  connection: api.IConnection,
) {
  // 1. Prepare unique admin credentials
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string =
    RandomGenerator.alphaNumeric(10) + "#1Aa"; // Enforce complexity

  // 2. Register the admin
  const signUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResult);

  // 3. Log in as this admin
  const signInResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResult);

  // 4. Generate a unique category name
  const categoryName: string = "Test Category " + RandomGenerator.alphaNumeric(8);

  // 5. Create the initial category
  const firstCategory = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: RandomGenerator.paragraph()(1),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(firstCategory);
  TestValidator.equals("category name matches")(firstCategory.name)(categoryName);

  // 6. Attempt to create a second category with duplicate name
  TestValidator.error("duplicate category name should fail")(async () => {
    await api.functional.polEcoBoard.admin.categories.create(connection, {
      body: {
        name: categoryName, // duplicate
        description: RandomGenerator.paragraph()(1),
        display_order: typia.random<number & tags.Type<"int32">>(),
      } satisfies IPolEcoBoardCategory.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate updating categories as an admin, including error scenarios for uniqueness conflicts and partial updates.
 *
 * This test covers:
 * 1. Register and login as an admin user for API access.
 * 2. Creating two categories to provide context for unique constraint and partial update testing.
 * 3. Updating the first category (all fields) and verifying response reflects correct update values and updated_at timestamp.
 * 4. Uniqueness conflict: trying to update the second category's name to the (now-updated) first category's name should trigger an error.
 * 5. Partial update: updating only the description of the second category verifies that unchanged fields remain unaltered.
 */
export async function test_api_category_update_success_and_conflict(
  connection: api.IConnection
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword =
    "AdminPwd1!" + typia.random<string>().slice(0, 8); // At least 8 chars & some complexity
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as the admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create two categories for update/uniqueness scenarios
  const category1Input = {
    name: "Eco Economy " + typia.random<string>().slice(0, 6),
    description: "First eco category: " + typia.random<string>().slice(0, 10),
    display_order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IPolEcoBoardCategory.ICreate;
  const category2Input = {
    name: "Eco Env " + typia.random<string>().slice(0, 6),
    description: "Second eco category: " + typia.random<string>().slice(0, 10),
    display_order: category1Input.display_order + 1,
  } satisfies IPolEcoBoardCategory.ICreate;

  const category1 = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    { body: category1Input }
  );
  typia.assert(category1);
  const category2 = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    { body: category2Input }
  );
  typia.assert(category2);

  // Save previous updated_at for later assertion
  const category1PrevUpdatedAt = category1.updated_at;

  // 4. Update the first category (all fields)
  const category1Update: IPolEcoBoardCategory.IUpdate = {
    name: category1.name + " Updated",
    description: (category1.description ?? "") + " (edited)",
    display_order: category1.display_order + 10,
  };
  const updatedCategory1 =
    await api.functional.polEcoBoard.admin.categories.update(connection, {
      categoryId: category1.id,
      body: category1Update,
    });
  typia.assert(updatedCategory1);
  TestValidator.notEquals("updated_at changed")(
    updatedCategory1.updated_at
  )(category1PrevUpdatedAt);
  TestValidator.equals("updated name")(
    updatedCategory1.name
  )(category1Update.name);
  TestValidator.equals("updated description")(
    updatedCategory1.description
  )(category1Update.description);
  TestValidator.equals("updated display_order")(
    updatedCategory1.display_order
  )(category1Update.display_order);

  // 5. Uniqueness conflict: try to update category 2's name to category1's (now updated) name
  await TestValidator.error("duplicate category name should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.categories.update(connection, {
        categoryId: category2.id,
        body: {
          name: updatedCategory1.name,
        },
      });
    }
  );

  // 6. Partial update: just update the description of the second category
  const partialDescription = (category2.description ?? "") + " (partial update)";
  const partiallyUpdatedCategory2 =
    await api.functional.polEcoBoard.admin.categories.update(connection, {
      categoryId: category2.id,
      body: {
        description: partialDescription,
      },
    });
  typia.assert(partiallyUpdatedCategory2);
  TestValidator.equals("description updated")(
    partiallyUpdatedCategory2.description
  )(partialDescription);
  TestValidator.equals("name remains unchanged")(
    partiallyUpdatedCategory2.name
  )(category2.name);
  TestValidator.equals("display_order remains unchanged")(
    partiallyUpdatedCategory2.display_order
  )(category2.display_order);
}

