  // 5. Assign moderator to board as admin
  const nowTimestamp = new Date().toISOString();
  const moderatorAssignmentCreateInput: IPolEcoBoardModeratorBoardAssignment.ICreate = {
    pol_eco_board_moderator_id: moderatorRegisterResp.moderatorId,
    pol_eco_board_board_id: board.id,
    assigned_by_admin_id: null, // For test we may set null or use admin - here null for simplicity
    assigned_at: nowTimestamp,
    ended_at: null,
    role_transfer_log: RandomGenerator.paragraph()(),
  };
  const assignment = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.create(
    connection,
    {
      body: moderatorAssignmentCreateInput,
    },
  );
  typia.assert(assignment);
  TestValidator.equals("assignment moderator reference")(assignment.pol_eco_board_moderator_id)(moderatorRegisterResp.moderatorId);
  TestValidator.equals("assignment board reference")(assignment.pol_eco_board_board_id)(board.id);
  TestValidator.equals("assigned_at matches")(assignment.assigned_at)(nowTimestamp);
  TestValidator.equals("role_transfer_log matches")(assignment.role_transfer_log)(moderatorAssignmentCreateInput.role_transfer_log);

  // 6. Retrieve assignment detail by assignment id
  const assignmentDetail = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.at(connection, {
    moderatorBoardAssignmentId: assignment.id,
  });
  typia.assert(assignmentDetail);

  // 7. Validate all expected fields and audit references are present and correct
  TestValidator.equals("assignment detail id")(assignmentDetail.id)(assignment.id);
  TestValidator.equals("moderator")(assignmentDetail.pol_eco_board_moderator_id)(moderatorRegisterResp.moderatorId);
  TestValidator.equals("board")(assignmentDetail.pol_eco_board_board_id)(board.id);
  TestValidator.equals("assigned_at")(assignmentDetail.assigned_at)(nowTimestamp);
  TestValidator.equals("role_transfer_log")(assignmentDetail.role_transfer_log)(moderatorAssignmentCreateInput.role_transfer_log);
  TestValidator.equals("ended_at null")(assignmentDetail.ended_at)(null);
  // Presence of audit fields
  TestValidator.predicate("created_at is ISO date-time")(typeof assignmentDetail.created_at === "string" && assignmentDetail.created_at.includes("T"));
  TestValidator.predicate("updated_at is ISO date-time")(typeof assignmentDetail.updated_at === "string" && assignmentDetail.updated_at.includes("T"));
}

