 * 1. Register new admin (via admin registration endpoint)
 * 2. Admin logs in to establish a privileged session (retrieve JWT token)
 * 3. Admin creates a new discussion board
 * 4. Register a new moderator (to be assigned to the board)
 * 5. Assign the moderator to the created board as the admin (record assignment event)
 * 6. Perform an update to the moderator-board assignment (set ended_at and/or update role_transfer_log)
 * 7. Validate that the updated assignment record returns the correct updated values, and all audit fields are consistent (timestamps updated, new log value recorded)
 */
export async function test_api_moderator_board_assignment_update_success(
  connection: api.IConnection,
) {
