      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin logs in
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(1).slice(0, 32),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(1).slice(0, 100),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 4. Register moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = RandomGenerator.alphaNumeric(10);
  const moderator = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v2025_accepted",
