      pol_eco_board_moderator_id: moderator.moderatorId,
      pol_eco_board_board_id: board.id,
      assigned_by_admin_id: null,
      assigned_at: now,
      ended_at: null,
      role_transfer_log: "Initial assignment by admin.",
    } satisfies IPolEcoBoardModeratorBoardAssignment.ICreate,
  });
