  TestValidator.equals("board id")(updated.pol_eco_board_board_id)(assignment.pol_eco_board_board_id);
  TestValidator.equals("ended_at")(updated.ended_at)(updatedEndedAt);
  TestValidator.equals("role_transfer_log")(updated.role_transfer_log)(updatedRoleTransferLog);
  TestValidator.predicate("updated_at is after created_at")(
    new Date(updated.updated_at) > new Date(assignment.updated_at)
