/**
 * Validates the admin hard deletion of a comment report in the polEcoBoard module.
 *
 * Business context:
 * Admins must be able to permanently remove abusive/invalid comment reports, ensuring audit and compliance. The flow models the typical intervention of site moderation when a report is malicious or misfiled, verifying both permission enforcement and full database deletion (hard-delete semantics).
 *
 * Test process:
 * 1. Register a new admin account and log in (to obtain valid admin session for privileged API calls).
 * 2. Register a member and log in as that member for post/comment actions.
 * 3. Member creates a new post in a board category.
 * 4. Member adds a comment to the newly created post.
 * 5. Member files a report (using any allowed reason code) on the comment.
 * 6. Switch to admin session using admin login credentials.
 * 7. As admin, delete the member-filed report on the comment using the admin hard-delete endpoint.
 * 8. Assert that deletion succeeds with no error.
 * 9. Attempt to delete the same report again to ensure it is fully deleted (should yield error or absence).
 *
 * The test validates both permission checks (admin can hard delete) and business rule (report is fully erased as per hard-delete logic).
 */
export async function test_api_admin_comment_report_hard_delete(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegisterResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminRegisterResp);

  // 2. Admin login (explicit to ensure fresh session)
  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResp);

  // 3. Member registration
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberRegisterResp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRegisterResp);

  // 4. Member login
  const memberLoginResp = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginResp);

  // 5. Member creates a post (category_id must be a uuid, use random for test)
  const postCreate = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()()(40),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postCreate);

  // 6. Member adds a comment to the post
  const commentCreate = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: postCreate.id,
    body: {
      body: RandomGenerator.content()()(8),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentCreate);

  // 7. Member files a report on the comment
  const reportCreate = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: commentCreate.id,
    body: {
      reason_code: "abuse",
      reason_description: RandomGenerator.paragraph()(20),
      comment_id: commentCreate.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
