import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate authorized moderator search, filter, and pagination for moderation actions with permission enforcement.
 *
 * This test case covers the authorized access pattern where a moderator should be able to:
 *   - Register and authenticate with valid credentials
 *   - Perform unfiltered, filtered, and paginated search for moderation actions
 *   - Validate data structure, result filtering, and pagination semantics
 *
 * Also verifies that unauthorized users cannot access moderation actions (returns a permission error).
 *
 * Steps:
 * 1. Register a new moderator with random credentials
 * 2. Login as the moderator to receive authentication tokens
 * 3. As moderator:
 *    a) Search moderation actions with no filters (should return some or empty valid results)
 *    b) Search with sample filters (action type, status); results must match filter conditions
 *    c) Search with pagination options; returned pagination must match the query
 * 4. Remove authorization and retry search to confirm access is forbidden for unauthorized users
 */
export async function test_api_moderation_action_search_by_moderator(connection: api.IConnection) {
  // 1. Register a moderator account for testing
  const email: string = typia.random<string & tags.Format<"email">>();
  const password = "StrongPassword1234!";
  const displayName = RandomGenerator.name();
  const consentStatus = "policy_v1_accepted";
  const registerRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registerRes);

  // 2. Login as the moderator (issue a valid JWT)
  const loginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginRes);

  // 3a. Search moderation actions as the authenticated moderator (no filters)
  const searchRes = await api.functional.polEcoBoard.moderator.moderationActions.search(connection, {
    body: {},
  });
  typia.assert(searchRes);
  TestValidator.equals("pagination - current is int")(typeof searchRes.pagination.current)("number");
  TestValidator.equals("pagination - limit is int")(typeof searchRes.pagination.limit)("number");
  TestValidator.equals("pagination - records is int")(typeof searchRes.pagination.records)("number");
  TestValidator.equals("pagination - pages is int")(typeof searchRes.pagination.pages)("number");
  TestValidator.predicate("data is array of actions")(Array.isArray(searchRes.data));

  // 3b. Filtered search: e.g., only show 'remove'/'completed' moderation events
  const filterRes = await api.functional.polEcoBoard.moderator.moderationActions.search(connection, {
    body: {
      action_type: "remove",
      status: "completed",
    },
  });
  typia.assert(filterRes);
  for (const item of filterRes.data) {
    if (item.action_type !== "remove" || item.status !== "completed")
      throw new Error(
        `Filtered moderation action (id: ${item.id}) returned wrong action_type (${item.action_type}) or status (${item.status})`
      );
  }

  // 3c. Pagination: limit results to one per page, page 1
  const pagedRes = await api.functional.polEcoBoard.moderator.moderationActions.search(connection, {
    body: {
      limit: 1,
      page: 1,
    },
  });
  typia.assert(pagedRes);
  TestValidator.equals("pagination.limit matches query")(pagedRes.pagination.limit)(1);
  TestValidator.equals("pagination.current matches query")(pagedRes.pagination.current)(1);
  TestValidator.predicate("page size <= 1")(pagedRes.data.length <= 1);

  // 4. Remove Authorization header to simulate unauthorized user
  const connectionNoAuth: api.IConnection = {
    ...connection,
    headers: Object.fromEntries(Object.entries(connection.headers ?? {}).filter(([key]) => key.toLowerCase() !== "authorization")),
  };
  await TestValidator.error("unauthenticated search is forbidden")(async () => {
    await api.functional.polEcoBoard.moderator.moderationActions.search(connectionNoAuth, {
      body: {},
    });
  });
}

