 * - Admins must be able to search and filter appeals using key fields, and view sensitive information such as rationale and reviewer identity.
 * - This test ensures that only admins can see full appeal details and that filtering and paging logic behaves as expected for real compliance/reporting use.
 *
 * Test workflow:
 * 1. Register and log in as a new admin (provision test admin credentials).
 * 2. Create several distinct appeals as admin, each with unique filterable properties.
 * 3. Test advanced search by using /polEcoBoard/admin/appeals PATCH with filters on appellant_id, status, and outcome.
 * 4. Validate paged results and that all sensitive data is visible (since admin).
 * 5. Confirm filtering works: matching (positive) and non-matching (negative) scenarios.
 */
export async function test_api_appeal_search_admin_role_advanced_filtering(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Log in as this admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create three appeals, each with unique appellant_id, status, and outcome
  const APPEAL_STATUSES = ["pending", "in_review", "resolved"];
  const APPEAL_OUTCOMES = ["approved", "denied", "escalated"];
  const createdAppeals: IPolEcoBoardAppeal[] = [];
  for (let i = 0; i < 3; i++) {
    const appealInput = {
      moderation_action_id: typia.random<string & tags.Format<'uuid'>>(),
      appellant_id: typia.random<string & tags.Format<'uuid'>>(),
      reason: `Appeal for ${APPEAL_STATUSES[i]}`,
      status: APPEAL_STATUSES[i],
    } satisfies IPolEcoBoardAppeal.ICreate;
    const appeal = await api.functional.polEcoBoard.admin.appeals.create(connection, {
      body: appealInput,
    });
    typia.assert(appeal);
    // Simulate non-pending statuses: set outcome to a known value (status likely determines outcome in real workflow)
    // The outcome may be set server-side on creation by business rules; this test uses created data as baseline
    createdAppeals.push(appeal);
  }

  // 4. Use PATCH /polEcoBoard/admin/appeals with filters
  {
    // Use the 2nd created appeal for filter checks
    const basis = createdAppeals[1];
    const filter = {
      appellant_id: basis.appellant_id,
      status: basis.status,
      outcome: basis.outcome,
    } satisfies IPolEcoBoardAppeal.IRequest;
    const page = await api.functional.polEcoBoard.admin.appeals.index(connection, {
      body: filter,
    });
    typia.assert(page);
    TestValidator.predicate("at least one match")(page.data.length >= 1);
    // Validate that each returned appeal in result matches all filter properties, and sensitive fields are visible
    for (const item of page.data) {
      TestValidator.equals("appellant_id match")(item.appellant_id)(basis.appellant_id);
      TestValidator.equals("status match")(item.status)(basis.status);
      // For admin, sensitive fields like reason and reviewer_admin_id are visible
      TestValidator.predicate("sensitive field - reason present")(typeof item.reason === "string");
      // reviewer_admin_id is optional, but should be visible as key (even if null)
      if ("reviewer_admin_id" in item) {
        // property exists, OK
      }
    }
  }
  // 5. Search with a filter that cannot possibly match (negative test)
  const fakeOutcome = "nonexistent_outcome";
  const emptyPage = await api.functional.polEcoBoard.admin.appeals.index(connection, {
    body: { outcome: fakeOutcome },
  });
  typia.assert(emptyPage);
  TestValidator.equals("no matches")(emptyPage.data.length)(0);
}

