/**
 * Test that a moderator can successfully upvote and downvote posts and that duplicate voting is prevented.
 *
 * Business context:
 *   - Moderators curate content by voting on posts for platform health and rule enforcement.
 *   - Each moderator can vote once per post (upvote or downvote), and cannot vote twice or change their vote by recasting.
 *   - Only member accounts can author posts; moderators must be registered and logged in to vote.
 *
 * This E2E test validates:
 *   1. Moderator account registration with consent and display name
 *   2. Moderator login (credentials set in connection headers)
 *   3. Member registration and login
 *   4. Member post creation (using valid random category uuid)
 *   5. Moderator can upvote (+1) on a post, and duplicate upvotes are rejected
 *   6. Moderator cannot downvote the same post after upvoting (one vote per post per moderator)
 *   7. Moderator can downvote (-1) a different post, and duplicate downvotes/upvotes on same post are rejected
 *   8. All major responses are type-asserted and business rules, including error cases, are enforced
 *
 * Steps:
 *   1. Register and login a new moderator with random email and display name
 *   2. Register and login a member
 *   3. Member creates first post (for upvote)
 *   4. Switch to moderator, upvote the post, verify response
 *   5. Attempt duplicate upvote and then a downvote on the same post — both must fail
 *   6. Member creates a second post
 *   7. Moderator downvotes the new post, verify response
 *   8. Attempt duplicate downvote and then an upvote on the second post — both must fail
 */
export async function test_api_post_vote_creation_moderator_success(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderatorPass1102!";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "test-consent-version";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    },
  });
  typia.assert(moderatorSignUp);

  // 2. Log in as moderator
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);

  // 3. Register and login member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "memberPass1102$";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    },
  });
  typia.assert(memberSignUp);

  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    },
  });
  typia.assert(memberLogin);

  // 4. Member creates post1
  const categoryId1 = typia.random<string & tags.Format<"uuid">>();
  const postTitle1 = RandomGenerator.paragraph()(15, 30).substring(0, 30); // min 10, max 30
  const postBody1 = RandomGenerator.content()()(80, 250).substring(0, 250); // min 10, max 250
  const post1 = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId1,
      title: postTitle1,
      body: postBody1,
    },
  });
  typia.assert(post1);

  // 5. Switch to moderator, upvote post1
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  const voteUp = await api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
    postId: post1.id,
    body: { vote_value: 1 },
  });
  typia.assert(voteUp);
  TestValidator.equals("vote linked to post1 - upvote")(voteUp.post_id)(post1.id);
  TestValidator.equals("vote_value = 1")(voteUp.vote_value)(1);

  // 6. Try duplicate upvote (should fail)
  await TestValidator.error("duplicate upvote rejected")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post1.id,
      body: { vote_value: 1 },
    })
  );
  // 7. Try downvote on already upvoted post (should also fail)
  await TestValidator.error("switch vote from up to down disallowed")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post1.id,
      body: { vote_value: -1 },
    })
  );

  // 8. Member creates post2
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    },
  });
  const categoryId2 = typia.random<string & tags.Format<"uuid">>();
  const postTitle2 = RandomGenerator.paragraph()(15, 30).substring(0, 30);
  const postBody2 = RandomGenerator.content()()(80, 250).substring(0, 250);
  const post2 = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId2,
      title: postTitle2,
      body: postBody2,
    },
  });
  typia.assert(post2);

  // 9. Switch back to moderator, downvote post2
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  const voteDown = await api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
    postId: post2.id,
    body: { vote_value: -1 },
  });
  typia.assert(voteDown);
  TestValidator.equals("vote linked to post2 - downvote")(voteDown.post_id)(post2.id);
  TestValidator.equals("vote_value = -1")(voteDown.vote_value)(-1);

  // 10. Duplicate downvote (should fail)
  await TestValidator.error("duplicate downvote rejected")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post2.id,
      body: { vote_value: -1 },
    })
  );
  // 11. Try upvote on already downvoted post2 (should fail)
  await TestValidator.error("switch vote from down to up disallowed")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post2.id,
      body: { vote_value: 1 },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test that an admin can upvote and downvote any existing post, enforcing all relevant business rules.
 *
 * Business context:
 * Admins may cast upvotes (1) or downvotes (-1) on posts they do not author, as part of board moderation and engagement analytics. The system must forbid duplicate voting (multiple upvotes/downvotes by same admin on the same post) and must prevent voting on one's own authored post if this logic is enforced for admins.
 *
 * Test workflow:
 * 1. Register and login as an admin user. Save email/password for switching sessions as needed.
 * 2. Register a member user and login as member.
 * 3. Create a valid post as the member user.
 * 4. Switch back to admin session (re-login as admin to ensure header/state).
 * 5. Submit an upvote (vote_value = 1) on the post as admin.
 *    - Assert success, response is a valid vote with value +1 and matches post id.
 * 6. Submit a downvote (vote_value = -1) on the same post as admin (which business logic may treat as a distinct vote, or may convert the vote).
 *    - Assert success or business logic as expected. Response is a valid vote with value -1 if the action is allowed, or enforced business logic error.
 * 7. Attempt to upvote or downvote again on the same post as admin (should be forbidden; assert error).
 * 8. (Optional) If admin authors a post themselves, attempt to vote on it; assert forbidden if business rule applies.
 */
export async function test_api_post_vote_creation_admin_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 4. Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postCreate = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(15),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postCreate);
  const postId = postCreate.id;

  // 6. Re-login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Cast upvote as admin
  const upvote = await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(upvote);
  TestValidator.equals("upvote: matches postId")(upvote.post_id)(postId);
  TestValidator.equals("upvote: admin voted")(upvote.vote_value)(1);

  // 8. Cast downvote as admin
  const downvote = await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: -1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(downvote);
  TestValidator.equals("downvote: matches postId")(downvote.post_id)(postId);
  TestValidator.equals("downvote: admin downvoted")(downvote.vote_value)(-1);

  // 9. Attempt duplicate upvote as admin should fail
  await TestValidator.error("duplicate upvote forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });

  // 10. Attempt duplicate downvote as admin should fail
  await TestValidator.error("duplicate downvote forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId,
      body: {
        vote_value: -1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });

  // 11. (Optional/Edge) Admin tries to post and vote on own post (if not forbidden, this step can be skipped)
  const adminPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(15),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(adminPost);
  await TestValidator.error("admin voting on own post forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId: adminPost.id,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a member can update their own post vote (switching upvote/downvote)
 * within allowed window, and cannot update another member's vote or update after deadline
 *
 * - Ensures voters can change their own votes (from upvote to downvote and vice versa)
 *   within the allowable window according to business rules
 * - Unauthorized attempts (by a different member) and late updates are prevented correctly
 *
 * Test Steps:
 * 1. Register and login memberA
 * 2. Create a post as memberA
 * 3. Cast a vote as memberA (upvote)
 * 4. MemberA updates vote to downvote (should succeed)
 * 5. Register and login memberB
 * 6. MemberB attempts to update memberA's vote (should fail)
 * 7. (If business logic exposes, try updating after expiration window -- omitted if not possible)
 */
export async function test_api_post_vote_update_by_member_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Register memberA
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  const signUpA = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpA);

  // 2. Login as memberA (the connection will carry the token)
  const signInA = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInA);

  // 3. Create a post as memberA
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(25),
      body: RandomGenerator.paragraph()(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Cast a vote for that post as memberA (upvote)
  const vote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("vote voter matches author")(vote.voter_member_id)(post.author_member_id);
  TestValidator.equals("vote is upvote")(vote.vote_value)(1);

  // 5. Update the vote to downvote (within allowed window)
  const updatedVote = await api.functional.polEcoBoard.member.posts.votes.update(connection, {
    postId: post.id,
    voteId: vote.id,
    body: {
      vote_value: -1,
    } satisfies IPolEcoBoardVote.IUpdate,
  });
  typia.assert(updatedVote);
  TestValidator.equals("vote flip to downvote")(updatedVote.vote_value)(-1);
  TestValidator.equals("vote id stays same")(updatedVote.id)(vote.id);
  TestValidator.equals("voter remains same")(updatedVote.voter_member_id)(vote.voter_member_id);

  // 6. Register memberB
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  const signUpB = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpB);

  // 7. Login as memberB
  const signInB = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInB);

  // 8. MemberB attempts to update memberA's vote (should fail with error)
  await TestValidator.error("memberB cannot update memberA's vote")(
    async () => {
      await api.functional.polEcoBoard.member.posts.votes.update(connection, {
        postId: post.id,
        voteId: vote.id,
        body: {
          vote_value: 1,
        } satisfies IPolEcoBoardVote.IUpdate,
      });
    },
  );

  // 9. (Omitted: simulate time passing beyond update window, unless supported)
}

