import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a member can successfully delete their own vote (withdraw vote) and that negative delete attempts (wrong user and invalid voteId) are handled properly.
 *
 * Ensures the following workflow and error scenarios:
 * 1. Register and login memberA (to act as the vote owner)
 * 2. Register and login memberB (to use as a "wrong member")
 * 3. MemberA creates a post
 * 4. MemberA casts a vote on their own post
 * 5. MemberA successfully deletes (withdraws) their vote
 * 6. MemberA attempts to delete the same vote again (expect error)
 * 7. MemberB attempts to delete memberA's vote (expect error)
 * 8. Attempt to delete a non-existent voteId (expect error)
 */
export async function test_api_post_vote_delete_by_member_success_and_error_cases(connection: api.IConnection) {
  // 1. Register and login memberA (vote owning member)
  const memberA_email = typia.random<string & tags.Format<"email">>();
  const memberA_password = typia.random<string & tags.Format<"password">>();
  const memberASignup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: memberA_password
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberASignup);

  // Establish session for memberA (perform login)
  const memberASignIn = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberA_email,
      password: memberA_password
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(memberASignIn);

  // 2. Register and login memberB (different account)
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_password = typia.random<string & tags.Format<"password">>();
  const memberBSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberB_email,
      password: memberB_password
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberBSignUp);

  // We'll login as memberB only for negative case, keep credentials handy.

  // 3. MemberA creates a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(20)(),
      tag_ids: [],
      attachments: []
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. MemberA casts a vote on that post
  const vote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: {
      vote_value: 1
    } satisfies IPolEcoBoardVote.ICreate
  });
  typia.assert(vote);

  // 5. MemberA successfully deletes (withdraws) their vote
  await api.functional.polEcoBoard.member.posts.votes.erase(connection, {
    postId: post.id,
    voteId: vote.id
  });

  // 6. Attempt to delete the same vote again (should error)
  await TestValidator.error("memberA cannot double-delete their vote")(async () => {
    await api.functional.polEcoBoard.member.posts.votes.erase(connection, {
      postId: post.id,
      voteId: vote.id
    });
  });

  // 7. Login as memberB and attempt to delete memberA's vote (should error)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password
    } satisfies IMemberAuthenticationMemberSignIn
  });

  await TestValidator.error("memberB cannot delete another member's vote")(async () => {
    await api.functional.polEcoBoard.member.posts.votes.erase(connection, {
      postId: post.id,
      voteId: vote.id
    });
  });

  // 8. Attempt to delete a non-existent voteId (should error)
  const nonExistentVoteId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("cannot delete non-existent voteId")(async () => {
    await api.functional.polEcoBoard.member.posts.votes.erase(connection, {
      postId: post.id,
      voteId: nonExistentVoteId
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardHistory";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can fetch a specific board history event by its UUID.
 *
 * Business Context:
 * This test ensures that a properly authenticated admin can retrieve a board change history record, which is critical for auditing category changes, compliance, and platform transparency. The test fully simulates session, entity creation, and traceability as expected for admin workflows.
 *
 * Steps:
 * 1. Register a unique admin (random email, strong password) for isolation.
 * 2. Login as admin to set proper authorization headers.
 * 3. Create a new board category via admin endpoint
 * 4. Create a new board referencing the created category
 * 5. Create a board history event (initial assignment, using test session as actor_admin)
 * 6. Retrieve the specific board history (by UUID) and assert properties match creation
 * 7. Validate all relevant entity field values are as expected.
 */
export async function test_api_board_history_detail_admin_access_success(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login to update connection header (session admin auth)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create board category
  const category = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(),
        display_order: typia.random<number & tags.Type<"int32">>(),
      } satisfies IPolEcoBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 4. Create board in this category
  const board = await api.functional.polEcoBoard.admin.boards.create(
    connection,
    {
      body: {
        pol_eco_board_category_id: category.id,
        name: RandomGenerator.alphaNumeric(6),
        code: RandomGenerator.alphaNumeric(10).toLowerCase(),
        description: RandomGenerator.paragraph()(),
        is_public: true,
        is_archived: false,
        display_order: typia.random<number & tags.Type<"int32">>(),
      } satisfies IPolEcoBoardBoard.ICreate,
    },
  );
  typia.assert(board);

  // 5. Create board history event with this admin (optional actors are set to null)
  const changedAt: string = new Date().toISOString();
  const history = await api.functional.polEcoBoard.admin.boardHistories.create(
    connection,
    {
      body: {
        pol_eco_board_board_id: board.id,
        previous_category_id: null,
        new_category_id: category.id,
        actor_admin_id: null,
        actor_moderator_id: null,
        change_type: "reassignment",
        change_reason: "Initial assignment",
        changed_at: changedAt,
      } satisfies IPolEcoBoardBoardHistory.ICreate,
    },
  );
  typia.assert(history);

  // 6. Retrieve board history using returned id
  const output = await api.functional.polEcoBoard.admin.boardHistories.at(
    connection,
    {
      boardHistoryId: history.id,
    },
  );
  typia.assert(output);

  // 7. Assert the fetched board history fields
  TestValidator.equals("board association")(output.pol_eco_board_board_id)(
    board.id,
  );
  TestValidator.equals("new category linkage")(output.new_category_id)(
    category.id,
  );
  TestValidator.equals("change_type is reassignment")(
    output.change_type,
  )("reassignment");
  TestValidator.equals("change_reason")(output.change_reason)(
    "Initial assignment",
  );
  TestValidator.equals("changed_at")(output.changed_at)(changedAt);
}

