import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardHistory";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator-driven board structure change logging in polEcoBoard.
 *
 * This test exercises the end-to-end flow required for a moderator to record a structural event—such as migrating a board from one category to another—by first registering a moderator account, performing authentication, creating two board categories, creating a board in the first category, and then logging a board history record noting reassignment from the first to the second category. The correct implementation must confirm that all business rules are respected: both category references must exist, the referenced board must exist, and the change_type (reassignment) must be accepted. Finally, the output must be checked for presence and validity of all relevant board history fields, and that the actor_moderator_id is set (and admin fields are null), confirming the action and audit trail are correct.
 *
 * 1. Register a moderator account
 * 2. Log in as moderator
 * 3. Create the source category
 * 4. Create the destination category
 * 5. Create a board in the source category
 * 6. Post a board history event, moving the board from source to destination category
 * 7. Confirm returned board history fields are valid and business rules are respected
 */
export async function test_api_board_history_create_moderator_success(
  connection: api.IConnection,
) {
  // 1. Register a moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(10);
  const moderatorDisplayName = RandomGenerator.alphaNumeric(8);
  const consentStatus = "2025-privacy-updated-v1";
  const registrationResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registrationResponse);
  const moderatorId = registrationResponse.moderatorId;

  // 2. Log in as moderator (to refresh session/JWT)
  const loginResponse = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResponse);
  TestValidator.equals("moderator login id matches registration")(loginResponse.moderatorId)(moderatorId);

  // 3. Create first (source) category
  const sourceCategory = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(sourceCategory);

  // 4. Create second (destination) category
  const destCategory = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(destCategory);

  // 5. Create a board in the source category
  const boardName = RandomGenerator.alphaNumeric(10);
  const boardCode = RandomGenerator.alphaNumeric(6).toLowerCase();
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: sourceCategory.id,
      name: boardName,
      code: boardCode,
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);
  TestValidator.equals("board category is source category")(board.pol_eco_board_category_id)(sourceCategory.id);

  // 6. Moderator creates a board history event to migrate board between categories
  const now = new Date().toISOString();
  const boardHistory = await api.functional.polEcoBoard.moderator.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: sourceCategory.id,
      new_category_id: destCategory.id,
      actor_admin_id: null,
      actor_moderator_id: moderatorId,
      change_type: "reassignment",
      change_reason: RandomGenerator.paragraph()(),
      changed_at: now,
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(boardHistory);
  // 7. Business rule assertions and audit field checks
  TestValidator.equals("board id")(boardHistory.pol_eco_board_board_id)(board.id);
  TestValidator.equals("previous category")(boardHistory.previous_category_id)(sourceCategory.id);
  TestValidator.equals("new category")(boardHistory.new_category_id)(destCategory.id);
  TestValidator.equals("actor admin is null")(boardHistory.actor_admin_id)(null);
  TestValidator.equals("actor moderator")(boardHistory.actor_moderator_id)(moderatorId);
  TestValidator.equals("change type")(boardHistory.change_type)("reassignment");
  TestValidator.predicate("change reason present")(!!boardHistory.change_reason);
  TestValidator.equals("changed_at at least now")(
    Date.parse(boardHistory.changed_at) >= Date.parse(now)
  )(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
