import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that duplicate board history events for identical changes cannot be created in immediate succession.
 *
 * This test ensures that if an admin submits the same migration (board history) event twice, the business logic prevents the second creation if unique transitions are enforced.
 *
 * Steps:
 * 1. Register a new admin account
 * 2. Login as the admin
 * 3. Create the first board category
 * 4. Create the second (target) board category
 * 5. Create a board under the first category
 * 6. Submit a board migration (reassignment) event from the first to the second category
 * 7. Attempt to submit the exact same migration event again (should fail if business logic works)
 */
export async function test_api_board_history_create_admin_duplicate_event(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create first board category
  const category1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: "Original Category",
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category1);

  // 4. Create second (target) board category
  const category2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: "Target Category",
      display_order: 2,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category2);

  // 5. Create a board under the first category
  const boardName = RandomGenerator.alphabets(12);
  const boardCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category1.id,
      name: boardName,
      code: boardCode,
      description: "Discussion board for migration test",
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 6. Submit migration (board history) event: reassign from category1 to category2
  const now = new Date().toISOString() as string & tags.Format<"date-time">;
  const boardHistoryBody = {
    pol_eco_board_board_id: board.id,
    previous_category_id: category1.id,
    new_category_id: category2.id,
    actor_admin_id: null,
    actor_moderator_id: null,
    change_type: "reassignment",
    change_reason: "Testing category reassignment event.",
    changed_at: now,
  } satisfies IPolEcoBoardBoardHistory.ICreate;

  const firstHistory = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: boardHistoryBody,
  });
  typia.assert(firstHistory);

  // 7. Attempt to submit the same migration event again (should fail)
  await TestValidator.error("duplicate board history event should fail")(() =>
    api.functional.polEcoBoard.admin.boardHistories.create(connection, {
      body: boardHistoryBody,
    })
  );
}

