import type { IPolEcoBoardBoardHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardHistory";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that only authorized moderators can update board history events, and ensure that members without moderator privileges are denied access with proper error feedback.
 *
 * Business context:
 *   - Board history changes are sensitive and should only be mutable by moderators; unauthorized member attempts must be rejected with a clear error and must not mutate data.
 *
 * Step-by-step process:
 * 1. Register a moderator.
 * 2. Moderator logs in (ensure Authorization header is set for privileged actions).
 * 3. Create two categories (needed for simulating a board migration history event).
 * 4. Create a board in the first category.
 * 5. As moderator, create a board history event for a reassignment from category1 to category2.
 * 6. Register a normal member (non-moderator).
 * 7. Login as member (Authorization now for member role).
 * 8. Attempt to update the board history as member (should fail with permission error).
 * 9. Login again as moderator; confirm no mutation has occurred (fetch fresh and assert unchanged fields).
 */
export async function test_api_board_history_update_moderator_no_permission(connection: api.IConnection) {
  // --- 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "v1-terms";
  const moderatorSignUpRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorSignUpRes);
  // After registration, token header set implicitly in connection

  // --- 2. Moderator logs in (refresh Authorization explicitly)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // --- 3. Create two categories
  const category1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category1);
  const category2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category2);

  // --- 4. Create a board in category1
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category1.id,
      name: RandomGenerator.alphaNumeric(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // --- 5. As moderator, create a board history event for reassignment
  const changeType: IPolEcoBoardBoardHistory["change_type"] = "reassignment";
  const boardHistory = await api.functional.polEcoBoard.moderator.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: category1.id,
      new_category_id: category2.id,
      actor_admin_id: undefined, // moderator event, not admin
      actor_moderator_id: moderatorSignUpRes.moderatorId,
      change_type: changeType,
      change_reason: RandomGenerator.paragraph()(),
      changed_at: new Date().toISOString(),
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(boardHistory);

  // --- Save original values for later compare
  const originalHistory = { ...boardHistory };

  // --- 6. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberDisplayName = RandomGenerator.name();
  const memberConsent = "v1-terms";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // API expects pre-hashed but test assumes raw string
      display_name: memberDisplayName,
      consent_status: memberConsent,
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // --- 7. Login as member (this sets member Authorization header)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // --- 8. Attempt to update board history as member (should be forbidden)
  // Try to mutate the history type and change_reason
  const attemptedUpdate: IPolEcoBoardBoardHistory.IUpdate = {
    change_type: "archive",
    change_reason: "User attempted edit",
    actor_admin_id: undefined,
    actor_moderator_id: undefined,
    changed_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(), // 1hr later
  };
  await TestValidator.error("board history update forbidden for member user")(async () => {
    await api.functional.polEcoBoard.moderator.boardHistories.update(connection, {
      boardHistoryId: boardHistory.id,
      body: attemptedUpdate,
    });
  });

  // --- 9. Log back in as moderator and confirm data not mutated
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // No direct "get-by-id" for board history in allowed API, so verify by update (try a no-op mutation as moderator should succeed)
  // (If/when 'get' exists, fetch here and compare)
  // Instead, attempt update with original values to verify it still accepts normal update
  const verifyNewReason = RandomGenerator.paragraph()();
  const fixedUpdate: IPolEcoBoardBoardHistory.IUpdate = {
    change_type: boardHistory.change_type,
    change_reason: verifyNewReason,
    actor_admin_id: undefined,
    actor_moderator_id: moderatorSignUpRes.moderatorId,
    changed_at: new Date().toISOString(),
  };
  const updatedHistory = await api.functional.polEcoBoard.moderator.boardHistories.update(connection, {
    boardHistoryId: boardHistory.id,
    body: fixedUpdate,
  });
  typia.assert(updatedHistory);
  TestValidator.equals("boardHistory id unchanged")(updatedHistory.id)(originalHistory.id);
  // Confirm type and other immutable fields not changed by failed attempt
  TestValidator.equals("boardHistory type unchanged")(
    updatedHistory.change_type
  )(fixedUpdate.change_type);
}

