/**
 * Test retrieving a paginated list of tags assigned to a post for both public and private boards.
 *
 * Ensures:
 * - Access control for public and private boards
 * - Correct tag assignment and retrieval
 * - Pagination and filter correctness
 *
 * Business workflow:
 * 1. Create a board category
 * 2. Create a public board and a private board under the category
 * 3. Register a member
 * 4. Member creates a post on each board
 * 5. Search tags to obtain at least two tag UUIDs
 * 6. Assign two tags to each post via moderator endpoint
 * 7. For PUBLIC post:
 *      a. Retrieve tags as unauthenticated user and validate correctness
 *      b. Check pagination/limit
 * 8. For PRIVATE post:
 *      a. Attempt retrieval unauthenticated (should error)
 *      b. Retrieve as the member and validate results
 */
export async function test_api_post_tag_list_retrieval_public_private_post(
  connection: api.IConnection
) {
  // 1. Create board category
  const category = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.alphaNumeric(24),
        display_order: typia.random<number & tags.Type<"int32">>(),
      },
    }
  );
  typia.assert(category);

  // 2. Create a public board and a private board
  const publicBoard = await api.functional.polEcoBoard.admin.boards.create(
    connection,
    {
      body: {
        pol_eco_board_category_id: category.id,
        name: RandomGenerator.alphaNumeric(12),
        code: RandomGenerator.alphaNumeric(8).toLowerCase(),
        description: RandomGenerator.alphaNumeric(20),
        is_public: true,
        is_archived: false,
        display_order: typia.random<number & tags.Type<"int32">>(),
      },
    }
  );
  typia.assert(publicBoard);

  const privateBoard = await api.functional.polEcoBoard.admin.boards.create(
    connection,
    {
      body: {
        pol_eco_board_category_id: category.id,
        name: RandomGenerator.alphaNumeric(12),
        code: RandomGenerator.alphaNumeric(8).toLowerCase(),
        description: RandomGenerator.alphaNumeric(20),
        is_public: false,
        is_archived: false,
        display_order: typia.random<number & tags.Type<"int32">>(),
      },
    }
  );
  typia.assert(privateBoard);

  // 3. Register member
  const memberEmail = `${RandomGenerator.alphaNumeric(8)}@test.com`;
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.alphaNumeric(10),
      profile_image_uri: null,
      consent_status: "v1-consent",
    },
  });
  typia.assert(member);

  // 4. Member creates post on public board
  // (Assuming after member create, connection uses member identity)
  // If not, an explicit member login API would be needed
  const publicPost = await api.functional.polEcoBoard.member.posts.create(
    connection,
    {
      body: {
        category_id: category.id,
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.paragraph()(40),
        tag_ids: null,
        attachments: null,
      },
    }
  );
  typia.assert(publicPost);

  // Member creates post on private board
  const privatePost = await api.functional.polEcoBoard.member.posts.create(
    connection,
    {
      body: {
        category_id: category.id,
        title: RandomGenerator.paragraph()(12),
        body: RandomGenerator.paragraph()(40),
        tag_ids: null,
        attachments: null,
      },
    }
  );
  typia.assert(privatePost);

  // 5. Search tags to obtain two tag UUIDs
  const tagsPage = await api.functional.polEcoBoard.tags.search(connection, {
    body: {
      limit: 10,
      page: 1,
    },
  });
  typia.assert(tagsPage);
  TestValidator.predicate("enough tags")(tagsPage.data.length >= 2);
  const tag1 = tagsPage.data[0];
  const tag2 = tagsPage.data[1];

  // 6. Assign two tags to each post via moderator endpoint
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: publicPost.id,
    body: { tag_id: tag1.id },
  });
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: publicPost.id,
    body: { tag_id: tag2.id },
  });
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: privatePost.id,
    body: { tag_id: tag1.id },
  });
  await api.functional.polEcoBoard.moderator.posts.postTags.create(connection, {
    postId: privatePost.id,
    body: { tag_id: tag2.id },
  });

  // 7. Retrieve tags for PUBLIC post as unauthenticated user
  {
    const output = await api.functional.polEcoBoard.posts.postTags.search(connection, {
      postId: publicPost.id,
      body: {
        page: 1,
        limit: 2,
      },
    });
    typia.assert(output);
    TestValidator.equals("public post tag count")(output.data.length)(2);
    TestValidator.equals("pagination count")(output.pagination.limit)(2);
    TestValidator.equals("tag-ids for public post")(
      output.data.map((t) => t.tag_id).sort()
    )([
      tag1.id,
      tag2.id,
    ].sort());
  }

  // 8. Retrieve tags for PRIVATE post
  // 8-a. As unauthenticated: expect error
  await TestValidator.error("private post tag listing as unauthenticated fails")(
    async () => {
      await api.functional.polEcoBoard.posts.postTags.search(connection, {
        postId: privatePost.id,
        body: {
          page: 1,
          limit: 2,
        },
      });
    }
  );
  // 8-b. As member (should succeed)
  const privateTags = await api.functional.polEcoBoard.posts.postTags.search(
    connection,
    {
      postId: privatePost.id,
      body: {
        page: 1,
        limit: 2,
      },
    }
  );
  typia.assert(privateTags);
  TestValidator.equals("private post tag count")(privateTags.data.length)(2);
  TestValidator.equals("pagination count")(privateTags.pagination.limit)(2);
  TestValidator.equals("tag-ids for private post")(
    privateTags.data.map((t) => t.tag_id).sort()
  )([
    tag1.id,
    tag2.id,
  ].sort());
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostTag";

/**
 * Validate access control and correct retrieval for post tag assignment detail endpoint.
 *
 * Business context:
 * - The endpoint retrieves the details of a specific post-tag assignment record, given postId and postTagId.
 * - Public posts should allow any user, including guests, to fetch tag assignment details.
 * - Private/restricted posts must restrict tag detail retrieval to authorized users: the post author, moderator, or admin.
 * - Unauthorized/unauthenticated users must get denied access to restricted post tag assignment detail.
 * - Not-found and invalid postTagId or postId are handled with error responses.
 *
 * Steps:
 * 1. Create a board category as admin.
 * 2. Create two discussion boards—one public, one non-public (restricted).
 * 3. As a regular member, create a post in each board.
 * 4. Assign a tag to each post (capture postTagId).
 * 5. Retrieve the tag assignment details for the public post as guest (no authentication), expect success, assert metadata.
 * 6. Retrieve the tag assignment details for the restricted post as guest, expect error (access denied).
 * 7. Retrieve the tag assignment details for the restricted post as the author (member), expect success, assert metadata.
 * 8. Attempt to retrieve a tag assignment detail with an invalid postTagId, expect not found error.
 */
export async function test_api_post_tag_assignment_detail_access_control(connection: api.IConnection) {
  // 1. Create board category as admin
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 2. Create two boards: one public, one restricted
  const publicBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: "Public Board",
      code: RandomGenerator.alphaNumeric(7).toLowerCase(),
      description: "For public posts.",
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(publicBoard);

  const restrictedBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: "Private Board",
      code: RandomGenerator.alphaNumeric(7).toLowerCase(),
      description: "For restricted posts.",
      is_public: false,
      is_archived: false,
      display_order: 2,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(restrictedBoard);

  // 3. As member, create a post in each board
  // (Assume connection is authenticated as a member—test infra usually provides this)
  const publicPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()(1)(2),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(publicPost);

  const restrictedPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()(1)(2),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(restrictedPost);

  // 4. Assign a tag to each post (use fake/random UUID as tag_id, just for assignment demo)
  const tagId1 = typia.random<string & tags.Format<"uuid">>();
  const tagId2 = typia.random<string & tags.Format<"uuid">>();

  const publicPostTag = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: publicPost.id,
    body: {
      tag_id: tagId1,
    } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(publicPostTag);

  const restrictedPostTag = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: restrictedPost.id,
    body: {
      tag_id: tagId2,
    } satisfies IPolEcoBoardPostTag.ICreate,
  });
  typia.assert(restrictedPostTag);

  // 5. Retrieve public post's tag assignment detail as guest (simulate logged-out by clearing connection.headers)
  const guestConnection = { ...connection, headers: {} };
  const publicTagDetail = await api.functional.polEcoBoard.posts.postTags.at(guestConnection, {
    postId: publicPost.id,
    postTagId: publicPostTag.id,
  });
  typia.assert(publicTagDetail);
  TestValidator.equals("public tag assignment tag_id")(publicTagDetail.tag_id)(tagId1);
  TestValidator.equals("public tag assignment post_id")(publicTagDetail.post_id)(publicPost.id);

  // 6. Attempt restricted post's tag assignment as guest, expect error/access denied
  await TestValidator.error("restricted post tag assignment should fail for guest")(async () => {
    await api.functional.polEcoBoard.posts.postTags.at(guestConnection, {
      postId: restrictedPost.id,
      postTagId: restrictedPostTag.id,
    });
  });

  // 7. Retrieve restricted post's tag assignment as member (author), expect success
  const restrictedTagDetail = await api.functional.polEcoBoard.posts.postTags.at(connection, {
    postId: restrictedPost.id,
    postTagId: restrictedPostTag.id,
  });
  typia.assert(restrictedTagDetail);
  TestValidator.equals("restricted tag assignment tag_id")(restrictedTagDetail.tag_id)(tagId2);
  TestValidator.equals("restricted tag assignment post_id")(restrictedTagDetail.post_id)(restrictedPost.id);

  // 8. Attempt to retrieve with invalid postTagId (random UUID), expect not found error
  await TestValidator.error("invalid postTagId (not found) should error")(async () => {
    await api.functional.polEcoBoard.posts.postTags.at(connection, {
      postId: restrictedPost.id,
      postTagId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

