import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationFailure";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin user can update an existing notification failure record, modifying business or error information as required for audit/compliance purposes.
 *
 * This test covers a full privileged admin workflow:
 * 1. Admin registration with unique email and strong password (using the dedicated admin register endpoint)
 * 2. Admin login with those credentials, ensuring a valid Authorization header for further staff operations
 * 3. Creation of a notification failure (with business-populated error fields and notification reference)
 * 4. Issue a PUT update by notificationFailureId to change multiple allowed fields (e.g. failure_code, resolution_status, failure_message)
 * 5. Verify the update response: updated fields reflect changes, non-updated fields remain untouched, and audit columns (updated_at) have changed
 *
 * This ensures proper RBAC, update logic, and audit data compliance for notification failure events.
 */
export async function test_api_notification_failure_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin to obtain JWT (connection's Authorization will update)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a notification failure for updating
  const initialNotificationFailureInput: IPolEcoBoardNotificationFailure.ICreate = {
    notification_id: typia.random<string & tags.Format<"uuid">>(),
    provider_id: typia.random<string & tags.Format<"uuid">>(),
    failure_code: "ERR_INIT_CREATE",
    failure_message: "Initial failure recorded for testing.",
    occurred_at: new Date().toISOString(),
    resolution_status: "pending",
  };
  const created: IPolEcoBoardNotificationFailure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: initialNotificationFailureInput,
  });
  typia.assert(created);

  // 4. Update notification failure with new status, code, and message
  const updateInput: IPolEcoBoardNotificationFailure.IUpdate = {
    failure_code: "ERR_UPDATED",
    resolution_status: "resolved",
    failure_message: "Error resolved after investigation.",
  };
  const updated: IPolEcoBoardNotificationFailure = await api.functional.polEcoBoard.admin.notificationFailures.update(connection, {
    notificationFailureId: created.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 5. Validate update: fields changed, others unchanged, audit updated
  TestValidator.equals("failure_code updated")(updated.failure_code)(updateInput.failure_code);
  TestValidator.equals("resolution_status updated")(updated.resolution_status)(updateInput.resolution_status);
  TestValidator.equals("failure_message updated")(updated.failure_message)(updateInput.failure_message);
  TestValidator.equals("notification_id unchanged")(updated.notification_id)(created.notification_id);
  TestValidator.equals("provider_id unchanged")(updated.provider_id)(created.provider_id);

  TestValidator.predicate("updated_at has changed")(
    updated.updated_at !== created.updated_at
  );
}

