 * It confirms that the deletion sets the deleted_at field, preserves the record for audit/compliance, but makes it inaccessible to non-admin roles.
 *
 * Steps:
 * 1. Register a new admin account (with unique business email and password).
 * 2. Log in as that admin to establish an authenticated session (tokens set in connection).
 * 3. Create a new notification failure record using the admin session.
 * 4. Delete (soft-delete) the notification failure record using its id via the admin-only endpoint.
 * 5. (Validate via SDK call—if supported) Confirm the record's deleted_at is set (if record can be queried as admin).
 * 6. (Validate by business logic/code comment) Confirm that non-admin queries would not return the deleted record and that the record remains in the database for audit/compliance (as per business requirements).
 */
export async function test_api_notification_failure_soft_delete_by_admin(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
