  // 4. Soft delete (mark as deleted_at) this notification failure
  await api.functional.polEcoBoard.admin.notificationFailures.erase(connection, {
    notificationFailureId: notificationFailure.id
  });

  // 5. (If API supports read as admin) Currently, there is no public SDK/API to re-query deleted failures for their deleted_at value.
  //    If available, you would fetch and assert deleted_at is a valid date-time string.

  // 6. By business workflow: After soft delete, record is hidden from non-admin queries but retained for audits.
  //    This E2E test ensures admin-driven deletion logic per contract.
}

