import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IPageIPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPostEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a post author (member) can retrieve the edit history (revision history) of their own post.
 *
 * Business context:
 * - Only an authenticated member (the author) should be able to view the full edit history of their post for audit/compliance.
 * - Edit snapshots are preserved for moderation, rollback, and dispute resolution. The member should see all their historical edits including the original post and any modifications they made.
 *
 * Test steps:
 * 1. Register a new member (author).
 * 2. Login as that member to get authenticated for post operations.
 * 3. Create a post as this member.
 * 4. Edit the post multiple times, each time changing the content.
 * 5. Retrieve the edit history for the post using the author's endpoint.
 * 6. Assert all edits are present and content matches the changes performed in steps 4 and 3.
 */
export async function test_api_post_edit_history_owner_permission_success(
  connection: api.IConnection,
) {
  // 1. Register a new member (author)
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signUpResult);

  // 2. Login as the member to ensure authenticated session
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password },
  });
  typia.assert(signInResult);

  // 3. Create a new post as this member
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const originalTitle = RandomGenerator.paragraph()(typia.random<number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<20>>());
  const originalBody = RandomGenerator.content()(typia.random<number & tags.Type<"int32"> & tags.Minimum<20> & tags.Maximum<100>>())();
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id,
    title: originalTitle,
    body: originalBody,
    attachments: [],
    tag_ids: [],
  };
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(createdPost);

  // 4. Edit the post multiple times; collect every edit body
  const editBodies: string[] = [originalBody];
  for (let i = 0; i < 3; i++) {
    const updateInput: IPolEcoBoardPost.IUpdate = {
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    };
    const updated = await api.functional.polEcoBoard.member.posts.update(connection, {
      postId: createdPost.id,
      body: updateInput,
    });
    typia.assert(updated);
    if (updateInput.body) editBodies.push(updateInput.body);
  }

  // 5. Retrieve the edit history using the author's endpoint
  const historyResult = await api.functional.polEcoBoard.member.posts.postEdits.searchEditHistory(connection, {
    postId: createdPost.id,
    body: { page: 1, limit: 50 },
  });
  typia.assert(historyResult);

  // 6. Assert the revision history contains all of the post body's in order.
  const historyBodies = historyResult.data.map(edit => edit.edit_body);
  editBodies.forEach(editBody => {
    TestValidator.predicate("edit body from workflow appears in revision history")(
      historyBodies.includes(editBody),
    );
  });

  // Confirm that at least as many edits as we made are in the history (should include original)
  TestValidator.predicate("revision count is at least post's edit count + original")(
    historyResult.data.length >= editBodies.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
