 *    c) Valid structure but empty reason string
 *    d) Payload missing moderation_action_id
 *    e) Payload missing appellant_id
 * 4. For each invalid submission, confirm that the API throws a runtime error and that no appeal record is created for bad input.
 */
export async function test_api_moderator_appeal_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "StrongP@ss1!";
