    },
  });
  typia.assert(reg);

  // 2. Log in as the moderator to set the session context
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(login);

  // 3. Valid baseline for reference
  const baseAppeal: IPolEcoBoardAppeal.ICreate = {
    moderation_action_id: typia.random<string & tags.Format<"uuid">>(),
    appellant_id: reg.moderatorId,
    reason: "Moderator believes moderation was unjustified.",
    status: "pending",
  };

  // a) Completely empty object
  await TestValidator.error("Appeal payload completely empty should fail")(() =>
    api.functional.polEcoBoard.moderator.appeals.create(connection, { body: {} as any }),
