      body: (({ appellant_id, reason, status }) => ({ appellant_id, reason, status }))(baseAppeal) as any,
    }),
  );

  // e) appellant_id omitted
  await TestValidator.error("Appeal payload without appellant_id should fail")(() =>
    api.functional.polEcoBoard.moderator.appeals.create(connection, {
      body: (({ moderation_action_id, reason, status }) => ({ moderation_action_id, reason, status }))(baseAppeal) as any,
    }),
  );
}

