 * 2. Log in as that admin to activate admin session.
 * 3. Create a moderation action as the admin (operator_id = admin's UUID for traceability).
 * 4. Submit an appeal as the same admin for the above moderation action (appellant_id = admin's UUID).
 * 5. Verify:
 *    - The appeal is linked to the correct moderation action and admin (appellant)
 *    - Status and reason are as input
 *    - All compliance/audit fields (id, created_at, updated_at, etc.) are present and well-formed
 */
export async function test_api_admin_appeal_creation_success(
  connection: api.IConnection,
) {
  // 1. Register a new unique admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const registerOutput = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerOutput);

  // 2. Login as the admin (updates connection session for privileged actions)
  const loginOutput = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginOutput);

  // 3. Create a moderation action as this admin
  const reportId = typia.random<string & tags.Format<"uuid">>();
  // For this workflow, operator_id should be a UUID that matches the acting admin
  // But as admin registration/login endpoints do not return admin id, we simulate by reusing a new random UUID for both moderation action and appellant_id
  // In practical E2E, after proper login info is exposed, it should use the true admin id
  const operatorId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: operatorId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "Automated compliance moderation for test post.",
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 4. Create an appeal against the above moderation action as the same admin (appellant)
  const appealReason = "Test E2E appeal reason for compliance traceability.";
  const appeal = await api.functional.polEcoBoard.admin.appeals.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      appellant_id: operatorId,
      reason: appealReason,
      status: "pending",
    } satisfies IPolEcoBoardAppeal.ICreate,
  });
  typia.assert(appeal);

  // 5. Assertions: Linkage, business fields, audit
  TestValidator.equals("appeal.moderation_action_id should match moderation action id")
    (appeal.moderation_action_id)
    (moderationAction.id);
  TestValidator.equals("appeal.appellant_id should match operator_id")
    (appeal.appellant_id)
    (operatorId);
  TestValidator.equals("appeal.status is 'pending'")
    (appeal.status)
    ("pending");
  TestValidator.equals("appeal.reason matches input")
    (appeal.reason)
    (appealReason);
  TestValidator.predicate("appeal.id is a UUID")
    (typeof appeal.id === "string" && /^[0-9a-fA-F\-]{36}$/.test(appeal.id));
  TestValidator.predicate("appeal.created_at is ISO string")
    (typeof appeal.created_at === "string" && appeal.created_at.includes(":"));
  TestValidator.predicate("appeal.updated_at is ISO string")
    (typeof appeal.updated_at === "string" && appeal.updated_at.includes(":"));
  TestValidator.predicate("moderationAction.id is a UUID")
    (typeof moderationAction.id === "string" && /^[0-9a-fA-F\-]{36}$/.test(moderationAction.id));
  TestValidator.predicate("moderationAction.created_at is ISO string")
    (typeof moderationAction.created_at === "string" && moderationAction.created_at.includes(":"));
}

