import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAppeal";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin update of mutable fields of an existing moderation appeal.
 *
 * This test ensures that a platform admin can update key editable fields on an appeal record — primarily status, outcome, reviewer assignment, and rationale — in the correct workflow and with all prerequisite records set up cleanly.
 * It verifies both successful write and read-back for correctness, and confirms that changes appear on the audit trail (if accessible) and cannot update disallowed properties.
 *
 * Steps:
 * 1. Register a new admin and login to get privileged API access.
 * 2. Create a test member (as the subject of moderation and appeal).
 * 3. Log in as the member to allow subsequent record creation (for moderation/appeal flows).
 * 4. Create a moderation action, assigning the admin as operator.
 * 5. File a new appeal as the member, targeting the moderation action.
 * 6. Switch back to the admin credential.
 * 7. Update the appeal record via the admin endpoint, modifying status, reviewer_admin_id, rationale, and adding an outcome value.
 * 8. Validate response: updated appeal fields match input/are correct, and that updated_by/audit info is present if available.
 * 9. (Optional future: Validate audit log or further workflow, if schema/API allows.)
 */
export async function test_api_appeal_update_admin_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(signUpResp);

  // 2. Log in as admin
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(loginResp);
  // connection.headers is updated with Authorization JWT via SDK

  // 3. Create a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 4. Member authenticates (to act as appellant)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  // connection.headers updated to member token

  // 5. Create moderation action as admin
  // We assume a fake report_id (since no report API), since creation requires it
  const fakeReportId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: fakeReportId,
      operator_id: member.id, // member is acting
      action_type: "warn",
      target_type: "user",
      status: "completed",
      rationale: RandomGenerator.paragraph()(),
      outcome: "escalated"
    } satisfies IPolEcoBoardModerationAction.ICreate
  });
  typia.assert(moderationAction);

  // 6. File an appeal as member
  const appeal = await api.functional.polEcoBoard.member.appeals.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      appellant_id: member.id,
      reason: RandomGenerator.paragraph()(),
      status: "pending"
    } satisfies IPolEcoBoardAppeal.ICreate
  });
  typia.assert(appeal);

  // 7. Switch back to admin session for appeal update
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  // connection.headers updated to admin Authorization JWT

  // 8. Update appeal as admin
  const updateBody: IPolEcoBoardAppeal.IUpdate = {
    reviewer_admin_id: appeal.appellant_id,
    status: "resolved",
    outcome: "approved",
    reason: RandomGenerator.paragraph()()
  };
  const updatedAppeal = await api.functional.polEcoBoard.admin.appeals.update(connection, {
    appealId: appeal.id,
    body: updateBody
  });
  typia.assert(updatedAppeal);

  // 9. Validate updated appeal fields
  TestValidator.equals("appeal ID")(updatedAppeal.id)(appeal.id);
  TestValidator.equals("moderation action link")(updatedAppeal.moderation_action_id)(appeal.moderation_action_id);
  TestValidator.equals("status")(updatedAppeal.status)(updateBody.status);
  TestValidator.equals("outcome")(updatedAppeal.outcome)(updateBody.outcome);
  TestValidator.equals("reviewer_admin_id")(updatedAppeal.reviewer_admin_id)(updateBody.reviewer_admin_id);
  TestValidator.equals("reason/rationale")(updatedAppeal.reason)(updateBody.reason);
  // All main mutable fields checked
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAppeal";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates business rule enforcement for updating appeals with invalid status/outcome values or when locked/finalized.
 *
 * This test covers rejection of appeal updates in the following scenarios:
 *  - Setting an invalid status value not allowed by appeal workflow
 *  - Setting a forbidden/invalid outcome value
 *  - Attempting to update an appeal which is locked/finalized
 * The test performs full prerequisite flow for a realistic context and checks errors are returned.
 *
 * Steps:
 * 1. Register a new admin account
 * 2. Login as that admin (for future API admin calls)
 * 3. Register a regular member account
 * 4. Login as that member (persist authentication for correct permission)
 * 5. Create a test moderation action (member or admin as operator, valid fields)
 * 6. Initiate an appeal referencing this moderation action (as member)
 * 7. Re-authenticate as admin (JWT token should set connection to admin mode)
 * 8. Try updating the appeal with:
 *     a) An invalid status (e.g., gibberish or unsupported string)
 *     b) An invalid outcome (e.g., gibberish or unsupported outcome code)
 *     c) Try locking the appeal and then attempt another update as a finalized record
 * Each of steps 8a–8c should fail with an error (i.e., business logic enforcement or validation error).
 *
 * This test ensures that:
 *   - Status values and outcome codes are strictly checked
 *   - Finalized/locked appeals cannot be updated further
 *   - Proper error codes/responses are returned for invalid modifications
 */
export async function test_api_appeal_update_admin_invalid_status(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(14);
  const memberDisplayName = RandomGenerator.name();
  const consentStatus = RandomGenerator.alphaNumeric(5);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: consentStatus,
    },
  });
  typia.assert(member);

  // 4. Login as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 5. Create a moderation action (simulate report_id as random UUID)
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const action = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: member.id,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: RandomGenerator.paragraph()(60),
      outcome: "accepted",
    },
  });
  typia.assert(action);

  // 6. Create an appeal
  const appeal = await api.functional.polEcoBoard.member.appeals.create(connection, {
    body: {
      moderation_action_id: action.id,
      appellant_id: member.id,
      reason: RandomGenerator.paragraph()(40),
      status: "pending",
    },
  });
  typia.assert(appeal);

  // 7. Switch back to admin (for admin appeal update)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 8a. Attempt update with an invalid status
  await TestValidator.error("update with invalid status should fail")(async () => {
    await api.functional.polEcoBoard.admin.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "not-a-real-status",
      },
    });
  });

  // 8b. Attempt update with an invalid outcome
  await TestValidator.error("update with invalid outcome should fail")(async () => {
    await api.functional.polEcoBoard.admin.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "in_review", // assume valid, outcome is invalid
        outcome: "not-a-real-outcome",
      },
    });
  });

  // 8c. Finalize the appeal, then try to further update (simulate as if resolved, then try to update)
  const finalizedAppeal = await api.functional.polEcoBoard.admin.appeals.update(connection, {
    appealId: appeal.id,
    body: {
      status: "resolved",
      outcome: "approved",
    },
  });
  typia.assert(finalizedAppeal);

  // Now try to update again - this should fail since the appeal is finalized/locked
  await TestValidator.error("update finalized appeal should fail")(async () => {
    await api.functional.polEcoBoard.admin.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "pending",
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAppeal";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that only admins can update an appeal, and non-admins (member or moderator) are denied with appropriate permission errors.
 *
 * Business context: Only admins are authorized to perform updates to appeals through the admin endpoint. Members and moderators, even if involved in an appeal, must not be permitted to directly update appeals via the admin-controlled PUT operation. This test ensures strong enforcement of permission boundaries in the moderation and appeal workflow.
 *
 * Step-by-step test process:
 * 1. Register a member as a regular user.
 * 2. Log in as that member (simulate member session).
 * 3. As the member, create a dummy moderation action (required for linking to the appeal).
 * 4. As the member, submit an appeal referencing the above moderation action.
 * 5. Attempt to update the created appeal via the admin endpoint as the member (should fail due to insufficient permissions).
 * 6. Register a second member to represent a moderator (since no explicit moderator auth API exists).
 * 7. Log in as the moderator.
 * 8. Attempt to update the same appeal as the moderator (should also fail for lack of admin rights).
 * 9. Assert that both requests are denied, demonstrating that only admin accounts can perform this operation, regardless of appeal participation.
 */
export async function test_api_appeal_update_admin_permission_denied(connection: api.IConnection) {
  // 1. Register primary member (the appellant)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accept-latest",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Log in as the member to get tokens
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  // Connection now holds member token

  // 3. As member, create a moderation action (minimal, required for link)
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: member.id,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "For test, removal due to policy violation.",
      outcome: "removed",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 4. As member, submit an appeal
  const appeal = await api.functional.polEcoBoard.member.appeals.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      appellant_id: member.id,
      reason: "I appeal: my post should not have been removed.",
      status: "pending",
    } satisfies IPolEcoBoardAppeal.ICreate,
  });
  typia.assert(appeal);

  // 5. Attempt to update appeal via admin endpoint as MEMBER (should fail: permission error)
  await TestValidator.error("member cannot update appeal via admin endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.appeals.update(connection, {
        appealId: appeal.id,
        body: {
          status: "resolved",
          reason: "Attempted unauthorized update.",
        } satisfies IPolEcoBoardAppeal.IUpdate,
      });
    },
  );

  // 6. Register a second member to simulate MODERATOR
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = typia.random<string & tags.Format<"password">>();
  const moderator = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: moderatorEmail,
      password_hash: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accept-latest",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(moderator);

  // 7. Log in as moderator
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  // Connection now holds moderator token

  // 8. Attempt to update appeal via admin endpoint as MODERATOR (should fail: permission error)
  await TestValidator.error("moderator cannot update appeal via admin endpoint")(
    async () => {
      await api.functional.polEcoBoard.admin.appeals.update(connection, {
        appealId: appeal.id,
        body: {
          status: "resolved",
          reason: "Attempted unauthorized update.",
        } satisfies IPolEcoBoardAppeal.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the deletion of moderation audit records and test access control.
 *
 * Business context:
 * - Only admin accounts may delete moderation audit records.
 * - Deleting an audit that is already deleted or does not exist must result in a not-found error.
 * - Attempts by non-admins must be denied with a proper error (permission denied/unauthorized).
 *
 * Test steps:
 * 1. Register and log in as a new admin (password of at least 8 chars).
 * 2. Create a moderation action (required for audit association).
 * 3. Create an audit record for that moderation action.
 * 4. Delete the audit as admin (success case).
 * 5. Verify that re-deletion of the same audit fails (not found).
 * 6. Attempt audit deletion as non-admin (simulate by using a connection without admin Authorization header).
 * 7. Attempt deletion with a random non-existent auditId, expect not found error.
 */
export async function test_api_moderation_audit_delete_success_and_access_control(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(registerRes);

  // 2. Log in as admin to set Authorization for privileged requests
  const loginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginRes);
  // Authorization header is now set for subsequent privileged API calls

  // 3. Create a moderation action (the parent for the audit)
  const actionInput = {
    report_id: typia.random<string & tags.Format<"uuid">>(),
    operator_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: RandomGenerator.alphabets(8),
    target_type: RandomGenerator.alphabets(6),
    status: "pending",
    rationale: RandomGenerator.paragraph()(),
    outcome: "accepted",
  } satisfies IPolEcoBoardModerationAction.ICreate;
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(
    connection,
    { body: actionInput },
  );
  typia.assert(moderationAction);

  // 4. Create an audit associated with the moderation action
  const auditInput = {
    moderation_action_id: moderationAction.id,
    auditor_id: moderationAction.operator_id,
    pre_state_snapshot: JSON.stringify(moderationAction),
    post_state_snapshot: JSON.stringify(moderationAction),
    reason: RandomGenerator.content()()(),
  } satisfies IPolEcoBoardModerationAudit.ICreate;
  const moderationAudit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(
    connection,
    {
      moderationActionId: moderationAction.id,
      body: auditInput,
    },
  );
  typia.assert(moderationAudit);

  // 5. Successfully delete the audit as admin
  await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
    connection,
    { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
  );

  // 6. Try to delete the audit again (must fail with not found)
  await TestValidator.error("second delete of same audit must fail")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 7. Attempt deletion as non-admin (simulate by removing admin Authorization header)
  const anonConnection = { ...connection, headers: {} } satisfies api.IConnection;
  await TestValidator.error("non-admin/unauthenticated cannot delete audit")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        anonConnection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 8. Attempt to delete a non-existent audit under this moderation action
  await TestValidator.error("deleting random auditId fails")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        {
          moderationActionId: moderationAction.id,
          auditId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardSanction";
import type { IPageIPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardSanction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin sanction search: filtering, access-control, and invalid-parameter handling.
 *
 * This test covers the workflow for listing/searching sanctions as an admin. It ensures that:
 * - Admin registration and authentication are correctly required and establish privilege.
 * - Multiple distinct moderation actions and sanctions are created for test data diversity.
 * - The search endpoint supports filtering by various criteria: status, type, user/member, moderation action, date-range, and pagination.
 * - Returned data honors each filter and includes correct pagination metadata.
 * - Invalid/malformed filters result in an appropriate validation error.
 * - Access control is enforced: only admins can search, attempts by non-admins or anonymous users are denied.
 *
 * Scenario Steps:
 * 1. Register an admin with a unique email/password for exclusive access.
 * 2. Log in as that admin to activate session/JWT.
 * 3. Create at least two moderation actions with different operator IDs and report IDs.
 * 4. For each moderation action, create sanctions with varied types, statuses, users, start/end times.
 * 5. Run search with no filters (should return all sanctions, paginated).
 * 6. Search by specific status (e.g., 'active'), specific sanction_type, and specific user.
 * 7. Search for a time range that only matches some sanctions.
 * 8. Use pagination (page, limit) and verify returned data & meta.
 * 9. Test invalid filters (bad field, wrong format) and expect validation errors.
 * 10. (Access) Try unauthorized search (not logged in or non-admin) and assert access denied.
 */
export async function test_api_sanction_search_admin_role_and_filters(connection: api.IConnection) {
  // 1. Register admin with unique credentials
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Log in as that admin
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Create two moderation actions (pretend operator_id is admin's, distinct reports)
  const operatorId = typia.random<string & tags.Format<"uuid">>(); // can't get the admin id directly, so random
  const reportId1 = typia.random<string & tags.Format<"uuid">>();
  const reportId2 = typia.random<string & tags.Format<"uuid">>();

  const moderationAction1 = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: reportId1,
      operator_id: operatorId,
      action_type: "warn",
      target_type: "post",
      status: "completed",
      rationale: RandomGenerator.paragraph()(),
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction1);

  const moderationAction2 = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: reportId2,
      operator_id: operatorId,
      action_type: "remove",
      target_type: "comment",
      status: "completed",
      rationale: RandomGenerator.paragraph()(),
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction2);

  // 4. Create several sanctions for both actions, with distinct users/types/status/times
  const sanctionedUser1 = typia.random<string & tags.Format<"uuid">>();
  const sanctionedUser2 = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const inFuture = new Date(now.getTime() + 2 * 86400 * 1000); // +2 days
  const past = new Date(now.getTime() - 2 * 86400 * 1000); // -2 days

  // Sanction 1: Recent, active, type 'ban', user1
  const sanction1 = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction1.id,
      sanctioned_user_id: sanctionedUser1,
      sanction_type: "ban",
      status: "active",
      rationale: RandomGenerator.paragraph()(),
      start_at: now.toISOString(),
      end_at: inFuture.toISOString(),
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction1);

  // Sanction 2: Old, expired, type 'suspension', user2
  const sanction2 = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction2.id,
      sanctioned_user_id: sanctionedUser2,
      sanction_type: "suspension",
      status: "expired",
      rationale: RandomGenerator.paragraph()(),
      start_at: past.toISOString(),
      end_at: now.toISOString(),
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction2);

  // Sanction 3: warning, same user1, status 'active'
  const sanction3 = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction2.id,
      sanctioned_user_id: sanctionedUser1,
      sanction_type: "warning",
      status: "active",
      rationale: RandomGenerator.paragraph()(),
      start_at: now.toISOString(),
      end_at: inFuture.toISOString(),
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction3);

  // 5. Search with no filters - should return all
  {
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {} satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    // Should include at least the sanctions just created
    const sanctionIds = [sanction1.id, sanction2.id, sanction3.id];
    const resultIds = result.data.map(s => s.id);
    for (const id of sanctionIds) {
      TestValidator.predicate(`result includes created sanction ${id}`)(resultIds.includes(id));
    }
    // Pagination meta present
    TestValidator.predicate("pagination object present")(!!result.pagination);
  }

  // 6. Filter by status, sanction_type, sanctioned_user_id
  {
    // Only active
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        status: "active",
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("all active")(s.status)("active");
    }
    // Only ban
    const resultBan = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        sanction_type: "ban",
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(resultBan);
    for (const s of resultBan.data) {
      TestValidator.equals("all bans")(s.sanction_type)("ban");
    }
    // Only user1
    const resultUser1 = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        sanctioned_user_id: sanctionedUser1,
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(resultUser1);
    for (const s of resultUser1.data) {
      TestValidator.equals("user id")(s.sanctioned_user_id)(sanctionedUser1);
    }
  }

  // 7. Filter by moderation_action or by date range
  {
    // By moderation_action
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        moderation_action_id: moderationAction2.id,
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("moderation_action_id matches")(s.moderation_action_id)(moderationAction2.id);
    }
    // By start_from and end_to
    const resultRange = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        start_from: past.toISOString(),
        end_to: inFuture.toISOString(),
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(resultRange);
    for (const s of resultRange.data) {
      TestValidator.predicate("start_at inside range")(
        new Date(s.start_at) >= past && new Date(s.start_at) <= inFuture
      );
    }
  }

  // 8. Pagination test
  {
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        page: 1,
        limit: 2,
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("limit respected")(result.data.length)(Math.min(2, result.pagination.records));
    TestValidator.equals("page number")(result.pagination.current)(1);
    TestValidator.predicate("valid pages count")(result.pagination.pages >= 1);
  }

  // 9. Invalid filters (malformed uuid, bad status string, page too low)
  {
    // Bad format for UUID
    await TestValidator.error("malformed moderation_action_id triggers validation error")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(connection, {
          body: {
            moderation_action_id: "not-a-uuid",
          } as any, // purposely wrong for runtime validation
        });
      },
    );
    // Page < 1, limit > 100
    await TestValidator.error("invalid pagination triggers validation")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(connection, {
          body: {
            page: 0,
            limit: 1000,
          } as any,
        });
      }
    );
  }

  // 10. Access control check (simulate missing/invalid auth)
  {
    // Remove Authorization header
    const unauthConn = { ...connection, headers: { ...connection.headers } };
    delete unauthConn.headers["Authorization"];
    await TestValidator.error("unauthenticated search denied")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(unauthConn, {
          body: {},
        });
      }
    );
    // Provide bogus Authorization header
    const invalidConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer BADTOKEN" } };
    await TestValidator.error("invalid token search denied")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(invalidConn, {
          body: {},
        });
      }
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
