import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin user can attach a file to an existing polEcoBoard post.
 *
 * This test confirms the business workflow and audit chain for privileged attachment actions:
 *
 * 1. Register a new admin account and log in to acquire admin credentials (JWT).
 * 2. Register and log in as a normal member (to create a post, since admins cannot directly create posts).
 * 3. Create a new post as the member, saving the resulting post ID for subsequent operations.
 * 4. Switch to the admin account (log in as admin and update authorization context).
 * 5. Upload a valid file attachment to the existing post via the admin endpoint, checking for file type/size/MME compliance as per IPolEcoBoardAttachment.ICreate constraints.
 * 6. Validate that the returned attachment is correctly persisted:
 *    - The attachment references the correct post_id
 *    - The author_member_id is set appropriately (admin context)
 *    - Metadata fields (mime_type, uri, file_name, file_size_bytes, created_at) are present and correctly set
 *    - No forbidden fields are present
 *    - Audit/history compliance (created_at is set, no deleted_at)
 * 7. Optionally, ensure that repeated attachment creation with the same admin context generates distinct attachment IDs (idempotency check).
 */
export async function test_api_post_attachment_creation_admin_happy_path(
  connection: api.IConnection
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Log in as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register member (for post creation)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 4. Log in as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Create a post as member
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1, 8);
  const postBody = RandomGenerator.content()()();
  const postCreate = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postCreate);

  // Save IDs
  const postId = postCreate.id;
  const memberAuthorId = postCreate.author_member_id;

  // 6. Log back in as admin (reset context)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Attach a file as admin
  const attachmentData = {
    uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(10)}.pdf`,
    file_name: `${RandomGenerator.alphaNumeric(8)}.pdf`,
    file_size_bytes: 512 * 1024,
    mime_type: "application/pdf",
  } satisfies IPolEcoBoardAttachment.ICreate;

  const attachment = await api.functional.polEcoBoard.admin.posts.attachments.create(connection, {
    postId,
    body: attachmentData,
  });
  typia.assert(attachment);

  // Assertions
  TestValidator.equals("post_id")(attachment.post_id)(postId);
  TestValidator.equals("mime_type")(attachment.mime_type)(attachmentData.mime_type);
  TestValidator.equals("file_name")(attachment.file_name)(attachmentData.file_name);
  TestValidator.equals("file_size_bytes")(attachment.file_size_bytes)(attachmentData.file_size_bytes);
  TestValidator.predicate("created_at set")(!!attachment.created_at);
  TestValidator.equals("deleted_at")(attachment.deleted_at)(null);
  TestValidator.notEquals("author_member_id is not member")(attachment.author_member_id)(memberAuthorId);
  TestValidator.equals("uri")(attachment.uri)(attachmentData.uri);
  TestValidator.predicate("attachment.id is uuid")(!!attachment.id && typeof attachment.id === "string" && attachment.id.length >= 32);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
