import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that uploading an attachment as an admin to a non-existent or deleted post fails as expected.
 *
 * This test ensures:
 * - Admin registration and login process work as prerequisites for privileged endpoints
 * - Attempting to upload an attachment to a bogus (non-existent) postId results in a business/404 error
 * - No orphan attachment record is created on error; the operation is atomically rejected
 * - API returns a clear error and does NOT silently succeed
 *
 * Step-by-step process:
 * 1. Register a new unique admin account (to avoid session conflict).
 * 2. Log in as this admin to set Authorization for protected API usage.
 * 3. Attempt to upload an attachment via /polEcoBoard/admin/posts/{postId}/attachments, supplying a guaranteed-fake valid UUID as postId.
 * 4. Confirm the API rejects the operation with an error and does not produce an attachment response.
 * 5. Validation: Only error presence is checked, not message/code/content.
 */
export async function test_api_post_attachment_creation_admin_invalid_post_error(
  connection: api.IConnection,
) {
  // 1. Register a new admin account with unique email & valid password
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const registerResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResult);

  // 2. Log in with the registered admin for Authorization
  const loginResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResult);

  // 3. Prepare attachment data and attempt upload to a bogus (random unused) postId
  const bogusPostId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const attachmentBody = typia.random<IPolEcoBoardAttachment.ICreate>();

  // 4. Validate that an error is thrown (operation rejected with no attachment created)
  await TestValidator.error("admin cannot upload attachment to nonexistent post")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.attachments.create(connection, {
        postId: bogusPostId,
        body: attachmentBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a member (as the post author) can update permitted metadata fields for an attachment to their post.
 *
 * Business context:
 * - Only the post author may update certain metadata (file_name, mime_type) of attachments.
 * - The attachment must remain correctly linked to its post.
 * - Fields outside those permitted (such as file content, uri, author_member_id, file_size_bytes) are immutable and must not change.
 *
 * Steps:
 * 1. Register as a new member (random email/password)
 * 2. Log in as that member (token managed automatically)
 * 3. Create a new post as that member
 * 4. Upload a valid attachment to the post
 * 5. Update attachment metadata (file_name & mime_type)
 * 6. Validate updates, author, post linkage, and immutability of forbidden fields
 */
export async function test_api_post_attachment_update_member_metadata_change(connection: api.IConnection) {
  // 1. Register as a new member
  const email = typia.random<string & tags.Format<'email'>>();
  const password = typia.random<string & tags.Format<'password'>>();
  const registration = await api.functional.auth.member.register.signUp(connection, {
    body: { email, password },
  });
  typia.assert(registration);

  // 2. Login as the member
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password },
  });
  typia.assert(login);

  // 3. Create a new post
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<'uuid'>>(),
    title: RandomGenerator.paragraph()(2),
    body: RandomGenerator.content()()(),
    tag_ids: null,
    attachments: null,
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 4. Upload a valid attachment to the post
  const attachmentInput: IPolEcoBoardAttachment.ICreate = {
    uri: RandomGenerator.alphabets(24),
    file_name: RandomGenerator.alphabets(12) + '.jpg',
    file_size_bytes: typia.random<number & tags.Type<'int32'>>(),
    mime_type: 'image/jpeg',
  };
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: attachmentInput,
  });
  typia.assert(attachment);

  // 5. Update attachment metadata
  const newFileName = RandomGenerator.alphabets(10) + '.png';
  const newMimeType = 'image/png';
  const updated = await api.functional.polEcoBoard.member.posts.attachments.update(connection, {
    postId: post.id,
    attachmentId: attachment.id,
    body: {
      file_name: newFileName,
      mime_type: newMimeType,
    },
  });
  typia.assert(updated);

  // 6. Validate permitted/forbidden field changes and linkage
  TestValidator.equals('file_name updated')(updated.file_name)(newFileName);
  TestValidator.equals('mime_type updated')(updated.mime_type)(newMimeType);
  TestValidator.equals('post_id unchanged')(updated.post_id)(post.id);
  TestValidator.equals('author_member_id unchanged')(updated.author_member_id)(post.author_member_id);
  TestValidator.equals('uri unchanged')(updated.uri)(attachment.uri);
  TestValidator.equals('file_size_bytes unchanged')(updated.file_size_bytes)(attachment.file_size_bytes);
}

