import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validates that a member can delete their own attachment from their authored post (ownership enforcement, soft-delete, audit).
 *
 * Business context:
 * - Only post authors (who are authenticated) can delete attachments from their own posts.
 * - Deletion is a soft-delete: sets deleted_at in the attachment record, retained for audit/compliance but not visible in business UI listings.
 * - This test ensures business rule, permission, and audit conformance for own attachment deletion.
 *
 * Step-by-step process:
 * 1. Register a new member with random credentials.
 * 2. Log in as the member (token handled by connection).
 * 3. Create a post as the member, using random values for category, title, and body.
 * 4. Attach a file to the post with valid metadata.
 * 5. Soft-delete the attachment (API will mark deleted_at; no listing fetch available to confirm removal from UI/business view).
 * 6. (No further UI fetch is possible via available API. Deletion and retention tested at operation level only.)
 */
export async function test_api_post_attachment_delete_member_ownership(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberCredentials = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
  };
  const registrationResult = await api.functional.auth.member.register.signUp(
    connection,
    { body: memberCredentials },
  );
  typia.assert(registrationResult);

  // 2. Log in as the same member
  const loginResult = await api.functional.auth.member.login.signIn(
    connection,
    { body: memberCredentials },
  );
  typia.assert(loginResult);

  // 3. Create a post as this member
  const postInput = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Attachment Deletion Test - " + RandomGenerator.alphaNumeric(10),
    body: RandomGenerator.paragraph()(),
  } satisfies IPolEcoBoardPost.ICreate;
  const post = await api.functional.polEcoBoard.member.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 4. Attach a file to the post
  const attachmentInput = {
    uri: "/files/attach-" + RandomGenerator.alphaNumeric(6) + ".txt",
    file_name: "TestFile-" + RandomGenerator.alphaNumeric(6) + ".txt",
    file_size_bytes: 2048,
    mime_type: "text/plain",
  } satisfies IPolEcoBoardAttachment.ICreate;
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(
    connection,
    { postId: post.id, body: attachmentInput },
  );
  typia.assert(attachment);

  // 5. Soft-delete the attachment (authorization validated by token, enforces author-only policy)
  await api.functional.polEcoBoard.member.posts.attachments.erase(
    connection,
    { postId: post.id, attachmentId: attachment.id },
  );
  // No fetch/confirm for deleted attachment possible in current API surface
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IPageIPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin notification preferences search API with filtering and pagination.
 *
 * This test ensures that an administrator can register, login, and retrieve notification preferences via the admin search endpoint. The test validates filtering by event type, channel, member ID, and opt-in status, and checks that pagination metadata is accurate and the data matches the search criteria.
 *
 * Step-by-step process:
 * 1. Register a new admin account.
 * 2. Login as the same admin to obtain authorization credentials.
 * 3. Build a set of search filters using random (but type-valid) data.
 * 4. Call the admin notification preferences search endpoint with the filters and pagination options.
 * 5. Verify the response contains valid pagination info and all returned records match the applied filters (when those filters are not undefined).
 * 6. Confirm the presence and format of all required fields in the response objects.
 */
export async function test_api_notification_preferences_admin_search_success(connection: api.IConnection) {
  // 1. Register a new admin account.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);

  const registration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registration);

  // 2. Login as the newly-created admin.
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(login);

  // 3. Prepare random (filtered) search criteria for notification preferences, using required and optional fields.
  const searchFilters: IPolEcoBoardNotificationPreference.IRequest = {
    event_type: RandomGenerator.pick([
      "reply",
      "moderation_action",
      "post_created",
      "like_received",
    ]),
    channel: RandomGenerator.pick([
      "email",
      "push",
      "in_app",
      "sms",
    ]),
    opt_in: RandomGenerator.pick([true, false]),
    page: 1,
    limit: 10,
  };

  // 4. Execute the search as admin.
  const result = await api.functional.polEcoBoard.admin.notificationPreferences.search(connection, {
    body: searchFilters,
  });
  typia.assert(result);

  // 5. Assert pagination structure is present and data is an array
  TestValidator.predicate("pagination present")(
    typeof result.pagination === "object" && result.pagination !== null,
  );
  TestValidator.predicate("pagination fields are numbers")(
    typeof result.pagination.current === "number" &&
      typeof result.pagination.limit === "number" &&
      typeof result.pagination.records === "number" &&
      typeof result.pagination.pages === "number",
  );
  TestValidator.predicate("data is array")(Array.isArray(result.data));

  // 6. For each record, assert that it matches the filter values when those are provided.
  for (const pref of result.data) {
    typia.assert(pref);
    if (searchFilters.event_type !== undefined)
      TestValidator.equals("event_type matches")(pref.event_type)(searchFilters.event_type);
    if (searchFilters.channel !== undefined)
      TestValidator.equals("channel matches")(pref.channel)(searchFilters.channel);
    if (searchFilters.opt_in !== undefined)
      TestValidator.equals("opt_in matches")(pref.opt_in)(searchFilters.opt_in);
  }
}

