/**
 * Validate that searching for notification preferences with unmatched filters yields an empty result set and proper pagination metadata for admin.
 *
 * Business context:
 * This test simulates an admin searching the notification preferences table using filters that are guaranteed not to match any records (such as a fictitious event type and channel). This workflow is important to ensure that the admin API behaves correctly when a query returns no data—that is, it must return an empty data array, no unhandled errors, and valid pagination fields. Additionally, it verifies the authentication workflow for admin-specific endpoints.
 *
 * Step-by-step process:
 * 1. Register a new admin with unique email and valid password.
 * 2. Log in as this admin to obtain the authenticated context (JWT, etc).
 * 3. Call the admin notification preference search endpoint with filter criteria that are not possible in real data.
 * 4. Confirm that the result contains no data, the pagination object reflects zero records, and other business rules are enforced (such as positive page/limit values).
 */
export async function test_api_notification_preferences_admin_search_no_result(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResponse);

  // 2. Login as the newly created admin
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResponse);

  // 3. Search for notification preferences with filters that won't match any records
  const searchResponse = await api.functional.polEcoBoard.admin.notificationPreferences.search(connection, {
    body: {
      event_type: "__definitely_not_a_real_event__",
      channel: "__this_channel_does_not_exist__",
      page: 1,
      limit: 10,
    } satisfies IPolEcoBoardNotificationPreference.IRequest,
  });
  typia.assert(searchResponse);

  // 4. Confirm the response is an empty result set with proper pagination metadata
  TestValidator.equals("data array is empty")(searchResponse.data)([]);
  TestValidator.equals("pagination reflects empty result")(searchResponse.pagination.records)(0);
  TestValidator.equals("pagination current is 1")(searchResponse.pagination.current)(1);
  TestValidator.predicate("pagination limit is positive")(searchResponse.pagination.limit > 0);
  TestValidator.predicate("pagination pages is 0 or 1")(searchResponse.pagination.pages === 0 || searchResponse.pagination.pages === 1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
