/**
 * Validate enforcement of admin-only access control for notification preference search endpoint.
 *
 * Business context: Only admin users should be able to access the /polEcoBoard/admin/notificationPreferences search endpoint. Regular members and unauthenticated users must not be able to read bulk notification preferences for security, privacy, and regulatory reasons.
 *
 * Test covers two permission denial pathways:
 * 1. Authenticated regular member attempts to use admin search endpoint – must be denied (permission error).
 * 2. Attempt search with no authentication at all – must also be denied.
 *
 * This ensures boundary enforcement and no privilege escalation.
 *
 * Step-by-step process:
 * 1. Register a regular member.
 * 2. Login as the member (obtain member's jwt token in connection).
 * 3. Attempt to call notification preferences search endpoint with valid member authentication – expect error.
 * 4. Remove authentication (simulate unauthenticated access).
 * 5. Attempt to call notification preferences search endpoint without any Authorization – expect error.
 */
export async function test_api_notification_preferences_admin_search_permission_denied(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const registerResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(registerResult);

  // 2. Login as the member
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(loginResult);

  // 3. Attempt admin notification preferences search as member (should be denied)
  await TestValidator.error("member cannot access admin notification preferences")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationPreferences.search(connection, {
        body: {}, // empty search (valid type)
      });
    }
  );

  // 4. Remove authentication, simulate no authentication
  const unauthenticatedConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthenticatedConnection.headers.Authorization;

  // 5. Attempt admin notification preferences search with no credentials (should be denied)
  await TestValidator.error("unauthenticated user cannot access admin notification preferences")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationPreferences.search(unauthenticatedConnection, {
        body: {},
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a member can retrieve their own notification preference by ID.
 *
 * Ensures end-to-end correctness for the workflow:
 * 1. Member registration (obtain credentials and authentication header/token)
 * 2. Login as member (confirm authentication works and SDK stores token)
 * 3. Create a member-owned notification preference setting (specifying event, channel, opt_in)
 * 4. Retrieve the just-created notification preference by its unique ID as the authenticated member
 * 5. Validate returned details match what was set (all event/channel/opt_in metadata, correct UUIDs)
 *
 * Does not cover unauthorized access (covered in separate error/negative tests).
 */
export async function test_api_notification_preference_member_get_own_success(connection: api.IConnection) {
  // 1. Register a new member
  const memberSignUpBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
  } satisfies IMemberAuthenticationMemberSignUp;
  const memberSignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: memberSignUpBody,
  });
  typia.assert(memberSignUpResult);

  // 2. Login as the new member
  const memberLoginBody = {
    email: memberSignUpBody.email,
    password: memberSignUpBody.password,
  } satisfies IMemberAuthenticationMemberSignIn;
  const memberLoginResult = await api.functional.auth.member.login.signIn(connection, {
    body: memberLoginBody,
  });
  typia.assert(memberLoginResult);

  // 3. Create a notification preference for this member
  // As per DTO, member_id is required, but most real APIs ignore provided value and use currently authenticated user session
  // Here, we supply a random uuid only for type satisfaction. Backend should link preference to authenticated user.
  const preferenceCreateBody = {
    member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "reply",
    channel: "email",
    opt_in: true,
  } satisfies IPolEcoBoardNotificationPreference.ICreate;
  const createdPreference = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: preferenceCreateBody,
  });
  typia.assert(createdPreference);

  // 4. Retrieve preference by its ID as the authenticated member
  const retrieved = await api.functional.polEcoBoard.member.notificationPreferences.at(connection, {
    notificationPreferenceId: createdPreference.id,
  });
  typia.assert(retrieved);

