 *
 * Workflow:
 * 1. Register a new admin (email/password)
 * 2. Login as that admin to establish Authorization context
 * 3. Register a new member (separate email/password)
 * 4. Login as member to create a notification preference record
 * 5. As member, create a notification preference with required payload (member_id set, event_type, channel, opt_in)
 * 6. Switch to admin (login) and fetch notification preference by its ID via privileged endpoint
 * 7. Validate all expected fields: id, member_id, event_type, channel, opt_in, created_at, updated_at
 */
export async function test_api_notification_preference_admin_get_any_success(connection: api.IConnection) {
