import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin GET of a non-existent notification preference by ID.
 *
 * This test ensures that a platform admin cannot retrieve notification preference records by supplying a random (non-existent) UUID, and that the API responds with an appropriate error (not found/404), never exposing sensitive data or leaking implementation details.
 *
 * Workflow:
 * 1. Register a new admin using an email and password (to obtain authentication).
 * 2. Login with the same credentials to get an Authorization header/token.
 * 3. Call GET /polEcoBoard/admin/notificationPreferences/{notificationPreferenceId}
 *    with a random UUID that does NOT correspond to any real notification preference
 * 4. Confirm the response results in a not found error, with no notification preference data present,
 *    and confirm that no sensitive system details or internal data are returned accidentally.
 * 5. Optionally verify that the error is a 404 Not Found and does not reveal stack traces or member IDs in the error payload.
 */
export async function test_api_notification_preference_admin_get_not_found(connection: api.IConnection) {
  // 1. Register as admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });

  // 2. Login as admin to set Authorization headers
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });

  // 3. Attempt to fetch notification preference with random (non-existent) UUID
  const randomId = typia.random<string & tags.Format<"uuid">>();

  // 4. Confirm not found error is thrown and nothing sensitive is exposed
  await TestValidator.error("admin get non-existent notification preference fails")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationPreferences.at(connection, {
        notificationPreferenceId: randomId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Verify that the admin-only notification preference detail API enforces permission restrictions.
 *
 * Attempts to access a notification preference as a non-admin (regular member) and expects a permission denied error, confirming that only admins are allowed to view this data via the specified endpoint.
 * This checks that unauthorized access is blocked and compliance is maintained.
 *
 * Process:
 * 1. Register a new non-admin member account
 * 2. Log in using the registered member's credentials
 * 3. Update the API connection to use the regular member's token
 * 4. Attempt to access the admin-only endpoint with a random notificationPreferenceId
 * 5. Validate that an access denied error is thrown (permission enforcement)
 */
export async function test_api_notification_preference_admin_get_permission_enforced(connection: api.IConnection) {
  // 1. Register a new non-admin member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signUpResult);

  // 2. Log in as that member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(signInResult);

  // 3. Update the API connection to use this member's token for future calls
  connection.headers = {
    ...connection.headers,
    Authorization: signInResult.setHeaders.Authorization,
  };

  // 4. Attempt to access the admin-only notification preference by random UUID
  const notificationPreferenceId = typia.random<string & tags.Format<"uuid">>();

  // 5. Validate permission denial
  await TestValidator.error("Non-admin member should not access admin notification preference detail")(
    async () => {
      await api.functional.polEcoBoard.admin.notificationPreferences.at(connection, {
        notificationPreferenceId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test successful creation of a notification preference by a member.
 *
 * This test validates that a member can register and authenticate, then submit
 * a request to create a notification preference record for themselves, specifying
 * all required fields (event_type, channel, and opt_in) as per schema. It verifies
 * that the API returns the created notification preference with a valid ID and
 * that the record contains the expected event_type, channel, and opt_in values.
 *
 * Step-by-step process:
 * 1. Register a new member account providing unique email and compliant password
 * 2. Login with the newly created member credentials to receive authorization (JWT)
 * 3. Create a notification preference using the authenticated connection, specifying
 *    event_type, channel, opt_in, and using a generated uuid for member_id as the
 *    actual member id is not retrievable from provided APIs
 * 4. Validate the response: it should return the created notification preference record
 *    with a valid UUID ID, timestamps, and the same event_type/channel/opt_in as input
 */
export async function test_api_notification_preference_member_create_success(
  connection: api.IConnection,
) {
  // 1. Register a new member with unique email and valid password
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = typia.random<string & tags.Format<"password">>();
  const registerResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(registerResult);

  // 2. Login with the new member credentials
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(loginResult);
  // Authorization header is applied to connection automatically

  // 3. Create notification preference for this member
  // As there is no endpoint to retrieve the current user's member_id, use a random uuid for member_id.
  const notificationPrefInput = {
    member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "reply",
    channel: "email",
    opt_in: true,
  };

  const preference = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: notificationPrefInput,
  });
  typia.assert(preference);

  // 4. Validate output matches input (except for generated fields)
  TestValidator.equals("event_type")(preference.event_type)(notificationPrefInput.event_type);
  TestValidator.equals("channel")(preference.channel)(notificationPrefInput.channel);
  TestValidator.equals("opt_in")(preference.opt_in)(notificationPrefInput.opt_in);
  // Assert presence of id and timestamp fields
  TestValidator.predicate("id is uuid")(typeof preference.id === "string" && preference.id.length > 10);
  TestValidator.predicate("created_at exists")(typeof preference.created_at === "string");
}

