/**
 * Test the prevention of duplicate notification preference creation.
 *
 * This test ensures that the API properly enforces its uniqueness constraint: a member cannot create multiple notification preferences for the same event type and channel combination.
 *
 * Business context: Users can specify notification preferences (opt-in/out) per event/channel. The system must prevent duplicate records for the same (member, event_type, channel) tuple.
 *
 * Steps:
 * 1. Register a new member with random email/password
 * 2. Log in as the new member to initiate authentication context
 * 3. Create a notification preference for a given event type and channel (e.g., "reply", "email")
 * 4. Attempt to create another notification preference using the exact same parameters
 * 5. Validate that the second creation triggers a uniqueness constraint error (i.e., the backend does not allow the duplicate)
 */
export async function test_api_notification_preference_member_create_duplicate_error(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const registration = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(registration);

  // 2. Log in as the member
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(login);

  // 3. Create a notification preference with test parameters
  const event_type = "reply";
  const channel = "email";
  const member_id = typia.random<string & tags.Format<"uuid">>();
  const prefInput = {
    member_id,
    event_type,
    channel,
    opt_in: true,
  } satisfies IPolEcoBoardNotificationPreference.ICreate;

  const createdPref = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: prefInput,
  });
  typia.assert(createdPref);

  // 4. Attempt to create a duplicate preference
  TestValidator.error("duplicate notification preference should fail")(async () => {
    await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
      body: prefInput,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test input validation for notification preference creation as a member.
 *
 * This test checks:
 *  1. Proper enforcement of supported event_type and channel values
 *  2. Required field validation
 *  3. Type and format enforcement on field values
 *  4. Ensures that no record is created on invalid input (API returns validation error)
 *
 * Step-by-step process:
 * 1. Register a new member account with a valid email and password
 * 2. Login as the created member and retain Authorization for future requests
 * 3. Attempt to create notification preferences using various invalid data:
 *    - Unsupported event_type (e.g., 'invalid_event')
 *    - Unsupported channel (e.g., 'carrier_pigeon')
 *    - Missing required fields (such as channel, event_type, opt_in, or member_id)
 *    - Malformed values (e.g., non-uuid member_id, opt_in as string, etc.)
 * 4. For each invalid input, expect an actionable validation error from the API and no successful record creation.
 */
export async function test_api_notification_preference_member_create_invalid_values(
  connection: api.IConnection,
) {
  // 1. Register new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const registration = await api.functional.auth.member.register.signUp(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(registration);

  // 2. Login as member
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(login);

  // Helper: generate a valid notification preference payload
  const validPayload = (): IPolEcoBoardNotificationPreference.ICreate => ({
    member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "reply",
    channel: "email",
    opt_in: true,
  });

  // Prepare invalid test cases
  const invalidCases: Partial<IPolEcoBoardNotificationPreference.ICreate>[] = [
    // 1. Unsupported event_type
    { ...validPayload(), event_type: "invalid_event" },
    // 2. Unsupported channel
    { ...validPayload(), channel: "carrier_pigeon" },
    // 3. Missing event_type
    (({ event_type, ...rest }) => rest)(validPayload()),
    // 4. Missing channel
    (({ channel, ...rest }) => rest)(validPayload()),
    // 5. Missing opt_in
    (({ opt_in, ...rest }) => rest)(validPayload()),
    // 6. Missing member_id
    (({ member_id, ...rest }) => rest)(validPayload()),
    // 7. Malformed member_id
    { ...validPayload(), member_id: "not-a-uuid" as any },
    // 8. opt_in as string
    { ...validPayload(), opt_in: "yes" as any },
  ];

  // 3. Attempt creation with each invalid input & expect a validation error
  for (const [i, body] of invalidCases.entries()) {
    await TestValidator.error(`invalid notification preference input case #${i + 1}`)(async () => {
      await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
        body: body as IPolEcoBoardNotificationPreference.ICreate,
      });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostTag";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can successfully assign a tag to a post using the admin postTags API in polEcoBoard.
 *
 * This end-to-end test simulates the following steps:
 *   1. Register a new admin and authenticate (to operate protected endpoints).
 *   2. Create a new category (which boards will belong to).
 *   3. Create a new board under the category.
 *   4. Register a new member (required to create posts).
 *   5. As the member (simulate, see note), create a post in the created board/category.
 *   6. As admin, create a new tag for assignment.
 *   7. Assign the created tag to the post as admin.
 *   8. Assert referential integrity (the tag-post assignment is correct, with expected IDs and timestamp).
 *
 * Note: While ideal flow would use actual member authentication for post creation, only public member registration API is available (no member auth/login), so this test assumes posting is permitted in test environment post-registration. If further distinction is introduced in the SDK, update to switch session context as needed.
 */
export async function test_api_post_tag_admin_tag_assignment_happy_path(connection: api.IConnection) {
  // 1. Register a new admin and obtain authorization (admin signUp)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminSignUpRes);
  // Authorization header now set in connection for admin

  // 2. Create a new category (admin-only operation)
  const categoryName = RandomGenerator.alphabets(10);
  const categoryDesc = RandomGenerator.paragraph()(1);
  const displayOrder = typia.random<number & tags.Type<"int32">>();
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: categoryDesc,
      display_order: displayOrder
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create a new board, linked to this category
  const boardName = RandomGenerator.alphabets(10);
  const boardCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const boardDesc = RandomGenerator.paragraph()(1);
  const boardIsPublic = true;
  const boardIsArchived = false;
  const boardDisplayOrder = typia.random<number & tags.Type<"int32">>();
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardName,
      code: boardCode,
      description: boardDesc,
      is_public: boardIsPublic,
      is_archived: boardIsArchived,
      display_order: boardDisplayOrder
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Register a new member (needed to create a post)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplayName = RandomGenerator.alphabets(10);
  const memberConsent = "consent_given";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: memberConsent
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 5. Create a post in the board/category as this member
  const postTitle = RandomGenerator.paragraph()(1).substring(0, 50); // min 10/max 120 chars
  const postBody = RandomGenerator.content()(1)();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      body: postBody
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Create a tag as admin
  const tagName = RandomGenerator.alphabets(8);
  const tagSlug = tagName.toLowerCase();
  const tagDesc = RandomGenerator.content()(1)();
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: tagName,
      slug: tagSlug,
      description: tagDesc
    } satisfies IPolEcoBoardTag.ICreate
  });
  typia.assert(tag);

  // 7. Assign the new tag to the post (admin API)
  const postTagAssignment = await api.functional.polEcoBoard.admin.posts.postTags.create(connection, {
    postId: post.id,
    body: {
      tag_id: tag.id
    } satisfies IPolEcoBoardPostTag.ICreate
  });
  typia.assert(postTagAssignment);
  // 8. Assert referential correctness and metadata
  TestValidator.equals("assignment tag_id matches")(postTagAssignment.tag_id)(tag.id);
  TestValidator.equals("assignment post_id matches")(postTagAssignment.post_id)(post.id);
  TestValidator.predicate("assignment has timestamp")(!!postTagAssignment.assigned_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostTag";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that assigning a duplicate tag to a post as admin fails as expected, enforcing business constraints.
 *
 * This test ensures that the platform prevents duplicate tag assignments on a single post, maintaining data integrity and correct taxonomy. The workflow demonstrates that a first-time tag assignment succeeds, but any subsequent attempt (with the same tag and post) yields a business error and does not increase the number of assignments. This protects against classification confusion and improper tag usage within posts.
 *
 * Process:
 * 1. Register and login as an admin user.
 * 2. Create a new board category.
 * 3. Create a board within that category.
 * 4. Register a member account for post creation.
 * 5. (Simulate member context) Create a post in the created category.
 * 6. (Admin context) Create a tag entity to be used for assignment.
 * 7. Assign the tag to the post (should succeed; validate response fields).
 * 8. Try to assign the exact same tag to the same post again (should fail with business error).
 * 9. Verify that only one tag assignment exists for the given post/tag pair.
 * 10. Confirm error raised, that no new assignment was created, and audit trail can be checked if available.
 */
export async function test_api_post_tag_admin_assignment_duplicate_error(connection: api.IConnection) {
  // 1. Register and login as an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 2. Create a new board category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create a board within the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      profile_image_uri: null,
      consent_status: "accepted"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 5. Create a post from that member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Admin creates a tag
  const tagName = RandomGenerator.alphabets(8);
  const tagSlug = tagName.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: tagName,
      slug: tagSlug,
      description: RandomGenerator.paragraph()()
    } satisfies IPolEcoBoardTag.ICreate
  });
