 * Denial/authorization checks:
 *  10. Attempt to delete the tag assignment as admin with NO Authorization token (expected: error).
 *  11. Attempt to delete the tag assignment as admin with an INVALID Authorization token (expected: error).
 *
 * Additional:
 *   - We (optionally) test that deletion repeatedly fails (i.e., tag assignment is not accidentally removed by failed attempts), but cannot directly re-fetch the tag assignment for further assert (API does not provide fetch-by-id list).
 *   - Audit log validation is omitted (API does not expose any such mechanism).
 */
export async function test_api_post_tag_deletion_by_admin_permission_denied(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Admin login (to obtain token for setup)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 3. Create board category (admin)
  const category = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph()(),
        display_order: 1,
      },
    },
  );
  typia.assert(category);

  // 4. Create board (admin)
  const board = await api.functional.polEcoBoard.admin.boards.create(
    connection,
    {
      body: {
        pol_eco_board_category_id: category.id,
        name: RandomGenerator.alphaNumeric(12),
        code: RandomGenerator.alphaNumeric(10).toLowerCase(),
        description: RandomGenerator.paragraph()(),
        is_public: true,
        is_archived: false,
        display_order: 1,
      },
    },
  );
  typia.assert(board);

  // 5. Create a tag (admin)
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(6),
      slug: RandomGenerator.alphaNumeric(6).toLowerCase(),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(tag);

  // 6. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      consent_status: "yes",
    },
  });
  typia.assert(member);

  // 7. Member login for token
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 8. Member creates a post in the board category
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 9. Member assigns the tag to their post
  const postTag = await api.functional.polEcoBoard.member.posts.postTags.create(
    connection,
    {
      postId: post.id,
      body: {
        tag_id: tag.id,
      },
    },
  );
  typia.assert(postTag);

  // 10. Attempt admin tag detachment with no Authorization header
  const connectionNoAuth = { ...connection, headers: { ...connection.headers } };
  delete connectionNoAuth.headers["Authorization"];
  await TestValidator.error("authorization required (no token) fails detachment")(
    async () => {
      await api.functional.polEcoBoard.admin.posts.postTags.erase(
        connectionNoAuth,
        {
          postId: post.id,
          postTagId: postTag.id,
        },
      );
    },
  );

  // 11. Attempt with an invalid/expired token
  const connectionInvalidAuth = {
    ...connection,
    headers: { ...connection.headers, Authorization: "Bearer invalidtokenvalue" },
  };
  await TestValidator.error(
    "authorization fails with invalid/expired token on detachment",
  )(async () => {
    await api.functional.polEcoBoard.admin.posts.postTags.erase(
      connectionInvalidAuth,
      {
        postId: post.id,
        postTagId: postTag.id,
      },
    );
  });

  // (Optional) 12. Attempt third deletion—to affirm failure and presence—behavior should be consistent
  await TestValidator.error(
    "repeated unauthorized detachment should still fail/no accidental deletion",
  )(async () => {
    await api.functional.polEcoBoard.admin.posts.postTags.erase(
      connectionNoAuth,
      {
        postId: post.id,
        postTagId: postTag.id,
      },
    );
  });

  // No audit log API exposed, so audit trail checks omitted
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPageIPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate that a registered member can search and retrieve the list of file attachments for a post they are permitted to access.
 *
 * This covers the following business workflow and validates correct API behavior, permissions, and metadata integrity for attachment searching:
 *
 * 1. Register a new board category as admin (needed for board context)
 * 2. Register a board in the created category (admin action)
 * 3. Register and login as a member (to create and access posts and attachments)
 * 4. Member creates a post on the board
 * 5. Member adds at least one attachment to the post
 * 6. Member requests the list of attachments for their own post using the PATCH search endpoint
 * 7. Validate:
 *    - Response contains all of that post's attachments, with correct metadata (filename, type, size, uri, etc)
 *    - Pagination fields are present and correct (e.g. total records, limit, pages)
 *    - Filtering (e.g. by file_name, mime_type) is respected if provided
 *    - Permission boundary: only attachments for accessible posts (not unrelated posts or posts by others) are returned
 *    - Fields like author_member_id, created_at, etc. are present and formatted correctly
 *
 * This E2E test ensures correct business logic, type conformance, and reliable access control around the attachment retrieval workflow.
 */
export async function test_api_post_attachment_search_as_member_success(connection: api.IConnection) {
  // 1. Create a category (admin required)
  const categoryBody: IPolEcoBoardCategory.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: categoryBody,
  });
  typia.assert(category);

  // 2. Create a board in the category (admin required)
  const boardBody: IPolEcoBoardBoard.ICreate = {
    pol_eco_board_category_id: category.id,
    name: RandomGenerator.alphaNumeric(10),
    code: RandomGenerator.alphaNumeric(8).toLowerCase(),
    description: RandomGenerator.paragraph()(),
    is_public: true,
    is_archived: false,
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: boardBody,
  });
  typia.assert(board);

  // 3. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberBody: IPolEcoBoardMember.ICreate = {
    email: memberEmail,
    password_hash: memberPassword, // For testing, treat as plain (in live, must be hashed)
    display_name: RandomGenerator.alphaNumeric(10),
    profile_image_uri: null,
    consent_status: "accepted", // Example value
  };
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: memberBody,
  });
  typia.assert(member);

  // 4. Login as the member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  // No assertion needed, token set in connection

  // 5. Member creates a post on the created board
  const postBody: IPolEcoBoardPost.ICreate = {
    category_id: category.id,
    title: RandomGenerator.alphaNumeric(30),
    body: RandomGenerator.paragraph()(),
    tag_ids: null,
    attachments: null, // attachments created by dedicated endpoint after post creation
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postBody,
  });
  typia.assert(post);

  // 6. Member adds an attachment to the post
  const attachmentBody: IPolEcoBoardAttachment.ICreate = {
    uri: `https://storage.example.com/u/${RandomGenerator.alphaNumeric(16)}`,
    file_name: `${RandomGenerator.alphaNumeric(8)}.pdf`,
    file_size_bytes: typia.random<number & tags.Type<"int32">>(),
    mime_type: "application/pdf",
  };
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: attachmentBody,
  });
  typia.assert(attachment);
  TestValidator.equals("postId matches")(attachment.post_id)(post.id);

  // 7. Member queries the attachment list for their post
  const pageSize = 10;
  const requestBody: IPolEcoBoardAttachment.IRequest = {
    post_id: post.id,
    file_name: null,
    mime_type: null,
    created_after: null,
    created_before: null,
    author_member_id: null,
    page: 1,
    limit: pageSize,
  };
  const result = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: post.id,
    body: requestBody,
  });
  typia.assert(result);

  // 8. Validate response: data should contain the attached file only, with valid metadata.
  TestValidator.predicate("returns at least one attachment for post")(result.data.length >= 1);
  const found = result.data.find((a) => a.id === attachment.id);
  TestValidator.predicate("must find uploaded attachment in result")(!!found);
  if (found) {
    TestValidator.equals("postId matches")(found.post_id)(post.id);
    TestValidator.equals("author matches")(found.author_member_id)(member.id);
    TestValidator.equals("filename matches")(found.file_name)(attachmentBody.file_name);
    TestValidator.equals("mime type matches")(found.mime_type)(attachmentBody.mime_type);
    TestValidator.equals("file size matches")(found.file_size_bytes)(attachmentBody.file_size_bytes);
    TestValidator.predicate("uri present and non-empty")(!!found.uri);
  }

  // 9. Validate pagination fields
  TestValidator.equals("correct page returned")(result.pagination.current)(1);
  TestValidator.equals("limit matches page size")(result.pagination.limit)(pageSize);
  TestValidator.predicate("total at least 1 record")(result.pagination.records >= 1);
  TestValidator.predicate("total pages >= 1")(result.pagination.pages >= 1);

  // 10. Filtering: file_name filter (exact match)
  const filteredResult = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: post.id,
    body: {
      file_name: attachmentBody.file_name,
      post_id: post.id,
      mime_type: null,
      created_after: null,
      created_before: null,
      author_member_id: null,
      page: 1,
      limit: pageSize,
    },
  });
  typia.assert(filteredResult);
  TestValidator.predicate("filtered result contains the file")(filteredResult.data.some((a) => a.id === attachment.id));

  // 11. Filtering: non-matching file_name (should return none)
  const filteredNone = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: post.id,
    body: {
      file_name: "definitely_not_a_file_name____invalid.pdf",
      post_id: post.id,
      mime_type: null,
      created_after: null,
      created_before: null,
      author_member_id: null,
      page: 1,
      limit: pageSize,
    },
  });
  typia.assert(filteredNone);
  TestValidator.equals("zero results for bad file name")(filteredNone.data.length)(0);

  // 12. (Negative test) Permission – attachments for other posts aren't returned (by post_id boundary)
  const bogusResult = await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
    postId: typia.random<string & tags.Format<"uuid">>(),
    body: {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      file_name: null,
      mime_type: null,
      created_after: null,
      created_before: null,
      author_member_id: null,
      page: 1,
      limit: pageSize,
    },
  });
  typia.assert(bogusResult);
  TestValidator.equals("no data for random/other post id")(bogusResult.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPageIPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validates that a guest (unauthenticated user) cannot access the attachment list of a private or member-only post.
 *
 * Business Context:
 * Many boards and posts restrict attachment access to authenticated members. Guest users must be denied both metadata and file access for privacy/security.
 *
 * Step-by-step process:
 * 1. Admin creates a category.
 * 2. Admin creates a private board (not public) under that category.
 * 3. Register and create a new member account.
 * 4. Member logs in (authentication, simulates real login flow).
 * 5. Member creates a post in the private board.
 * 6. Member attaches a file to the post.
 * 7. As a guest (after clearing Authorization), attempts to retrieve attachment list for the post via PATCH.
 * 8. Validate that permission is denied and no attachment data is leaked.
 */
export async function test_api_post_attachment_search_access_denied_guest(connection: api.IConnection) {
  // 1. Admin creates a category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(3),
      description: RandomGenerator.paragraph()(2),
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(category);

  // 2. Admin creates a private board assigned to the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(3),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(2),
      is_public: false, // Not public
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(board);

  // 3. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // The API expects a password (see login), hash naming is business convention
      display_name: RandomGenerator.name(),
      consent_status: "consented",
      profile_image_uri: null,
    },
  });
  typia.assert(member);

  // 4. Member login
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 5. Member creates a post in the board
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()()(),
      tag_ids: [],
      attachments: [],
    },
  });
  typia.assert(post);

  // 6. Member attaches a file to the post
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: {
      uri: "https://storage.example.com/files/testfile.dat",
      file_name: "testfile.dat",
      file_size_bytes: typia.random<number & tags.Type<"int32"> & tags.Minimum<128> & tags.Maximum<2048>>() ,
      mime_type: "application/octet-stream",
    },
  });
  typia.assert(attachment);

  // 7. Simulate logout as guest by clearing Authorization header
  if (connection.headers) {
    delete connection.headers.Authorization;
  } else {
    connection.headers = {};
  }

  // 8. Attempt PATCH as guest to retrieve attachments (should fail with no data leaked)
  await TestValidator.error("guest cannot access member/private post attachments")(
    async () => {
      await api.functional.polEcoBoard.member.posts.attachments.search(connection, {
        postId: post.id,
        body: {},
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPageIPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * E2E test: Moderator can retrieve all post attachments, including flagged content
 *
 * Validates that a moderator can view all file attachments for any post in the board, even if files are hidden or flagged for regular members. Ensures system's permission policies for moderator role awareness/audit capabilities. Also checks audit trail (implicit, via operation success).
 *
 * Steps:
 * 1. Register and login a moderator (capture credentials)
 * 2. Register and login a regular member
 * 3. Create a board category (admin)
 * 4. Create a board under that category (admin)
 * 5. Member creates a post in the board
 * 6. Member uploads multiple file attachments to the post (at least one should be considered 'flagged': for demo, we upload normally, but we simulate a "flagged" state by using a special filename)
 * 7. Switch to moderator session (login as moderator)
 * 8. Moderator invokes attachment search for the post via moderator API
 * 9. Assert:
 *   - All files (including "flagged" ones) are included in the results
 *   - Total attachments in moderator search match uploads
 *
 * (NOTE: As we cannot programmatically flag attachments, we use markers in filenames; test validates that all, including ones that would be hidden to regular members in real system, show for moderator)
 */
export async function test_api_post_attachment_search_by_moderator_with_flagged_content(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const modEmail = typia.random<string & tags.Format<'email'>>();
  const modPassword = 'P@ssw0rd123!';
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: RandomGenerator.name(),
      consent_status: 'accept-v1',
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);

  // 2. Login moderator (capture token for later use)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: modEmail, password: modPassword } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);

  // 3. Register a regular member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberPassword = 'Pass1234!';
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // For demonstration, plain password (API does server-side hash in test)
      display_name: RandomGenerator.name(),
      consent_status: 'accept-v1',
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Member login
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Create a board category (admin)
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `Category-${RandomGenerator.alphabets(5)}`,
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 6. Create a board under that category (admin)
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: `Board-${RandomGenerator.alphabets(5)}`,
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 7. Member creates a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: 'Moderator test post',
      body: 'Main content for attachment audit.',
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 8. Member uploads several attachments to the post
  // Simulate some files as "flagged" by marker in file_name
  const attachments: string[] = [];
  for (const fileName of [
    'normal-file-A.txt',
    'normal-file-B.txt',
    'flagged-content-001.txt', // This one is considered "flagged" for test purposes
  ]) {
    const att = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
      postId: post.id,
      body: {
        uri: `https://fileserver.example.com/files/${fileName}`,
        file_name: fileName,
        file_size_bytes: typia.random<number & tags.Type<'int32'>>(),
        mime_type: 'text/plain',
      } satisfies IPolEcoBoardAttachment.ICreate,
    });
    attachments.push(fileName);
    typia.assert(att);
  }

  // 9. Switch to moderator session by logging in as moderator
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: modEmail, password: modPassword } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 10. Moderator invokes attachment search for the post
  const result = await api.functional.polEcoBoard.moderator.posts.attachments.search(connection, {
    postId: post.id,
    body: {}, // no filter, fetch all
  });
  typia.assert(result);

  // 11. Assert that all uploaded files are returned in the moderator attachment search
  const resultNames = result.data.map(x => x.file_name).sort();
  const expectedNames = attachments.slice().sort();
  TestValidator.equals('All attachment filenames')(resultNames)(expectedNames);
}

