import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdmin";
import type { IPageIPolEcoBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test paginated and filtered admin account search in polEcoBoard.
 *
 * This test covers admin account creation, login, usage of the /polEcoBoard/admin/admins PATCH endpoint for admin account search with pagination and filter options. The business goal is to validate operational effectiveness of the admin search view for management/audit dashboards, ensure correct access control, and guarantee large-dataset performance.
 *
 * Steps:
 * 1. Register several admin accounts with different combinations of privilege_level and is_active.
 * 2. Log in as one of the new admins using a registered email & password.
 * 3. Search for admins using PATCH /polEcoBoard/admin/admins with combinations of filters: privilege_level and is_active, plus pagination options.
 * 4. Validate that only summary (non-sensitive) fields are returned, and response matches the filter criteria and expected pagination behavior.
 * 5. Confirm operation handles large page/limit requests and correct record counts.
 *
 * This test does not attempt to access or infer sensitive admin account fields that should not be visible in search results.
 */
export async function test_api_admin_search_pagination_and_filtering(connection: api.IConnection) {
  // 1. Register a pool of admin accounts with varying attributes
  const adminCredentials: { email: string; password: string; }[] = ArrayUtil.repeat(10)(() => ({
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12), // min 8 chars by spec
  }));

  for (const cred of adminCredentials)
    await api.functional.auth.admin.register.signUp(connection, {
      body: {
        email: cred.email,
        password: cred.password,
      } satisfies IPolEcoBoardAdminAuth.SignUp,
    });

  // 2. Log in as a random admin
  const loginCred = RandomGenerator.pick(adminCredentials);

  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: loginCred.email,
      password: loginCred.password,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);

  // 3. Fetch first page, limit=5: no filters (all admins)
  const page1 = await api.functional.polEcoBoard.admin.admins.search(connection, {
    body: {
      page: 1,
      limit: 5,
    } satisfies IPolEcoBoardAdmin.IRequest,
  });
  typia.assert(page1);
  TestValidator.predicate("<=5 admins on page 1")(page1.data.length <= 5);

  // 4. Pagination: fetch page 2, should contain remainder
  const page2 = await api.functional.polEcoBoard.admin.admins.search(connection, {
    body: {
      page: 2,
      limit: 5,
    } satisfies IPolEcoBoardAdmin.IRequest,
  });
  typia.assert(page2);
  TestValidator.predicate("Admins do not repeat between pages")(
    page1.data.every(a1 => page2.data.every(a2 => a1.id !== a2.id))
  );

  // 5. Filtering: search by privilege_level=0 (should return only accounts with privilege 0)
  const filterPrivilege = await api.functional.polEcoBoard.admin.admins.search(connection, {
    body: {
      privilege_level: 0,
    } satisfies IPolEcoBoardAdmin.IRequest,
  });
  typia.assert(filterPrivilege);
  TestValidator.predicate("All results have privilege_level 0")(
    filterPrivilege.data.every(a => a.privilege_level === 0)
  );

  // 6. Filtering by is_active=true
  const filterActive = await api.functional.polEcoBoard.admin.admins.search(connection, {
    body: {
      is_active: true,
    } satisfies IPolEcoBoardAdmin.IRequest,
  });
  typia.assert(filterActive);
  TestValidator.predicate("All admins in filterActive are active")(
    filterActive.data.every(a => a.is_active === true)
  );

  // 7. Security: returned summaries do not include sensitive fields (only ISummary)
  if (filterActive.data.length) {
    const example = filterActive.data[0];
    // Only properties in ISummary (id, member_id, privilege_level, appointed_by_admin_id, is_active, created_at, updated_at)
    const allowed = ["id","member_id","privilege_level","appointed_by_admin_id","is_active","created_at","updated_at"];
    TestValidator.predicate("Only summary fields returned")(
      Object.keys(example).every(k => allowed.includes(k))
    );
  }
}

