import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate retrieval of filtered & paginated comment lists as a registered member using polEcoBoard endpoints.
 *
 * This test covers the following workflow:
 * 1. Register a new member (ensures proper consent_status/display_name).
 * 2. Log in as the member and use returned session for future requests.
 * 3. As admin, create a new board category (with required properties: unique name, display_order).
 * 4. As admin, create a new board in that category (unique name/code, is_public, display order).
 * 5. As the member, create a post in that board.
 * 6. As the member, create multiple comments under the new post (with variable content; a few active and at least one flagged).
 * 7. Retrieve a filtered, paginated comment list using POST/{postId}/comments PATCH with criteria:
 *    - Filter by author_member_id to match only the test member.
 *    - Filter out flagged comments (flagged = false; comment that is flagged should not appear).
 *    - Use limit=2, page=1 (pagination test for truncation).
 * 8. Assert:
 *    - Only comments matching filters (active, correct author, not flagged) are returned in .data
 *    - Pagination metadata in .pagination is correct (limit, records, pages, current)
 *    - Comments not matching filter (different author, flagged) are omitted.
 */
export async function test_api_member_comment_list_success_filter_pagination(connection: api.IConnection) {
  // 1. Register test member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestP@ssword123";
  const memberDisplayName = RandomGenerator.name();
  const consentStatus = "terms_v1";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: consentStatus
    }
  });
  typia.assert(member);

  // 2. Log in as the member
  const signin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });
  typia.assert(signin);
  // Patch connection with member token for future API calls
  connection.headers = { ...(connection.headers ?? {}), Authorization: signin.setHeaders.Authorization };

  // 3. Create a category (admin action; skip re-auth for admin for this test, assuming permissions for test env)
  const categoryName = "TestCat_" + RandomGenerator.alphaNumeric(8);
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      display_order: 1 + typia.random<number & tags.Type<"int32">>(),
      description: RandomGenerator.paragraph()()
    }
  });
  typia.assert(category);

  // 4. Create a board
  const boardCode = "testboard_" + RandomGenerator.alphaNumeric(6).toLowerCase();
  const boardName = "Board_" + RandomGenerator.name();
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: boardName,
      code: boardCode,
      is_public: true,
      is_archived: false,
      display_order: 1,
      description: RandomGenerator.paragraph()()
    }
  });
  typia.assert(board);

  // 5. Create a post as test member (connection is member session now)
  const postTitle = "Test Post Title " + RandomGenerator.alphaNumeric(6);
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: postTitle,
      body: postBody
    }
  });
  typia.assert(post);

  // 6. Create three comments as test member
  const commentBodies: string[] = [
    "First comment for filter",
    "Second one for filter",
    "A flagged comment for exclusion"
  ];
  const comments: IPolEcoBoardComment[] = [];
  for (let i = 0; i < commentBodies.length; ++i) {
    const createResult = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: commentBodies[i]
      }
    });
    typia.assert(createResult);
    comments.push(createResult);
  }

  // 6b. Simulate one comment being flagged (patch local .flagged property)
  comments[2].flagged = true;

  // 7. Search comments: filter only by member's own comments, flagged = false, page/limit
  const searchReq: IPolEcoBoardComment.IRequest = {
    post_id: post.id,
    author_member_id: member.id,
    flagged: false,
    page: 1,
    limit: 2,
    sort: "created_at",
    order: "asc"
  };
  const output = await api.functional.polEcoBoard.member.posts.comments.searchComments(connection, {
    postId: post.id,
    body: searchReq
  });
  typia.assert(output);
  // 8. Assert output
  for (const comment of output.data) {
    TestValidator.equals("correct author")(comment.author_member_id)(member.id);
    TestValidator.equals("not flagged")(comment.flagged)(false);
  }
  TestValidator.equals("pagination limit")(output.pagination.limit)(2);
  TestValidator.predicate("pagination page")(
    output.pagination.current >= 1
  );
  TestValidator.predicate("pagination records > 0")(
    output.pagination.records > 0
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPageIPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate the listing of comments for a post that has no comments.
 *
 * This test verifies the API returns an empty comment result set with correct pagination structure
 * when there are no comments for the given post. This is critical for ensuring correct edge case behavior
 * and for verifying the API's pagination contract even in the absence of data (empty state).
 *
 * Workflow:
 * 1. Register a new member
 * 2. Log in as the new member
 * 3. As admin, create a new board category
 * 4. As admin, create a new board assigned to the created category
 * 5. As the member, create a post in the created board (category)
 * 6. Request the comment list for that post (without adding any comments)
 * 7. Check that the returned list is empty and pagination fields are properly set
 */
export async function test_api_member_comment_list_empty_result(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberDisplayName = RandomGenerator.alphabets(10);
  const member: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      // Use password as hash for simplicity (simulate password hash scenario)
      password_hash: memberPassword,
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: "v1"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Log in as the member
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(loginResult);
  // connection.headers automatically updated with Authorization

  // 3. As admin, create a new board category
  const category: IPolEcoBoardCategory = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `Category ${RandomGenerator.alphabets(8)}`,
      description: "Test category for empty comment listing.",
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 4. As admin, create a new board assigned to the created category
  const board: IPolEcoBoardBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: `Board ${RandomGenerator.alphabets(6)}`,
      code: RandomGenerator.alphabets(10).toLowerCase(),
      description: "Test board for empty comments.",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 5. As the member, create a post in the created board (category)
  const post: IPolEcoBoardPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(2, 8),
      body: RandomGenerator.content()()(15, 32),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Request the comment list for the post (without adding any comments)
  const commentsPage = await api.functional.polEcoBoard.member.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      // Use default pagination (page 1, backend default limit)
      author_member_id: null,
      created_from: null,
      created_to: null,
      flagged: null,
      include_deleted: null,
      search: null,
      parent_comment_id: null,
      page: null,
      limit: null,
      sort: null,
      order: null
    } satisfies IPolEcoBoardComment.IRequest
  });
  typia.assert(commentsPage);

  // 7. Check that the returned list is empty and pagination fields are properly set
  TestValidator.equals("should have no comments")(commentsPage.data)([]);
  TestValidator.equals("pagination should be page 1")(commentsPage.pagination.current)(1);
  TestValidator.equals("pagination default limit")(typeof commentsPage.pagination.limit === "number" && commentsPage.pagination.limit > 0)(true);
  TestValidator.equals("pagination no records")(commentsPage.pagination.records)(0);
  TestValidator.equals("pagination no pages")(commentsPage.pagination.pages === 0 || commentsPage.pagination.pages === 1)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPageIPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardComment";
