import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test: member cannot retrieve comments on a post if its board is locked/archived.
 *
 * Business context: Platform must strictly restrict access to comments of posts belonging to locked or archived boards, as part of moderation and content lifecycle. This ensures users cannot interact with or view content on boards that have been administratively disabled (locked/archived). This test simulates a standard member workflow, validates permission enforcement, and prevents regression where comments surface from inactive boards.
 *
 * Steps:
 * 1. Register a new member (unique email/display_name, consent_status random static)
 * 2. Log in as that new member; capture session (auth header handled)
 * 3. Admin creates a new category (random name/desc, display_order arbitrary low int)
 * 4. Admin creates a board in this category (random name/code, is_public: true, is_archived: false)
 * 5. Member creates a post on this board's category (title/body > 10 chars, using created category)
 * 6. Admin locks/archives the board (is_archived: true)
 * 7. Attempt as member to list comments on the post: expect runtime error (forbidden/denied)
 *
 * Edge cases: Board archiving after post is created, but before comment list fetch occurs.
 */
export async function test_api_member_comment_list_access_denied_for_locked_post(connection: api.IConnection) {
  // 1. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "P@ssw0rd!";
  const memberDisplayName = RandomGenerator.name();
  const consent = "v1.0";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // Plain for test context; real API may hash
      display_name: memberDisplayName,
      consent_status: consent,
    },
  });
  typia.assert(member);

  // 2. Member login (session state)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 3. Admin creates category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    },
  });
  typia.assert(category);

  // 4. Admin creates board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphaNumeric(10),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 1,
    },
  });
  typia.assert(board);

  // 5. Member login again (ensure login context)
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword },
  });

  // Member creates post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()()(),
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(post);

  // 6. Admin login (simulate by registering a new admin if needed, otherwise assume admin auth context present)
  // For this test, we'll assume the current context allows admin ops (for board archive), or would inject admin token as part of test orchestration
  const locked = await api.functional.polEcoBoard.admin.boards.update(connection, {
    boardId: board.id,
    body: { is_archived: true },
  });
  typia.assert(locked);

  // 7. Member login again to restore context
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword },
  });

  // Attempt comment fetch, expect forbidden
  await TestValidator.error("should deny comment list for archived board")(async () => {
    await api.functional.polEcoBoard.member.posts.comments.searchComments(connection, {
      postId: post.id,
      body: { post_id: post.id },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPageIPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can retrieve the full list of comments for a post, including flagged and soft-deleted comments, confirming privileged visibility and correct filtering logic.
 *
 * This test simulates a realistic moderation workflow – from fresh registration and login as a moderator, to creating a test board category, board, and post, to generating several comments, some of which are later soft-deleted by the moderator to simulate moderation edge cases. The test then uses the PATCH operation as the moderator to fetch the post's comments with filters for flagged/deleted status, and checks that both ordinary and privileged (flagged, deleted) comment records are properly included in the result.
 *
 * Step-by-step process:
 * 1. Register a new moderator (fresh credentials)
 * 2. Log in as the moderator (obtain moderator session)
 * 3. Create a new board category as the moderator
 * 4. Create a board inside the category as the moderator
 * 5. Create a new post on the board as a member (using current session for test isolation)
 * 6. Add several comments (at least 3): ordinary, flagged candidate, and one to be deleted
 * 7. As moderator, soft-delete one of the comments (simulate soft deletion)
 * 8. As moderator, use PATCH postId/comments with filters:
 *    - flagged: null (fetch all)
 *    - include_deleted: true (must include deleted comments in moderation view)
 * 9. Assert that all expected comments (ordinary and deleted) appear in the moderator's result
 */
export async function test_api_moderator_comment_list_with_flagged_and_deleted(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestP@ssw0rd!42";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsentStatus = "v1.0";
  const regResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsentStatus,
    },
  });
  typia.assert(regResult);

  // 2. Moderator login
  const loginResult = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(loginResult);

  // 3. Create category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "E2E Moderation Cat " + RandomGenerator.alphaNumeric(8),
      description: "Category for testing moderator comment retrieval.",
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(category);

  // 4. Create board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: "Test Board " + RandomGenerator.alphaNumeric(6),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: "Board for moderator comment filter E2E.",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(board);

  // 5. Create a post (use moderator session for test isolation)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: "Moderator filter E2E Test Post",
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 6. Add comments
  const commentBodies = [
    "Normal comment for moderation.",
    "Will be deleted comment.",
    "Another ordinary comment."
  ];
  const commentObjs: IPolEcoBoardComment[] = [];
  for (const body of commentBodies) {
    const res = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body,
      },
    });
    typia.assert(res);
    commentObjs.push(res);
  }

  // 7. Delete the second comment (simulate moderator deletion)
  const deleted = await api.functional.polEcoBoard.moderator.posts.comments.erase(connection, {
    postId: post.id,
    commentId: commentObjs[1].id,
  });
  typia.assert(deleted);

  // 8. Fetch all comments as moderator, including deleted
  const search = await api.functional.polEcoBoard.moderator.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      include_deleted: true,
      flagged: null,
    },
  });
  typia.assert(search);

  // 9. Validate that all created comment bodies are represented
  const returnedBodies = search.data.map((c) => c.body);
  for (const originalBody of commentBodies) {
    TestValidator.predicate(`comment visible to moderator: ${originalBody}`)(returnedBodies.includes(originalBody));
  }
  // Specifically check that the deleted comment appears
  TestValidator.predicate("soft-deleted comment present in moderator view")(returnedBodies.includes(commentBodies[1]));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
