/**
 * Validate admin comment listing with flagged, soft-deleted, and author-filtering capabilities.
 *
 * This test ensures that an admin can:
 * 1. See all comments on a post, including flagged and soft-deleted ones (using include_deleted filter).
 * 2. Perform advanced filtering by author_member_id as well as soft-deleted status.
 * 3. See all business/audit fields in the comment summaries (such as flagged, deleted_at, timestamps), demonstrating permission boundaries.
 *
 * Steps:
 * 1. Register and log in an admin.
 * 2. Admin creates a new board category and board.
 * 3. Member context (admin also acts as member) creates a post and three comments under it.
 * 4. Admin soft-deletes one comment.
 * 5. Admin lists all comments (with include_deleted=true) and verifies all are visible.
 * 6. Admin lists only deleted comments and confirms soft-deleted comment appears.
 * 7. Admin runs filtering by author_member_id and checks only the correct author's comments are listed.
 * 8. Admin verifies all required fields are visible in the results, including internal audit fields.
 */
export async function test_api_admin_comment_list_with_flagged_deleted_and_filtering(connection: api.IConnection) {
  // 1. Register admin for privileged access
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUp = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUp);

  // 2. Login as admin to get auth/session
  const signIn = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signIn);

  // 3. Admin: create a category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `TestCat_${RandomGenerator.alphaNumeric(6)}`,
      description: "Test category for admin comment filters",
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Admin: create a board in the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: `Board_${RandomGenerator.alphaNumeric(4)}`,
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: "E2E admin board",
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Member context: create a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()(40)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Member context: add comments
  const commentNormal = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: { body: "Normal comment for admin E2E" } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentNormal);

  const commentFlagged = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: { body: "This comment will represent a flagged case" } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentFlagged);

  const commentToDelete = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: { body: "To be deleted by admin for filter test" } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(commentToDelete);

  // 7. Admin soft-deletes a comment
  const deletedComment = await api.functional.polEcoBoard.admin.posts.comments.erase(connection, {
    postId: post.id,
    commentId: commentToDelete.id,
  });
  typia.assert(deletedComment);
  TestValidator.predicate("deleted_at is set for soft-deleted comment")(!!deletedComment.deleted_at);

  // 8. Admin fetches ALL comments (include_deleted=true)
  const allComments = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      include_deleted: true,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(allComments);
  TestValidator.predicate("admin sees all comments including deleted")(
    allComments.data.length >= 3 &&
    allComments.data.some(c => c.id === commentNormal.id) &&
    allComments.data.some(c => c.id === commentFlagged.id) &&
    allComments.data.some(c => c.id === commentToDelete.id)
  );

  // 9. Admin filters to show only deleted comments (manual check)
  const deletedOnly = allComments.data.filter(c => c.id === commentToDelete.id);
  TestValidator.predicate("soft-deleted comment is present in results")(
    deletedOnly.length === 1
  );

  // 10. Admin filters by author (should see all test comments for this author)
  const filteredByAuthor = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      author_member_id: commentNormal.author_member_id,
      include_deleted: true,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(filteredByAuthor);
  TestValidator.predicate("all returned comments are by requested author")(
    filteredByAuthor.data.every(c => c.author_member_id === commentNormal.author_member_id)
  );

  // 11. (Extra) Admin verifies presence of audit/business fields in summaries
  for (const c of allComments.data) {
    TestValidator.predicate("flagged present")(typeof c.flagged === "boolean");
    TestValidator.predicate("created_at present")(typeof c.created_at === "string");
    TestValidator.predicate("updated_at present")(typeof c.updated_at === "string");
    // If soft-deleted, allow deleted_at to be set (may be missing or string/null)
    if (c.id === commentToDelete.id) {
      TestValidator.predicate("deleted_at present for deleted")(
        typeof deletedComment.deleted_at === "string"
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPageIPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate pagination, total records, edge pages, and sort order for admin comment listing.
 *
 * This scenario simulates admin listing a large comment set under a post with strict pagination,
 * verifying first/middle/last/empty page logic, correctness of total count and page count, and
 * ensures all data returned is tied to the test post. Additional check for 'asc' ordering provided.
 *
 * Workflow:
 * 1. Register a new admin and login (capture JWT for all admin calls)
 * 2. Create a new board category
 * 3. Create a new board within the category
 * 4. Create a new post in the board (simulate via member endpoint)
 * 5. Bulk create many comments under the post (45 total)
 * 6. As admin, paginate comment list with limit/page settings:
 *    - Page 1 (limit 10): expect 10 records
 *    - Page 3 (limit 10): expect 10 records
 *    - Last page (limit 10): expect 5 records
 *    - Page beyond last: expect 0 records
 *    - Confirm total record count/pages correct
 *    - All data post_id matches test post
 *    - Data sorted by created_at desc by default, or asc when so requested
 */
export async function test_api_admin_comment_list_pagination_and_edge_case(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResp);

  // 2. Login as admin (JWT for all protected calls)
  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResp);

  // 3. Create category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "E2E PagCat " + RandomGenerator.alphaNumeric(7),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Admin creates board under the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: "PagTestBoard_" + RandomGenerator.alphaNumeric(8),
      code: ("ptest_" + RandomGenerator.alphaNumeric(8)).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Create a post as member (using same session, assuming admin has member context)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: "Test Pagination Post " + RandomGenerator.alphaNumeric(8),
      body: RandomGenerator.paragraph()(3),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Bulk create 45 comments under the post
  const COMMENTS_TOTAL = 45;
  for (let idx = 0; idx < COMMENTS_TOTAL; ++idx) {
    const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: `Comment #${idx + 1} - ` + RandomGenerator.paragraph()(1),
      } satisfies IPolEcoBoardComment.ICreate,
    });
    typia.assert(comment);
  }

  // Pagination parameters for admin search
  const LIMIT = 10;
  const totalPages = Math.ceil(COMMENTS_TOTAL / LIMIT);

  // 1st page
  const page1 = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: 1,
      limit: LIMIT,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("1st page size")(page1.data.length)(10);
  TestValidator.equals("pagination.current == 1")(page1.pagination.current)(1);
  TestValidator.equals("pagination.limit == 10")(page1.pagination.limit)(10);

  // 3rd page
  const page3 = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: 3,
      limit: LIMIT,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(page3);
  TestValidator.equals("3rd page size")(page3.data.length)(10);
  TestValidator.equals("pagination.current == 3")(page3.pagination.current)(3);

  // Last page (should have 5)
  const lastPage = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: totalPages,
      limit: LIMIT,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(lastPage);
  TestValidator.equals("last page size")(lastPage.data.length)(5);
  TestValidator.equals("pagination.current == last page")(lastPage.pagination.current)(totalPages);

  // Out-of-bounds page (should be 0 records)
  const emptyPage = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: totalPages + 1,
      limit: LIMIT,
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty page size")(emptyPage.data.length)(0);

  // Validate total records and total pages
  TestValidator.equals("page1 total records")(page1.pagination.records)(COMMENTS_TOTAL);
  TestValidator.equals("page1 total pages")(page1.pagination.pages)(totalPages);
  TestValidator.equals("lastPage total records")(lastPage.pagination.records)(COMMENTS_TOTAL);
  TestValidator.equals("lastPage total pages")(lastPage.pagination.pages)(totalPages);

  // Confirm all comments returned are for the test post
  for (const res of [page1, page3, lastPage]) {
    for (const comment of res.data) {
      TestValidator.equals("comment belongs to post")(comment.post_id)(post.id);
    }
  }

  // Desc sort: Timestamps should be descending (default)
  const descStamps = page1.data.map(c => c.created_at);
  for (let i = 1; i < descStamps.length; ++i)
    TestValidator.predicate(`desc order ${i}`)(descStamps[i - 1] >= descStamps[i]);

  // Check ASC order
  const ascPage = await api.functional.polEcoBoard.admin.posts.comments.searchComments(connection, {
    postId: post.id,
    body: {
      post_id: post.id,
      page: 1,
      limit: LIMIT,
      order: "asc",
    } satisfies IPolEcoBoardComment.IRequest,
  });
  typia.assert(ascPage);
  TestValidator.equals("ascPage size")(ascPage.data.length)(10);
  const ascStamps = ascPage.data.map(c => c.created_at);
  for (let i = 1; i < ascStamps.length; ++i)
    TestValidator.predicate(`asc order ${i}`)(ascStamps[i - 1] <= ascStamps[i]);
}

