/**
 * Validates that a registered member can view all details of a specific active comment under a post they have access to.
 *
 * Business context:
 * This test runs through a typical member workflow: registering, login, post creation, commenting, and retrieval. It ensures that a member can see all relevant comment fields—with correct contents—on an accessible, active post they own.
 *
 * Process steps:
 * 1. Register a new member (unique email, password, display name, consent)
 * 2. Log in as the member (JWT/auth setup)
 * 3. Admin creates a unique category
 * 4. Admin creates a board in that category (is_public)
 * 5. Member creates a post assigned to the category
 * 6. Member adds a comment to their post
 * 7. Member fetches comment details via GET endpoint
 * 8. Validate that all returned fields in the comment are correct and as expected:
 *    - id, post_id, author_member_id, body, flagged status, created/updated timestamp, deleted_at null
 */
export async function test_api_member_comment_detail_view_accessible(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestPW!123#";
  const memberDisplayName = RandomGenerator.name();
  const consentStatus = "v1";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: consentStatus,
      profile_image_uri: null
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Log in as the member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });

  // 3. Admin creates a category
  const categoryName = RandomGenerator.alphaNumeric(10);
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: RandomGenerator.paragraph()(6),
      display_order: typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<99>>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 4. Admin creates a board in the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphaNumeric(12),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(4),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<99>>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 5. Member creates a post in the category (not board ID, but category ID is required)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()()(40),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Member adds a comment to the post
  const commentBody = RandomGenerator.paragraph()(7);
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: commentBody
    } satisfies IPolEcoBoardComment.ICreate
  });
  typia.assert(comment);

  // 7. Fetch comment detail as the member
  const detail = await api.functional.polEcoBoard.member.posts.comments.at(connection, {
    postId: post.id,
    commentId: comment.id
  });
  typia.assert(detail);

  // 8. Validate critical response fields
  TestValidator.equals("comment id matches")(detail.id)(comment.id);
  TestValidator.equals("post id matches")(detail.post_id)(post.id);
  TestValidator.equals("author matches member")(detail.author_member_id)(member.id);
  TestValidator.equals("comment body matches")(detail.body)(commentBody);
  TestValidator.equals("flagged false")(detail.flagged)(false);
  TestValidator.predicate("comment created_at string")(typeof detail.created_at === "string");
  TestValidator.predicate("comment updated_at string")(typeof detail.updated_at === "string");
  TestValidator.equals("comment not soft deleted")(detail.deleted_at)(null);
