    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create category (must be possible with current JWT—if not, simulate admin here)
  const category: IPolEcoBoardCategory = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `E2E Test Category ${RandomGenerator.alphabets(6)}`,
      description: "Test category for locked board permission",
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 4. Create a board in that category
  const board: IPolEcoBoardBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: `E2E Test Board ${RandomGenerator.alphabets(6)}`,
      code: `e2e_board_${RandomGenerator.alphaNumeric(8).toLowerCase()}`,
      description: "Test board for comment permission",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 5. Create a post as the member
  const post: IPolEcoBoardPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: `Test Post Title ${RandomGenerator.alphabets(5)}`,
      body: RandomGenerator.paragraph()(),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Create a comment as the member
  const comment: IPolEcoBoardComment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()().substring(0, 100),
      parent_comment_id: null
    } satisfies IPolEcoBoardComment.ICreate
