  TestValidator.equals("sanctioned_user_id")(sanctionResp.sanctioned_user_id)(memberId);
  TestValidator.equals("sanction_type")(sanctionResp.sanction_type)(sanctionType);
  TestValidator.equals("status")(sanctionResp.status)(sanctionStatus);
  TestValidator.equals("rationale")(sanctionResp.rationale)(sanctionRationale);
  TestValidator.equals("start_at")(sanctionResp.start_at)(startAt);
  TestValidator.equals("end_at")(sanctionResp.end_at)(endAt);
  TestValidator.predicate("created_at is date-time")(!!Date.parse(sanctionResp.created_at));
  TestValidator.predicate("updated_at is date-time")(!!Date.parse(sanctionResp.updated_at));
  TestValidator.equals("deleted_at is null")(sanctionResp.deleted_at)(null);
}

