import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardEscalation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardEscalation";
import type { IPageIPolEcoBoardEscalation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardEscalation";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Tests the search/filter and pagination workflow for escalations from the admin panel.
 *
 * This covers the full privileged moderation admin journey: uses privileged registration/login, creates a range of escalation cases
 * referencing different actions, operators, statuses, and rationales, and exercises a variety of filters and paging queries.
 *
 * Validates:
 * - Registration and authentication of admin
 * - Creation of different moderation actions and escalation cases with varied business data
 * - Searching escalations using various combinations of: status, rationale substring, escalator, recipient admin, moderation_action_id, and time ranges
 * - Verifies that only the expected records are returned for each filter and that paging metadata is correct
 * - Pagination: checks that page, limit, total count, and returned results conform to expectations
 * - Edge cases: searches that should yield 0 results, searches with invalid filters (business-friendly error response)
 *
 * Full end-to-end moderation scenario for compliance, audit dashboard, and escalation incident workflows.
 *
 * Steps:
 * 1. Register a new admin
 * 2. Log in with this admin account (token is set)
 * 3. Create several moderation actions with different actors/statuses/outcomes/reports
 * 4. Create a variety of escalations referring to those actions, using different combinations of escalator/admin/status/reason/time
 * 5. Test search by: specific status, rationale substring, escalator id, recipient admin id, moderation action id, and created_at interval
 * 6. Validate that only correct escalations are returned for each case and that paging metadata is mathematically correct
 * 7. Test paginated queries for different page/limit combos
 * 8. Try edge cases: search returning 0 records, search with invalid filters, ensure compliant error handling
 */
export async function test_api_escalation_search_filter_pagination_admin(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: password,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResp);

  // 2. Login as admin (token is set in connection)
  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResp);

  // 3. Create moderation actions with different actors/statuses/outcomes/rationales
  const actionCount = 3;
  const uniqueReports = ArrayUtil.repeat(actionCount)(() => typia.random<string & tags.Format<"uuid">>());
  const uniqueOperators = ArrayUtil.repeat(actionCount)(() => typia.random<string & tags.Format<"uuid">>());
  const moderationActions: IPolEcoBoardModerationAction[] = [];
  for (let i = 0; i < actionCount; ++i) {
    const action = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
      body: {
        report_id: uniqueReports[i],
        operator_id: uniqueOperators[i],
        action_type: RandomGenerator.alphabets(6),
        target_type: RandomGenerator.alphabets(6),
        status: ["pending", "completed", "overruled"][i % 3],
        rationale: `Rationale #${i}`,
        outcome: ["accepted", "rejected", "escalated"][i % 3],
      } satisfies IPolEcoBoardModerationAction.ICreate,
    });
    typia.assert(action);
    moderationActions.push(action);
  }

  // 4. Create escalation events referencing those actions w/ different moderators, admins
  const escalationCount = 6;
  const escalations: IPolEcoBoardEscalation[] = [];
  for (let i = 0; i < escalationCount; ++i) {
    const escalation = await api.functional.polEcoBoard.moderator.escalations.create(connection, {
      body: {
        moderation_action_id: moderationActions[i % actionCount].id,
        escalator_id: typia.random<string & tags.Format<"uuid">>(),
        recipient_admin_id: uniqueOperators[i % actionCount],
        reason: `Escalation Reason ${i}`,
        status: ["pending", "resolved", "rejected"][i % 3],
      } satisfies IPolEcoBoardEscalation.ICreate,
    });
    typia.assert(escalation);
    escalations.push(escalation);
  }

  // Helper: get escalations filtered as expected by basic equality checks
  function filterEscalations(filters: Partial<IPolEcoBoardEscalation.IRequest>): IPolEcoBoardEscalation[] {
    return escalations.filter(esc =>
      (!filters.moderation_action_id || esc.moderation_action_id === filters.moderation_action_id) &&
      (!filters.escalator_id || esc.escalator_id === filters.escalator_id) &&
      (!filters.recipient_admin_id || esc.recipient_admin_id === filters.recipient_admin_id) &&
      (!filters.reason || esc.reason.includes(filters.reason)) &&
      (!filters.status || esc.status === filters.status)
    );
  }

  // 5. Search tests by field (status, reason substring, escalator, recipient admin, moderation_action_id)
  for (const status of ["pending", "resolved", "rejected"]) {
    const matching = filterEscalations({ status });
    const output = await api.functional.polEcoBoard.admin.escalations.search(connection, {
      body: { status } satisfies IPolEcoBoardEscalation.IRequest,
    });
    typia.assert(output);
    TestValidator.equals(`escalations for status=${status}`)(output.data.length)(matching.length);
    TestValidator.predicate("all records match status")(
      output.data.every(e => e.status === status),
    );
    TestValidator.equals("pagination count matches")(output.pagination.records)(matching.length);
  }

  // Search by rationale substring (should pick up reasons containing e.g. 'Reason 2')
  const reasonSearch = "Reason 2";
  const rationaleMatches = filterEscalations({ reason: reasonSearch });
  const rationaleRes = await api.functional.polEcoBoard.admin.escalations.search(connection, {
    body: { reason: reasonSearch } satisfies IPolEcoBoardEscalation.IRequest
  });
  typia.assert(rationaleRes);
  TestValidator.equals("rationale substring match count")(rationaleRes.data.length)(rationaleMatches.length);
  TestValidator.predicate("all records contain searched rationale")(
    rationaleRes.data.every(e => e.reason.includes(reasonSearch)),
  );

  // Search by recipient_admin_id
  const recipientId = escalations[0].recipient_admin_id;
  const recipientMatches = filterEscalations({ recipient_admin_id: recipientId });
  const recipientRes = await api.functional.polEcoBoard.admin.escalations.search(connection, {
    body: { recipient_admin_id: recipientId } satisfies IPolEcoBoardEscalation.IRequest
  });
  typia.assert(recipientRes);
  TestValidator.equals("recipient admin filter count")(recipientRes.data.length)(recipientMatches.length);
  TestValidator.predicate("admin id match")(
    recipientRes.data.every(e => e.recipient_admin_id === recipientId),
  );

  // Search by escalator_id
  const escalatorId = escalations[1].escalator_id;
  const escalatorMatches = filterEscalations({ escalator_id: escalatorId });
  const escalatorRes = await api.functional.polEcoBoard.admin.escalations.search(connection, {
    body: { escalator_id: escalatorId } satisfies IPolEcoBoardEscalation.IRequest
  });
  typia.assert(escalatorRes);
  TestValidator.equals("escalator filter count")(escalatorRes.data.length)(escalatorMatches.length);
  TestValidator.predicate("escalator id match")(
    escalatorRes.data.every(e => e.escalator_id === escalatorId),
  );

  // Search by moderation_action_id
  const modActionId = escalations[2].moderation_action_id;
  const modMatches = filterEscalations({ moderation_action_id: modActionId });
  const modRes = await api.functional.polEcoBoard.admin.escalations.search(connection, {
    body: { moderation_action_id: modActionId } satisfies IPolEcoBoardEscalation.IRequest
  });
  typia.assert(modRes);
  TestValidator.equals("mod action id filter count")(modRes.data.length)(modMatches.length);
  TestValidator.predicate("mod action id matches")(
    modRes.data.every(e => e.moderation_action_id === modActionId),
  );

  // 6. Date filtering: created_at_start/created_at_end
  // We'll use min/max created_at of our escalations
  const byTimestamp = escalations.slice().sort((a, b) => a.created_at.localeCompare(b.created_at));
  const start = byTimestamp[1].created_at;
  const end = byTimestamp[4].created_at;
  const dateMatches = escalations.filter(e => e.created_at >= start && e.created_at <= end);
  const dateRes = await api.functional.polEcoBoard.admin.escalations.search(connection, {
    body: { created_at_start: start, created_at_end: end } satisfies IPolEcoBoardEscalation.IRequest
  });
  typia.assert(dateRes);
  TestValidator.equals("created_at range count")(dateRes.data.length)(dateMatches.length);
  TestValidator.predicate("all in range")(
    dateRes.data.every(e => e.created_at >= start && e.created_at <= end)
  );

  // 7. Pagination: Test limit and page
  const pagedRes = await api.functional.polEcoBoard.admin.escalations.search(connection, {
    body: { limit: 2, page: 2 } satisfies IPolEcoBoardEscalation.IRequest
  });
  typia.assert(pagedRes);
  TestValidator.equals("limit on page=2")(pagedRes.data.length)(Math.min(2, escalations.length - 2));
  TestValidator.equals("pagination meta matches")(pagedRes.pagination.limit)(2);
  TestValidator.equals("pagination meta page")(pagedRes.pagination.current)(2);

  // 8. Edge: filter that returns 0 results
  const noMatchReason = "not-a-reason";
  const zeroRes = await api.functional.polEcoBoard.admin.escalations.search(connection, {
    body: { reason: noMatchReason } satisfies IPolEcoBoardEscalation.IRequest
  });
  typia.assert(zeroRes);
  TestValidator.equals("zero result search count")(zeroRes.data.length)(0);

  // 9. Edge: invalid filter (simulate, e.g., impossible uuid)
  await TestValidator.error("invalid filter yields error")(
    async () => {
      await api.functional.polEcoBoard.admin.escalations.search(connection, {
        body: { moderation_action_id: "not-a-uuid" as any } satisfies IPolEcoBoardEscalation.IRequest
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPageIPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator search & filtering of post abuse reports by various filters/pagination.
 *
 * Ensures that:
 * - Moderator can fetch a paginated/filterable list of reports for a post.
 * - Filtering by reason_code, reporter_member_id, created_at ranges works.
 * - Pagination is honored.
 * - Only reports matching the given postId are shown (no cross-post contamination).
 * - Forbidden or invalid postId queries return error.
 *
 * Limitations:
 * - Cannot directly simulate member authentication or non-moderator access attempts due to missing member login endpoints.
 * - Only moderator and the system's allowed flows are testable here.
 *
 * Steps:
 * 1. Register & login as moderator.
 * 2. Create Post as member (performed as moderator, since no member API exists).
 * 3. Create several reports by simulating different "reporters" (random reporter_member_id, reason_code, created_at).
 * 4. Test querying with:
 *    a. No filter (expect all reports)
 *    b. reason_code filter
 *    c. reporter_member_id filter
 *    d. created_at_start/created_at_end
 *    e. Pagination (limit/page)
 *    f. No match filter (expect empty)
 *    g. Invalid postId (error expected)
 *    h. Cross-post check: unrelated report must not be returned
 */
export async function test_api_post_report_search_by_moderator_various_filters(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const password = "Moderator@123";
  const displayName = RandomGenerator.name();
  const consent = "agreed-v1";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password,
      display_name: displayName,
      consent_status: consent
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(moderatorReg);

  // 2. Login as moderator (obtain auth token)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(moderatorLogin);

  // 3. Create a post (as-member simulation; only endpoint is available, so performed as moderator)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1, 2);
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: { category_id: categoryId, title: postTitle, body: postBody } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Create multiple reports on this post (simulate different reporters, reasons, time)
  const reasons = ["abuse", "spam", "hate", "off_topic", "other"];
  const createdReports: IPolEcoBoardReport[] = [];
  const reporterIds: string[] = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  // For time variation, set created_at values spread in the past
  const now = new Date();

  for (let i = 0; i < 8; ++i) {
    const reporter_member_id = RandomGenerator.pick(reporterIds);
    const reason_code = RandomGenerator.pick(reasons);
    // Simulate as if reports are created sequentially by changing reason, reporter, created_at spacing
    const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
      postId: post.id,
      body: {
        reason_code,
        reason_description: RandomGenerator.paragraph()(),
        post_id: post.id
      } satisfies IPolEcoBoardReport.ICreate
    });
    // Emulate variety in report creation times by modifying created_at (not possible via API: only system fills created_at)
    createdReports.push(report);
    typia.assert(report);
  }

  // 5. Create an unrelated post + report (for cross-post contamination check)
  const otherPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: { category_id: typia.random<string & tags.Format<"uuid">>(), title: RandomGenerator.paragraph()(1, 2), body: RandomGenerator.content()()() } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(otherPost);

  const otherReport = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: otherPost.id,
    body: {
      reason_code: "spam",
      reason_description: RandomGenerator.paragraph()(),
      post_id: otherPost.id
    } satisfies IPolEcoBoardReport.ICreate
  });
  typia.assert(otherReport);

  // 6a. As moderator, query without filter: expect all 8 reports
  const resAll = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
    postId: post.id,
    body: {} satisfies IPolEcoBoardReport.IRequest
  });
  typia.assert(resAll);
  const reportIdsAll = resAll.data.map((r) => r.id);
  TestValidator.equals("all reports count")(reportIdsAll.length)(8);

  // 6b. By reason_code
  for (const reason of reasons) {
    const res = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: post.id,
      body: { reason_code: reason } satisfies IPolEcoBoardReport.IRequest
    });
    typia.assert(res);
    for (const report of res.data) TestValidator.equals("filter reason_code")(report.reason_code)(reason);
  }

  // 6c. By reporter_member_id
  for (const repId of reporterIds) {
    const res = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: post.id,
      body: { reporter_member_id: repId } satisfies IPolEcoBoardReport.IRequest
    });
    typia.assert(res);
    for (const report of res.data) TestValidator.equals("filter reporter_member_id")(report.reporter_member_id)(repId);
  }

  // 6d. created_at_start/created_at_end - pick min/max from createdReports
  const createdAts = createdReports.map(r => r.created_at).sort();
  if (createdAts.length >= 2) {
    const start = createdAts[1];
    const end = createdAts[createdAts.length - 2];
    const res = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: post.id,
      body: { created_at_start: start, created_at_end: end } satisfies IPolEcoBoardReport.IRequest
    });
    typia.assert(res);
    for (const report of res.data) {
      TestValidator.predicate("created_at_start")(report.created_at >= start);
      TestValidator.predicate("created_at_end")(report.created_at <= end);
    }
  }

  // 6e. Pagination (limit=2, page=2)
  const pageRes = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 2, page: 2 } satisfies IPolEcoBoardReport.IRequest
  });
  typia.assert(pageRes);
  TestValidator.equals("pagination limit")(pageRes.pagination.limit)(2);
  TestValidator.equals("pagination page")(pageRes.pagination.current)(2);

  // 6f. Filter returning no match (e.g., bogus reporter_member_id)
  const noneRes = await api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
    postId: post.id,
    body: { reporter_member_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardReport.IRequest
  });
  typia.assert(noneRes);
  TestValidator.equals("no results")(noneRes.data.length)(0);

  // 6g. Cross-post: ensure a report from other post is not returned here
  for (const report of resAll.data) {
    TestValidator.notEquals("cross-post contamination")(report.id)(otherReport.id);
    TestValidator.equals("belongs to correct post")(report.post_id)(post.id);
  }

  // 6h. Invalid postId (malformed uuid)
  TestValidator.error("invalid postId")(async () =>
    api.functional.polEcoBoard.moderator.posts.reports.search(connection, {
      postId: "invalid-uuid-format" as any,
      body: {} satisfies IPolEcoBoardReport.IRequest
    })
  );

  // 6i. Forbidden: not testable (no member login), so omitted
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPageIPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin user can properly search, filter, and paginate abuse/moderation reports for a specific post.
 *
 * This comprehensive test covers:
 * 1. Set up: Register a new admin and log in, register a post as a member, and create several reports on that post as a member user.
 * 2. As an admin, call the report search (PATCH /polEcoBoard/admin/posts/{postId}/reports) endpoint with:
 *    - No filters (basic scan, first page expected)
 *    - Pagination (e.g. limit=2, page=2), verifying correct metadata and content
 *    - Filter by reason_code (should return only matching subset)
 *    - Filter by created_at range (should return only reports in this window)
 *    - Filter by reporter_member_id (only reports by a specific reporter)
 *    - All filters combined (should properly intersect sets)
 *    - Filter with intentionally excessive limits (should clip to allowed server max, e.g. 100)
 *    - Filter for an empty result (no matches)
 * 3. Negative cases:
 *    - Search for a non-existent postId (should yield empty or error)
 *    - Search for a deleted postId (should yield empty or error)
 *    - search as unauthenticated or with expired/bad token (should fail with auth error)
 *    - search with invalid postId format (should fail with validation error)
 *    - search as a non-admin (should fail with authorization error)
 *
 * Steps:
 * 1. Register and login as admin.
 * 2. Register and login as member (for creating a post and reports).
 * 3. Create a post as a member.
 * 4. File several reports against that post as a member (vary reason, description, and created_at via test timing).
 * 5. Switch to admin user.
 * 6. Exercise the /polEcoBoard/admin/posts/{postId}/reports endpoint with varied filters and paging as described above.
 * 7. Validate response types, content, pagination, and access controls.
 */
export async function test_api_post_report_search_by_admin_filter_pagination_error_handling(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Create a post as a member (simulate as member by using member post endpoint)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1, 2),
      body: RandomGenerator.content()(1, 3)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. File several reports as a member (simulate as ordinary member)
  // We'll file 3 reports with different reason_codes
  const reasons = ["abuse", "spam", "hate"];
  for (const reason of reasons) {
    const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
      postId: post.id,
      body: {
        reason_code: reason,
        reason_description: `Report for ${reason} at ${new Date().toISOString()}`,
        post_id: post.id,
      } satisfies IPolEcoBoardReport.ICreate,
    });
    typia.assert(report);
  }

  // 4. As admin, perform report searches with various filters & pagination
  // a) No filters (should return all above reports, correct pagination)
  let output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: {},
  });
  typia.assert(output);
  TestValidator.predicate("all reports returned")(output.data.length >= 3);
  TestValidator.equals("total records")(output.pagination.records)(output.data.length);

  // b) Pagination (limit=2, page=1)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 2, page: 1 },
  });
  typia.assert(output);
  TestValidator.equals("pagination limit")(output.pagination.limit)(2);
  TestValidator.equals("pagination current page")(output.pagination.current)(1);
  TestValidator.predicate("page contains 2 or fewer entries")(output.data.length <= 2);

  // c) Filter by reason_code (reason_code = "spam")
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "spam" },
  });
  typia.assert(output);
  TestValidator.predicate("only spam reports")(output.data.every(r => r.reason_code === "spam"));

  // d) Date range filter (from now - 1min to now + 2min)
  const now = new Date();
  const from = new Date(now.getTime() - 60 * 1000).toISOString();
  const to = new Date(now.getTime() + 120 * 1000).toISOString();
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { created_at_start: from, created_at_end: to },
  });
  typia.assert(output);
  TestValidator.predicate("created in window")(output.data.every(r => r.created_at >= from && r.created_at <= to));

  // e) Reporter filter (reporter_member_id from a report)
  const firstReport = output.data[0];
  if (firstReport) {
    output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
      postId: post.id,
      body: { reporter_member_id: firstReport.reporter_member_id },
    });
    typia.assert(output);
    TestValidator.predicate("only first reporter")(output.data.every(r => r.reporter_member_id === firstReport.reporter_member_id));
  }

  // f) Combination filter (reason_code and date range)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "spam", created_at_start: from, created_at_end: to },
  });
  typia.assert(output);
  TestValidator.predicate("spam reports in window")(output.data.every(r => r.reason_code === "spam" && r.created_at >= from && r.created_at <= to));

  // g) Excessive limit (limit=1000, should be capped, but must not error)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { limit: 1000 },
  });
  typia.assert(output);
  TestValidator.predicate("limit not exceeded")(output.pagination.limit <= 100);

  // h) Empty result (impossible reason_code)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: post.id,
    body: { reason_code: "nonexistent_reason_code_zzz" },
  });
  typia.assert(output);
  TestValidator.equals("empty data")(output.data.length)(0);

  // 5. Negative cases
  // i) Non-existent postId (random uuid)
  output = await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
    postId: typia.random<string & tags.Format<"uuid">>(),
    body: {},
  });
  typia.assert(output);
  // We cannot guarantee error vs empty, but must not throw

  // j) Invalid postId format
  await TestValidator.error("malformed postId should fail")(async () => {
    await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
      postId: "not_a_uuid" as any,
      body: {},
    });
  });

  // k) Unauthenticated: remove token manually and attempt
  if (connection.headers) {
    const oldAuth = connection.headers.Authorization;
    delete connection.headers.Authorization;
    await TestValidator.error("unauthenticated access fails")(async () => {
      await api.functional.polEcoBoard.admin.posts.reports.search(connection, {
        postId: post.id,
        body: {},
      });
    });
    connection.headers.Authorization = oldAuth;
  }

  // l) Authorization: simulate as member (auth as member) - cannot create member with current API, so omitted.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator and unauthorized access to individual report details, covering business rules for transparency, audit linkage, and strict permission boundaries.
 *
 * 1. Register a moderator and capture credentials
 * 2. Log in as moderator for privileged access
 * 3. Create a post as a (simulated) member
 * 4. File a report on the post as that member
 * 5. [Success] Fetch report detail as moderator: verify all key fields and referential integrity
 * 6. [Negative] Try fetching the same report with a mismatched postId: expect error
 * 7. [Negative] Try fetching a non-existent reportId: expect error
 * 8. [Negative] Try fetching the same report as unauthenticated or regular member: expect permission denied
 * 9. Confirm data privacy: No fields exposed beyond those in schema (reporter_member_id is an opaque UUID)
 */
export async function test_api_post_report_detail_view_by_moderator_and_permission_checks(connection: api.IConnection) {
  // --- Step 1: Register a moderator and capture credentials
  const modEmail = typia.random<string & tags.Format<'email'>>();
  const modPassword = 'TestM0dPass!';
  const modDisplayName = RandomGenerator.name();
  const consentStatus = 'accepted_v1';

  const modRegRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(modRegRes);

  // --- Step 2: Log in as moderator
  const modLoginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(modLoginRes);

  // Store moderator JWT for swapping back later
  const moderatorToken = modLoginRes.setHeaders.Authorization;

  // --- Step 3: Create a post as (simulated) member (no member endpoints provided, so use existing context)
  const categoryId = typia.random<string & tags.Format<'uuid'>>();
  const postTitle = RandomGenerator.paragraph()(15);
  const postBody = RandomGenerator.content()(3)();

  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // --- Step 4: File a report on the post as that member
  const reportReason = 'abuse';
  const reportDescription = 'Inappropriate content';

  const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: post.id,
    body: {
      reason_code: reportReason,
      reason_description: reportDescription,
      post_id: post.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report);

  // --- Step 5: Fetch report detail as moderator: expect success
  // Ensure connection uses moderator token
  connection.headers = { ...connection.headers, Authorization: moderatorToken };
  const reportRead = await api.functional.polEcoBoard.moderator.posts.reports.at(connection, {
    postId: post.id,
    reportId: report.id,
  });
  typia.assert(reportRead);

  // Validate linkage and all mandatory fields in API contract
  TestValidator.equals('report id matches')(reportRead.id)(report.id);
  TestValidator.equals('post id linkage')(reportRead.post_id)(post.id);
  TestValidator.equals('reason')(reportRead.reason_code)(reportReason);
  TestValidator.equals('reason description')(reportRead.reason_description)(reportDescription);
  TestValidator.equals('reporter member id present')(reportRead.reporter_member_id)(report.reporter_member_id);

  // --- Step 6: Try fetching report with mismatched postId: expect error
  await TestValidator.error('mismatched postId should fail')(async () => {
    await api.functional.polEcoBoard.moderator.posts.reports.at(connection, {
      postId: typia.random<string & tags.Format<'uuid'>>(), // Wrong post ID
      reportId: report.id,
    });
  });

  // --- Step 7: Try fetching a non-existent report: expect error
  await TestValidator.error('non-existent report should fail')(async () => {
    await api.functional.polEcoBoard.moderator.posts.reports.at(connection, {
      postId: post.id,
      reportId: typia.random<string & tags.Format<'uuid'>>(), // Non-existent reportId
    });
  });

  // --- Step 8: Try as unauthorized/regular member (remove Authorization header): expect permission error
  const priorHeaders = connection.headers;
  connection.headers = { ...priorHeaders };
  delete connection.headers.Authorization;
  await TestValidator.error('unauthorized member cannot access report details')(async () => {
    await api.functional.polEcoBoard.moderator.posts.reports.at(connection, {
      postId: post.id,
      reportId: report.id,
    });
  });
  connection.headers = priorHeaders; // Restore any prior headers
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can update the consent status of a guest session.
 *
 * Business context: For legal compliance, only admin accounts may change the privacy consent status of guest sessions. This test ensures that admin authentication is required, and that consent updates really change relevant fields for the specified guest session, supporting audit and compliance requirements.
 *
 * Step-by-step process:
 * 1. Register a new admin account with a random unique email and valid password.
 * 2. Log in as the admin – the connection JWT is automatically updated.
 * 3. Create a new guest session (with IP, device fingerprint, and initial consent status).
 * 4. As admin, update the consent_status string for the guest session to a new unique value.
 * 5. Validate all of the following:
 *    - The returned guest object has the same id, ip_address, and created_at as before.
 *    - consent_status now matches the new value provided.
 *    - updated_at timestamp reflects the update (is different from before).
 */
export async function test_api_guest_update_valid_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Log in as admin to obtain a valid JWT
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // 3. Create a fresh guest session
  const guestCreation = await api.functional.polEcoBoard.guests.create(connection, {
    body: {
      ip_address: "203.0.113." + typia.random<number & tags.Type<"uint32"> & tags.Maximum<255>>().toString(),
      device_fingerprint: RandomGenerator.alphaNumeric(16),
      consent_status: RandomGenerator.alphaNumeric(8),
    } satisfies IPolEcoBoardGuest.ICreate,
  });
  typia.assert(guestCreation);

  // 4. Update consent_status as admin to a new string
  let newConsentStatus: string;
  do {
    newConsentStatus = RandomGenerator.alphaNumeric(10);
  } while (newConsentStatus === guestCreation.consent_status);

  const updatedGuest = await api.functional.polEcoBoard.admin.guests.update(connection, {
    guestId: guestCreation.id,
    body: {
      consent_status: newConsentStatus,
    } satisfies IPolEcoBoardGuest.IUpdate,
  });
  typia.assert(updatedGuest);

  // 5. Validate all relevant fields
  TestValidator.equals("id unchanged")(updatedGuest.id)(guestCreation.id);
  TestValidator.equals("ip_address unchanged")(updatedGuest.ip_address)(guestCreation.ip_address);
  TestValidator.equals("created_at unchanged")(updatedGuest.created_at)(guestCreation.created_at);
  TestValidator.equals("device_fingerprint unchanged")(updatedGuest.device_fingerprint)(guestCreation.device_fingerprint);
  TestValidator.equals("consent_status updated")(updatedGuest.consent_status)(newConsentStatus);
  TestValidator.notEquals("updated_at has changed")(updatedGuest.updated_at)(guestCreation.updated_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Verify that only admin users can update guest session records, by confirming that both unauthenticated and member (non-admin) users are denied permission.
 *
 * Business context:
 * Guest session records contain potentially sensitive data and regulatory consent fields. Update operations are restricted exclusively to admin roles. Any attempt by public or standard members must be rejected by the access control mechanism to uphold privacy policy.
 *
 * Test Steps:
 * 1. Create a guest session (unauthenticated, public user) to obtain a valid guestId
 * 2. Register a standard member account (with non-admin privileges) and log in as that member
 * 3. Attempt to update the guest record (as a public/unauthenticated session); expect a permission-denied error
 * 4. Attempt to update the guest record (using the member session); expect a permission-denied error
 * 5. Validate that both attempts are rejected, confirming only admin users can modify guest records.
 */
export async function test_api_guest_update_invalid_admin_permissions(connection: api.IConnection) {
  // 1. Create a guest session (public)
  const guestCreate = await api.functional.polEcoBoard.guests.create(connection, {
    body: {
      ip_address: "203.0.113.5",
      device_fingerprint: "fp-test-guest-invalid-admin",
      consent_status: "accepted"
    }
  });
  typia.assert(guestCreate);

  // 2. Register and log in as a non-admin member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: { email, password }
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: { email, password }
  });

  // 3. Attempt update as unauthenticated user (reset Authorization header if present)
  const nonAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete nonAuthConnection.headers["Authorization"];

  // Should be denied - unauthenticated
  await TestValidator.error("Non-authenticated user cannot update guest record")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.update(nonAuthConnection, {
        guestId: guestCreate.id,
        body: { consent_status: "denied" }
      });
    }
  );

  // 4. Attempt update as logged-in member (non-admin) -- should also be denied
  await TestValidator.error("Non-admin member cannot update guest record")(
    async () => {
      await api.functional.polEcoBoard.admin.guests.update(connection, {
        guestId: guestCreate.id,
        body: { device_fingerprint: "hackerAttempt" }
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
