/**
 * Test the ability of an admin to delete a guest session record in compliance with privacy and audit requirements.
 *
 * This test verifies that:
 * - Only an admin can delete a guest session record.
 * - The guest data is irretrievable after deletion (i.e. it cannot be fetched).
 * - The operation supports compliance by ensuring data is not recoverable post-removal.
 *
 * The workflow is as follows:
 * 1. Register a new admin user account.
 * 2. Log in as that admin to acquire authorization tokens.
 * 3. Create a guest session (public endpoint) and extract its guestId.
 * 4. As the admin, invoke the delete API using the guestId.
 * 5. Note: There is no provided API to fetch a guest session by id, so post-deletion retrieval is not possible to test directly.
 *
 * Log/audit checks are assumed to be implementation-level and not testable via API without additional endpoints.
 */
export async function test_api_guest_delete_valid_admin(
  connection: api.IConnection
) {
  // 1. Register a new admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin to get JWT session
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
