import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate permission controls for deletion of guest session records.
 *
 * Only administrators should be able to delete guest session records due to the private and sensitive nature of the data. This test ensures that non-admin users — specifically, authenticated members and unauthenticated (public) users — are forbidden from deleting guest sessions via the admin-only endpoint.
 *
 * Test Procedure:
 * 1. Create a new guest session (as unauthenticated user).
 * 2. Register a normal (non-admin) member account and log in as that member.
 * 3. As an authenticated member, attempt to delete the guest session via the admin endpoint. This should result in a forbidden/unauthorized error.
 * 4. Log out to become the public/unauthenticated session.
 * 5. As a public (unauthenticated) user, attempt to delete the guest session via the admin endpoint. Again, this action must fail with a forbidden/unauthorized error.
 *
 * At each step, the API response must be checked to confirm proper enforcement of access controls and that non-admin users never succeed in deletion attempts.
 */
export async function test_api_guest_delete_forbidden_nonadmin(connection: api.IConnection) {
  // 1. Create a new guest session (public)
  const guest = await api.functional.polEcoBoard.guests.create(connection, {
    body: {
      ip_address: '127.0.0.1',
      device_fingerprint: RandomGenerator.alphaNumeric(16),
      consent_status: RandomGenerator.alphabets(8),
    } satisfies IPolEcoBoardGuest.ICreate,
  });
  typia.assert(guest);

  // 2. Register a new member (non-admin)
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberPassword = typia.random<string & tags.Format<'password'>>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);

  // 3. Log in as the member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);

  // 4. As authenticated member, try to delete guest (should fail)
  await TestValidator.error(
    'non-admin member cannot delete guest via admin endpoint',
  )(async () => {
    await api.functional.polEcoBoard.admin.guests.erase(connection, {
      guestId: guest.id,
    });
  });

  // 5. Become public session (simulate logout by removing Authorization header)
  if (connection.headers) delete connection.headers['Authorization'];

  // 6. As public user, try to delete guest (should fail)
  await TestValidator.error(
    'unauthenticated user cannot delete guest via admin endpoint',
  )(async () => {
    await api.functional.polEcoBoard.admin.guests.erase(connection, {
      guestId: guest.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPageIPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate advanced member search with filters and pagination by an admin.
 *
 * This test ensures that the member search endpoint allows an administrator
 * to search for members using various filters and pagination options,
 * with correct result sets and security constraints. It proves member 
 * information is filtered and sorted per criteria, pagination works, and 
 * sensitive fields (like password hashes) are never present. It also confirms
 * a non-admin is denied access.
 *
 * Steps:
 * 1. Register a new admin account with a random business-valid email and a strong password (min length 8).
 * 2. Log in as the admin to set authentication context (store Authorization header in connection).
 * 3. Register multiple (N=6) member accounts using random emails and display names (using unique substrings for filtering), spaced with different creation intents (for date filtering test).
 * 4. As admin, search:
 *    (a) Without filters: all members, assert expected count >= members created, pagination structure is correct, and each member has allowed fields only (no credentials hashes, etc.)
 *    (b) By partial display_name: filter using a unique substring from one member, verify only that member is returned.
 *    (c) By registration date: filter for members created after a target date (using local test memory for created_at timestamps), verify date-based filtering.
 *    (d) By paging and sorting: query with low limit (e.g. 2), change sort_field and sort_direction, and verify correct ordering/chunk.
 * 5. As a regular member, attempt to perform search and confirm access is denied (catch error).
 */
export async function test_api_member_search_admin_role_filters_pagination(
  connection: api.IConnection,
) {
  // ------ Step 1 & 2: Admin registration and login ------
  const adminEmail = `${RandomGenerator.alphabets(8)}@company.com`;
  const adminPassword = RandomGenerator.alphaNumeric(12);

  // Register admin
  const adminSignUpOutput = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpOutput);

  // Log in as admin (to set Authorization header)
  const adminLoginOutput = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginOutput);

  // ------ Step 3: Register test member accounts ------
  type TestMember = { email: string; password: string; displayName: string; createdAt: string };
  const createdTestMembers: TestMember[] = [];
  const DISPLAY_NAME_PREFIX = RandomGenerator.alphabets(4);
  for (let i = 0; i < 6; ++i) {
    // Use deterministic display_name prefixes; create some for substring filter test
    const displayName = `${DISPLAY_NAME_PREFIX}_${RandomGenerator.alphabets(5)}_${i}`;
    const email = `${RandomGenerator.alphabets(9)}_${i}@testdomain.com`;
    const password = RandomGenerator.alphaNumeric(10 + i); // ensure valid/unique pw
    // Wait to space out created_at timestamps for date filtering
    await new Promise(res => setTimeout(res, 1100));
    const memberSignUpOutput = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password,
      } satisfies IMemberAuthenticationMemberSignUp,
    });
    typia.assert(memberSignUpOutput);
    // The actual created_at will only be available via subsequent search, so record local time
    createdTestMembers.push({ email, password, displayName, createdAt: new Date().toISOString() });
  }

  // ------ Step 4a: As admin, search all (no filters) ------
  const allMembersPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {} satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(allMembersPage);
  TestValidator.predicate("all test members present")(
    allMembersPage.data.filter(m => createdTestMembers.some(tm => m.email === tm.email)).length >= 6,
  );
  TestValidator.predicate("pagination structure")(
    typeof allMembersPage.pagination.current === "number" &&
    typeof allMembersPage.pagination.limit === "number" &&
    typeof allMembersPage.pagination.records === "number" &&
    typeof allMembersPage.pagination.pages === "number"
  );
  for (const member of allMembersPage.data) {
    // Confirm only allowed member fields are returned, no credentials etc.
    typia.assert(member);
    const forbiddenFields = ["password", "password_hash", "credential_hash"];
    for (const f of forbiddenFields)
      TestValidator.predicate(`field ${f} not present`)(!(f in member));
  }

  // ------ Step 4b: Filter by partial display_name ------
  // Use a unique substring from one test member's display name
  const testDisplayName = createdTestMembers[2].displayName;
  // Use the 2nd segment of the display name (after '_') as filter
  const displayNameSubstring = testDisplayName.split("_")[1].slice(0, 3);
  const displayNameFilteredPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      display_name: displayNameSubstring,
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(displayNameFilteredPage);
  // Results should include at least one test member with that substring
  TestValidator.predicate("display_name filter matches")(
    displayNameFilteredPage.data.some(m => m.display_name.includes(displayNameSubstring)),
  );

  // ------ Step 4c: Date filtering ------
  // Use a midpoint "created_at" from a local record
  const midIdx = Math.floor(createdTestMembers.length / 2);
  const fromDate = createdTestMembers[midIdx].createdAt;
  const dateFilteredPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      created_after: fromDate,
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(dateFilteredPage);
  TestValidator.predicate("date filter")(
    dateFilteredPage.data.every(m => Date.parse(m.created_at) >= Date.parse(fromDate)),
  );

  // ------ Step 4d: Paging and sorting ------
  const pageLimit = 2;
  const sortedAscPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      limit: pageLimit,
      sort_field: "created_at",
      sort_direction: "asc",
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(sortedAscPage);
  TestValidator.equals("page chunk matches limit")(sortedAscPage.data.length)(pageLimit);
  // For ascending, earliest created_at first
  const ascTimestamps = sortedAscPage.data.map(m => m.created_at);
  TestValidator.predicate("sorted ascending")(
    ascTimestamps.every((v, i, arr) => i === 0 || v >= arr[i - 1]),
  );

  // Descending sort
  const sortedDescPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      limit: pageLimit,
      sort_field: "created_at",
      sort_direction: "desc",
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(sortedDescPage);
  const descTimestamps = sortedDescPage.data.map(m => m.created_at);
  TestValidator.predicate("sorted descending")(
    descTimestamps.every((v, i, arr) => i === 0 || v <= arr[i - 1]),
  );

  // ------ Step 5: Access as non-admin (should fail) ------
  // Log in as one of the test members (simulate member session)
  const testMember = createdTestMembers[0];
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: testMember.email,
      password: testMember.password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  // Try member search as non-admin
  await TestValidator.error("member search forbidden for non-admin")(async () => {
    await api.functional.polEcoBoard.admin.members.search(connection, {
      body: {} satisfies IPolEcoBoardMember.IRequest,
    });
  });
}

