import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPageIPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate advanced post search and filtering via the moderator API, enforcing permission boundaries and result accuracy.
 *
 * This test covers registration and authentication flows for both moderator and standard member users, population of post data with varying authors and states (normal, flagged, soft-deleted), and ensures:
 * - The moderator can retrieve and filter posts by fields such as author, status, category, creation date, with correct pagination and result summary data.
 * - The moderator can see both flagged and soft-deleted posts in results when filtering for these states (not directly tested due to API limitations).
 * - Attempts by a regular member to access the moderator search endpoint fail with appropriate permission error (boundary enforcement).
 *
 * Steps:
 * 1. Register and authenticate a moderator
 * 2. Register and authenticate two members
 * 3. Each member creates posts with differing categories and contents
 * 4. As moderator, perform post searches with combinations of filters:
 *    - By author_member_id (should yield only that member's posts)
 *    - By category_id (should filter to posts of that category)
 *    - By creation date range (should respect min/max created_at boundaries)
 *    - By pagination (limit/page)
 *    - By ordering (order_by/order_dir)
 * 5. Validate correctness of search responses (summaries match filters/query as per business rules)
 * 6. As regular member, attempt to call the moderator search endpoint and validate unauthorized/forbidden error.
 */
export async function test_api_moderator_post_search_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphabets(12);
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    },
  });
  typia.assert(moderatorReg);
  TestValidator.equals("Moderator email")(moderatorReg.email)(moderatorEmail);

  // 2. Moderator login (establishes moderator session)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("Moderator login email")(moderatorLogin.email)(moderatorEmail);

  // 3. Register and authenticate two members
  const memberAccounts = await ArrayUtil.asyncRepeat(2)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const password = RandomGenerator.alphabets(14);
    const reg = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password,
      },
    });
    typia.assert(reg);
    // Authenticate and store for later use
    const login = await api.functional.auth.member.login.signIn(connection, {
      body: {
        email,
        password,
      },
    });
    typia.assert(login);
    return { email, password, login };
  });

  // 4. Each member creates at least two posts (different categories, different content)
  // Use random UUIDs for categories (no category create API)
  const categories = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const posts: IPolEcoBoardPost[] = [];
  for (const { email, password } of memberAccounts) {
    // Switch to member session
    await api.functional.auth.member.login.signIn(connection, {
      body: { email, password },
    });
    for (let j = 0; j < 2; ++j) {
      const categoryIdx = j % categories.length;
      const res = await api.functional.polEcoBoard.member.posts.create(connection, {
        body: {
          category_id: categories[categoryIdx],
          title: RandomGenerator.paragraph()(10),
          body: RandomGenerator.content()()(30),
          tag_ids: null,
          attachments: null,
        },
      });
      typia.assert(res);
      posts.push(res);
    }
  }

  // 5. As moderator, perform post searches with combinations of filters
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword },
  });

  // (A) Search by author_member_id (should retrieve only that author's posts)
  for (const post of posts) {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { author_member_id: post.author_member_id },
    });
    typia.assert(result);
    TestValidator.predicate("Only relevant member's posts")(
      result.data.every((s) => s.author_member_id === post.author_member_id),
    );
  }

  // (B) Search by category_id
  for (const category_id of categories) {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { category_id },
    });
    typia.assert(result);
    TestValidator.predicate("Only category's posts")(
      result.data.every((s) => s.category_id === category_id),
    );
  }

  // (C) By min_created_at/max_created_at using posts' timestamps
  const [minDate, maxDate] = [posts[0].created_at, posts[posts.length - 1].created_at];
  {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { min_created_at: minDate, max_created_at: maxDate },
    });
    typia.assert(result);
    TestValidator.predicate("Date filter - all in range")(
      result.data.every(
        (s) => s.created_at >= minDate && s.created_at <= maxDate,
      ),
    );
  }

  // (D) Pagination - limit/page
  {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { limit: 1, page: 1 },
    });
    typia.assert(result);
    TestValidator.equals("Should be one per page")(result.data.length)(1);
  }

  // (E) Ordering - order_by/order_dir
  {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { order_by: "created_at", order_dir: "desc" },
    });
    typia.assert(result);
    const sorted = [...result.data].sort((a, b) => (a.created_at < b.created_at ? 1 : -1));
    TestValidator.equals("Ordering descending")(result.data.map((s) => s.id))(sorted.map((s) => s.id));
  }

  // 6. Permissions: regular member attempts moderator search (should fail)
  // Use first member
  const { email: memberEmail, password: memberPassword } = memberAccounts[0];
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword },
  });
  await TestValidator.error("Member forbidden for moderator endpoint")(async () => {
    await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: {},
    });
  });
}

