  // At this point, connection.headers.Authorization is set to token by SDK

  // 2. Create two fake categories—since there is no endpoint, just generate UUIDs for category_id
  const categoryIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
