  const tagIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // Create four posts, with varying category, title/body/keywords, tags, flagged etc
  const posts: IPolEcoBoardPost[] = [];
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[0],
      title: "Climate Policy Overview", // contains 'climate'
      body: "This post discusses new global climate policy initiatives.", // contains 'climate'
      tag_ids: [tagIds[0]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[1],
      title: "Economic Recovery Plan", // contains 'economy'
      body: "Stimulus and economic reform discussion.", // contains 'economy'
      tag_ids: [tagIds[1]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[0],
      title: "Flagged: Unusual Activity", // keyword 'flagged', flagged should be set (simulate)
      body: "Moderator has flagged this post for unusual content.",
      tag_ids: [tagIds[0]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[1],
      title: "Deleted: Obsolete Discussion", // keyword 'deleted', will simulate deleted by reading property after creation
      body: "This thread has been deleted by admin.",
      tag_ids: [tagIds[1]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));

  for (const post of posts) typia.assert(post);

  // 3. Filtering by category_id should only return posts from that category
  const resCategory = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { category_id: categoryIds[0] } satisfies IPolEcoBoardPost.IRequest
  });
