  // 4. Filtering by tag_ids should only return posts with the tag(s)
  const resTag = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { tag_ids: [tagIds[0]] } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resTag);
  // Can't directly check tag match because summary doesn't include tags - at minimum, assert success
  TestValidator.predicate("admin tag search returns summary result")(
    Array.isArray(resTag.data)
  );

  // 5. Filtering by keyword (search in title/body)
  const resKeyword = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { search: "climate" } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resKeyword);
  TestValidator.predicate("admin keyword search returns at least one expected post")(
    resKeyword.data.some((p) => p.title.includes("climate"))
