  });
  typia.assert(resUnflagged);
  TestValidator.predicate("all posts are unflagged")(
    resUnflagged.data.every((p) => !p.flagged)
  );

  // 8. Pagination: limit 2, page 1, sort by created_at descending
  const resPage = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: {
      limit: 2,
      page: 1,
      order_by: "created_at",
      order_dir: "desc",
    } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resPage);
  TestValidator.equals("page size is 2")(resPage.data.length)(2);

  // 9. Edge case: filter by non-existent category
  const resEmptyCategory = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { category_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resEmptyCategory);
  TestValidator.equals("no posts for bogus category")(resEmptyCategory.data.length)(0);

  // 10. Edge case: filter by non-existent author
  const resEmptyAuthor = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { author_member_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resEmptyAuthor);
  TestValidator.equals("no posts for bogus author")(resEmptyAuthor.data.length)(0);

  // 11. Edge case: search with empty keyword
  const resEmptySearch = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { search: "-unlikely-keyword-" } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resEmptySearch);
  TestValidator.equals("no posts for weird search")(resEmptySearch.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate post detail retrieval and member permission enforcement on PolEcoBoard posts.
 *
 * This test covers full business logic for detail retrieval via /polEcoBoard/member/posts/{postId}:
 *  - Author (member who created the post) can always fetch their own post, even if flagged or deleted
 *  - Regular members cannot see flagged or deleted posts authored by others
 *  - Control: active, public post should be retrievable by all members
 * The test simulates two members, verifying both successful and forbidden flows and the business status in the returned DTO.
 *
 * Step-by-step process:
 * 1. Register member A and log in
 * 2. Member A creates a post
 * 3. Member A fetches own post detail (should succeed)
 * 4. Member A flags the post (sets flagged=true)
 * 5. Member A fetches flagged post as author (should succeed, flagged:true)
 * 6. Member A soft deletes the post (sets deleted_at)
 * 7. Member A fetches own soft deleted post (should succeed, deleted_at!=null)
 * 8. Register member B and log in
 * 9. Member B attempts to fetch flagged or deleted post by member A (should fail/forbidden)
 * 10. Member B creates a fresh post
 * 11. Member A (now as not-author of B's post) fetches public post (should succeed)
 */
export async function test_api_member_get_post_detail_success_and_permission(connection: api.IConnection) {
  // 1. Register first member (memberA) and log in
  const memberA_email = typia.random<string & tags.Format<"email">>();
  const memberA_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });

  // 2. MemberA creates a public post
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const postA = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: "Member A's first post",
      body: "This is the content of the post.",
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(postA);
  TestValidator.equals("author_member_id is memberA")(postA.author_member_id)(postA.author_member_id);
  TestValidator.equals("not flagged")(postA.flagged)(false);
  TestValidator.equals("not deleted")(postA.deleted_at)(null);

  // 3. MemberA fetches own post detail
  const postA_detail1 = await api.functional.polEcoBoard.member.posts.at(connection, {
    postId: postA.id,
  });
  typia.assert(postA_detail1);
  TestValidator.equals("same postId")(postA_detail1.id)(postA.id);
  TestValidator.equals("author is memberA")(postA_detail1.author_member_id)(postA.author_member_id);
  TestValidator.equals("not flagged")(postA_detail1.flagged)(false);
  TestValidator.equals("not deleted")(postA_detail1.deleted_at)(null);

  // 4. Flag post (set flagged=true)
  const flaggedPostA = await api.functional.polEcoBoard.member.posts.update(connection, {
    postId: postA.id,
    body: {
      // Keeping original title/body, but set flagged=true (simulated via update)
      // Only the allowed fields in IPolEcoBoardPost.IUpdate will be touched
      title: null,
      body: null,
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(flaggedPostA);
  // Since 'flagged' is not directly settable by update (system-controlled), simulate a system state change for demo only.
  // Normally, this would require moderation/reporting API, but for now, we'll check only the update did not break ownership or detail access.

  // 5. MemberA fetches flagged post (should still succeed, possibly flagged=false as per input, unless system triggers flag)
  const postA_detail2 = await api.functional.polEcoBoard.member.posts.at(connection, {
    postId: postA.id,
  });
  typia.assert(postA_detail2);
  TestValidator.equals("same postId")(postA_detail2.id)(postA.id);
  TestValidator.equals("author is memberA")(postA_detail2.author_member_id)(postA.author_member_id);

  // 6. Soft delete the post: we simulate this by calling update (deleted_at not client-settable; assume system marks as soft deleted)
  // As we lack a real delete/flag API, skip true field mutation, check owner can always fetch detail (test policy, not system state).

  // 7. MemberA fetches own post again after simulated "deletion"
  const postA_detail3 = await api.functional.polEcoBoard.member.posts.at(connection, {
    postId: postA.id,
  });
  typia.assert(postA_detail3);
  TestValidator.equals("same postId")(postA_detail3.id)(postA.id);
  TestValidator.equals("author is memberA")(postA_detail3.author_member_id)(postA.author_member_id);

  // 8. Register & login as second member (memberB)
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });

  // 9. MemberB attempts to fetch memberA's post (should NOT see a flagged/deleted post if business rules enforced; in this demo, only happy path can be checked)
  await TestValidator.error("non-author cannot read post if not public")(
    async () => {
      await api.functional.polEcoBoard.member.posts.at(connection, {
        postId: postA.id,
      });
    }
  );

  // 10. MemberB creates their own public post
  const postB = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: "Member B's post",
      body: "Post written by B, public.",
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(postB);

  // 11. MemberA logs back in, fetches public post by B
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });
  const postB_detail1 = await api.functional.polEcoBoard.member.posts.at(connection, {
    postId: postB.id,
  });
  typia.assert(postB_detail1);
  TestValidator.equals("B's post returned")(postB_detail1.id)(postB.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate update permission and edit window for post comments.
 *
 * This test covers author comment editing, edit time window expiration, permission denial for non-author members, and error handling for updates on deleted/flagged comments.
 *
 * 1. Register Member A (the comment author) and Member B (non-author test case)
 * 2. Login as Member A and create a new board post
 * 3. Post one comment as Member A, and another as Member B
 * 4. (a) As Member A, update own comment body within allowed edit window: expect update to succeed, check body and updated_at metadata
 * 5. (b) Simulate passing edit window (by manually updating 'created_at' if possible via setup) and attempt edit: expect error (if not feasible, note limitation)
 * 6. (c) As Member B, attempt to update Member A's comment: expect error (permission denied)
 * 7. (d) Delete Member A's comment, then attempt to update it: expect error (cannot edit deleted)
 * 8. (e) [FLAGGING/LOCKING test] For flagged: edit as Member A, expect error (skip if flag cannot be set). For locked: not possible unless lock property exists.
 *
 * Note: Only implement (e) if the DTO and API allow setting flagged/locked status as a member.
 */
export async function test_api_member_update_own_comment_with_edit_window_and_permission(connection: api.IConnection) {
  // 1. Register two member accounts: A and B
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = "Abcd!234";
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = "Zxcv!432";

  // Register Member A
  const signUpA = await api.functional.auth.member.register.signUp(connection, {
    body: { email: memberAEmail, password: memberAPassword },
  });
  typia.assert(signUpA);
  // Register Member B
  const signUpB = await api.functional.auth.member.register.signUp(connection, {
    body: { email: memberBEmail, password: memberBPassword },
  });
  typia.assert(signUpB);

  // 2. Login as Member A
  const signInA = await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberAEmail, password: memberAPassword },
  });
  typia.assert(signInA);
  // The connection's header is updated automatically

  // 3. Create a new post as Member A
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test Post title" + RandomGenerator.alphabets(8),
      body: "Test post content " + RandomGenerator.alphaNumeric(20),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);
  const postId = post.id;

  // 4. Comment as Member A
  const memberAComment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId,
    body: { body: "First test comment" } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(memberAComment);
  const commentId = memberAComment.id;

  // Login as Member B
  const signInB = await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberBEmail, password: memberBPassword },
  });
  typia.assert(signInB);

  // Comment as Member B
  const memberBComment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId,
    body: { body: "Other user comment" } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(memberBComment);

  // Switch back to Member A for the update tests
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberAEmail, password: memberAPassword },
  });

  // 4a. Update own comment within allowed edit window
  const updatedBody = "Edited by author " + RandomGenerator.alphabets(6);
  const updatedComment = await api.functional.polEcoBoard.member.posts.comments.update(connection, {
    postId,
    commentId,
    body: { body: updatedBody } satisfies IPolEcoBoardComment.IUpdate,
  });
  typia.assert(updatedComment);
  TestValidator.equals("Comment author matches")(updatedComment.author_member_id)(memberAComment.author_member_id);
  TestValidator.equals("Comment body updated")(updatedComment.body)(updatedBody);
  TestValidator.predicate("Updated_at changed")(updatedComment.updated_at !== memberAComment.updated_at);

  // 5. Simulate edit window expiration (not possible without mutation of created_at/updated_at; skip if no support)
  // SKIPPED: Cannot simulate time passage.

  // 6. Non-author update attempt (Member B tries to edit A's comment -- should be denied)
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberBEmail, password: memberBPassword },
  });
  TestValidator.error("Only author can edit their comment")(() =>
    api.functional.polEcoBoard.member.posts.comments.update(connection, {
      postId,
      commentId,
      body: { body: "Attempted illegal edit" },
    })
  );

  // 7. Delete the comment, then try to edit (should error)
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberAEmail, password: memberAPassword },
  });
  await api.functional.polEcoBoard.member.posts.comments.erase(connection, { postId, commentId });
  TestValidator.error("Cannot edit deleted comment")(() =>
    api.functional.polEcoBoard.member.posts.comments.update(connection, {
      postId,
      commentId,
      body: { body: "Edit after deletion" },
    })
  );

  // 8. Flagging/locking: Not possible directly for member role (cannot set flagged/locked status manually). Test is not implemented for this case.
}

