import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can update (edit) comments regardless of authorship, time limit, or comment restrictions such as flagged or deleted status.
 *
 * Business context: On the PolEcoBoard, moderators can override standard member edit limitations (e.g., only author within edit window).
 * This test ensures moderator edit privileges, proper update on flagged or deleted comments, and verifies that business and audit rules are enforced.
 * Failure modes (invalid IDs, disabled moderator, etc.) are included.
 *
 * Steps:
 * 1. Register a new moderator and login as moderator to obtain JWT.
 * 2. Create a post as a member (auth context is member).
 * 3. Add a comment as member to the post.
 * 4. As moderator, update the comment's body successfully (overriding edit window or author-only restrictions).
 * 5. Soft-delete the comment as member to simulate a "deleted" state.
 * 6. As moderator, update the previously deleted comment body and verify success (moderator can override deleted restriction).
 * 7. (Edge) As moderator, attempt to update a comment for a non-existent post → expect failure.
 * 8. (Edge) As moderator, attempt edit with a wrong commentId → expect failure.
 * 9. (Edge) Simulate disabled moderator by altering the JWT, attempt to edit → expect failure.
 * Business/audit verification is limited by available APIs; actual audit trail validation skipped if not directly accessible.
 */
export async function test_api_moderator_update_comment_override_edit_window_and_flagged(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "SecureTestPassword123!";
  const displayName = RandomGenerator.name();
  const consent = "v1-policy";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);
  // Set moderator's JWT to connection
  connection.headers = { ...(connection.headers || {}), ...moderatorReg.setHeaders };

  // 2. Moderator logs in again to verify login works
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResp);
  connection.headers = { ...(connection.headers || {}), ...loginResp.setHeaders };

  // 3. Create a post as member (simulate member context by clearing/modifying JWT)
  connection.headers = {}; // Remove Authorization for member action
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(10),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Add a comment as member
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "Original comment for moderation test.",
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. As moderator, update the comment body (override normal restrictions)
  connection.headers = { ...loginResp.setHeaders };
  const updatedComment = await api.functional.polEcoBoard.moderator.posts.comments.update(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      body: "[MODERATED] Updated by moderator.",
    } satisfies IPolEcoBoardComment.IUpdate,
  });
  typia.assert(updatedComment);
  TestValidator.equals("updated comment body")(updatedComment.body)("[MODERATED] Updated by moderator.");

  // 6. As member, soft-delete the comment to set deleted_at
  connection.headers = {}; // back to member (unauth/auth as member if required)
  const erasedComment = await api.functional.polEcoBoard.member.posts.comments.erase(connection, {
    postId: post.id,
    commentId: comment.id,
  });
  typia.assert(erasedComment);
  TestValidator.predicate("deleted_at is set")(
    typeof erasedComment.deleted_at === "string" && !!erasedComment.deleted_at
  );

  // 7. As moderator, update the deleted comment body (should succeed)
  connection.headers = { ...loginResp.setHeaders };
  const moderatedAfterDelete = await api.functional.polEcoBoard.moderator.posts.comments.update(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      body: "[MODERATED] Edited after deletion.",
    } satisfies IPolEcoBoardComment.IUpdate,
  });
  typia.assert(moderatedAfterDelete);
  TestValidator.equals("body updated post-deletion")(moderatedAfterDelete.body)("[MODERATED] Edited after deletion.");
  TestValidator.predicate("deleted_at preserved")(
    typeof moderatedAfterDelete.deleted_at === "string" && !!moderatedAfterDelete.deleted_at
  );

  // 8. Failure: Non-existent post
  const fakePostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("edit comment on non-existent post")(() =>
    api.functional.polEcoBoard.moderator.posts.comments.update(connection, {
      postId: fakePostId,
      commentId: comment.id,
      body: { body: "Should Fail" },
    }),
  );

  // 9. Failure: Wrong (non-existent) commentId
  const fakeCommentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("edit with wrong commentId")(() =>
    api.functional.polEcoBoard.moderator.posts.comments.update(connection, {
      postId: post.id,
      commentId: fakeCommentId,
      body: { body: "Should Fail" },
    }),
  );

  // 10. Simulate disabled moderator by setting bad JWT
  const invalidConn = { ...connection, headers: { Authorization: "Bearer invalid.jwt.token" } };
  await TestValidator.error("edit as disabled moderator")(() =>
    api.functional.polEcoBoard.moderator.posts.comments.update(invalidConn, {
      postId: post.id,
      commentId: comment.id,
      body: { body: "Should fail for disabled moderator" },
    }),
  );
}

