import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IPageIPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate retrieval of votes for a post with filtering and pagination
 *
 * This test verifies that a member can search through votes on a post, with support for
 * sophisticated filters (vote_value, voter_member_id, date ranges), and that the API returns correct pagination and analytics.
 *
 * Steps:
 * 1. Register the first member (member1)
 * 2. Login as member1
 * 3. Create a new post as member1
 * 4. Cast an upvote as member1 on their own post
 * 5. Register a second member (member2)
 * 6. Login as member2
 * 7. Cast a downvote as member2 on the same post
 * 8. Search votes for the post filtered by vote_value=1 (upvotes), expect only member1
 * 9. Search votes for the post filtered by vote_value=-1 (downvotes), expect only member2
 * 10. Search all votes for the post and verify both votes appear, and pagination/result metadata are valid
 * 11. Search votes filtered by voter_member_id=member2.id, expect only member2's vote
 * 12. Search votes with a date range covering only the first vote, expect only member1
 */
export async function test_api_member_post_vote_search_success(connection: api.IConnection) {
  // 1. Register the first member (member1)
  const email1 = typia.random<string & tags.Format<"email">>();
  const pw1 = "password1";
  const member1 = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: email1,
      password_hash: pw1,
      display_name: RandomGenerator.name(),
      profile_image_uri: null,
      consent_status: "v1"
    }
  });
  typia.assert(member1);

  // 2. Login as member1
  const login1 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: email1,
      password: pw1
    }
  });
  typia.assert(login1);

  // 3. Create a new post as member1
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(20),
      tag_ids: null,
      attachments: null
    }
  });
  typia.assert(post);

  // 4. Cast an upvote as member1 on their own post
  const vote1 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 }
  });
  typia.assert(vote1);

  // 5. Register a second member (member2)
  const email2 = typia.random<string & tags.Format<"email">>();
  const pw2 = "password2";
  const member2 = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: email2,
      password_hash: pw2,
      display_name: RandomGenerator.name(),
      profile_image_uri: null,
      consent_status: "v1"
    }
  });
  typia.assert(member2);

  // 6. Login as member2
  const login2 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: email2,
      password: pw2
    }
  });
  typia.assert(login2);

  // 7. Cast a downvote as member2 on the same post
  const vote2 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: -1 }
  });
  typia.assert(vote2);

  // 8. Search votes: filter vote_value = 1 (upvotes)
  const upvotePage = await api.functional.polEcoBoard.member.posts.votes.search(connection, {
    postId: post.id,
    body: { vote_value: 1 }
  });
  typia.assert(upvotePage);
  TestValidator.equals("find only one upvote")(upvotePage.data.length)(1);
  TestValidator.equals("upvoter is member1")(upvotePage.data[0].voter_member_id)(member1.id);
  TestValidator.equals("vote value is 1")(upvotePage.data[0].vote_value)(1);

  // 9. Search votes: filter vote_value = -1 (downvotes)
  const downvotePage = await api.functional.polEcoBoard.member.posts.votes.search(connection, {
    postId: post.id,
    body: { vote_value: -1 }
  });
  typia.assert(downvotePage);
  TestValidator.equals("find only one downvote")(downvotePage.data.length)(1);
  TestValidator.equals("downvoter is member2")(downvotePage.data[0].voter_member_id)(member2.id);
  TestValidator.equals("vote value is -1")(downvotePage.data[0].vote_value)(-1);

  // 10. Search all votes for the post
  const allVotesPage = await api.functional.polEcoBoard.member.posts.votes.search(connection, {
    postId: post.id,
    body: { }
  });
  typia.assert(allVotesPage);
  TestValidator.equals("find two votes")(allVotesPage.data.length)(2);
  // Pagination data
  TestValidator.equals("pagination current")(allVotesPage.pagination.current)(1);
  TestValidator.predicate("pagination records >= 2")(allVotesPage.pagination.records >= 2);
  // Both vote values present
  const values = allVotesPage.data.map(v => v.vote_value).sort();
  TestValidator.equals("has -1 and 1")(values)([-1, 1]);

  // 11. Search votes filtered by voter_member_id=member2.id
  const member2VotePage = await api.functional.polEcoBoard.member.posts.votes.search(connection, {
    postId: post.id,
    body: { voter_member_id: member2.id }
  });
  typia.assert(member2VotePage);
  TestValidator.equals("find only one member2 vote")(member2VotePage.data.length)(1);
  TestValidator.equals("member2 vote record")(member2VotePage.data[0].voter_member_id)(member2.id);

  // 12. Search votes with date range covering only the first vote
  const after = new Date(Date.parse(vote1.created_at) - 5 * 1000).toISOString();
  const before = new Date(Date.parse(vote1.created_at) + 5 * 1000).toISOString();
  const rangeVotePage = await api.functional.polEcoBoard.member.posts.votes.search(connection, {
    postId: post.id,
    body: { created_after: after, created_before: before }
  });
  typia.assert(rangeVotePage);
  TestValidator.equals("find only vote1 in date range")(rangeVotePage.data.length)(1);
  TestValidator.equals("vote is from member1")(rangeVotePage.data[0].voter_member_id)(member1.id);
}

