  TestValidator.equals("pagination current page")(voteSearchResult.pagination.current)(1);
  TestValidator.equals("pagination limit (default 100)")(voteSearchResult.pagination.limit)(100);
  TestValidator.equals("pagination total pages")(voteSearchResult.pagination.pages)(0);
