import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can search and access all votes cast on a post, including those by other members.
 *
 * This test covers a full business workflow:
 * 1. Register a moderator and login for privileged access.
 * 2. Register a first member. Login as the member and create a post in a random category.
 * 3. The first member casts a vote (upvote or downvote) on their own post.
 * 4. Register a second member. Login as the second member. The second member casts a different vote (opposite value) on the same post.
 * 5. Login as the moderator. Use the moderator PATCH votes endpoint to:
 *    a. Retrieve all votes on the post (no filtering) - should see both votes.
 *    b. Filter by voter_member_id of the first member - only that member's vote should appear.
 *    c. Filter by vote_value=1 and vote_value=-1 - should return the respective matching vote(s).
 *
 * Steps:
 * 1. Moderator registration (consent status random string, display name random).
 * 2. Moderator login.
 * 3. Member1 registration and login (generate unique email/password/display_name, consent status, profile image optional).
 * 4. Member1 creates a post (generate title, body, category_id, attachments/tags optional).
 * 5. Member1 votes on own post (vote_value=1).
 * 6. Member2 registration and login.
 * 7. Member2 votes on the same post (vote_value=-1).
 * 8. Moderator searches all votes for the post with various filters, asserting full access and correct filtering.
 */
export async function test_api_moderator_post_vote_search_all_access(connection: api.IConnection) {
  // 1. Register moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "StrongP@ssword1!";
  const modDisplay = RandomGenerator.name();
  const modConsent = RandomGenerator.alphaNumeric(8);

  const regMod = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplay,
      consent_status: modConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(regMod);

  // 2. Login as moderator (token will be loaded into connection)
  const loginMod = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginMod);

  // 3. Register first member
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1PasswordRaw = "AlphaP@ss1234";
  const member1 = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member1Email,
      password_hash: member1PasswordRaw,
      display_name: RandomGenerator.name(),
      consent_status: RandomGenerator.alphaNumeric(8),
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member1);

  // 4. Login as member1
  const loginMember1 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member1Email,
      password: member1PasswordRaw,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(loginMember1);

  // 5. Member1 creates a new post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.paragraph()(25),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Member1 casts a vote on own post
  const vote1 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote1);

  // 7. Register second member
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2PasswordRaw = "BetaP@ss4321";
  const member2 = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member2Email,
      password_hash: member2PasswordRaw,
      display_name: RandomGenerator.name(),
      consent_status: RandomGenerator.alphaNumeric(8),
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member2);

  // 8. Login as member2
  const loginMember2 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2PasswordRaw,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(loginMember2);

  // 9. Member2 votes on same post
  const vote2 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: -1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote2);

  // 10. Re-login as moderator for search
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 11. Moderator queries all votes on the post
  const allVotesResp = await api.functional.polEcoBoard.moderator.posts.votes.search(connection, {
    postId: post.id,
    body: {}, // No filters
  });
  typia.assert(allVotesResp);
  const votesAll = allVotesResp.data;
  TestValidator.equals("vote count, all votes")(votesAll.length)(2);
  const voterIds = votesAll.map((v) => v.voter_member_id);
  TestValidator.predicate("vote contains member1")(voterIds.includes(member1.id));
  TestValidator.predicate("vote contains member2")(voterIds.includes(member2.id));

  // 12a. Moderator filters by member1
  const byMember1Resp = await api.functional.polEcoBoard.moderator.posts.votes.search(connection, {
    postId: post.id,
    body: { voter_member_id: member1.id },
  });
  typia.assert(byMember1Resp);
  TestValidator.equals("vote count, by member1")(byMember1Resp.data.length)(1);
  TestValidator.equals("vote by member1 id")(byMember1Resp.data[0].voter_member_id)(member1.id);

  // 12b. Moderator filters by vote_value 1
  const upvoteResp = await api.functional.polEcoBoard.moderator.posts.votes.search(connection, {
    postId: post.id,
    body: { vote_value: 1 },
  });
  typia.assert(upvoteResp);
  TestValidator.equals("vote count, upvote")(upvoteResp.data.length)(1);
  TestValidator.equals("upvote vote_value")(upvoteResp.data[0].vote_value)(1);
  TestValidator.equals("upvote voter id")(upvoteResp.data[0].voter_member_id)(member1.id);

  // 12c. Moderator filters by vote_value -1 (downvote)
  const downvoteResp = await api.functional.polEcoBoard.moderator.posts.votes.search(connection, {
    postId: post.id,
    body: { vote_value: -1 },
  });
  typia.assert(downvoteResp);
  TestValidator.equals("vote count, downvote")(downvoteResp.data.length)(1);
  TestValidator.equals("downvote vote_value")(downvoteResp.data[0].vote_value)(-1);
  TestValidator.equals("downvote voter id")(downvoteResp.data[0].voter_member_id)(member2.id);
}

