import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate error handling for deleting a non-existent attachment as a moderator.
 *
 * Business context: Moderators have elevated permissions to manage post attachments, but mistaken or malicious actions (such as referencing invalid or non-existent attachmentId values for a given post) should be gracefully handled. The API must ensure correct error reporting and prevent side effects (no attachments removed).
 *
 * Steps:
 * 1. Register a new moderator via the registration API (valid random credentials, acceptance of consent).
 * 2. Log in as the same moderator to establish permissioned session (ensure Authorization token is set).
 * 3. Attempt to delete a file attachment from a (theoretical) post using random UUIDs for both postId and attachmentId that are extremely unlikely to exist (since test infra doesn't allow creating posts/attachments here).
 * 4. Verify that a not-found or business error is thrown by the API (TestValidator.error), indicating the resource does not exist, and check that the error is indeed thrown.
 * 5. As an added assurance, attempt the same request again and confirm the same error is thrown.
 *
 * No post or attachment creation functions are available in this API surface, so only error validation is possible in this scope.
 */
export async function test_api_moderator_post_attachment_delete_nonexistent(connection: api.IConnection) {
  // Step 1: Register a new moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "TestPassword!234";
  const moderatorDisplayName: string = RandomGenerator.name();
  const consentStatus: string = "v1-2024-policy-accepted";
  const registerResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus
    }
  });
  typia.assert(registerResponse);

  // Step 2: Log in as moderator
  const loginResponse = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword }
  });
  typia.assert(loginResponse);

  // Step 3: Attempt to delete a non-existent attachment
  const randomPostId: string = typia.random<string & tags.Format<"uuid">>();
  const randomAttachmentId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Should fail: deleting nonexistent attachment")(
    () => api.functional.polEcoBoard.moderator.posts.attachments.erase(connection, {
      postId: randomPostId,
      attachmentId: randomAttachmentId
    })
  );

  // Step 4: Repeat for consistency
  await TestValidator.error("Should consistently fail: retry deleting same nonexistent attachment")(
    () => api.functional.polEcoBoard.moderator.posts.attachments.erase(connection, {
      postId: randomPostId,
      attachmentId: randomAttachmentId
    })
  );
}

