  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // In this context, schema treats plain or pre-hashed as needed by platform
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: "granted",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Member login to obtain auth/session for authoring actions
  const memberLoginResponse = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
