import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for admin comment update: ensures admins can update any user's comment, edit is audited, and data is consistent.
 *
 * Business context:
 *   - Only privileged users (admins) can edit others' comments.
 *   - This test ensures admins can update any member's comment, edit is visible, and audit record is present (through updated_at).
 *
 * Test Steps:
 * 1. Register a new member and login, capturing JWT for authenticated actions.
 * 2. Member creates a post in a board category.
 * 3. Member posts a comment on the post.
 * 4. Register an admin user and login as admin (JWT in connection).
 * 5. Admin updates the member's comment with new body text.
 * 6. Verify the update: id and post_id remain unchanged, body reflects update, updated_at is advanced, ensuring audit trail integrity.
 */
export async function test_api_comment_admin_update_valid_data(
  connection: api.IConnection,
) {
  // 1. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const signUpMember = await api.functional.auth.member.register.signUp(
    connection,
    {
      body: {
        email: memberEmail,
        password: memberPassword,
      } satisfies IMemberAuthenticationMemberSignUp,
    },
  );
  typia.assert(signUpMember);
  // Use member's token for subsequent actions
  const memberAuth = signUpMember.setHeaders.Authorization;
  connection.headers = {
    ...connection.headers,
    Authorization: memberAuth,
  };

  // 2. Member creates post
  const post = await api.functional.polEcoBoard.member.posts.create(
    connection,
    {
      body: {
        category_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.paragraph()(10),
        body: RandomGenerator.paragraph()(30),
      } satisfies IPolEcoBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 3. Member adds comment to post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(
    connection,
    {
      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(5),
      } satisfies IPolEcoBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 4. Register admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpAdmin = await api.functional.auth.admin.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignUp,
    },
  );
  typia.assert(signUpAdmin);

  // 5. Login as admin
  const loginAdmin = await api.functional.auth.admin.login.signIn(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignIn,
    },
  );
  typia.assert(loginAdmin);
  const adminAuth = loginAdmin.setHeaders.Authorization;
  connection.headers = {
    ...connection.headers,
    Authorization: adminAuth,
  };

  // 6. Update member's comment as admin
  const updatedBody = RandomGenerator.paragraph()(7);
  const updatedComment = await api.functional.polEcoBoard.admin.posts.comments.update(
    connection,
    {
      postId: post.id,
      commentId: comment.id,
      body: {
        body: updatedBody,
      } satisfies IPolEcoBoardComment.IUpdate,
    },
  );
  typia.assert(updatedComment);

  // 7. Validate update
  TestValidator.equals("comment id unchanged")(updatedComment.id)(comment.id);
  TestValidator.equals("post id unchanged")(updatedComment.post_id)(comment.post_id);
  TestValidator.equals("body updated")(updatedComment.body)(updatedBody);
  TestValidator.notEquals("updated_at changed")(updatedComment.updated_at)(comment.updated_at);
}

