 */
export async function test_api_comment_edit_admin_update_forbidden_field(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(14);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  connection.headers = { ...connection.headers, Authorization: adminSignIn.setHeaders.Authorization };

  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRes);

  // 4. Switch to member auth and create a post
  connection.headers = { ...connection.headers, Authorization: memberRes.setHeaders.Authorization };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.content()(30)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Create a comment to the post as member
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()(10)(),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 6. Switch back to admin and create a comment edit record
  connection.headers = { ...connection.headers, Authorization: adminSignIn.setHeaders.Authorization };
  const commentEdit = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.create(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      edit_body: RandomGenerator.content()(15)(),
      edit_reason: RandomGenerator.paragraph()(2),
    } satisfies IPolEcoBoardCommentEdit.ICreate,
  });
  typia.assert(commentEdit);

  // 7. Attempt forbidden/malformed update (not possible to send forbidden fields, but simulate empty update, which is not allowed)
  await TestValidator.error("Empty/faulty update body should be rejected")(() =>
    api.functional.polEcoBoard.admin.posts.comments.commentEdits.update(connection, {
      postId: post.id,
      commentId: comment.id,
      commentEditId: commentEdit.id,
      body: {}, // Should be rejected – nothing to update, forbidden in business rules
    })
  );

  // 8. Attempt valid update with allowed field only
  const updated = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.update(connection, {
    postId: post.id,
    commentId: comment.id,
    commentEditId: commentEdit.id,
    body: {
      edit_reason: RandomGenerator.paragraph()(3),
    } satisfies IPolEcoBoardCommentEdit.IUpdate,
  });
  typia.assert(updated);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCommentEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * E2E test for soft deletion of a comment edit by a moderator (polEcoBoard domain).
 *
 * Validates end-to-end that a moderator can soft delete a comment edit record.
 * Business context: This ensures privileged users (moderators) can effectively redact or hide previous edits in compliance/audit scenarios, while ensuring auditability (if API allows).
 *
 * Step-by-step:
 * 1. Register a member (for authorship of the post/comment/edit)
 * 2. Register a moderator account (with required consent/display_name)
 * 3. Moderator logs in (privilege JWT retrieval)
 * 4. Switch authentication context to member and create a post
 * 5. Add a comment under that post
 * 6. Switch back to moderator role
 * 7. Create a manual comment edit record (as moderator)
 * 8. Soft delete the comment edit (as moderator)
 * 9. Validate the returned comment edit record
 *
 * Limitations:
 * - The IPolEcoBoardCommentEdit DTO does not include a deleted_at property or soft-delete marker. It is not possible to directly validate the deletion flag. This step is skipped as per the implementation feasibility guideline.
 * - Revision history retrieval/exclusion cannot be validated due to missing API. Only successful flow and type validity is checked.
 */
export async function test_api_comment_edit_moderator_soft_delete(connection: api.IConnection) {
  // 1. Register a member who will author the post/comment/edit
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = typia.random<string & tags.Format<"password">>();
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberSignUp);

  // 2. Register a moderator (separate account)
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = RandomGenerator.alphaNumeric(16);
  const moderatorDisplayName: string = RandomGenerator.name();
  const moderatorConsent: string = "accepted-v1";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    },
  });
  typia.assert(moderatorSignUp);

  // 3. Moderator login to get JWT for privileged actions
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  connection.headers = { ...(connection.headers ?? {}), ...moderatorLogin.setHeaders };

  // 4. Switch to member authentication to create post/comment
  // (Simulate login/authorization acquisition for business context.)
  // If actual login endpoint existed for member, would use here; reuse previous JWT for subsequent steps.
  connection.headers = { ...(connection.headers ?? {}), ...memberSignUp.setHeaders };

  // 5. Member creates a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(20),
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(post);

  // 6. Member adds a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()()(10),
      parent_comment_id: null,
    },
  });
  typia.assert(comment);

  // 7. Switch back to moderator to perform edit creation and deletion
  connection.headers = { ...(connection.headers ?? {}), ...moderatorLogin.setHeaders };

  // 8. Moderator creates a comment edit record
  const commentEdit = await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.create(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      edit_body: RandomGenerator.content()()(8),
      edit_reason: "Initial moderation revision for audit.",
    },
  });
  typia.assert(commentEdit);

  // 9. Moderator soft-deletes the comment edit record
  const deletedEdit = await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.erase(connection, {
    postId: post.id,
    commentId: comment.id,
    commentEditId: commentEdit.id,
  });
  typia.assert(deletedEdit);
  // Cannot assert deleted_at since not present in DTO; audit trail/retrieval not implementable.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCommentEdit";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test the deletion of a comment edit by a moderator with an invalid or non-existent commentEditId.
 *
 * This test ensures the API robustly handles an attempt to delete a comment edit when the given commentEditId does not exist. It verifies not-found (or business logic) error responses instead of deleting anything improperly. Steps:
 *
 * 1. Register as a new moderator (ensuring permission context)
 * 2. Login as the moderator
 * 3. Attempt to delete a comment edit using random invalid UUIDs for postId, commentId, and commentEditId
 * 4. Confirm the API returns an error (not found/business denial), not a successful deletion
 */
export async function test_api_comment_edit_moderator_delete_invalid_id(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "TestPassword123!";
  const displayName: string = "Mod_" + RandomGenerator.alphaNumeric(8);
  const consentStatus: string = "v1_agree";
  const registerResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registerResponse);

  // 2. Log in as moderator
  const loginResponse = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResponse);

  // 3. Attempt to delete a non-existent comment edit as moderator
  await TestValidator.error("Deleting invalid commentEditId must result in error")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.comments.commentEdits.erase(
        connection,
        {
          postId: typia.random<string & tags.Format<"uuid">>(),
          commentId: typia.random<string & tags.Format<"uuid">>(),
          commentEditId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
}
